\section{Fully faithfulness}


\begin{defn}
Define a natural functor
\eq{Phi1}{\Phi_1:\Pro\Mod(A)\xra{} \TopMod(A),\quad``\lim " M_i\ra \lim M_i.}
Here the $\lim M_i$ refers to the limit in the category $\TopMod(A)$, i.e., the inverse limit of $M_i$ as modules equipped with the inverse limit topology of discrete spaces.
\end{defn}




\begin{prop}\label{Phi1FF}
The following restriction of $\Phi_1$
\eq{{Phi1ML}}{\Pro^{\ML}_{\rm t.o.}\Mod(A)\subset \Pro\Mod(A)\xra{\Phi_1} \TopMod(A),\quad``\lim " M_i\ra \lim M_i}
is fully faithful.
% Here $\Pro^{\ML}\Mod(A)$ refers to the full subcategory of $\Pro\Mod(A)$ generated by objects satisfying the Mittag-Leffler condition, namely, for any fixed $i\in I$, the family $\phi_{ji}(M_j)\subset M_i$ ($\phi_{ji}:M_j\ra M_i$ refers to the transition maps) for $j\ge i$ stabilizes.
\end{prop}
\begin{proof}
Take $``\lim_I" M_i\in \Pro^{\ML}\Mod(A), ``\lim_J" N_j\in \Pro\Mod(A)$. Then
\begin{align*} 
\Hom_{\Pro\Mod(A)}(``\lim_I" M_i,``\lim_J"N_j)
&\stackrel{(1)}{=}\lim_J \colim_I \Hom_{\Mod(A)}(M_i,N_j)
\\
% &\stackrel{(2')}{\hra}\lim_J\colim_{\stackrel{I'\subset I}{{\rm finite}}} \Hom_{\Mod(A)}(\lim_{I'}M_i, N_j)\\
&\stackrel{(2)}{=}\lim_J \Hom_{\TopMod(A)}(\lim_I M_i,N_j)\\
&\stackrel{(3)}{=}\Hom_{\TopMod(A)}(\lim_I M_i,\lim_J N_j).
\end{align*}
Here 
\begin{enumerate}
\item 
follows from the definition of the pro-category.     
\item 
follows from the definition of the inverse limit topology on $\lim_IM_i$ as the restriction of the product topology $\prod_I M_i$ and the Mittag-Leffler condition.
In fact, since $\{0\}$ is open in the discrete space $N_j$, any continuous map  $f:\lim_IM_i\ra N_j$ must have an open kernel. In particular, there exists a finite subset $I'$ of $I$, an open subset $U\subset \prod_{i\in I'}M_i$, such that
$$\lim_{i\in I}M_i \cap \left( U\times \prod_{i\in I\setminus I'} M_i\right) \subset \Ker f.$$
Let $p_{I'}:\lim_{i\in I} M_i\ra \prod_{i\in I'} M_i$ be the projection map.
Then $f$ factors through some 
$$\bar f: \Im(p_{I'})\ra N_j.$$
As the pro-system $``\lim_I" M_i$ satisfies Mittag-Leffler and $I'$ is finite, we can find a common $k\in I$ such that for all $l>k$, all $i\in I'$,
$$\phi_{ki}(M_k)=\phi_{li}(M_{l})$$
as submodules of $M_i$.
As $I$ is totally orderd, this means for any $m\in \prod_{i\in I'} \phi_{ki}(M_k)\subset \prod_{i\in I'} M_i$,
one can always find a lift $\tilde m\in \lim_I M_i$ such that 
$$p_{I'}(\tilde m)=m.$$
In particular, $\prod_{i\in I'}\phi_{ki}(M_k)\subset \Im(p_{I'})$.
(Actually we have $\prod_{i\in I'}\phi_{ki}(M_k)= \Im(p_{I'})$, as $\Im(p_{I'})\subset \prod_{i\in I'}\phi_{ki}(\Im (p_k))\subset \prod_{i\in I'}\phi_{ki}(M_k)$ shows the opposite direction.
But we shall not need this.)
Let's put everything in a diagram:
$$\xymatrix@C=10ex{
\lim_I M_i\ar[rrd]^f\ar@{->>}[dr]_{p_{I'}}\ar@{->>}[d]_{p_k}
\\
\Im(p_{k})  
\ar[r]_{\prod_{i\in I'}\phi_{ki}}\ar@{^(->}[d]& 
\Im(p_{I'})  \ar@{^(->}[d]
\ar[r]_{\bar f}& N_j.
\\
M_k \ar@{-->}[ur]
\ar[r]_{\prod_{i\in I'}\phi_{ki}}&
\prod_{I'} M_i&
}$$
We see that $f$ factors through $M_k$ via the composite of the dotted map $\prod_{i\in I'} \phi_{ki}$ and the map $\bar f$.
This proves (2).
\item
follows from the universal property of $\lim_J$.
\end{enumerate}
\end{proof}
\begin{rmk}
One might want such a functor to land in $\LCA$, but even after restricting to $\N$-indexed pro-systems, $\Phi_1$ does not satisfy this property. 
The key point is that the limit of locally compact spaces in $\Top$ are not necessarily locally compact.
For example, if we equip $\prod_\N \Z$ with the Tychonoff product topology, then this is a limit of locally compact abelian groups (i.e., $\prod^n_{i=1} \Z$), but itself is not locally compact, as a countable direct product $\prod G_n$ of locally compact $G_n$'s is locally compact if and only if  all $G_n$ are compact except for finitely many $n$.
\end{rmk}



\begin{prop}\label{Phi1landsincgwh}
The functor $$\Phi_1:\Pro_\N\Mod(A)\subset \Pro\Mod(A)\xra{\eqref{Phi1}} \TopMod(A)$$ lands in  $\Top\Mod(A)^{\cgwh}$.
\end{prop}
\begin{proof}
% The class of prodiscrete abelian groups with countable index categories are precisely those topological abelian groups with complete ultrametric underlying topological spaces, see \cite{15465}. So they are metrizable, and hence compactly generated and weakly Hausdorff.
Any prodiscrete abelian groups with the index category $\N$ is metrizable (and hence compactly generated and weakly Hausdorff).
In fact, as any subspace of a metrizable space is metrizable, it suffices to show that any $\N$-indexed product of discrete spaces is metrizable.
It is clear that such a space must be Hausdorff.
It is also second-countable, as it is a countable product of second-countable spaces.
As discrete spaces satisfy the separation axioms $T_0$ and $T_3$, any product space of discrete spaces satisfies satisfy $T_0$ and $T_3$ as well (\cite[Part I, Section 2, p. 15 para. 2]{SS_Counterex}).
Hence the space is metrizable by Urysohn's metrization theorem.
\end{proof}

\begin{rmk}
The proposition is false without restricting to $\N$-indexed pro-systems. 
The key point is that prodiscrete spaces are not necessarily compactly generated. 
For example, $\prod_{\aleph_1} \Z$ (where $\aleph_1$ is the first uncountable cardinal) is not compactly generated.
\end{rmk}


\begin{lem}\label{liminProNC}
\begin{enumerate}
\item 
For any category $\cC$, $\Pro_\N\cC$ admits $\N$-indexed limits.
\item 
If $\cC$ admits all finite limits (resp. colimits), then so does $\Pro_\N\cC$.
\item 
If $\cC$ is an abelian category, then so is $\Pro_\N\cC$.
\end{enumerate}

\end{lem}
\begin{proof}
\begin{enumerate}
\item 
% This is a variant of \cite[Proposition A.4.4]{AM}. 
Let $``\lim_{i\in \N}"X^i\in \Pro_\N\Pro_\N\cC$, where for each $i\in \N$, $``\lim_{j\in \N}"X^i_j\in \Pro_\N\cC.$
We identify $\N\times \N$ with $\N$ via the Cantor folding order.
Then $$``\lim_{(i,j)\in \N\times \N}"X^i_j$$ is the limit of $``\lim_{i\in \N}"X^i$ in $\Pro\cC$ by \cite[A. Proposition 4.4]{AM}.
In particular, it is the limit of $``\lim_{i\in \N}"X^i$ in the full subcategory $\Pro_\N\cC$.
\item 
Suppose $I$ is finite, and we are given a pro-system $``\lim_{i\in I}"X^i$ in $\Pro\Pro_\N\cC$, with each $X_i=``\lim_{j\in \N}"X^i_j\in\Pro_\N\cC$.
Since $I$ is finite, we can straighten the indices $j$ such that any structure morphism $``\lim_{i\in I}"X^i\ra ``\lim_{i'\in I}"X^{i'}$ in the pro-system $``\lim_{i\in I}"X^i$ is given by levelwise maps in $j$ (see \cite[A. Corollary 3.2]{AM}), i.e., an element in 
$$\lim_{j\in \N} \Hom_{\cC}(X^i_j, X^{i'}_j).$$
Then $$``\lim_{j\in \N}"\lim_i X^i_j\in \Pro_\N\cC$$ is the desired limit in $\Pro\cC$, and hence also the limit in $\Pro_\N\cC$.
The construction for finite colimits is similar.
This is a similar argument as the one in \cite[A. Proposition 4.2]{AM}
\item 
Since finite limits and finite colimits are constructed levelwise, we can check the axioms of an abelian category from the constructions given in (2).
\end{enumerate}
\end{proof}

\begin{prop}\label{Phi1commlim}
$\Phi_1:\Pro_\N\Mod(A)\ra \TopMod(A)^{\cgwh}$ commutes with $\N$-indexed limits and finite limits.
\end{prop}
\begin{proof}
This is clear from the construction in \Cref{liminProNC}.
\end{proof}




























\begin{prop}[{\cite[Theorem 2.16(ii)]{CS}}]\label{Phi2FF}
The functor
\eq{Phi2FFeq1}{\Phi_2: \TopMod(A)^{\cgwh}\xra{} \Cond(A),\quad M\mapsto \ul M:=\Hom_{\Top}(-,M)}
is fully faithful.
Moreover, its essential image lies in $\Cond(A)^{\qs}$, the full subcategory of condensed $A$-modules whose underlying condensed set is quasiseparated.
\end{prop}
\begin{lem}\label{IndProExact0Lem}
The restricted functor
$\TopMod(A)^\delta\subset\TopMod(A)^{\cgwh}\xra{\Phi_2} \Cond(A)$
to the full subcategory of discrete $A$-modules is exact.
\end{lem}
\begin{proof}
This is clear, as the restricted $\Phi_2$ factors through $\LCA$, and both $\TopMod(A)^\delta\ra \LCA$ and $\LCA\ra \Cond(A)$ are strict exact functors between quasiabelian categories. See \cite[the last paragraph on p. 26]{CS}
\end{proof}


\begin{prop}\label{IndProExact}
The category $\TopAb$ is quasiabelian by \cite[Proposition 1.6]{Prosmans}.
\begin{enumerate}
\item 
Let $\bar{\Ind_\N \TopAb^{\chaus}}$ be the essential image of 
\eq{IndProExacteq0}{
\Ind_\N\TopAb^{\chaus}\ra \TopAb,
\quad 
``\colim_j"M_j \mapsto \colim_j M_j.
}
This is a full subcategory of $\TopAb.$
\item 
The exact functor from \Cref{IndProExact0Lem} extends to an exact functor
$$\ul{(-)}:\bar{\Ind_\N \TopAb^{\chaus}}\xra{} \Cond(\Ab),$$
That is, it sends strictly exact sequences in $\bar{\Ind_\N \TopAb^{\chaus}}$ to exact sequences in $\Cond(\Ab)$.
\end{enumerate}
\end{prop}
\begin{proof}
\begin{enumerate}
\item 
Let $f:M=\colim_j M_j\ra \colim_j N_j$ be a map of topological groups, where $M_j$, $N_j$ are topological groups with compact Hausdorff underlying topological spaces.
Let $$N'_j:=\Im (N_j\ra N).$$
Then $\{N'_j\}_{j\in \N}$ is an increasing sequence of subspaces of $N.$
As the image of $M_j$ in $N$ is compact and the colimit is sequential, it must land in a single $N'_{l(j)}$.
Hence we have a function $l:\N\ra \N$, mapping $j$ to $l(j)$.
As $N=\colim_j N_{l(j)}$, the map $f$ is given by taking the colimit of the levelwise maps $M_{j} \ra N_{l(j)}$.
\item 
Let 
\eq{IndProExacteq1}{M\xra{f} N\xra{g} P}
be a strict exact sequence in $\bar{\Ind_\N \TopAb^{\chaus}}$, where
$$M=\colim_j M_i,\quad 
N=\colim_j N_j,\quad 
P=\colim_j  P_j,$$
with all $M_j,N_j,P_j\in \TopAb^{\chaus}$.
That is, $f$ and $g$ are group homomorphisms and are strict (i.e., the coimage and image are canonically isomorphic), and 
$\Ker f= \Im g$.
By  (1), we can assume that the sequence \eqref{IndProExacteq1} is the $\colim_j$ of
$$ M_{j}\xra{f_{j}} N_{j}\xra{g_{j}} P_{j}$$
(with no exactness on this level).
% As $0\in P$ is closed, $\Ker g$ is a closed subgroup of $N$.
% That is, for any $j\in \N$, $\Ker g\cap N'_j$ is closed in 
% $$N'_j:=\Im (N_j\ra N).$$
% Note that $\{N'_j\}_{j\in \N}$ is an increasing sequence of subspaces of $N.$




We want to show that $\Ker \ul g=\Im \ul f$, where $\ul f$ and $\ul g$ come from the induced sequence
$$\ul M\xra{\ul f} \ul N\xra{\ul g} \ul P.$$
The direction $\Im \ul f\subset \Ker \ul g$ is clear.
We show $\Ker \ul g\subset \Im \ul f$.
Fix an uncountable strong limit cardinal $\kappa$ and $S\in \Proj_\kappa$.
We have to show $(\Ker \ul g)(S)\subset (\Im\ul f)(S)$.
Let $\phi \in \ul N(S)=\Hom_{\Top}(S,N)$ such that the composite 
$$g\circ \phi=0:S\ra P.$$
Let 
$$M'_j:=\Im(M_j\ra M),\quad N'_j:=\Im (N_j\ra N).$$
As $S\in \Proj_\kappa$ is compact, $\phi(S)\subset N$ is a compact subspace.
Since $\{N'_j\}_{j\in \N}$ is an increasing sequence of open subspaces of $N$,  there exists a $j_0>>0$ such that $\phi(S)\subset N_{j_0}'$.
The question now reduces to whether the dotted arrow exists in the following commutative diagram
$$\xymatrix{
&S\ar[d]^{\phi}\ar[dr]^0\ar@{-->}[dl]_{}&
\\
M'_{j_0}\ar[r]_{f_{j_0}}
&N'_{j_0}\ar[r]_{g_{j_0}}& P_{j_0}.
}$$
As compact subspace of a Hausdorff space is closed, $\phi(S)$ is closed in $N'_{j_0}$.
Hence $f^{-1}(\phi(S))$ is closed in $M'_{j_0}$.
As a closed subset of a compact space is compact, $f^{-1}(\phi(S))$ is compact.
Both $\phi(S)$ and $f^{-1}(\phi(S))$ are Hausdorff, as they are subspaces of Hausdorff ambient spaces $N'_{j_0}$ and $M'_{j_0}$.
Moreover, since $\phi(S)\subset \Ker g=\Im f$,
$$f:f^{-1}(\phi(S))\ra \phi(S)$$
is surjective as a map of compact Hausdorff spaces.
As $S$ is a projective object in the category of compact Hausdorff spaces \cite[Theorem 2.5]{Gleason}, the dotted lift exists.
This finishes the proof of the proposition.
\end{enumerate}
\end{proof}










\begin{lem}\label{noneedshifify}
Fix an uncountable strong limit cardinal $\kappa.$
Then for any $N\in \Top,$
$\Hom_{\Top}(-,N): \Prof_{\kappa}\ra \Set$ 
is a sheaf.
\end{lem}
\begin{proof}
This is clear from \cite[p. 12, remarks after the proof of Proposition 2.7]{CS} and \cite[Example 1.5]{CS}.
\end{proof}
\begin{prop}\label{Phi2commlim}
The functor $\Phi_2$ in \eqref{Phi2FFeq1} commutes with arbitrary limits, i.e., for any $M_i\in \TopMod(A)^{\cgwh}$, $i\in I$ a pro-system in $\TopMod(A)^{\cgwh}$,
$$\ul{k\lim_I M_i}\simeq \lim_I \ul{M_i}.$$
In particular, if the index category is $\N$ and all $M_i$ are discrete, then
\eq{limNcommwithul}{\ul{\lim_\N M_i}\simeq \lim_\N \ul{M_i}.}
\end{prop}
\begin{proof}
Let $M_i\in \TopMod(A)^{\cgwh}$, $i\in I$ be a pro-system in $\TopMod(A)^{\cgwh}$. 
We claim that the limit in $\TopMod(A)^{\cgwh}$ is $k\lim_I M_i$, where $k$ is the k-ification functor (see e.g. \cite[Definition 1.4.11, Fact 1.4.12(ii)]{BC_CondFreiburg}).
Indeed, if we forget about the module structure, $k\lim_I M_i$ is the limit of the pro-system in $\Top^{\cgwh}.$
As $k$ is a functor, the images of the structure maps of the topological module $\lim_I M_i$ remain continuous,  therefore $k\lim_I M_i\in \TopMod(A)^{\cgwh}$, as desired.
Hence both the domain and the codomain of $\Phi_2$ are complete (and cocomplete), so the statement makes sense.

We fix an uncountable strong limit cardinal $\kappa$.
Let $S\in \Proj_\kappa$ be an extremally  disconnected profinite set.
Then $S$, $k\lim_I M_i$ and $M_i$ all lie in $\Top^{\cgwh}$, and therefore
\begin{align*} 
\Hom_{\Top}(S,{k\lim_I} M_i)
=\Hom_{\Top^{\cgwh}}(S,{k\lim_I} M_i)
=\lim_I \Hom_{\Top^{\cgwh}}(S,M_i)
&=\lim_I \Hom_{\Top}(S,M_i).
\end{align*}
By \Cref{noneedshifify}, we know that  $\Hom_{\Top}(-,N)$ is a sheaf on $\Prof_\kappa$ for any topological space $N$. 
This means $\ul{k\lim_I M_i}=\lim_I \ul{M_i}$ in $\Cond(A)_\kappa\subset \Cond(A)$, as desired.

When $I=\N$ and all $M_i$'s are discrete, $\lim_\N M_i$ is metrizable, and hence $\lim_\N M_i=k\lim_\N M_i\in \TopMod(A)^{\cgwh}$. This proves \eqref{limNcommwithul}.
\end{proof}

\begin{thm}\label{thm1}
The composite functor
$$\Pro_{\N}\Mod(A)\xra{\Phi_1} \TopMod(A)^{\cgwh}\xra{\Phi_2}\Cond(A), \quad ``\lim_\N" M_i\mapsto \ul{\lim_\N M_i}$$
factors through $\Solid(A)$.
We denote this functor by
$$\Phi:\Pro_{\N}\Mod(A)\ra \Solid(A)$$
and it is left exact.
Moreover, $\Phi$ induces a fully faithful and exact functor
$$\Phi^{\ML}:\Pro_{\N}^{\ML}\Mod(A)\ra \Solid(A).$$
\end{thm}
\begin{proof}
$\Phi$ is left exact by \Cref{Phi1commlim}, \Cref{Phi2commlim} and the fact that limits in $\Solid(A)$  are also limits in $\Cond(A)$ (\cite[Proposition 7.5(i)]{CS}).
The fully faithfulness of $\Phi^{\ML}$ follows from \Cref{Phi1FF} and \Cref{Phi2FF}.
It is also right exact, because the Mittag-Leffler condition guarantees that the limit of condensed presheaves preserves surjections, and a further sheafification step will not destroy this.
It remains to show $\Phi$ factors through $\Solid(A)$.
Since discrete modules are solid, $\ul{M_i}\in \Solid(A)$ for all $i$.
Then $\ul{\lim_\N M_i}\stackrel{\eqref{limNcommwithul}}{=}\lim_\N \ul{M_i}\in \Solid(A)$, as $\Solid(A)\subset \Cond(A)$ is closed under all limits.
\end{proof}
\begin{rmk}
In \cite{MPV_TateCondv2}, the authors showed a result similar to our result on
$\Phi^{\ML}:\Pro^{\ML}_\N \Mod(A)\ra \Solid(A)$.
In short, they have shown that the category of $\aleph_0$-Tate objects of finitely generated projective $A$-modules fully faithfully embeds into $\Solid(A)$, and this embedding functor is also exact. 
The definition of Tate objects they use assumes that all the transition maps are surjective.
As the main application we have in mind is Deligne's $j_!$ for coherent sheaves, which always produces pro-objects with non-surjective (and also non-Mittag-Leffler) transition maps, we have to include a study on non-Mittag-Leffler pro-objects.
\end{rmk}

\begin{defn}\label{RPhiDef}
Define
$$R\Phi: \Pro_{\N}\Mod(A)\ra D(\Solid(A)),\quad ``\lim_\N" M_i\mapsto R\lim_\N \ul{M_i}.$$
\end{defn}



















\section{Compatibility with $j_!$}


Before we proceed to the main theorem, we need a flatness statement.
\begin{prop}\label{flatmodvsflatcondmod}
Let $A$ be a noetherian ring. $f\in A$ is a nonzerodivisor.
Let $\hat A:=\lim_n A/f^n$, and we equip it with the inverse limit topology, where all $A/f^n$ are discrete. 
Then $\ul A\ra \ul{\hat A}$ is flat, i.e., $-\otimes_{\ul A} \ul {\hat A}:\Cond(A)\ra \Cond(A)$ is exact.
\end{prop}
\begin{proof}
Fix an  uncountable strong limit cardinal $\kappa$ and let $S=\lim_{i\in I} S_i\in \Proj_\kappa$, where all $S_i$ are finite.
Since every profinite space is the inverse limit of its discrete quotient spaces (\cite[Proposition 1.1.7]{Wilson}), by possibly replacing the pro-system $\{S_i\}_{i\in I}$ with the pro-system of the finite quotients of $S$, we can assume that all transition maps are surjective.
We want to show that $\ul A(S)\ra \ul{\hat A}(S)$ is a flat ring map.
Let $r_i$ be the cardinality of $S_i$. 
Then by the compactness of $S$, we have
$$\ul A(S)=\colim_i \Hom_{\Top}(S_i,A)=\colim_i A^{r_i}=:B$$
$$
\ul{\hat A}(S)=\lim_n\colim_i \Hom_{\Top}(S_i,A/f^n)=\lim_n((\colim_i A^{r_i})/f^n)=:\hat B $$
Since the colimits over $i$ are induced from the transition maps $S_j\ra S_i$ of the projective system $S=\lim_i S_i$, it maps a basis of $A^{r_i}$ to a subset of a basis of $A^{r_j}$, which can be extended to a full basis of $A^{r_j}$.
We will fix a choice of a system of compatible bases 
$$\{e_{i1},\dots, e_{i r_i}\}_{i\in I}$$
of $\{A^{r_i}\}_{i\in I}$ along the transition maps of $S$, as the following claim enables us.
\begin{claim}\label{clbasis}
There exists a system of bases of $\{A^{r_i}\}_i$ as $A$-modules, such that for any $j>i$,
the pullback along the transition map $S_j\ra S_i$ of the chosen basis of $A^{r_i}$ is a subset of the chosen basis of $A^{r_j}$.
\end{claim}
\begin{proof}[Proof of \Cref{clbasis}]
Let $\cS$ be the set of all possible compatible choices of bases for subcollections of $\{A^{r_i}\}_{i\in I}$, i.e.,
$$\cS:=\left\{\{E_i\}_{i\in I'}
\middle|
\begin{array}{c}
     I'\subset I,\\
     \text{$E_i:=\{e_{ij}\}_{1\le j\le r_i}$ is a basis of $A^{r_i}$ as a $A$-module,}  \\
     \text{for any $l<i$ in $I'$, the pullback of $E_l$ is a subset of $E_i$} 
\end{array}
\right\}$$
$\cS$ is partially ordered by the relation 
$$\{E_i\}_{i\in I'}\le \{E_i\}_{i\in I''}
\quad\Leftrightarrow\quad
I'\subset I''\text{ and }\{E_i\}_{i\in I'}\subset \{E_i\}_{i\in I''}
$$
$\cS$ is nonempty, as there is an initial object in the ind-system $\{A^{r_i}\}_i$, namely, $A$ itself.
We pick $1$ as its basis, and it lies in $\cS$.
Suppose we are given a chain $\cT$ of subsets of $\cS$.
It corresponds to a chain $\cI$ of subsets of $I$, i.e., $I'\in \cI$ if and only if there is some $\{E_i\}_{i\in I'}\in \cT$.
Then $$\bigcup_{I'\in \cI}\{E_i\}_{i\in I'}$$
is a upper bound for all elements in $\cT$ and it lies in $\cS$.
By Zorn's lemma, $\cS$ has an maximal element.
This finishes the proof of the claim.
\end{proof}



Consider the following diagram
$$\xymatrix{
A\ar[d]\ar[r]&B\ar[d]
\\
\hat A\ar[r]&\hat A\otimes_A B\ar[r]&\hat B.
}$$
As $A$ is noetherian, $A\ra \hat A$ is flat by \cite[Thm 8.8]{Matsumura}.
Hence the base change $B\ra \hat A\otimes_A B$ is flat.
To show that $B\ra \hat B$ is flat, it suffices to show $\hat A\otimes_A B\ra \hat B$ is flat.  
Let $c_l\in B\otimes_A \hat A$, $x_l\in \hat B$ ($l=1,\dots, m$) be elements satisfying the relation
$$\sum_{l=1}^m c_lx_l=0.$$
Then in particular, for any $n$, they satisfy this relation in $\hat B/f^n=B/f^n=\colim_i A^{r_i}/f^n$.
As $x_1,\dots,x_m$ are finitely many elements, there exists a single $i$ such that the residue classes of $x_1,\dots,x_m$ in $\hat B/f^n$ all lie in $A^{r_i}/f^n.$
In the free $A/f^n$-module $A^{r_i}/f^n$, we write
$$x_l=\sum_{j=1}^{r_i} a_{ljn} e_{ij}$$
with $a_{ljn}\in A/f^n$ being the uniquely determined elements. 
As $\{e_{ij}\}$ are chosen to be compatible bases with respect to different $i$'s, 
\begin{enumerate}
\item 
the elements $a_{ljn}$ are independent of the choice of $i$ and hence justifies our notations;
\item 
$a_{ljn}$ are compatible with respect to $n$, i.e., the natural map $A/f^{n+1}\ra A/f^{n}$ sends $a_{i,j,n+1}$ to $a_{ijn}$.
\end{enumerate}
As the images of  $e_{i1},\dots e_{ir_i}$ form a basis of $A^{r_i}/f^n$ as a $A/f^n$-module, the condition $\sum_{l=1}^m c_lx_l=0$ in $A^{r_i}/f^n$ necessarily forces
$$\sum_{l=1}^m c_la_{ljn}=0$$
in $A/f^n$ for all $j$.
Set
$$a_{lj}=\text{image of $(a_{ljn})_n$ under the map $\lim_n A/f^n=\hat A \ra \hat A\otimes_A B$.}$$
This is well-defined by (2).
Then
$$x_l=\sum_{j=1}^{r_i} a_{lj} e_{ij},\quad \sum_{l=1}^m c_la_{lj}=0$$
by construction.
By the equational criterion of flatness (\cite[\href{https://stacks.math.columbia.edu/tag/00HK}{Tag 00HK}]{stacks-project}), 
the map $\hat A\otimes_A B\ra \hat B$ is flat.
\end{proof}

To simplify notations, from now on we omit the ``derived'' part from the notations, except for the tensor product (e.g. $\otimes_{\ul A}$, $\otimes_{A_\bbox}$, $\otimes_{(A[T],A)_\bbox}$, etc.) and $R\lim$. All the other functors in this section  shall be read as derived, such as $\Phi$ refers to $R\Phi$, $f^*$ refers to $Lf^*$, etc.. 
\begin{thm}\label{thm2}
Let $A$ be a finite type $\Z$-algebra, and $f\in A$ be a nonzerodivisor. Let $j:\Spec A[\frac{1}{f}]\hra \Spec A$ be the open immersion.
Then the natural functor 
$$\Phi:\Pro_\N\Mod(A)\subset D(\Pro_\N\Mod(A)) \ra D(\Solid(A))$$
given in \Cref{RPhiDef} is compatible with the $j_!$ defined by Deligne \cite[Appendix]{Hartshorne_RD} and the one defined by Clausen-Scholze \cite[Lecture VIII]{CS}.
That is, 
the diagram
\eq{thmeq1}{\xymatrix{
\Mod^{\fp}(A[\frac{1}{f}])\ar[r]^{\Phi}\ar[d]^{j^{\De}_!}&
D(\Solid(A[\frac{1}{f}]))\ar[d]^{j^{\CS}_!}\\
\Pro_\N\Mod^{\fp}(A)\ar[r]^{\Phi}&D(\Solid(A))
}}
is commutative.
\end{thm}
\begin{proof}
Take $M\in \Mod^{\fp}(A[\frac{1}{f}])$.
Then as $A$ is noetherian, there exists a $A$-submodule $M'\in \Mod^{\fp}(A)$ of $M$, such that 
$$j^*M' =M'\otimes_A A[\frac{1}{f}]= M$$
in $\Mod(A[\frac{1}{f}]).$
(In fact: since $M$ is the colimit of the finitely generated $A$-submodules, there exists one single $A$-submodule such that it contains all the finitely many generators of $M$ as an $A[\frac{1}{f}]$-module.
As $A$ is noetherian, any finitely generated $A$-module is automatically finitely presented.)
For each $n$,
$$0\ra f^n\ul M'\ra \ul M'\ra \ul{M'/f^nM'}\ra 0$$
is an exact sequence. Therefore
$$R\lim_n f^n\ul M'\ra \ul M'\ra R\lim_n \ul{M'/f^nM'}=\lim_n \ul{M'/f^nM'}\xra{+1} $$
is a distinguished triangle.
Hence we have
\eq{thmeqDe2}{\Phi(j_!^{\De}M)= \Phi(``\lim_n"f^nM')=R\lim_n \ul{f^n M'}
=
{\rm Cone}(\ul M'\ra \lim_n \ul{M'/f^nM'})[-1].}




The image of the schematic morphism $j$  in the category of adic spaces (via Huber's fully faithful functor $t$, see \cite[Proposition 4.2(i)]{Huber_gen}), factors canonically as a composition of two morphisms of adic spaces, namely
$$t(\Spec A[\frac{1}{f}])=\Spa(A[\frac{1}{f}],A[\frac{1}{f}])
\xra{j_1}
\Spa(A[\frac{1}{f}],A)
\xra{j_2}
\Spa(A,A)=t(\Spec A).$$
Hence
$j_!^{\CS}$ factors as
$$D(A[\frac{1}{f}]_\bbox)
\xra{j_{1!}}
D((A[\frac{1}{f}],A)_\bbox)
\xra{j_{2!}}
D(A_\bbox),
$$
where $j_{2!}=j_{2*}$ is the forgetful functor.
$j_{1!}$ and $j_{2!}$ fit into the following commutative diagram
$$\xymatrix{
D(A[T]_\bbox)\ar[r]^{j'_{1!}}\ar@/^5ex/[rr]^{j'_!}
&
D((A[T],A)_\bbox)
\ar[r]^(0.6){j'_{2!}}
&
D(A_\bbox)
\\
D(A[\frac{1}{f}]_\bbox)
\ar[u]^{h'_!}
\ar[r]^{j_{1!}}\ar@/_4ex/[rr]_{j^{\CS}_!}&
D((A[\frac{1}{f}],A)_\bbox)
\ar[u]_{h_!}\ar[r]^(0.6){j_{2!}}
&
D(A_\bbox).\ar@{=}[u]
}$$
Here
$j_1'$ is the canonical map $\Spa(A[T],A[T])\ra \Spa(A[T],A)$, and $j'_{1!}$ is given by $$(-)\otimes^L_{(A[T],A)_\bbox} (A((T^{-1}))/A[T])[-1],$$
as introduced in the proof of \cite[Theorem 8.13(ii)]{CS}, and $A((T^{-1}))$ is regarded as a topological $A[T]$-module with the colimit topology of the $T^{-1}$-adic topology of $A[[T^{-1}]]$.
The vertical maps, $h_!,h'_!$ are induced from $A[T]\ra A[\frac{1}{f}]$, mapping $T$ to $1/f$.
As this ring map is surjective, $A[\frac{1}{f}]_\bbox=(A[\frac{1}{f}],A[T])_\bbox.$
In particular, $h_!=h_*$ and $h'_!=h'_*$, and hence they both are forgetful functors.
We have
$$j^{\CS}_{!}=j_{2!}j_{1!}= j'_{2!}j'_{1!}h'_!.$$

Let  $M\in \Mod^{\fp}(A[\frac{1}{f}])$, $M'\in \Mod(A)$ be as before. 
Since $\ul{A[T]}$ is projective in $\Solid((A[T],A)_\bbox)$,
\[\ul{A[\frac{1}{f}]}\otimes^L_{(A[T],A)_\bbox} \ul{A[T]}
=\ul{A[\frac{1}{f}]}\otimes_{(A[T],A)_\bbox} \ul{A[T]}
=\ul{A[\frac{1}{f}]}.
\numberthis \label{thmeqCS1}\]
Since 
$$0\ra \ul{A[T]}\xra{fT-1} \ul{A[T]}\xra{T\mapsto 1/f} \ul{A[\frac{1}{f}]}\ra 0$$
is a projective resolution of $\ul{A[\frac{1}{f}]}$ in $\Solid((A[T],A)_\bbox)$,
we have
\begin{align*} 
\numberthis \label{thmeqCS2}
\ul{A[\frac{1}{f}]}\otimes^L_{(A[T],A)_\bbox} \ul{A((T^{-1}))}
&=\Cok\left(\ul{A((T^{-1}))}\xra{T^{-1}-f}\ul{A((T^{-1}))}\right)
% \quad\text{($fT-1:\ul{A((T^{-1}))}\xra{}\ul{A((T^{-1}))}$ is injective.)}
\\&
=\ul{A((T^{-1}))}/(fT-1)
\\&
=\left(\ul{A[[T^{-1}]]}/(f-T^{-1})\right)[\frac{1}{f}]
% \quad\text{(Colimits commute with quotients)}
\\&
=\left(\left(\lim_n \ul{A[T^{-1}]}/T^{-n}\right)/ (T^{-1}-f)\right)[\frac{1}{f}]
\\&
=\left(\lim_n\left((\ul{A[T^{-1}]}/T^{-n})/ (T^{-1}-f)\right)\right)[\frac{1}{f}]
\quad\text{(\cite[Theorem 8.1(ii)]{Matsumura})}
\\&
=\left(\lim_n \ul{A/f^n}\right)[\frac{1}{f}].
\end{align*}
Hence
\begin{align*}
\numberthis \label{thmeqCS3}
&\ul{A[\frac{1}{f}]}\otimes^L_{(A[T],A)_\bbox} (\ul{A((T^{-1}))}/\ul{A[T]})
\\
&={\rm Cone}\left(
\ul{A[\frac{1}{f}]}\otimes^L_{(A[T],A)_\bbox} \ul{A[T]}
\xra{}
\ul{A[\frac{1}{f}]}\otimes^L_{(A[T],A)_\bbox} \ul{A((T^{-1}))}
\right)
\\
&
={\rm Cone}\left( \ul{A[\frac{1}{f}]}\ra (\lim_n \ul{A/f^n})[\frac{1}{f}]\right)
\quad\text{(by \eqref{thmeqCS1} and \eqref{thmeqCS2})}.
\end{align*}
Moreover, since $M'\in \Mod^{\fp}(A)$, we have
\begin{align*} 
\numberthis \label{thmeqCS4}
\ul M'\otimes^L_{A_\bbox} \ul{(\lim_n A/f^n)[\frac{1}{f}]}
&=\ul M'\otimes^L_{A_\bbox} \ul{(\lim_n A/f^n)} \otimes^L_{A_\bbox}\ul{A[\frac{1}{f}]}
\\
&=\left(\ul M'\otimes^L_{\ul A} \ul{(\lim_n A/f^n)} \right)\otimes^L_{\ul A} A_\bbox
\otimes^L_{A_\bbox}\ul{A[\frac{1}{f}]}
\\
&=\left(\ul M'\otimes_{\ul A} \ul{(\lim_n A/f^n)} \right)\otimes^L_{\ul A} A_\bbox
\otimes^L_{A_\bbox}\ul{A[\frac{1}{f}]}
\quad \text{(\Cref{flatmodvsflatcondmod})}
\\&=
(\lim_n \ul{M'/f^nM'}) \otimes^L_{\ul A} A_\bbox
\otimes^L_{A_\bbox}\ul{A[\frac{1}{f}]}
\quad \text{(\cite[Theorem 8.7]{Matsumura})}
\\&=
(\lim_n \ul{M'/f^nM'})
\otimes^L_{A_\bbox}\ul{A[\frac{1}{f}]}
\\&=
(\lim_n \ul{M'/f^nM'})[\frac{1}{f}]
\end{align*}

Altogether,
\begin{align*} 
\numberthis \label{thmeqCS5}
j_!^{\CS}(\Phi(M))&= 
j_!^{\CS}(\ul M)=
j_!^{\CS}(j^*\ul M')
=\ul M'\otimes^L_{A_\bbox} j^{\CS}_!\ul{A[\frac{1}{f}]}
\quad \text{(\cite[Theorem 8.13(iii)]{CS})}
\\
&=\ul M'\otimes^L_{A_\bbox}\left(\ul{A[\frac{1}{f}]}\otimes^L_{(A[T],A)_\bbox} (\ul{A((T^{-1}))}/\ul{A[T]})\right)[-1]
\\
&=\ul M'\otimes^L_{A_\bbox}
{\rm Cone}\left( A[\frac{1}{f}]\ra (\lim_n A/f^n)[\frac{1}{f}]\right)[-1]
\quad\text{(\Cref{thmeqCS3})}
\\
&=
{\rm Cone}\left( \ul M'\otimes^L_{A_\bbox}\ul{A[\frac{1}{f}]}\ra \ul M'\otimes^L_{A_\bbox} (\lim_n \ul{A/f^n})[\frac{1}{f}]\right)[-1]
\\
&={\rm Cone}(\ul M\ra (\lim_n \ul{M'/f^nM'})[\frac{1}{f}])[-1]
\quad\text{(\Cref{thmeqCS4})}
\end{align*}

We compare the results \eqref{thmeqDe2} and \eqref{thmeqCS5}.
Consider the following diagram, in which both rows are exact:
\[
\xymatrix{
0\ar[r]&
\ul{\Ker'}\ar[r]\ar@{^(->}[d]&
\ul M'\ar@{^(->}[d]\ar[r] & 
\lim_n \ul{M'/f^nM'}
\ar[d]\ar[r]&
\ul{\Cok'}\ar[r]
\ar[d]
&0
\\
0\ar[r]&
\ul{\Ker}\ar[r]&
\ul M\ar[r]&
(\lim_n \ul{M'/f^nM'})[\frac{1}{f}]
\ar[r]&
\ul{\Cok}\ar[r]
&0.
}
\]
We want to show that the first and last vertical maps are isomorphisms.
Note that the 4 objects in the middle part of this diagram are all the underline of topological modules:
$\lim_n \ul{M'/f^nM'}$ is the underline of the prodiscrete topological module $\lim_n {M'/f^nM'}$, and 
$(\lim_n \ul{M'/f^nM'})[\frac{1}{f}]$ is the underline of the colimit of prodiscrete topological modules $\frac{1}{f^n}(\lim_n {M'/f^nM'})$.
By \Cref{IndProExact}, $\ul{\Ker'}$ (resp. $\ul{\Ker}$)  is the underline of the module-theoretic kernel
\begin{center}
$\Ker':=\Ker(M'\ra \lim_n M'/f^nM')$ \quad
(resp. $\Ker:=\Ker(M\ra (\lim_n M'/f^nM')[\frac{1}{f}])$), 
\end{center}
and
$\ul{\Cok'}$ (resp. $\ul{\Cok}$)  is the underline of the module-theoretic cokernel
\begin{center}
$\Cok':=\Cok(M'\ra \lim_n M'/f^nM')$ \quad
(resp. $\Cok:=\Cok(M\ra (\lim_n M'/f^nM')[\frac{1}{f}])$)
\end{center}
(and this in particular justifies our notations).
Now it remains to show 
$$\Ker'=\Ker,\quad\Cok=\Cok'$$
in $\TopAb$.

First we show the isomorphism between the kernels. 
Let $m\in  M$ satisfying the condition that $f^N m=0$ in $\lim_n {M'/f^nM'}$.
As multiplying by $f$ is an injective map on $ M$, it is in particular an injective map when restricted to $ M'$.
Hence $m\in \cap_{n\ge 0} f^n M'= \Ker'$.
This proves the surjectivity of $\Ker'\ra \Ker$, i.e., 
$$\Ker'= \Ker={\bigcap_{n\ge 0} f^n M'}.$$

It remains to show that $\Cok'\ra \Cok$ is an isomorphism.
Consider the following diagram in $\TopAb$:
$$
\xymatrix{
0\ar[r]&
M'/\Ker'\ar@{^(->}[d]\ar[r] & 
\lim_n {M'/f^nM'}
\ar[d]\ar[r]&
{\Cok'}\ar[r]
\ar[d]
&0
\\
0\ar[r]&
 M/\Ker\ar[r]&
(\lim_n {M'/f^nM'})[\frac{1}{f}]
\ar[r]&
{\Cok}\ar[r]
&0.
}
$$
Both of the rows are clearly strictly exact.
The arrow in the middle is injective, as it is the same as applying $-\otimes_A \lim_n A/f^n$ to the injection $M'\hra M$, and $A\ra \lim_n A/f^n$ is flat.
Hence in order to show $\Cok'=\Cok$,
it is equivalent to showing that
\eq{thmeq2}{ M/  M'\ra \left((\lim_n {M'/f^nM'})[\frac{1}{f}]\right)/\left(\lim_n {M'/f^nM'})\right)}
is an isomorphism.
As any element in $(\lim_n {M'/f^nM'})[\frac{1}{f}]$ can be written as a Laurent series in $f$, one can find from the same residue class  a representative with only (finitely many) negative $f$ powers. Such a representative lies in the image of \eqref{thmeq2}, and this proves the surjectivity.
On the other hand, since $M\cap \lim_n M'/f^nM'=M'$ inside $(\lim_n {M'/f^nM'})[\frac{1}{f}]$ in $\Mod(A[\frac{1}{f}])$, injectivity of \eqref{thmeq2} follows.
This means that \eqref{thmeqDe2} and \eqref{thmeqCS5} agree, and we are done with the proof of the theorem.
\end{proof}








































