\begin{defn} Let $R$ and $\wr$ be finitely generated algebras 
over  fields $k$ and $K$ of characteristic $p>0$ and of 0, respectively.


Assume $\wr (\mod p)=R$ holds by compatible skeletons $\Phi_p: \ws\to S$, where $S\subset R$ and 
        $\ws\subset \wr$.

        For  ideals $\a_R\subset R$ and $\taa_\wr\subset \wr$  we write $\taa_\wr(\mod p)=\a_R$ and say
       {\sl  `` $\taa_\wr $ is a lifting of $\a_R$" } if we can take a generator system of $\taa_\wr$ from $\ws$ whose image by $\Phi_p$
        generates
         $\a_R\subset R$. It is equivalent to the following:


          \begin{enumerate}
\item There are ideals $\a\subset S$ and $\taa\subset \ws$
       such that $\taa_\wr=\taa\wr$, $\a_R=\a R$, and  
\item         $\Phi_p(\taa)=\a$.
\end{enumerate}
%
 In this case, we call $\a$  a {\sl skeleton of }$\a_R$, and $\taa$  a {\sl skeleton of} $\taa_\wr$.

\end{defn}

\begin{rem} According to the definition above, the unit ideal $\wr$ itself is a lifting of any ideal $\a_R\subset R$ generated by
 elements of the skeleton $S\subset R$.
 Because the pull-back $\taa:=\Phi_p^{-1}(\a)$ satisfies the conditions above and contains $p\in \ZZ\subset \wr$,
 a unit element of $\wr$.


\end{rem}
\noindent
This gives a trivial example that
 a lifting of a prime ideal in $R$ is not necessarily prime. 
But the following proposition shows that for rings of special type a prime ideal has
 at least one lifting which is prime in the ``skeleton level'' and
gives a proper ideal in $\wr$ by the extension.
Here, we note that even when the extension is a proper ideal of $\wr$,
it is not necessarily prime.
Throughout this paper, we work on such algebras $R$ and $\wr$ as follows:



\begin{prop-def}\label{prime-lift}
  Let $k$ and $K$ be fields of characteristic $p>0$ and $0$, respectively.
  Let  $R$ and $\wr$ be $k$-subalgebra of $k[x_1,\ldots,x_m]$ and $K$-subalgebra of
$K[x_1,\ldots,x_m]$, respectively.
Denote the maximal ideal $(x_1,\ldots, x_m)\subset k[x_1,\ldots, x_m]$ by $\m$ and 
the maximal ideal $(x_1,\ldots, x_m)\subset K[x_1,\ldots, x_m]$ by $\wm$.
Let $\p_R\subset R$ be a prime ideal contained in $\m$.
 Let $S\subset R$  be a skeleton such that $\p:=\p_R\cap S$ generates $\p_R$
 and $\ws\subset \wr$ a lifting skeleton of  $S$ such that the canonical map
 $$\ws\cap \wm \to S\cap \m$$
 is surjective.

 %
 Then, 
 the following hold:
\begin{enumerate}
\item  There is at least one prime ideal $\wp\subset \ws\cap\wm\subset\ws$ such that
% 
$$\Phi_p(\wp)= \p.$$
%
  In this case, we call $\wp$ a {\sl prime lifting of $\p$ in the skeleton level}.
  When $\p$ corresponds to a point $P$ in the scheme defined by $R$ (eg. as $\spec$ or $\proj$),
  then the point $\tP$ corresponding to $\wp$ in the scheme defined by $\ws$ is called 
  a {\sl lifting of the point $P$ in the skeleton level}.



\item  Let prime ideals  $\p'_{R}\subset \p_R\subset R$   be  generated by 
$\p':=\p'_{R}\cap S$ and by $\p:=\p_R\cap S$, respectively.
  Assume there is a prime lifting  $\wp'\subset\ws\cap\wm$  of $\p'$ in the skeleton level.
   Then $\p$ has a prime lifting $\wp\subset\ws$ in the skeleton level containing $\wp'$.


 \item In both cases (1) and (2) above, the prime lifting $\wp$ of $\p$ satisfies
 $$\height \wp_\QQ=\height \p,$$
  where $\wp_\QQ=\wp\otimes_\ZZ\QQ\subset \ws\otimes_\ZZ\QQ$.
\end{enumerate}   
\end{prop-def}



 \begin{rem}\label{homo}  The proposition above also holds for graded algebras $R, \wr, S, \ws$ and homogeneous prime ideals $\p, \p_i$,
$\wp,$ and $ \wp_i$. 
where the degree is given by a weighted degree of $x_i$'s.
 \end{rem}

 In this paper, we work on algebras of the special type: {\it i.e.,} a finitely generated $k$-subalgebra $R$ of a polynomial ring.
On such an algebra $R$, properties on an ideal $\a$ of $R$ are reduced to the properties of its skeleton ideal $\a\cap S$ as follows:
