\begin{rem}[see for example {\cite{kssw}}]\label{graded}
 Let $A_n\to A_{n-1}\to\cdots A_1\to A$ be a sequence of blow-ups with the center at  subschemes 
 over an affine  smooth variety $A=\spec R_0$.
      Then, each $A_i$ is described as $  A_i=\proj R_i$, where $R_i$ is a graded ring over $R_0$ as follows:
  \begin{equation}\label{proj} 
      R_i=\oplus _{\ell\geq0} R_{0}[I_1 T_1,\ldots, I_{i}T_{i}]_{(\ell g_1,\ldots,\ell g_{i-1}, \ell g_i)}, \ \ \ \mbox{for} \ \
      g_1 \gg g_2\gg\cdots \gg g_{i}\gg ..\gg g_n,
\end{equation}
   where $T_1,\ldots, T_n$ are indeterminates, and 
   ${I}_1\subset R_0,\ldots, I_i\subset R_{i-1},\ldots, I _n\subset R_{n-1}$ are the homogeneous  ideals 
   defining the center of each blow-up.
   We define the multi-degree of an element  $rT_1^{e_1}\cdots T_i^{e_i}\in R_i$  ($r\in R_0$) as follows:
    $$\deg r T_1^{e_1}\cdots T_i^{e_i}=(e_1,\cdots, e_i).$$  

   By this degree, the ring $ R_{0}[I_1 T_1,\ldots, I_{i}T_{i}]$ becomes a multi-graded ring 
   and $ R_{0}[I_1 T_1,\ldots, I_{i}T_{i}]_{(\ell g_1,\ldots,\ell g_{i-1}, \ell g_i)}$ is its homogeneous part
   of degree $(\ell g_1,\ldots,\ell g_{i-1}, \ell g_i)$.
   Then, 
   $R_i$ is a ``diagonal'' sub-graded ring of $ R_{0}[I_1 T_1,\ldots, I_{i}T_{i}]$.
   From now on, we regard $R_i$ as a graded ring with respect to $\ell\in \ZZ_{\geq0}$
   and a homogeneous ideal of $R_i$ is in this grading.
\end{rem}

We will now present a fundamental lemma that will be used in the upcoming proposition:






\begin{lem}\label{normalgoren} Let $A$ be an irreducible Noetherian  scheme and $Z\subset A$  a closed subscheme with  locally a complete intersection in $A$.
Let $\psi:A'\to A$ be the blow-up by $Z$.
Then, the following hold:
 \begin{enumerate}
    \item[(i)] $\psi^{-1}(Z)\simeq \PP(I_Z/I_Z^2)$, where $I_Z$ is the defining ideal of $Z$ in $A$.
    In particular, 
    the irreducible components of $\psi^{-1}(Z)$ and the irreducible components of $Z$ correspond bijectively.

\item[(ii)] Assume $A$ is a normal Gorenstein variety over a field $k$, and 
    for any irreducible component $Z'$ of $Z$,  the  singular loci $\sing A$ and $\sing Z$ of $A$ and of $Z,$
    respectively, satisfy:
    \begin{equation}\label{singlocus}
    Z'\not\subset (\sing A)\cup (\sing Z).
    \end{equation}   
    Then $\psi^{-1}(Z)$ is Gorenstein and    
        $A'$ is normal and Gorenstein.
    \end{enumerate}
\end{lem}
\begin{proof} %%%Hartshorne のample subvarieites..のp.105%%
    As the embedding $Z\subset A$ is locally a complete intersection, by \cite[IV, 16.9.4]{ega}, it follows
    $$\bigoplus_{n\geq0}I_Z^n/I^{n+1}_Z\simeq S(I_Z/I_Z^{2}),$$
    where $I_Z/I_Z^{2}$ is a locally free $\oo_Z$-modlue of rank $c=\codim (Z,A)$.
    The description yields $\psi^{-1}(Z)\simeq \PP(I_Z/I_Z^2)$ as required in (i).
   % 
    On the other hand, as $\psi^{-1}(Z)$ is a projective bundle on $Z$, its irreducible component is
    in the form $\psi^{-1}(Z')$ for an irreducible component $Z'$ of $Z$, which yields the second statement of (i).

    For (ii), we use (\ref{singlocus}) to see that $A'$ is $R_1$.
    %
    On the other hand,  we have that $Z$ is Gorenstein by  the assumption on $Z$ and $A$.
    Then, it follows $\psi^{-1}(Z)$ is locally isomorphic to  $Z\times \PP^{c-1}$, 
        which implies $\psi^{-1}(Z)$ is  Gorenstein.
    As $\psi^{-1}(Z)$ is locally a hypersurface of $A'$, it follows
    $A'$ is Gorenstein.
    Applying the Serre's criterion to $A'$, we obtain that $A'$ is normal.
\end{proof}

