\begin{prop}\label{az0} Let $k$ be an algebraically closed  field of characteristic $p\geq0$ and
      $E$  a prime divisor over the affine space $A=\AA_k^N$ over $k$
     with the center at the origin $0\in A$.
     Then, there exists a sequence:
     $$A_n\stackrel{\varphi_n}\longrightarrow A_{n-1} \to
       \cdots A_1 \stackrel{\varphi_1}\longrightarrow A$$
         of blow-ups   such that  

 \begin{enumerate}
 \item[(i)]    
     $E$ appears on $A_n$,
 \item[(ii)]
 the first blow-up $\varphi_1$ is by the maximal ideal $\m=(x_1,\ldots, x_N)\subset k[x_1,\ldots, x_N]$,
 \item[(iii)] for each \( i  \), the morphism \( \varphi_i: A_i \to A_{i-1} \) is the blow-up along 
 a complete intersection subscheme $Z_{i}\subset A_{i-1}$.
 One irreducible components of $Z_i$ is the center of \( E \) on \( A_{i-1} \), while the other components, if exist, 
 are not contained in the fiber over \( 0 \in A (=:A_0) \) on $A_{i-1}$,
% 
  \item[(iv)] $A_i$'s are all normal Gorenstein varieties and smooth  
  at the generic point of the center of $E$ and also smooth outside of the fiber over $0\in A$.
 \end{enumerate}   

 \end{prop}

 \begin{proof} 
 Let $\varphi_1: A_1\to A$ be the blow-up by the maximal ideal
 $(x_1,\ldots,x_N)\subset R_0:=k[x_1,\ldots, x_N]$, the ideal defining the origin $0\in A$
 which is the center of $E$ on $A$.
 (automatically (ii) and (iii) are satisfied for $i=1$).
 As $A_1$ is smooth, (iv) is satisfied for $i=1$.
 We will construct $\varphi_i$ by induction in $i$ so that (iii) and (iv) are satisfied.

 Let $i\geq2$ 
 and assume we constructed  $A_{i-1}$ with the properties (iii) and (iv).
 As $A_{i-1}\to A$ is projective, we can write $A_{i-1}=\proj R_{i-1}$ and 
 $$R_{i-1}=\oplus_{n=0}^\infty  J_n,$$
 where $R_0$-submodule $J_n\subset R_{i-2}$ is the degree $n$ part of $R_{i-1}$.
 By replacing $R_{i-1}$ by a suitable Veronese subring, we may assume that 
 $R_{i-1}$ is generated by  $J_1$.
  Let $\p_i\subset R_{i-1}$ be the homogeneous prime ideal defining the center of $E$ in $A_{i-1}$.

 \noindent
 {\bf Claim.}
  We can take a subset $\{f_1,\ldots, f_t\}\subset \p_i$ such that

 \begin{enumerate}
   \item  $V(f_1,\ldots, f_t)=V(\p_i)$ and 
   each $f_j$ has the common degree $d>0$ in the graded ring $R_{i-1}$,
   \item the linear system $\Lambda$ defined by the $k$-vector subspace 
   $$\langle  f_1,\ldots, f_t\rangle \subset 
   \Gamma(A_{i-1}, \oo_{A_{i-1}}(d))$$
   is very ample on $A_{i-1}\setminus V(\p_i)$.
   In prticular, $\Lambda$ is very ample on $A_{i-1}\setminus 
   \phi_{i-1}^{-1}(0)$, where $\phi_{i-1}:A_{i-1}\to A$ is the composite 
   $\varphi_{1}\circ\cdots\circ\varphi_{i-1}$ and $0\in A$ is the origin.
   Here, note that $V(\p_i)\subset  \phi_{i-1}^{-1}(0)$.
\end{enumerate}
%
Let $\{h_1,\ldots, h_s\}$ be a generator system of $J_1$ over $R_0$, then the linear system over $k$
 defined by $\{h_1,\ldots, h_s\}$ is
relatively very ample over $A$. Then, the affine space $A$ has a very ample linear system defined by $y_1,\ldots, y_m \in R_0$
such that the linear system defined by the following $k$-vector subspace
$$\langle y_\alpha\cdot h_\beta\rangle_{\alpha, \beta}\subset \Gamma(A_{i-1}, \oo_{A_{i-1}}(1))$$
 is very ample on $A_{i-1}$.
 Denote $y_\alpha\cdot h_\beta$ by $X_{\alpha\beta}$.

 To prove the Claim above, we start by taking any homogeneous generator system $\{f'_1,\ldots, f'_r\} $ of  $\p_i\subset R_{i-1}$ with the degree $d_1\leq\cdots\leq d_r$, respectively.
 We will construct an appropriate  system of elements with the properties required in (1) and (2).
 Here, $V(\p_i)\subset A_{i-1}$ is the center of $E$ on $A_{i-1}$.

  Let $d>d_r$.
 Define $$f_{i\gamma}:=f'_i\cdot X_\gamma^{(d-d_i)},$$
 where 
 $$\left\{ X_\gamma^{(d-d_i)} \middle| \gamma=1,\ldots, \left(\begin{array}{c}
                 														ms+d-d_i-1\\
														             d-d_i\\
														             \end{array}\right)  \right\}$$
 is the set of all monomials in variables $X_{\alpha\beta}$ of degree $d-d_i$.														             
 Then the set of elements
 $$\left\{ f_{i\gamma}\middle| 1\leq i\leq r, 1\leq \gamma\leq \left(\begin{array}{c}
                 														ms+d-d_i-1\\
														             d-d_i\\
														             \end{array}\right)  \right\}$$
gives the closed subset $V(f_{i\gamma})=V(\p_i)$.
Note that all $f_{i\gamma}$ are of degree $d$.
Thus (1) in the Claim holds.
Let $\Lambda$ be the linear system defined by the $k$-vector subspace
$\langle f_{i\gamma}\rangle\subset \Gamma(A_{i-1},\oo_{A_{i-1}}(d))$.
Then, $\Lambda $ has the base locus $V(\p_i)$ and is very ample outside of $V(\p_i)$.
As $V(\p_i)\subset \phi_{i-1}^{-1}(0)$, the linear system $\Lambda$ is very ample outside of $\phi_{i-1}^{-1}(0)$.
Now, denote the $\{f_{i\gamma}\} $ just by  $\{f_i \mid i=1,\ldots, t\} $ 
for simplicity of notation.
Then the system $\{f_i \mid i=1,\ldots, t\} $ satisfies  (2) required in the Claim.

Let $c=\height \p_i$ and take $c$ general linear combinations of $f_i$'s over $k$:
  $$\sum_{i=1}^r a_{ji}f_i  \ (a_{ji}\in k \ \mbox{ for}\ j=1,\ldots, c)$$
  and rename them as $f_1,\ldots, f_c$.
  Then, $\{f_1,\ldots, f_c\}$ becomes a regular sequence in $R_{i-1}$.
  Let $I_i\subset R_{i-1}$ be the ideal generated by $\{f_1,\ldots, f_c\}$ and $\mathcal{I}_{i-1}$  the 
  ideal sheaf of $\oo_{A_{i-1}}$ defined by $I_{i-1}$.
  Similarly, let $\mathcal{P}_i$ be the ideal sheaf of $\oo_{A_{i-1}}$ defined by $\p_i$.
   By the choice of $f_1,\ldots, f_c$, these give a regular system of paremeters of $\oo_{A_{i-1},P_i}$,
   where $P_i\in A_{i-1}$ is the generic point of $V(\p_i)$.
    Therefore, $$\mathcal{I}_i\oo_{A_{i-1},P_i}=\mathcal{P}_i\oo_{A_{i-1},P_i} .$$ 
  Therefore,  one of the  irreducible components of $Z_i:=V(I_{i}) \subset A_{i-1}$ is the center of $E$ on $A_{i-1}$.

%  
    As $Z_i\subset A_{i-1}$ is obtained by successive cutting $A_{i-1}$ with $c$ general hypersurfaces 
    $$H_i:=V(f_i)\ \ (i=1,\ldots, c) $$
    from the  linear system $\Lambda$,
   we obtain the following:
    \begin{enumerate}
         \item[(a)] $\dim (\sing A_{i-1})\cap Z_i < N-c$ and 
          \item[(b)] $\dim (\phi_{i-1}^{-1}(0)\setminus V(\p_i))\cap Z_i < N-c$.
     \end{enumerate}
     Indeed, first we have
     $$\dim (\sing A_{i-1}\setminus V(\p_i))\cap Z_i < N-c.$$
     Because $\Lambda$ is very ample on $A_{i-1}\setminus V(\p_i)$,
     each cut by a general member of $\Lambda$ makes the dimension of the intersection with $\sing A_{i-1}\setminus V(\p_i)$ exactly 1 less.
     Next we have
     $$\dim (\sing A_{i-1}\cap V(\p_{i}))\cap Z_i < N-c,$$
because $\dim V(\p_{i})=N-c$ and the generic point of $V(\p_{i})$ is smooth in $A_{i-1}$ by the induction hypothesis. 
Thus (a) follows, and (b) also follows in the similar way.

By (a), any irreducible component of $Z_i$ is not contained in $\sing A_{i-1}$, since the dimension of 
every irreducible component of $Z_i$ is $N-c$.
By (b), any irreducible component of $Z_i$, except for $V(\p_{i})$, is not contained in the fiber $\phi_{i-1}^{-1}(0)$. 
Then, $Z_i$ satisfies the condition (iii) of the proposition.

Moreover, we obtain that $$(A_{i-1}\setminus\phi_{i-1}^{-1}(0))\cap Z_i$$ is a smooth scheme
by the Bertini's Theorem ``for very ample linear system'' $\Lambda$ on
a smooth quasi-projective scheme
$A_{i-1}\setminus\phi_{i-1}^{-1}(0)$.
Note that the ``very ample version'' of  the Bertini's Theorem holds for any characteristic base field
(see the proof of \cite[II, Theorem 8.18]{ha}).
A fortiori, every irreducible component of $Z_i$ is not contained in $\sing Z_{i}$ nor in $\sing A_{i-1}$.
Now the condition (\ref{singlocus}) in Lemma \ref{normalgoren} is satisfied.
Therefore, if $\varphi_i:A_i\to A_{i-1}$ is the blow-up with the center $Z_i\subset A_{i-1}$,
then,  $A_i$ is also normal and Gorenstein by the lemma.
As the blow-up $\varphi_i$ is the same as the blow-up at the center $V(\p_i)\subset A_{i-1}$ of $E$ around the
generic point of $V(\p_i)$,
the generic point of the center of $E$ on $A_i$ is also smooth (see the comment below Proposition-Definition \ref{zs}).





As $A_{i-1}\setminus\phi_{i-1}^{-1}(0)$ and ($A_{i-1}\setminus\phi_{i-1}^{-1}(0))\cap Z_i$
are smooth, we also obtain the blown-up space $$A_{i}\setminus\phi_{i}^{-1}(0)$$ 
of  $A_{i-1}\setminus\phi_{i-1}^{-1}(0)$ by the center $(A_{i-1}\setminus\phi_{i-1}^{-1}(0))\cap Z_i$
is also smooth, which completes the  of (iv). 

As 
  the sequence of the blow-ups is the same as the Zariski sequence for $E$ around the centers of $E$ on any $A_i$ by (iii), 
  the prime divisor $E$ appears on $A_n$ for a certain $n\in \ZZ_{\geq0}$.
  Hence,  (i)  follows.
 \end{proof}

 \begin{defn} For a prime divisor $E$ over  $A$ with the center at a closed point $0\in A$, 
 the sequence in Proposition \ref{az0} is called a {\sl normal Gorenstein Zariski sequence} for $E$.
 This definition makes sense, as
  the sequence  is the same as the Zariski sequence for $E$ around the generic point of the center of $E$ on each $A_i$
  by the properties (i) and (iii) in Proposition \ref{az0}.
  \end{defn}

