\section{Proof of the Main Theorem and applications}

\noindent
   We fix the notation used in this section.
    Let $k$ be an algebraically closed  field of characteristic $p>0$.
 %   
    Let $A=\AA_k^N$ be the 
     affine space over $k$ of dimension $N\geq 2$ 
      and $0$ the origin of $A$.



 Let $E$ be a prime divisor over $(A, 0)$ and
 $$A_n\stackrel{\varphi_n}\longrightarrow A_{n-1} \to
       \cdots A_1 \stackrel{\varphi_1}\longrightarrow A$$
       be a normal Gorenstein Zariski sequence for $E$.
Proposition \ref{lifting of skeleton} guarantees the existence of a reasonable lifting of the sequence:
$$\wa_n\stackrel{\widetilde\varphi_n}\longrightarrow \wa_{n-1} \to
       \cdots \wa_1 \stackrel{\widetilde\varphi_1}\longrightarrow \wa=\AA_L^N,$$
In the following discussions, we will use the notation in Proposition \ref{lifting of skeleton}.


  As in \cite{I-lift}, for a technical reason, we will blow-up two more times from $A_n$ and lift them,
  which will lead to the main statement in this paper.


   \begin{lem}\label{main:F}
      Let $E$ be a prime divisor over $(A,0)$, and
    $$A_n\stackrel{\varphi_n}\longrightarrow A_{n-1} \to
       \cdots A_1 \stackrel{\varphi_1}\longrightarrow A$$
   be a normal Gorenstein Zariski sequence for $E$, 
      We use the same notation as in Proposition \ref{az0} and \ref{lifting of skeleton}.
        Let $$
        A_{n+2}\stackrel{\varphi_{n+2}}\longrightarrow A_{n+1}\stackrel{\varphi_{n+1}}\longrightarrow A_n$$ 
        be the composite of two blow-ups at general closed points $P_{n+1}\in E_n\subset A_n$ and  $P_{n+2}\in F_1\subset A_{n+1}$,
        where $F_1$ is the exceptional divisor for $\varphi_{n+1}$. 
        Denote the exceptional divisor for $\varphi_{n+2}$ by $F_2$.


     %  
      Then, by taking a skeletons $\Sigma \subset k$ sufficiently large, and letting $\wsig\subset \CC$ be its lifting,  
      one obtains  liftings $\tP_{n+1}\in \wa_n$ and $ \tP_{n+2}\in \wa_{n+1}$ of $P_n$ and $P_{n+1}$, respectively,
      and the sequence:
      $$
        \wa_{n+2}\stackrel{\widetilde\varphi_{n+2}}\longrightarrow \wa_{n+1}\stackrel{\widetilde\varphi_{n+1}}\longrightarrow \wa_n,$$ 
         the composite of two blow-ups at  $\tP_{n+1}\in \we_n\subset \wa_n$ and  $\tP_{n+2}\in \wF_1\subset \wa_{n+1}$,
         where $\wF_1$ and $\wF_2$ are the exceptional divisor of $\widetilde\varphi_{n+1}$ and  $\widetilde\varphi_{n+2}$, respectively.


        Then, we obtain 
              $$k_{F_1}=k_{\wF_1}=N-1+k_{E_n}=N-1+k_{\we_{n}}\ \mbox{and}$$
                     $$k_{F_2}=k_{\wF_2}=2(N-1)+k_{E_n}=2(N-1)+k_{\we_{n}}.$$



\end{lem}

\begin{proof} 
      Take a  general closed point $P_{n+1}\in E_n\subset A_n$ such that
       $$P_{n+1} \not\in  \bigcup_{j<n}(E_j\cup E'_j),$$
       where we denote  the proper transform of $E_j$ and $E'_j$ on $A_n$ by the same symbols as $E_j$ and $E'_j\subset A_j$.
       Here, we denote the fiber $\varphi_j^{-1}(Z_j)= E_j+E'_j$ as Cartier divisors on $A_j$.


     Next, take a general closed point $P_{n+2}\in F_1\subset A_{n+1}$ such that 
   $$P_{n+2}\not\in E_n,$$
   where $E_n$ denotes the proper transform of $E_n$ on $A_{n+1}$ as well.
   Here, we note that $P_{n+1}$ and $P_{n+2}$ are $k$-valued point as $k$ is algebraically closed.
   So, we can realize their defining ideals in the skeletons $S_{n}$ and $S_{n+1}$ for sufficiently large $\Sigma\subset k$.
   Then, in the same way as in Proposition \ref{az0}, we can construct a sequence 
    $$
        \wa_{n+2}\stackrel{\widetilde\varphi_{n+2}}\longrightarrow \wa_{n+1}\stackrel{\widetilde\varphi_{n+1}}\longrightarrow \wa_n,$$ 
        of blow-ups with the centers $\tP_{n+1}\in \we_n$ and $\tP_{n+2}\in \wF_1$ of liftings of $P_{n+1}$ and $P_{n+2}$,
        respectively.
        Hence, by the choice of the points of blow-ups, we obtain the required equalities.
  \end{proof}      

  %%%%
   \begin{lem}\label{pull-back} Under the notation in the proof of Proposition \ref{az0} and Lemma \ref{main:F}, consider the ideals
 $$\uwI_1=\wm=(x_1,\ldots,x_N)\subset \wsig[x_1,\ldots,x_N]\ \ \mbox{and}$$
 $$\underline{I}_1=\m=(x_1,\ldots,x_N)\subset \Sigma[x_1,\ldots,x_N].$$
Then, the following hold for $1\leq i \leq n+2$:

\begin{enumerate}
\item[(i)] $\oo_{\wB_i}/\wm^t\oo_{\wB_i}$ is $\ZZ$-flat at $p\in \ZZ$ 
for every $t\in \NN$, and
\item[(ii)] $\oo_{\wB_i}/\wm^t\oo_{\wB_i}\otimes _\ZZ \zp=\oo_{B_i}/\m^t\oo_{B_i}$.
\end{enumerate}
\end{lem}

\begin{proof} For $1\leq i\leq n+2$, denote the proper transforms on $B_i$ of the prime divisors $E_j\subset B_j$ and $\we_j\subset \wB_j$ $(i<j)$ by the same symbols $E_j$ and $\we_j$, as we did in the previous discussions.
(For consistency of the notation, only in this proof, we denote $F_i$ and $\wF_i$ $(i=1,2)$ by $E_{n+i}$ and $\we_{n+i}$, respectively.)
%%%%%
As $Z_i$ ($i\geq2$) is not necessarily irreducible,
the irreducible component of the exceptional divisor of $\varphi_i: B_i\to B_{i-1}$ is not only $E_i$.



%%%%
As $\widetilde\varphi_1$ is the blow-up by $\widetilde\m=(x_1,\ldots, x_N)\subset \ws_0$, the pull-back
$\wm^t\oo_{\wB_1}$ is an invertible ideal sheaf on $\wB_1$.
Then, for every $i\geq 1$ its pull-back $\wm^t\oo_{\wB_i}$ on $\wB_i$ is also an invertible ideal sheaf on $\wB_i$.
By the similar reason, $\m^t\oo_{B_i}$ is also an invertible ideal sheaf for every $i\geq 1$.

For the proof of (i), let $\wD_i\subset \wB_i$ be the subscheme defined by $\wm^t\oo_{\wB_i}$,
and $D_i\subset B_i$ the subscheme defined by $\m^t\oo_{B_i}$ for $1\leq i\leq n+2$.
Then, $\wD_i\subset\wB_i$ is locally a hypersurface and its support is  contained in the exceptional divisor of $\widetilde\phi_i: \wB_i\to \wB_0$.
%
Since the exceptional divisor of $\widetilde\phi_i$ does not contain $B_i$,
the closed subscheme $\wD_i$ does not contain the fiber  $B_i$ over $p$, 
which yields that $\wD_i$ is flat over $\ZZ$ at $p$ (see,  \cite[Corollary, p.177]{mats}).
This completes the proof of (i)
%%


For the proof of (ii), we first claim that the supports of $D_i$ and $\wD_i$ are expressed as follows:
\begin{equation}\label{support}
\supp D_i=\bigcup_{j\leq i}E_j,\ \mbox{and}\ \ \supp \wD_i= \bigcup_{j\leq i}\we_j \ \ \mbox{in\ a\ neighborhood\ of} \ p .
\end{equation}
Here, we remark again that the irreducible components of the exceptional set of $\widetilde\phi_i$ are not only $\we_1,\ldots, \we_i$, because each center of the blow-up $\wv_j $ $(j\leq i)$ is not necessarily irreducible.
We will prove these equalities in (\ref{support}) by induction on $i$.

For $i=1$ the equalities are trivial. 
So we assume $i\geq2$ and the equalities hold for $i-1$.
Now, assume there exists an irreducible component $C$ of $D_i$ such that
$$C\not\subset \bigcup_{j\leq i}E_j.$$
Then, $\varphi_i(C)\subset D_{i-1}$.
Therefore, $\varphi_i(C)\subset Z_i$, because otherwise, $\varphi_i$ is isomorphic at the generic point
of $C$ and
by the hypothesis of the induction, we have 
$\varphi_i(C)\subset E_j\subset B_{i-1}$ for some $j<i$, which gives
$C\subset E_j\subset B_i$, a contradiction to the assumption.
Hence, we obtain
$$\varphi_i(C)\subset Z_i\cap D_{i-1}\subset B_{i-1}\ \mbox{ and}\ \ \varphi_i(C)\not\subset V(\p_i).$$ 
By the construction of $Z_i$ (see, Proposition \ref{az0}), it follows
$$\codim (Z_i\cap D_{i-1}\setminus V(\underline\p_i), B_{i-1})=c_i+1:=\height \p_i+1,$$
which yields $$\codim (C, B_i)\geq \codim (\varphi_i^{-1}(\varphi_i(C)), B_i)\geq \codim (\varphi_i(C), B_{i-1})-(c_i-1)$$
$$
\geq \codim (Z_i\cap D_{i-1}\setminus V(\underline\p_i), B_{i-1} )-(c_i-1)=2,$$
a contradiction to that $C$ is an irreducible component of a closed subscheme defined by a locally principal ideal
on an irreducible reduced scheme $B_i$.
Therefore we obtain
$$\supp D_i=\bigcup_{j\leq i}E_j.$$

On the other hand, we have 
$$\codim (\wZ_i\cap \wD_{i-1}\setminus V(\uwtp_i), \wB_{i-1} )\geq \codim (Z_i\cap D_{i-1}\setminus V(\underline\p_i), B_{i-1} )=c_i+1$$
in a neighborhood of $p\in \ZZ$.
Then, by the similar discussion as above, we obtain
$$\supp \wD_i= \bigcup_{j\leq i}\we_i.$$

In order to prove (ii), it is sufficient to show the equality 
$$\m^t\oo_{B_i}=\wm^t\oo_{\wB_i}\otimes_\ZZ \zp$$ 
of the ideal sheaves for every $1\leq i \leq n+1$.
Note that it is equivalent to the equality of their extensions to the normal variety 
$B_{iQ}:=B_i\otimes_\Sigma Q(\Sigma)$,
where $Q(\Sigma)$ is the field of fractions of $\Sigma$.
As in Lemma \ref{main:F}, we denote
$\wa_i=\wB_i\otimes_\wsig Q(\wsig)$.
Then, as $B_{iQ}$ and $\wa_i$ 
 are normal varieties, and from the claim proved above,
the ideal sheaves have the following expressions:
$$\m^t\oo_{B_{iQ}}=\oo_{B_{iQ}}\left(-\sum_{j\leq i}a_jE_j\right),$$
$$\wm^t\oo_{\wa_i}=\oo_{\wa_i}\left(-\sum_{j\leq i}\ta_j\we_j\right).$$
As $\left(\wm^t\oo_{\wB_i}\otimes_\ZZ\zp\right)\otimes_\Sigma Q(\Sigma)=\oo_{B_{iQ}}(-\sum_{j\leq i}\ta_j E_j)$,
for the proof of (ii), it is sufficient to show $a_j=\ta_j$ ($j\leq i$).
We will prove this by induction on $i$.

For $i=1$, it is clear that $a_1=\ta_1$.
Assume $i\geq2$ and $a_j=\ta_j$ holds for $j\leq i-1$.
The center $P_i\in B_{i-1Q}$ of the blow-up $\varphi_i$ and the center 
$\wP_i\in \wa_{i-1}$ of the blow-up $\wv_i$ satisfies
\begin{center}
 $P_i\in E_j$ if and only if $\wP_i\in \we_j$ for $j\leq i$.
 \end{center}
 $$a_i=\sum_{P_i\in E_j}a_j =\sum_{\wP_i\in \we_j}\ta_j=\ta_i,$$
 where the first and the last equalities follows from the fact that $P_i\in A_{i-1}$ and
 $\tP_i\in \wa_{i-1}$ are non-singular (see the last part of the proof of Proposition \ref{lifting of skeleton}).
Hence, the statement holds for $i$.
%%%%
\end{proof}


\begin{thm}[Theorem \ref{main}, (i), (ii)]\label{main'}
 Let $N$ be an integer $\geq 2$,
and $k$  an algebraically closed field of characteristic $p>0$.
Let $A=\AA_k^N$ be the 
     affine space over $k$ of dimension $N$,  
      and $0$ the origin of $A$.
    Let $E$ be a prime divisor over $A$ with the center at $0$, and    $\a\subset k[x_1,\ldots,x_N]$ a non-zero  ideal.
     Then, there exists  a prime divisor $F_\CC$ over the affine space $A_\CC=\AA_\CC^N$  over $\CC$ with the center
      at the origin $\tze$ satisfying the following:

    \begin{enumerate}
      \item[(i)]  $2(N-1)+k_E=k_{F_\CC}$;
      \item[(ii)]  there exists a lifting $\taa\subset \oo_{A_\CC}$ of $\a$  satisfying
                 $$v_E(\a)=v_{F_\CC}(\taa).$$


      \end{enumerate}
\end{thm}


\begin{proof} 
We may assume $N\geq 4$, because the theorem is proved for $N\leq 3$ by \cite[Theorem 5.3]{I-lift}.
We replace the sequence of non-singular blow-ups in \cite[Proposition 4.2]{I-lift} by our normal Gorenstein Zariski sequence.
By \cite[Remark 5.8]{I-lift},
only parts we need to verify are 
\begin{enumerate}
\item
Lemma \ref{pull-back} for $\widetilde\phi_{n+2}$, a lifting of $\phi_{n+2}$, which is our normal Gorenstein Zariski sequence plus two more blow-ups, and
\item $R^1\phi_{n+2}\oo_{A_{n+2}}=0$.
\end{enumerate}
Actually, the proof of (i) of the theorem follows immediately from Lemma \ref{main:F} as in \cite[Theorem 5.3]{I-lift}.
The proof of (ii) in \cite[Theorem 5.6]{I-lift} for $\dim \geq 4$ was divided into four statements; (a)--(d).
These (a)--(d) were proved by using (1) and (2) for composite of smooth blow-ups in \cite{I-lift}.

Now, in our case for normal Gorenstein Zariski sequence,
Lemma \ref{pull-back} is proved above and the vanishing (2) holds for any proper 
birational morphism $A_{n+2}\to A$ from a normal variety $A_{n+2}$ to a smooth variety $A$
defined over a field of arbitrary characteristic (\cite{iy},\cite{lodh}).
Here, we note that $A_{n+2}$ is normal, since it is obtained by just two more blow-ups by smooth closed points
from a normal Gorenstein variety $A_n$.
\end{proof}



  \begin{cor}[Theorem \ref{main}, (iii)] 
  Let $k$ be an algebraically closed  field of characteristic $p>0$, $A=\AA_k^N$ the 
     affine space over $k$ of dimension $N\geq 2$ 
      and $0$ the origin of $A$.
 %   
    Let $E$ be a prime divisor over $(A,0)$ and  $\a_1,\ldots, \a_r\subset k[x_1,\ldots, x_N]$  non-zero  ideals.
     Then, there exists  a prime divisor $F_\CC$ over the affine space $A_\CC=\AA_\CC^N$  over $\CC$ with the center
      at the origin $\tze$ satisfying the following:


 There exist liftings $\taa_i\subset \oo_{A_\CC}$ of $\a_i$ $(i=1,\ldots,r)$ such that
                 for every multi-ideal
                 $\a^e:=\a_1^{e_1}\cdots\a_r^{e_r}$ $(e_i\in \RR_{>0})$ on $A$,
                 the lifting 
                 $\taa^e=\taa_1^{e_1}\cdots\taa_r^{e_r}$ of $\a^e$ on $A_\CC$
                 satisfies 
                 $$2(N-1)+a(E;A,\a^e) =a(F_\CC;A_\CC,\taa^e).$$ 

\end{cor}
\begin{proof} By (i) and (ii) of the theorem, the equality
 $$2(N-1)+a(E;A,\a) =a(F_\CC;A_\CC,\taa)$$ 
 is obvious for an ideal.
 For multi-ideal case, as the number of ideals is finite in the multi-ideal, we can take common centers  $P_{n+1}$ and $P_{n+2}$ 
 general for all ideals.
 Then we obtain a lifting $\taa_i$ of $\a_i$ for each $i$ such that $v_E(\a_i)=v_{F_\CC}(\taa_i)$,
 which completes the proof of our corollary.
\end{proof}


Until now, we assume the base space $A$ to be the affine space.
 However, 
we can apply the theorem also to a pair consisting of  a non-singular  variety and a multi-ideal with a real exponent.
In such a case, we cannot define a lifting of a regular function around the point $0$,
but passing through the completion we can reduce the discussion to the case of the affine space.


\begin{cor}[Corollary \ref{equal-p-0}, (i)]\label{basic.cor1}
   Let $k$ be an algebraically closed field  of 
       characteristic $p>0$.
         Let $0\in A$ be a  non-singular closed point of a variety $A$ of dimension $N$.
  Then, for fixed $N$ and an exponent $e\in \RR_{>0}^r$, the set of log discrepancies 
  $$\Lambda_{N,e}:=\left\{a(E;A,\a^e) \middle| \begin{array}{l}
                                           E: \mbox{prime\ divisor\ over\ }(A,0)\\
                                           (A, \a^e) :\mbox{log\ canonical\ at\ }0\\
                                           \end{array} 
                                           \right\}$$
    is discrete in the sense of Corollary \ref{equal-p-0}, (i).
    In particular, for a fixed $e$, the set $\{\mld(0,A, \a^e) \mid \a:\ \mbox{non-zero\ ideal}\ \}$ is finite.
  % 
\end{cor}


The proof of Corollary \ref{basic.cor1} is given in the same way as  \cite[Corollary 5.10]{I-lift}.
The following is obtained by applying Corollary \ref{basic.cor1} to a special case.

  \begin{cor}\label{compute}  Let $k$ be an algebraically closed field  of 
       characteristic $p>0$.
         Let $0\in A$ be a  non-singular closed point of a variety $A$ of dimension $N$,
         and $\a^e$ a multi-ideal with a real exponent.
         Then, there exists a prime divisor over $A$ with the center at $0$ computing 
         $$\mld(0;A,\a^e).$$
   \end{cor}

   \begin{proof} If $\mld(0;A,\a^e)=-\infty$, then a prime divisor $E$ with $a(E; A, \a^e)<0$ computes
   the mld. 
   If $\mld(0;A,\a^e)\geq 0$, the discreteness of log discrepancies in Corollary \ref{basic.cor1} gives the
   existence of a prime divisor computing the mld.
  % 
   \end{proof}


 The existence of a prime divisor computing $\mld$ in positive characteristic was already proved for a special case 
 by K. Shibata (\cite{sb}).


  \begin{defn} Let $k$ be a field and $0\in X$ a non-singular $k$-valued point of dimension $N\geq2$.
  Fix an exponent $e\in \RR_{>0}^r$.
  We define  
  $$T_{N,e,k}:=\{\lct(0;X,\a^e) \mid \a^e \ \mbox{ a\ multi-ideal\ with\ the\ exponent\ }e \mbox{ on}\  X\}$$
  the set of log canonical thresholds.
  \end{defn}

  \begin{cor}\label{basic.cor2}
  Let $k$ be an algebraically closed field $k$ of positive characteristic
 and $0\in A$  a non-singular closed point  in a variety $A$ of dimension $N$.
  Fix an exponent $e\in \RR_{>0}^r$.
 %
  Then, $$T_{N,e,k}\subset T_{N,e,\CC}.$$
 \end{cor}     
   %

 \begin{proof} 
 As is seen in the proof of Corollary 5.19 in \cite{I-lift}
  we may assume that $A=\AA_k^N$ and $0$ is 
 the origin of $\AA_k^N$.
 As 
  the corollary is proved for $N\leq 3$ in \cite{I-lift}
 we may assume that $N\geq 4$.
 For simplicity, we denote ${\sum e_i v_E(\a_i)}$ by $v_E(\a^e)$.

 In \cite{dm}, they prove that $T_{N-1,e,\CC}\subset T_{N,e,\CC}$ and the accumulation points of $T_{N,e,\CC}$ belong to $T_{N-1,e,\CC}$.
 Actually, they stated it only for $e=(1)\in \RR_{>0}$.
 However, their proof also works for every fixed $e\in \RR^r_{>0}$.
Now we look at a positive characteristic pair $(A, \a^e)$ and let $c=\lct(0;A,\a^e)$.
 If $c\in T_{N-1,e,\CC}$, then $c\in T_{N,e,\CC}$, which completes the proof.
  Assume $c\not\in T_{N-1,e,\CC}$, then by the result of \cite{dm}, $c$ is not an accumulation point of $T_{N,e,\CC}$.
 Therefore, we obtain $\epsilon>0$ such that:
  $$(c, c+\epsilon)\cap T_{N,\CC}=\emptyset.$$ 
  We claim that there is a prime divisor $E$ over $(A,0)$ such that 
  \begin{equation}\label{ineq1}
  z(E;A,\a^e)=\frac{k_E+1}{v_E(\a^e)}<c+\frac{\epsilon}{2},\ \ \mbox{and}
  \end{equation}
  \begin{equation}\label{ineq2}
  \frac{2(N-1)}{v_E(\a^e)}<\frac{\epsilon}{2}.
  \end{equation}
 Indeed, by the definition of $\lct$, it is clear that there exists a prime divisor $E'$ over $A$ 
  with the center 
  ``containing $0$'' and satisfies the inequality (\ref{ineq1}):
 $$
  z(E';A,\a^e)=\frac{k_{E'}+1}{v_{E'}(\a^e)}<c+\frac{\epsilon}{2}.
 $$
 We need to find a prime divisor ``with the center at $0$'' satisfying the inequality (\ref{ineq1}).
 If the center of $E'$  is not $\{0\}$, then by suitable blow-ups, 
 we obtain a normal variety $\overline{A}$ on which $E'$ appears, and there is an exceptional divisor $E'_1$ on 
 $\overline{A}$ with the center at $0$ such that
 $$E'\cap E'_1\neq \emptyset.$$ 
 %
  We may assume that 
  $\overline{A}$ is smooth around $E'\cap E'_1$ outside a closed subset of codimension $4$, 
  and 
  $E'$ and $E'_1$ intersect normally there.
  Because 
  even over a field of positive characteristic, there is a log resolution for dimension $\leq 3$ (\cite[Proposition 4.2]{c-p08}).


  If $z(E'_1;A,\a^e)\geq c+{\epsilon}/{2}$, then take the blow-up at the intersection $E'\cap E'_1$ to obtain a new prime 
  divisor  $E'_2$  dominating $E'\cap E'_1$ such that
 %
  $$z(E';A,\a^e)<z(E'_2;A,\a^e)<z(E'_1;A,\a^e).$$
  Next,  blow-up at $E'\cap E'_2$ to obtain $E'_3$. 
  Continue this process, then we have a sequence of prime divisors $\{E'_i\}$ over $(A,0)$ such that 
  $$\lim_{i\to \infty} z(E'_i;A,\a^e)=z(E'; A,\a^e).$$
  This gives a prime divisor $E'_n$ over $(A,0)$ satisfying (\ref{ineq1}).
  The inequality (\ref{ineq2}) in the claim holds when one takes  sufficiently many times of blow-ups.


  For $E$ and $\a^e$, take a prime divisor $F_\CC$ and a lifting $\taa^e $ on $\AA_\CC^N$ as in Theorem \ref{main}.
  Then we obtain the inequalities by using Lemma \ref{inequality of mld}:
  $$c+\epsilon >\frac{k_E+1+2(N-1)}{v_E(\a^e)}=\frac{k_{F_\CC}+1}{v_{F_\CC}(\taa^e)}\geq \lct(\tze;\AA_\CC^N,\taa^e)\geq
  \lct(0;A,\a^e)=c.$$
  By the definition of $\epsilon$, the last inequality must be the equality:
  $$\lct(\tze;\AA_\CC^N,\taa^e)=
  \lct(0;A,\a^e)=c,$$
  which yields $\lct(0;A,\a^e)\in T_{N,e,\CC}$.


 \end{proof}

 \begin{cor}[Corollary \ref{equal-p-0},(ii),(iii)]   Assume  $0\in A$ is a non-singular closed point of a variety of dimension $N$
 over an algebraically closed field. 
           Then the following  hold:
\begin{enumerate}
          \item[(ii)]\label{rational}{\rm(\bf Rationality of $\lct$'s and their accumulation points)}  
          For a rational exponent $e$ and the multi-ideal $\a^e$ on $A$, 
          the log canonical threshold $\lct(0;A,\a^e)$ is a rational number and an accumulation point of the log canonical
         thresholds is also a rational number.
         \item[(iii)]\label{acc.lct}{\rm(\bf ACC of $\lct$)}   Let $D\subset \RR_{>0}$ be a DCC set.
       Then,  ACC holds for the set   $$T_{ N, k}(D):=\{\lct(0;A,\a^e) \mid e=(e_1,\ldots,e_r), \forall e_i \in D\}.$$
\end{enumerate}    

 \end{cor}

 \begin{proof} By Corollary \ref{basic.cor2}, for rational $e$, every value $c=\lct(0; A,\a^e)$  belongs to $T_{N,e,\CC}\subset \QQ$,
   and $T_{N,e,\CC}$ is known to be closed (\cite{dm}),
    therefore (ii) follows immediately.
As the set $T_{N,\CC}(D)$ satisfies ACC by \cite{dem} for a special case and by \cite{hmx} for the general case,
its subset $T_{N,k}(D)$ satisfies ACC as well.
%
  \end{proof}
