\end{figure}

We are therefore dealing with the two following systems~:
\begin{equation}\label{GasDynamicLeft}
\left\{\begin{array}{l}
\ds{\partial_{t}\rho_{\ell}(t,x)+ \partial_{x} (\rho_{\ell} u_{\ell})(t,x)=0,}\\
\ds{\partial_{t}(\rho_{\ell} u_{\ell})(t,x)+\partial_{x} (\rho_{\ell} u_{\ell}^2+ p(\rho_{\ell}))(t,x)=0,}
\end{array}\right. \text{ for } x \in [0,L_{\ell}],
\end{equation}
and
\begin{equation}\label{GasDynamicRight}
\left\{\begin{array}{l}
\ds{\partial_{t}\rho_{r}(t,x)+ \partial_{x} (\rho_{r} u_{r})(t,x)=0,}\\
\ds{\partial_{t}(\rho_{r} u_{r})(t,x)+\partial_{x} (\rho_{r} u_{r}^2+ p(\rho_{r}))(t,x)=0,}
\end{array}\right. \text{ for } x \in [0,L_{r}],
\end{equation}
complemented with no-flux boundary conditions, at least for smooth solutions, at the external points of the two intervals, namely, always setting for the flux $q=\rho u$ in the following~:
\begin{equation}\label{bc}
\left\{\begin{array}{l}
\partial_{x} \rho_{\ell} (t, 0)=0, \quad q_{\ell} (t, 0)=0, \text{ for all } t \geq 0 \text{ on the left arc,}
\\
 \partial_{x} \rho_{r} (t, L_{r})=0 ,\quad q_{r}(t, L_{r}) =0, \text{ for all } t \geq 0 \text{ on the right arc}.
 \end{array}\right.
 \end{equation}
 Clearly the boundary conditions, as usual for hyperbolic problems, have to be intended in a proper sense, since sometimes, due to the direction of the characteristics with respect to the boundary, they need to be interpreted, see \cite{serre} and references therein for more details.

Finally, we define transmission conditions at the junction, which couple the unknowns of both systems. For that purpose, we consider the equality of  fluxes in order to have the mass conservation at the junction, i.e.~:
\begin{equation}\label{jcegal}
q_{\ell} (t, L_{\ell})=q_{r}(t, 0), \text{ for all } t \geq 0 .
\end{equation}
We supplement this condition with a jump transmission  condition (JTC) for the density at the junction, that is to say~:
\begin{equation}\label{jc}
q_{\ell} (t, L_{\ell})=q_{r}(t, 0)= \kappa (\rho_{\ell}(t, L_{\ell})-\rho_{r}(t, 0)), \text{ for all } t \geq 0,
\end{equation}
where $\kappa$ is a {\it permeability coefficient } that we suppose to be constant. 
These previous conditions represent some transport conditions through a jump (given by a membrane or a change of domain), and  the fluxes are linked with the difference of densities on both sides of the jump.

 This condition (JTC)  is the hyperbolic analogous of the parabolic Kedem-Katchalsky transmission condition, see for instance \cite{KK,QVZ,CZ,CN}. The connection between condition \eqref{jc} and the Kedem-Katchalsky condition can be seen in the diffusive limit of the damped version of equation \eqref{GasDynamic}. By scaling this equation as in \cite{DiFM02}, we obtain the perturbed system 
\begin{equation*}%\label{GasDynamic_diffusive}
\left\{\begin{array}{l}
\ds{\partial_{t}\rho+ \partial_{x} (\rho u)=0,}\\
\ds{\partial_{t}(\epsilon^2\rho u)+\partial_{x} (\epsilon^2\rho u^2+ p(\rho))=-\rho u,}
\end{array}\right.
\end{equation*}
where the inertial terms $\partial_{t}(\rho u)+\partial_{x} (\rho u^2)$ are supposed to be negligible. 

So, as $\epsilon$ tends to zero, the momentum $\rho u$ approaches $-\partial_x p(\rho)$ and, as shown in \cite{DiFM02},  we obtain the porous medium equation
\begin{equation*}%\label{porousmedia}
\partial_{t}\rho- \partial_{xx} p(\rho)=0,
\end{equation*}
see also \cite{NRT2} in the framework of asymptotic preserving numerical schemes for isentropic Euler equations coupled with chemotaxis. 

Replacing $q=\rho u$ by $-\partial_x p(\rho)$  in \eqref{jc}, we obtain the condition
\begin{equation*}%\label{kk}
-\partial_x p(\rho_{\ell})  (t, L_{\ell})=-\partial_x p(\rho_{r})(t, 0) = \kappa (\rho_{\ell} (t, L_{\ell})-\rho_{r}(t, 0))
\end{equation*}
which is in the form of the diffusive Kedem-Katchalsky condition treated for instance in \cite{CGLP, CDP24}. 


Clearly, condition  \eqref{jcegal} together with condition \eqref{bc} ensure the mass conservation of the system, that is to say, working with smooth solutions~:
\begin{equation}\label{consmass2}
 \frac{d}{dt}m (t)=0, \text{ with } m(t)= \int_{0}^{L_{\ell}} \rho_{\ell}(t, x) \, dx+\int_{0}^{L_{r}} \rho_{r}(t, x) \, dx.
  \end{equation}

\subsection{Entropy dissipation}\label{sec:entropy}
Let us  prove now that, at least for smooth solutions,  system \eqref{GasDynamicLeft}-\eqref{jc} is endowed with an entropy dissipation property at the continuous level under the condition that the density jump is small enough at the junction.
% and that this property is also preserved at the discrete level. In the numerical tests of Sec.\ref{NumericalTests}, we will  check  numerically at the discrete level that the entropy dissipation property is indeed satisfied by the numerical scheme we use. 

First, on an interval, there exists at least an entropy--entropy flux pair $(\eta,G)$ for system \eqref{GasDynamic},  see \cite{Dafermos} p.212, namely the functions 
\begin{equation}\label{eq:entropy_pair}
 \eta(\rho, \rho u)=\frac 1 2 \rho u^2+ \frac{p_{0}}{\gamma-1} \rho^\gamma \text{ and }G(\rho, \rho u)=\left(\frac 1 2 \rho u^2+ \frac{p_{0} \gamma}{\gamma-1} \rho^\gamma\right)u.
\end{equation}
The function $\eta$ is convex and, for smooth solutions $(\rho,q= \rho u)$ to system \eqref{GasDynamic} we have
\begin{equation*}%\label{eq:entropy_equ}
\partial_{t} \eta(\rho, q)+\partial_{x} G(\rho, q) = 0.
\end{equation*}
For weak solutions, the admissible (entropy) solutions have to verify (in the weak sense) the inequality
\begin{equation}\label{eq:entropy_inequ}
\partial_{t} \eta(\rho, q)+\partial_{x} G(\rho, q) \leq 0,
\end{equation}
and we can say that the admissible solutions dissipate the entropy (see again \cite{Dafermos}). In general, for one single interval $[0,L]$ with no flux conditions, the quantity 
 \[\int_{0}^{L} \eta(\rho(t,x), q (t,x))dx	\]
is decreasing in time.

Now, we want to investigate if condition (JTC) in \eqref{jc} preserves this dissipation property, at least in some range of solutions. Let us consider smooth solutions to equation  \eqref{eq:entropy_inequ} on the $2$ arcs of the previous  network and integrate it with respect to time and space~: 
\begin{equation*}
\begin{aligned}
S(t):= \int_{0}^{L_{\ell}}& \eta(\rho_{\ell}(t,x), q_{\ell} (t,x))dx+ \int_{0}^{L_{r}} \eta(\rho_{r}(t,x), q_{r} (t,x))dx  \\
&\leq  \int_{0}^{L_{\ell}} \eta(\rho_{\ell}(0,x), q_{\ell} (0,x))dx+ \int_{0}^{L_{r}} \eta(\rho_{r}(0,x), q_{r} (0,x))dx \\
 &-\int_{0}^t  \left(G (\rho_{\ell}(s,L_{\ell}), q_{\ell} (s,L_{\ell}))-G (\rho_{\ell}(s,0), q_{\ell} (s,0))\right) ds\\
 &
 -\int_{0}^t \left(G (\rho_{r}(s,L_{r}), q_{r} (s,L_{r}))-G (\rho_{r}(s,0), q_{r} (s,0))\right)ds. 
\end{aligned}
\end{equation*}

Thanks to boundary conditions on the external domain, we find that since $\gamma>1$, we have 
\[\ds G (\rho_{r}(s,L_{r}), q_{r} (s,L_{r}))=G (\rho_{\ell}(s,0), q_{\ell} (s,0))=0,\] which leads to the inequality~:
\begin{equation}\label{eq:entropy_inequ_estimate}
\begin{aligned}
 S(t)=\int_{0}^{L_{\ell}}& \eta(\rho_{\ell}(t,x), q_{\ell} (t,x))dx+ \int_{0}^{L_{r}} \eta(\rho_{r}(t,x), q_{r} (t,x))dx  \\
&\leq  \int_{0}^{L_{\ell}} \eta(\rho_{\ell}(0,x), q_{\ell} (0,x))dx+ \int_{0}^{L_{r}} \eta(\rho_{r}(0,x), q_{r} (0,x))dx \\
 &-\int_{0}^t  \left(G (\rho_{\ell}(s,L_{\ell}), q_{\ell} (s,L_{\ell}))-G (\rho_{r}(s,0), q_{r} (s,0))\right)ds. 
\end{aligned}
\end{equation}
Therefore, if the quantity $\ds \Delta G(t):= G (\rho_{\ell}(t,L_{\ell}), q_{\ell} (t,L_{\ell}))-G (\rho_{r}(t,0), q_{r} (t,0)) \geq 0$ for all $t>0$, we have entropy dissipation, that is to say  for all $t>0$ it holds
\begin{equation*}%\label{eq:entropy_diss}
S(t)\leq S(0)
\end{equation*}
for all $t>0$.

Now, using the conditions at the junction, we can compute $\ds  \Delta G$
 as follows. Using that $\rho>0$, we rewrite $G(\rho, q)$ as~: $$ G(\rho, q)=G(\rho, \rho u)=\frac 1 2 \rho u^3+ \frac{p_{0} \gamma}{\gamma-1} \rho^\gamma u =\frac 1 2 \frac{q^3}{\rho^2}+ \frac{p_{0} \gamma}{\gamma-1} \rho^{\gamma-1} q $$
and therefore 
\begin{equation*}
\begin{aligned}
 &\Delta G(t)= G (\rho_{\ell}(t,L_{\ell}), q_{\ell} (t,L_{\ell}))-G (\rho_{r}(t,0), q_{r} (t,0))\\
& = \frac 1 2 \left(\frac{(q_{\ell} (t,L_{\ell}))^3}{(\rho_{\ell}(t,L_{\ell}))^2}-\frac{(q_{r} (t,0))^3}{(\rho_{r}(t,0))^2}\right)+ \frac{p_{0} \gamma}{\gamma-1} \left((\rho_{\ell}(t,L_{\ell}))^{\gamma-1} q_{\ell} (t,L_{\ell})-(\rho_{r}(t,0))^{\gamma-1} q_{r} (t,0) \right)
%-G (\rho_{r}^*, q_{r}^*)+G (\rho_{\ell}^*, q_{\ell}^*)= \frac 1 2 \left(\frac{(q_{\ell}^*)^3}{(\rho_{\ell}^*)^2}-\frac{(q_{r}^*)^3}{(\rho_{r}^*)^2}\right)+ \frac{p_{0} \gamma}{\gamma-1} \left((\rho_{\ell}^*)^{\gamma-1} q_{\ell}^*-(\rho_{r}^*)^{\gamma-1} q_{r}^* \right)
\end{aligned}
\end{equation*}
Using the conditions \eqref{jc} at the junction, the previous expression can be simplified as~:
\begin{equation*}
\begin{aligned}
\Delta G(t)= G (\rho_{\ell}(t,L_{\ell}), q_{\ell} (t,L_{\ell}))&-G (\rho_{r}(t,0), q_{r} (t,0))\\
 = -\frac 1 2 \kappa^3 &(\rho_{\ell}(t,L_{\ell})-\rho_{r}(t,0))^4\frac{\rho_{r}(t,0)+\rho_{\ell}(t,L_{\ell})}{(\rho_{r}(t,0))^2(\rho_{\ell}(t,L_{\ell}))^2}\\
&
+ \frac{p_{0} \gamma}{\gamma-1} \kappa (\rho_{\ell}(t,L_{\ell})-\rho_{r}(t,0))\left((\rho_{\ell}(t,L_{\ell}))^{\gamma-1}-(\rho_{r}(t,0))^{\gamma-1}  \right).
\end{aligned}
\end{equation*}

%\begin{equation*}
%-G (\rho_{r}^*, q_{r}^*)+G (\rho_{\ell}^*, q_{\ell}^*)= -\frac 1 2 \kappa^3 (\rho_{\ell}^*-\rho_{r}^*)^4\frac{\rho_{r}^*+\rho_{\ell}^*}{(\rho_{r}^*)^2(\rho_{\ell}^*)^2}
%+ \frac{p_{0} \gamma}{\gamma-1} \kappa (\rho_{\ell}^*-\rho_{r}^*)\left((\rho_{\ell}^*)^{\gamma-1}-(\rho_{r}^*)^{\gamma-1}  \right),
%\end{equation*}
The first term on the right hand-side is negative whereas the second one is positive. 
We remark that as long as the difference $\rho_{\ell}(t,L_{\ell})-\rho_{r}(t,0)$ is small, 
\begin{equation*}
\Delta G(t)\sim  \frac{p_{0} \gamma}{\gamma-1} \kappa (\rho_{\ell}(t,L_{\ell})-\rho_{r}(t,0))\left((\rho_{\ell}(t,L_{\ell}))^{\gamma-1}-(\rho_{r}(t,0))^{\gamma-1}  \right) \geq 0
\end{equation*}
and the dissipation entropy property holds, 
whereas as the difference $\rho_{\ell}(t,L_{\ell})-\rho_{r}(t,0)$ becomes large, we have
\begin{equation*}
\Delta G(t)\sim -\frac 1 2 \kappa^3 (\rho_{\ell}(t,L_{\ell})-\rho_{r}(t,0))^4\frac{\rho_{r}(t,0)+\rho_{\ell}(t,L_{\ell})}{(\rho_{r}(t,0))^2(\rho_{\ell}(t,L_{\ell}))^2} \leq 0,
\end{equation*}
and then, a priori, the dissipation property is no longer true.
In Section \ref{NumericalTests} we will test this dissipation property more closely, for various initial data, since in some cases the dissipation inside the arcs can compensate the growth of the entropy at the junction. 




\section{The Riemann problem at the junction - the case of a 2-arc network } \label{RIJunctionCondition}

We want to solve the Riemann problem for \eqref{GasDynamicLeft}--\eqref{jc} at the junction using the classical approach with  Riemann invariants. 

\subsection{The Riemann problem on a single interval} 
Let us first describe Riemann invariants on an interval before generalizing it to the junction case, see for example \cite{Dafermos} for more details. 

Let consider isentropic gas dynamics given by Eq.\eqref{GasDynamic} on a single arc, under the form
 \begin{equation}\label{eq:GenSys}
\partial_{t} U+\partial_{x}F(U)=0 , 
\end{equation}
where $U \in \R^2$ is the vector of unknowns 
$\ds
U=\left( \begin{array}{c}  \rho \\ q=\rho u\end{array}\right)$,
and the function $F : \R^2 \to \R^2$ is the flux of the system defined by
$\ds F(U)=\left( \begin{array}{c}  \rho u \\  \rho u^2 +p(\rho)\end{array}\right).
$


The eigenvalues of the system are
\begin{equation*}%\label{eq:eigPsys}
\mu_1(\rho,q) = \frac{q}{\rho}-\sqrt{p^\prime(\rho)}, \quad \mu_2(\rho,q) = \frac{q}{\rho}+\sqrt{p^\prime(\rho)},
\end{equation*}
where $q=\rho\,u$, and the eigenvectors are
\begin{equation*}%\label{eq:evPsys}
r_1(\rho,q) = \left(\begin{array}{c}
\rho \\ q-\rho\sqrt{p^\prime(\rho)}
\end{array}\right), \quad 
r_2(\rho,q) = \left(\begin{array}{c}
\rho \\ q+\rho\sqrt{p^\prime(\rho)}
\end{array}\right).
\end{equation*}
The system is strictly hyperbolic in $\mathcal{D}=\{(\rho,q) : \rho> 0 \mbox{ or } q=0\}$ with $\mu_1<\mu_2$. It is genuinely nonlinear in both characteristic fields, i.e. $\nabla\mu_i \cdot r_i \neq 0$, i=1,2.
The two functions $z_1 = z_1(\rho, q)$, $z_2 = z_2(\rho, q)$ 
are called the \textit{Riemann invariants} of system \eqref{GasDynamic} corresponding to $\mu_1$ and $\mu_2$ if they satisfy the equations
\begin{equation}\label{eq:gasRiemannInv}
\nabla z_i \cdot r_i = 0, \quad i=1,2.
\end{equation}
One solution of \eqref{eq:gasRiemannInv}, when $p$ follows the pressure law of isentropic gases \eqref{eq:pfunct} is
\begin{equation}\label{eq:solRinv}
z_1(\rho, q) = \frac{q}{\rho} + \alpha_\gamma \sqrt{p^\prime(\rho)} , \quad z_2(\rho, q) = \frac{q}{\rho} - \alpha_\gamma\sqrt{p^\prime(\rho)}, \quad  \text{ with }\alpha_\gamma = \frac{2}{\gamma-1}.
\end{equation}

Consider now the Riemann problem for \eqref{eq:GenSys}, that is to say system \eqref{eq:GenSys}   complemented with piecewise constant initial data such that 
\begin{align*}
U(x,0) = \left\{\begin{array}{lcl}
U^- &\mbox{if}& x< 0,
\\
U^+ &\mbox{if}& x> 0,
\end{array}\right.
\end{align*}
for two given constant left and right states $U^-=(\rho^-,q^-)$ and $U^+=(\rho^+,q^+)$.
The solution to the Riemann problem is then explicitly known and defined by an intermediate state $\hat U = (\hat\rho,\hat q)$ verifying the following conditions:
\begin{itemize}
\item[i)] The left state $U^-$ is connected to $\hat U$ by a 1-shock or a 1-rarefaction wave such that
$$z_1(\rho^-,q^-) = z_1(\hat\rho,\hat q).$$
Moreover, shock waves satisfy $\mu_1(U^-)> \mu_1(\hat U)$ (Lax admissibility condition) while rarefaction waves satisfy $\mu_1(U^-)< \mu_1(\hat U)$. We then have a 1-shock if $\hat \rho > \rho^-$ and $z_1(\rho^-,q^-) = z_1(\hat\rho,\hat q)$ or a 1-rarefaction if $\hat\rho < \rho^-$ and $z_1(\rho^-,q^-) = z_1(\hat\rho,\hat q)$.
\item[ii)] The intermediate state $\hat U$ is connected to the right state $U^+$ by a 2-shock 
if $\hat\rho > \rho^+$ and $z_2(\hat\rho,\hat q) = z_2(\rho^+,q^+)$ or by a 2-rarefaction if $\hat\rho < \rho^+$ and $z_2(\hat\rho,\hat q) = z_2(\rho^+,q^+)$.
\end{itemize}

The intermediate state $\hat U$ is then uniquely defined if, in the $(\rho,u)$-plane, the following two curves $u_1(\rho)= u^- + \alpha_\gamma \left(\sqrt{p^\prime(\rho^-)} - \sqrt{p^\prime(\rho)}\right)$ and $u_2(\rho)= u^+ - \alpha_\gamma \left(\sqrt{p^\prime(\rho^+)}-\sqrt{p^\prime(\rho)}\right)$ intersect. Since $u_1(\rho)$ is strictly decreasing, unbounded, and starts at $u^- + \alpha_\gamma \sqrt{p^\prime(\rho^-)}$ and $u_2(\rho)$ is strictly increasing, unbounded, with minimum $u^+ - \alpha_\gamma \sqrt{p^\prime(\rho^+)}$, the Riemann problem has a unique solution in the region where
\begin{equation*}%\label{eq:condRP}
u^- + \alpha_\gamma \sqrt{p^\prime(\rho^-)} \geq u^+ - \alpha_\gamma \sqrt{p^\prime(\rho^+)}
\end{equation*}
or equivalently
\begin{equation}\label{eq:condRP}
z_1(\rho^-,q^-) \geq z_2(\rho^+,q^+).
\end{equation}


Furthermore, we say that a state $(\rho,q)\in\mathcal{D}\backslash\{(0,0)\}$ is \emph{subsonic} if $\mu_1(\rho,q) < 0 <\mu_2(\rho,q)$, \emph{sonic} if $\mu_1(\rho,q) =0$ or $ \mu_2(\rho,q) = 0$ and \emph{supersonic} if $\mu_1(\rho,q) < \mu_2(\rho,q)<0 \mbox{ or } 0 <\mu_1(\rho,q) < \mu_2(\rho,q)$.


