\subsection{Two-node Linear Gaussian Models}
\label{appendix:LCN}
The data generation details for the two-node linear Gaussian experiments from \cref{sec:two_linear_gaussian} and the derivations of the posterior interventional distribution are explained in this section.


We examine the basic scenario involving $n$ independent and identically distributed (i.i.d.) random vectors, each consisting of two components, defined as $X^{i} := [X^{i}_1, X^{i}_2]^T$ for $i \in \{1, 2, \ldots, n\}$. Let the observed dataset be denoted by $\obsdata := \{X^{1}, X^{2}, \ldots, X^{n}\}$. For the sake of notational simplicity, we drop the subscript $\operatorname{BCM}$ from $p_{\operatorname{BCM}}$ in \cref{eq:BCM_def} throughout the subsequent proofs. In this setting, where the random vectors are composed of only two nodes $(X_1, X_2)$, there exist three distinct possible structural SCMs:


\begin{equation}
        \mathcal{G}_1 := \begin{bmatrix}
  0 & 0 \\
  1 & 0
\end{bmatrix}:X_1 = wX_2 + U_1 \text{ and } X_2 = U_2
\label{eq:model_1_ident}
\end{equation}

\begin{equation}
        \mathcal{G}_2 := \begin{bmatrix}
  0 & 1 \\
  0 & 0
\end{bmatrix}:X_1 = U_1 \text{ and } X_2 = wX_1 + U_2
\label{eq:model_2_ident}
\end{equation}

\begin{equation}
        \mathcal{G}_3 := \begin{bmatrix}
  0 & 0 \\
  0 & 0
\end{bmatrix}: X_1 = U_1 \text{ and } X_2 = U_2
\label{eq:model_3_ident}
\end{equation}

We consider two models, one where the causal graph is identifiable (\cref{appendix:LCN_ident}) and one where it is not identifiable (\cref{appendix:LCN_nonident}).



\subsubsection{Identifiable Case}
\label{appendix:LCN_ident}
 We begin with the case where the error terms $U_1$ and $U_2$ are Gaussian distributed and the noise variances of \( U_1 \) and \( U_2 \) are equal and known---a setting shown to be identifiable in \citet{Peters_2013_equal_vars}. Fixing \( \sigma^2, \sigma_w^2 \in \mathbb{R}^+ \), we consider the following hierarchical model:


\begin{align*}
    \mathcal{G} \sim \mathcal{U}\{\mathcal{G}_1, \mathcal{G}_2 &, \mathcal{G}_3\}, \quad  U_{i} \sim \mathcal{N}(0, \sigma^2) \quad \text{for } i = 1,2 \\
    w &\sim \mathcal{N}(0, \sigma_w^2) \quad \text{if} \quad \mathcal{G} \in \{\mathcal{G}_1, \mathcal{G}_2\}.
\end{align*}

which induces the following joint distribution:

\begin{equation}
    p(X, w, \calG) = p(X|w, \calG)p(w|\calG)p(\calG)  \text{   if } \calG \in\{\calG_1, \calG_2\} \text{ or }
    \label{eq:joint_distr_1}
\end{equation}

\begin{equation}
    p(X, \calG_3) = p(X| \calG_3)p(\calG_3), \quad \text{otherwise}.
    \label{eq:joint_distr_2}
\end{equation}


We show below that the above models can be identified by the posterior.
\begin{theorem}
    Let $\obsdata := \{X^{(1)}, X^{(2)}, \ldots ,X^{(n)}\}$ be i.i.d. observations generated by one of the simple models described in \crefrange{eq:model_1_ident}{eq:model_3_ident}. The posterior over the graphs $[p(\calG_1|\obsdata), p(\calG_2|\obsdata), p(\calG_3|\obsdata)] $ is 

\begin{equation*}
    \frac{1}{c}\Bigg[\frac{\sigma}{\sqrt{(\sigma_w^2S_2 +\sigma^2)}}\exp\Bigg(\frac{\sigma_w^2}{2\sigma^2} \frac{S_{12}^2}{\sigma_w^2S_2 +\sigma^2} \Bigg) , \frac{\sigma}{\sqrt{(\sigma_w^2S_1 +\sigma^2)}}\exp\Bigg(\frac{\sigma_w^2}{2\sigma^2} \frac{S_{12}^2}{\sigma_w^2S_1 +\sigma^2} \Bigg) , 1  \Bigg],
\end{equation*}
where $c$ is a constant of normalisation and 
\begin{equation}
    S_{12} := \sum_{i=1}^nX_1^{i}X_2^{i}, \quad S_1 :=  \sum_{i=1}X_1^{i2}, \quad S_2 := \sum_{i=1}X_2^{i2}.
    \label{eq:s_defs}
\end{equation}

The posterior interventional distribution is a mixture of 2 Gaussian distributions

\begin{align}
     \notag p(X_1= y|\opdo(X_2 = x), \obsdata) &= p(\calG_1|\obsdata) \mathcal{N} \Big(y|\mu_{1-2}(x),\sigma_{1-2}^2(x)\Big)+ (1-p(\calG_1|\obsdata))\mathcal{N}(y|0, \sigma^2),
    \label{eq:linear_intv_distr1}
\end{align}  
with
\begin{equation}
    \mu_{1-2}(x) := \frac{\sigma_w^2S_{12}}{\sigma_w^2S_2+\sigma^2}\cdot x \quad \text{and}\quad \sigma_{1-2}^2(x):= \sigma^2\Bigg(1+  \frac{\sigma_w^2x^2}{\sigma_w^2S_2+\sigma^2}\Bigg).
    \label{eq:mean_var_ident_1-2}
\end{equation}

\end{theorem}

{\bf Proof:}
First, we find the full conditional distribution, $p(w|\mathcal{G}, \obsdata)$ and the posterior distribution over the DAG models, $p(\mathcal{G}|\obsdata)$. Following Bayes' rule we have

\begin{align*}
    p(w|\calG_1,\obsdata) &\propto p(w|\calG_1) p(\calG_1)\prod_{i=1}^n p(X_i|\calG_1, w) \propto p(w|\calG_1)\prod_{i=1}^n p(X_i|\calG_1, w)  \\
    &\propto \exp\Bigg(-\frac{w^2}{2\sigma_w^2}-\frac{1}{2\sigma^2}\sum_{i=1}^n \Big(X_1^{i} -wX_2^{i}\Big)^2 \Bigg)
\end{align*}
and by completing the square we obtain 

\begin{equation}
    p(w|\calG_1,\obsdata) = \mathcal{N}\Bigg(w\Bigg| \frac{\sigma^2S_{12}}{\sigma_w^2S_2+\sigma_1^2}, \frac{\sigma_1^2\sigma_w^2}{\sigma_w^2S_2+\sigma_1^2}\Bigg),
    \label{eq:full_cond_distr1}
\end{equation}
with $S_{12}$ and $S_2$ being defined in \cref{eq:s_defs}.




Similarly, conditioned on the $\calG_2$ model, the full conditional distribution is again Gaussian

\begin{equation}
    p(w|\calG_2,\obsdata) = \mathcal{N}\Bigg(w\Bigg| \frac{\sigma^2S_{12}}{\sigma_w^2S_1+\sigma^2}, \frac{\sigma^2\sigma_w^2}{\sigma_w^2S_1+\sigma^2}\Bigg).
    \label{eq:full_cond_distr2}
\end{equation}
Using \cref{eq:full_cond_distr1} and \cref{eq:full_cond_distr2}, the posterior for the $\calG$ is 

\begin{align}
\notag p(\calG_1|\obsdata) &\propto \int p(w) p(\calG_1)\prod_{i=1}^n p(X^{i}|\calG_1, w)  dw \\
&\propto \exp \Bigg(-\frac{S_1+S_2}{2\sigma^2}\Bigg) \frac{\sigma}{\sqrt{(\sigma_w^2S_2 +\sigma^2)}}\exp\Bigg(\frac{\sigma_w^2}{2\sigma^2} \frac{S_{12}^2}{\sigma_w^2S_2 +\sigma^2} \Bigg) \label{eq:linear_post_graph1}\\
\notag p(\calG_2|\obsdata) &\propto \int p(w) p(\calG_2)\prod_{i=1}^n p(X_i|\calG_2, w)  dw\\
&\propto \exp \Bigg(-\frac{S_1+S_2}{2\sigma^2}\Bigg)\frac{\sigma}{\sqrt{(\sigma_w^2S_1 +\sigma^2)}}\exp\Bigg(\frac{\sigma_w^2}{2\sigma^2} \frac{S_{12}^2}{\sigma_w^2S_1 +\sigma^2} \Bigg) \label{eq:linear_post_graph2}\\
p(\calG_3|\obsdata) &\propto p(\calG_3)\prod_{i=1}^n p(X_i|\calG_3) \propto \exp \Bigg(-\frac{S_1+S_2}{2\sigma^2}\Bigg) \label{eq:linear_post_graph3}.
\end{align}
Next, the posterior interventional distribution is 

\begin{align*}
    &p(X_{1}|\opdo(X_2 = x), \obsdata) = p(X_1, \calG_3|\opdo(x), \obsdata) + \sum_{\calG \in \{\calG_1, \calG_2\}} \int p(X_1, \calG, w|\opdo(x), \obsdata) dw \\
    & = p(X_1|\opdo(x), \calG_3, \obsdata) p(\calG_3|\obsdata)+\sum_{\calG\in \{\calG_1, \calG_2\}} p(\calG|\obsdata) \int p(X_1|\opdo(x), \calG, w) p(w|\calG, \obsdata) dw.
\end{align*}
Conditioned on the model graphs, the interventional distributions are

\begin{align*}
    p(X_1 = y|\opdo(X_2 = x), \calG_1, w) = \mathcal{N}(y|wx, \sigma^2), \quad p(X_1&= y|\opdo(X_2 = x), \calG_2, w) = \mathcal{N}(y|0, \sigma^2)\\
    p(X_1= y|\opdo(X_2 = x), \calG_3) &= \mathcal{N}(y|0, \sigma^2).
\end{align*}
Then, we have
\begin{equation*}
    \int p(X_1 = y|\opdo(X_2 = x), \calG_2, w) p(w|\calG_2, \obsdata) dw = \int \mathcal{N}(y|0, \sigma^2)p(w|\calG_2, \obsdata) dw = \mathcal{N}(y|0, \sigma^2),
\end{equation*}

\begin{equation*}
    \int p(X_1 = y|\opdo(X_2 = x), \calG_3, w) p(w|\calG_3, \obsdata) dw = \int \mathcal{N}(y|0, \sigma^2)p(w|\calG_3, \obsdata) dw = \mathcal{N}(y|0, \sigma^2),
\end{equation*}

and
\begin{align*}
    \int p(X_1 &= y|\opdo(X_2 = x), \calG_1, w) p(w|\calG_1, \obsdata) dw = \int \mathcal{N}(y|wx, \sigma^2)p(w|\calG_1, \obsdata) dw \\
    &=\mathcal{N}\Bigg(y\Bigg|\frac{\sigma_w^2S_{12}}{\sigma_w^2S_2+\sigma^2}\cdot x, \sigma^2\Bigg(1+  \frac{\sigma_w^2x^2}{\sigma_w^2S_2+\sigma^2} \Bigg)\Bigg).
\end{align*}
Hence, the interventional distribution is simply a mixture of 2 Gaussian distributions

\begin{align}
     \notag p(X_1= y|\opdo(X_2 = x), \obsdata) &= p(\calG_1|\obsdata) \mathcal{N} \Big(y|\mu_{1-2}(x),\sigma_{1-2}^2(x)\Big)+ (1-p(\calG_1|\obsdata))\mathcal{N}(y|0, \sigma^2),
    \label{eq:linear_intv_distr1}
\end{align}  
with $p(\calG_1|\obsdata)$ calculated in \crefrange{eq:linear_post_graph1}{eq:linear_post_graph3} and $\mu_{1-2}(x), \sigma_{1-2}^2(x)$ defined in \cref{eq:mean_var_ident_1-2}.

Similarly, the next result easily follows 

\begin{align}
     \notag p(X_2= y|\opdo(X_1 = x), \obsdata) &= p(\calG_2|\obsdata) \mathcal{N} \Big(y|\mu_{2-1}(x), \sigma_{2-1}^2(x)\Big)+ (1-p(\calG_2|\obsdata))\mathcal{N}(y|0, \sigma^2),
\end{align}  
with $p(\calG_2|\obsdata)$ calculated in \cref{eq:linear_post_graph2} and 

\begin{equation*}
    \mu_{2-1}(x) := \frac{\sigma_w^2S_{12}}{\sigma_w^2S_1+\sigma^2}\cdot x \quad \text{and}\quad \sigma_{2-1}^2(x):= \sigma^2\Bigg(1+  \frac{\sigma_w^2x^2}{\sigma_w^2S_1+\sigma^2}\Bigg).
\end{equation*}
\qed

{\bf Remark:} It can be shown that if $\obsdata$ is generated by one of the models presented in \crefrange{eq:model_1_ident}{eq:model_3_ident}, then the posterior distribution $p(\mathcal{G} \mid \obsdata)$ asymptotically concentrates around the true data-generating structure $\mathcal{G}^*$ \citep{chickering2002optimal, walker2004modern, dhir2024continuous}. Consequently, in the infinite data limit, the posterior interventional distribution converges to a Gaussian distribution whose mean and variance depend on the intervened node and the true underlying causal mechanism $\mathcal{G}^*$.

\subsubsection{ Non-identifiable Case}
\label{appendix:LCN_nonident}
Second, we consider the errors' variances to be unknown while keeping the same SCMs described in \crefrange{eq:model_1_ident}{eq:model_3_ident}. Therefore, we place priors on these extra parameters as well chosen such that the model is not identifiable \citep{geiger2002parameter}.  We propose the following hierarchical model for fixed $\alpha>\frac{1}{2},$ and $\beta, \eta >0$


\begin{align*}
    &\hspace{5cm}\mathcal{G} \sim \mathcal{U}\{\mathcal{G}_1, \mathcal{G}_2, \mathcal{G}_3\}\\
    \text{If } &\calG =\calG_1, \text{ then } \tau_1^2\sim InvGamma(\alpha, \beta), \tau_2^2\sim InvGamma(\alpha-\frac{1}{2}, \beta), w\sim\mathcal{N}(0, \eta\tau_1^2)\\
    \text{If } &\calG =\calG_2, \text{ then } \tau_1^2\sim InvGamma(\alpha-\frac{1}{2}, \beta), \tau_2^2\sim InvGamma(\alpha, \beta), w\sim\mathcal{N}(0, \eta\tau_2^2)\\
    \text{If } &\calG =\calG_3, \text{ then } \tau_1^2\sim InvGamma(\alpha-\frac{1}{2}, \beta), \tau_2^2\sim InvGamma(\alpha, \beta).
\end{align*}
Then, this hierarchical model introduces the following joint distributions
\begin{align*}
    \text{If } &\calG =\calG_1, \text{ then } p(X, w, \tau_1^2, \tau_2^2, \calG_1) = p(X|w, \tau_1^2, \tau_2^2, \calG_1)p(w|\calG_1,\tau_1^2)p(\tau_2^2)p(\calG_1)\\
    \text{If } &\calG =\calG_2, \text{ then } p(X, w, \tau_1^2, \tau_2^2, \calG_2) = p(X|w, \tau_1^2, \tau_2^2, \calG_2)p(w|\calG_2, \tau_2^2)p(\tau_1^2)p(\calG_2)\\
    \text{If } &\calG =\calG_3, \text{ then } p(X, \tau_1^2, \tau_2^2, \calG_3) = p(X| \tau_1^2, \tau_2^2, \calG_3)p(\tau_1^2)p(\tau_2^2)p(\calG_3).
\end{align*}

For completeness, we show below that the above priors result in the same posterior for graphs in the same Markov equivalence class --- \(\gG_1\) and \(\gG_2 \).
We begin by recalling a simple result before stating the main theorem of this subsection.
\begin{lemma} 
\label{lemma:gamma_int}
For any $\nu >0$ and $A, B, C \in \mathbb{R}$ such that $CA^2>B$ we have
$$\int_{-\infty}^{\infty} \frac{dx}{(A^2x^2-2Bx+C)^{\frac{\nu+1}{2}}} = \sqrt{\pi}\frac{\Gamma(\frac{\nu}{2})}{\Gamma(\frac{\nu+1}{2})}\times \frac{(A^2)^{\frac{\nu-1}{2}}}{(CA^2-B^2)^{\frac{\nu}{2}}},$$
where $\Gamma(\cdot)$ is the usual Gamma-function.
\end{lemma}
{\sc Proof:} Completing the square in the dominator we have

$$\int_{-\infty}^{\infty} \frac{dx}{(A^2x^2-2Bx+C)^{\frac{\nu+1}{2}}} = \Bigg(\frac{A^2}{CA^2-B^2}\Bigg)^{\frac{\nu+1}{2}} \int_{-\infty}^\infty \frac{dx}{\Bigg( \frac{A^4}{CA^2-B^2}\Big(x-\frac{B}{A^2}\Big)^2 +1 \Bigg)^{\frac{\nu+1}{2}}}.$$

Next, we recall the probability density function (pdf) of a shifted and scaled version of the standard student-t distribution (i.e. $Z = \mu+\sigma T,$ with $T\sim t(\nu)$)

$$f_Z(z) = \frac{\Gamma(\frac{\nu+1}{2})}{\Gamma(\frac{\nu}{2})\sqrt{\pi}}\Bigg( 1+\frac{1}{\nu} \Big(\frac{z-\mu}{\sigma^2} \Big)^2 \Bigg)^{-\frac{\nu+1}{2}}.$$

Then, matching the terms gives the desired result. \qed



\begin{theorem}
    Let $\obsdata := \{X^{(1)}, X^{(2)}, \ldots ,X^{(n)}\}$ be i.i.d. observations generated by one of the simple models described in \crefrange{eq:model_1_ident}{eq:model_3_ident}. The posterior over the graphs $[p(\calG_1|\obsdata), p(\calG_2|\obsdata), p(\calG_3|\obsdata)] $ is 

\begin{equation*}
    \frac{1}{c}\Bigg[ \frac{(S_2^\eta)^{(\nu -1)/2}}{(S_2^\beta)^{(\nu -1)/2} [S_1^\beta S_2^\eta -S_{12}^2]^{\nu/2} }, \frac{(S_1^{\eta})^{(\nu -1)/2}}{(S_1^\beta)^{(\nu -1)/2} [S_2^\beta S_1^\eta -S_{12}^2]^{\nu/2}}, \frac{1}{(S_1^\beta)^{(\nu-1)/2}(S_2^\beta)^{(\nu/2)}}\Bigg],
\end{equation*}
where $c$ is the constant of normalisation, $\nu := 2\alpha+n$ and 


\begin{equation}
    S_i^\eta := S_i+\frac{1}{\eta},\text{ } S_i^\beta :=S_i+2\beta \text{ for } i \in \{1, 2\},
    \label{eq:def_S_beta_eta}
\end{equation}

with $S_1, S_2$ and $S_{12}$ defined in \cref{eq:s_defs}. The posterior interventional distribution is a mixture of 2 shifted and scaled Student-t distributions

\begin{align*}
     p(X_1 = y|\opdo(X_2 = x), \obsdata) = p(\calG_1|\obsdata)t(\nu, \mu_{1-2}(x), \sigma_{1-2}(x))+(1-p(\calG_1|\obsdata))t\Bigg(\nu, 0, \sqrt{\frac{S_1^\beta}{\nu-1}}\Bigg)
    \label{eq:linear_intv_distr1_nonident}
\end{align*}  
with
\begin{equation}
    \mu_{1-2}(x) := \frac{xS_{12}}{S_2^\eta} \quad \text{and}\quad \sigma_{1-2}^2(x):= \frac{S_2^\eta(S_1^\beta S_2^{\eta}- S_{12}^2) + x^2(S_1^\beta S_2^\eta-S_{12}^2)}{(S_2^{\eta})^2\nu}.
    \label{eq:mean_var_ident_1-2}
\end{equation}

\end{theorem}

{\bf Proof:} Similar to the case presented in Appendix \ref{appendix:LCN_ident}, we start by deriving the posterior over the three models described above and use the same definitions from \cref{eq:s_defs}.

\begin{align}
    \label{eq:non_ident_post_graph1}
   \notag &p(\calG_1|\obsdata) \propto \int p(\obsdata|\calG_1, w, \tau_1^2, \tau_2^2) p(w|\tau_1^2)p(\tau_1^2)p(\tau_2^2)d(\tau_1^2)\text{ } \text{ } d(\tau_2^2)\text{ }dw \\
  \notag  & = \int \frac{1}{\Big(\sqrt{2\pi \tau_1^2}\Big)^n}\exp \Big(-\frac{1}{2\tau_1^2}\sum_{i=1}^n(X_1^{i}-wX_2^{i})^2 \Big) \frac{1}{\Big(\sqrt{2\pi \tau_2^2}\Big)^n}\exp \Big(-\frac{1}{2\tau_2^2}S_2 \Big) \frac{1}{\sqrt{2\pi\eta\tau_1^2}} \\
 \notag   &\times \exp\Big(-\frac{w^2}{2\eta\tau_1^2} \Big) \frac{\beta^{2\alpha-\frac{1}{2}}}{\Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} (\tau_1^2)^{-\alpha-1} \exp \Big(-\frac{\beta}{\tau_1^2} \Big) (\tau_2^2)^{-\alpha-1/2} \exp \Big(-\frac{\beta}{\tau_2^2} \Big)d(\tau_1^2) \text{ } d(\tau_2^2)\text{ }dw \\
\notag    &=
    \frac{1}{\sqrt{\eta}} \frac{1}{(2\pi)^{n+1/2}} \frac{\beta^{2\alpha-1/2}}{\Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} \frac{\Gamma(\alpha+\frac{n-1}{2})}{\Big( \beta + \frac{S_2}{2} \Big)^{(\nu-1)/2}} \int_{-\infty}^\infty \frac{\Gamma(\alpha+\frac{n+1}{2})}{\Big( \beta+ \frac{\sum_{i=1}^n(X_1^{i}-wX_2^{i})^2}{2} +\frac{w^2}{2\eta}   \Big)^{\alpha+\frac{n+1}{2}}} dw \\
\notag    & = \frac{(2\beta)^{2\alpha-\frac{1}{2}} \Gamma(\alpha+\frac{n-1}{2})\Gamma(\alpha+\frac{n}{2})}{\sqrt{\eta} \pi^n \Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} \cdot \frac{(1/\eta + S_2)^{(\nu-1)/2}}{(2\beta + S_2)^{(\nu-1)/2}} \cdot \frac{1}{[(2\beta+S_1)(1/\eta+S_2) - S_{12}^2]^{\alpha+n/2}}\\
   &= \frac{(2\beta)^{2\alpha-\frac{1}{2}} \Gamma(\alpha+\frac{n-1}{2})\Gamma(\alpha+\frac{n}{2})}{\sqrt{\eta} \pi^n \Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} \cdot \Big(\frac{ S_2^\eta}{S_2^\beta}\Big)^{(\nu-1)/2} \cdot \frac{1}{(S_1^\beta S_2^\eta - S_{12}^2)^{\nu/2}},
\end{align}

where in the last step we used the result of Lemma \ref{lemma:gamma_int}. We note that the conditions in the lemma are fulfilled as
\begin{equation}
  (2\beta+S_1)(1/\eta+S_2)>S_1S_2 \geq \Big(S_{12}\Big)^2,
  \label{eq:ineq1}
\end{equation}
where we used the fact that $\beta, \eta >0$ and the Cauchy-Schwartz inequality in the second step.

Similarly, we find the posterior for the second model, $\calG_2$

\begin{align}
    \label{eq:non_ident_post_graph2}
    \notag p(\calG_2|\obsdata) &\propto \frac{(2\beta)^{2\alpha-\frac{1}{2}} \Gamma(\alpha+\frac{n-1}{2})\Gamma(\alpha+\frac{n}{2})}{\sqrt{\eta} \pi^n \Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} \cdot \Big(\frac{ S_1^\eta}{S_1^\beta}\Big)^{(\nu-1)/2} \cdot \frac{1}{(S_2^\beta S_1^\eta - S_{12}^2)^{\nu/2}}
\end{align}
and for the third model, $\calG_3$

\begin{align}
    \notag p(\calG_3|\obsdata) &\propto \int p(\obsdata|\calG_3, \tau_1^2, \tau_2^2) p(\tau_1^2)p(\tau_2^2)d(\tau_1^2)\text{ } \text{ } d(\tau_2^2) \\
  \notag  & = \int \frac{1}{\Big(\sqrt{2\pi \tau_1^2}\Big)^n}\exp \Big(-\frac{1}{2\tau_1^2}S_1 \Big) \frac{1}{\Big(\sqrt{2\pi \tau_2^2}\Big)^n}\exp \Big(-\frac{1}{2\tau_2^2}S_2 \Big)\\
  &\times  \frac{\beta^{2\alpha-1/2}}{\Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} (\tau_1^2)^{-\alpha-1/2} \exp \Big(-\frac{\beta}{\tau_1^2} \Big) (\tau_2^2)^{-\alpha-1} \exp \Big(-\frac{\beta}{\tau_2^2} \Big)d(\tau_1^2)\text{ }d(\tau_2^2)\\
 & = \frac{(2\beta)^{2\alpha-1/2} \Gamma(\alpha+\frac{n-1}{2})\Gamma(\alpha+\frac{n}{2})}{ \pi^n \Gamma(\alpha)\Gamma(\alpha-\frac{1}{2})} \cdot \frac{1}{ (S_1^\beta)^{(\nu-1)/2}(S_2^\beta)^{\nu/2}}.
    \label{eq:non_ident_post_graph3}
\end{align}

Conditioned on the models, the interventional distributions are
\begin{align*}
    p(X_1 = y|\opdo(x), \calG_1, w, \tau_1^2):=p(X_1 = y|\opdo(X_2 = x), \calG_1, w, \tau_1^2) &= \mathcal{N}(y|wx, \tau_1^2),\\
    p(X_1= y|\opdo(x), \calG_2, w, \tau_1^2) = p(X_1= y|\opdo(X_2 = x), \calG_2, w, \tau_1^2) &= \mathcal{N}(y|0, \tau_1^2),\\
    p(X_1= y|\opdo(x), \calG_3, \tau_1^2) := p(X_1= y|\opdo(X_2 = x), \calG_3, \tau_1^2) &= \mathcal{N}(y|0, \tau_1^2).
\end{align*}
Then, the posterior interventional distribution, $p(X_1|\opdo( x), \obsdata)$, is 

\begin{align*}
     \sum_{\calG \in \{\calG_1, \calG_2 \}}& p(\calG|\obsdata)\int p(X_1 = y|\opdo{(x)} , \calG, w, \tau_1^2)  p(w,\tau_1^2, \tau_2^2|, \calG, \obsdata)\text{ }d(\tau_1^2)\text{ } d(\tau_2^2)\text{ } dw \\
    &+ p(\calG_3|\obsdata)\int p(X_1 = y|\opdo(x), \calG_3, \tau_1^2)  p(\tau_1^2, \tau_2^2|, \calG_3, \obsdata)\text{ }d(\tau_1^2)\text{ } d(\tau_2^2).
\end{align*}
First, we find the last term

\begin{align}
   \notag  &\int p(X_1 = y|\opdo(X_2 = x), \calG_3, \tau_1^2)  p(\tau_1^2, \tau_2^2|, \calG_3, \obsdata)\text{ }d(\tau_1^2)\text{ } d(\tau_2^2) \propto\\
 \notag   & \int \frac{1}{\sqrt{2\pi \tau_1^2}} \exp\Big(-\frac{y^2}{2\tau_1^2}\Big) p(\obsdata|\calG_3, \tau_1^2, \tau_2^2) p(\tau_1^2)p(\tau_2^2)d(\tau_1^2)\text{ } \text{ } d(\tau_2^2) \propto\\
    & \propto\frac{1}{(2\beta+S_1+y^2)^{\alpha+\frac{n-1}{2}}} \propto \frac{1}{(1+ \frac{y^2}{S_1^\beta})^{\alpha+\frac{n-1}{2}}},
    \label{eq:non_indent_interv2}
\end{align}
which is a scaled Student-t distribution with $\nu = 2\alpha+n$ degrees of freedom and $\sigma^2 =\frac{S_1^\beta}{\nu-1}$. Computing the next integral follows the same pattern presented in \cref{eq:non_ident_post_graph3}

\begin{align}
    \notag &\int p(X_1 = y|\opdo(X_2 = x), \calG_2, w, \tau_1^2)  p(w,\tau_1^2, \tau_2^2|, \calG_2, \obsdata)\text{ }d(\tau_1^2)\text{ } d(\tau_2^2)\text{ } dw \propto \\
    \notag &\int \frac{1}{\sqrt{2\pi \tau_1^2}} \exp\Big(-\frac{y^2}{2\tau_1^2}\Big) p(\obsdata|w, \tau_1^2, \tau_2^2) p(w|\tau_2^2) p(\tau_1^2) p(\tau_2^2) \text{ }d(\tau_1^2)\text{ } d(\tau_2^2)\text{ } dw \propto\\
     & \frac{(S_1 +\frac{1}{\eta})^{\alpha+\frac{n-1}{2}}}{(2\beta+S_1 +y^2)^{\alpha+\frac{n-1}{2}}}\cdot \frac{1}{\Big[ (2\beta+S_2)(S_1 +\frac{1}{\eta}) - (S_{12})^2\Big]}\propto\frac{1}{(1+ \frac{y^2}{S_1^\beta})^{\alpha+\frac{n-1}{2}}}, 
    \label{eq:non_indent_interv1}
\end{align}
which is again a scaled Student-t distribution with $\sigma^2 =\frac{S_1^\beta}{\nu-1}$ and $\nu$ degrees of freedom. Finally, using similar steps as in \cref{eq:non_ident_post_graph1}, the last term is 

\begin{align}
    \notag &\int p(X_1 = y|\opdo(X_2 = x), \calG_1, w, \tau_1^2)  p(w,\tau_1^2, \tau_2^2|, \calG_1, \obsdata)\text{ }d(\tau_1^2)\text{ } d(\tau_2^2)\text{ } dw \propto \\
    \notag &\int \frac{1}{\sqrt{2\pi \tau_1^2}} \exp\Big(-\frac{(y-wx)^2}{2\tau_1^2}\Big) p(\obsdata|w, \tau_1^2, \tau_2^2) p(w|\tau_1^2) p(\tau_1^2) fp\tau_2^2) \text{ }d(\tau_1^2)\text{ } d(\tau_2^2)\text{ } dw \propto\\
    &\frac{1}{\Big[ (S_2+x^2 +\frac{1}{\eta})(2\beta+S_1+y^2) -(S_{12}+xy)^2 \Big]^{\alpha+\frac{n}{2}}}, 
    \label{eq:intv_distr_1_final}
\end{align}

where the denominator is always bounded away from $0$ as in \cref{eq:ineq1}. By completing the square, we obtain another scaled and shifted student-t distribution with $\nu = 2\alpha+n$, $\mu_{1-2}(x)$ and $\sigma_{1-2}^2(x)$ defined in \cref{eq:mean_var_ident_1-2}. Then, combining \crefrange{eq:non_ident_post_graph1}{eq:intv_distr_1_final} we obtain the result.

Similarly, we show

$$p(X_2 = y|\opdo(x), \obsdata) = p(\calG_2|\obsdata)t(\nu, \mu_{2-1}(x), \sigma_{2-1}(x))+(1-p(\calG_2|\obsdata))t\Bigg(\nu, 0, \sqrt{\frac{S_2^\beta}{\nu-1}}\Bigg)
    \label{eq:linear_intv_distr1_nonident}$$
with
\begin{equation}
    \mu_{2-1}(x) := \frac{xS_{12}}{S_1^\eta} \quad \text{and}\quad \sigma_{2-1}^2(x):= \frac{S_1^\eta(S_2^\beta S_1^{\eta}- S_{12}^2) + x^2(S_2^\beta S_1^\eta-S_{12}^2)}{(S_1^{\eta})^2\nu}.
    \label{eq:mean_var_ident_1-2}
\end{equation}
\qed


\textbf{Remark:} We employ asymmetric priors for $\tau_1^2$ and $\tau_2^2$ to ensure that the posterior assigns equal probability to the models $\mathcal{G}_1$ and $\mathcal{G}_2$, which belong to the same Markov equivalence class. In particular, setting $2\beta = \eta$ results in $S_1^\eta = S_1^\beta$ and $S_2^\eta = S_2^\beta$, which implies that the posterior distribution over graphs,
\[
\big[p(\mathcal{G}_1 \mid \obsdata),\ p(\mathcal{G}_2 \mid \obsdata),\ p(\mathcal{G}_3 \mid \obsdata)\big],
\]
takes the form:

\begin{equation}
    \frac{1}{c} \left[ 
    \frac{1}{(S_1^\beta S_2^\beta - S_{12}^2)^{\nu/2}},\ 
    \frac{1}{(S_2^\beta S_1^\beta - S_{12}^2)^{\nu/2}},\ 
    \frac{1}{(S_1^\beta)^{(\nu - 1)/2}(S_2^\beta)^{\nu/2}} 
    \right],
    \label{eq:BGe_score}
\end{equation}
where $c$ is a normalising constant.


This setup corresponds to the prior structure proposed by \citet[Equation 12]{geiger2002parameter}, obtained by setting the precision matrix $T$ in the Wishart distribution to the identity. As noted in their \citet[Section 4]{geiger2002parameter}, a change of variables transforms the Wishart prior on the covariance of $X$ into the prior used here for the weights $w$ and error variances $\tau_1^2$ and $\tau_2^2$.

Assuming a true data-generating mechanism, the posterior concentrates on its Markov equivalence class. If the true graph is $\mathcal{G}_1$ or $\mathcal{G}_2$, then $p(\mathcal{G}_1|\obsdata) = p(\mathcal{G}_2|\obsdata) \to 1/2$. Conversely, if $\mathcal{G}_3$ is the true graph, then $p(\mathcal{G}_3|\obsdata) \to 1$\citep{chickering2002optimal, walker2004modern, dhir2024continuous}.

The degrees of freedom, $\nu = \alpha + n$, grow with the sample size $n$, so the corresponding Student-$t$ distributions converge to Gaussians in the large-sample regime.



\subsection{Three-node Experiments}

In the three-node experiments (\cref{sec:exp_3node}) we use two datasets with two different functional mechanisms $f_i(\cdot)$ as defined in \cref{eq:scm}: one sampled from a GP prior, and one based on neural networks. In both cases, we sample Erd\H{o}s--R\'enyi graphs  with graph degree chosen uniformly from $\{1, 2, 3\}$.
Following \citet{ormaniec2025standardizing}, we standardise all variables upon generation.

\paragraph{GP functional mechanism} To model $f_i(\cdot)$ we use a GP with a squared exponential kernel, with a randomly sampled lengthscale for each parent set $\mathrm{PA}_{i}$ of size $\lvert\mathrm{PA}_{i}\lvert$. More specifically, we sample the lengthscale from a log- distribution $\{\lambda_p\}_{p=1}^{\lvert\mathrm{PA}_{i}\lvert} \sim \text{Log}(-1, 1)$, followed by clipping between $\lambda_p = \text{clip}(\lambda_p, 0.1, 5)$ to ensure that a too long lengthscale does not result in independence of the variable from a parent. This defines the kernel matrix between the $n$-th and $m$-th samples as: 
\begin{align*}
    \mathbf{K}_{nm} = \exp(- (\mathrm{PA}^n_{i} - \mathrm{PA}^m_{i})^T\bm\Lambda^{-1}(\mathrm{PA}^n_{i} - \mathrm{PA}^m_{i})),
\end{align*}
with $\bm\Lambda := \mathrm{Diag}(\lambda_1, \ldots, \lambda_{\lvert\mathrm{PA}_{i}\lvert})$. We then add noise with variance $\sigma^2 \sim \mathrm{Gamma}(1, 5)$ and sample the variables as follows
\begin{align*}
    X_i \sim \mathcal{N}(\mathbf{0}, \mathbf{K} + \sigma^2\mathbf{I})
\end{align*}

\paragraph{Neural network-based functional mechanism} We sample each variable as follows
\begin{align*}
    \eta_i &\sim \mathcal{N}(0, 1)\\
    X^n_i &\sim \mathrm{ResNet}_{\theta}([\mathrm{PA}^n_{i}, \eta_i]) + \sigma \epsilon,
\end{align*}
where $\sigma^2 \sim \mathrm{Gamma}(1, 10)$, $\epsilon \sim \mathcal{N}(0, 1)$. $\mathrm{ResNet}_{\theta}$ is a residual neural network with a randomly sampled number of blocks $N_{\text{blocks}}\sim \mathcal{U}\{1, \ldots, 8\}$ and randomly sampled hidden dimension $d_{\text{hidden}} \sim \mathcal{U}\{2^5, 2^6, 2^7, 2^8\}$. We use the GELU \citep{gelu} activation function.



\subsection{Higher-dimensional experiments}
\label{app:data_gen_high_dim}

For the higher dimension experiments in \cref{sec:exp_higherdim}, we generate the training data for MACE-TNP as follows:
\begin{itemize}
    \item We sample number of variables \(D \sim \gU[5,40]\).
    \item We sample a type of graph, either an Erd\H{o}s--R\'enyi graph or a scale-free graph \citep{barabasi1999emergence}.
    \item The density of the graph (number of edges) is sampled from \(\gU \left[\frac{D}{2}, 6D \right]\).
    \item For each node, we sample a functional mechanism randomly from either a GP with an additional latent variable input, or a Neural network with an additional latent variable input:
    \begin{itemize}
        \item GP with latent: We sample  a latent \(\eta_i \sim \mathcal{N}(0, 1)\), and lengthscales \(\{\lambda_p\}_{p=1}^{\lvert\mathrm{PA}_{i}\lvert + 1} \sim \text{Log}(-0.5, 1)\), where \(\mathrm{PA}_i\) denotes the set of parents of node index \(i\). Functions are sampled from a squared expoenential kernel with \(\eta_i\) included as an input and Gaussian noise added with variance \(\sigma^2 \sim \mathrm{Gamma}(1,5)\).
        \item NN with latent: 
        \begin{align*}
    \eta_i &\sim \mathcal{N}(0, 1)\\
    X^n_i &\sim \mathrm{NN}_{\theta}([\mathrm{PA}^n_{i}, \eta_i]) + \sigma \epsilon,
        \end{align*}
        where $\sigma^2 \sim \mathrm{Gamma}(1, 10)$, $\epsilon \sim \mathcal{N}(0, 1)$.  \(\mathrm{NN}_{\theta}\) denotes a randomly initialised neural network with \(128\) hidden dimensions and one hidden layer.
\end{itemize}
\end{itemize}
Using a latent as an input ensures that the final distribution is not Gaussian.
Following \citet{ormaniec2025standardizing}, we standardise all variables during the data generation process. 

For testing for each variable size in \cref{tab:highdim-exp}, we only generate Erd\H{o}s--R\'enyi graphs with density \(4D\). 
This is to test the performance of the baselines and our method in the difficult dense graph case.
The rest of the data generation process is the same as the training data.
