	\centering
	\includegraphics[width=.8\linewidth]{figures/figure6.pdf}
	\caption{Analytical prediction for the local IEPR $\dot{\sigma}$ [Eq.~\eqref{loc_epr}] as a function of the distance $d$ between defects within a disc of radius $R$. (a)~Series of snapshots of $\dot{\sigma}$ for varous values of $d$. The colorbars are normalized by the maximum $\dot{\sigma}_{max}$ attained within the disc. (b)~The integrated IEPR $\dot{\cal S}_{R}$ [Eq.~\eqref{int_epr}] as a function of $d/R$. The blue dashed line is the sum of the IEPR for the isolated $+\frac{1}{2}$ and $-\frac{1}{2}$ defects in a disc of the same radius $R$.
	}
	\label{fig:epr_creation}
