\section{Stochastic dynamics of the stream function}\label{ap:stream_derivation}

To derive the stochastic dynamics of the stream function [Eq.~\ref{eq:stream_dynamics}], we apply the curl operator to the Stokes equation [Eq.~\ref{eq:stokes}]. The term that contains the gradient of pressure vanishes:
\begin{equation}\label{eq:pressure}
    \nabla \times (\nabla p)=0 ,
\end{equation}
and the viscous term gives
\begin{equation}
	\nabla \times (\eta \nabla^{2}\mathbf{v}) = -\eta\nabla^{4}\psi ,
\end{equation}
where $\nabla \times$ is the curl in 2 dimensions and we have used the fact that curl and Laplacian operators commute, and $\partial_{y}v_{x}-\partial_{x}v_{y} = \nabla^{2}\psi$ by definition of the stream function [Eq.~\eqref{eq:streamF}]. Defining the force $f$ as
\begin{equation}\label{eq:force}
	f_{\alpha} = \partial _{\beta}( \Sigma_{\alpha \beta}^{P} + \Sigma_{\alpha \beta}^{A}) = (\zeta+\kappa) \big[ (\delta_{\alpha \beta}/2) \partial _{\beta}(\partial_{\gamma\gamma}\phi)^{2}-\partial _{\beta}(\partial_{\alpha}\phi\partial_{\beta}\phi) \big] ,
\end{equation}
where we have used the definitions of $\Sigma_{\alpha \beta}^{P}$ and $\Sigma_{\alpha \beta}^{A}$ [Eq.~\eqref{eq:stress_tensor}], we get
\begin{equation}
\begin{aligned}
	\frac{f_{x}}{\kappa+\zeta} &= \frac{1}{2}\partial _{x} \left [(\partial_{y}\phi)^{2}-(\partial_{x}\phi)^{2} \right]-\partial _{y}\big[(\partial_{x}\phi)(\partial_{y}\phi) \big] ,
	\\
	\frac{f_{y}}{\kappa+\zeta} &= \frac{1}{2}\partial _{y}\left [(\partial_{x}\phi)^{2}-(\partial_{y}\phi)^{2} \right ] - \partial _{x} \big[(\partial_{x}\phi)(\partial_{y}\phi) \big] ,
\end{aligned}
\end{equation}
from which we deduce
\begin{equation}\label{eq:force_bis}
\begin{aligned}
	\frac{\partial_{x}f_{y} - \partial_{y}f_{x}}{\kappa+\zeta} &= (\partial_{x}\phi) \left[ -\partial_{x}(\partial_{xy}^{2}\phi)+\partial_{y}(\partial_{yy}^{2}\phi)+2\partial_{x}(\partial_{xy}^{2}\phi) \right] 
	\\
	&\quad +(\partial_{y}\phi) \left[ -\partial_{x}(\partial_{xx}^{2}\phi)+\partial_{yy}^{2}(\partial_{x}\phi)-2\partial_{x}(\partial_{yy}^{2}\phi) \right]
	\\
	&=	(\partial_{x}\phi)\nabla^{2}(\partial_{y}\phi) -(\partial_{y}\phi)\nabla^{2}(\partial_{x}\phi) .
\end{aligned}
\end{equation}
Applying the curl operator $\epsilon_{\alpha \alpha'}\partial_{\alpha'}$ to the noise term $\partial_\beta\Gamma_{\alpha \beta}$, where $\epsilon$ is the Levi-Civita matrix ($\epsilon_{xy}=-\epsilon_{yx}=1)$, the noise term $\Xi=\epsilon_{\alpha \alpha'}\partial_{\alpha'\beta}^{2}\Gamma_{\alpha \beta}$ has Gaussian statistics with zero mean and correlation given by 
\begin{equation}\label{eq:psi_noise}
\begin{aligned}
	\langle \Xi(\vb*{r},t) \Xi(\vb*{r}',t') \rangle &= \epsilon_{\alpha \alpha'} \epsilon_{\mu \mu'} \left ( \delta_{\alpha \mu}\delta_{\beta \nu} +\delta_{\alpha \nu} \delta_{\beta \mu} \right ) \partial_{\alpha'\beta \mu' \nu }^{4} \delta(\vb*{r}-\vb*{r}')\delta(t-t')
	\\
	&= \left ( \epsilon_{\alpha \alpha'} \epsilon_{\alpha \mu'} \partial_{\alpha' \mu' }^{2}\nabla^{2} + \epsilon_{\alpha \alpha'} \epsilon_{\mu \mu'}\partial_{\alpha \alpha'\mu \mu' }^{4} \right ) \delta(\vb*{r}-\vb*{r}')\delta(t-t')
	\\
	&= \nabla^{4}\delta(\vb*{r}-\vb*{r}')\delta(t-t') ,
	\end{aligned}
\end{equation}
where we have used the identities $\epsilon_{\alpha \alpha'}\epsilon_{\alpha \mu'}=\delta_{\alpha'\mu'}$ and $\epsilon_{\alpha \alpha'}\epsilon_{\mu \mu'}=\delta_{\alpha\mu}\delta_{\alpha'\mu'}-\delta_{\alpha\alpha'}\delta_{\mu\mu'}$. Therefore, combining Eqs.~(\ref{eq:pressure}-\ref{eq:psi_noise}), we deduce the stream dynamics in Eq.~\eqref{eq:stream_dynamics}.


