\section{Derivation of the informatic entropy production rate}\label{ap:derivation_epr}

To derive the informatic entropy production rate (IEPR) [Eq.~\eqref{eq:def_epr}], we start by writing the path probability for the forward $\mathcal{P} \left(\{\vb*{J},\psi\}_0^{t} \right)$ and backward $\mathcal{P}^{R} (\{\vb*{J},\psi\}_0^{t})$ paths:
\begin{equation}
	\mathcal{P} (\{\vb*{J},\psi\}_0 ^{\tau}) = \exp(-\mathcal{A}) ,
	\quad
	\mathcal{P}^{R} \left (\{\vb*{J},\psi\}_0 ^{\tau} \right ) = \exp(-\mathcal{A}^{R}) , 
\end{equation}
where the $(\mathcal{A},\mathcal{A}^R)$ are the corresponding dynamical actions, and the time-reversal operation is defined by 
\begin{equation}
	t \xrightarrow{} \tau-t ,
	\quad
	\phi^R(\vb*{r},t)=\phi(\vb*{r},\tau-t) ,
	\quad
	\psi^R(\vb*{r},t)=-\psi(\vb*{r},\tau-t) .
\end{equation}
Given that the noise realizations in the dynamics of the density field $\phi$ [Eq.~\eqref{eq:phi_dynamics}] and the stream field $\psi$ [Eq.~\eqref{eq:stream_dynamics}] are independent, we separate $(\mathcal{A},\mathcal{A}^R)$ as
\begin{equation}
	\mathcal{A} =  \int_0^\tau \mathrm{d}t \int \, \mathrm{d}\vb*{r} \left (\mathcal{A}_\phi +\mathcal{A}_\psi \right ) ,
	\quad
	\mathcal{A}^{R} = \int_0^\tau \mathrm{d}t \int \, \mathrm{d}\vb*{r} \left(\mathcal{A}^{R}_\phi +\mathcal{A}^{R}_\psi \right) ,
\end{equation}
where $(\mathcal{A}_\phi,\mathcal{A}_\phi^R)$ and $(\mathcal{A}_\psi,\mathcal{A}_\psi^R)$ are the contributions from the dynamics $\phi$ and $\psi$, respectively. The IEPR follows as
\begin{equation}\label{eq:epr_gen}
\begin{aligned}
	\dot{\mathcal{S}} &= \lim _{\tau  \to \infty} \frac{1}{\tau } \left ( \mathcal{A}^{R}-\mathcal{A} \right )
	\\
	&	=	\underbrace{ \lim_{\tau  \to \infty} \frac{1}{\tau } \int_0^\tau \mathrm{d}t \int \mathrm{d}\vb*{r}	\left (\mathcal{A}^{R}_\phi-\mathcal{A}_\phi \right ) }_{\dot{\mathcal{S}}_{\phi}} + \underbrace{	\lim_{\tau  \to \infty} \frac{1}{\tau } \int_0^\tau \mathrm{d}t \int \, \mathrm{d}\vb*{r} \left (\mathcal{A}^{R}_\psi-\mathcal{A}_\psi \right ) }_{\dot{\mathcal{S}}_{\psi}} .
\end{aligned}
\end{equation}
The expression for $\mathcal{A}_\psi$ reads~\cite{nardini_2017}
\begin{equation}\label{eq:L}
	\mathcal{A}_\psi = \frac{1}{4\eta T}\left [\nabla^{-2} \left (L-\eta \nabla ^{4} \psi \right ) \right ]^{2} ,
	\quad
	L = (\kappa+\zeta)[(\partial_x \phi)\nabla ^2 (\partial_y \phi)-(\partial_y \phi)\nabla ^2 (\partial_x \phi)] ,
\end{equation}
and $\mathcal{A}_\phi$ is given by
\begin{equation}\label{eq:a_phi}
	\mathcal{A}_\phi = \frac{1}{4MT}\left[\nabla ^{-1} \left(\dot{\phi}+\vb*{v} \cdot \nabla \phi +\nabla \cdot \vb*{J}_{d} \right) \right]^{2} ,
	\quad
	\vb*{J}_d = - M \nabla \frac{\delta\cal F}{\delta\phi} ,	
\end{equation}
from which we deduce
\begin{equation}
	\mathcal{A}^{R}_\psi = \frac{1}{4\eta T} \left [\nabla^{-2} \left (L + \eta \nabla^{4} \psi \right) \right ]^{2} ,
	\quad
	\mathcal{A}_\phi^R = \frac{1}{4MT}\left[\nabla ^{-1} \left(\dot{\phi}+\vb*{v} \cdot \nabla \phi - \nabla \cdot \vb*{J}_{d} \right)\right]^{2} ,
\end{equation}
yielding
\begin{equation}\label{eq:s_decomp}
	\dot{\cal S}_\psi = - \frac{1}{T} \int \langle L \psi \rangle \, \mathrm{d}\vb*{r} ,
	\quad 
	\dot {\cal S}_\phi = - \frac 1 T \int \left\langle \left(\dot{\phi}+ \vb*{v} \cdot \nabla \phi \right) \frac{\delta\cal F}{\delta\phi} \right\rangle \, \mathrm{d}\vb*{r} ,
\end{equation}
where we have used integration by parts. In the expression of $\dot{\cal S}_\phi$, we identify a vanishing boundary term:
\begin{equation}  
	\int \, \mathrm{d}\vb*{r} \left\langle \dot \phi \frac{\delta\cal F}{\delta\phi} \right\rangle = \left\langle \frac{\mathrm{d}\cal F}{\mathrm{d} t} \right\rangle = \underset{\tau\to\infty}{\lim} \frac{{\cal F}(\tau) - {\cal F}(0)}{\tau} = 0 .
\end{equation}
Using the definition $v_\alpha = \epsilon_{\alpha\beta}\partial_\beta\psi$ [Eq.~\eqref{eq:streamF}] and the expression of the free energy $\cal F$ [Eq.~\eqref{eq:free}], the remaining contribution to $\dot{\cal S}_\phi$ can be written as
\begin{equation}
\begin{aligned}
	T \dot{\cal S}_\phi &= \epsilon_{\alpha\beta} \int \langle (\partial_\beta \psi) (\partial_\alpha \phi) ( dg/d\phi - \kappa\nabla^2 \phi ) \rangle \,\mathrm{d}\vb*{r}
	\\
	&= \epsilon_{\alpha\beta} \int \langle (\partial_\beta \psi) (\partial_\alpha g - \kappa (\partial_\alpha \phi) \nabla^2 \phi ) \rangle \,\mathrm{d}\vb*{r}
	\\
	&= - \epsilon_{\alpha\beta} \int \langle \psi (\partial_\beta\partial_\alpha g - \kappa \partial_\beta( (\partial_\alpha \phi) \nabla^2 \phi ) ) \rangle \,\mathrm{d}\vb*{r} ,
\end{aligned}
\end{equation}
where we have integrated by parts. Given that $\epsilon_{\alpha\alpha} \partial_\alpha\partial_\beta h(\phi) =0$ for an arbitrary function $h$ (since $\epsilon_{\alpha\beta}=-\epsilon_{\alpha\beta}$), we deduce
\begin{equation}\label{eq:s_phi}
	T \dot{\cal S}_\phi = \kappa \epsilon_{\alpha\beta} \int \langle \psi (\partial_\alpha \phi) \nabla^2 (\partial_\beta \phi) \rangle \,\mathrm{d}\vb*{r} .
\end{equation}
Moreover, using the definition of $L=(\kappa+\zeta)\epsilon_{\alpha\beta}(\partial_\alpha\phi) \nabla^2(\partial_\beta \phi)$ [Eq.~\eqref{eq:L}] and $\dot{\cal S}_\psi $ [Eq.~\eqref{eq:s_decomp}], we find
\begin{equation}\label{eq:s_psi}
	T \dot{\cal S}_\psi = -(\zeta + \kappa) \epsilon_{\alpha\beta} \int 
    \langle  \psi (\partial_\alpha\phi) \nabla^2(\partial_\beta \phi)\rangle \, \mathrm{d}\vb*{r} .
\end{equation}
Comparing Eqs.~\eqref{eq:s_phi} and~\eqref{eq:s_psi}, we find $\dot{\cal S}_\phi = -\kappa(\zeta + \kappa)^{-1} \dot{\cal S}_\psi$, from which we deduce the total IEPR:
\begin{equation}
	T\dot{\cal S} = T (\dot{\cal S}_\phi + \dot{\cal S}_\psi) = \frac{\zeta}{\zeta+\kappa} \int \langle L \psi \rangle \,\mathrm{d} \vb*{r} .
\end{equation}
In the noiseless regime ($T\to0$), the dynamics of $\psi$  [Eq.~\eqref{eq:stream_dynamics}] reduces to $L=\eta \nabla^{4}\psi$, yielding
\begin{equation}
\label{eq:EPRderivation}
	T\dot{\cal S} = \frac{\eta \zeta}{\zeta+\kappa} \int \langle (\nabla^2\psi)^2 \rangle \, \mathrm{d} \vb*{r} ,
\end{equation}
which coincides with Eq.~\eqref{loc_epr}.


