\section{Derivation of the dissipation rate}\label{app:LIT}

To derive the relation between the dissipation rate $T\dot{\cal S}_{\rm tot}$ [Eq.~\eqref{eq:diss}] and IEPR $\dot{\cal S}$ [Eq.~\eqref{loc_epr}], we start by expressing $T\dot{\cal S}_{\rm tot}$ as the sum of products between fluxes and forces~\cite{Mazur}:
\begin{equation}\label{eq:EPRfluxforce}
	T\dot{\cal S}_\mathrm{tot} = \int ({\mathbb J}\cdot{\mathbb X}) \mathrm{d} \vb*{r} = \int \left[ -J_\alpha \partial_\alpha \frac{\delta\cal F}{\delta\phi} + v_{\alpha\beta} \left( \Sigma^\mathrm{tot}_{\alpha\beta}-\Sigma^\mathrm{P,tot}_{\alpha\beta}\right) + r \Delta\mu \right]  \mathrm{d} \vb*{r} ,
\end{equation}
where we have used the definitions of $({\mathbb X}, {\mathbb J})$ [Eq.~\eqref{eq:lit}]. Integrating by parts the first and second terms in Eq.~\eqref{eq:EPRfluxforce}, we deduce
\begin{equation}
\begin{aligned}
	T\dot{\cal S}_\mathrm{tot} &= \int \left[ (\partial_\alpha J_\alpha) \frac{\delta\cal F}{\delta\phi} + v_{\beta} \left( \partial_\alpha\Sigma^\mathrm{P,tot}_{\alpha\beta} - \partial_\alpha\Sigma^\mathrm{tot}_{\alpha\beta} \right) + r \Delta\mu  \right]  \mathrm{d} \vb*{r}
	\\
	&= \int \left[ - \frac{\delta\cal F}{\delta\phi} (\partial_t\phi + v_\alpha\partial_\alpha\phi) + v_{\beta}\partial_\alpha\Sigma^\mathrm{P,tot}_{\alpha\beta} + r \Delta\mu \right] \mathrm{d} \vb*{r} ,
\end{aligned}
\end{equation}
where we have used Eqs.~\eqref{eq:phi_dynamics} and~\eqref{eq:stokes_bis}. Using the following identity for the passive stress~\cite{Cates2025}
\begin{equation}
	\phi\,\partial_\alpha\frac{\delta\cal F}{\delta\phi} = - \partial_\alpha\Sigma^\mathrm{P,tot}_{\alpha\beta} ,
\end{equation}
together with
\begin{equation}
	\int \frac{\delta \mathcal{F}}{\delta\phi} \, \partial_t\phi\, \mathrm{d} \vb*{r} = - \frac{\mathrm{d}\mathcal{F}}{\mathrm{d}t} ,
	\quad
	\partial_\alpha v_\alpha = 0 ,
\end{equation}
we then deduce
\begin{equation}\label{eq:EPRsplit}
	T\dot{\cal S}_\mathrm{tot} = - \frac{\mathrm{d}\mathcal{F}}{\mathrm{d}t}  + \int  ( r \Delta\mu ) \mathrm{d} \vb*{r} .
\end{equation}
As mentioned in the main text, the term $\mathrm{d}\mathcal{F}/\mathrm{d}t$ vanishes in steady state. Combining the definitions of the chemical rate $r$ [Eq.~\eqref{eq:r}] and of the determinant of the Onsager matrix $\det\mathbb L$ [Eq.~\eqref{eq:det}], we obtain
\begin{equation}\label{eq:rDmu}
	\int (r\Delta\mu) {\rm d}\vb*{r} = \frac{(2\eta)^4\Delta\mu ^2}{M}\int ( \det\mathbb{L} )\mathrm{d} \vb*{r} - \int v_{\alpha\beta} \Sigma_{\alpha\beta}^A {\rm d}\vb*{r} .
\end{equation}
Using the definition $v_\alpha = \epsilon_{\alpha\beta}\partial_\beta\psi$ [Eq.~\eqref{eq:streamF}] and integrating by parts, we write the last term in Eq.~\eqref{eq:rDmu} as follows:
\begin{equation}\label{eq:vS}
	\int v_{\alpha\beta}\Sigma_{\alpha\beta}^A \mathrm{d}\vb*{r} = \int \epsilon_{\beta\gamma}\partial_\alpha\partial_\gamma \psi \Sigma_{\alpha\beta}^A \mathrm{d}\vb*{r} = \int \psi\,\epsilon_{\beta\gamma}\partial_\alpha\partial_\gamma  \Sigma_{\alpha\beta}^A \mathrm{d}\vb*{r} .
\end{equation}
Finally, using $\Sigma_{\alpha\beta}=\Sigma_{\alpha\beta}^P+\Sigma_{\alpha\beta}^A$ and Eq.~\eqref{eq:stress_tensor}, we can rewrite the dynamics of $\psi$ [Eq.~\eqref{eq:stream_dynamics}] in terms of the active stress:
\begin{equation}\label{eq:stokes2}
	\eta \nabla^4 \psi = - \epsilon_{\beta\gamma} \frac{\kappa+\zeta}{\zeta}\partial_\alpha\partial_\gamma \Sigma_{\alpha\beta}^A .
\end{equation}
Substituting Eq.~\eqref{eq:stokes2} into Eq.~\eqref{eq:vS}, we find that Eq.~\eqref{eq:vS} is identical to the IEPR of AMH:
\begin{equation}\label{eq:connectionIEPR}
	\int v_{\alpha\beta}\Sigma_{\alpha\beta}^A \mathrm{d}\vb*{r} = \frac{\eta\zeta}{\kappa+\zeta} \int (\psi\, \nabla^4\psi) \mathrm{d}\vb*{r} = \frac{\eta\zeta}{\kappa+\zeta} \int (\nabla^2 \psi)^2  \mathrm{d}\vb*{r} = T\dot{\cal S} \, ,
\end{equation}
where we have identified the expression of IEPR $\dot{\cal S}$ [Eq.~\eqref{loc_epr}]. Finally, substituting the relations from Eqs.~\eqref{eq:rDmu} and~\eqref{eq:connectionIEPR} into Eq.~\eqref{eq:EPRsplit}, we obtain the connection between the steady-state dissipation $T\dot{\cal S}_{\rm tot}^{\,(\mathrm{ss})}$ and $\dot{\cal S}$ in Eq.~\eqref{eq:EPRsplit2Main}. Last, we note that combining the definition of $\det\mathbb L$ [Eq.~\eqref{eq:det}] with the following relation
\begin{equation}
	\tilde{\Sigma}^A_{\alpha\beta}\tilde{\Sigma}^A_{\alpha\beta} = \frac{\zeta^2}{2\Delta\mu^2}|\nabla\phi|^4 ,
\end{equation}
we can simplify Eq.~\eqref{eq:EPRsplit2Main} as
\begin{equation}\label{eq:resEPR}
	T ( \dot{\cal S}_\mathrm{tot}^{\,(\mathrm{ss})} - \dot{\cal S} ) = \int  \left(c_r\Delta\mu ^2 - \frac{\zeta^2}{2\eta} |\nabla\phi|^4\right) \mathrm{d} \vb*{r} .
\end{equation}
Therefore, any local inhomogeneity of the swimmer density $\phi$ tends to reduce $\dot{\cal S}_\mathrm{tot}^{\,(\mathrm{ss})} - \dot{\cal S}$.


