\title{New presentation of the twisted Yangian of type $D$}
\author{Shuichi Harako\thanks{Graduate school of Mathematical Sciences, the University of Tokyo, harako@ms.u-tokyo.ac.jp} and Mamoru Ueda\thanks{Graduate school of Mathematical Sciences, the University of Tokyo, mueda@ms.u-tokyo.ac.jp}}
