\begin{abstract}
We construct a new presentation of the twisted Yangian of type $D$ with a finite number of generators. By using this presentation, we propose a new definition of the twisted affine Yangian of type $D$.
\end{abstract}
\section{Introduction}
Drinfeld (\cite{D1}, \cite{D2}) introduced the Yangian $Y_h(\mathfrak{g})$ associated with a finite dimensional simple Lie algebra $\mathfrak{g}$. The Yangian $Y_h(\mathfrak{g})$ is a quantum group which is a deformation of a current algebra $\mathfrak{g}\otimes\mathbb{C}[z]$. The Yangian has several presentations including the RTT presentation, the Drinfeld $J$ presentation, the Drinfeld presentation. By using the Drinfeld presentation, the definition of the Yangian can be extended to a symmetrizable Kac-Moody Lie algebra. For an affine Lie algebra, Guay-Nakajima-Wendlandt \cite{GNW} constructed a finite presentation of the Yangian and showed that the Yangian associated with an affine Lie algebra has a coproduct. Recently, relationships between Yangians and $W$-algebras have been actively studied. In finite setting, there exists a relationship between the Yangian of type $A$ and a finite $W$-algebra of type $A$ (see Ragoucy-Sorba \cite{RS} and Brundan-Kleshchev \cite{BK}). As for other types, a finite $W$-algebra is connected to the twisted Yangian (see \cite{Bro}, \cite{DKV} and \cite{LPTTW}). 

Olshanskii (\cite{O}) introduced the twisted Yangian associated with an orthogonal Lie algebra $\mathfrak{so}(n)$ or a symplectic Lie algebra $\mathfrak{sp}(\dfrac{n}{2})$. Similarly to the finite Yangian $Y_\hbar(\mathfrak{sl}(n))$, the twisted Yangian also has several presentations. Olshanskii defined the twisted Yangian by the RTT presentation. Belliard and Regelskis (\cite{BR1}) constructed the Drinfeld $J$ presentation of the twisted Yangian. Lu-Wang-Zhang \cite{LWZ0}, \cite{LWZ} and Lu-Zhang \cite{LWZ1} gave the Drinfeld presentation of the twisted Yangian.
In this article, we give a new presentation of the twisted Yangian of type $D$, which corresponds to the presentation given in \cite{GNW}. 

In this article, we only consider the twisted Yangian associated with $\mathfrak{so}(2n)$. A Lie algebra $\mathfrak{so}(2n)$ can be regarded as a fixed point subalgebra in $\mathfrak{sl}(2n)$ of an appropriate involution of $\mathfrak{sl}(2n)$. We can choose this involution by two ways. The first one is the transpose of an $2n\times 2n$-matrix. The another one is given by
\begin{align*}
E_{i,j}\mapsto -E_{j+n,i+n},\ E_{i,j+n}\mapsto -E_{j,i+n},\ E_{i+n,j}\mapsto -E_{j+n,i}\text{ for }1\leq i,j\leq n,
\end{align*}
where $E_{i,j}$ is a matrix unit whose $(i,j)$-component is $1$ and other components are $0$. Lu-Wang-Zhang \cite{LWZ0} gave the Drinfeld presentation by using the first involution. In this article, we use the latter involution and denote it by $\tau$. 

In Section 3, we give a presentation of the universal enveloping algebra of a twisted current Lie algebra $\mathfrak{sl}(2n)[z]^{\widetilde{\tau}}=\{x\in\mathfrak{sl}(2n)[u]\mid\widetilde{\tau}(x)=x\}$, where $\widetilde{\tau}$ is an involution of $\mathfrak{sl}(2n)[z]$ defined by $\widetilde{\tau}(xz^r)=(-1)^r\tau(x)z^r$. The set of generators of this presentation is
\begin{align*}
\{h_iz^{2r},x^\pm_iz^{2r},\bar{h}_jz^{2r+1},\bar{x}^\pm_kz^{2r+1}\mid 1\leq i\leq n,1\leq j\leq n-1,1\leq k\leq n+1,r\geq0\},
\end{align*}
where
\begin{gather*}
h_i=\begin{cases}
E_{i,i}-E_{i+1,i+1}-E_{n+i,n+i}+E_{n+i+1,n+i+1}&\text{ if }1\leq i\leq n-1,\\
E_{n-1,n-1}+E_{n,n}-E_{2n-1,2n-1}-E_{2n,2n}&\text{ if }i=n,
\end{cases}\\
x^+_i=\begin{cases}
E_{i,i+1}-E_{n+i+1,n+i}&\text{ if }1\leq i\leq n-1,\\
E_{n-1,2n}-E_{n,2n-1}&\text{ if }i=n,
\end{cases}\ 
x^-_i=\begin{cases}
E_{i+1,i}-E_{n+i,n+i+1}&\text{ if }1\leq i\leq n-1,\\
E_{2n,n-1}-E_{2n-1,n}&\text{ if }i=n,
\end{cases}\\
\bar{h}_i=
E_{i,i}-E_{i+1,i+1}+E_{n+i,n+i}-E_{n+i+1,n+i+1}\text{ if }1\leq i\leq n-1,\\
\bar{x}^+_i=
\begin{cases}
E_{i,i+1}+E_{n+i+1,n+i}&\text{ if }1\leq i\leq n-1,\\
E_{n-1,2n}+E_{n,2n-1}&\text{ if }i=n,\\
E_{n,2n}&\text{ if }i=n+1,
\end{cases}\ 
\bar{x}^-_i=
\begin{cases}
E_{i+1,i}+E_{n+i,n+i+1}&\text{ if }1\leq i\leq n-1,\\
E_{2n,n-1}+E_{2n-1,n}&\text{ if }i=n,\\
E_{2n,n}&\text{ if }i=n+1.
\end{cases}
\end{gather*}

In Section 4, we construct a presentation of the twisted current Lie algebra $U(\mathfrak{sl}(2n)[z]^{\widetilde{\tau}})$ with the generators $\{h_i,x^\pm_i,\bar{h}_jz,\bar{x}^\pm_iz\mid 1\leq i\leq n,1\leq j\leq n-1\}$. In Section 6, by using the presentation given in Section~4, we define an associative algebra $TY_\hbar(\mathfrak{so}(2n))$ as a deformation of $U(\mathfrak{sl}(2n)[z]^{\widetilde{\tau}})$. 

\begin{Theorem}
The associative algebra $TY_\hbar(\mathfrak{so}(2n))$ is isomorphic to the twisted Yangian associated with $\mathfrak{so}(2n)$.
\end{Theorem}
Since Guay \cite{Gu1} defined the affine Yangian associated with $\widehat{\mathfrak{sl}}(n)$ by extending the minimalistic presentation of the Yangian associated with $\mathfrak{sl}(n)$, we expect that this finite presentation will be useful for giving a definition of the twisted affine Yangian. In \cite{U77}, the author defined the twisted affine Yangian of type $C$ as a subalgebra of the affine Yangian associated with $\widehat{\mathfrak{sl}}(n)$ and constructed a relationship between the twisted affine Yangian of type $C$ and a rectangular $W$-algebra of type $D$ in certain cases. However, this definition is not so useful because the defining relations of the twisted affine Yangian were not given. In Section 7, we propose a new definition of the twisted affine Yangian of type $D$ by extending the definition of $TY_\hbar(\mathfrak{so}(2n))$. We conjecture that this twisted affine Yangian will become a coideal of the affine Yangian associated with $\widehat{\mathfrak{sl}}(2n)$. 

\section{Lie algebra $\mathfrak{so}(2n)$}

Let $n$ be a positive integer greater than $4$ and define a set $I_n=\{\pm1,\pm2,\cdots,\pm n\}$. 
We set an involution of the general linear Lie algebra $\mathfrak{gl}(2n)=\bigoplus_{i,j\in I_n}\mathbb{C}E_{i,j}$ by $\tau(E_{i,j})=-E_{-j,-i}$,
where $E_{i,j}$ is a $2n\times2n$-matrix whose $(p,q)$ component is $\delta_{i,p}\delta_{j,q}$. By the definition of $\tau$, the restriction of $\tau$ to $\mathfrak{sl}(2n)$ becomes an involution of $\mathfrak{sl}(2n)$. Let us set two subalgebras of $\mathfrak{sl}(2n)$:
\begin{align*}
\mathfrak{b}_1&=\{x\in\mathfrak{sl}(2n)\mid \tau(x)=x\}\\
&=\{\begin{pmatrix}
A&B \\
C&-A^t 
\end{pmatrix}\in\mathfrak{gl}(2n)\mid A,B,C\in\mathfrak{gl}(n),B^t=-B,C^t=-C\},\\
\mathfrak{b}_2&=\{x\in\mathfrak{sl}(n)\mid \tau(x)=-x\}\\
&=\{\begin{pmatrix}
A&B \\
C&A^t 
\end{pmatrix}\in\mathfrak{gl}(2n)\mid A\in\mathfrak{sl}(n),B,C\in\mathfrak{gl}(n),B^t=B,C^t=C\},
\end{align*}
where $X^t$ is the transpose of $X$ for an $n\times n$-matrix $X$.
It is well known that $\mathfrak{b}_1$ is isomorphic to the orthogonal Lie algebra $\mathfrak{so}(2n)$.

Let us set $f_{i,j}$ as $E_{i,j}-E_{-j,-i}$ for $i,j\in I_n$.
By the definition, $\mathfrak{b}_1$ has a basis
\begin{equation*}
\{f_{i,j}\mid i,j>0\}\cup\{f_{i,j}\mid ij<0,i\neq-j,|i|<|j|\}
\end{equation*}
and has a non-degenerate symmetric invariant bilinear form $(\ ,\ )$ defined by $(f_{i,j},f_{p,q})=\delta_{i,q}\delta_{j,p}-\delta_{i,-p}\delta_{j,-q}$.
We set $(a_{i,j})_{1\leq i,j\leq n}$ as the Cartan matrix of $\mathfrak{so}(2n)$:
\begin{align*}
a_{i,j}&=\begin{cases}
2\delta_{i,j}-\delta_{i,j+1}-\delta_{i+1,j}&\text{ if }1\leq i,j\leq n-1,\\
2\delta_{i,j}-\delta_{i,n-2}-\delta_{j,n-2}&\text{ if }i\text{ or }j=n
\end{cases}
\end{align*}
We also take the Chevalley generators of $\mathfrak{b}_1$ as follows:
\begin{gather*}
h_i=\begin{cases}
f_{i,i}-f_{i+1,i+1}&\text{ if }1\leq i\leq n-1,\\
f_{n-1,n-1}+f_{n,n}&\text{ if }i=n,
\end{cases}\\
x^+_i=\begin{cases}
f_{i,i+1}&\text{ if }1\leq i\leq n-1,\\
f_{n-1,-n}&\text{ if }i=n,
\end{cases}\ 
x^-_i=\begin{cases}
f_{i+1,i}&\text{ if }1\leq i\leq n-1,\\
f_{-n,n-1}&\text{ if }i=n.
\end{cases}
\end{gather*}
\section{Twisted current algebra $\mathfrak{sl}(2n)[u]^{\widetilde{\tau}}$}
The current algebra $\mathfrak{sl}(n)[u]$ is a Lie algebra whose vector space is $\mathfrak{sl}(n)\otimes\mathbb{C}[u]$ with the commutator relation:
\begin{equation*}
[x\otimes u^r,y\otimes u^s]=[x,y]\otimes u^{r+s}\text{ for }x,y\in\mathfrak{sl}(n).
\end{equation*}
Let $(A_{i,j})_{1\leq i,j\leq n}$ be the Cartan matrix of $\mathfrak{sl}(n)$. It is famous that the current algebra $\mathfrak{sl}(n)[u]$ has the following presentation.
\begin{Lemma}
The associative algebra $U(\mathfrak{sl}(n)[u])$ is isomorphic to the associative algebra generated by
\begin{equation*}
\{\mathfrak{h}_{i,r},\mathfrak{x}^\pm_{i,r}\mid1\leq i\leq n-1,r\in\mathbb{Z}_{\geq0}\}
\end{equation*}
with the relations:
\begin{gather}
[\mathfrak{h}_{i,r},\mathfrak{h}_{j,s}]=0,\label{last1}\\
[\mathfrak{h}_{i,0},\mathfrak{x}^\pm_{j,s}]=A_{i,j}\mathfrak{x}^\pm_{j,s},\label{last2}\\
[\mathfrak{x}^+_{i,r},\mathfrak{x}^-_{j,s}]=\delta_{i,j}\mathfrak{h}_{i,r+s},\label{last3}\\
[\mathfrak{x}^\pm_{i,r},\mathfrak{x}^\pm_{j,s}]=0\text{ for }A_{i,j}=0,\label{last4}\\
[\mathfrak{x}^\pm_{i,r_1},[\mathfrak{x}^\pm_{i,r_2},\mathfrak{x}^\pm_{j,s}]]=0\text{ for }A_{i,j}=-1,\label{last5}\\
[\mathfrak{h}_{i,r+1},\mathfrak{x}^\pm_{j,s}]=[\mathfrak{h}_{i,r},\mathfrak{x}^\pm_{j,s+1}],\label{last6}\\
[\mathfrak{x}^\pm_{i,r+1},\mathfrak{x}^\pm_{j,s}]=[\mathfrak{x}^\pm_{i,r},\mathfrak{x}^\pm_{j,s+1}].\label{last7}
\end{gather}
Moreover, the generators $\{\mathfrak{x}^+_{i,r}\mid 1\leq i\leq n-1,r\in\mathbb{Z}_{\geq0}\}$ and the relations \eqref{last4}, \eqref{last5} and \eqref{last7} give a Lie subalgebra $\mathfrak{n}_+(n)=\bigoplus_{1\leq i<j\leq n}\limits\mathbb{C}E_{i,j}u^r\subset\mathfrak{sl}(n)[u]$.
\end{Lemma}

We define an involution of the current algebra $\mathfrak{sl}(2n)[u]$ by $\widetilde{\tau}(x\otimes u^r)=(-1)^r\tau(x)\otimes u^r$.
By the definition of $\widetilde{\tau}$, the twisted current algebra $\mathfrak{sl}(2n)[u]^{\widetilde{\tau}}=\{x\in\mathfrak{sl}(2n)[u]\mid \widetilde{\tau}(x)=x\}$ can be decomposed to the sum of $\{x\otimes u^{2r}\mid x\in\mathfrak{b}_1\}$ and $\{x\otimes u^{2r+1}\mid x\in\mathfrak{b}_2\}$. Let us set $f^r_{i,j}=E_{i,j}u^r-(-1)^rE_{-j,-i}u^r$, which satisfies the relation
\begin{equation*}
[f^r_{i,j},f^s_{p,q}]=\delta_{j,p}f^{r+s}_{i,q}-\delta_{i,q}f^{r+s}_{p,j}-(-1)^r\delta_{-i,p}f^{r+s}_{-j,q}+(-1)^r\delta_{-j,q}f^{r+s}_{p,-i}.
\end{equation*}
Then, by the definition, $f^r_{i,j}$ spans the twisted current algebra $\mathfrak{sl}(2n)[u]^{\widetilde{\tau}}$.  We also take generators of $\mathfrak{sl}(2n)[u]^\tau$ as
\begin{gather*}
h_{i,r}=\begin{cases}
f^r_{i,i}-f^r_{i+1,i+1}&\text{ if }1\leq i\leq n-1,\\
f^r_{n-1,n-1}+f^r_{n,n}&\text{ if }i=n,r\text{ is }even,
\end{cases}\\
x^+_{i,r}=\begin{cases}
f^r_{i,i+1}&\text{ if }1\leq i\leq n-1,\\
f^r_{n-1,-n}&\text{ if }i=n,\\
f^r_{n,-n}&\text{ if }i=n+1,r\text{ is }odd,
\end{cases}\ 
x^-_{i,r}=\begin{cases}
f^r_{i+1,i}&\text{ if }1\leq i\leq n-1,\\
f^r_{-n,n-1}&\text{ if }i=n,\\
f^r_{-n,n}&\text{ if }i=n+1,r\text{ is }odd.
\end{cases}
\end{gather*}

For a non-negative integer $r$, we set matrices $(a^r_{i,j})$ as
\begin{align*}
a^r_{i,j}=\begin{cases}
a_{i,j}&\text{ if }1\leq i,j\leq n,r\text{ is even,}\\
a_{i,j}+2\delta_{i,n-1}\delta_{j,n}&\text{ if }1\leq i\leq n-1,1\leq j\leq n,r\text{ is odd}.
\end{cases}
\end{align*}
Then, we have $[h_{i,r},x^\pm_{j,s}]=\pm a^r_{i,j}x^\pm_{j,r+s}=0$ for $j\neq n+1$. 

In this section, we will give a presentation of the universal enveloping algebra of $\mathfrak{sl}(2n)[u]^\tau$ whose generators are $\{h_{i,r},x^\pm_{i,r}\}$.
\begin{Definition}
We define $L$ as the associative algebra generated by
\begin{equation*}
\{H_{i,2r},X^\pm_{i,2r}\mid 1\leq i\leq n,r\in\mathbb{Z}_{\geq0}\}\cup\{H_{i,2r+1},X^\pm_{j,2r+1}\mid 1\leq i\leq n-1,1\leq j\leq n+1,r\in\mathbb{Z}_{\geq0}\}
\end{equation*}
with the commutator relations:
\begin{gather}
[H_{i,r},H_{j,s}]=0,\label{Eq901}\\
[H_{i,r},X^\pm_{j,s}]=\pm a^{r}_{i,j}X^\pm_{j,r+s}\text{ for }j\neq n+1,\label{Eq901-1}\\
[H_{i,r},X^\pm_{n+1,s}]=\begin{cases}
0&r\text{ is odd},\\
\pm(2\delta_{i,n}-2\delta_{i,n-1})X^\pm_{n+1,r+s}&r\text{ is even},
\end{cases}\label{Eq901-1-1}\\
[X^+_{i,r},X^-_{j,s}]=\delta_{i,j}H_{i,r+s}\text{ for }1\leq i,j\leq n-1,\label{Eq901-2}\\
[X^+_{n,r},X^-_{j,s}]=\begin{cases}
\delta_{n,j}H_{n,r+s}&\text{ if }j\neq n-1,n+1,r+s\text{ is even},\\
\delta_{n,j}H_{n-1,r+s}&\text{ if }j\neq n-1,n+1,r+s\text{ is odd},
\end{cases}\label{Eq901-3}\\
[X^+_{n,r},X^-_{n-1,s}]=0\text{ if }r+s\text{ is even},\label{Eq901-4}\\
[X^+_{n,r},X^-_{n-1,s}]=-X^+_{n+1,r+s}\text{ if }r+s\text{ is odd},\label{Eq901-5}\\
[X^+_{j,r},X^-_{n,s}]=\delta_{n,j}H_{n,r+s}\text{ if }j\neq n-1,n+1,\label{Eq901-6}\\
[X^+_{n-1,r},X^-_{n,s}]=0\text{ if }r+s\text{ is even},\label{Eq901-7}\\
[X^+_{n-1,r},X^-_{n,s}]=-X^-_{n+1,r+s}\text{ if }r+s\text{ is odd},\label{Eq901-8}\\
[X^+_{n+1,2r+1},X^-_{n+1,2s+1}]=2(H_{n,2r+2s+2}-H_{n-1,2r+2s+2}),\label{Eq901-9}\\
[X^\pm_{i,r+1},X^\pm_{j,s}]=[X^\pm_{i,r},X^\pm_{j,s+1}]\text{ for }1\leq i,j\leq n\text{ and }(i,j)\neq(n-1,n),(n,n-1),\label{Eq901-10-0}\\
[X^\pm_{n,r+1},X^\pm_{n-1,s}]=-[X^\pm_{n,r},X^\pm_{n-1,s+1}],\label{Eq901-10}\\
[X^\pm_{n+1,2r+1},X^\pm_{n+1,2s+1}]=0,\label{Eq901-10-1}\\
[X^\pm_{i,r},X^\pm_{i,s}]=0\text{ for }1\leq i\leq n,\label{Eq901-10-2}\\
[X^+_{n+1,2r+1},X^\pm_{j,s}]=0\text{ for }j<n-1,\label{Eq901-11}\\
[X^-_{n+1,2r+1},X^\pm_{j,s}]=0\text{ if }j<n-1,\label{Eq901-12}\\
[X^+_{n+1,2r+1},X^+_{n-1,s}]=-2X^+_{n,2r+s+1},\ [X^+_{n+1,2r+1},X^-_{n-1,s}]=0,\label{Eq901-13}\\
[X^+_{n+1,2r+1},X^-_{n,s}]=2X^-_{n-1,2r+s+1},\ [X^+_{n+1,2r+1},X^+_{n,s}]=0,\label{Eq901-14}\\
[X^-_{n+1,2r+1},X^-_{n-1,s}]=2X^-_{n,2r+s+1},\ [X^-_{n+1,2r+1},X^+_{n-1,s}]=0,\label{Eq901-15}\\
[X^-_{n+1,2r+1},X^+_{n,s}]=-2X^+_{n-1,2r+s+1},\ [X^-_{n+1,2r+1},X^-_{n,s}]=0,\label{Eq901-16}\\
[X^\pm_{i,r},X^\pm_{j,s}]=0\text{ if }a_{i,j}=0\text{ and }(i,j)\neq (n-1,n),(n,n-1),\label{Eq901-17}\\
[X^\pm_{n-1,r},X^\pm_{n,s}]=0\text{ if }r+s\text{ is even},\label{Eq901-17-1}\\
[X^\pm_{i,r_1},[X^\pm_{i,r_2},X^\pm_{j,s}]]=0\text{ if }(i,j)=(n-1,n),(n,n-1)\text{ and }r_1+s,r_2+s\text{ are odd},\label{Eq901-17-2}\\
[X^\pm_{i,r_1},[X^\pm_{i,r_2},X^\pm_{j,s}]]=0\text{ if }a_{i,j}=-1\text{ and }1\leq i,j\leq n,\label{Eq902}\\
[X^\pm_{n,s},[X^\pm_{n-2,r},X^\pm_{n-1,u}]]=(-1)^{s+u}[X^\pm_{n-1,u},[X^\pm_{n-2,r},X^\pm_{n,s}]],\label{Eq903-1}\\
[[X^\pm_{n,0},X^\pm_{n-2,r}],[X^\pm_{n,0},X^\pm_{n-1,s}]]=0,\label{Eq903-3}\\
[[X^+_{n,s},[X^+_{n-2,0},X^+_{n-3,0}]],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r}]]=0,\label{Eq903-4}\\
[[X^+_{n,2r+1},X^+_{n-2,0}],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,s}]]=0,\label{Eq903-5},\\
[[X^\pm_{n-1,0},X^\pm_{n-2,0}],[X^\pm_{n-1,s},X^\pm_{n,r}]]=0,\label{Eq903-7}\\
[[X^+_{n-1,s},[X^+_{n-2,0},X^+_{n-3,0}]],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r}]]=0,\label{Eq903-8}\\
[[X^+_{n-1,s},X^+_{n-2,0}],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r}]] = 0.\label{Eq903-8.5}
\end{gather}
\end{Definition}
In this section, we will show that $L$ is isomorphic to $U(\mathfrak{sl}(2n)^{\widetilde{\tau}})$.

For positive integers $1\leq i<j\leq n$, we set
\begin{align}
X_{i,j,r}&=\prod_{u=i}^{j-2}\ad(X^+_{u,0})(X^+_{j-1,r}),\label{9001}\\
X_{i,-j,r}&=\Big(\prod_{u=i}^{j-2}\ad(X^+_{u,0})\Big)\Big(\prod_{u=j+1}^{n}\ad(X_{u-2,u,0})\Big)x^+_{n,r},\label{9007}\\
X_{n,-n,2r+1}&=X^+_{n+1,2r+1},\label{9009}\\
X_{i,-i,2r+1}&=\ad(X^+_{i,0})\Big(\prod_{u=i+2}^{n}\ad(X_{u-2,u,0})\Big)X^+_{n,2r+1}.\label{9011}
\end{align}
We note that $X_{i,j,r}$ corresponds to $f_{i,j,r}$, $X_{i,-j,r}$ corresponds to $X_{i,-i,2r+1}$ corrresponds to $-f_{i,-i,r}$, and $\begin{cases}
-(-1)^rf_{i,j,r}&\text{ if }j-n\text{ is odd},\\
-f_{i,j,r}&\text{ if }j-n\text{ is even and }j\leq n,\\
f_{i,-n,r}&\text{ if }j=n.
\end{cases}$
\begin{Lemma}\label{gat}
The following elements are spanned by $\{X_{u,v,r},X_{u,-u,r},X_{u,-v,r}\mid1\leq u<v\leq n,r\in\mathbb{Z}_{\geq0}\}$:
\begin{gather*}
[X_{i,j,r},X_{a,b,s}],[X^+_{n,s},X_{i,j,r}],[X^+_{p,s},X_{i,-j,r}],[X^+_{n,s},X_{i,-j,r}],[X^+_{p,s},X_{i,-i,2r+1}][X^+_{n,s},X_{i,-i,2r+1}]
\end{gather*}
for $1\leq p\leq n-1$ and $1\leq i<j\leq n,1\leq a<b\leq n$.
\end{Lemma}
\begin{comment}
\begin{Lemma}\label{gat}
For $1\leq p\leq n-1$, the following relations hold:
\begin{gather}
[X_{i,j,r},X_{p,q,s}]=\delta_{j,p}X_{i,q,r+s}-\delta_{i,q}X_{p,j,r+s},\label{gat1}\\
[X^+_{n,s},X_{i,j,r}]=-\delta_{j,n-1}X_{i,-n,r+s}-(-1)^r\delta_{n,j}X_{i,-n+1,r+s},\label{gat2}\\
