\begin{Theorem}\label{pre}
The universal enveloping algebra $U(\mathfrak{sl}(2n)[u]^\tau)$ is isomorphic to $L$.
\end{Theorem}
\begin{proof}
By replacing $x$ with $X$, we define $x_{p,q,r}$ for $p\neq q$.
There exists a natural surjective homomorphism 
\begin{equation*}
\rho\colon L\to U(\mathfrak{sl}(2n)[u]^\tau)
\end{equation*}
by $X^\pm_{i,r}\mapsto x^\pm_{i,r}$ and $H_{i,r}\mapsto h_{i,r}$. By the definition, we find that $\mathfrak{sl}(2n)[u]^\tau$ has a basis which consists of $h_{i,r}$, $x^\pm_{n+1,2r+1}$ and $x_{p,q,r}$. By the PBW theorem, the ordered monomials of $h_{i,r}$, $x^\pm_{n+1,2r+1}$ and $x_{p,q,r}$ become a basis of $U(\mathfrak{sl}(2n)[u]^\tau)$. Thus, it is enough to show that the ordered monomials of $H_{i,r},X^\pm_{n+1,2r+1}$ and $X^\pm_{p,q,r}$ form the spanning set of $L$.
This follows from Lemma~\ref{indu1} and \eqref{Eq901-1-1}.
\end{proof}
\section{Finite presentation of $U(\mathfrak{sl}(2n)[u]^\tau)$}
One of the difficulty of the presentation given in Theorem~\ref{pre} is that the number of generators is infinite. In this section, we give a presentation of $U(\mathfrak{sl}(2n)[u]^\tau)$ with finite generators.
\begin{Theorem}\label{Mini}
The universal enveloping algebra $U(\mathfrak{sl}(2n)[u]^\tau)$ is isomorphic to the associative algebra generated by
\begin{equation*}
\{H_{i,0},H_{j,1},X^\pm_{i,r}\mid 1\leq i\leq n,1\leq j\leq n-1,r=0,1\}
\end{equation*}
with the commutator relations:
\begin{gather}
[H_{i,r},H_{j,s}]=0\text{ if }0\leq r,s\leq1,\label{eq901}\\
[H_{i,r},X^\pm_{j,0}]=\pm a^{r}_{i,j}X^\pm_{j,r}\text{ for }r=0,1,\label{eq901-1}\\
[X^+_{i,0},X^-_{j,0}]=\delta_{i,j}H_{i,0},\label{eq901-2--1},\\
[X^+_{i,1},X^-_{i,0}]=\delta_{i,j}H_{i,1}\text{ if }i\neq n,\label{eq901-2-0}\\
[[X^+_{n-1,2},X^-_{n-1,0}],X^\pm_{n,0}]=0,\label{eq901-2-1}\\
[X^+_{n,1},X^-_{n,0}]=H_{n-1,1}\label{eq901-3-1}\\
[X^\pm_{i,1},X^\pm_{i,0}]=[X^\pm_{i,0},X^\pm_{i,1}],\label{eq901-10-1}\\
[X^\pm_{i,0},X^\pm_{j,0}]=0\text{ if }a_{i,j}=0,\label{eq901-17}\\
[X^\pm_{i,0},[X^\pm_{i,0},X^\pm_{j,0}]]=0\text{ if }a_{i,j}=-1,\label{eq902}\\
[X^\pm_{n,1},[X^\pm_{n-2,0},X^\pm_{n-1,0}]]=-[X^\pm_{n-1,0},[X^\pm_{n-2,0},X^\pm_{n,1}]],\label{eq903-1}\\
[[X^\pm_{n,0},X^\pm_{n-2,0}],[X^\pm_{n,0},X^\pm_{n-1,1}]]=0,\label{eq903-3}\\
[[X^\pm_{n-1,0},X^\pm_{n-2,0}],[X^\pm_{n-1,0},X^\pm_{n,1}]]=0.\label{eq903-7}
\end{gather}
\end{Theorem}
This section is devoted to the proof of Theorem~\ref{Mini}. We define $X^\pm_{i,s},H_{i,2s-2},H_{j,2s-1}$ for $s\geq 2$, $1\leq i\leq n$ and $1\leq j\leq n-1$ inductively by
\begin{gather*}
X^\pm_{i,s}=\begin{cases}
\dfrac{1}{2}[H_{i,1},X^\pm_{i,s-1}]&\text{ if }1\leq i\leq n-1,\\
\dfrac{1}{2}[H_{n-1,1},X^\pm_{n,s-1}]&\text{ if }i=n,
\end{cases}\\
H_{i,2s-2}=[X^\pm_{i,2s-2},X^-_{i,0}],\ H_{j,2s-1}=[X^+_{j,2s-1},X^-_{j,0}].
\end{gather*}
We also define
\begin{align*}
X^+_{n+1,2r+1}&=-[X^+_{n,2r+1},X^-_{n-1,0}],\ 
X^-_{n+1,2r+1}=-[X^+_{n-1,2r+1},X^-_{n,0}].
\end{align*}
By the definition of $H_{i,2s-2}$, we can rewrite \eqref{eq901-2-1} as
\begin{align}
[H_{n-1,2},X^\pm_{n,0}]=0.\label{eqeq0-1}.
\end{align}
We denote the associative algebra defined by \eqref{eq901}-\eqref{eq903-7} by $\widetilde{L}$.
\begin{Lemma}\label{Lem-1}
There exists a homomorphism from $U(\mathfrak{so}(2n))$ to $\widetilde{L}$ given by $h_i\mapsto H_{i,0}$ and $x^\pm_i\mapsto X^\pm_{i,0}$.
\end{Lemma}
This naturally follows from \eqref{eq901}, \eqref{eq901-1}, \eqref{eq901-2--1}, \eqref{eq901-17} and \eqref{eq902}.

\begin{Lemma}\label{Lem0}
\textup{(1)}\ We obtain
\begin{gather}
[X^+_{i,r},X^-_{i,s}]=\delta_{i,j}H_{i,r+s}\text{ if }r+s\leq 1,1\leq i,j\leq n-1,\label{eq901-2}
\end{gather}
\textup{(2)}\ The following relations hold:
\begin{gather}
[X^+_{n,1},X^-_{n-1,0}]=[X^+_{n,0},X^-_{n-1,1}],\label{eq901-5}\\
[X^+_{n-1,1},X^-_{n,0}]=[X^+_{n-1,0},X^-_{n,1}].\label{eq901-8}
\end{gather}
\textup{(3)}\ We obtain
\begin{gather}
[X^+_{n,r},X^-_{j,s}]=\delta_{n,j}H_{n-1,1}\text{ if }j\neq n-1,n+1\text{ and }r+s=1,\label{eq901-3}\\
[X^+_{j,r},X^-_{n,s}]=\delta_{n,j}H_{n,1},\text{ if }j\neq n-1,n+1\text{ and }r+s=1.\label{eq901-6}
\end{gather}
\textup{(4)}\ The following relation hold:
\begin{gather}
[X^\pm_{i,1},X^\pm_{j,0}]=[X^\pm_{i,0},X^\pm_{j,1}]\text{ for }1\leq i,j\leq n\text{ and }(i,j)\neq(n-1,n),(n,n-1).\label{eq901-10}
\end{gather}
\end{Lemma}
\begin{proof}
\textup{(1)}\ In the case that $1\leq i,j\leq n-1$ and $i\neq j$, by \eqref{eq901-1}, we have
\begin{gather*}
0=[H_{i,1},[X^+_{i,0},X^-_{j,0}]]=a_{i,i}[X^+_{i,1},X^+_{j,0}]-a_{i,j}[X^+_{i,0},X^+_{j,1}],\\
0=[H_{j,1},[X^+_{i,0},X^-_{j,0}]]=a_{i,j}[X^+_{i,1},X^+_{j,0}]-a_{j,j}[X^+_{i,0},X^+_{j,1}].
\end{gather*}
Since the matrix $\begin{pmatrix}
a_{i,i} & a_{i,j} \\
a_{i,j} & a_{j,j} \\
\end{pmatrix}$
is invertible, we find the relation $[X^+_{i,r},X^+_{j,1-r}]=0$. By \eqref{eq901} and \eqref{eq901-1}, we obtain
\begin{gather*}
0=[H_{i,1},H_{i,0}]=[H_{p,1},[X^+_{i,0},X^-_{i,0}]]=a_{i,i}([X^+_{i,1},X^-_{i,0}]-[X^+_{i,0},X^-_{i,1}])
\end{gather*}
Thus, we find that $[X^+_{i,0},X^-_{i,1}]=[X^+_{i,1},X^-_{i,0}]=H_{i,1}$ holds.

We can prove (2) and (3) by the similar way to (1).
\begin{comment}
\textup{(2)}\ 
\begin{equation*}
0=[H_{n-2,1},[X^+_{n,0},X^-_{n-1,0}]]=-[X^+_{n,1},X^-_{n-1,0}]+[X^+_{n,0},X^-_{n-1,1}].
\end{equation*}
\end{comment}

\textup{(4)}\ We only consider the $+$ case. The $-$ case can be proven in the same way. We need to show the case that $i\neq j$. In the case that $a_{i,j}=0$, $i\neq n$ and $(i,j)\neq (n-1,n),(n,n-1)$, we can choose $k$ such that $a^1_{i,k}\neq0$ and $a^1_{j,k}=0$. Then, we obtain
\begin{align*}
[X^+_{i,1},X^+_{j,0}]&=\dfrac{1}{a^1_{i,k}}[H_{k,1},[X^+_{i,0},X^+_{j,0}]]=0.
\end{align*}
In the case that $a_{i,j}=-1$, we have
\begin{align*}
0=[[X^+_{i,0},[X^+_{i,0},X^+_{j,0}]],X^-_{i,1}]&=[X^+_{i,0},[H_{i,1},X^+_{j,0}]]+[H_{i,1},[X^+_{i,0},X^+_{j,0}]]\\
&=-[X^+_{i,0},X^+_{j,1}]+2[X^+_{i,1},X^+_{j,0}]-[X^+_{i,0},X^+_{j,1}]
\end{align*}
where we consider $H_{n,1}=H_{n-1,1}$. Thus, we have proved the relation.
\end{proof}

\begin{Lemma}\label{Lem1}
For $1\leq i,j\leq n$ and $(i,j)\neq(n-1,n),(n,n-1)$, the relations \eqref{Eq901}-\eqref{Eq901-3}, \eqref{Eq901-10}, \eqref{Eq901-17} and \eqref{Eq902} are obtained. Moreover, we obtain the relation
