We only show the first equation. The second equation can be proven in a similar way.
By \eqref{eq901-2--1}, Lemma~\ref{Lem1} and \eqref{eqeq0-1}, we have
\begin{align}
0&=[H_{n-1,2},[X^-_{n-1,0},X^+_{n,0}]]=-2[X^-_{n-1,2},X^+_{n,0}].\label{ultra}
\end{align}
We obtain
\begin{align}
0&=[H_{n-2,2},[X^-_{n-1,0},X^+_{n,0}]]=[X^-_{n-1,2},X^+_{n,0}]-[X^-_{n-1,0},X^+_{n,2}]=-[X^-_{n-1,0},X^+_{n,2}]\label{ultra-2}
\end{align}
by \eqref{eq901-2--1}, Lemma~\ref{Lem1} and \eqref{ultra}. By \eqref{ultra-2}, Lemma~\ref{Lem1}, \eqref{eq901-5}, we have
\begin{align*}
&\quad[X^+_{n,1},X^-_{n-1,1}]=[X^+_{n,1},X^-_{n-1,1}]-[X^+_{n,2},X^-_{n-1,0}]\\
&=[H_{n-2,1},[X^+_{n,1},X^-_{n-1,0}]]=[H_{n-2,1},[X^+_{n,0},X^-_{n-1,1}]]\\
&=-[X^+_{n,1},X^-_{n-1,1}]+[X^+_{n,0},X^-_{n-1,2}]=-[X^+_{n,1},X^-_{n-1,1}].
\end{align*}
Thus, we have obtained $[X^+_{n,r},X^-_{n-1,s}]=0$ for $r+s=2$.
