\begin{Lemma}
The relation \eqref{Eq901-1} holds for $(i,j)=(n,n-1),(n-1,n)$.
\end{Lemma}
\begin{proof}
By Lemma~\ref{Lem1}, we obtain
\begin{align*}
[H_{n-1,r},X^+_{n,s}]=\Big(\dfrac{\ad(H_{n-1,1})}{2}\Big)^{s-1}[H_{n-1,r},X^+_{n,0}].
\end{align*}
For the case that $r$ is even, by \eqref{eq901-2--1} and \eqref{Eq901-4}, we have
\begin{align*}
[H_{n-1,r},X^+_{n,0}]=[[X^+_{n-1,r},X^-_{n-1,0}],X^+_{n,0}]=0.
\end{align*}
For the case that $r$ is odd, we obtain
\begin{align*}
[[X^+_{n-1,0},X^-_{n-1,r}],X^+_{n,0}]=[X^+_{n-1,0},X^+_{n+1,r}]=2X^+_{n-1,r},
\end{align*}
where the first equality is due to the definition of $X^+_{n+1,s}$ and \eqref{Eq901-17}, and the second equality is due to \eqref{Eq901-13}.
Thus, by Lemma~\ref{Lem1}, we have obtained \eqref{Eq901-1} for the case that $(i,j)=(n-1,n)$.

Similarly, by Lemma~\ref{Lem1}, \eqref{eq901-2--1} and \eqref{Eq901-4}, we can obtain 
\begin{align*}
[H_{n,2r},X^+_{n-1,s}]&=\Big(\dfrac{\ad(H_{n-1,1})}{2}\Big)^{s-1}[H_{n,2r},X^+_{n-1,0}]\\
&=\Big(\dfrac{\ad(H_{n-1,1})}{2}\Big)^{s-1}[[X^+_{n,2r},X^-_{n,0}],X^+_{n-1,0}]=0.
\end{align*}
\end{proof}
\begin{Corollary}\label{Last}
\begin{enumerate}
\item
The relation \eqref{Eq901} holds for $(i,j)=(n,n-1),(n-1,n)$.
\item The relations \eqref{Eq901-1-1}, \eqref{Eq901-9} and \eqref{Eq901-10} hold.
\end{enumerate}
\end{Corollary}
\begin{proof}
\begin{enumerate}
\item
By \eqref{Eq901-1} and the definition of $H_{i,r}$, we have
\begin{align*}
[H_{n-1,r},H_{n,s}]=[H_{n-1,r},[X^+_{n,s},X^-_{n,0}]]=a^r_{n-1,n}([X^+_{n,s+r},X^-_{n,0}]-[X^+_{n,s},X^-_{n,r}])=0,
\end{align*}
where the last equality is due to Lemma~\ref{Lem1}.
\item First, we show the relation \eqref{Eq901-1-1}. We only prove the $+$ case. The $-$ case can be shown in a similar way. We obtain
\begin{align*}
&\quad[H_{i,2r},X^+_{n+1,2s+1}]\\
&=[H_{i,2r},-\dfrac{1}{2}[X^+_{n,2s+1},X^-_{n-1,0}]]\\
&=-(2\delta_{i,n}-\delta_{i,n-2})[X^+_{n,2s+2r+1},X^-_{n-1,0}]+(2\delta_{i,n-1}-\delta_{i,n-2})[X^+_{n,2s+1},X^-_{n-1,2r}]\\
&=(2\delta_{i,n}-\delta_{i,n-2})X^+_{n+1,2s+2r+1}-(2\delta_{i,n-1}-\delta_{i,n-2})X^+_{n+1,2s+2r+1}\\
&=(2\delta_{i,n}-2\delta_{i,n-1})X^+_{n+1,2r+2s+1},
\end{align*}
where the first equality is due to the definition of $X^+_{n+1,2s+1}$, and the second and third equalities are is due to \eqref{Eq901-1} and the last equality is due to \eqref{Eq901-6}.
Similarly, we also obtain
\begin{align*}
&\quad[H_{i,2r+1},X^+_{n+1,2s+1}]\\
&=[H_{i,2r+1},-\dfrac{1}{2}[X^+_{n,2s+1},X^-_{n-1,0}]]\\
&=-(2\delta_{i,n-1}-\delta_{i,n-2})[X^+_{n,2r+2s+2},X^-_{n-1,0}]+(2\delta_{i,n-1}-\delta_{i,n-2})[X^+_{n,2s+1},X^-_{n-1,2r+1}]\\
&=0-0=0,
\end{align*}
where the first equality is due to the definition of $X^+_{n+1,2s+1}$, the second equality is due to \eqref{Eq901-1} and the third equality is due to \eqref{Eq901-5}.

Next, we show the relation \eqref{Eq901-9}. 
\begin{align*}
&\quad[X^+_{n+1,2r+1},X^-_{n+1,2s+1}]=[-[X^+_{n,2r+1},X^-_{n-1,0}],X^-_{n+1,2s+1}]\\
&=-[[X^+_{n,2r+1},X^-_{n+1,2s+1}],X^-_{n-1,0}]-[X^+_{n,2r+1},[X^-_{n-1,0},X^-_{n+1,2s+1}]]\\
&=-[2X^+_{n-1,2r+2s+2},X^-_{n-1,0}]-[X^+_{n,2r+1},-2X^-_{n,2s+1}]\\
&=2(-H_{n-1,2r+2s+2}+H_{n,2r+2s+2}),
\end{align*}
where the first equality is due to the definition of $X^+_{n+1,2s+1}$, the third equality is due to \eqref{Eq901-15} and \eqref{Eq901-16} and the last equality is due to \eqref{Eq901-2}.

Finally, we prove the relation \eqref{Eq901-10}. We only show the $+$ case. The $-$ case can be proven in the same way.
\begin{align*}
&\quad[X^+_{n+1,2r+1},X^+_{n+1,2s+1}]=[X^+_{n+1,2r+1},-[X^+_{n,2s+1},X^-_{n-1,0}]]\\
&=-[X^+_{n,2s+1},[X^+_{n+1,2r+1},X^-_{n-1,0}]]-[[X^+_{n+1,2r+1},X^+_{n,2s+1}],X^-_{n-1,0}]=0+0=0,
\end{align*}
where the first equality is due to the definition of $X^+_{n+1,2s+1}$ and the second equality is due to \eqref{Eq901-13} and \eqref{Eq901-14}.
\end{enumerate}
\end{proof}
\begin{Lemma}\label{LemLem2}
The relation \eqref{Eq903-1} holds.
\end{Lemma}
\begin{proof}
We only show the $+$ case. The $-$ case can be proven in a similar way.
Let us set
\begin{align*}
f(r,s,u)=[X^+_{n,s},[X^+_{n-2,r},X^+_{n-1,u}]]-(-1)^{s+u}[X^+_{n-1,u},[X^+_{n-2,r},X^+_{n,s}]].
\end{align*}
By \eqref{Eq901-1}, we have
\begin{align}
[H_{n-3,1},f(r,s,u)]=-f(r+1,s,u).\label{last91}
\end{align}
Thus, it is enough to show the case that $r=0$.

We prove this by induction on $s+u$. The case that $s+u=0$ follows from Lemma~\ref{Lem-1}. For the case that $s+u=1$, we obtain
\begin{align*}
0=[H_{n-2,1},f(0,0,0)]=2f(1,0,0)-f(0,1,0)-f(0,0,1)=0-0-f(0,0,1),
\end{align*}
by \eqref{last91}, \eqref{Eq901-1} and \eqref{eq903-1}. Thus, \eqref{Eq903-1} is true for the case that $s+u=1$.
The case that $s+u=2$ follows from the following relations:
\begin{gather*}
0=[H_{n,2},f(r,0,0)]=2f(r,2,0)-f(r+2,0,0)=2f(r,2,0),\\
0=[H_{n-1,2},f(r,0,0)]=2f(r,0,2)-f(r+2,0,0)=2f(r,0,2),\\
[H_{n-2,1},f(r,1,0)]=2f(r+1,1,0)-f(r,2,0)-f(r,1,1),
\end{gather*}
which are deduced from \eqref{last91} and \eqref{Eq901-1}. 

Suppose that \eqref{Eq903-1} holds if $s+u\leq m$. We obtain
\begin{gather*}
0=[H_{n,2},f(r,m-u,u)]=2f(r,m+2-u,u)-f(r+2,m-u,u)=2f(r,m+2-u,u)-0,\\
0=[H_{n-1,2},f(r,s,m-s)]=2f(r,s,m+2-s)-f(r+2,s,m-s)=2f(r,s,m+2-s)-0
\end{gather*}
by \eqref{Eq901-1} and \eqref{last91}. Thus, we have proved \eqref{Eq901-1}.
\end{proof}
\begin{Lemma}\label{LemLem3}
We obtain the relations \eqref{Eq903-3}-\eqref{Eq903-8.5}.
\end{Lemma}
\begin{proof}
First, we show \eqref{Eq903-3}. We only show the $+$ case. The $-$ case can be proven in the same way.
Let us set 
\begin{align*}
