\end{align*}
By \eqref{Eq901-1} and \eqref{Eq901-10-0} and \eqref{Eq901-10}, we have
\begin{align}
[H_{n-3,1},f(r,s)]&=-f(r+1,s),\label{last93}\\
[H_{n-1,2},f(r,s)]&=-f(r+2,s)+2f(r,s+2).\label{last94}
\end{align}
We prove this by induction on $r+s$. The case $r+s=0$ is derived from the defining relations of $\mathfrak{so}(2n)$. The case $r+s=1$ follows from \eqref{eq903-3} and 
\begin{align*}
0=[H_{n-3,1},f(0,0)]=-f(1,0),
\end{align*}
which are derived from \eqref{last93}.

Suppose that \eqref{Eq903-9} holds in the case that $r+s\leq m+1$. 
By \eqref{last93} and \eqref{last94}, we have
\begin{align*}
0=[H_{n-1,2},f(r,m-r)]&=-f(r+2,m-r)+2f(r,m+2-r),\\
0=[H_{n-3,1},f(r,m+1-r)]&=-f(r+1,m+1-r).
\end{align*}
Thus, we find that \eqref{Eq903-3} holds for the case $r+s=m+2$. We can obtain \eqref{Eq903-7} similarly.

Next, we show the relation \eqref{Eq903-4}. Let us set
\begin{align*}
g(s,r)&=[[X^+_{n,s},[X^+_{n-2,0},X^+_{n-3,0}]],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r}]].
\end{align*}
By \eqref{Eq901-1}, we have
\begin{align*}
[H_{n-4,1},g(s,r)]&=-[[X^+_{n,s},[X^+_{n-2,0},X^+_{n-3,1}]],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r}]].
\end{align*}
Since
\begin{align*}
&\quad[X^+_{n,s},[X^+_{n-2,0},X^+_{n-3,1}]]=[X^+_{n,s},[X^+_{n-2,1},X^+_{n-3,0}]]\\
&=[[X^+_{n,s},X^+_{n-2,1}],X^+_{n-3,0}]=[[X^+_{n,s+1},X^+_{n-2,0}],X^+_{n-3,0}]=[X^+_{n,s+1},[X^+_{n-2,0},X^+_{n-3,0}]]
\end{align*}
holds by \eqref{Eq901-17}, we obtain
\begin{align}
[H_{n-4,1},g(s,r)]=-g(s+1,r).\label{last191}
\end{align}
By \eqref{Eq901-1}, we have
\begin{align*}
&\quad[H_{n-1,1},g(s,r)]\\
&=[2[X^+_{n,s+1},[X^+_{n-2,0},X^+_{n-3,0}]]-[X^+_{n,s},[X^+_{n-2,1},X^+_{n-3,0}]],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r}]]\\
&\quad+[[X^+_{n,s},[X^+_{n-2,0},X^+_{n-3,0}]],\\
&\qquad\qquad\qquad2[[X^+_{n-1,1},X^+_{n-2,0}],X^+_{n,r}]-[[X^+_{n-1,0},X^+_{n-2,1}],X^+_{n,r}]-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]].
\end{align*}
Since
\begin{align}
&\quad2[X^+_{n,s+1},[X^+_{n-2,0},X^+_{n-3,0}]]-[X^+_{n,s},[X^+_{n-2,1},X^+_{n-3,0}]]\\
&=2[X^+_{n,s+1},[X^+_{n-2,0},X^+_{n-3,0}]]-[X^+_{n,s+1},[X^+_{n-2,0},X^+_{n-3,0}]]\\
&=[X^+_{n,s+1},[X^+_{n-2,0},X^+_{n-3,0}]]
\end{align}
holds by \eqref{Eq903-17} and
\begin{align*}
&\quad2[[X^+_{n-1,1},X^+_{n-2,0}],X^+_{n,r}]-[[X^+_{n-1,0},X^+_{n-2,1}],X^+_{n,r}]-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]\\
&=[[X^+_{n-1,0},X^+_{n-2,1}],X^+_{n,r}]-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]\\
&=(-1)^r[[X^+_{n,r},X^+_{n-2,1}],X^+_{n-1,0}]-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]\\
&=(-1)^r[[X^+_{n,r+1},X^+_{n-2,0}],X^+_{n-1,0}]-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]\\
&=-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]-[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]\\
&=-2[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]
\end{align*}
hold by \eqref{Eq903-17} and \eqref{Eq903-1}, we obtain
\begin{align}
[H_{n-1,1},g(s,r)]&=g(s+1,r)-2g(s,r+1).\label{last192}
\end{align}

We prove this by induction on $r+s$. The case $r+s=0$ follows from Lemma~\ref{Lem-1}. Suppose that \eqref{Eq903-4} holds for $r+s\leq m$. By \eqref{last191} and \eqref{last192}, we have
\begin{align*}
