&\quad-[[X^+_{n-1,s},X^+_{n-2,0}],[[X^+_{n-1,1},X^+_{n-2,0}],X^+_{n,r}]]\\
&\quad+2[[X^+_{n-1,s},X^+_{n-2,0}],[[X^+_{n-1,0},X^+_{n-2,1}],X^+_{n,r}]]\\
&\quad-[[X^+_{n-1,s},X^+_{n-2,0}],[[X^+_{n-1,0},X^+_{n-2,0}],X^+_{n,r+1}]]\\
&=k(s+1,r)-2k(s,r+1).
\end{align*}
\end{comment}
\end{proof}
By Lemma~\ref{Lem1}-Lemma~\ref{LemLem3}, we complete the proof of Theorem~\ref{Mini}.

\section{Twisted Yangian of type $D$}
Let us recall the definition of the twisted Yangian given in \cite{MNO}. The twisted Yangian associated with $\mathfrak{so}(2n)$ is defined as a subalgebra of the Yangian associated with $\mathfrak{gl}(2n)$.
\begin{Definition}
Let $\hbar\in\mathbb{C}$.
The Yangian associated with $\mathfrak{gl}(2n)$ is the associative algebra generated by $\{T^{(r)}_{i,j}\mid r\geq0,i,j\in I_n\}$ with the commutator relation:
\begin{gather*}
T^{(0)}_{i,j}=\delta_{i,j},\ [T^{(r+1)}_{i,j},T^{(s)}_{k,l}]-[T^{(r)}_{i,j},T^{(s+1)}_{k,l}]=\hbar(T^{(r)}_{k,j}T^{(s)}_{i,l}-T^{(s)}_{k,j}T^{(r)}_{i,l}).
\end{gather*}
\end{Definition}
We denote the Yangian associated with $\mathfrak{gl}(2n)$ by $Y_\hbar(\mathfrak{gl}(2n))$.  Let us set $\{S^{(r)}_{i,j}\mid r\geq0,i,j\in I_n\}\subset Y_\hbar(\mathfrak{gl}(2n))$ by $S^{(0)}_{i,j}=\delta_{i,j}$ and
\begin{gather*}
S_{i,j}^{(r)}=T^{(r)}_{i,j}-(-1)^rT^{(r)}_{-j,-i}+\hbar\sum_{s=1}^{r-1}\sum_{a\in I_n}(-1)^sT^{(r-s)}_{i,a}T_{-j,-a}^{(s)}.
\end{gather*}
for $r\geq1$. In particular, we have
\begin{align*}
S^{(1)}_{i,j}&=T^{(1)}_{i,j}-T^{(1)}_{-j,-i},\\
S^{(2)}_{i,j}&=T^{(2)}_{i,j}+T^{(2)}_{-j,-i}-\hbar\sum_{a\in I_n}T^{(1)}_{i,a}T^{(1)}_{-j,-a},\\
S^{(3)}_{i,j}&=T^{(3)}_{i,j}-T^{(3)}_{-j,-i}-\hbar\sum_{a\in I_n}(T^{(2)}_{i,a}T^{(1)}_{-j,-a}-T^{(1)}_{i,a}T^{(2)}_{-j,-a}).
\end{align*}
By the definition of $S^{(r)}_{i,j}$, we obtain the following lemma (See Proposition 3.7 in \cite{MNO}).
\begin{Lemma}
\begin{enumerate}
\item We obtain
\begin{align}
S^{(1)}_{i,j}+S^{(1)}_{-j,-i}&=0,\label{SS5}\\
S^{(2)}_{i,j}-S^{(2)}_{-j,-i}&=-\hbar S^{(1)}_{i,j},\label{SS6}\\
S^{(3)}_{i,j}+S^{(3)}_{-j,-i}&=0.\label{SS6.5}
\end{align}
In particular, we have $S^{(1)}_{i,-i}=0$.
\item The following relations hold:
\begin{align}
[S^{(1)}_{i,j},S^{(r)}_{k,l}]&=\delta_{i,k}S^{(r)}_{i,l}-\delta_{i,l}S^{(r)}_{k,j}-\delta_{k,-i}S^{(1)}_{-j,l}+\delta_{-j,l}S^{(r)}_{k,-i}\text{ for }r=1,2,3,\label{SS1}\\
[S^{(2)}_{i,i},S^{(2)}_{j,j}]&=\hbar S^{(1)}_{j,i}S^{(2)}_{i,j}-\hbar S^{(2)}_{j,i}S^{(1)}_{i,j}-\hbar S^{(1)}_{i,-j}S^{(2)}_{-i,j}+\hbar S^{(2)}_{j,-i}S^{(1)}_{-j,i}\text{ for }i,j>0,\label{SS3}\\
[S^{(2)}_{n-1,n},S^{(2)}_{n,n-1}]&=S^{(3)}_{n-1,n-1}-S^{(3)}_{n,n}+\hbar S^{(1)}_{n,n}S^{(2)}_{n-1,n-1}-\hbar S^{(2)}_{n,n}S^{(1)}_{n-1,n-1}\nonumber\\
&\quad-\hbar S^{(1)}_{n-1,-n}S^{(2)}_{-n,n-1}+\hbar S^{(2)}_{n-1,-n}S^{(1)}_{-n+1,n}.\label{SS4}
\end{align}
\end{enumerate}
\end{Lemma}
\begin{Definition}
The twisted Yangian associated with $\mathfrak{so}(2n)$ is the subalgebra generated by $\{S^{(r)}_{i,j}\mid r\geq0,i,j\in\{\pm1,\pm2,\cdots,\pm n\}\}$.
\end{Definition}
We denote the twisted Yangian associated with $\mathfrak{so}(2n)$ by $\widetilde{TY}_\hbar(\mathfrak{so}(2n))$. Let us set the degree of $\widetilde{TY}_\hbar(\mathfrak{so}(2n))$ by $\text{deg}(S^{(r)}_{i,j})=r-1$ for $r\geq1$. Then, $\widetilde{TY}_\hbar(\mathfrak{so}(2n))$ becomes a filtered algebra. We denote the graded associative algebra of $\widetilde{TY}_\hbar(\mathfrak{so}(2n))$ by $\text{gr}\widetilde{TY}_\hbar(\mathfrak{so}(2n))$.
\begin{Theorem}[Proposition 2.23 in \cite{MNO}]\label{gra}
The graded algebra $\text{gr}\widetilde{TY}_\hbar(\mathfrak{so}(2n))$ is isomorphic to $U(\mathfrak{sl}(2n)[u]^\tau)$.
\end{Theorem}
\section{New presentation of the twisted Yangian of type $D$}
We give a finite presentation of the twisted Yangian of type $D$.
\begin{Definition}\label{fin.pre}
We define $TY_\hbar(\mathfrak{so}(2n))$ as the associative algebra generated by
\begin{equation*}
\{H_{i,0},H_{j,1},X^\pm_{i,r}\mid 1\leq i\leq n,1\leq j\leq n-1,r=0,1\}
\end{equation*}
with the defining relations:
\begin{gather}
[H_{i,r},H_{j,s}]=0\text{ if }0\leq r,s\leq1,\label{q901}\\
[H_{i,0},X^\pm_{j,0}]=\pm a_{i,j}X^\pm_{j,0},\label{q901-1-1}\\
[H_{i,1}-\dfrac{\hbar}{2}H_{i,0}^2,X^\pm_{j,0}]=\pm a_{i,j}X^\pm_{j,1},\label{q901-1}\\
[X^+_{i,0},X^-_{j,0}]=\delta_{i,j}H_{i,0},\label{q901-2--1}\\
[X^+_{i,1},X^-_{i,0}]=H_{i,1}\text{ if }i\neq n\label{q901-2-0}\\
[X^+_{n,1},X^-_{n,0}]=H_{n-1,1}-\dfrac{\hbar}{4}(H_{n-1,0}^2-H_{n,0}^2)+\hbar X^-_{n-1,0}X^+_{n-1,0},\label{q901-3}\\
[X^\pm_{i,1},X^\pm_{i,0}]=\hbar(X^\pm_{i,0})^2,\label{q901-10}\\
[X^\pm_{i,0},X^\pm_{j,0}]=0\text{ if }a_{i,j}=0,\label{q901-17}\\
[X^\pm_{i,0},[X^\pm_{i,0},X^\pm_{j,0}]]=0\text{ if }a_{i,j}=-1,\label{q902}\\
[[X^+_{n,0},X^+_{n-2,0}],[X^+_{n,0},X^+_{n-1,1}]]=\hbar X^+_{n,0}[X^+_{n-2,0},[X^+_{n-1,0},X^+_{n,0}]],\label{q903-3}\\
[[X^-_{n,0},X^-_{n-2,0}],[X^-_{n,0},X^-_{n-1,1}]]=-\hbar [X^-_{n-2,0},[X^-_{n-1,0},X^-_{n,0}]]X^-_{n,0},\label{q903-3-}\\
[[X^+_{n-1,0},X^+_{n-2,0}],[X^+_{n-1,0},X^+_{n,1}]]=-\hbar [X^+_{n-2,0},[X^+_{n-1,0},X^+_{n,0}]]X^+_{n-1,0},\label{q903-7}\\
[[X^-_{n-1,0},X^-_{n-2,0}],[X^-_{n-1,0},X^-_{n,1}]]=\hbar X^-_{n-1,0}[X^-_{n-2,0},[X^-_{n-1,0},X^-_{n,0}]]\label{q903-7-}
\end{gather}
and
\begin{align}
&\quad[[X^+_{n-1,1},X^-_{n-1,1}],X^+_{n,0}]\nonumber\\
&=-2(n-1)\hbar [H_{n-1,1},X^+_{n,0}]-2\hbar X^+_{n,1}H_{n-1,0}-2(n-1)\hbar^2 X^+_{n,0}(H_{n-1,0}+ H_{n,0})\nonumber\\
&\quad+(4n-4)\hbar X^+_{n,1}+6(n-1)\hbar^2 X^+_{n,0},\label{q901-2-1}\\
&\quad[[X^+_{n-1,1},X^-_{n-1,1}],X^-_{n,0}]\nonumber\\
&=-2(n-1)\hbar [H_{n-1,1},X^-_{n,0}]+2\hbar H_{n-1,0}X^-_{n,1}+2(n-1)\hbar^2 (H_{n-1,0}+ H_{n,0})X^-_{n,0}\nonumber\\
&\quad-(4n-4)\hbar X^-_{n,1}-6(n-1)\hbar^2 X^-_{n,0},\label{q901-2-1-}\\
&\quad[X^+_{n,1},[X^+_{n-2,0},X^+_{n-1,0}]]-[[X^+_{n,1},X^+_{n-2,0}],X^+_{n-1,0}]\nonumber\\
&=-(n-1)\hbar[X^+_{n-2,0},[X^+_{n-1,0},X^+_{n,0}]]+\hbar X^+_{n-1,0}[X^+_{n-2,0},X^+_{n,0}]+\hbar X^+_{n,0}[X^+_{n-2,0},X^+_{n-1,0}],\label{q903-1}\\
&\quad[X^-_{n,1},[X^-_{n-2,0},X^-_{n-1,0}]]-[[X^-_{n,1},X^-_{n-2,0}],X^-_{n-1,0}]\nonumber\\
&=-(n-1)\hbar[X^-_{n-2,0},[X^-_{n-1,0},X^-_{n,0}]]+\hbar [X^-_{n-2,0},X^-_{n,0}]X^-_{n-1,0}-\hbar [X^-_{n-2,0},X^-_{n-1,0}]X^-_{n,0}.\label{q903-1-}
\end{align}
\end{Definition}
We can connect $TY_\hbar(\mathfrak{so}(2n))$ with the twisted Yangian $\widetilde{TY}_\hbar(\mathfrak{so}(2n))$.
\begin{Theorem}\label{Main}
There exits a homomorphism $\Phi\colon TY_\hbar(\mathfrak{so}(2n))\to \widetilde{TY}_\hbar(\mathfrak{so}(2n))$ given by
\begin{align*}
\Phi(H_{i,1})&=-S^{(2)}_{i,i}+S^{(2)}_{i+1,i+1}-\dfrac{i+n-1}{2}\hbar(S^{(1)}_{i,i}-S^{(1)}_{i+1,i+1})-\hbar S^{(1)}_{i,i}S^{(1)}_{i+1,i+1}\\
&\quad+\hbar\sum_{a\in I_i}S^{(1)}_{i,a}S^{(1)}_{a,i}-\hbar\sum_{a\in I_i}S^{(1)}_{i+1,a}S^{(1)}_{a,i+1},\\
\Phi(X^+_{i,1})&=\begin{cases}
-S^{(2)}_{i,i+1}-\dfrac{i+n-1}{2}\hbar S^{(1)}_{i,i+1}+\hbar\sum_{a\in I_i}S^{(1)}_{i,a}S^{(1)}_{a,i+1}&\text{ if }1\leq i\leq n-1,\\
-S^{(2)}_{n-1,-n}-(n-1)\hbar S^{(1)}_{n-1,-n}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}&\text{ if }i=n,
\end{cases}\\ 
\Phi(X^-_{i,1})&=\begin{cases}
-S^{(2)}_{i,i+1}-\dfrac{i+n-1}{2}\hbar S^{(1)}_{i,i+1}+\hbar\sum_{a\in I_i}S^{(1)}_{i,a}S^{(1)}_{a,i+1}&\text{ if }1\leq i\leq n-1,\\
-S^{(2)}_{-n,n-1}-(n-1)\hbar S^{(1)}_{-n,n-1}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{-n,a}S^{(1)}_{a,n-1}&\text{ if }i=n.
\end{cases}
\end{align*}
\end{Theorem}
The proof of Theorem~\ref{Main} is given in the appendix.
\begin{Theorem}
The homomorphism $\Phi$ is an isomorphism.
\end{Theorem}
\begin{proof}
Let us take a grading of $TY_\hbar(\mathfrak{so}(2n))$ by $\text{deg}(H_{i,r})=\text{deg}(X^\pm_{i,r})=r$. Then, $TY_\hbar(\mathfrak{so}(2n))$ becomes a filtered algebra. We denote the graded associated algebra of the twisted Yangian $TY_\hbar(\mathfrak{so}(2n))$ by $grTY_\hbar(\mathfrak{so}(2n))$. Since $\Phi$ is a homomorphism of filtered algebras, $\Phi$ induces a homomorphism 
\begin{gather*}
gr\Phi\colon grTY_\hbar(\mathfrak{so}(2n))\to gr\widetilde{TY}_\hbar(\mathfrak{so}(2n))=U(\mathfrak{sl}(2n)[u]^\tau).
\end{gather*}
By the definition of $\Phi$, we have
\begin{align*}
gr\Phi(H_{i,r})&=H_{i,r},\ gr\Phi(X^\pm_{i,r})=X^\pm_{i,r}.
\end{align*}
Since $U(\mathfrak{sl}(2n)[u]^\tau)$ is generated by $H_{i,r},X^\pm_{i,r}$, $gr\Phi$ is surjective. By the definition of $TY_\hbar(\mathfrak{so}(2n))$, \eqref{eq901}-\eqref{eq903-7} hold in $grTY_\hbar(\mathfrak{so}(2n))$. By Theorem~\ref{Mini}, $gr\Phi$ is injective.
Since $gr\Phi$ is an isomorphism, $\Phi$ also becomes an isomorphism.
\end{proof}

\section{Suggestion of a definition of the twisted affine Yangian of type $D$}
Guay \cite{Gu1} defined the affine Yangian associated with $\widehat{\mathfrak{sl}}(n)$ by extending the minimalistic presentation of the Yangian associated with $\mathfrak{sl}(n)$. Similarly, we expect that the twisted affine Yangian of type $D$ can be defined by extending the presentation given in Theorem~\ref{fin.pre}. 

The Cartan matrix of $\widehat{\mathfrak{so}}(2n)$ is given by $A_{i,j}=\begin{cases}
2\delta_{i,j}-\delta_{i,j+1}-\delta_{i+1,j}&\text{ if }1\leq i,j\leq n-1,\\
2\delta_{i,j}-\delta_{i,n-2}-\delta_{j,n-2}&\text{ if }i\text{ or }j=n,\\
2\delta_{i,j}-\delta_{i,2}-\delta_{j,2}&\text{ if }i\text{ or }j=0
\end{cases}$
for $0\leq i,j\leq n$.
\begin{Definition}
We define $TY_\hbar(\widehat{\mathfrak{so}}(2n))$ as the associative algebra generated by
\begin{equation*}
\{H_{i,0},H_{j,1},X^\pm_{i,r}\mid 0\leq i\leq n,1\leq j\leq n-1,r=0,1\}
\end{equation*}
with the defining relations \eqref{q901}, \eqref{q901-2--1},\eqref{q901-3}, \eqref{q901-10}, \eqref{q901-17}-\eqref{q903-1-} and
\begin{gather}
[H_{i,0},X^\pm_{j,0}]=\pm A_{i,j}X^\pm_{j,0},\label{Q901-1-1}\\
[H_{i,1}-\dfrac{\hbar}{2}H_{i,0}^2,X^\pm_{j,0}]=\pm A_{i,j}X^\pm_{j,1},\label{Q901-1}\\
[X^+_{i,1},X^-_{i,0}]=H_{i,1}\text{ if }i\neq 0,n\label{Q901-2-0}\\
[X^+_{0,1},X^-_{0,0}]=H_{1,1}-\dfrac{\hbar}{4}(H_{1,0}^2-H_{0,0}^2)+\hbar X^-_{1,0}X^+_{1,0},\label{Q901-3}\\
[[X^+_{0,0},X^+_{2,0}],[X^+_{0,0},X^+_{1,1}]]=\hbar X^+_{0,0}[X^+_{2,0},[X^+_{1,0},X^+_{0,0}]],\label{Q903-3}\\
[[X^-_{0,0},X^-_{2,0}],[X^-_{0,0},X^-_{1,1}]]=-\hbar [X^-_{2,0},[X^-_{1,0},X^-_{0,0}]]X^-_{0,0},\label{Q903-3-}\\
[[X^+_{1,0},X^+_{2,0}],[X^+_{1,0},X^+_{0,1}]]=-\hbar [X^+_{2,0},[X^+_{1,0},X^+_{0,0}]]X^+_{1,0},\label{Q903-7}\\
[[X^-_{1,0},X^-_{2,0}],[X^-_{1,0},X^-_{0,1}]]=\hbar X^-_{1,0}[X^-_{2,0},[X^-_{1,0},X^-_{0,0}]]\label{Q903-7-}
\end{gather}
and
\begin{align}
&\quad[[X^+_{1,1},X^-_{1,1}],X^+_{0,0}]\nonumber\\
&=-2\hbar [H_{1,1},X^+_{0,0}]-2\hbar X^+_{0,1}H_{1,0}-2\hbar^2 X^+_{0,0}(H_{1,0}+ H_{0,0})\nonumber\\
&\quad+4\hbar X^+_{0,1}+6\hbar^2 X^+_{0,0},\label{Q901-2-1}\\
&\quad[[X^+_{1,1},X^-_{1,1}],X^-_{0,0}]\nonumber\\
&=-2\hbar [H_{1,1},X^-_{0,0}]+2\hbar H_{1,0}X^-_{0,1}+2\hbar^2 (H_{1,0}+ H_{0,0})X^-_{0,0}\nonumber\\
&\quad-4\hbar X^-_{0,1}-6\hbar^2 X^-_{0,0},\label{Q901-2-1-}\\
&\quad[X^+_{0,1},[X^+_{2,0},X^+_{1,0}]]-[[X^+_{0,1},X^+_{2,0}],X^+_{1,0}]\nonumber\\
&=-\hbar[X^+_{2,0},[X^+_{1,0},X^+_{0,0}]]+\hbar X^+_{1,0}[X^+_{2,0},X^+_{0,0}]+\hbar X^+_{0,0}[X^+_{2,0},X^+_{1,0}],\label{Q903-1}\\
&\quad[X^-_{0,1},[X^-_{2,0},X^-_{1,0}]]-[[X^-_{0,1},X^-_{2,0}],X^-_{1,0}]\nonumber\\
&=-\hbar[X^-_{2,0},[X^-_{1,0},X^-_{0,0}]]+\hbar [X^-_{2,0},X^-_{0,0}]X^-_{1,0}-\hbar [X^-_{2,0},X^-_{1,0}]X^-_{0,0}.\label{Q903-1-}
\end{align}
\end{Definition}
The Dynkin diagram of $\widehat{\mathfrak{so}}(2n)$ can be regarded as a combination of two Dynkin diagrams of $\mathfrak{so}(2n)$. Thus, we can propose the following conjecture.
\begin{Conjecture}
The associative algebra $TY_\hbar(\widehat{\mathfrak{so}}(2n))$ becomes a coideal of the affine Yangian associated with $\widehat{\mathfrak{sl}}(n)$ and can be regarded as the twisted affine Yangian of type $D$.
\end{Conjecture}
