\end{Lemma}
\begin{proof}
First, we show the relation \eqref{Eq903-9.5}. By the definition of $X_{i,j,r}$, we can rewrite $X_{i,j,r}=\prod_{u=i}^{j-2}\ad(X^+_{u,0})X^+_{j-1,r}$. Thus, \eqref{Eq903-9.5} follows from \eqref{Eq901-17} and the assumption that $j\leq n-2$.

Next, we show the relation \eqref{Eq903-12}. We obtain
\begin{align*}
&\quad[X_{i,n-1,0},[X^+_{n-2,r},X^+_{n,s}]]=[[X_{i,n-3,0},X_{n-3,,n-1,0}],[X^+_{n-2,r},X^+_{n,s}]]\\
&=[X_{i,n-3,0},[[X^+_{n-3,0},X^+_{n-2,0}],[X^+_{n-2,r},X^+_{n,s}]]=0,
\end{align*}
where the first equality is due to \eqref{gat1}, the second equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, and the third equality is due to \eqref{Eq903-13} and \eqref{Eq901-10}.

Next, we show the relation \eqref{Eq903-9}. The following relation holds:
    \begin{align}
        &\phantom{{}={}} [X_{i,n-1,0},[X_{i,n,0}, X^+_{n,2r}]]
        = [X_{i,n-1,0}, [[X_{i,n-1,0}, X^+_{n-1,0}],X^+_{n,2r}]]\nonumber \\
        &{}= [X_{i,n-1,0}, [[X_{i,n-1,0},X^+_{n,2r}], X^+_{n-1,0}]]\nonumber \\
        &{}= [[X_{i,n-1,0}, [X_{i,n-1,0}, X^+_{n,2r}]], X^+_{n-1,0}]
            + [[X_{i,n-1,0}, X^+_{n,2r}], [X_{i,n-1,0}, X^+_{n-1,0}]],\label{first1}
    \end{align}
where the first equality is due to \eqref{gat1}, the second equality is due to \eqref{Eq901-17-1} and the third equality is due to the Jacobi identity.
Here after, we denote the $i$-th term of the right hand side of the equality $(\cdot)$ by $(\cdot)_i$. We obtain
\begin{align*}
\eqref{first1}_1&=
[[X^+_{n-2,0}, [X^+_{n-2,0}, X^+_{n,2r}]], X^+_{n-1,0}]=0.
\end{align*}
by \eqref{Eq902} if $i=n-2$ and
\begin{align*}
\eqref{first1}_1
&=[[X_{i,n-1,0}, [[X_{i,n-2,0},X^+_{n-2,0}], X^+_{n,2r}]], X^+_{n-1,0}]\\
&=[[X_{i,n-2,0},[X_{i,n-1,0}, [X^+_{n-2,0}, X^+_{n,2r}]]], X^+_{n-1,0}]=0
\end{align*}
if $i<n-2$, where the first equality is due to \eqref{gat1}, the second equality is due to the assumption of $i$ and \eqref{Eq903-9.5}, and the last equality is due to \eqref{Eq903-12}.
By \eqref{gat1}, we have
\begin{align*}
\eqref{first1}_2&=[[X_{i,n-1,0}, X^+_{n,2r}], X_{i,n,0}]=-[X_{i,n-1,0},[X_{i,n,0}, X^+_{n,2r}]].
\end{align*}
Hence, we obtain the relation $[X_{i,n-1,0},[X_{i,n,0}, X^+_{n,2r}]] = -[X_{i,n-1,0},[X_{i,n,0}, X^+_{n,2r}]]$, which means that $[X_{i,n-1,0},[X_{i,n,0}, X^+_{n,2r}]]=0$.

Next, we show the relation \eqref{Eq903-10}. The cases that $j=n-2,n-1$ directly follows from \eqref{Eq903-19} and \eqref{Eq901-10}. Thus, it is enugh to show the case that $j \leq n-3$. 
The following relation holds for $j\leq n-3$:
    \begin{align*}
        &\phantom{{}={}} [X_{j,n,s}, X^+_{n,r}]
        = [[X_{j,n-2,0}, [X^+_{n-2,0}, X^+_{n-1,s}]], X^+_{n,r}] \\
        &{}= (-1)^s[X_{j,n-2,0}, [[X^+_{n-2,0}, X^+_{n-1,0}], X^+_{n,r+s}]]
        = (-1)^s[X_{j,n,0}, X^+_{n,r}],
    \end{align*}
where the first equality is due to \eqref{gat1} and the second equality is due to \eqref{Eq903-9.5} and \eqref{Eq903-19}.
We can prove \eqref{Eq903-11} by the similar way to \eqref{Eq903-10}.

Next, we show \eqref{Eq903-14-0}. In the case that $i=j=n-2$, the relation follows from \eqref{Eq902}. In the case that $i<j=n-2$, we have
\begin{align*}
&\quad[X_{i,n-1,s},[X_{j,n-1,0},X_{n,r}]]=[X_{i,n-1,s},[X^+_{n-2,0},X_{n,r}]]\\
&=[[X_{i,n-3,0},X_{n-3,n-1,s}],[X^+_{n-2,0},X_{n,r}]]=[X_{i,n-3,0},[[X^+_{n-3,0},X^+_{n-2,0}],[X^+_{n-2,0},X^+_{n,r}]]]=0,
\end{align*}
where the second equality is due to \eqref{gat1}, the third equality is due to \eqref{gat1} and \eqref{Eq903-9.5} and the last equality is due to \eqref{Eq903-13}.

Suppose $i\leq j<n-2$. Then, we obtain
\begin{align*}
&\quad[X_{i,n-1,s},[X_{j,n-1,0},X_{n,r}]]=[X_{i,n-1,s},[[X_{j,n-2,0},X^+_{n-1,0}],X_{n,r}]]\\
&=[X_{j,n-2,0},[X_{i,n-1,s},[X^+_{n-1,0},X_{n,r}]]]=[X_{j,n-2,0},[[X_{i,n-2,0},X^+_{n-1,s}],[X^+_{n-1,0},X_{n,r}]]]\\
&=[X_{j,n-2,0},[X_{i,n-2,0},[X^+_{n-1,s},[X^+_{n-1,0},X_{n,r}]]]]=0,
\end{align*}
where the first and third equalities are due to \eqref{gat1}, the second and 4th equalities are due to \eqref{gat1} and \eqref{Eq903-9.5}, and the last equality is due to \eqref{Eq901-17-1} and \eqref{Eq901-17-2}.

Next, we show \eqref{Eq903-14}. By \eqref{gat1} and the Jacobi identity, we obtain
    \begin{align}
        &\phantom{{}={}} [X_{i,n,0}, [X_{j-1,n-1,0}, X^+_{n,r}]] 
        = [[X_{i,n-1,0}, X^+_{n-1,0}], [X_{j-1,n-1,0}, X^+_{n,r}]]\nonumber\\
        &{}= [[X_{i,n-1,0}, [X_{j-1,n-1,0}, X^+_{n,r}]], X^+_{n-1,0}]-[X_{i,n-1,0}, [[X_{j-1,n-1,0}, X^+_{n,r}], X^+_{n-1,0}]].\label{first2}
    \end{align}
By \eqref{Eq903-14-0}, we find that $\eqref{first2}_1$ is $0$. We also obtain
\begin{align*}
\eqref{first2}_2&=-[X_{i,n-1,0}, [[[X_{j-1,n-2,0},X^+_{n-2,0}], X^+_{n,r}], X^+_{n-1,0}]]\\
&=-[X_{i,n-1,0},[X_{j-1,n-2,0},[[X^+_{n-2,0},X^+_{n,r}],X^+_{n-1,0}]]]\\
&=-(-1)^r[X_{i,n-1,0},[X_{j-1,n-2,0},[[X^+_{n-2,0},X^+_{n-1,0}],X^+_{n,r}]]]\\
&=-(-1)^r[X_{i,n-1,0},[X_{j-1,n,0},X^+_{n,r}]],
\end{align*}
where the first equality is due to \eqref{gat1}, the second equality and last equalities are due to \eqref{Eq903-9.5} and \eqref{gat1}, and the third equality is due to \eqref{Eq903-1}.

Next, we show the relation \eqref{Eq903-18}. In the case that $i=j=n-2$, \eqref{Eq903-18} follows from \eqref{Eq903-8.5} and \eqref{gat1}. We will show other cases.

By \eqref{gat1} and \eqref{Eq903-10}, we have
\begin{align*}
[X_{i,n,s},[X_{j,n,0},X^+_{n,r}]]&=[X_{j,n,0},[X_{i,n,s},X^+_{n,r}]]=(-1)^s[X_{j,n,0},[X_{i,n,0},X^+_{n,r+s}]].
\end{align*}
Thus, it is enough to show the case that $s=0$ and $i\leq j$. 
By \eqref{Eq901-17} and \eqref{gat1}, we have
\begin{align*}
[X_{i,n,0},[X_{j,n,0},X^+_{n,r}]]=\prod_{u=i}^{j-2}\ad(X^+_{u,0})[X_{j-1,n,0},[X_{j,n,0},X^+_{n,r}]]
\end{align*}
if $i+2\leq j$ and
\begin{align*}
[X_{i,n,0},[X_{i,n,0},X^+_{n,r}]]=\ad(X^+_{i,0})[X_{i,n,0},[X_{i+1,n,0},X^+_{n,r}]]
\end{align*}
if $i=j<n-2$. Thus, it is enough to show \eqref{Eq903-17} by induction on $j$ only for the case $i = j - 1$. The case $j = n-2$ immediately follows from \eqref{Eq903-8}. 
    For $j = n-3$, we obtain
    \begin{align*}
        &\phantom{{}={}} [X_{n-4,n,s}, [X_{n-3,n,0}, X^+_{n,r}]] \\
        &{}= [[X_{n-4,n-2,s}, X_{n-2,n,0}], [[X_{n-3,n-1,0}, X^+_{n-1,0}], X^+_{n,r}]] \\
        &{}= [X_{n-4,n-2,s}, [[X_{n-3,n-1,0}, X^+_{n-1,0}], [X_{n-2,n,0}, X^+_{n,r}]]] = 0,     
    \end{align*}
    where the first and second equalities are due to \eqref{gat1}, the third equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, and the last equality is due to \eqref{Eq903-8}.

    If $ [X_{j+1,n,0}, [X_{j+2,n,0}, X^+_{n,r}]] = 0 $ holds for $j+2 < n-1$, then we have 
    \begin{align*}
        &\phantom{{}={}} [X_{j-1,n,s}, [X_{j,n,0}, X^+_{n,r}]] \\
        &{}= [[X_{j-1,j+1,s}, X_{j+1,n,0}], [X_{j,j+2,0},[X_{j+2,n,0}, X^+_{n,r}]]] \\
        &{}= [X_{j-1,j+1,s}, [X_{j+1,n,0}, [X_{j,j+2,0}, [X_{j+2,n,0}, X^+_{n,r}]]]] \\
        &{}= [X_{j-1,j+1,s}, [X_{j,j+2,0}, [X_{j+1,n,0}, [X_{j+2,n,0}, X^+_{n,r}]]]] = 0,
    \end{align*}
where the first equality is due to \eqref{gat1}, the second equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, and the last equality is due to the induction hypothesis.

Next, we show the relation \eqref{Eq903-20}. The following relations hold:
\begin{align*}
&\quad[X_{i,n,s},[X_{j,n-1,0},X^+_{n,r}]]=[X_{j,n-1,0},[X_{i,n,s},X^+_{n,r}]]\\
&=(-1)^s[X_{j,n-1,0},[X_{i,n,0},X^+_{n,r+s}]]=(-1)^s[X_{i,n,0},[X_{j,n-1,0},X^+_{n,r+s}]],
\end{align*}
where the first equality is due to \eqref{gat1}, the second equality is due to \eqref{Eq903-10}, and the last equality is due to \eqref{gat1}. The relation \eqref{Eq903-21} can be proven in a similar way.

Next, we show the relation \eqref{Eq903-22} and \eqref{Eq903-23}. 
The following relation holds:
\begin{align*}
&\quad[X_{i,n-1,0},[X^+_{n-2,s},X^+_{n,r}]]=[[X_{i,n-3,0},X_{n-3,n-1,0}],[X^+_{n-2,s},X^+_{n,r}]]\\
&=[X_{i,n-3,0},[X_{n-3,n-1,0},[X^+_{n-2,s},X^+_{n,r}]]]=0,
\end{align*}
where the first equality is due to \eqref{gat1}, the second equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, and the last equality is due to \eqref{Eq903-13}.
By \eqref{Eq902}, we also obtain 
\begin{align*}
&\quad0=[[X_{i,n-1,0},[X^+_{n-2,s},X^+_{n,r}]],X^+_{n-1,0}]=[X_{i,n,0},[X^+_{n-2,s},X^+_{n,r}]].
\end{align*}

Finally, we show \eqref{Eq903-18-2} by induction on $i$. 
The case $i = n-1,n-2$ follows from \eqref{Eq901-17-1},\eqref{Eq901-17-2} and \eqref{Eq903-8.5}. 

    Suppose $[X_{i+1,n,0}, [X_{i+1,n,0}, X^+_{n,r}]] = 0$ holds for $i + 1 \leq n-2$.
    From \eqref{gat1}, we have 
    $X_{i,n,0} = [X_{i,i+1,0}, X_{i+1,n,0}]$ and 
    $[X_{i,n,0}, X_{i,i+1,0}] = 0$. 
    By the Jacobi identity, we have
    \begin{align*}
        &\phantom{{}={}} [X_{i,n,0}, [X_{i,n,0}, X^+_{n,r}]]
        = [X_{i,n,0}, [[X_{i,i+1,0}, X_{i+1,n,0}], X^+_{n,r}]] \\
        &{}= [X_{i,n,0}, [X_{i,i+1,0}, [X_{i+1,n,0}, X^+_{n,r}]]]
        = [X_{i,i+1,0}, [X_{i,n,0}, [X_{i+1,n,0}, X^+_{n,r}]]]
        = 0
    \end{align*}
    using \eqref{Eq903-9.5} and \eqref{Eq903-18} in the second and last equality respectively. 
\end{proof}
We also need to prepare a new presentation of $X_{i,-j,r}$ and $X_{i,-i,2r+1}$.
By \eqref{gat1} and the definition of $X_{i,-j,r}$, we have
\begin{align*}
    X_{i,-j,r} =
    \begin{cases}
        [X_{i,n,0},[X_{j,n-1,0},X^+_{n,r}]] & \text{ if } j\leq n-3 \text{ and } j-n \text{ is odd}, \\
        [X_{i,n-1,0},[X_{j,n,0},X^+_{n,r}]] & \text{ if } j\leq n-2 \text{ and } j-n \text{ is even}, \\
        [X_{i,n,0},X^+_{n,r}] & \text{ if } j=n-1, \\
        [X_{i,n-1,0},X^+_{n,r}] & \text{ if } j=n \text{ and } i < n-1
    \end{cases}
\end{align*}
and
\begin{align*}
    X_{i,-i,2r+1} = 
    \begin{cases}
        [X_{i,n,0}, [X_{i,n-1,0}, X^+_{n,2r+1}]] & \text{ if } i \leq n-2, \\
        [X^+_{n-1,0}, X^+_{n,2r+1}] & \text{ if } i = n-1.
    \end{cases}
\end{align*}
Now, we can complete the proof of Lemma~\ref{gat}
\subsection{Proof for $[X^+_{n,s},X_{i,j,r}]$}
From \eqref{Eq901-10-0}, \eqref{Eq901-10} and \eqref{Eq903-1}, we have
\begin{align*}
    &\phantom{{}={}} \left[ X^+_{n,s}, X_{i,j,r} \right]\\
    &{}= \delta_{j,n-1} \left(\prod_{u=i}^{n-3} \ad(X^+_{u,0}) \right)
    \left[X^+_{n,s}, X^+_{n-2,r}\right]
    + \delta_{j,n} \left( \prod_{u=i}^{n-3} \ad(X^+_{u,0}) \right)
    \left[X^+_{n,s} \left[X^+_{n-2,0}, X^+_{n-1,r}\right]\right] \\
    &{}= \delta_{j,n-1} \left(\prod_{u=i}^{n-3} \ad(X^+_{u,0}) \right)
    \left[X^+_{n,s}, X^+_{n-2,r}\right]\\
  &{}-(-1)^r \delta_{j,n} \left( \prod_{u=i}^{n-3} \ad(X^+_{u,0}) \right)
    \left[\left[X^+_{n-2,0}, X^+_{n-1,0}\right],X^+_{n-2,r+s}]\right] \\
    &{}= -\delta_{j,n-1} X_{i,-n,r+s}
    -(-1)^r \delta_{j,n} X_{i,-n+1,r+s},
\end{align*}
where the first equality is due to \eqref{Eq901-17} and the second equality is due to \eqref{Eq903-19}. Thus, $[X^+_{n,s},X_{i,j,r}]$ can be spanned by the given set.

\subsection{Proof for $[X^+_{p,s},X_{i,-j,r}]$}
We show the statement for each of the cases $p \leq n-3$, $p = n-2$ and $p = n-1$.

First, we show the case that $p\leq n-3$. Suppose that $p \leq n-3$. 
For the case $j \leq n-3$ and $j - n$ is odd, we have 
\begin{align*}
    &\phantom{{}={}} [X^+_{p,s}, X_{i,-j,r}]
    = [X_{p,p+1,s}, [X_{i,n,0}, [X_{j,n-1,0}, X^+_{n,r}]]] \nonumber\\
    &{}= \delta_{p+1, i} [X_{i-1,n,s}, [X_{j,n-1,0}, X^+_{n,r}]]
        + \delta_{p+1, j} [X_{i,n,0}, [X_{j-1,n-1,s}, X^+_{n,r}]]\\
    &{}= \delta_{p+1, i} [X_{i-1,n,s}, [X_{j,n-1,0}, X^+_{n,r}]]
        + \delta_{p+1, j} [X_{i,n,0}, [X_{j-1,n-1,0}, X^+_{n,r+s}]]\\
    &{}=\delta_{p+1, i}(-1)^s [X_{i-1,n,0}, [X_{j,n-1,0}, X^+_{n,r+s}]]-(-1)^{r+s}\delta_{p+1, j} [X_{i,n-1,0}, [X_{j-1,n,0}, X^+_{n,r+s}]],
\end{align*}
where the second equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, the third equality is due to \eqref{Eq903-11}, and the last equality is due to \eqref{Eq901-10-0}, \eqref{Eq903-14} and \eqref{Eq903-20}.
Thus, we have proved this case.

For the case $j \leq n-2$ and $j - n$ is even, we have
\begin{align*}
    &\phantom{{}={}} [X^+_{p,s}, X_{i,-j,r}]
    = [X_{p,p+1,s}, [X_{i,n-1,0}, [X_{j,n,0}, X^+_{n,r}]]] \\
    &{}= \delta_{p+1,i} [X_{i-1,n-1,s}, [X_{j,n,0}, X^+_{n,r}]]
        + \delta_{p+1,j} [X_{i,n-1,0}, [X_{p,n,s}, X^+_{n,r}]] \\
    &{}= \delta_{p+1,i} [X_{i-1,n-1,0}, [X_{j,n,0}, X^+_{n,r+s}]]+ (-1)^s\delta_{p+1,j} [X_{i,n-1,0},[X_{j-1,n,0}, X^+_{n,r+s}]] \\
    &{}= \delta_{p+1,i} [X_{i-1,n-1,0}, [X_{j,n,0}, X^+_{n,r+s}]]+ (-1)^s\delta_{p+1,j} [X_{i,n,0},[X_{j-1,n-1,0}, X^+_{n,r+s}]] \\
    &{}= \delta_{p+1,i} X_{i-1,-j,r+s}+ (-1)^s\delta_{p+1,j} X_{i,-j+1,r+s},
\end{align*}
where the second equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, the third equality is due to \eqref{Eq903-21} and \eqref{Eq903-10}, and the 4-th equality is due to \eqref{Eq903-1}.

For the case $j = n-1$, we obtain
\begin{align*}
    &\phantom{{}={}} [X^+_{p,s}, X_{i,-j,r}]
    = [X_{p,p+1,s}, [X_{i,n,0}, X^+_{n,r}]] \\
    &{}= \delta_{p+1,i} [X_{i-1,n,s}, X^+_{n,r}]
    = (-1)^s\delta_{p+1,i} X_{i-1, -n+1, r+s}
\end{align*}
by \eqref{gat1}, \eqref{Eq903-9.5} and \eqref{Eq903-10}. 

For the case $j=n$, we have
\begin{align*}
    &\phantom{{}={}} [X^+_{p,s}, X_{i,-j,r}]
    = [X_{p,p+1,s}, [X_{i,n-1,0}, X^+_{n,r}]] \\
    &{}= \delta_{p+1,i} [X_{p,n-1,s}, X^+_{n,r}] = \delta_{p+1,i} X_{i-1,-n,r+s}
\end{align*}
from \eqref{gat1}, \eqref{Eq903-9.5} and \eqref{Eq903-11}.
Thus, the statement is true for every $p \leq n-3$.

Next, we show the case that $p=n-2$. Suppose that $p=n-2$. 
For the case $j \leq n-3$ and $j - n$ is odd, we have 
\begin{align*}
    &\phantom{{}={}} [X^+_{n-2,s}, X_{i,-j,r}]
    = [X^+_{n-2,s}, [X_{i,n,0}, [X_{j,n-1,0}, X^+_{n,r}]]] \\
    &{}= [X_{i,n,0}, [X_{j,n-1,0}, [X^+_{n-2,s}, X^+_{n,r}]]] = 0,
\end{align*}
where the second equality is due to \eqref{gat1} and the assumption that $j\leq n-3$ and the third equality is due to \eqref{Eq903-12}.

For the case $j \leq n-2$ and $j - n$ is even, 
\begin{align*}
    &\phantom{{}={}} [X^+_{n-2,s}, X_{i,-j,r}]
    = [X^+_{n-2,s}, [X_{i,n-1,0}, [X_{j,n,0}, X^+_{n,r}]]] \\
    &{}=  [X_{j,n,0},[X_{i,n-1,0}, [X^+_{n-2,0}, X^+_{n,r}]]] = 0,
\end{align*}
where the second equality is due to \eqref{gat1} and the assumption that $j\leq n-3$, and the last equality is due to \eqref{Eq903-22} and \eqref{gat1}.

For the case $j = n-1$, we obtain 
\begin{align*}
    &\phantom{{}={}} [X^+_{n-2,s}, X_{i,-(n-1),r}]
    = [X_{i,n,0}, [X^+_{n-2,s}, X^+_{n,r}]] \\
    &{}= \delta_{i,n-2} [[X^+_{n-2,0}, X^+_{n-1,0}], [X^+_{n-2,0}, X^+_{n,r+s}]]+\delta_{n-1,i}[X^+_{n-1,0}, [X^+_{n-2,s}, X^+_{n,r}]]\\
    &{}=0-(-1)^{r+s}[[X^+_{n-2,0},X^+_{n-1,0}],X^+_{n,r+s}]
    =-(-1)^{r+s} \delta_{n-1,i} X_{n-2,-n+2,r+s},
\end{align*}
where the second equality is due to \eqref{Eq903-22}, and the third equality is due to\eqref{Eq903-7} and \eqref{Eq903-19}.
For the case $i<n-1$ and $j=n$, by \eqref{Eq903-23} and \eqref{Eq902}, we find that
\begin{align*}
    &\phantom{{}={}} [X^+_{n-2,s}, X_{i,-n,r}]
    = [X_{n-2,n-1,s}, [X_{i,n-1,0}, X^+_{n,r}]]= 0.
\end{align*}
Since the case $(i,j)=(n-1,n)$ is trivial, the statement is true for $p=n-2$.

Finally, we show the case that $p=n-1$. Suppose that $p=n-1$. 
For the case $j \leq n-3$ and $j - n$ is odd, by \eqref{gat1} and \eqref{Eq903-18}, we obtain
\begin{align*}
    &\phantom{{}={}} [X^+_{n-1,s}, X_{i,-j,r}]
    = [X^+_{n-1,s}, [X_{i,n,0}, [X_{j,n-1,0}, X^+_{n,r}]]]\\
    &{}= [X_{i,n,0}, [X^+_{n-1,s}, [X_{j,n-1,0}, X^+_{n, r}]]]\\
    &{}=[X_{i,n,0}, [X_{j,n-1,0}, [X^+_{n-1,s}, X^+_{n, r}]]]-[X_{i,n,0}, [X_{j,n,0}, X^+_{n, r}]]\\
    &{}=[X_{j,n-1,0}, [X_{i,n,0}, [X^+_{n-1,s}, X^+_{n, r}]]]-0\\
    &{}=[X_{j,n-1,0}, [[X_{i,n-3},X_{n-2,n}], [X^+_{n-1,s}, X^+_{n, r}]]]\\
    &{}=[X_{j,n-1,0},[X_{i,n-3}, [X_{n-2,n}, [X^+_{n-1,s}, X^+_{n, r}]]]]=0,
\end{align*}
where the second and 5-th equalities are due to \eqref{gat1}, the third equality is due to the Jacobi identity, the 4-th equality is due to \eqref{Eq903-18} and \eqref{gat1}, the 6-th equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, and the last equality is due to \eqref{Eq903-7}. 

For the case $j \leq n-2$ and $j - n$ is even, 
by \eqref{Eq903-7} and \eqref{Eq903-18}, 
\begin{align*}
    &\phantom{{}={}} [X^+_{n-1,s}, X_{i,-j,r}]
    = [X^+_{n-1,s}, [X_{i,n-1,0}, [X_{j,n,0}, X^+_{n,r}]]] \\
    &{}= -[X_{i,n,s}, [X_{j,n,0}, X^+_{n,r}]] + [X_{i,n-1,0}, [X_{j,n,0}, [X^+_{n-1,s}, X^+_{n,r}]]] \\
    &{}= 0 + [X_{i,n-1,0}, [X_{j,n-2,0}, [[X^+_{n-2,0}, X^+_{n-1,0}], [X^+_{n-1,s}, X^+_{n,r}]]]]
    = 0,
\end{align*}
where the second equality is due to the Jacobi identity, the third equality is due to \eqref{Eq903-18}, and the last equality is due to \eqref{Eq903-7}.

For the case $j = n-1$, we obtain
\begin{align*}
    & [X^+_{n-1,s}, X_{i,-n+1,r}] 
    = [X^+_{n-1,s}, [X_{i,n,0}, X^+_{n,r}]]
    = [X_{i,n,0}, [X^+_{n-1,s}, X^+_{n,r}]] \\
    &{}=(-1)^s[X_{i,n,0},[X^+_{n-1,0},X^+_{n,r+s}]]=(-1)^s[X^+_{n-1,0},[X_{i,n,0},X^+_{n,r+s}]]=0,
\end{align*}
where the second, third equality is due to \eqref{gat1}, the third equality is due to \eqref{Eq901-10}, and the last equality is due to \eqref{Eq903-18}.

For the case $i\leq n-2$ and $j=n$, we have
\begin{align*}
    & [X^+_{n-1,s}, X_{i,-n,r}]
    = [X^+_{n-1,s}, [X_{i,n-2,0}, [X^+_{n-2,0}, X^+_{n,r}]]] \\
    &{}= [X_{i,n-2,0}, [X^+_{n-1,s}, [X^+_{n-2,0}, X^+_{n,r}]]] \\
    &{}=-(-1)^r[X_{i,n-2,0}, [[X^+_{n-2,0},X^+_{n-1,0}],X^+_{n,s+r}]]\\
    &{}=-(-1)^r [X_{i,n,0}, X^+_{n,r+s}] = -(-1)^r X_{i,-n+1,r+s}, 
\end{align*}
where the second equality is due to \eqref{gat1}, the third equality is due to \eqref{Eq903-16}, and the 4-th equality is due to \eqref{gat1} and \eqref{Eq903-9.5}.

For the case that $(i,j)=(n-1,n)$, by the definition of $X_{n-1,-n+1,r}$, \eqref{Eq901-10} and \eqref{Eq901-17-1}, we have
\begin{align*}
    & [X^+_{n-1,s}, X_{n-1,-n,r}] 
    = [X^+_{n-1,s}, X^+_{n,r}] = (-1)^s \delta_{r+s,odd} X_{n-1,-n+1,r+s}.
\end{align*}
Thus, the statement is true for $p = n-1$. 

\subsection{Proof for $[X^+_{n,s}, X_{i,-j,r}]$}
We show the statement for each of the cases $j\leq n-2$, $j=n-1$ and $j=n$.

For the case $j \leq n-2$, by \eqref{Eq903-9.5} and the Jacobi identity, we have 
\begin{align*}
    &\phantom{{}={}} [X^+_{n,s}, X_{i,-j,r}]
    = \left( \prod_{u=i}^{j-2} \ad (X^+_{u,0}) \right)
        \left( \prod_{u=j+1}^n \ad (X_{u-2,u,0}) \right) (X^+_{n,r}) \\
    &{}= \left( \prod_{u=i}^{j-2} \ad (X^+_{u,0}) \right)
        \left( \prod_{u=j+1}^{n-2} \ad (X_{u-2,u,0}) \right) \\
        &\phantom{{}={}} \quad\quad\quad [X^+_{n,s}, [[X^+_{n-3,0}, X^+_{n-2,0}], [[X^+_{n-2,0}, X^+_{n-1,0}], X^+_{n,r}]]]\\
    &{}=[[X^+_{n,s}, [X^+_{n-2,0}, X^+_{n-3,0}]], [[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,r}]]\\
     &\phantom{{}={}} +[[X^+_{n-2,0}, X^+_{n-3,0}], [X^+_{n,s},[[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,r}]]].
\end{align*}
The first term of the right hand side is equal to zero by \eqref{Eq903-4}. We also find that the second term of the right hand side is equal to zero since we obtain
\begin{align}
&\quad[X^+_{n,s},[[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,r}]]\nonumber\\
&=[[X^+_{n,s},X^+_{n-1,0}],[X^+_{n-2,0},X^+_{n,r}]]+[[X^+_{n-1,0},X^+_{n,r}],[X^+_{n,s},X^+_{n-2,0}]]=0+0,\label{first5}
\end{align}
where the first equality is due to the Jacobi identity, \eqref{Eq901-17-1}, \eqref{Eq901-17-2} and \eqref{Eq902}, and the second equality is due to \eqref{Eq903-3}, \eqref{Eq901-10-0} and \eqref{Eq901-10}.

For the case $j = n-1$, the following relation holds:
\begin{align*}
    &\phantom{{}={}} [X^+_{n,s}, X_{i,-j,r}]
    = \left[ X^+_{n,s}, \left( \prod_{u=i}^{n-3} \ad (X^+_{u,0}) \right) 
        [[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,r}] \right] \\
    &{}= \left( \prod_{u=i}^{n-3} \ad (X^+_{u,0}) \right) 
        [X^+_{n,s}, [[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,r}]] = 0,
\end{align*}
where the second equality is due to \eqref{gat1} and \eqref{Eq903-9.5}, and the last equality is due to \eqref{first5}.

Suppose that $j=n$. In the case that $i=n-1$, this directly follows from \eqref{Eq901-10-2}.
For $i\leq n-2$, by \eqref{Eq903-9.5} and \eqref{Eq902}, we have 
\begin{align*}
    &\phantom{{}={}} [X^+_{n,s}, X_{i,-j,r}]
    = \left[ X^+_{n,s}, \left( \prod_{u=i}^{n-3} \ad (X^+_{u,0}) \right) 
        ([X^+_{n-2,0}, X^+_{n,r}]) \right] \\
    &{}= \left( \prod_{u=i}^{n-3} \ad (X^+_{u,0}) \right) [X^+_{n,s}, [X^+_{n-2,0}, X^+_{n,r}]] = 0.
\end{align*}

\subsection{Proof for $[X^+_{p,s}, X_{i,-i,2r+1}]$}
We show the statement for each of the cases $i\leq n-2$ and $i=n-1$.

First, we show the case $i\leq n-2$. Suppose $i \leq n-2$. 
From the Jacobi identity, we have 
\begin{align}
    &\phantom{{}={}} [X^+_{p,s}, X_{i,-i,2r+1}]
    = [X_{p,p+1,s}, [X_{i,n,0}, [X_{i,n-1,0}, X^+_{n,2r+1}]]]\nonumber \\
    &{}= [[X_{p,p+1,s}, X_{i,n,0}], [X_{i,n-1,0}, X^+_{n,2r+1}]]
    + [X_{i,n,0}, [[X_{p,p+1,s}, X_{i,n-1,0}], X^+_{n,2r+1}]] \nonumber\\
    &{} \quad \quad \quad  + [X_{i,n,0}, [X_{i,n-1,0}, [X^+_{p,s}, X^+_{n,2r+1}]]]. \label{first6}
\end{align}
By \eqref{gat1} and \eqref{Eq901-17}, we have
\begin{align*}
\eqref{first6}_1&=\delta_{p+1,i} [X_{p,n,s}, [X_{i,n-1,0}, X^+_{n,2r+1}]],\\
\eqref{first6}_2&=\delta_{p+1,i} [X_{i,n,0}, [X_{p,n-1,s}, [X^+_{n,2r+1}]]]
            - \delta_{p,n-1} [X_{i,n,0}, [X_{i,p+1,s}, X^+_{n,2r+1}]],\\
\eqref{first6}_3&=(\delta_{p,n-1} + \delta_{p,n-2}) [X_{i,n,0}, [X_{i,n-1,0}, [X^+_{p,s}, X^+_{n,2r+1}]]].
\end{align*}
Thus, it is enough to compute the following three terms:
\begin{gather}
[X_{i-1,n,s}, [X_{i,n-1,0}, X^+_{n,2r+1}]]
        + [X_{i,n-1,0}, [X_{i-1,n,s}, X^+_{n,2r+1}]],\label{first7}\\
[X_{i,n,0}, [X_{i,n-1,0}, [X^+_{n-2,s}, X^+_{n,2r+1}]]],\label{first8}\\
[X_{i,n,0}, [X_{i,n-1,0}, [X^+_{n-1,s}, X^+_{n,2r+1}]]]
        - [X_{i,n,0}, [X_{i,n,s}, X^+_{n,2r+1}]].\label{first9}
\end{gather}
By \eqref{Eq903-12}, we find that \eqref{first8} is equal to zero.

From the assumption that $i\leq n-2$, the Jacobi identity and \eqref{gat1}, we find that
\begin{align*}
    \eqref{first7}
    &{}= 2[X_{i,n-1,0}, [X_{i,n,s}, X^+_{n,2r+1}]]
    = (-1)^s 2 [X_{i,n-1,0}, [X_{i-1,n,0}, X^+_{n,2r+1+s}]]\\
    &{}=-(-1)^s (-1)^{2r+1+s} 2[X_{i,n,0}, [X_{i-1,n-1,0}, X^+_{n,2r+1+s}]]] \\
    &{}= 2[X_{i,n,0}, [X_{i-1,n-1,0}, X^+_{n,2r+1+s}]]].
\end{align*}
Here we used \eqref{Eq903-10} in the second equality and \eqref{Eq903-14} in the third equality.
Hence, in either case $n - i$ is even or odd, we have 
\begin{align*}
    \eqref{first7}
    &{}= 
    2 ((-1)^s \delta_{n-i,odd} + \delta_{n-i,even}) X_{i-1,-i,2r+1+s}. 
\end{align*}

Since $[X_{i,n-1,0}, X^+_{n-1,s}] = X_{i,n,s}$ from \eqref{gat1}, we have
\begin{align*}
 \eqref{first9}
    &{}= (-1)^s([X_{i,n,0}, [X_{i,n-1,0}, [X^+_{n-1,0}, X^+_{n,2r+1+s}]]]
        - [X_{i,n,0}, [X_{i,n,0}, X^+_{n,2r+1+s}]]) \\
    &{}= (-1)^s([X_{i,n,0}, [[X_{i,n-1,0}, X^+_{n-1,0}], X^+_{n,2r+1+s}]]  \\
    & \quad \quad+ [X_{i,n,0}, [X^+_{n-1,0}, [X_{i,n-1,0}, X^+_{n,2r+1+s}]]] - [X_{i,n,0}, [X_{i,n,0}, X^+_{n,2r+s+1}]] ) \\
    &{}= (-1)^s [X_{i,n,0}, [X^+_{n-1,0}, [X_{i,n-1,0}, X^+_{n,2r+1+s}]]],
\end{align*}
where the first equality is due to \eqref{Eq903-10}.
We have the relations $X_{i,n-1,0} = [X_{i,n-2,0}, X^+_{n-2,0}]$,
$[X^+_{n-1,0}, X_{i,n-2,0}] = 0$ and
$[X_{i,n-2,0}, X^+_{n,2r+1+s}] = 0$ from \eqref{gat1} and \eqref{Eq903-9.5}, hence we obtain
\begin{align*}
    \eqref{first9}
    &{}= (-1)^s [X_{i,n,0}, [X^+_{n-1,0}, [X_{i,n-2,0}, [X^+_{n-2,0}, X^+_{n,2r+1+s}]]]] \\
    &{}= (-1)^s [X_{i,n,0}, [X_{i,n-2,0}, [X^+_{n-1,0}, [X^+_{n-2,0}, X^+_{n,2r+1+s}]]]] \\
    &{}= (-1)^s (-1)^{2r+1+s} [X_{i,n,0}, [X_{i,n-2,0}, [X^+_{n,2r+1+s}, [X^+_{n-2,0}, X^+_{n-1,0}]]]] \\
    &{}= [X_{i,n,0}, [X_{i,n-2,0}, [[X^+_{n-2,0}, X^+_{n-1,0}], X^+_{n,2r+1+s}]]] \\
    &{}= [X_{i,n,0}, [[X_{i,n-2,0}, [X^+_{n-2,0}, X^+_{n-1,0}]], X^+_{n,2r+1+s}]] \\
    &{}= [X_{i,n,0}, [X_{i,n,0}, X^+_{n,2r+1+s}]] = 0.
\end{align*}
Here we used \eqref{Eq903-1} in the third equality, and \eqref{Eq903-18-2} in the last equality. 

Next, we show the case $i=n-1$. For the case $i = n-1$, we obtain
\begin{align*}
    &\phantom{{}={}} [X^+_{p,s}, X_{n-1,-n+1,2r+1}] \\
    &{}= [[X_{p,p+1,s}, X_{n-1,n,0}], X^+_{n,2r+1}]
        + [X^+_{n-1,0}, [X^+_{p,s}, X^+_{n,2r+1}]] \\
    &{}= \delta_{p+1,n-1} [X_{p,n,s}, X^+_{n,2r+1}]
        + \delta_{p,n-2} [X^+_{n-1,0}, [X^+_{p,s}, X^+_{n,2r+1}]] \\
    &{}= \delta_{p+1,n-1} ([X_{n-2,n,s}, X^+_{n,2r+1}]
        + [X^+_{n-1,0}, [X^+_{n-2,s}, X^+_{n,2r+1}]]), 
\end{align*}
where the second equality is due to \eqref{gat1}, \eqref{Eq901-17-1} and \eqref{Eq901-17-2}.
Since $X_{n-2,n,s} = [X^+_{n-2,0}, X^+_{n-1,s}]$ holds by \eqref{gat1}, we have 
\begin{align*}
    &\phantom{{}={}} \delta_{p+1,n-1} ([X_{n-2,n,s}, X^+_{n,2r+1}]
        + [X^+_{n-1,0}, [X^+_{n-2,s}, X^+_{n,2r+1}]]) \\
    &{}= \delta_{p+1,n-1} ([[X^+_{n-2,0}, X^+_{n-1,s}], X^+_{n,2r+1}]
        + [X^+_{n-1,0}, [X^+_{n-2,s}, X^+_{n,2r+1}]]) \\
    &{}= \delta_{p+1,n-1} ((-1)^s [[X^+_{n-2,0}, X^+_{n-1,0}], X^+_{n,2r+1+s}] 
        + (-1)^{2r+1+s} [X^+_{n,2r+1+s}, [X^+_{n-2,0}, X^+_{n-1,0}]]) \\
    &{}= 2 (-1)^s \delta_{p+1,n-1} [[X^+_{n-2,0}, X^+_{n-1,0}], X^+_{n,2r+1+s}] 
    = 2 (-1)^s \delta_{p+1,n-1} X_{n-2,-n+1,2r+1+s}
\end{align*}
using \eqref{Eq903-16} and \eqref{Eq903-19} in the second equality.

\subsection{Proof for $[X^+_{n,s}, X_{i,-i,2r+1}]$}
We show the statement for each of the cases $i\leq n-3$, $i=n-2$ and $i=n-1$.

For $i \leq n-3$, the following relation holds:
\begin{align*}
    &\phantom{{}={}} [X^+_{n,s}, X_{i,-i,2r+1}] \\
    &{}= \Bigg[ X^+_{r,s}, \ad (X^+_{i,0}) 
        \left( \prod_{u=i+2}^{n-2} \ad (X_{u-2,u,0}) \right)  \\
       &\phantom{{}={}} \quad\quad\quad \ad ([X^+_{n-3,0}, X^+_{n-2,0}]) \ad ([X^+_{n-2,0}, X^+_{n-1,0}]) (X^+_{n,2r+1}) \Bigg] \\
    &{}= \ad (X^+_{i,0}) 
        \left( \prod_{u=i+2}^{n-2} \ad (X^+_{u-2,u,0}) \right) \\
        &\phantom{{}={}} \quad\quad\quad [X^+_{n,s}, [[X^+_{n-2,0}, X^+_{n-3,0}], [[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,2r+1}]]]\\
     &{}= \ad (X^+_{i,0}) 
        \left( \prod_{u=i+2}^{n-2} \ad ([X^+_{u-1,0}, X^+_{u-2,0}]) \right) \\
        &\phantom{{}={}} \quad\quad\quad [[X^+_{n,s}, [X^+_{n-2,0}, X^+_{n-3,0}]], [[X^+_{n-1,0}, X^+_{n-2,0}], X^+_{n,2r+1}]] 
        = 0,
\end{align*}
where the second equality is due to \eqref{Eq903-9.5} and \eqref{gat1},  the third equality is due to \eqref{first5}, and the last equality is due to \eqref{Eq903-4}.

For $i = n-2$, we obtain
\begin{align*}
&\quad[X^+_{n,s}, X_{n-2,-n+2,2r+1}]= [X^+_{n,s}, [X^+_{n-2,0}, [[X^+_{n-2,0}, X^+_{n-1,0}], X^+_{n,2r+1}]]]\\
&=[X^+_{n,s},  [[X^+_{n-2,0}, X^+_{n-1,0}], [X^+_{n-2,0},X^+_{n,2r+1}]]]\\
&=[[X^+_{n,s},[X^+_{n-2,0}, X^+_{n-1,0}]], [X^+_{n-2,0},X^+_{n,2r+1}]]=0.
\end{align*}
where the second and third equalities are due to \eqref{Eq902} and the last equality is due to \eqref{Eq903-5}.

For $i=n-1$, by \eqref{Eq902} and \eqref{Eq901-14}, we have
\begin{align*}
    [X^+_{n,s}, X_{n-1,-n+1,2r+1}] &{}= [X^+_{n,s}, [X^+_{n-1,0}, X^+_{n,2r+1}]]= 0.
\end{align*}

\section{Proof of Theorem~\ref{Main}}
It is enough to show the compatibility with the relations \eqref{q901}-\eqref{q903-7}. By \eqref{SS1}, the compatibilities with the relations \eqref{q901-1-1}, \eqref{q901-2--1}, \eqref{q901-17} and \eqref{q902}  are trivial. Thus, we need to show the compatibility with \eqref{q901}, \eqref{q901-1}, \eqref{q901-2-0}, \eqref{q901-2-1}, \eqref{q901-3}, \eqref{q901-10}, \eqref{q903-1}, \eqref{q903-3} and \eqref{q903-7}. We will give the proof of the compatibility with \eqref{q901}, \eqref{q901-1}, \eqref{q901-2-1}, \eqref{q901-3}, \eqref{q901-10}, \eqref{q903-1}, \eqref{q903-3} and \eqref{q903-7}. The other compatibilities can be proven by the similar way.
\begin{comment}
By the definition of $\Phi$, we have
\begin{align*}
[\Phi(H_{i,1}),\Phi(X^-_{n,0})]&=[\sigma\circ\Phi(H_{i,1}),\sigma\circ\Phi(X^+_{n,0})]=-\sigma([\Phi(H_{i,1}),\Phi(X^+_{n,0})]).
\end{align*}
Since $\sigma(\Phi(X^+_{n,1}))=\Phi(X^-_{n,1})$ holds, it is enough to show the $+$ case.
\end{comment}

\subsection{Compatibility with \eqref{q901}}
Let us set 
\begin{align*}
V_i&=\sum_{1\leq a\leq i}S^{(1)}_{i,a}S^{(1)}_{a,i},\ W_i=\sum_{1\leq b\leq i}S^{(1)}_{i,-b}S^{(1)}_{-b,i}.
\end{align*}
By \eqref{SS1} and the relation $S^{(1)}_{i,-i}=0$, we can rewrite
\begin{align*}
&\quad[\Phi(H_{i,1}),\Phi(H_{j,1})]\\
&=[-S^{(2)}_{i,i}+S^{(2)}_{i+1,i+1}+\hbar(V_i+W_i-V_{i+1}-W_{i+1}),\\
&\qquad\qquad-S^{(2)}_{j,j}+S^{(2)}_{j+1,j+1}+\hbar(V_j+W_j-V_{j+1}-W_{j+1})].
\end{align*}
Thus, for the proof of the compatibility with \eqref{q901}, it is enough to show the relation
\begin{align*}
[-S^{(2)}_{i,i}+\hbar(V_i+W_i),-S^{(2)}_{j,j}+\hbar(V_j+W_j)]&=0.
\end{align*}
By \eqref{SS1}, we obtain
\begin{align}
[S^{(2)}_{i,i},V_j+W_j]&=\delta(i\leq j)(S^{(1)}_{j,i}S^{(2)}_{i,j}-S^{(2)}_{j,i}S^{(1)}_{i,j})+\delta(i\leq j)(S^{(1)}_{i,-j}S^{(2)}_{-j,i}-S^{(2)}_{i,-j}S^{(1)}_{-j,i}).\label{SVW}
\end{align}
In the case that $i<j$, by \eqref{SVW}, we have
\begin{align}
[V_i+W_i,S^{(2)}_{j,j}]=0.\label{SVW2}
\end{align}
By \eqref{SVW}, \eqref{SVW2} and \eqref{SS3}, we have
\begin{align}
[S^{(2)}_{i,i},S^{(2)}_{j,j}]-[S^{(2)}_{i,i},\hbar(V_j+W_j)]-[\hbar(V_i+W_i),S^{(2)}_{j,j}]=0\label{SVW3}
\end{align}
for $i<j$. By the symmetry with respect to $i$ and $j$, \eqref{SVW3} holds for any $1\leq i,j\leq n$. Thus, we need to show that $[V_i+W_i,V_j+W_j]=0$. 

By \eqref{SS1} and a direct computation, for $i\neq j$, we obtain
\begin{align}
[V_i,V_j]&=0,\\
[V_i,W_j]&=-\delta(i>j)\sum_{1\leq b\leq j}S^{(1)}_{i,j}S^{(1)}_{j,-b}S^{(1)}_{-b,i}+\delta(i>j)\sum_{1\leq b\leq j}S^{(1)}_{i,b}S^{(1)}_{j,-b}S^{(1)}_{-j,i}\nonumber\\
&\quad+\delta(i>j)\sum_{1\leq b\leq j}S^{(1)}_{i,-b}S^{(1)}_{-b,j}S^{(1)}_{j,i}-\delta(i>j)\sum_{1\leq b\leq j}S^{(1)}_{i,-j}S^{(1)}_{-b,j}S^{(1)}_{b,i},\label{1}\\
[W_i,W_j]&=-\delta(i<j)\sum_{1\leq a\leq i}S^{(1)}_{i,-a}(S^{(1)}_{j,i})S^{(1)}_{-a,j}-\delta(i>j)\sum_{1\leq b\leq j}S^{(1)}_{i,-b}S^{(1)}_{j,i}S^{(1)}_{-b,j}\nonumber\\
&\quad-\delta(i<j)\sum_{1\leq a\leq i}S^{(1)}_{i,-a}S^{(1)}_{-a,-j}S^{(1)}_{-i,j}+\delta(i>j)\sum_{1\leq b\leq j}S^{(1)}_{i,-j}S^{(1)}_{b,i}S^{(1)}_{-b,j}\nonumber\\
