&\quad [\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n-1,n-1}S^{(1)}_{n,b}S^{(1)}_{b,n},S^{(1)}_{n-1,-n}]\nonumber\\
&=-\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n-1,n-1}S^{(1)}_{n,b}S^{(1)}_{b,-n+1}+\hbar^2 S^{(1)}_{n-1,n-1}S^{(1)}_{n,-n+1}S^{(1)}_{n,n}+\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n-1,-n}S^{(1)}_{n,b}S^{(1)}_{b,n},\label{qqq7}\\
&\quad[\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{-n,n-1},S^{(1)}_{n-1,-n}]=\hbar^2 S^{(1)}_{n,-n+1}[S^{(1)}_{-n,n-1},S^{(1)}_{n-1,-n}]\nonumber\\
&=\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{-n,-n}-\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{n-1,n-1},\label{qqq8}\\
&\quad[\hbar^2 \sum_{a,b\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,b}S^{(1)}_{b,n-1},S^{(1)}_{n-1,-n}]\nonumber\\
&=\hbar^2 \sum_{a,b\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,b}S^{(1)}_{b,-n}+\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n+1}S^{(1)}_{n,n-1}\nonumber\\
&\quad+\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}S^{(1)}_{n-1,n-1}+\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n-1,-n}S^{(1)}_{n-1,b}S^{(1)}_{b,n-1},\label{qqq9}\\
&\quad[\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{n,n}S^{(1)}_{a,n-1},S^{(1)}_{n-1,-n}]\nonumber\\
&=\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{n,n}S^{(1)}_{a,-n}-\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{n,-n+1}S^{(1)}_{a,n-1}+\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n,n}S^{(1)}_{n-1,n-1},\label{qqq10}\\
&\quad[\hbar^2 \sum_{a,b\in I_{n-1}}S^{(1)}_{n,b}S^{(1)}_{b,a}S^{(1)}_{a,n},S^{(1)}_{n-1,-n}]\nonumber\\
&=-\hbar^2 \sum_{a,b\in I_{n-1}}S^{(1)}_{n,b}S^{(1)}_{b,a}S^{(1)}_{a,-n+1}+\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n,b}S^{(1)}_{b,-n+1}S^{(1)}_{n,n}\nonumber\\
&\quad+\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n,b}S^{(1)}_{b,-n}S^{(1)}_{n-1,n}+\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n,-n+1}S^{(1)}_{n,a}S^{(1)}_{a,n}.\label{qqq11}
\end{align}
By \eqref{SS5}, \eqref{SS6} and \eqref{SS1}, we have
\begin{align}
&\quad\eqref{qqq2}_3-\eqref{qqq3}_3=-2\hbar S^{(2)}_{n-1,-n}S^{(1)}_{n-1,n-1}+\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{n-1,n-1},\label{rrr1}\\
&\quad-\eqref{qqq3}_1+\eqref{qqq5}_2=-(2n-2)\hbar S^{(2)}_{n,-n+1}-\hbar S^{(2)}_{n-1,-n}+\hbar^2 \sum_{a\in I_n}S^{(1)}_{n-1,a}(S^{(1)}_{a,-n}),\label{rrr2}\\
&\quad\eqref{qqq2}_4+\eqref{qqq5}_2=-\hbar S^{(2)}_{n,-n+1},\label{rrr3}\\
&\quad\eqref{qqq2}_2-\eqref{qqq4}_2=0,\label{rrr4}\\
&\quad-\eqref{qqq4}_1+\eqref{qqq5}_1=\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}-(2n-2)\hbar S^{(2)}_{n,-n+1}+\hbar S^{(2)}_{n,-n+1},\label{rrr5}\\
&\quad\eqref{qqq2}_1+\eqref{qqq6}_2=2\hbar S^{(2)}_{n,-n+1}S^{(1)}_{n,n}+\hbar S^{(2)}_{n,-n+1}-\hbar^2 S^{(1)}_{n,n}S^{(1)}_{n-1,-n},\label{rrr6}\\
&\quad-\eqref{qqq7}_1+\eqref{qqq9}_3\nonumber\\
&=\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n,b}S^{(1)}_{b,-n+1}+2\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n-1,b}S^{(1)}_{b,-n}+(2n-3)\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{n-1,n-1},\label{rrr7}\\
&\quad-\eqref{qqq7}_3-\eqref{qqq11}_4=0,\label{rrr8}\\
&\quad-\eqref{qqq7}_2-\eqref{qqq10}_3=\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n,n},\label{rrr9}\\
&\quad-\eqref{qqq10}_1-\eqref{qqq11}_2\nonumber\\
&=-(2n-1)\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n,n}-\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}-2\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{n,b}S^{(1)}_{b,-n+1}S^{(1)}_{n,n},\label{rrr10}\\
&\quad\eqref{qqq9}_1-\eqref{qqq11}_1=(2n-3)\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}+(2n-3)\hbar^2 \sum_{b\in I_{n-1}}S^{(1)}_{b,-n}S^{(1)}_{n-1,b},\label{rrr11}\\
&\quad\eqref{qqq9}_4-\eqref{qqq10}_2=-\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n-1,n-1}.\label{rrr12}
\end{align}
Since we obtain
\begin{align*}
[\Phi(X^+_{n-1,1}),X^+_{n,0}]
&=S^{(2)}_{n-1,-n+1}-\hbar \sum_{a\in I_n}S^{(1)}_{n-1,a}S^{(1)}_{a,-n+1}+\hbar S^{(1)}_{n-1,-n}S^{(1)}_{n-1,n},\\
[\Phi(X^-_{n-1,1}),X^+_{n,0}]
&=-S^{(2)}_{n,-n}+\hbar \sum_{a\in I_n}S^{(1)}_{n,a}S^{(1)}_{a,-n}+\hbar S^{(1)}_{n,-n+1}S^{(1)}_{n,n-1},
\end{align*}
we have
\begin{align}
-\eqref{qqq3}_2+\eqref{qqq9}_2
&=-\hbar [\Phi(X^+_{n-1,1}),X^+_{n,0}]S^{(1)}_{n,n-1}+\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n-1,n}S^{(1)}_{n,n-1},\label{rrr13}\\
\eqref{qqq6}_3-\eqref{qqq11}_3
&=-\hbar [\Phi(X^-_{n-1,1}),X^+_{n,0}]S^{(1)}_{n-1,n}+\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{n,n-1}S^{(1)}_{n-1,n}.\label{rrr14}
\end{align}
Since
\begin{align*}
&\quad\eqref{rrr1}_1+\eqref{rrr7}_2=2\hbar \Phi(X^+_{n,1})S^{(1)}_{n,n}+2(n-1)\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n,n},\\
&\quad\eqref{rrr6}_1+\eqref{rrr10}_3=-2\hbar \Phi(X^+_{n,1})S^{(1)}_{n-1,n-1}-2(n-1)\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n-1,n-1},\\
&\quad\eqref{rrr2}_3+\eqref{rrr5}_1+\eqref{rrr10}_2+\eqref{rrr11}_1=(2n-2)\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n},\\
&\quad\eqref{rrr7}_1+\eqref{rrr11}_2=(2n-2)\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n,a}S^{(1)}_{a,-n+1}\\
&=(2n-2)\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}+(2n-2)\hbar^2 \sum_{a\in I_{n-1}}(S^{(1)}_{n,-n+1}-\delta_{a,-n+1}S^{(1)}_{n,-n+1})\\
&=(2n-2)\hbar^2 \sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}+(2n-2)(2n-3)\hbar^2 S^{(1)}_{n,-n+1},\\
&\quad\eqref{rrr2}_1+\eqref{rrr2}_2+\eqref{rrr3}+\eqref{rrr5}_2+\eqref{rrr5}_3+\eqref{rrr6}_2\\
&=-\hbar S^{(2)}_{n-1,-n}-(4n-5)\hbar S^{(2)}_{n,-n+1}=-(4n-4)\hbar S^{(2)}_{n-1,-n}-(4n-5)\hbar^2S^{(1)}_{n,-n+1}\\
&\quad\eqref{qqq8}_1+\eqref{rrr6}_3+\eqref{rrr9}+\eqref{rrr10}_1\\
&=-\hbar^2[S^{(1)}_{n-1,-n},S^{(1)}_{n,n}]-2(n-1)\hbar^2S^{(1)}_{n-1,-n}S^{(1)}_{n,n}=\hbar^2 S^{(1)}_{n-1,-n}-2(n-1)\hbar^2 S^{(1)}_{n-1,-n}S^{(1)}_{n,n},\\
&\quad\eqref{qqq8}_2+\eqref{rrr1}_2+\eqref{rrr7}_3+\eqref{rrr12}=(2n-2)\hbar^2 S^{(1)}_{n,-n+1}S^{(1)}_{n-1,n-1},
\end{align*}
we have
\begin{align*}
&\quad[[\Phi(X^+_{n-1,1}),\Phi(X^-_{n-1,1})],X^+_{n,0}]\\
&=-2(n-1)\hbar [\Phi(H_{n-1,1}),X^+_{n,0}]-2\hbar \Phi(X^+_{n,1})\Phi(H_{n-1,0})\\
&\quad-2(n-1)\hbar \Phi(X^+_{n,0})(\Phi(H_{n-1,0})+\Phi(H_{n,0}))\\
&\quad+(4n-4)\hbar \Phi(X^+_{n,1})+6(n-1)\hbar^2 \Phi(X^+_{n,0}).
\end{align*}
\subsection{Compatibility with \eqref{q903-1}}
By \eqref{SS1}, we obtain
\begin{align*}
&\quad[\Phi(X^+_{n,1}),[\Phi(X^+_{n-2,0}),\Phi(X^+_{n-1,0})]]\\
&=[-S^{(2)}_{n-1,-n}-(n-1)\hbar S^{(1)}_{n-1,-n}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n},[S^{(1)}_{n-2,n-1},S^{(1)}_{n-1,n}]]\\
&=[-S^{(2)}_{n-1,-n}-(n-1)\hbar S^{(1)}_{n-1,-n}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n},S^{(1)}_{n-2,n}]\\
&=S^{(2)}_{n-1,-n+2}+(n-1)\hbar S^{(1)}_{n-1,-n+2}\\
&\quad-\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n+2}+\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-2,-n}+\hbar S^{(1)}_{n-1,-n+2}S^{(1)}_{-n,-n}
\end{align*}
and
\begin{align*}
&\quad[[\Phi(X^+_{n,1}),\Phi(X^+_{n-1,0})],\Phi(X^+_{n-2,0})]\\
&=[[-S^{(2)}_{n-1,-n}-(n-1)\hbar S^{(1)}_{n-1,-n}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n},S^{(1)}_{n-2,n-1}],S^{(1)}_{n-1,n}]]\\
&=[S^{(2)}_{n-2,-n}+(n-1)\hbar S^{(1)}_{n-2,-n}\\
&\quad-\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-2,a}S^{(1)}_{a,-n},S^{(1)}_{n-1,n}]\\
&=-S^{(2)}_{n-2,-n+1}-(n-1)\hbar S^{(1)}_{n-2,-n+1}\\
&\quad+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-2,a}S^{(1)}_{a,-n+1}-\hbar S^{(1)}_{n-2,n}S^{(1)}_{n-1,-n}-\hbar S^{(1)}_{n-2,-n+1}S^{(1)}_{-n,-n}
\end{align*}
Thus, we obtain
\begin{align*}
&\quad[\Phi(X^+_{n,1}),[\Phi(X^+_{n-2,0}),\Phi(X^+_{n-1,0})]]\\
&=S^{(2)}_{n-1,-n+2}+S^{(2)}_{n-2,-n+1}-\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n+2}-\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-2,a}S^{(1)}_{a,-n+1}\\
&\quad+\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-2,-n}+\hbar S^{(1)}_{n-2,n}S^{(1)}_{n-1,-n}\\
&=-\hbar S^{(1)}_{n-1,-n+2}-(n-1)S^{(1)}_{n-1,-n+2}+\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-2,-n}+\hbar S^{(1)}_{n-2,n}S^{(1)}_{n-1,-n}\\
&=-(n-1)S^{(1)}_{n-1,-n+2}+\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-2,-n}+\hbar S^{(1)}_{n-1,-n}S^{(1)}_{n-2,n}.
\end{align*}
\subsection{Compatibility with \eqref{eq903-3}}
By \eqref{SS1}, we obtain
\begin{align*}
&\quad[[\Phi(X^+_{n,0}),\Phi(X^+_{n-2,0})],[\Phi(X^+_{n,0}),\Phi(X^+_{n-1,1})]]\\
&=-[S^{(1)}_{n-2,-n},[S^{(1)}_{n-1,-n},-S^{(2)}_{n-1,n}-(n-1)\hbar S^{(1)}_{n-1,n}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,n}]]\\
&=-[S^{(1)}_{n-2,-n},-\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n+1}-\hbar S^{(1)}_{n-1,-n}S^{(1)}_{n-1,n}]\\
&=\hbar\sum_{a\in I_{n-1}}[S^{(1)}_{n-2,-n},S^{(1)}_{n-1,a}S^{(1)}_{a,-n+1}]+\hbar S^{(1)}_{n-1,-n}[S^{(1)}_{n-2,-n},S^{(1)}_{n-1,n}]\\
&=-\hbar S^{(1)}_{n-1,-n}S^{(1)}_{n-2,-n+1}-\hbar S^{(1)}_{n-1,-n+2}S^{(1)}_{n,-n+1}+\hbar S^{(1)}_{n-1,-n}S^{(1)}_{n-1,-n+2}\\
&=-\hbar S^{(1)}_{n-1,-n}S^{(1)}_{n-2,-n+1}.
\end{align*}

\subsection{Compatibility with \eqref{eq903-7}}
By \eqref{SS1}, we obtain
\begin{align*}
&\quad[[\Phi(X^+_{n-1,0}),\Phi(X^+_{n-2,0})],[\Phi(X^+_{n-1,0}),\Phi(X^+_{n,1})]]\\
&=-[S^{(1)}_{n-2,n},[S^{(1)}_{n-1,n},-S^{(2)}_{n-1,-n}-(n-1)\hbar S^{(1)}_{n-1,-n}+\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n}]]\\
&=-[S^{(1)}_{n-2,n},\hbar\sum_{a\in I_{n-1}}S^{(1)}_{n-1,a}S^{(1)}_{a,-n+1}-\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-1,-n}]\\
&=\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-2,-n+1}+\hbar S^{(1)}_{n-1,-n+2}S^{(1)}_{-n,-n+1}+\hbar S^{(1)}_{n-1,n}S^{(1)}_{n-1,-n+2}\\
&=\hbar S^{(1)}_{n-2,-n+1}S^{(1)}_{n-1,n}.
\end{align*}

