  \centering
  \includegraphics[width = 0.45\linewidth]{upper_bound.jpg}
  \caption{Plot of upper bound for $\rho$ given in Proposition \ref{prop:4}.}
\end{figure}

To offer some degree of protection against outliers, we will focus on modeling in the context of multivariate 
analysis using the Laplace distribution, a member from the class of elliptically contoured distributions that has 
been studied in detail, for example in \cite{Gomez:1998, Kotz:2001, Gomez:2008}. More recently, the Laplace distribution 
has been proposed for robust estimation in the linear mixed-effects model by \cite{Yavuz:2018}, who developed an 
EM algorithm to perform the parameter estimation. Following \cite{Yavuz:2018} (see also \cite{Pinheiro:2001}) we 
obtain an efficient procedure for parameter estimation based on a random sample $\bs{x}_1,\dots,\bs{x}_n$ from the 
$\mathsf{Laplace}_k(\bs{\mu},\bs{\Sigma})$ distribution, with density
\[
  f(\bs{x}_i;\bs{\mu},\bs{\Sigma}) = \frac{\Gamma(k/2)}{\pi^{k/2}\Gamma(k)2^{k+1}}\,\lvert\bs{\Sigma}\rvert^{-1/2}
  \exp\big[-\half\big\{(\bs{x}_i - \bs{\mu})^\top\bs{\Sigma}^{-1}(\bs{x}_i - \bs{\mu})\big\}^{1/2}\big], \qquad 
  i = 1,\dots,n,
\]
by applying a data augmentation scheme incorporating latent variables $\omega_1,\dots,\omega_n$, and using an 
EM algorithm\cite{Dempster:1977} based on the hierarchical representation $\bs{X}_i\mid\omega_i \sim \mathsf{N}_k(\bs{\mu},
\bs{\Sigma})$, with $\omega_i$ being a positive random variable having a probability density function
\begin{equation}\label{eq:mixture}
  h(\omega_i) = \frac{1}{2^{(3k+1)/2}\Gamma\big(\frac{k+1}{2}\big)}\,\omega_i^k \exp(-\omega_i^2/8), 
  \quad \omega_i > 0,
\end{equation}
for $i=1,\dots,n$. It is easy to notice that, disregarding terms that do not depend on $\bs{\theta} = (\bs{\mu}^\top,
\bs{\sigma}^\top)^\top$, with $\bs{\sigma} = \vech(\bs{\Sigma})$ denoting the different elements in the $\bs{\Sigma}$ 
matrix, the conditional expectation of the complete-data log-likelihood function, % $(\bs{x}_1^top,\omega_1)^top,\dots,(\bs{x}_n^top,\omega_n)^top$, 
takes the form.
\[
  Q(\bs{\theta};\bs{\theta}^{(r)}) = -\frac{n}{2}\log\lvert\bs{\Sigma}\rvert - \frac{1}{2}\sum_{i=1}^n \omega_i^{(r)}
  (\bs{x}_i - \bs{\mu})^\top\bs{\Sigma}^{-1}(\bs{x}_i - \bs{\mu}),
\]
where
\begin{equation}\label{eq:E-step}
  \omega_i^{(r)} = \E(\omega_i^{-2}\mid\bs{x}_i,\bs{\theta}^{(r)}) = \frac{1/2}{D_i(\bs{\theta}^{(r)})}\,
  \frac{K_{k/2-1}(D_i(\bs{\theta}^{(r)})/2)}{K_{k/2}(D_i(\bs{\theta}^{(r)})/2)}, \qquad i = 1,\dots,n,
\end{equation}
with $D_i^2(\bs{\theta}^{(r)}) = (\bs{x}_i - \bs{\mu}^{(r)})^\top\{\bs{\Sigma}^{(r)}\}^{-1}(\bs{x}_i - \bs{\mu}^{(r)})$,
while $K_\nu(\cdot)$ represents the modified Bessel function of second type of order $\nu$ and $\bs{\theta}^{(r)}$ 
denotes an initial estimate for the $r$-th stage of the algorithm. Maximizing $Q(\bs{\theta};\bs{\theta}^{(r)})$ with 
respect to $\bs{\mu}$ and $\bs{\sigma}$ we obtain the following updates,
\begin{align} 
  \bs{\mu}^{(r+1)} & = \frac{1}{\sum_{j=1}^n \omega_j^{(r)}}\,\sum_{i=1}^n \omega_i^{(r)}\bs{x}_i, \label{eq:M-center} \\
  \bs{\Sigma}^{(r+1)} & = \frac{1}{n}\sum_{i=1}^n \omega_i^{(r)}(\bs{x}_i - \bs{\mu}^{(r+1)})
  (\bs{x}_i - \bs{\mu}^{(r+1)})^\top. \label{eq:M-scatter}
\end{align}
The steps described in Equations \eqref{eq:E-step}, \eqref{eq:M-center} and \eqref{eq:M-scatter}, must be iterated 
until convergence is reached. We must emphasize that in our numerical experiments we will have $k = 2$ measuring 
instruments. On the other hand, to deal with the parameter estimation subject to the constraint $\mu_1 = \mu_2$, 
a rather simple modification of the previous procedure must be considered, the details of which are presented in 
the Appendix.

Let $\what{\bs{\mu}}$ and $\what{\bs{\Sigma}}$ be the ML estimators for a random sample from a Laplace distribution 
obtained, for example, from the procedure described in Equations \eqref{eq:E-step}-\eqref{eq:M-scatter}. In the general 
context of elliptical contoured distributions, the Fisher information matrix required to characterize the asymptotic 
distribution of the ML estimators has been obtained independently in \cite{Tyler:1982} and \cite{Mitchell:1989}. Thus, 
it follows that
\[
  \sqrt{n}(\what{\bs{\mu}} - \bs{\mu}) \stackrel{D}{\longrightarrow} \mathsf{N}_k\Big(\bs{0},4k\bs{\Sigma}\Big).
\]
%where $a_g = \E(W_g^2(R^2)R^2)$, with $R^2 = \|\bs{Z}\|^2$ and $\bs{Z}\sim\mathsf{Laplace}_k(\bs{0},\bs{I})$. 

Because of the important simplifications that occur in the case that $\mu_1 = \mu_2$. Next, we will be interested 
in testing linear hypotheses of the form $H_0:\bs{A\mu} = \bs{0}$, where $\bs{A}$ is a known matrix of order $r \times k$, 
with $rk(\bs{A}) = r$ $(r \leq k)$. To test this type of hypothesis we shall consider tests for large samples based 
on the likelihood, namely the Wald\cite{Wald:1943}, Rao score\cite{Rao:1948} and gradient statistics\cite{Terrell:2002}. 
Those that take the form:
\begin{align} 
  W_n & = \frac{n}{4k}\what{\bs{\mu}}{}^\top\bs{A}^\top(\bs{A}\what{\bs{\Sigma}}\bs{A}^\top)^{-1}\bs{A}\what{\bs{\mu}}, \label{eq:Wald} \\
  R_n & = \frac{4k}{n}\Big\{\sum_{i=1}^n\omega_i(\widetilde{\bs{\theta}})(\bs{x}_i - \widetilde{\bs{\mu}})\Big\}^\top
  \widetilde{\bs{\Sigma}}{}^{-1}\Big\{\sum_{i=1}^n\omega_i(\widetilde{\bs{\theta}})(\bs{x}_i - \widetilde{\bs{\mu}})\Big\}, \label{eq:Rao} \\
  G_n & = \Big\{\sum_{i=1}^n\omega_i(\widetilde{\bs{\theta}})(\bs{x}_i - \widetilde{\bs{\mu}})\Big\}^\top\widetilde{\bs{\Sigma}}{}^{-1}
  \what{\bs{\mu}}, \label{eq:Terrell}
\end{align}
where $\widetilde{\bs{\theta}}$ and $\what{\bs{\theta}}$ are the restricted and unrestricted ML estimators, respectively.
We should note that $\omega_i(\widetilde{\bs{\theta}})$ correspond to the estimated weights obtained at the convergence 
of the algorithm for constrained estimation outlined in the Appendix. Indeed, under $H_0:\bs{A\mu} = \bs{0}$, all of these 
test statistics are asymptotically equivalent, each with chi-squared distribution with $r$ degrees of freedom. Furthermore, 
we can appreciate that, both $\widetilde{\bs{\Sigma}}$ and $\what{\bs{\Sigma}}$ are consistent estimators of $\bs{\Sigma}$.

An interesting alternative for testing hypotheses of the type $H_0:\bs{A\mu} = \bs{0}$ which is particularly useful as it 
does not require iterative algorithms, is based on $\bs{x}_1,\dots,\bs{x}_n$ a random sample from a population with a 
$\mathsf{Laplace}_k(\bs{\mu},\bs{\Sigma})$ distribution, and consider $\overline{\bs{x}}=\frac{1}{n}\sum_{i=1}^n\bs{x}_i$ 
and $\bs{S}=\frac{1}{n-1}\sum_{i=1}^n(\bs{x}_i-\overline{\bs{x}})(\bs{x}_i-\overline{\bs{x}})^\top$ as the mean vector 
and covariance matrix of sample size $n$, respectively. We know that $\overline{\bs{x}}$ and $\bs{S}$ are unbiased and 
consistent estimators of $\bs{\mu}$ and $\bs{\Sigma}$, respectively. In addition, $\overline{\bs{x}}$ and $\bs{S}$ are 
asymptotically independent, with limit distributions given, respectively, by
\[
  \sqrt{n}(\overline{\bs{x}}-\bs{\mu}) \stackrel{D}{\longrightarrow} \mathsf{N}_k(\bs{0}, \bs{\Sigma}), \qquad
  \sqrt{n}(\vech(\bs{S})-\vech(\bs{\Sigma})) \stackrel{D}{\longrightarrow} \mathsf{N}_{k^*}(\bs{0}, \bs{\Omega}),
\]
where $k^*=k(k+1)/2$ and
\[
 \bs{\Omega} = \frac{1}{k+1}\bs{D}_k^\top\{(k+3)(\bs{I}_{k^2}+\bs{K}_k)(\bs{\Sigma}\otimes\bs{\Sigma}) + 2(\ovec\bs{\Sigma})
 (\ovec\bs{\Sigma})^\top\}\bs{D}_k,
\]
with $\bs{D}_k$ and $\bs{K}_k$ being duplication and commutation matrices of order $k$, respectively \cite{Anderson:1992, 
Anderson:2003}. It is straightforward to note that the excess kurtosis associated with a $\mathsf{Laplace}_k(\bs{\mu},\bs{\Sigma})$ 
distribution is given by $\kappa=2/(k+1)$.The above result is valid for the whole class of multivariate elliptical distributions 
and enables the use of the generalized Hotelling's $T^2$ statistic, which adopts the form
\begin{equation}\label{eq:T2}
  T_n^2 = n\overline{\bs{x}}{}^\top\bs{A}^\top(\bs{ASA}^\top)^{-1}\bs{A}\overline{\bs{x}}.
\end{equation}
Although its small sample distribution is difficult to obtain, the asymptotic distribution of $T_n^2$ can be obtained 
by noticing that $\sqrt{n}\bs{A}(\overline{\bs{x}}-\bs{\mu})\stackrel{D}{\longrightarrow}\mathsf{N}_r(\bs{0},\bs{A\Sigma}
\bs{A}^\top)$ and $\bs{S} \stackrel{p}{\rightarrow} \bs{\Sigma}$ \cite{Anderson:2003}. This leads to notice that, under 
$H_0$, the test statistic in \eqref{eq:T2} follows an asymptotically chi-squared distribution with $r$ degrees of freedom. 
We can emphasize that the main advantage of the generalized Hotelling $T^2$ statistic is that it does not require any 
iterative algorithm to obtain parameter estimates, instead it is based on moment estimators.

