\bmsubsection*{A scaled $\bs{\rho_1}$ coefficient}

Consider the following result established by \cite{King:2001}. Assume that $(X_1,X_2)^\top$ 
follows a bivariate normal distribution with $\bs{\mu} = (\mu_1,\mu_2)^\top$, and 
\[
  \bs{\Sigma} = \begin{pmatrix}
    \sigma_{11} & \sigma_{12} \\
    \sigma_{21} & \sigma_{22}
  \end{pmatrix},
\]
and suppose that $\varphi(z)$ is a non-decreasing convex function such that for all $z\geq 0$, 
$\varphi(0)=0$ and $\varphi(z) = \varphi(-z)$. Then, the coefficient
\[
  \rho_\varphi = \frac{\E\{\varphi(X_1-X_2):\sigma_{12} = 0\} - \E\{\varphi(X_1+X_2):\sigma_{12}=0\} 
  - \big[\E\{\varphi(X_1-X_2)\} - \E\{\varphi(X_1+X_2)\}\big]}{\E\{\varphi(X_1-X_2):\sigma_{12}=0\} 
  - \E\{\varphi(X_1+X_2):\sigma_{12}=0\} + \half\big[\E\{\varphi(2X_1)\} + \E\{\varphi(2X_2)\}\big]},
\]
belongs to the interval $[-1,1]$. It is straightforward to see that Lin's coefficient given in \eqref{eq:Lin} 
is obtained for $\varphi(z) = z^2$. Similarly, an $L_1$ coefficient like \eqref{eq:CCC1} can be derived using 
$\varphi(z) = \lvert z\rvert$. This coefficient will be a scaled version of \eqref{eq:CCC1} to the interval $[-1,1]$.

%%============================================================================%%
\bmsubsection*{Proofs of main results}

\begin{proof}[Proof of Proposition~{\rm\ref{prop:1}}]
  Note that $X_1 - X_2\sim \mathsf{EC}_1(\gamma,\tau^2;\psi)$. Also notice that $Z = \gamma + \tau W$, 
  where $\gamma = \mu_1-\mu_2$, $\tau^2 = \sigma_{11}+\sigma_{22}-2\sigma_{12}$ and $W\sim\mathsf{EC}_1(0,1;\psi)$, 
  thus $\lvert Z\rvert$ follows a folded elliptical contoured distribution and $\lvert Z\rvert = \lvert X_1 - X_2\rvert$. 
  Then,
  \begin{align*}
    \E(\lvert Z\rvert) & = \E(\lvert\gamma + \tau W\rvert) = \E[(\gamma + \tau W)I\{\gamma + \tau W\geq 0\}]
    + \E[(-\gamma - \tau W)I\{\gamma + \tau W < 0\}] \\[.25em]
    & = \E(\gamma + \tau W) - 2\E[(\gamma + \tau W)I\{W < - \gamma/\tau\}] = \gamma - 2\E[\gamma\,
    I\{W < -\gamma/\tau\}] - 2\tau\E[W\,I\{W < -\gamma/\tau\}] \\
    & = \gamma - 2\gamma\Pr(W \leq -\gamma/\tau) - 2\tau\E[W\,I\{W < -\gamma/\tau\}] = \gamma - 2\gamma
    C_g\int_{-\infty}^{-\gamma/\tau} g(r^2)\rd r - 2\tau C_g\int_{-\infty}^{-\gamma/\tau} r g(r^2)\rd r \\
    & = \gamma\Big(1 - 2C_g\int_{-\infty}^{-\gamma/\tau} g(r^2)\rd r\Big) - 2\tau C_g
    \int_{-\infty}^{-\gamma/\tau} r g(r^2)\rd r.
  \end{align*}
  Thus, this yields \eqref{eq:CCC1-EC} and the proposition is verified.
\end{proof}

%%============================================================================%%
\begin{proof}[Proof of Proposition~{\rm\ref{prop:2}}]
  Because of \eqref{eq:density},
  \begin{align*}
    \E(\lvert Z\rvert^p) & =\frac{C_g}{\sqrt{\sigma_{11}+\sigma_{22}-2\sigma_{12}}} \int_{-\infty}^\infty \lvert z\rvert^p
    g\Big(\frac{z^2}{\sigma_{11}+\sigma_{22}-2\sigma_{12}}\Big)\rd z \\
    & = \frac{2C_g}{\sqrt{\sigma_{11}+\sigma_{22}-2\sigma_{12}}} \int_0^\infty z^p g\Big(\frac{z^2}{\sigma_{11}+\sigma_{22}
    -2\sigma_{12}}\Big)\rd z \\
    & = (\sigma_{11} + \sigma_{22} - 2\sigma_{12})^{p/2} G_p(t),
  \end{align*}
  where $G_p(t) = \displaystyle \int_0^\infty t^{(p-1)/2}g(t)\rd t$. Thus, 
  \[
    \rho_p = 1 - \frac{\E(\lvert X_1-X_2\rvert^p)}{\E(\lvert X_1-X_2\rvert^p: \sigma_{12}=0)} 
    = 1 - \Big(\frac{\sigma_{11} + \sigma_{22} - 2\sigma_{12}}{\sigma_{11}+\sigma_{22}}\Big)^{p/2}.
  \]
\end{proof}

%%============================================================================%%
\begin{proof}[Proof of Proposition~{\rm\ref{prop:3}}]
  Since $\sigma_{12} = \rho\sqrt{\sigma_{11}\sigma_{22}}$ and $\mu_1=\mu_2$,
  \[
    v^2= \frac{1}{n-2}\Big\{\frac{(1-\rho^2)\rho_c^2}{(1-\rho_c^2)\rho^2} + \frac{4\rho_c^3(1-\rho_c)u^2}{\rho(1-\rho_c^2)^2}
    - \frac{2\rho_c^2u^4}{\rho^2(1-\rho_c^2)^2}\Big\} = \frac{(1-\rho^2)\rho_c^2}{(n-2)(1-\rho_c^2)\rho^2}.
  \]
   A straightforward calculation shows that
   \begin{align*}
    \var(\what{\rho}_p) & = \frac{1}{4}\rho v^2(1-\rho_c^2)^2\big\{1-\rho_c)^{p/2-1}\big\}^2 \\
    & = \frac{p^2 \left(1-\rho^2\right)\sigma _{11}\sigma_{22}\big(2\rho\sqrt{\sigma_{11}\sigma_{22}}
    + \sigma_{11} + \sigma_{22}\big)\big(1 - 2\rho\sqrt{\sigma_{11}\sigma_{22}}/(\sigma_{11} + 
    \sigma_{22})\big)^{p-1}}{(n-2)(\sigma_{11} + \sigma_{22})^3}.
  \end{align*}
  If $\rho<0$, then $1 - 2\rho\sqrt{\sigma_{11}\sigma_{22}}/(\sigma_{11} + 
  \sigma_{22})>1$ and the function $p\mapsto p^2\big(1 - 2\rho\sqrt{\sigma_{11}\sigma_{22}}/(\sigma_{11} + 
  \sigma_{22})\big)^{p-1}$ is strictly increasing in $p$ for $p>0$. Therefore, the minimum of $\var(\what{\rho}_p)$ occurs at $p=1$.
\end{proof}

