\bmsubsection*{ML estimation under equality of location parameters}

Consider $\bs{x}_1,...,\bs{x}_n$ as a random sample from a population following a $\mathsf{Laplace}_k(\bs{\mu},\bs{\Sigma})$ 
distribution, and consider the constraint,
\[
  \mu_1 = \mu_2 = \cdots = \mu_k = \lambda,
\]
that is, we can write $\bs{\mu} = \lambda\bs{1}_k$ with $\lambda\in\Rset$. Assume the hierarchical 
model,
\[
  \bs{X}_i\mid\omega_i \stackrel{\sf ind}{\sim} \mathsf{N}_k(\lambda\bs{1}_k,\bs{\Sigma}),
\]
and $\omega_i$ follows the distribution given by the density defined in Equation \eqref{eq:mixture}.
Thus, an EM algorithm\cite{Meng:1993} to perform the estimation subject to the constraint of equality 
among the location parameters is summarized in the following steps,
\begin{itemize}
  \item \textbf{E-step:} Using a current estimate for $\bs{\theta} = (\lambda,\bs{\sigma}^\top)^\top$, 
  the conditional expectation of the log-likelihood function for complete data assumes the form,
  \[
    Q(\bs{\theta};\bs{\theta}^{(r)}) = -\frac{n}{2}\log\lvert\bs{\Sigma}\rvert - \frac{1}{2}
    \sum_{i=1}^n \omega_i^{(r)}(\bs{x}_i - \lambda\bs{1}_k)^\top\bs{\Sigma}^{-1}(\bs{x}_i - \lambda\bs{1}_k),
  \]
  where the weights $\omega_i^{(r)}$ are defined in Equation \eqref{eq:E-step}, although they must be 
  evaluated at the distances,
  \[
    D_i(\bs{\theta}^{(r)}) = \big[(\bs{x}_i - \lambda\bs{1}_k)^\top\{\bs{\Sigma}^{(r)}\}^{-1}
    (\bs{x}_i - \lambda\bs{1}_k)\big]^{1/2}, \qquad i=1,\dots,n.
  \]

  \item \textbf{CM-step 1:} Update $\lambda^{(r+1)}$, as:
  \[
    \lambda^{(r+1)} = \frac{\bs{1}_k^\top\{\bs{\Sigma}^{(r)}\}^{-1}\bs{\mu}^{(r+1)}}
    {\bs{1}_k^\top\{\bs{\Sigma}^{(r)}\}^{-1}\bs{1}_k},
  \]
  where $\bs{\mu}^{(r+1)}$ is given in \eqref{eq:M-center}.

  \item \textbf{CM-step 2:} Update $\bs{\Sigma}^{(r+1)}$ by maximizing $Q(\bs{\theta};\bs{\theta}^{(r)})$ 
  with respect to $\bs{\sigma}$, leading 
  \[
    \bs{\Sigma}^{(r+1)} = \frac{1}{n}\,\sum_{i=1}^n \omega_i^{(r)}(\bs{x}_i - \lambda^{(r+1)}\bs{1}_k)
    (\bs{x}_i - \lambda^{(r+1)}\bs{1}_k)^\top.
  \]
\end{itemize}
Thus, the procedure iterates between the E-step and the CM-steps defined above until convergence is reached.

