\caption{Variation of real part of $ld_+$ (\ref{d_2l0_real}), and imaginary part of $ld_+$ (\ref{im_d2l}) as a function of $\Delta$ for $\Delta=\Delta_d$. All other simulation parameters are same as Figure. \ref{d_1l0_real}.}%
    \label{d_1l0}%
