\section{Identification and inference in a three period model}
In this example, we assume binary choice. We set $t_{a,1} = t_{a,2} = t_a$ and $t_{b,1} = t_{b,2} = t_b$ and assume the exclusion restrictions
\begin{align}
u_{1,t_a}(x_{a,1}) = &u_{1,t_a}(x_{a,2}) \\
u_{1,t_b}(x_{b,1}) = &u_{1,t_b}(x_{b,2})
\end{align}
The two exclusion restrictions lead to the two moment conditions 
\begin{align}
		&\ln\left(\frac{\cp_{1,t_a}(x_{a,1})}{\cp_{2,t_a}(x_{a,1})}\right) - \ln\left(\frac{\cp_{1,t_a}(x_{a,2})}{\cp_{2,t_a}(x_{a,2})}\right) = \nonumber \\
		 & \beta \delta \left[\mathbf{Q}_{1}(x_{a,1}) - \mathbf{Q}_K(x_{a,1})
		 -\mathbf{Q}_{1}(x_{a,2}) + \mathbf{Q}_K(x_{a,2})\right]
		 \left[\mathbf{m}_{t_a+1} + \delta \mathbf{Q}^{pb}_{t+1}\mathbf{v}_{t_a+2}  \right], \\
&\ln\left(\frac{\cp_{1,t_b}(x_{b,1})}{\cp_{2,t_b}(x_{b,1})}\right) - \ln\left(\frac{\cp_{1,t_b}(x_{b,2})}{\cp_{2,t_b}(x_{b,2})} \right)  =  \nonumber\\
		& \beta \delta \left[\mathbf{Q}_{1}(x_{b,1})  - \mathbf{Q}_K(x_{b,1})
		 -\mathbf{Q}_{1}(x_{b,2})+ \mathbf{Q}_k(x_{b,2})\right]\left[\mathbf{m}_{t_b+1} + \delta \mathbf{Q}^{pb}_{t_b+1}\mathbf{v}_{t_b+2} \right] .
\end{align}




% Period T-1
\subsection*{Period $T-1$} 
We first show that present-biased discount functions can not be identified from only two periods of observed choices and states. 
Let $t_a = t_b = T-1$, then define  
\begin{align*}
\Delta \mathbf{Q}_1(x_a) & = \left[\mathbf{Q}_1(x_{a,1}) - \mathbf{Q}_K(x_{a,1})- \mathbf{Q}_1(x_{a,2}) + \mathbf{Q}_K(x_{a,2})\right],
\end{align*}
and analogously for $\Delta \mathbf{Q}_1(x_b)$. Next, define 
\begin{align*}
\Delta \ln(\cp_{1, T-1}(x_a)) & = \ln\left(\frac{\cp_{1,T-1}(x_{a,1})}{\cp_{2,T-1}(x_{a,1})}\right) - \ln\left(\frac{\cp_{1,T-1}( x_{a,2})}{\cp_{2,T-1}(x_{a,2})}\right).
\end{align*}
The moment conditions in \eqref{eq:systemofmomentsA} can now be written
\begin{align}
		\Delta \ln(\cp_{1, T-1}(x_a)) & =  \beta \delta \Delta \mathbf{Q}_1(x_a) \mathbf{m}_{T}  \\
		\Delta \ln(\cp_{1, T-1}(x_b)) &=  \beta \delta \Delta \mathbf{Q}_1(x_b) \mathbf{m}_{T} 
\end{align}
The two polynomials are clearly linearly dependent. This also an example of a common factor. Since the parameters $\beta$ and $\delta$ are interchangeable in both moment conditions, they can not be separately identified with only two periods of data. Their product is however point identified. 

% Period T-2
\subsection*{Period $T-2$}
With three periods of data, the discount function parameters are formally set identified. 
Let $t_a = t_b = T-2$. The moment conditions are
\begin{align*}
		\Delta \ln(\cp_{1, T-2}(x_a)) & =   \beta \delta  \Delta \mathbf{Q}_1(x_a) \left[\mathbf{m}_{T-1} + \delta\mathbf{Q}^{pb}_{T-1}\mathbf{m}_{T} \right]   \\
				\Delta \ln(\cp_{1, T-2}(x_b)) & =   \beta \delta  \Delta \mathbf{Q}_1(x_b) \left[\mathbf{m}_{T-1} + \delta\mathbf{Q}^{pb}_{T-1}\mathbf{m}_{T} \right]  
\end{align*}
Writing out the terms, we get
\begin{align}
		 \Delta \ln(\cp_{1, T-2}(x_a)) = & \beta \delta \Delta \mathbf{Q}_1(x_a)\mathbf{m}_{T-1}  + \beta \delta^2 \Delta \mathbf{Q}_1(x_a)\overline{\mathbf{Q}}_{T-1}\mathbf{m}_{T} \nonumber + \\
		 &  \beta^2 \delta^2 \Delta \mathbf{Q}_1(x_a)\left[ \overline{\mathbf{Q}}_{T-1}- \mathbf{Q}_2 \right]\mathbf{m}_T    \\
		 \Delta \ln(\cp_{1, T-2}(x_b)) = & \beta \delta \Delta \mathbf{Q}_1(x_b)\mathbf{m}_{T-1}  + \beta \delta^2 \Delta \mathbf{Q}_1(x_b)\overline{\mathbf{Q}}_{T-1}\mathbf{m}_{T} + \nonumber \\
		 & \beta^2 \delta^2 \Delta \mathbf{Q}_1(x_b)\left[ \overline{\mathbf{Q}}_{T-1}- \mathbf{Q}_2 \right]\mathbf{m}_T 
\end{align}
We first note that the only term for which $\beta$ and $\delta$ are not interchangeable in period $T-2$ is $\beta \delta^2 \Delta \mathbf{Q}_1(x_a)\overline{\mathbf{Q}}_{T-1}\mathbf{m}_T$. The set identification of $\beta$ and $\delta$ therefore relies on a higher order interaction term. These terms are furthermore likely to be highly correlated in finite samples which suggests that precise estimation of the two parameters separately may be hard to achieve. We illustrate this point with a simulation below.




%% Estimation routine
\subsection{Estimation routine}
We estimate $\beta$ and $\delta$ from  the sample counterparts to the moment conditions in \eqref{eq:systemofmomentsA} and \eqref{eq:systemofmomentsB} by minimum distance. Holding the choice fixed at some $k \in \mathcal{D}\backslash \{K\}$,  a pair of periods $t$ and $t'$ and a pair of states $x_{1}$ and $x_{2}$ give the exclusion restriction $u_t(x_1) = u_{t'}(x_2)$. The corresponding moment is 
\begin{align}\label{eq:criterionmoment}
\mathbf{\psi}(\beta, \delta; x, t) = & \frac{\cp_{k,t}(x_{1})}{\cp_{K,t}(x_{1})} - \frac{\cp_{k,t'}(x_{2})}{\cp_{K,t'}(x_{2})}- \nonumber\\
&\beta\delta \left([\mathbf{Q}_k(x_{1}) - \mathbf{Q}_K(x_{2})] \mathbf{v}_{t+1} - [\mathbf{Q}_k(x_{2}) - \mathbf{Q}_K(x_{2})] \mathbf{v}_{t'+1} \right) 
\end{align}
where $\mathbf{v}_{t} = \mathbf{m}_t + \delta \mathbf{Q}^{pb}_t \mathbf{v}_{t+1}$.  We denote the vector of moments which has one element for each exclusion restriction  $\mathbf{\psi}(\beta, \delta;.,.)$. The minimum distance criterion is
\begin{align*}
S(\beta, \delta) & = \mathbf{\psi} \mathbf{W} \mathbf{\psi}'
\end{align*}
for a weight matrix $\mathbf{W}$. The gradient and the Hessian of the criterion function are given in the appendix.

