\section{Gradient and Hessian of the criterion function}
For each exclusion restriction in \eqref{eq:criterionmoment}, the corresponding moment $\mathbf{\psi}$ has derivatives 
\begin{align}
\frac{\partial \mathbf{\psi}(\beta, \delta; x, t)}{\partial \beta}  = - \delta \Bigg(&[\mathbf{Q}_k(x_1) - \mathbf{Q}_K(x_1)]\left[\mathbf{v}_{t+1}(\beta, \delta) + \beta \frac{\partial \mathbf{v}_{t+1}(\beta, \delta)}{\partial \beta} \right] -  \\
  & [\mathbf{Q}_k(x_2)- \mathbf{Q}_K(x_2)] \left[\mathbf{v}_{t'+1}(\beta, \delta) + \beta \frac{\partial \mathbf{v}_{t'+1}(\beta, \delta)}{\partial \beta} \right] \Bigg) \nonumber\\
  \frac{\partial \mathbf{\psi}(\beta, \delta; x, t)}{\partial \delta}  = - \beta \Bigg(&[\mathbf{Q}_k(x_1) - \mathbf{Q}_K(x_1)]\left[\mathbf{v}_{t+1}(\beta, \delta) + \delta \frac{\partial \mathbf{v}_{t+1}(\beta, \delta)}{\partial \delta} \right] -  \\
  & [\mathbf{Q}_k(x_2)- \mathbf{Q}_K(x_2)] \left[\mathbf{v}_{t'+1}(\beta, \delta) + \delta \frac{\partial \mathbf{v}_{t'+1}(\beta, \delta)}{\partial \delta} \right] \Bigg)\nonumber
\end{align}
The derivatives $\mathbf{v}_t(\beta, \delta) = \mathbf{m}_t + \delta \mathbf{Q}^{pb}_t(\beta)\mathbf{v}_{t+1}(\beta, \delta)$ are calculated recursively
\begin{align}
\frac{\partial \mathbf{v}_{t}(\beta, \delta)}{\partial \beta }& = \delta \left(\mathbf{Q}^{pb}_t(\beta) \frac{\partial \mathbf{v}_{t+1}(\beta, \delta)}{\partial \beta} + \delta [\mathbf{Q}_K - \mathbf{\overline{Q}}_t] \mathbf{v}_{t+1}(\beta, \delta) \right) \\
\frac{\partial \mathbf{v}_{t}(\beta, \delta)}{\partial \delta } & = \mathbf{Q}^{pb}_t(\beta)\left[\mathbf{v}_{t+1}(\beta, \delta) + \delta \frac{\partial \mathbf{v}_{t+1}(\beta, \delta)}{\partial \delta} \right] 
\end{align}
with terminal conditions $\frac{\partial \mathbf{v}_T}{\partial \beta}=   \frac{\partial \mathbf{v}_T}{\partial \delta} = 0$. The gradient of the criterion  
\begin{align}
S = \mathbf{\psi} \mathbf{W} \mathbf{\psi}'
\end{align}
is then
\begin{align}
g(\theta) = 2 \frac{\partial \mathbf{\psi}}{\partial \theta} \mathbf{W} \mathbf{\psi}',
\end{align}
where $\theta = [\beta, \delta]$. 
\\
\\
The second derivatives of a given moment are  
\begin{align}
\frac{\partial^2 \mathbf{\psi}(\beta, \delta; x, t)}{\partial \beta \partial \delta} = -\frac{1}{\delta}\frac{\partial \mathbf{\psi} }{\partial \beta} - &
 \delta \left[\mathbf{Q}_k(x_1) - \mathbf{Q}_K(x_1)\right]\left[\frac{\partial \mathbf{v}_{t+1}}{\partial \delta} + \beta \frac{\partial^2 \mathbf{v}_{t+1}}{\partial \delta \partial \beta} \right] - \nonumber \\ 
&\left[\mathbf{Q}_k(x_2) - \mathbf{Q}_K(x_2)\right]\left[\frac{\partial \mathbf{v}_{t'+1}}{\partial \delta} + \beta \frac{\partial^2 \mathbf{v}_{t'+1}}{\partial \delta \partial \beta}\right] \\
\frac{\partial^2 \mathbf{\psi}(\beta, \delta; x, t)}{\partial \beta^2 } = -\delta \bigg(&\left[\mathbf{Q}_k(x_1) - \mathbf{Q}_K(x_1)\right]\left[2\frac{\partial \mathbf{v}_{t+1}}{\partial \beta} + \beta \frac{\partial^2 \mathbf{v}_{t+1}}{\partial \beta^2}\right] - \nonumber \\& \left[\mathbf{Q}_k(x_2) - \mathbf{Q}_K(x_2)\right]\left[2\frac{\partial \mathbf{v}_{t'+1}}{\partial \beta} + \beta \frac{\partial^2 \mathbf{v}_{t'+1}}{\partial \beta^2}\right] \bigg) \\
\frac{\partial^2 \mathbf{\psi}(\beta, \delta; x, t)}{\partial \delta^2 } = -\beta \bigg(&\left[\mathbf{Q}_k(x_1) - \mathbf{Q}_K(x_1)\right]\left[2\frac{\partial \mathbf{v}_{t+1}}{\partial \delta} + \delta \frac{\partial^2 \mathbf{v}_{t+1}}{\partial \delta^2}\right] - \nonumber \\& \left[\mathbf{Q}_k(x_2) - \mathbf{Q}_K(x_2)\right]\left[2\frac{\partial \mathbf{v}_{t'+1}}{\partial \delta} + \delta \frac{\partial^2 \mathbf{v}_{t'+1}}{\partial \delta^2}\right] \bigg)
\end{align}
The second derivatives of the value functions are calculated recursively
\begin{align}
\frac{\partial \mathbf{v}_t}{\partial \delta \partial \beta} & = \frac{\partial \mathbf{Q}^{pb}_t}{\partial \beta} \left[\mathbf{v}_{t+1} + \delta \frac{\partial \mathbf{v}_{t+1}}{\partial \beta} \right] + \mathbf{Q}^{pb}_t\left[\frac{\partial \mathbf{v}_{t+1}}{\partial \beta} + \delta \frac{\partial \mathbf{v}_{t+1}}{\partial \delta \partial \beta} \right]   \\
\frac{\partial \mathbf{v}_{t}}{\partial \beta^2} & = \delta \left[ \frac{ \partial \mathbf{Q}^{pb}_t}{\partial \beta}\left[\frac{\partial \mathbf{v}_{t+1}}{\partial \beta} + \delta \mathbf{v}_{t+1}\right] + \mathbf{Q}^{pb}_t \frac{\partial \mathbf{v}_{t+1}}{\partial \beta^2} \right] \\
\frac{\partial^2 \mathbf{v}_t}{\partial \delta^2} & = \mathbf{Q}^{pb}_t \left[2\frac{\partial \mathbf{v}_{t+1}}{\partial \delta} + \delta \frac{\partial \mathbf{v}_{t+1}}{\partial \delta^2} \right]
\end{align}
where we note that $\frac{\partial \mathbf{Q}^{pb}_t}{\partial \beta} = \mathbf{Q}_K - \overline{\mathbf{Q}}_t$. The Hessian is 
\begin{align}
H(\theta) = 2\left(\frac{\partial^2 \mathbf{\psi}}{\partial \theta^2}\mathbf{W} \left[\mathbf{I}_2 \otimes \mathbf{\psi}'\right] + \frac{\partial \mathbf{\psi}}{\partial \theta}\mathbf{W}\frac{\partial \mathbf{\psi}'}{\partial \theta}\right).
\end{align}

