\subsection{Proof of \Cref{thm:CharacterizationVisiblyFairMechanisms}}


\begin{proof}
    \underline{Part 1}: A $m$-queue allocation mechanism is visibly fair. 


    For any officer $k\in I$, since $a_k \in G(S^k,m_k)$, there does not exist a $s \in S^k$ such that $s \succ_{m_k} a_k$. Meanwhile, for all $s \in S \setminus S^k$, $|\{ i\in I:  i< k \text{ and } a_i=s\}|= q_{s}$. Therefore, the outcome of $m$-queue allocation mechanism is not visibly unfair.

    \noindent  \underline{Part 2}: A visibly fair mechanism is a $m$-queue allocation mechanism


    For any $m\in M$, consider the outcome $\psi(m)=a$ of a visibly fair mechanism. Define set $S^k$ for each officer $k\in I$ as follows:

\begin{itemize}
\item[] \textbf{Step $0$}:  Set $S^1=S$.


    \item[] \textbf{Step $k$ ($1\leq k\leq n$)}: Set $s^k=a_k$. If the number of officers assigned to $s^k$ reaches $q_{s^k}$, that is $|\{ i\in I:  i\leq k \text{ and } a_i=s^k\}|= q_{s^k}$, then $S^{k+1}\equiv S^{k}\backslash\{s^k\}$. Otherwise, $S^{k+1}= S^{k}$.


\end{itemize}

Since allocation $a^k$ is visibly fair, we also have that $a^k \in G(S^k,m_k)$. Since, $a_k \in G(S^k, m_k)$, $\psi$ is a $m$-queue allocation mechanism.
\end{proof}





\subsection{Proof of \Cref{thm:CharacterizationIncontestableMechanisms2}}
\begin{proof}
\underline{Part 1}: A partitioned priority mechanism is visibly fair.

For any officer $k\in I$, since $a_k \in G(S^k,m_k)$, there does not exist a $s \in S^k$ such that $s \succ_{m_k} a_k$. Meanwhile, for all $s \in S \setminus S^k$, $\left|\{ i\in I:  i< k \text{ and } a_i=s\}\right|= q_{s}$. Therefore, the outcome of partitioned priority mechanism cannot be visibly unfair.

\noindent  \underline{Part 2}: A visibly fair mechanism is a partitioned priority mechanism.

For each $m\in M$, consider the outcome $\psi(m)=a$ of a visibly fair mechanism. We now construct a zone selection function $\mathcal{C}_k$ and set $S^k$ for each officer $k\in I$ by using the following steps:

\begin{itemize}
\item[] \textbf{Step $0$}:  Set $S^1=S$.


    \item[] \textbf{Step $k$ ($1\leq k\leq n$)}: $\mathcal{C}_k(S^k,m)=z $ if $a_k \in z$. If the number of officers assigned to $s^k$ reaches $q_{s^k}$, that is $\left|\{ i\in I:  i\leq k \text{ and } a_i=s^k\}\right|= q_{s^k}$, then $S^{k+1}\equiv S^{k}\backslash\{s^k\}$. Otherwise, $S^{k+1}= S^{k}$.


\end{itemize}

The values of $\mathcal{C}_k(S',m)$ for the remaining combinations of $S'\subseteq S$ and $m\in M$ can take any value, since they are never used.

Since the allocation $a$ is visibly fair,  we also have that for all $k$, $a^k \in G(S^k,m_k)$. Since, $a_k \in G(S^k, m_k) \cap \mathcal{C}_k(S^k,m))$, $\psi$ is a partitioned priority mechanism. 

\end{proof}

\subsection{Proof of \Cref{thm:CharacterizationIncontestableMechanisms3}}

\begin{proof} \underline{Part 1}: A ranked partitioned priority mechanism is visibly fair.

For any officer $k\in I$, since $a_k \in G(S^k,m_k)\cap \mathcal{C}_k(S^k,m)$, there does not exist a $s \in S^k$ such that $s \succ_{m_k} a_k$. Meanwhile, for all $s \in S \setminus S^k$, $\left|\{ i\in I:  i< k \text{ and } a_i=s\}\right|= q_{s}$. Therefore, the outcome of ranked partitioned priority mechanism cannot be visibly unfair.


\noindent  \underline{Part 2}: A visibly fair mechanism is a ranked partitioned priority mechanism.

\Cref{thm:CharacterizationIncontestableMechanisms2}'s constructed zone selection function and argument apply here as well. For each $m\in M$, consider the outcome $\psi(m)=a$ of a visibly fair mechanism. We now construct a zone selection function $\mathcal{C}_k$ and set $S^k$ for each officer $k\in I$ by using the following steps:

\begin{itemize}
\item[] \textbf{Step $0$}:  Set $S^1=S$.


    \item[] \textbf{Step $k$ ($1\leq k\leq n$)}: $\mathcal{C}_k(S^k,m)=z $ if $a_k \in z$. If the number of officers assigned to $s^k$ reaches $q_{s^k}$, that is $\left|\{ i\in I:  i\leq k \text{ and } a_i=s^k\}\right|= q_{s^k}$, then $S^{k+1}\equiv S^{k}\backslash\{s^k\}$. Otherwise, $S^{k+1}= S^{k}$.


\end{itemize}

The values of $\mathcal{C}_k(S',m)$ for the remaining combinations of $S'\subseteq S$ and $m\in M$ can take any value, since they are never used.

Since the allocation $a$ is visibly fair,  we also have that for all $k$, $a^k \in G(S^k,m_k)$. Since, $a_k \in G(S^k, m_k) \cap \mathcal{C}_k(S^k,m))$, $\psi$ is a partitioned priority mechanism. 




We need to additionally show that the constructed zone selection function is a ranked zone selection function. 

Suppose not, then for officer $k\in I$, $S^k \cap \mathcal{C}_k(S^k,m) =  \left\{min\left(\mathcal{C}_k(S^k,m),m_k\right)\right\}$ and there is a zone $z \in Z$ such that  $z\rhd_{k} \mathcal{C}_k(S^k,m)$ and $max\left(m_k,z\right)\in S^k$. Since $max\left(m_k,z\right) \succ_{m_k} min\left(\mathcal{C}_k(S^k,m),m_k\right)$, $a^k= min\left(\mathcal{C}_k(S^k,m_k),m_k\right)$ is visibly unfair for officer $k$ under $m$.
\end{proof}







\subsection{Proof of \Cref{thm:Truthful1}}


\textit{ A visibly fair mechanism is strategy-proof if and only if it satisfies expressiveness and weak availability. }


\begin{proof}



\textbf{If part a.} % EXPR. --> SP &&& Contrapositive: not SP --> not EXPR.
A visibly fair mechanism satisfying weak availability is strategy-proof if it satisfies expressiveness. 
We prove the contrapositive statement: If a visibly fair mechanism satisfying weak availability is not strategy-poof it does not satisfy expressiveness. 

\begin{enumerate}
\item By assumption, there exists a truthful message $m_i$ and a message $\hat{m}_i \in M_i$ such that $\psi(\hat{m}_i, m_{-i})_i \succ_i \psi(m)_i$.

%\item As $\psi(\hat{m}_i, m_{-i})_i$ is strictly preferred to $\psi(m)_i$ we must have $\psi(\hat{m}_i, m_{-i})_i \neq \psi(m)_i$.

\item By weak availability $\psi(\hat{m}_i, m_{-i})_i$ is available under $\psi(m)$.

\item  The information $\psi(\hat{m}_i, m_{-i})_i \succ_{m_i} \psi(m)_i$ would lead to a violation of visible fairness. Thus, we have found a violation of expressiveness. 
\end{enumerate}


\textbf{If part b.} % AVIL. --> SP &&& Contrapositive: not SP --> not AVAIL.
A visibly fair mechanism satisfying expressiveness is strategy-proof if it satisfies weak availability. 
We prove the contrapositive statement: If a visibly fair mechanism satisfying expressiveness is not strategy-poof it does not satisfy weak availability. 

\begin{enumerate}
\item By assumption, there exists a truthful message $m_i$ and a message $\hat{m}_i \in M_i$ such that $\psi(\hat{m}_i, m_{-i})_i \succ_i \psi(m)_i$.

%\item As $\psi(\hat{m}_i, m_{-i})_i$ is strictly preferred to $\psi(m)_i$ we must have $\psi(\hat{m}_i, m_{-i})_i \neq \psi(m)_i$.

\item By expressiveness the information $\psi(\hat{m}_i, m_{-i})_i \succ_{m_i} \psi(m)_i$ is available under $\psi(m)$.

\item  The availability of $\psi(\hat{m}_i, m_{-i})_i$ under $\psi(m)$ would lead to a violation of visible fairness. Thus, we have found a violation of weak availability. 
\end{enumerate}


\bigskip

\textbf{Only if part a.}
% SP --> EXPRESSIVE  &&& Contrapositive: not EXPRESSIVE --> not SP
 A visibly fair mechanism satisfying weak availability also satisfies expressiveness if it is strategy-proof.
We prove the contrapositive statement: If a visibly fair mechanism satisfying weak availability does not satisfy expressiveness then it is not strategy-proof. 

\begin{enumerate}

\item
By assumption there exist messages $m_i$ and $\hat{m}_i$ s.t. neither $\psi(\hat{m}_i, m_{-i})_i \succ_{m_i} \psi(m)_i$ nor $ \psi(m)_i \succ_{m_i} \psi(\hat{m}_i, m_{-i})_i$

\item Consider any preference $\succsim^*_i \in Q_i$ s.t.  $\psi(\hat{m}_i, m_{-i}) \succ^*_{i} \psi(m)$ and $s \succ^*_i s'$ whenever $s \succ_{m_i} s'$. By construction, $m_i$ is a truthful message for preference $\succsim^*_i \in Q_i$. Moreover, there exists another message   $\hat{m}_i \in M_i$ such that $\psi(\hat{m}_i, m_{-i})_i \succ_i \psi(m)_i$, i.e., a violation of strategy-proofness. 

%As $m_i\in M_i$ that is truthful for a preference $\succsim_i \in \mathcal{Q}_i$ it directly follows that $m'_i\in M_i \setminus \{m_i\}$ is a successful manipulation as $\psi(m'_i, m_{-i})_i \succ_i \psi(m)_i$.
\end{enumerate}


\textbf{Only if part b.}
% SP --> AVAILABILITY  &&& Contrapositive: not AVAILABILITY --> not SP
 A visibly fair mechanism satisfying expressiveness also satisfies weak availability if it is strategy-proof.
We prove the contrapositive statement: If a visibly fair mechanism satisfying expressiveness does not satisfy weak availability then it is not strategy-proof. 

\begin{enumerate}

\item As $m_i\in M_i$ that is truthful for a preference $\succsim_i \in \mathcal{Q}_i$ it directly follows that $m'_i\in M_i\setminus\{m_i\}$ is a successful manipulation as $\psi(m'_i,m_{-i})_i \succ_i \psi(m)_i$.
\end{enumerate}

\end{proof}



\subsection*{Proof of \Cref{thm:Truthful2}}

\textit{ A mechanism is strategy-proof if and only if it satisfies consistency.  }


\begin{proof}



\textbf{If part a.}
A mechanism is strategy-proof if it satisfies consistency. 
We prove the contrapositive statement: If a mechanism is not strategy-poof it does not satisfy expressiveness. 

\bigskip

 \noindent By assumption, there exists a truthful message $m_i$ and a message $\hat{m}_i \in M_i$ such that $\psi(\hat{m}_i, m_{-i})_i \succ_i \psi(m)_i$. 
 As $\psi(\hat{m}_i, m_{-i})_i$ is strictly preferred we have $\psi(\hat{m}_i, m_{-i})_i \neq \psi(m)_i$.  As $m_i$ is truthful we cannot have $\psi(m) \succ_{m_i} \psi(\hat{m}_i, m_{-i})$, and therefore $\psi(\hat{m}_i, m_{-i})\in G(\{\psi(m)\} \cup \{\psi(\hat{m}_i, m_{-i})\} , m_i)$, i.e., a violation of consistency. 

\bigskip

\textbf{Only if part a.}
 A mechanism satisfies consistency if it is strategy-proof.
We prove the contrapositive statement: If a mechanism does not satisfy consistency then it is not strategy-proof. 


 \noindent By assumption, there exists a  message $m_i$ and a message $\hat{m}_i \in M_i$ such that  $\psi(\hat{m}_i, m_{-i})\in G(\{\psi(m)\} \cup \{\psi(\hat{m}_i, m_{-i})\}$. 
 Consider any preference $\succsim^*_i \in Q_i$ s.t.  $\psi(\hat{m}_i, m_{-i}) \succ^*_{i} \psi(m)$ and $s \succ^*_i s'$ whenever $s \succ_{m_i} s'$. By construction, $m_i$ is a truthful message for preference $\succsim^*_i \in Q_i$. Moreover, there exists another message   $\hat{m}_i \in M_i$ such that $\psi(\hat{m}_i, m_{-i})_i \succ_i \psi(m)_i$, i.e., a violation of strategy-proofness. 


\end{proof}



\subsection{Proof of \Cref{modulartheorem}}

\begin{proof}
    First, it should be clear that the Modular Priority Mechanism is a partitioned priority mechanism: each agent, following the priority order, is associated with a zonal message space, and is matched to the most-preferred state from a zone that still has states with spare capacity.

    Next, we show that, for any given set of type-specific modular upper-bound systems and exogenous rankings \( (\blacktriangleright_{i})_{i\in I} \), the Modular Priority Mechanism, represented by the function $\psi$,is strategy-proof. Notice first that, by construction, an officer $i$ cannot, by submitting a different message, change the assignment of any officer $j<i$ and, as a consequence, the zones that are feasible for her. Since the zone from which $i$'s assignment will be drawn from depends on the assignment of officers with higher priority and the ranking $\blacktriangleright_{i}$, both unaffected by $m_i$.

    Notice, therefore, that since for any $m$ and $m_i'$, $\psi(m)$ and $\psi(m_i', m_{-i})$ are comparable under both $m_i$ and $m_i'$ (since they must all be in the same zone).This implies that, for any officer $i$ and true preference $\succsim_i\in \mathcal{Q}_i$, if $m_i$ is a truthful message, then $m_i$ completely ranks all states in a zone exactly like $\succsim_i$. 

    All of this implies that there is no preference $\succsim_i\in \mathcal{Q}_i$ with truthful message $m_i \in M_i$ and $m'_i \in M_i\setminus \{m_i\}$ for which $\psi(m_i', m_{-i}) \neq \psi(m)$ and $\psi(m_i', m_{-i})\succ_i \psi(m)$.  Therefore, $\psi$ trivially satisfies expressiveness and availability.

    Finally, we need to show that the Modular Priority Mechanism respects modular upper-bounds. That is, the final allocation \(\psi(m) = a\) satisfies, for every type \( t \in T \) and every upper-bound \( (S_h^{t}, k_h^{t}) \in H^{t} \):
\[
    \left| \left\{ i \in I : a_i \in S_h^{t},\ t_i = t \right\} \right| \leq k_h^{t}.
\]

We prove this by induction on the steps \( k = 1, 2, \ldots, n \) of the mechanism. In order to facilitate notation and comprehension, we will denote by $a^t$ the ``tentative'' allocation $a$ by the end of step $t$ of the mechanism.

\medskip

\noindent\textbf{Base Case (\( k = 0 \))}:

At initialization, no officers have been assigned. That is, \( a^0_i = \emptyset \) for all \( i \in I \). Therefore, for any type \( t \in T \) and upper-bound \( (S_h^{t}, k_h^{t}) \in H^{t} \), we have:
\[
    \left| \left\{ i \in I : a^0_i \in S_h^{t},\ t_i = t \right\} \right| = 0 \leq k_h^{t}.
\]
Thus, the allocation trivially respects all modular upper-bounds at step \( k = 0 \).

\medskip

\noindent\textbf{Inductive Step}:

Assume that at step \( k - 1 \), the current assignment \( a^{k-1} \) respects all modular upper-bounds; that is, for every type \( t \in T \) and upper-bound \( (S_h^{t}, k_h^{t}) \in H^{t} \):
\[
    N_{h}^{k-1} = \left| \left\{ i \in I : a_i^{k-1} \in S_h^{t},\ t_i = t \right\} \right| \leq k_h^{t}.
\]

We need to show that after assigning officer \( i_k \) at step \( k \), the updated assignment \( a^{k} \) also respects all modular upper-bounds.

\medskip

Consider officer \( i_k \) of type \( t_{i_k} \). There are two cases:

\medskip

\noindent\textbf{Case 1: Officer \( i_k \) is assigned to a state \( s^\ast \)}:

According to the mechanism, \( i_k \) is assigned to a state \( s^\ast\) within a zone \( z^* \) where the upper-bounds for type \( t_{i_k} \) involving states in that zone are not yet binding before $i_k$'s assignment---this is tracked by the flag \( B_{z^*}^{t_{i_k}} = \text{False} \).

That is, for every upper-bound involving type $t_{i_k}$ and upper-bound \( (S_h^{t}, k_h^{t}) \in H^{t} \) for which  $s^\ast\in S_h^{t}$:

\[
    \left| \left\{ i \in I : a_i^{k-1} \in S_h^{t},\ t_i = t \right\} \right| < k_h^{t}.
\]

Since all of these constraints are strictly below their upper-bounds after assigning \( i_k \) to \( s^\ast \) they will remain below their bounds or hit them. None of them will go beyond their limits. Therefore, the resulting assignment $a^k$ respects all modular upper-bounds.

\medskip

\noindent\textbf{Case 2: Officer \( i_k \) remains unmatched}:

If no feasible zone is found for \( i_k \), they remain unmatched; that is, \( a^{k}_{i_k} = \emptyset \) and \( a^{k}_i = a^{k-1}_i \) for all \( i \neq i_k \). In this case, $a^{k-1}_i$ respects upper-bounds, so does $a^{k}_i$.

\medskip

\noindent\textbf{Conclusion}:

In both cases, the assignment \( a^{k} \) at step \( k \) respects all modular upper-bounds. By induction, the final allocation \( a^{n} \) produced by the mechanism satisfies:
\[
    \left| \left\{ i \in I : a_i^{n} \in S_h^{t},\ t_i = t \right\} \right| \leq k_h^{t},
\]
for every type \( t \in T \) and every upper-bound \( (S_h^{t}, k_h^{t}) \in H^{t} \).

\end{proof}


\subsection{Proof of \Cref{thm:NoMechanismAllThree}}

\begin{proof}
Consider a problem with three officers \(I=\{i_1,i_2,i_3\}\) (with priority \(\pi(i_1) < \pi(i_2) < \pi(i_3)\)) and two states \(S = \{s_1, s_2\}\) with capacity \(q_{s_1} = q_{s_2} = 2\). Assume that all officers are of the same type \(t\) and that the modular upper--bound for type \(t\) is \((\{s_1\}, 1)\); that is, at most one officer of type \(t\) may be assigned to \(s_1\).

Thus, any allocation that \emph{respects the upper--bounds} must assign at most one officer to \(s_1\). We now show that no visibly fair mechanism in this setup is constrained Pareto efficiency.

Since there are two states, each officer’s message space admits only two possibilities regarding the comparison between \(s_1\) and \(s_2\): (i) The officer can express a strict preference between \(s_1\) and \(s_2\), or (ii) The officer cannot express any comparison between \(s_1\) and \(s_2\).

Next, note that no mechanism that elicits preferences of more than one officer between \(s_1\) and \(s_2\) and is visibly fair respects modular upper-bounds. To see that, assume that two officers express that $s_1\succ_i s_2$. Visible fairness requires that $s_1$ does not have and empty slot. But this would violate modular upper-bounds.

Any visibly fair mechanism that respects modular upper-bounds, therefore, will not elicit preferences for at least two officers.


Let's denote the overall message-space configuration by a triple $(X_1,X_2,X_3)$, where \(X_k = \text{Y}\) if officer \(i_k\) can express a preference between \(s_1\) and \(s_2\), and \(X_k = \text{N}\) otherwise.

We now examine the four cases in which we do not elicit preferences for at least two officers and show that in each case, \emph{either} the mechanism must return an assignment that violates the modular upper--bound (i.e., assigns two or more officers to \(s_1\)), \emph{or} the outcome is not constrained Pareto efficient (because it is Pareto dominated by another allocation that still respects the upper--bound).

\vspace{1em}
\noindent \textbf{Case 1:} \((X_1,X_2,X_3) = (\text{Y}, \text{N}, \text{N})\).
Suppose \(i_1\) reports \(s_2 \succ s_1\). By visible fairness she is assigned \(s_2\). By visible fairness and modular upper-bounds, the mechanism must assign \(i_2\) and \(i_3\) to \(s_1\) and \(s_2\). Suppose it assigns $i_2$ to $s_1$ and $i_3$ to $s_2$. If their true preferences are such that $s_2\succ_{i_2}s_1$ and $s_1\succ_{i_3}s_2$, an assignment that swaps their matches Pareto dominates the aoutcome, while still respecting modular upper-bounds. The same reasoning can be applied if the mechanism swaps the assignments of $i_2$ and $i_3$.

\vspace{1em}

\noindent \textbf{Case 2:} \((X_1,X_2,X_3) = (\text{N}, \text{N}, \text{Y})\).
Suppose that $i_3$ reports $s_2\succ_{i_3}s_1$. There are two cases to consider: (i) one of $i_1$,$i_2$ is matched to $s_1$, or (ii) both $i_1$ and $i_2$ are matched to $s_2$. In the first case, let without loss of generality $i_1$ be matched to $s_2$ and $i_2$ be matched to $s_1$ and. Then, if $i_1$ prefers $s_1$ and $i_2$ prefers $s_2$, swapping their assignments would Pareto dominate the outcome produced by the mechanism while still respecting modular upper-bounds.

In the second case, both $i_1$ and $i_2$ are matched to $s_2$. Suppose that one of them prefer $s_1$ to $s_2$. Then swapping that agent's assignment with $i_3$ would Pareto dominate the outcome produced by the mechanism while still respecting modular upper-bounds.

\vspace{1em}

\noindent \textbf{Case 3:} \((X_1,X_2,X_3) = (\text{N}, \text{Y}, \text{N})\).
Suppose that $i_2$ reports $s_2\succ_{i_2}s_1$. Then, visible fairness requires that she is assigned to $s_2$. By modular upper-bounds, $i_1$ and $i_3$ are matched to $s_1$ and $s_2$. Suppose that both prefer the other's assignment. Then, swapping their matches would Pareto dominate the outcome produced by the mechanism while still respecting modular upper-bounds.

\vspace{1em}

\noindent \textbf{Case 4:} \((X_1,X_2,X_3) = (\text{N}, \text{N}, \text{N})\).

The mechanism must choose an assignment of two officers to $s_2$ and one to $s_1$ solely by some fixed rule. Let $i$ be the officer matched to $s_1$ and $i', i''$ be matched to $s_2$ (their precise identities do not matter in this case). Suppose that $i$ prefers $s_2$ to $s_1$, and $i'$ prefers $s_1$ to $s_2$. Then, swapping their matches would Pareto dominate the outcome produced by the mechanism while still respecting modular upper-bounds.

\medskip

In every case, the following occurs: either the outcome produced by the mechanism (which is constrained to be \emph{upper--bound respecting}) violates the modular upper--bound (by assigning more than one officer to \(s_1\)), or there exists another allocation that both respects the upper--bounds and yields a strict Pareto improvement with respect to the officers' true preferences. Therefore, no mechanism exists that is simultaneously visibly fair and is constrained Pareto efficient.

\end{proof}



\subsection{Proof of \Cref{dynamicModPriorityMechVisiblyFairModularAndSP}}



\begin{proof}
  \underline{Part 1}: Visible fairness.\\
  In the Dynamic Modular Priority Mechanism, officers are processed in strict priority order \(i_1,i_2,\dots,i_n\). For each officer \(i_k\), the mechanism partitions the state space \(S\) into two zones: $z_1$ and $z_2$. Officer \(i_k\) is matched to her most-preferred state in $z_1$. Therefore, there is no state that $i_k$ ranks above her assignment. This is true for every officer, and therefore the resulting assignment is visibly fair.

  \underline{Part 2}: Respects modular upper-bounds.\\
  We show by induction on the assignment order that for any type \(t\in T\) and any modular upper-bound \((S_h^t, k_h^t)\), the number of type-\(t\) officers assigned to states in \(S_h^t\) never exceeds \(k_h^t\).

\emph{Base Case.} Before any assignment (step 0), no officer is assigned and the count is \(0 \le k_h^t\).

\emph{Inductive Step.} Suppose that after assigning officers \(i_1,\dots,i_{k-1}\), the upper-bound \((S_h^t,k_h^t)\) is not violated. When officer \(i_k\) (of type \(t_{i_k}\)) is considered, if \(t_{i_k} \neq t\) the claim is unaffected. If \(t_{i_k}=t\) and \(i_k\) is assigned a state \(s\) with \(s\in S_h^t\), then by construction \(s\) belongs to zone \(z_1\) for \(i_k\) and the current count of type-\(t\) officers in \(S_h^t\) is strictly less than \(k_h^t\). If after assignment the count reaches \(k_h^t\), the mechanism updates \(B^t\) by adding \((S_h^t,k_h^t)\); hence, any subsequent officer of type \(t\) will have \(S_h^t\) excluded from her zone $z_1$. Thus, by induction, no upper-bound is ever violated.

  \underline{Part 3}:  Strategy-proof.\\
We show that no officer can obtain a strictly better outcome by misreporting her preferences. In the mechanism, the available set of states for officer \(i_k\) is determined solely by:
\begin{enumerate}
    \item The assignments of all higher-priority officers \(i_1,\dots,i_{k-1}\), and
    \item The set \(B_k^{t_{i_k}}\) of binding modular upper-bounds for type \(t_{i_k}\).
\end{enumerate}
Neither of these depends on the message \(m_{i_k}\) provided by officer \(i_k\). Thus, her feasible set—the zone \(z_1\)—remains fixed regardless of her report. Within \(z_1\), if \(m_{i_k}\) truthfully reflects her preference ordering, she is assigned her top available choice. Any misreport would merely permute her ranking over the same fixed set \(z_1\) and cannot result in an outcome strictly preferred (by her true preference) to her truthful assignment. Therefore, the mechanism is strategy-proof.


 \underline{Part 4}:  Constrained Pareto efficient.\\
Assume for contradiction that there exists an allocation \(a'\) which Pareto dominates \(a\) and also respects all modular upper-bounds. Let \(i^*\) be the highest-priority officer for whom \(a'_{i^*} \succ_{i^*} a_{i^*}\); that is, for every officer \(j < i^*\), we have \(a'_j = a_j\).

Consider officer \(i^*\). Under the Dynamic Modular Priority Mechanism, when \(i^*\) was processed, she was assigned \(a_{i^*}\) as her most-preferred available state in zone $z_1$. If \(a'_{i^*} \succ_{i^*} a_{i^*}\), then the state \(a'_{i^*}\) must have been available when \(i^*\) was considered. There are two possibilities:

\begin{enumerate}
    \item \emph{Capacity constraint:} The state \(a'_{i^*}\) might have been unavailable because its capacity was already exhausted by officers \(j < i^*\). However, since \(a'_j = a_j\) for all \(j < i^*\), the capacity allocated in \(a\) and \(a'\) is identical for states assigned to higher-priority officers. Thus, if \(a'_{i^*}\) is available in \(a'\), it must have been available for \(i^*\) in \(a\) as well.
    \item \emph{Binding Upper-Bound:} The other reason for \(a'_{i^*}\) not to be in \(i^*\)’s zone $z_1$ under \(a\) is if \(a'_{i^*}\) belonged to a set \(S_h^{t_{i^*}}\) for which the corresponding upper-bound \((S_h^{t_{i^*}}, k_h^{t_{i^*}})\) was already binding at the time of \(i^*\)’s assignment. However, if \(a'_{i^*}\) were in such a set and \(a'\) respects the upper-bound, then \(a'_{i^*}\) could not be assigned to \(i^*\) without causing the total number of type \(t_{i^*}\) officers in \(S_h^{t_{i^*}}\) to exceed \(k_h^{t_{i^*}}\).
\end{enumerate}

In either case, if \(a'_{i^*}\) is strictly better for \(i^*\) than \(a_{i^*}\), then the state \(a'_{i^*}\) must have been available for \(i^*\) under the mechanism; hence, the mechanism would have assigned \(a'_{i^*}\) to \(i^*\) rather than \(a_{i^*}\). This contradiction shows that no allocation \(a'\) can Pareto dominate \(a\) while still respecting all modular upper-bounds. Therefore, any allocation \(a'\) that Pareto dominates \(a\) must violate some modular upper-bound.
\end{proof}


\subsection{More on efficiency}

An allocation $a$ is \textbf{visibily efficient under $m$}  if it is not visible that it is Pareto dominated by another allocation, that is, there is no allocation $a^\prime \in \mathcal{A}$ such that for all $i \in I$ with $a^\prime_i \not= a_i$, we have   $a^\prime_i \succ_{m_i} a_i$. A mechanism $\psi$ is \textbf{visibly efficient} if $\psi(m)$ is visibility efficient for all $m\in M$. 



\begin{thm}
\label{thm:Efficiency}
For any message $m\in M$, the following statements are true.
\begin{enumerate}
    \item Every visibly fair allocation is visibly efficient.
    \item A visibly efficient allocation may not be visibly fair. 

\end{enumerate}

\end{thm}


\begin{proof}
       \underline{Statement 1}: Fix a message \(m\in M\). Suppose \(a \in \mathcal{A}\) is a visibly fair allocation that is not visibly efficient under $m$. Then there exists another allocation \(a^{\prime} \in \mathcal{A}\) such that for all $i \in I$ with $a^\prime_i \not= a_i$, we have   $a^\prime_i \succ_{m_i} a_i$. 

Let $i^*$ be the highest ranking officer among the ones that are allocated to a different state under $a$ and $a'$ and let $s^*$ be her assigned state. That is, for \[ \bar{I}:=\left \{ i\in I:a_i\ne a^\prime_i \right \}, \qquad i^* := \arg\min_{i\in \bar{I}} \pi(i),  \quad \text{and} \quad a'_{i^*}=s^*.\]

Allocation $a$ must be visibly unfair for officer $i^*$ under $m$. This is because either $a_i=s^*$ for some $i \in \bar{I}$, or $|\{ i\in I: a_i=s^*\}|< q_{s^*}$. Yet $s^* \succ_{m_{i^*}} a_{i^*}$.


    \underline{Statement 2}:     Let $I=\{1,2\}$, $S=\{s_1,s_2\}$, $q_{s_1}=q_{s_2}=1$, and $\pi(i)=i$. Additionally, assume zonal message space, $Z=\{z_1\}$ with $z_1 = \{s_1,s_2\}$.  For preferences ${s_1} \succ_1 s_2$ and $s_1 \succ_2 {s_2} $, the allocation $(a_1, a_2) =(s_2,s_1)$ is visibly efficient but not visibly fair under the truthful message.

\end{proof}



In contrast, an allocation $a$ is \textbf{Pareto efficient}  if it is not Pareto dominated by another allocation, that is, there is no allocation $a^\prime \in \mathcal{A}$ such that for all $i \in I$ with $a^\prime_i \not= a_i$, we have   $a^\prime_i \succ_i a_i$. A mechanism $\psi$ is \textbf{Pareto efficient} if $\psi(m)$ is Pareto efficient for all $m\in M$.

\begin{thm}
\label{thm:Efficiency2}
For any truthful message $m\in M$, the following statements are true.
\begin{enumerate}
    \item Every Pareto efficient allocation is visibly efficient.
    \item A visibly efficient allocation may not be Pareto efficient. 

    \item A visibly fair allocation may not be Pareto efficient.
\end{enumerate}

\end{thm}

\begin{proof}
    \underline{Statement 1}: Consider an allocation \(a \in \mathcal{A}\) that is not visibly efficient for some truthful message \(m\in M\). This implies there is another allocation \(a^\prime \in \mathcal{A}\) such that for all $i \in I$ with $a^\prime_i \not= a_i$, we have $a^\prime_i \succ_{m_i} a_i$, and therefore $a^\prime_i \succ_i a_i$ ($m$ is a truthful message). Thus, \(a\) is not Pareto efficient.

    \underline{Statement 2 and 3}:     Let $I=\{1,2\}$, $S=\{s_1,s_2,s_3\}$, $q_{s_1}=q_{s_2}=q_{s_3}=1$, and $\pi(i)=i$. Additionally, assume a zonal message space, $Z=\{z_1, z_2\}$ with  $z_1=\{s_1,s_2\}$ and $z_2=\{s_3\}$. For preferences $s_3 \succ_1 {s_1} \succ_1 s_2$ and $s_1 \succ_2 {s_3} \succ_2 s_2$, the allocation $(a_1, a_2) =(s_1,s_3)$ is visibly fair and visibly efficient under the truthful message as $s_1$ and $s_3$ are incomparable. However, it is not Pareto efficient.
\end{proof}






Message $\hat{m}$ \textbf{contains more preference information than} $m$, if for all $i\in I$:

$$s \succ_{m_i} s'  \quad \implies \quad s \succ_{\hat{m}_i} s'.$$

\begin{thm}
\label{thm:Efficiency3}
Suppose message $\hat{m}$ contains more preference information than $m$. Then the following statements are true. 

\begin{enumerate}
    \item Every visibly fair allocation under $\hat{m}$ is also visibly fair under $m$.
    \item A visibly fair allocation under ${m}$ may not be visibly fair under $\hat{m}$.
    \item Every visibly efficient allocation under $\hat{m}$ is also visibly efficient under $m$.
    \item A visibly efficient allocation under ${m}$ may not be visibly efficient under $\hat{m}$.
\end{enumerate}
\end{thm}

\begin{proof}
    \underline{Statement 1}: If allocation \(a\) is not visibly fair under \(m\) because there exist some \(i\in I\) such that there is a $j\in I$ such that $a_i\not=a_j$, $\pi(i) <  \pi(j)$, and $a_j \succ_{m_i} a_i$. Since $a_j \succ_{\hat{m}_i} a_i$, $a$ cannot be visibly fair under $\hat{m}$.

    If allocation \(a\) is not visibly fair under \(m\) because there exist some \(i\in I\) such that there is a $s\in S$ such that $a_i\not=s$, $|\{ i\in I: a_i=s\}|\leq q_s$, and $s \succ_{m_i} a_i$. Since $s \succ_{\hat{m}_i} a_i$,  $a$ cannot be visibly fair under $\hat{m}$.

\underline{Statement 3}: If allocation \(a\) is not visibly efficient under \(m\), then there exists another allocation \(a^\prime\) such that for all $i \in I$ with $a^\prime_i \not= a_i$, we have   $a^\prime_i \succ_{m_i} a_i$. Since $a^\prime_i \succ_{\hat{m_i}} a_i$ for all such $i\in I$, $a$ cannot be visibly efficient under \(\hat{m}\). 

\underline{Statement 2 and 4}: Let $I=\{1,2\}$, $S=\{s_1,s_2,s_3\}$, $q_{s_1}=q_{s_2}=q_{s_3}=1$, and $\pi(i)=i$. Additionally, assume a zonal message space, $Z=\{z_1, z_2\}$ with  $z_1=\{s_1,s_2\}$ and $z_2=\{s_3\}$. For preferences $s_3 \succ_1 {s_1} \succ_1 s_2$ and $s_1 \succ_2 {s_3} \succ_2 s_2$, the allocation $(a_1, a_2) =(s_1,s_3)$ is visibly fair and visibly efficient under the truthful message $m$ as $s_1$ and $s_3$ are incomparable. 

Consider the zonal message space $Z=\{S\}$. The truthful message $\hat{m} = (\succ_i)_{i\in I}$ contains more preference information than $m$. However,  allocation $(a_1, a_2) =(s_1,s_3)$  is not visibly fair and visibly efficient under $\hat{m}$.
\end{proof}

