\title{Asymmetric SICs over finite fields}
\author{Joseph W.\ Iverson\thanks{Department of Mathematics, Iowa State University, Ames, IA} \and Dustin G.\ Mixon\thanks{Department of Mathematics, The Ohio State University, Columbus, OH} \thanks{Translational Data Analytics Institute, The Ohio State University, Columbus, OH}}
