\section{Preliminaries}
\label{sec:definitions-preliminaries}

\subsection{Notation}
\label{sec:notation}

We denote by $\Naturals$, $\Integers$, and $\Reals$ the set of naturals, integers, and reals, respectively. $[i:j]\eqdef\{i,i+1,\ldots,j\}$ for $i,j\in \Integers$, $i\leq j$. Vectors are \emph{row} vectors and boldfaced, e.g., $\vect{x}$. The all-zero vector is denoted by $\vect{0}$. Matrices and sets are represented by capital sans serif letters and calligraphic uppercase letters, respectively, e.g., $\mat{X}$ and $\set{X}$. An identity matrix $n \times n$ is denoted by $\mat{I}_n$. The inner product of two vectors is denoted by $\inner{\vect{a}}{\vect{b}}$. The natural embedding $\phi_q \colon\Integers_q^n \rightarrow \Integers^n$ is such that $\phi_q(x)$ maps each element $x\in\Integers_q$ to the corresponding integer.

\subsection{Lattices and Linear Codes}
\label{sec:basics_codes-lattices}

A \emph{lattice} $\Lambda\subset\Reals^n$ is a discrete additive subgroup of $\Reals^{n}$. A (full rank) lattice can also be seen as $\Lambda=\{\vect{\lambda}=\vect{u}\mat{L}_{n\times n}\colon\vect{u}\in\Integers^n\}$, where the $n$ rows of the \emph{generator matrix} $\mat{L}$ form a lattice basis in $\Reals^n$. If a lattice $\Lambda$ has generator matrix $\mat{L}$, then the lattice $\Lambda^\star\subset\Reals^n$ generated by $\trans{\bigl(\inv{\mat{L}}\bigr)}$ is called the \emph{dual lattice} of $\Lambda$. The \emph{volume} of a lattice $\Lambda$ is $\vol{\Lambda} = \ecard{\det(\mat{L})}$. A \emph{sublattice} $\Lambda'$ of a lattice $\Lambda$ is a lattice such that $\Lambda' \subseteq \Lambda$.

Next, we define the theta series of a lattice $\Lambda$. %., which describes its spectrum of distance.

\begin{definition}[Theta series]
  \label{def:theta-series}
  Let $\Lambda$ be a lattice. Its theta series is given by
  \begin{IEEEeqnarray*}{c}
    \Theta_\Lambda(z) = \sum_{\vect{\lambda}\in\Lambda} q^{\norm{\vect{\lambda}}^2}
    =\sum_{\vect{\lambda}\in\Lambda}\ope^{i\pi z\norm{\vect{\lambda}}^2},
  \end{IEEEeqnarray*}
  where $q\eqdef\ope^{i\pi z}$ and $\Im{z} > 0$.
\end{definition}

Here, we will consider $z$ to be purely imaginary. Then, the theta series of $\Lambda$ reduces to
\begin{equation*}
  \Theta_\Lambda(i\tau)=\sum_{\vect{\lambda}\in\Lambda}\ope^{-\pi\tau\norm{\vect{\lambda}}^2}.\label{eq:theta-series_tau}
\end{equation*}

A lattice $\Lambda$ is said to be \emph{integral} if the inner product of any two lattice vectors is an integer or equivalently if and only if $\Lambda \subseteq \Lambda^\star$. An integral lattice such that $\Lambda = \Lambda^\star$ is a \emph{unimodular} lattice. A lattice that can be obtained from
its dual by a rotation or reflection is called \emph{isodual}. We say that a lattice $\Lambda$ is \emph{formally unimodular} if and only if $\Theta_{\Lambda}(z)=\Theta_{\Lambda^\star}(z)$.  It is worth mentioning that unimodular, isodual, and formally unimodular lattices all have volume equal to $1$.
A lattice $\Lambda$ is said to be \emph{stable} if $\vol{\Lambda}=1$ and $\vol{\Lambda'}\geq 1$ for all sublattice $\Lambda' \subseteq \Lambda$. Unimodular lattices are stable~\cite[Cor., p.~407]{Weng02_1}.

Analogous to the theta series of a lattice, a binary $[n,k]$ linear code\footnote{A binary $[n,k]$ code $\code{C}$ is a $k$-dimensional linear subspace of $\Field_2^n$. In general, codes can be defined over a Galois field $\Field_q$.} $\code{C}\subseteq\Field_2^n$ has a \emph{weight enumerator}
\begin{IEEEeqnarray*}{c}
  W_\code{C}(x,y)=\sum_{\vect{c}\in\code{C}} x^{n-\Hwt{\vect{c}}}y^{\Hwt{\vect{c}}} % \nonumber \\
  =\sum_{w=0}^n A_w(\code{C})\, x^{n-w}y^w,\IEEEeqnarraynumspace
  \label{eq:weight-enumerator}
\end{IEEEeqnarray*}
where $A_w(\code{C})\eqdef\card{\{\vect{c}\in\code{C}\colon\Hwt{\vect{c}}=w\}}$, $w\in[0:n]$. 

Next, we define the \emph{generalized Hamming weight} of linear codes, a quantity that characterizes the weights of subcodes of a given linear code $\code{C}$.

\begin{definition}[Generalized Hamming weight~\cite{Wei91_1}]
  \label{def:def_GHW_Z2}
  The $r$-th generalized Hamming weight of an $[n,k]$ code $\code{C}$ is the size of the smallest support of an $r$-dimensional subcode of $\code{C}$, i.e., 
  \begin{IEEEeqnarray*}{c}
    d_{r}(\code{C})=\min\{w(\code{C}_r)\colon\code{C}_r ~ \textnormal{is an $[n,r]$ subcode of}~\code{C}
    % ~\textnormal{of dimension}~r
    \},
    \IEEEeqnarraynumspace
  \end{IEEEeqnarray*}
considering $w(\code{C}) = \bigl|\{i\in [1:n]\colon\exists\,\vect{c}=(c_1,\ldots,c_n) \in \code{C}~\textnormal{s.t.}~c_i \neq 0\}\bigr|$, and $r\in [1:k]$. We define $\vect{d}(\code{C})\eqdef\{d_1(\code{C}),\ldots,d_k(\code{C})\}$ as the \emph{weight hierarchy} of a code $\code{C}$ and $d_r(\code{C})$ denotes the $r$-th generalized Hamming weight of $\code{C}$.
\end{definition}

We remark that, in the literature, most results on generalized Hamming weights are established for binary $[n,k]$ codes. However, there also exist several results concerning linear codes over $\Field_q$. See, for example,~\cite{JurriusPellikaan09_1}.

The generalized Hamming weight is monotonic.

\begin{theorem}\cite[Thm.~1]{Wei91_1} 
\label{thm:order-generalized-hamming-weight}
For an $[n,k]$ linear code $\code{C}$ with $k>0$, we have that
\begin{IEEEeqnarray*}{c}
1 \leq d_1(\code{C}) < d_2(\code{C})< \cdots < d_{k}(\code{C}) \leq n.   
\end{IEEEeqnarray*}
\end{theorem}

\begin{example}
  \label{ex:generalized-hamming-weight}
  Consider two non-isometric $[6,3]$ binary codes $\code{C}_1$ and $\code{C}_2$ in~\cite[pp.~40--42]{ConwayFung09_1}, with respective generator matrices $\mat{G}^{\code{C}_1} = (\mat{I}_3 ~ \mat{B}_1)$ and $\mat{G}^{\code{C}_2} = (\mat{I}_3 ~ \mat{B}_2)$, where
  \begin{IEEEeqnarray*}{c}
    \mat{B}_1=
    \begin{pmatrix}
      1 &  0 & 0
      \\
      0 &  1 & 0
      \\
      0 &  0 & 1
    \end{pmatrix}
    \textnormal{ and }
    \mat{B}_2=
    \begin{pmatrix}
      0 &  1 & 0
      \\
      1 &  1 & 1
      \\
      0 &  1 & 0
    \end{pmatrix}.
  \end{IEEEeqnarray*}

  The weight hierarchies of $\code{C}_1$ and $\code{C}_2$ are 
  \begin{IEEEeqnarray*}{c}
    \vect{d}(\code{C}_1)=\{2,4,6\}\textnormal{ and }\vect{d}(\code{C}_2)=\{2,3,6\}.
  \end{IEEEeqnarray*}

  The distinct weight hierarchies indicate that the two codes are indeed non-isometric. However, they have the same weight enumerator 
  \begin{IEEEeqnarray*}{c}
    W_{\code{C}_1}(x,y)= W_{\code{C}_2}(x,y)=x^6+3x^4y^2+3x^2y^4+y^6,
  \end{IEEEeqnarray*}
  and thus, are said to be \emph{isospectral}.\exampleend

\end{example}

Lattices can be constructed from linear codes through Construction A~\cite{ConwaySloane99_1, Zamir14_1}. A $\Integers_q$ linear code $\code{C}$ of length $n$ is an additive subgroup of $\Integers_q^n$. 

\begin{definition}[{Construction A~\cite[p.~31]{Zamir14_1}}]
  \label{def:def_ConstrAq}
  Let $\code{C}$ be a $\Integers_q$ linear code, then $\ConstrAq[q]{\code{C}}\eqdef\frac{1}{\sqrt{q}}(\phi_q(\code{C}) + q\Integers^n)$ is a lattice.
\end{definition}

\subsection{Conjectures on the Theta Series}

Characterizing the theta series of a general lattice is a hard task. It has applications in many fields, being used to bound the success probability of eavesdropping a message in communication channels~\cite{BelfioreSole10_1}, or in theoretical computer science, where it is believed that the theta series of the integer lattice $\Integers^n$ maximizes the theta series of stable lattices~\cite{RegevStephens-Davidowitz24_1}.

We start by defining a particular quotient of the theta series.

\begin{definition}[{Theta series ratio~\cite{BollaufLin24_1sub}}]
  \label{def:secrecy_ratio}
  Let $\Lambda$ be a lattice with volume $\vol{\Lambda}=1$. The theta series ratio of $\Lambda$ is defined by
  \begin{equation*}
    \Delta_{\Lambda}(\tau)\eqdef\frac{\Theta_{\Lambda}(i \tau)}{\Theta_{\Integers^n}(i \tau)},\quad\tau\eqdef -i z>0.
    \label{eq:def_secrecy-ratio}
  \end{equation*} 
\end{definition}

Regev and Stephen-Davidowitz conjectured that $\Delta_{\Lambda}(\tau) \leq 1$ for all stable lattices~\cite{RegevStephens-Davidowitz24_1}.

\begin{conjecture}[{Upper bound on the theta series ratio for stable lattices}]
  \label{conj:RSD}
  For all stable lattices $\Lambda\subset\Reals^n$ and \emph{for all} $\tau>0$, it holds that
  \begin{equation*}
    \Theta_{\Lambda}(i \tau) \leq \Theta_{\Integers^n}(i \tau) \text{ or equivalently }\Delta_{\Lambda}(\tau)\leq 1.
  \end{equation*}
\end{conjecture}

In the context of Gaussian wiretap channel communication, the theta series ratio is also of fundamental importance since it upper bounds the error probability of an eavesdropper guessing a sent message once lattice coset encoding is performed~\cite{BelfioreSole10_1}. The original conjecture was stated for unimodular lattices.

\begin{conjecture}[{Global minimum of the theta series ratio for unimodular lattices}]
  \label{conj:conjecture_BelfioreSole_unimodular-lattices}
  The theta series ratio of a unimodular lattice $\Lambda$ achieves its global minimum at $\tau=1$, i.e.,
  \begin{equation*}
    \argmin_{\tau>0}\Delta_{\Lambda}(\tau)=1.
    \label{eq:global-minimum_unimodular-lattices}
  \end{equation*}
\end{conjecture}
Later on, the same conjecture was extended to isodual~\cite[Conj.~1]{OggierSoleBelfiore16_1} and formally unimodular lattices~\cite[Conj.~37]{BollaufLinYtrehus23_3}. Given that formally unimodular lattices are also isodual, we will focus on isodual lattices from this point onward. Nevertheless, the same conclusions apply to formally unimodular lattices.  % from now on, we focus on isodual, but the same conclusion also holds for formally unimodular lattices.

Fig.~\ref{fig:good_secrecy_gain_bordered_double_circulant_n6} illustrates several \emph{typical} isodual lattices that simultaneously satisfy Conjectures~\ref{conj:RSD} and~\ref{conj:conjecture_BelfioreSole_unimodular-lattices}.
  \begin{figure}[t!]
    \centering
    % \Scale[0.8]{
    \input{\Figs/good_secrecy_gain_bordered_double_circulant_n6.tex} %}
    \caption{Theta series ratios as a function of $\tau>0$ for several \emph{isodual} lattices that both satisfy Conjectures~\ref{conj:RSD} and~\ref{conj:conjecture_BelfioreSole_unimodular-lattices}. Observe that $\Delta_{\Lambda}(\tau)\leq 1$ for all $\tau>0$ and $\argmin_{\tau>0}\Delta_{\Lambda}(\tau)=1$.}
    \label{fig:good_secrecy_gain_bordered_double_circulant_n6}
