%	\begin{itemize}
	%		\item[] [type-1.1] $R$ agents at the meeting;
	%		\item[] [type-1.2] $x\cdot R$ agents at the meeting;
	%		\item[] [type-1.3] $j$ agents at the meeting, where $j\ne R$ and $j\ne x\cdot R$;
	%	\end{itemize}
%	\item [] [type-2] no fast agents and at least one sentinel agent at the meeting;
%	\begin{itemize}
