Lemma \ref{lem-basic-capture} shows in how many rounds an agent $a$ that moves with speed one can capture an agent that moves with half speed and progresses in the same direction as $a$.

\begin{lemma}\label{lem-basic-capture}
	Let $a$ denote the agent that performs 
	\texttt{proceed}($\cdot, false$) and let $b$ denote the agent that starts performing \texttt{proceed}($\cdot, true$) after wake-up.
	If $a$ and $b$ progress left (resp. right) and $a$ is left (resp. right) of $b$ at a distance $\ell$ in the round $t$, for any even number $t\ge 2$, then $a$ captures $b$ in round $t+2\ell$.
\end{lemma}

\begin{proof}
	Without loss of generality, assume that both $a$ and $b$ progress left.
	Hence, in round $t$, $a$ is left of $b$ at a distance $\ell$.
	Between rounds $t$ and $t+2\ell$, $a$ moves for $2\ell$ rounds and $b$ moves for $\ell$ rounds.
	Before the round $t+2\ell$, $a$ is left of $b$, and in the round $t+2\ell$, both $a$ and $b$ are at the same node.
	Moreover, since $t$ is even, $t+2\ell$ is also even.
	Therefore, in round $t+2\ell$, $a$ moves and $b$ stays idle, and thus $a$ meets $b$ in round $t+2\ell$.
\end{proof}

Lemma \ref{lem-double-capture} shows how many rounds it takes a singleton agent $a$ to capture every agent in the team associated with $a$  at least once, as $a$ swings.

\begin{lemma}\label{lem-double-capture}
	Let $a$ denote any singleton agent swinging in round $t$ between two non-singleton agents $b$ and $b'$ in the team associated with $a$.
	\begin{itemize}
		\item[i)] If $t$ is even, then $a$ catches each of $b$ and $b'$ at least once, between  round $t$ and round $9t$;
		\item[ii)] If $t$ is odd, then $a$ catches each of $b$ and $b'$ at least once, between round $t$ and round $9t+3$.
	\end{itemize}
\end{lemma}

\begin{proof}
	Without loss of generality, assume that in round $t$, $a$ is progressing towards $b$.

	If $t$ is even, then the distance between $b$ and $b'$ in round $t$ is $t$; hence, the distance between $a$ and $b$ is at most $t$.
	In view of Lemma \ref{lem-basic-capture}, $a$ captures $b$ by the round $t+2t=3t$.
	After capturing $b$, $a$ moves towards $b'$.
	By the round $3t$, the distance between $b'$ and $b$ is at most $3t$.
	In view of Lemma \ref{lem-basic-capture}, $a$ captures $b'$ by the round $3t+2(3t)=9t$.
	This proves the statement i).

	If $t$ is odd, then the distance between $b$ and $b'$ in round $t$ is $t+1$; hence, the distance between $a$ and $b$ is at most $t+1$.
	In round $t+1$, the distance between $a$ and $b$ is at most $t$.
	In view of Lemma \ref{lem-basic-capture}, $a$ captures $b$ by the round $t+1+2(t)=3t+1$.
	After capturing $b$, $a$ moves towards $b'$.
	By the round $3t+1$, the distance between $b'$ and $b$ is at most $3t+1$.
	In view of Lemma \ref{lem-basic-capture}, $a$ captures $b'$ by the round $3t+1+2(3t+1)=9t+3$.
	This proves the statement ii).
\end{proof}





