Lemma \ref{lem-assumption-forever} is used later to prove that in some round the agent $\alpha$ captures a non-singleton agent such that at the meeting the former agent stores in its bag $2(R-X_s)$ labels, and the later agent stores in its bag $X_s$ labels.


\begin{lemma}\label{lem-assumption-forever}
	Assume that after switching to a \texttt{fast} mode, every singleton agent swings for at least  $54D+9$ rounds  between the two agents in its associated team. By the round $54D+9$,
	\begin{itemize}
		\item  every singleton agent has caught at least one non-singleton agent in every non-singleton team, including the agents $\ell_R$ and $r_L$, and
		\item both $\ell_R$ and $r_L$ have been caught, respectively, by every singleton agent.
	\end{itemize}
\end{lemma}
\begin{proof}
	%From the round $t_x$, the agent $r_L$ is right of $\ell_r$.
	%Observe that as long as $r_L$ is right of $\ell_r$, between (inclusive) a non-singleton agent and its companion of every non-singleton team, there is at least one non-singleton agent from every non-singleton team, including $\ell_R$ and $r_L$.	
	%
	Let $t_m=\max(t_{asso}, t_x)$.
	In view of Lemmas \ref{lem-t-asso} and \ref{lem-t-x}, both $t_{asso}$ and $t_x$ are odd, and thus $t_m$ is odd.
	Let $t^a\ge t_m$, for any singleton agent $a$, denote the earliest round, not earlier than $t_m$, when $a$ captures a non-singleton agent, say $b$, in the team associated with $a$.

	Recall that $b$ stays idle in even rounds, and thus $t^a$ must be an even number.
	In view of statement i) of Lemma \ref{lem-double-capture}, from the round $t^a$ ($\ge t_m\ge t_x$) to the round $9t^a$, it happens at least once that 1) the singleton agent $a$ moves towards $b'$, starting from $b$, and captures $b'$, 2) and then the singleton agent $a$ moves towards $b$, starting from $b'$, and captures $b$.
	Therefore, by the round $9t^a$, the singleton agent $a$  has caught at least one non-singleton agent in every non-singleton team, including $\ell_R$ and $r_L$, in view of Observation \ref{obser} ii).
	%the agent $a$ captures sequentially $b'$ and $b$, from the round $t^a$ to $9t^a$.
	%
	%
	%In the round $t^a$, the distance between $b$ and its companion $b'$ is exactly $2\lceil \frac{t^a}{2} \rceil=t^a$.
	%In view of Lemma \ref{lem-basic-capture}, $a$ captures $b'$ in the round $t^a+2(t^a)=3t^a$.
	%In the round $3t^a$, the distance between $b$ and its companion $b'$ is exactly $3t^a$.
	%In view of Lemma \ref{lem-basic-capture}, $a$ captures $b$ again in the round $3t^a+2(3t^a)=9t^a$.






	Next, we show an upper bound on $t_a$.

	\begin{claim}\label{claim-t-a-upper-bound}
		We have $t^a\le 6D+1$.
	\end{claim}

	In order to prove the claim, recall that $t_m$ is an odd number and that $a$ captures $b$ when $a$ moves and $b$ stays.
	Therefore, $a$ cannot capture $b$ in the round $t_m$.
	Instead, $a$ is moving towards $b$ in round $t_m$, in view of the definition of $t^a$.	
	Let $b'$ denote the companion of the agent $b$ in the team associated with $a$.

	In round $t_m$, the distance between $b$ and $b'$ is $2\lceil \frac{t_m}{2}\rceil=t_m+1$, since $t_m$ is odd.
	Hence, the distance between $b$ and $a$ is at most $t_m+1$.
	In round $t_m+1$, $a$ moves and $b$ stays, as $t_m+1$ is even, and thus the distance between $b$ and $a$ is at most $t_m$.
	In view of Lemma \ref{lem-basic-capture}, $a$ has caught $b$ by the round $t_m+1+2(t_m)=3t_m+1$, and thus we have $t^a\le 3t_m+1$.
	In view of Lemmas \ref{lem-t-asso} and \ref{lem-t-x}, $t_m\le 2D$, and thus we have $t^a\le 6D+1$. $\diamond$


	In view of Claim \ref{claim-t-a-upper-bound}, we have $9t^a\le 54D+9$, for any singleton agent $a$.
	This concludes the proof.
\end{proof}

In view of \texttt{Event D}, only the agent $\alpha$ can switch to a \texttt{search} mode.
Next, we prove that $\alpha$ must switch to a \texttt{search} mode and give an upper bound on the round when it happens.

\begin{lemma}\label{lem-alpha-switch-search}
	The agent $\alpha$ switches to a \texttt{search} mode before the round $486D+84$.
\end{lemma}
\begin{proof}
	If the agent $\alpha$ switches to a \texttt{search} mode before the round $54D+9$, then the statement of the lemma is true.
	Otherwise, in the round $54D+9$, every singleton agent stores in its bag $2(R-X_s)$ labels of all non-singleton agents, and both $\ell_R$ and $r_L$ store in their respective bags the set of labels of all $X_s$ singleton agents, in view of Lemma \ref{lem-assumption-forever}.
	Hence, from the round $54D+9$ on, once the agent $\alpha$ captures one of non-singleton agents whose bag stores $X_s$ distinct labels, e.g., $\ell_R$ or $r_L$, $\alpha$ is guaranteed to switch to a \texttt{search} mode.

	Since $t_{asso}<2D$, the agent $\alpha$ has found its associated team by the round $54D+9$.
	Let $b$ and $b'$ denote two non-singleton agents in the team associated with $\alpha$.
	Without loss of generality, assume that $\alpha$ is progressing towards $b$ in round $54D+9$.
	Observe that $54D+9$ is an odd number.
	In view of statement ii) of Lemma \ref{lem-double-capture}, from the round $54D+9$ to the round $9(54D+9)+3$, it happens at least once that the agent $\alpha$ moves towards $b'$, starting from $b$, and captures $b'$.
	Recall that from the round $54D+9$ on, both $\ell_R$ and $r_L$ are between $b$ and $b'$.
	Therefore, $\alpha$ captures one non-singleton agent $c$ before the round $9(54D+9)+3$ such that at the meeting $\alpha$ stores $2(R-X_s)$ labels and $c$ stores $X_s$ labels.
	As a result, $\alpha$ switches to a \texttt{search} mode at the meeting, before the round $9(54D+9)+3=486D+84$.
\end{proof}

In view of \texttt{Event E}, the agent $\alpha$ switches from a \texttt{search} mode to the mode $\hiber$, once it captures an agent in a \texttt{slow} mode.
Next, we show an upper bound on the round when the agent $\alpha$ switches to the mode $\hiber$.

\begin{lemma}\label{lem-alpha-switch-hiber}
	The agent $\alpha$ has switched to the mode $\hiber$ by the round $1458D+252$.
\end{lemma}
\begin{proof}
	Recall that in the round when the agent $\alpha$ switches from a \texttt{fast} mode to a \texttt{search} mode, $\alpha$ changes its progressing direction and the bag stored by $\alpha$ has exactly $2(R-X_s)$ labels. %, and this must happen after the round $t_x$, in view of Lemma \ref{lem-t-x}.
	%In view of Lemma \ref{lem-t-x}, the agent $\alpha$ switches to a \texttt{search} mode after the round $t_x$.
	In view of Lemma \ref{lem-progressing-R-X-s}, there are $R-X_s$ non-singleton agents ahead of $\alpha$, each progressing in the same direction as $\alpha$.
	Hence, the first non-singleton agent caught by $\alpha$ must be either $r_L$ or $\ell_R$.

	If $\alpha$ switches to the mode $\hiber$ before the round $486D+84$, then the lemma holds.
	Otherwise, let $b$ and $b'$ denote the two non-singleton agents in the team associated with $\alpha$.
	Without loss of generality, assume that the agent $\alpha$ moves towards $b$ in the round $486D+84$.


	Observe that $486D+84$ is even and that in the round $486D+84$, the distance between $b$ and $b'$ is exactly $486D+84$.
	Since $\alpha$ is between $b$ and $b'$, the distance between $\alpha$ and $b$ is at most $486D+84$.
	In view of Lemma \ref{lem-basic-capture}, the agent $\alpha$ captures $b$ by the round $486D+84+2(486D+84)=1458D+252$.
	Recall that from round $t_x$ ($\le D+1$) on, both $\ell_R$ and $r_L$ are between (inclusive) the non-singleton agents in every non-singleton team.
	Therefore, the agent $\alpha$ captures either $\ell_R$ or $r_L$ by the round $1458D+252$, and thus $\alpha$ switches to the mode $\hiber$ by the round $1458D+252$.
\end{proof}

In view of \texttt{Event F}, when a singleton agent in a \texttt{fast} mode meets the agent $\alpha$, while the latter is in the mode $\hiber$, the former switches to the mode $\hiber$ as well. 
Next, we prove that every singleton agent switches to the $\hiber$ mode and stays with $\alpha$.

\begin{lemma}\label{lem-hiber-all}
	Every singleton agent, other than $\alpha$, meets $\alpha$ and switches to the mode $\hiber$ by the round $13122D+2268$.
\end{lemma}
\begin{proof}
	In view of Lemmas \ref{lem-t-asso} and \ref{lem-t-x}, the agent $\alpha$ switches to the $\hiber$ mode, after the round $\max(t_x, t_{asso})$.
	From the round $t_{asso}$ on, every singleton agent is associated with a non-singleton team.
	From the round $t_x$ on, the agents $\ell_R$ and $r_L$ are between two non-singleton agents in every non-singleton team.
	As the agent $\alpha$ switches to the mode $\hiber$ at a node between $\ell_R$ and $r_L$ and any singleton agent $a$, other than $\alpha$, swings between two non-singleton agents in the team associated with $a$, $a$ must meet $\alpha$ and switches to the mode $\hiber$.

	Assume that there are still singleton agents swinging in the round $1458D+252$; otherwise, the lemma holds.
	Let $c$ denote any of these singleton agents and let $b$ and $b'$ denote the non-singleton agents in the team associated with $c$.
	Without loss of generality, assume that $c$ is progressing towards $b$ in the round $1458D+252$.
	Observe that $1458D+252$ is even.
	In view of statement i) of Lemma \ref{lem-double-capture}, from the round $1458D+252$ to the round $9(1458D+252)$, it happens at least once that the agent $\alpha$ moves towards $b'$, starting from $b$, and captures $b'$.
	Since the agent $\alpha$ stays idle between $b$ and $b'$, $c$ must meet $\alpha$ and switch to the $\hiber$ mode, by the round $9(1458D+252)=13122D+2268$.
	This concludes the proof.
\end{proof}

In view of \texttt{Event F}, after all $X_s$ singleton agents are at the same node in the mode $\hiber$, each of them switches to a \texttt{collect} mode and moves in the same direction.
Without loss of generality, assume that they are progressing right.
Recall that $X_s$ singleton agents switched to the mode $\hiber$ at the same node between the agents $\ell_R$ and $r_L$.
Hence, there are $R-X_s$ non-singleton agents, progressing right in a \texttt{slow} mode, ahead of every non-singleton agent.
In view of \texttt{Event G}, each time the set of singleton agents capture a non-singleton agent, the latter switches to the same \texttt{collect} mode as others at the meeting and the agent $\alpha$ decrements its variable $countMultiTeams$ by one.
Recall that $countMultiTeams$ initially stores $R-X_s$.
When $countMultiTeams$ becomes $0$, agents capture the furthest non-singleton agent on the right side and they move together left with speed one.
Finally, all the agents gather after capturing the leftmost non-singleton agent.
The agent $\alpha$ knows when gathering happens, since $\alpha$ stores the total number of agents in its variable $total$.
This proves that algorithm \texttt{Team Sizes One and Two} guarantees gathering.
Its complexity is summarized as Theorem \ref{theorem-1-2}.

\begin{theorem}\label{theorem-1-2}
	Algorithm {\tt Team Sizes One and Two} gathers $R$ teams of agents at the same node of an unoriented line in $O(D)$ rounds, where $D$ denotes the distance between the bases of the most distant teams.
\end{theorem}
\begin{proof}
	Let $t_{coll}$ denote the round when all $X_s$ singleton agents switch from the $\hiber$ mode to a \texttt{collect} mode.
	Let $p$ (resp. $q$) denote the rightmost (resp. leftmost) non-singleton agent in the round $t_{coll}$.

	Let $t_1$ denote the round when $\alpha$ captures $p$.
	Note that $t_1$ must be even.
	In round $t_1$, the distance between $p$ and $q$ is at most $t_1+D$, as the distance between $p$ and its team companion $p'$ is $t_1$ and the distance between $p'$ and $q$ is at most $D$.
	In view of Lemma \ref{lem-basic-capture},  $\alpha$ captures $q$ by the round $t_1+2(t_1+D)=3t_1+2D$.
	Therefore, gathering is achieved by the round $3t_1+2D$.

	The distance between the agent $\alpha$ and $p$ in the round $t_{coll}$ is at most $t_{coll}+D$, as the distance between $\alpha$ and $r_L$ is at most $t_{coll}$ and the distance between $r_L$ and $p$ is at most $D$.

	In view of Lemma \ref{lem-basic-capture}, if $t_{coll}$ is even, then $t_1\le t_{coll}+2(t_{coll}+D)=3t_{coll}+2D$;
	otherwise, $t_1\le t_{coll}+1+2(t_{coll}+D-1)=3t_{coll}+2D-1$.
	Hence, we have $t_1\le 3t_{coll}+2D$.
	In view of Lemma \ref{lem-hiber-all}, we have $t_{coll}\leq 13122D+2268$, and thus gathering is achieved by the round $3t_1+2D\le 9t_{coll}+8D \leq118106D+20412$.
	This concludes the proof.
\end{proof}



