Denote by $\mathcal{G}(\boldsymbol{w})$ the set of graphs $\Gamma$ thus 
constructed, and note that this set is independent of $N$. For each such 
graph with $v_\Gamma$ vertices, we can recover all associated 
$\boldsymbol{i}\in\mathcal{I}_N(\boldsymbol{w})$ uniquely by assigning 
distinct values of $[N]$ to its vertices. There are 
$N(N-1)\cdots(N-v_\Gamma+1)$ ways to do this.
If the graph has $e_\Gamma^w$ edges with color 
$w$, then the corresponding expectation for each such $\boldsymbol{i}$ is
$$
	\mathbf{E}\big[ (U_{w_1}^N)_{i_1i_2}
	(U_{w_2}^N)_{i_2i_3}\cdots (U_{w_q}^N)_{i_qi_1}\big] =
	\prod_{w=1}^{r}
	\frac{1}{N(N-1)\cdots (N-e_\Gamma^w+1)},
$$
since the random variable in the expectation is the event that for
each $w$, the permutation matrix $U_w^N$ has $e_\Gamma^w$ of its rows
fixed as specified by the realizable tuple $\boldsymbol{i}$.
Here we presumed that $N\ge q$, which ensures that
$N\ge v_\Gamma$ and $N\ge e_\Gamma^w$.

In summary, we have proved the following.

\begin{lem}
For every $\boldsymbol{w}=(w_1,\ldots,w_q)$ and $N\ge q$, we have
$$
	\mathbf{E}\big[{\tr U_{w_1}^N\cdots U_{w_q}^N}\big] =
	\sum_{\Gamma\in \mathcal{G}(\boldsymbol{w})}
	\frac{N(N-1)\cdots(N-v_\Gamma+1)}{
	\prod_{w=1}^{r} N(N-1)\cdots (N-e_\Gamma^w+1)}.
$$
\end{lem}

The proof of Lemma \ref{lem:polyenc} is now straightforward.

\begin{proof}[Proof of Lemma \ref{lem:polyenc}]
We can rewrite the above lemma as
$$
	\mathbf{E}\big[\ntr U_{w_1}^N\cdots U_{w_q}^N|_{1^\perp}\big] =
	\sum_{\Gamma\in \mathcal{G}(\boldsymbol{w})}
	\bigg(\frac{1}{N}\bigg)^{e_\Gamma-v_\Gamma+1}
	\frac{\prod_{k=1}^{v_\Gamma-1} (1-\frac{k}{N})}{
	\prod_{w=1}^{r} \prod_{k=1}^{e_\Gamma^w-1} (1-\frac{k}{N})}
	-\frac{1}{N},
$$
where $e_\Gamma$ is the total number of edges in $\Gamma$.
As every $\Gamma$ is connected by construction, we have
$e_\Gamma-v_\Gamma+1\ge 0$ and thus the right-hand side is
a rational function of $\frac{1}{N}$.

Define a polynomial of degree $r(q-1)$ by
$$
	g_q(x) = (1-x)^r(1-2x)^r\cdots (1-(q-1)x)^r.
$$
Since $e_\Gamma^w\le e_\Gamma\le q$ for all $w$, it is clear that
$f_{\boldsymbol{w}}(\frac{1}{N})=
\mathbf{E}[\ntr U_{w_1}^N\cdots U_{w_q}^N|_{1^\perp}]\,g_q(\frac{1}{N})$
is a polynomial of degree at most $Cq$ for some constant $C$ (which 
depends on $r$).
\end{proof}

We can now read off the first terms in the $\frac{1}{N}$-expansion. 
Recall that $g\in\mathbf{F}_r\backslash\{e\}$ is called a \emph{proper 
power} if $g=v^k$ for some $v\in\mathbf{F}_r$, $k\ge 2$, and is called 
a \emph{non-power} otherwise. Every $g\ne e$ can be 
written uniquely as $g=v^k$ for a non-power $v$.

\begin{cor}
\label{cor:divisor}
We have
$$
	\mu_0(\boldsymbol{w}) =
	\lim_{N\to\infty} 
	\mathbf{E}\big[\ntr U_{w_1}^N\cdots U_{w_q}^N|_{1^\perp}\big]
	= 1_{g_{w_1}\cdots g_{w_q}=e}.
$$
Moreover, if $g_{w_1}\cdots g_{w_q}=v^k$ for a non-power $v$, then  
$$
	\mu_1(\boldsymbol{w}) =
	\lim_{N\to\infty} N\,
	\mathbf{E}\big[\ntr U_{w_1}^N\cdots U_{w_q}^N|_{1^\perp}\big]
	= \omega(k)-1,
$$
where $\omega(k)$ denotes the number of divisors of $k$.
\end{cor}

\begin{proof}
If $g_{w_1}\cdots g_{w_q}=e$, it is obvious that 
$\mu_0(\boldsymbol{w})=1$. We therefore assume this is not the case. We 
may further assume that $g_{w_1}\cdots g_{w_q}$ is cyclically reduced, 
since the left-hand side of Lemma \ref{lem:polyenc} is unchanged under 
cyclic reduction. Then every vertex of any 
$\Gamma\in\mathcal{G}(\boldsymbol{w})$ must have degree at least two.

For the first identity, it now suffices to note that there cannot exist 
$\Gamma\in\mathcal{G}(\boldsymbol{w})$ with $e_\Gamma-v_\Gamma+1=0$: this 
would imply that $\Gamma$ is a tree, which must have a vertex of 
degree one. Thus the expression in the proof of Lemma \ref{lem:polyenc} 
yields $\mu_0(\boldsymbol{w})=0$.

We can similarly read off from the proof of Lemma \ref{lem:polyenc} that
$$
	\mu_1(\boldsymbol{w}) = \#\{\Gamma\in\mathcal{G}(\boldsymbol{w}):
	e_\Gamma-v_\Gamma=0\} - 1.
$$
That $e_\Gamma-v_\Gamma=0$ implies (as each vertex has degree at least 
two) that $\Gamma$ is a cycle. As $\boldsymbol{w}$ defines a closed 
nonbacktracking walk in $\Gamma$, it must go around the cycle an integer
number of times, so the possible lengths of cycles are
the divisors of $k$.
\end{proof}


\subsection{The master inequality}

We now proceed to the core of the polynomial method. Our main tool 
is the following inequality of A.\ Markov \cite[p.\ 91]{Che98}.

\begin{lem}[Markov inequality]
\label{lem:markov}
For any real polynomial $f$ of degree $q$ and $a>0$
$$
	\|f'\|_{L^\infty[0,a]} \le \frac{2q^2}{a}\|f\|_{L^\infty[0,a]}.
$$
\end{lem}

As well known consequence of the Markov inequality is that a bound
on a polynomial on a sufficiently fine grid extends to a uniform bound
\cite[p.\ 91]{Che98}. For completeness, we spell out the argument in the 
form we will need it.

\begin{cor}
\label{cor:cheney}
For any real polynomial $f$ of degree $q$ and $M\ge 2q^2$, we have
$$
	\|f\|_{L^\infty[0,\frac{1}{M}]} \le 
	2\sup_{N\ge M} |f(\tfrac{1}{N})|.
$$
\end{cor}

\begin{proof}
For any $x\in[0,\frac{1}{M}]$, its distance to the set
$\{\frac{1}{N}\}_{N\ge M}$ is at most $\frac{1}{2M^2}$. Thus
$$
	\|f\|_{L^\infty[0,\frac{1}{M}]} \le
	\sup_{N\ge M} |f(\tfrac{1}{N})| + 
	\frac{1}{2M^2}\|f'\|_{L^\infty[0,\frac{1}{M}]}
	\le
	\sup_{N\ge M} |f(\tfrac{1}{N})| +
        \frac{q^2}{M} \|f\|_{L^\infty[0,\frac{1}{M}]}
$$
by the Markov inequality. The conclusion follows.
\end{proof}

In the following, we fix a self-adjoint
$P\in\mathbb{C}\langle x_1,\ldots,x_{2r}\rangle$ of degree $q_0$.
For every polynomial test function $h\in\mathcal{P}$ of degree $q$,
Lemma \ref{lem:polyenc} yields
$$
	\mathbf{E}\big[ \ntr h(P(\boldsymbol{U}^N,\boldsymbol{U}^{N*}))
	|_{1^\perp}\big] = \frac{f_h(\frac{1}{N})}{g_{qq_0}(\frac{1}{N})}
	=\Phi_h(\tfrac{1}{N})
$$
where $f_h,g_{qq_0}$ are real polynomials of degree at most $Cq$ and
$g_{qq_0}$ is defined in the proof of Lemma \ref{lem:polyenc}.
We define $\nu_0(h),\nu_1(h)$ for $h\in\mathcal{P}$ as in
\eqref{eq:expansion}, and denote by $K$ the sum of the moduli of
the coefficients of $P$. Note that all the above objects depend
on the choice of $P$, which we consider fixed.

The key idea is to use the Markov inequality to bound the
derivatives of $\Phi_h$.

\begin{lem}
\label{lem:polymethod}
For any $h\in\mathcal{P}$ of degree $q$, we have 
$$
	\|\Phi_h'\|_{L^\infty[0,\frac{1}{N}]} \le
	Cq^4\|h\|_{L^\infty[-K,K]},
	\qquad
	\|\Phi_h''\|_{L^\infty[0,\frac{1}{N}]} \le
	Cq^8\|h\|_{L^\infty[-K,K]}
$$
for all $N\ge Cq^2$, where $C$ is a constant (which depends on $P$).
\end{lem}

\begin{proof}
It is easily verified using the explicit expression for $g_{qq_0}$ in the 
proof of Lemma \ref{lem:polyenc} that there are constants $C,c>0$ (which 
depend on $P$) so that
$$
	c\le g_q(x)\le 1, \qquad
	\bigg|\frac{g_{qq_0}'(x)}{g_{qq_0}(x)}\bigg| \le Cq^2,\qquad
	\bigg|\frac{g_{qq_0}''(x)}{g_{qq_0}(x)}\bigg| \le Cq^4
$$
for all $x\in[0,\frac{1}{q^2}]$.
We now simply apply the chain rule. For the first derivative,
$$
	\|\Phi_h'\|_{L^\infty[0,\frac{1}{Cq^2}]} = 
	\bigg\|\frac{f_h'}{g_{qq_0}} -
	\frac{f_h}{g_{qq_0}}
	\frac{g_{qq_0}'}{g_{qq_0}}\bigg\|_{L^\infty[0,\frac{1}{Cq^2}]}
	\le
	\frac{3C}{c} q^4 \|f_h\|_{L^\infty[0,\frac{1}{Cq^2}]}
$$
using Lemma \ref{lem:markov}. But Corollary \ref{cor:cheney} yields
$$
	\|f_h\|_{L^\infty[0,\frac{1}{Cq^2}]} \lesssim
	\sup_{N\ge q^2} |f_h(\tfrac{1}{N})| \le
	\sup_{N\ge q^2} |\Phi_h(\tfrac{1}{N})| \le
	\|h\|_{L^\infty[-K,K]},
$$
where we used $g_q\le 1$ in the second inequality and that
$\|P(\boldsymbol{U}^N,\boldsymbol{U}^{N*})\|\le K$ in the last inequality.
The bound on $\Phi_h''$ is obtained
in a completely analogous manner.
\end{proof}

We now easily obtain a quantitative form of \eqref{eq:expansion}.

\begin{cor}[Master inequality]
\label{cor:master}
For every $h\in\mathcal{P}$ of degree $q$ and $N\ge 1$,
$$
	\bigg| 
	\mathbf{E}\big[ \ntr 
	h(P(\boldsymbol{U}^N,\boldsymbol{U}^{N*}))|_{1^\perp}\big]
	- \nu_0(h) - \frac{\nu_1(h)}{N} \bigg|
	\le \frac{Cq^8}{N^2} \|h\|_{L^\infty[-K,K]},
$$
as well as $|\nu_1(h)| \le Cq^4\|h\|_{L^\infty[-K,K]}$.
\end{cor}

\begin{proof}
The bound on $|\nu_1(h)|$ follows immediately from Lemma 
\ref{lem:polymethod} as $\nu_1(h)=\Phi_h'(0)$. 
Now note that the left-hand side of the equation display in the statement 
equals
$$
	\big|\Phi_h(\tfrac{1}{N}) - \Phi_h(0) - \tfrac{1}{N}\Phi_h'(0)\big|
	\le \tfrac{1}{2N^2}\|\Phi_h''\|_{L^\infty[0,\frac{1}{N}]}.
$$
Thus the bound in the statement follows for $N\ge Cq^2$ from
Lemma
\ref{lem:polymethod}. On the other hand, when $N<Cq^2$, we can trivially
bound
$$
	\bigg| 
	\mathbf{E}\big[ \ntr 
	h(P(\boldsymbol{U}^N,\boldsymbol{U}^{N*}))|_{1^\perp}\big] 
	- \nu_0(h) - \frac{\nu_1(h)}{N} \bigg| \le
	\bigg(2+ \frac{Cq^4}{N}\bigg)\|h\|_{L^\infty[-K,K]}
$$
by the triangle inequality, as 
$\nu_0=\mu_{P(\boldsymbol{u},\boldsymbol{u}^*)}$ is supported
in $[-K,K]$, and using the bound on $\nu_1(h)$.
The conclusion follows using $1<\frac{Cq^2}{N}$.
\end{proof}


\subsection{Extension to smooth functions}

We are now ready to prove Proposition~\ref{prop:smex}. To this end, we 
will show that Corollary \ref{cor:master} can be extended to smooth test 
functions $h$ using a simple Fourier-analytic argument.

Recall that the \emph{Chebyshev polynomial (of the first kind)} $T_n$ is
the polynomial of degree $n$ defined by 
$T_n(\cos\theta)=\cos(n\theta)$. Any $h\in\mathcal{P}$ of degree $q$
can be written as
$$
	h(x) = \sum_{n=0}^q a_n\,T_n(K^{-1}x)
$$
for some real coefficients $a_0,\ldots,a_q$. Note that the latter are 
merely the Fourier coefficients of the function $\tilde 
h:S^1\to\mathbb{R}$ defined by $\tilde h(\theta)=h(K\cos\theta)$.

\begin{proof}[Proof of Proposition~\ref{prop:smex}]
Fix any $h\in\mathcal{P}$ and let $a_0,\ldots,a_q$ be its Chebyshev
coefficients as above. As $\|T_n\|_{L^\infty[-1,1]}=1$ for all $n$,
we can estimate
$$
	|\nu_1(h)| \le
	\sum_{n=0}^q |a_n|\, |\nu_1(T_n(K^{-1}\cdot))|
	\le
	C\sum_{n=0}^q n^4|a_n|,
$$
using the estimate on $\nu_1$ in Corollary \ref{cor:master}.
Now note that $n^ka_n$ is the $n$th Fourier coefficient of
the $k$th derivative $\tilde h^{(k)}$ of $\tilde h$.
We can therefore estimate
$$
	|\nu_1(h)| \le
	C\Bigg(\sum_{n=0}^q \frac{1}{n^2}\Bigg)^{\frac{1}{2}}
	\Bigg(
	\sum_{n=0}^q  n^{10}|a_n|^2\Bigg)^{\frac{1}{2}} 
	\le C' \|\tilde h^{(5)}\|_{L^2(S^1)}
	\le C'' \|h\|_{C^5[-K,K]}
$$
by Cauchy--Schwarz and Parseval, where the last inequality is obtained by 
applying the chain rule to
$\tilde h(\theta)=h(K\cos\theta)$. Since
this estimate holds for all $h\in\mathcal{P}$, the definition
of $\nu_1$ extends uniquely by continuity to any $h\in 
C^\infty(\mathbb{R})$. In particular, $\nu_1$ extends to a compactly 
supported distribution.

Applying the identical argument to the first inequality of
Corollary \ref{cor:master} yields
$$
	\bigg| 
	\mathbf{E}\big[ \ntr 
	h(P(\boldsymbol{U}^N,\boldsymbol{U}^{N*}))|_{1^\perp}\big]
	- \nu_0(h) - \frac{\nu_1(h)}{N} \bigg|
	\le \frac{C}{N^2} \|h\|_{C^9[-K,K]}
$$
for all $h\in C^\infty(\mathbb{R})$. In particular,
\eqref{eq:expansion} remains valid for any $h\in C^\infty(\mathbb{R})$.
\end{proof}


\subsection{The infinitesimal distribution}

It remains to prove Lemma \ref{lem:supp}. As was explained in section 
\ref{sec:infdist}, this result follows immediately from the following 
lemma, whose proof uses a spectral graph theory argument due to 
\cite[Lemma 2.4]{Fri03}.

\begin{lem}
\label{lem:frieduke}
Assume that $P$ has positive coefficients. Then
$$
	\limsup_{p\to\infty} |\nu_1(x^p)|^{\frac{1}{p}}
	\le
	\|P(\boldsymbol{u},\boldsymbol{u}^*)\|.
$$
\end{lem}

To set up the proof, let us fix a noncommutative polynomial $P$ of degree 
$d$ with positive coefficients.
By homogeneity, we may assume without loss of generality that the
coefficients sum to one. It will be convenient to express
$$
	P(\boldsymbol{u},\boldsymbol{u}^*) =
	\sum_{i_1,\ldots,i_d=0}^{2r}
	a_{i_1,\ldots,i_d}\,u_{i_1}\cdots u_{i_d} =
	\mathbf{E}[u_{I_1}\cdots u_{I_d}],
$$
where $\boldsymbol{I}=(I_1,\ldots,I_d)$ are random variables such that
$\mathbf{P}[\boldsymbol{I}=(i_1,\ldots,i_d)]=a_{i_1,\ldots,i_d}$.
Now let
$(I_{sd+1},\ldots,I_{(s+1)d})$ be independent copies of 
$\boldsymbol{I}$
for $s\in\mathbb{N}$, so that we have 
$P(\boldsymbol{u},\boldsymbol{u}^*)^p
= \mathbf{E}[u_{I_1}\cdots u_{I_{pd}}]$. Then we can apply
Corollary \ref{cor:divisor} to compute
$$
	\nu_1(x^p) =
	-\tau\big(P(\boldsymbol{u},\boldsymbol{u}^*)^p\big) +
	\sum_{k=2}^{pd} (\omega(k)-1)
	\sum_{v\in\mathbf{F}_r^{\rm np}}
	\mathbf{E}\big[1_{g_{I_1}\cdots g_{I_{pd}}=v^k}\big],
$$
where $\mathbf{F}_r^{\rm np}$ denotes the set of non-powers in
$\mathbf{F}_r$.\footnote{Here we used that
$\mu_1(\boldsymbol{w})=-1$ if $g_{w_1}\cdots g_{w_q}=e$, since
$\ntr \id|_{1^\perp} = \frac{N-1}{N}$.\label{foot:muid}}

\begin{proof}[Proof of Lemma \ref{lem:frieduke}]
We would like to argue that if a word $g_{i_1}\cdots g_{i_{pd}}=v^k$,
it must be a 
concatenation of $k$ words that reduce to $v$. This is only true, however,
if $v$ is cyclically reduced: otherwise the last letters of $v$ may
cancel the first letters of the
next repetition of $v$, and the cancelled letters need not appear
in our word. The correct version of this statement is that there exist
$g,w\in\mathbf{F}_d$ 
with $v=gwg^{-1}$ (where $w$ is the cyclic reduction of $v$) so that
every word that reduces to $v^k$ is a concatenation of
words that reduce to $g,w,w,w^{k-2},g^{-1}$. Thus
\begin{multline*}
	\sum_{v\in\mathbf{F}_r^{\rm np}}
	1_{g_{i_1}\cdots g_{i_{pd}}=v^k} \le
	\sum_{g,w\in\mathbf{F}_r}
	\sum_{0\le t_1\le \cdots\le t_4\le pd}
	1_{g_{i_1}\cdots g_{i_{t_1}} = g}\,
	1_{g_{i_{t_1+1}}\cdots g_{i_{t_2}} = w} \times\mbox{} \\
	1_{g_{i_{t_2+1}}\cdots g_{i_{t_3}} = w}\,
	1_{g_{i_{t_3+1}}\cdots g_{i_{t_4}} = w^{k-2}}\,
	1_{g_{i_{t_4+1}}\cdots g_{i_{pd}} = g^{-1}}.
\end{multline*}
To relate this bound to the spectral properties of 
$P(\boldsymbol{u},\boldsymbol{u}^*)$, we make the simple observation
that the indicators above can be expressed as matrix elements
$$
	1_{g_{w_1}\cdots g_{w_q}=v} = \langle \delta_v,
	u_{w_1}\cdots u_{w_q}\,\delta_e\rangle.
$$
If we substitute the formula in the above inequality, and then
take the expectation with respect to each independent block of variables
$(I_{sd+1},\ldots,I_{(s+1)d})$ that lies entirely inside one of the
matrix elements, we obtain
\begin{multline*}
	\sum_{v\in\mathbf{F}_r^{\rm np}}
	\mathbf{E}\big[1_{g_{I_1}\cdots g_{I_{pd}}=v^k}\big]
	\le
	\sum_{g,w\in\mathbf{F}_r}
	\sum_{0\le t_1\le \cdots\le t_4\le pd}
	\mathbf{E}\big[
	\langle \delta_g,X_{1,\boldsymbol{t}}\,\delta_e\rangle\,
	\langle \delta_w,X_{2,\boldsymbol{t}}\,\delta_e\rangle 
	\times\mbox{} \\
	\langle\delta_w,X_{3,\boldsymbol{t}}\,\delta_e\rangle\,
	\langle\delta_{w^{k-2}},X_{4,\boldsymbol{t}}\,\delta_e\rangle\,
	\langle\delta_{g^{-1}},X_{5,\boldsymbol{t}}\,\delta_e\rangle
	\big]
\end{multline*}
with
$$
	X_{j,\boldsymbol{t}} =
	u_{I_{t_{j-1}+1}}\cdots u_{I_{a_j}}
	P(\boldsymbol{u},\boldsymbol{u}^*)^{m_j}
	\,u_{I_{b_j+1}}\cdots u_{I_{t_j}},
$$
where $a_j=\min\{sd:s\in\mathbb{Z}_+,~t_{j-1}\le sd\}\wedge t_j$,
$b_j=\max\{sd:s\in\mathbb{Z}_+,~sd\le t_j\}\vee a_j$, $m_jd=b_j-a_j$,
and we write $t_0=0$ and $t_5=pd$ for simplicity. 

The crux of the proof is now to note that as
$$
	\sum_{v\in\mathbf{F}_r} |\langle \delta_v,X_{j,\boldsymbol{t}}\,
	\delta_e\rangle|^2 =
	\|X_{j,\boldsymbol{t}}\,
	\delta_e\|^2 \le \|P(\boldsymbol{u},\boldsymbol{u}^*)\|^{2m_j},
$$
it follows readily using Cauchy--Schwarz that
\begin{align*}
	\sum_{v\in\mathbf{F}_r^{\rm np}}
	\mathbf{E}\big[1_{g_{I_1}\cdots g_{I_{pd}}=v^k}\big]
	&\le
	\sum_{0\le t_1\le \cdots\le t_4\le pd}
	\|P(\boldsymbol{u},\boldsymbol{u}^*)\|^{m_1+\cdots+m_5}
	\\ &\le
	(pd+1)^4 \|P(\boldsymbol{u},\boldsymbol{u}^*)\|^{p+O(1)},
\end{align*}
since each $X_{j,\boldsymbol{t}}$ contains at most $2d=O(1)$ variables
other than $P(\boldsymbol{u},\boldsymbol{u}^*)^{m_j}$.
As $\sum_{k=2}^{pd}(\omega(k)-1) \le (pd)^2$ and
$|\tau(P(\boldsymbol{u},\boldsymbol{u}^*)^p)|\le
\|P(\boldsymbol{u},\boldsymbol{u}^*)\|^p$, the conclusion follows
directly from the expression for $\nu_1(x^p)$ stated before the proof.
\end{proof}

\begin{rem}
\label{rem:mdlspos}
The proof of Lemma \ref{lem:frieduke} relies on positivization: since all 
the terms in the proof are positive, we are able to obtain upper bounds by 
overcounting as in the first equation display of the proof. While this 
argument only applies in first instance to polynomials with positive 
coefficients, strong convergence for arbitrary polynomials then follows 
\emph{a posteriori} by Lemma \ref{lem:pos}.

It is also possible, however, to apply a variant of the positivization 
trick directly to $\nu_1$. This argument \cite[\S 6.2]{MdlS24} shows that 
the validity of Lemma \ref{lem:frieduke} for polynomials with positive 
coefficients already implies its validity for all self-adjoint polynomials 
(even with matrix coefficients), so that the polynomial method can be 
applied directly to general polynomials. The advantage of this approach is 
that it yields much stronger quantitative bounds than can be achieved by 
applying Lemma~\ref{lem:pos}. Since we have not emphasized the 
quantitative features of the polynomial method in our presentation, we do 
not develop this approach further here.
\end{rem}


\subsection{Discussion: on the role of cancellations}
\label{sec:discpoly}

When encountered for the first time, the simplicity of proofs by the 
polynomial method may have the appearance of a magic trick. An explanation 
for the success of the method is that it uncovers a genuinely new 
phenomenon that is not captured by classical methods of random matrix 
theory. Now that we have provided a complete proof of Theorem \ref{thm:bc} 
by the polynomial method, we aim to revisit the proof to highlight 
where this phenomenon arises. For simplicity, we place the following 
discussion in the context of random matrices $X^N$ with 
limiting operator $X_{\rm F}$; the reader may keep in mind 
$$
	X^N = P(\boldsymbol{U}^N,\boldsymbol{U}^{N*})|_{1^\perp},
	\qquad
	X_{\rm F} = P(\boldsymbol{u},\boldsymbol{u}^*)
$$
in the context of Theorem \ref{thm:bc} and its proof.

\subsubsection{The moment method}
\label{sec:momentmethod}

It is instructive to first recall the classical moment method that is 
traditionally used in random matrix theory. Let us take for granted
that $X^N$ converges \emph{weakly} to $X_{\rm F}$, so that
\begin{equation}
\label{eq:momentmethod}
	\mathbf{E}[\ntr {(X^N)^{2p}}]^{\frac{1}{2p}}
	= (1+o(1)) \tau(X_{\rm F}^{2p})^{\frac{1}{2p}} \le
	(1+o(1)) \|X_{\rm F}\|
\end{equation}
as $N\to\infty$ with $p$ fixed. The premise of the moment method is that 
\emph{if} it could be shown that this convergence remains valid when $p$ 
is allowed to grow with $N$ at rate $p\gg \log N$, then a strong 
convergence upper bound would follow: indeed, since
$\|X^N\|^{2p} \le \tr[(X^N)^{2p}] = N\,\ntr[(X^N)^{2p}]$, we could then
estimate 
$$
	\mathbf{E}\|X^N\| \le
	N^{\frac{1}{2p}}
	\mathbf{E}[\ntr {(X^N)^{2p}}]^{\frac{1}{2p}} \le
	(1+o(1))\|X_{\rm F}\|,
$$
where we used that $N^{\frac{1}{2p}}=1+o(1)$ for $p\gg\log N$.

There are two difficulties in implementing the above method. First, 
establishing \eqref{eq:momentmethod} for 
$p\gg\log N$ can be technically challenging and often requires delicate
combinatorial estimates. When $p$ is fixed, we can write an expansion
$$
	\mathbf{E}[\ntr {(X^N)^{2p}}] =
	\alpha_0(p) + \frac{\alpha_1(p)}{N} +
	\frac{\alpha_2(p)}{N^2} + \cdots
$$
(this is immediate, for example, from \eqref{lem:polyenc}) and 
establishing \eqref{eq:momentmethod} requires us to understand only the 
lowest-order term $\alpha_0(p)$. In contrast, when $p\gg\log N$ the 
coefficients $\alpha_k(p)$ themselves grow faster than polynomially in 
$N$, so that it is necessary to understand the terms in the expansion to 
all orders.

In the setting of Theorem \ref{thm:bc}, however, there is a more serious 
problem: \eqref{eq:momentmethod} is not just difficult to prove, but 
actually fails altogether.

\begin{example}
\label{ex:tangles}
Consider the permutation model of $2r$-regular random graphs as in Theorem
\ref{thm:friedman}, so that $X^N=A^N|_{1^\perp}$ where $A^N$
is the adjacency matrix. We claim that $\|X^N\|=2r$ with probability
at least $N^{-r}$. As $\|X_{\rm F}\|=2\sqrt{2r-1}$, this implies
$$
	\mathbf{E}[\tr {(X^N)^{2p}}] \ge
	N^{-r}(2r)^{2p} \ge
	N^{-r}
	\bigg(\frac{4}{3}\bigg)^p \|X_{\rm F}\|^{2p},
$$
contradicting the validity of \eqref{eq:momentmethod} for $p\gg\log N$.

To prove the claim, note that any given point of $[N]$ is simultenously a 
fixed point of the random permutations $U_1^N,\ldots,U_r^N$ with 
probability $N^{-r}$. Thus with probability at least $N^{-r}$, random 
graph has a vertex with $2r$ self-loops which is disconnected from the 
rest of the graph, so that $A^N$ has eigenvalue $2r$ with multiplicity at 
least two. The latter cleatly implies that $\|X^N\|=2r$.
\end{example}

Example \ref{ex:tangles} shows that the appearance of outliers in the 
spectrum with polynomially small probability $\sim N^{-c}$ presents a 
fundamental obstruction to the moment method. In random graph models, this 
situation arises due to the appearance of ``bad'' subgraphs, called 
\emph{tangles}. Previous proofs \cite{Fri08,Bor20,BC19} of optimal 
spectral gaps in this setting must overcome these difficulties by 
conditioning on the absence of tangles, which significantly complicates 
the analysis and has made it difficult to adapt these methods to more 
challenging models.\footnote{A notable exception being the work of 
Anantharaman and Monk on random surfaces \cite{AM25i,AM25ii}.}

\subsubsection{A new phenomenon}

The polynomial method is essentially based on the same input as the moment 
method: we consider the spectral statistics
$$
	\mathbf{E}[\ntr h(X^N)] =
	\text{linear combination of }\mathbf{E}[\ntr {(X^N)^p}] 
	\text{ for }p\le q,
$$
where $h$ is any real polynomial of degree $q$, and aim to compare 
these with the spectral statistics of $X_{\rm F}$. Since we have shown in 
Example \ref{ex:tangles} that each moment can be larger than its limiting 
value by a factor exponential in the degree, that is, $\mathbf{E}[\ntr 
{(X^N)^{2p}}]\ge e^{Cp}\tau((X_{\rm F})^{2p})$ for $p\gg\log N$, it seems 
inevitable that $\mathbf{E}[\ntr h(X^N)]$ must be poorly approximated by 
$\tau(h(X_{\rm F}))$ for high degree polynomials $h$. The surprising 
feature of the polynomial method is that it defies this expectation: for 
example, a trivial modification of the proof of Corollary \ref{cor:master} 
yields the bound
\begin{equation}
\label{eq:polymeth}
	\big| \mathbf{E}[\ntr h(X^N)] -
	\tau(h(X_{\rm F})) \big|
	\le \frac{Cq^4}{N} \|h\|_{L^\infty[-K,K]}
\end{equation}
which depends only polynomially on the degree $q$.

There is of course no contradiction between these observations: if we 
choose $h(x)=x^p$ in \eqref{eq:polymeth}, then $\|h\|_{L^\infty[-K,K]}= 
K^p\ge e^{Cp}\|X_{\rm F}\|^p$ and we recover the exponential dependence on 
degree that was observed in Example \ref{ex:tangles}. On the other hand, 
\eqref{eq:polymeth} shows that the dependence on the degree becomes 
polynomial when $h$ is uniformly bounded on the interval 
$[-K,K]$. Thus the polynomial method reveals an unexpected cancellation 
phenomenon that happens when the moments are combined to form bounded test 
functions $h$.

The idea that classical tools from the analytic theory of polynomials, 
such as the Markov inequality, make it possible to capture such 
cancellations lies at the heart of the polynomial method. These 
cancellations would be very difficult to realize by a direct combinatorial 
analysis of the moments. The reason that this phenomenon greatly 
simplifies proofs of strong convergence is twofold. First, it only 
requires us to understand the $\frac{1}{N}$-expansion of the moments to 
first order, rather than to every order as would be required by the moment 
method. Second, this eliminates the need to deal with tangles, since 
tangles do not appear in the first-order term in the expansion. (The 
tangles are however visible in the higher order terms, which gives rise to 
the large deviations behavior in Figure \ref{fig:staircase}.)

\begin{rem} 
We have contrasted the polynomial method with the moment method since
both rely only on the ability to compute moments $\mathbf{E}[\ntr {(X^N)^p}]$.
Beside the moment method, another classical method of random 
matrix theory is based on resolvent statistics such as
$\ntr {(z-X^N)^{-1}}$.
This approach was used by Haagerup--Thorbj{\o}rnsen \cite{HT05}
and Schultz \cite{Sch05} to establish strong convergence for Gaussian 
ensembles, where strong analytic tools are available.
It is unclear, however, how such quantities can be 
computed or analyzed in the context of discrete models
as in Theorem \ref{thm:bc}. Nonetheless, let us note that the 
recent works \cite{HY24,HMY24,HMY25} 
have successfully used such an approach in the setting of random regular 
graphs.
\end{rem}


\section{Intrinsic freeness}
\label{sec:mconc}

The aim of this section is to explain the origin of the intrinsic freeness 
phenomenon that was introduced in section \ref{sec:intriintro}. Since 
Theorem \ref{thm:intrfree} requires a number of technical ingredients 
whose details do not in themselves shed significant light on the 
underlying phenomenon, we defer to \cite{BBV23,BCSV23} for a complete 
proof. Instead, we aim to give an informal discussion of the key ideas 
behind the proof: in particular, we aim to explain the underlying 
mechanism.

Before we can do so, however, we must first describe the limiting object 
$X_{\rm free}$ and explain why it is useful in practice, which we will do 
in section \ref{sec:semicircle}. We subsequently sketch some key ideas 
behind the proof of Theorem \ref{thm:intrfree} in section 
\ref{sec:pfintr}.


\subsection{The free model}
\label{sec:semicircle}

To work with Gaussian random matrices, we must 
recall how to compute moments of independent standard Gaussians 
$\boldsymbol{g}=(g_1,\ldots,g_r)$: given any $k_1,\ldots,k_n\in [r]$,
the Wick formula \cite[Theorem 22.3]{NS06} states that
$$
	\mathbf{E}[g_{k_1}\cdots g_{k_n}] =
	\sum_{\pi\in\mathrm{P}_2[n]} \prod_{\{i,j\}\in\pi}
	1_{k_i=k_j},
$$
where $\mathrm{P}_2[n]$ denotes the set of pairings of $[n]$
(that is, partitions into blocks of size two). This 
classical result is easily proved by induction on $n$ using integration by 
parts. A convenient way to rewrite the Wick formula is to introduce for 
every $\pi\in\mathrm{P}_2[n]$ and $j\in[n]$ random variables 
$\boldsymbol{g}^{j|\pi}=(g_1^{j|\pi},\ldots,g_r^{j|\pi})$ with the same 
law as $\boldsymbol{g}$ so 
that $\boldsymbol{g}^{j|\pi}=\boldsymbol{g}^{l|\pi}$ for $\{j,l\}\in\pi$, 
and $\boldsymbol{g}^{j|\pi},\boldsymbol{g}^{l|\pi}$ 
are independent otherwise. Then
$$
	\mathbf{E}[g_{k_1}\cdots g_{k_n}] = \sum_{\pi\in\mathrm{P}_2[n]}
	\mathbf{E}\big[g_{k_1}^{1|\pi}\cdots g_{k_n}^{n|\pi}\big],
$$
as the expectation in the sum factors as
$\prod_{\{i,j\}\in\pi}E[g_{k_i}g_{k_j}]$.

What happens if we replace the scalar Gaussians
$\boldsymbol{g}=(g_1,\ldots,g_r)$ by independent GUE matrices 
$\boldsymbol{G}^N=(G_1^N,\ldots,G_r^N)$?
To explain this, we need the following notion: a pairing 
$\pi$ has a \emph{crossing} if there exist 
pairs $\{i,j\},\{l,m\}\in\pi$ so that $i<l<j<m$. If we represent $\pi$ by 
drawing each element of $[n]$ as a vertex on a line, and drawing a 
semicircular arc between the vertices in each pair $\{i,j\}\in\pi$, the 
pairing has a crossing precisely when two of the arcs cross; see Figure 
\ref{fig:crossing}. 
