    \[
        Y_t=\int_t^T D(t,s)\,C_s\,\emph{d}s-\int_t^T Z_{t,s}\,\emph{d}W_s,
    \]
    whose control field $Z_{t,s}$ carries both time indices and captures the memory effect of the moving discount kernel.
\end{example}
