\end{figure}
\fi
\subsubsection{Example 3: An FSDE-BSVIE system coupled in \textit{Y} and \textit{Z}}
For $d\in\N$, $a,x_0\in\R^d$, $b,c,k\in\R$, and $\sigma\in\R^{d\times d}$. We consider the following coupled FSDE-BSVIE system
\begin{equation}\label{eq:BSVIE_fully_coupled}
\begin{dcases}
X_t \;=\; x_0+\int_0^t \big(a+bZ_{s,s}\big)\,\d s \;+\;\int_0^t\big(c+Y_s\big) \sigma W_t,\quad\overline{X}_t=\frac{1}{d}\sum_{i=0}^dX_t^i,
\\[4pt]
Y_t \;=\;
t\sin(k\widebar{X}_T) \;+\;\displaystyle 
\int_{t}^{T}\Big(\frac{tk^2}{2d^2}\sin(k\overline{X}_s)(c+Y_s)^2\|\mathbf{1}^\top\sigma\|^2 - \cos(k\overline{X}_s)(t\mathbf{1}^\top a + sb\mathbf{1}^\top Z_{t,s})\big)\Big)\d s
\\ \;-\;
\int_{t}^{T} Z_{t,s}^\top\,\d W_s,
\quad
(t,s)\in\Delta[0,T]^2.
\end{dcases}
\end{equation}

A direct calculation shows that the unique solution $\{(Y_t,Z_{t,s})\}_{(t,s)\in\Delta[0,T]^2}$ is given by the closed-form expressions
\begin{equation}\label{eq:ref_solution_BSVIE_4}
Y_t \;=\; t\sin(k\widebar{X}_t)
\quad\text{and}\quad
Z_{t,s} 
\;=\;
t\cos(k\overline{X}_s)(c+s\sin(k\overline{X}_s)))\mathbf{1}^\top \sigma,
\quad
(t,s)\in\Delta[0,T]^2.
\end{equation}
Let $d=k=5$, $T=1$, $x_0=1$, $a=(0.15,0.075,0.0,-0.075,-0.15)^\top$, $\sigma=\text{diag}(0.4,0.5,0.6,0.7,0.9)$, $c=1.001$ ($c>1$ to guarantee enough ellipticity), and $N=40$. 

Figure~\ref{fig:XY_fully_coupled}-\ref{fig:Z_fully_coupled} shows our approximate $X$-,$Y$- and $Z$-processes, compared with the semi-analytic (we have to approximate the FSDE with an Euler--Maruyama scheme) reference solutions.  In particular, the reference solution for the FSDE is obtained by substituting \(Y_t = t \sin(k\widebar{X}_t)\), and $Z_{t,t}=\frac{tk}{d}\cos(k\overline{X}_t)(c+t\sin(k\overline{X}_t)))\mathbf{1}^\top \sigma$ into the drift coefficient and approximating the decoupled FSDE via the Euler--Maruyama scheme. 
