\section{Proof of Lemma 4.1}\label{app:proof_41}
In this appendix we provide the full proof of Lemma~\ref{lemma:main_res}, restated here for convenience.
\begin{lemma}\label{lemma:main_res_2}
  Assume that $h$ is small enough so that  $(2K_1 + \tfrac{1}{2})\,h<1$. 
For $j \in \{1,2\}$, suppose 
  $\bigl\{\widehat{Y}_n^{k,\pi,j}, \widehat{Z}_n^{k,\pi,j}\bigr\}_{(k,n)\in \Delta^\pi[0,T]^2}$ 
  are two square integrable solutions to \eqref{eq:BSDE_family_disc_generic}. 
  Define the differences
  \begin{equation*}
    \delta Y_n^k \;=\; \widehat{Y}_n^{k,\pi,1} \;-\; \widehat{Y}_n^{k,\pi,2},
    \qquad
    \delta Z_n^k \;=\; \widehat{Z}_n^{k,\pi,1} \;-\; \widehat{Z}_n^{k,\pi,2}.
  \end{equation*}
  Then there exist constants $C_Y$ and $C_Z$, depending only on $T$ and $K_1$, such that 
  for every $(k,n)\in \Delta^\pi[0,T]^2$, the following estimates hold:
  \begin{align*}
    \E\bigl|\delta Y_n^k\bigr|^2 
    &\;\;\le\;\; 
      C_Y \Bigl(\,
        \E\bigl|\delta Y_N^k\bigr|^2 
        \;+\; 
        \sum_{\ell=n}^{N-1}\E\bigl|\delta Y_N^\ell\bigr|^2\,h
      \Bigr),
    \\[6pt]
    \E\bigl|\delta Z_n^k\bigr|^2 \, h
    &\;\;\le\;\; 
      C_Z \Bigl(\,
        \E\bigl|\delta Y_N^k\bigr|^2 
        \;+\; 
        \sum_{\ell=n}^{N-1}\E\bigl|\delta Y_N^\ell\bigr|^2\,h
      \Bigr).
  \end{align*}
    \begin{proof}
Let $\delta f_n^k=f(t_k,t_n,X_n^\pi,Y_n^{n,\pi,1},Z_n^{k,\pi,1}) -  f(t_k,t_n,X_n^\pi,Y_n^{n,\pi,2},Z_n^{k,\pi,2})$, then
\begin{align*}
    \delta Y_{n+1}^k=\E\big[\delta Y_{n+1}^k\,|\,\F_{t_n}\big] + \delta f_n^kh,\quad \delta Z_n^k=\frac{1}{h}\E\big[\delta Y_{n+1}^k\Delta W_n\,|\,\F_{t_n}\big].
\end{align*}
Then, by the martingale representation theorem, there exists an adapted, square integrable process $(\delta Z_t^k)_{t\in[t_n,{n+1}]}$, such that
\begin{align*}
\delta Y_{n+1}^k= \E\big[\delta Y_{n+1}^k\,|\,\F_{t_n}\big] + \int_{t_n}^{t_{n+1}}\delta Z_n^k dW_t=\delta Y_n^k - \delta f_n^kh + \int_{t_n}^{t_{n+1}}\delta Z_n^k dW_t.
\end{align*}
 Since $\delta f_n^k$ and $\delta Y_n^k$ are $\F_{t_n}$-measurable, it holds that $\E\big[\delta Y_n^k\int_{t_n}^{t_{n+1}}\delta Z_n^k dW_t\big]=\E\big[\delta f_n^k\int_{t_n}^{t_{n+1}}\delta Z_n^k dW_t\big]=0$ and by Itô-Isometry, we have    
\begin{align*}
    \E|\delta Y_{n+1}^k|^2&\geq \E|\delta Y_n^k - \delta f_n^kh|^2 + \int_{t_n}^{t_{n+1}}\E|\delta Z_t^k|^2\d s.
\end{align*}
The first term, $\E|\delta Y_n^k - \delta f_n^kh|^2$ is treated in two separate cases.


\vspace{0.25cm}\noindent \textbf{Case I} ($n>k$):\newline
For the first term on the right-hand side, we use Lipschitz continuity of $f$, and then apply the root-mean-square and geometric-mean inequalities with $\lambda>0$ to obtain
\begin{align*}
    \E|\delta Y_n^k - \delta f_n^k|^2\geq&  \E|\delta Y_n^k|^2 -2h\E\big[\delta Y_n^k\delta f_n^k\big]\geq \E|\delta Y_n^k|^2 - \lambda\E|\delta Y_n^k|^2h -K_1\lambda^{-1}\big(\E|\delta Y_n^n|^2 + \E|\delta Z_n^k|^2)h.\\
\end{align*}
We observe that 
$\E\bigl[\int_{t_n}^{t_{n+1}}\delta Z_t^k\mathrm{d}t\,\big|\,\F_{t_n}\bigr] = h\delta Z_n^k$, see \textit{e.g.,} \cite[Lemma 1]{han2020convergence},
 which, by the Cauchy--Schwartz inequality, implies that 
$\int_{t_n}^{t_{n+1}}\E|\delta Z_t^k|^2\mathrm{d}t \geq \E|\delta Z_n^k|^2h.$
Collecting terms then yields 
\begin{align}\label{ineq:splt_Y_Z}
    \E|\delta Y_{n+1}^k|^2\geq \big(1-\lambda h\big)\E|\delta Y_n^k|^2 - \lambda^{-1}K_1\E|\delta Y_n^n|^2h + (1- K_1\lambda^{-1})\E|\delta Z_n^k|^2h.
\end{align}
setting $\lambda=2K_1$ (assuming $K_1>0$) and rearranging yields
\begin{align*}
    \big(1-2K_1h\big)\E|\delta Y_n^k|^2+ \frac{1}{2}\E|\delta Z_n^k|^2h\leq 2\E|\delta Y_{n+1}^k|^2 + \E|\delta Y_n^n|^2h.
\end{align*}
Then, for sufficiently small $h$, such that $2K_1 h<1$, we have
\begin{align*}
    \E|\delta Y_n^k|^2\leq \big(1-2K_1 h\big)^{-1}\Big(\E|\delta Y_{n+1}^k|^2 + \frac{1}{2}\E|\delta Y_n^n|^2h\Big).
\end{align*}
Setting $A_1=(1-2K_1 h)^{-1}$ and iteratively applying the bound for $\E|\delta Y_n^k|^2$, yield
\begin{align}\label{ineq:deltaY_nk}
       \E|\delta Y_n^k|^2\leq A_1^{N-n}\E|\delta Y_N^k|^2 + \frac{1}{2}\sum_{\ell=n}^{N-1}A_1^{\ell+1-n}\E|\delta Y_\ell^\ell|^2h. 
\end{align}
\vspace{0.25cm}\newline \textbf{Case II} ($n=k$):\newline
We, again use the root-mean-square and geometric-mean inequalities with $\lambda=2K_1$ and Lipschitz continuity of $f$ to obtain
\begin{align*}
    \E|\delta Y_{n+1}^n|^2\geq&  \E|\delta Y_n^n|^2 -2h\E\big[\delta Y_n^n\delta f_n^n\big] + \E|\delta Z_n^n|^2h\\
    \geq&\Big(1-\big(2K_1+\frac{1}{2}\big)h\Big)\E|\delta Y_n^n|^2 + \frac{1}{2}\E|\delta Z_n^n|^2h.
\end{align*}
The above implies that we have the following bounds
\begin{align}\label{ineq:delta_Y_nn_Z_nn}
    \E|\delta Y_n^n|^2\leq \Big(1-\big(2K_1+\frac{1}{2}\big)h\Big)^{-1}\E|\delta Y_{n+1}^n|^2,\quad     \E|\delta Z_n^n|^2h\leq 2\E|\delta Y_{n+1}^n|^2.
\end{align}

Setting $A_2=\Big(1-\big(2K_1+\frac{1}{2}\big)h\Big)^{-1}A_1$ and combining~\eqref{ineq:deltaY_nk} and \eqref{ineq:delta_Y_nn_Z_nn} iteratively, we obtain 
\begin{align*}
    \E|\delta Y_n^k|^2\leq&A_1^{N-n}\E|\delta Y_N^k|^2 + A_2\sum_{\ell=n}^{N-1}A_1^{N-\ell-1}(1+A_2h)^{n-\ell}\E|\delta Y_N^\ell|^2h,\\
    \E|\delta Y_n^k|^2\leq&A_1^N\E|\delta Y_N^k|^2 + A_1^NA_2(1+A_2h)^N\sum_{\ell=n}^{N-1}\E|\delta Y_N^\ell|^2h,
\end{align*}
where in the last step we use the fact that $A_1,A_2>1$ by construction.
%\begin{align*}
%        \E|\delta Y_n^k|^2\leq&A_1^N\E|\delta Y_N^k|^2 + A_1^NA_2(1+A_2h)^N\sum_{\ell=n}^{N-1}\E|\delta Y_N^\ell|^2h
%\end{align*}
To bound $\E|\delta Z_n^k|^2$ we note that, \eqref{ineq:splt_Y_Z} yields
\begin{align*}
\E|\delta Z_n^k|^2h\leq& 2\E|\delta Y_{n+1}^k|^2 +\E|\delta Y_n^n|^2h\\
\leq& A_1^N\E|\delta Y_N^k|^2 + (1+h)A_1^NA_2^N\sum_{\ell=n}^{N-1}\E|\delta Y_N^\ell|^2h.
\end{align*}

The remaining task is to analyze $A_1^N$, $A_2^N$, and $(1 + A_2 h)^N$. 
Noting that $h = \tfrac{T}{N}$, we begin with the first term
\begin{align*}
    A_1^N&=\Big(\frac{1}{1-2K_1h}\Big)^N=\Big(1+\frac{2K_1T}{N-2K_1T}\Big)^N.
\end{align*}
Hence, for $N>2K_1 T$, $A_1^N$ is a decreasing sequence in $N$, converging to $\mathrm{e}^{2K_1 T}$. 
Similarly, for $A_2^N$, we have that for $N>(2K_1+\tfrac{1}{2})T$
\begin{align*}
    A_2^N 
    &= \Bigl(1 + \frac{(2K_1 + \tfrac{1}{2})T}{\,N - (2K_1 + \tfrac{1}{2})T\,}\Bigr)^N 
       \,\Bigl(1 + \frac{2K_1 T}{\,N - 2K_1 T\,}\Bigr)^N
\end{align*}
is a decreasing sequence in $N$, converging to $\mathrm{e}^{(3K_1+\tfrac{1}{2})T}$. 
For the last term, $(1 + A_2 h)^N = \bigl(1 + \tfrac{A_2 T}{\,N\,}\bigr)^N \le \mathrm{e}^{A_2 T}$, 
which is also decreasing in $N$. 
Finally, $A_1^N$, $A_2^N$, and $(1 + A_2 h)^N$ are bounded and decreasing sequences in $N$, 
and hence, there exist bounded constants $C_Y$ and $C_Z$ such that
\begin{align*}
    \E|\delta Y_n^k|^2 
    &\leq C_Y \Bigl(\E|\delta Y_N^k|^2 
            \;+\; \sum_{\ell=n}^{N-1}\E|\delta Y_N^\ell|^2\,h\Bigr),\\
    \E|\delta Z_n^k|^2\,h 
    &\leq C_Z \Bigl(\E|\delta Y_N^k|^2 
            \;+\; \sum_{\ell=n}^{N-1}\E|\delta Y_N^\ell|^2\,h\Bigr).
\end{align*}
    \end{proof}
\end{lemma}
