\begin{theo}
\label{Theorem1}
The Felsenthal Owen power index is the only CFI that satisfies NN, QG, and PELS. 
\end{theo}

\begin{proof}
\quad\\
\noindent\textbf{Existence.} 
It is immediate from its definition that the Felsenthal Owen power index satisfies NN.\medskip

To show that it's a CFI power index, let us consider $(N,W,N^{0})$ and its quotient game $(U,\overline{W})$. 

 Since $N^{0}$ is the trivial union, it follows that $|\overline{W}^{ls}|=|W^{ls}|$. Let us fix $i 
 \in N$ and $k\in U$ such that $i\in P_k$. It means that $P_k=\{i\}$ and there is a bijection between $\overline{W}^{ls}_{k}$ and $W^{ls}_{i}$, such that 
 assigns to each $R\in \overline{W}^{ls}_{k}$ the coalition $S=\{i\in P_k \mid k\in R\}\in W^{ls}_{i}$, which satisfies that $|S|=|R|$. Furthermore, given $R\in \overline{W}^{ls}$, the game $(P_k,W_{R,k})$ has just one player and the Felsenthal index is efficient so $\psi_{i}(P_k,W_{R,k})=1$. Then,
    $$
    \Psi_{i}(N,W,N^{0})=\frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\psi_{i}(P_k,W_{R,k})=\frac{1}{|W^{ls}|}\sum_{S \in W^{ls}_{i}}\frac{1}{|S|}=\psi_{i}(N,W).
    $$   

The QG property follows from the definition of $\Psi$ and the efficiency of the Felsenthal index. Indeed, for a fixed $P_k\in P$, it holds that,

\begin{align*}
    \sum_{i\in P_{k}}\Psi_{i}(N,W,P) & =\sum_{i\in P_{k}}\frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\psi_{i}(P_{k},W_{R,k})&\\
         & =\frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\sum_{i\in P_{k}}\psi_{i}(P_{k},W_{R,k})&\\
         & =\frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|} = \Psi_{k}(U,\overline{W},U^{0}).
    \end{align*}
Lastly, we show that $\Psi$ satisfies PELS. First, note that for a player $i\in P_{k}$, $\Psi_{i}(N,W,P)\neq 0 $ if and only if there exists a coalition $R\in \overline{W}^{ls}_{k}$ such that $E^{ls}_{R,k,i}(N,W,P)\neq \emptyset$, which is equivalent to $\psi_{i}(P_{k},W_{R,k})\neq 0$. Furthermore, by the CFI property:
\begin{equation*}
    \Psi_{i}(N,W,P)= \frac{1}{|\overline{W}^{ls}|}\frac{1}{|R|}\sum_{R\in \overline{W}^{ls}_{k}}\Psi_{i}(P_{k},W_{R,k},P_{k}^{0}), 
\end{equation*}
Hence,  
$\Psi_{i}(N,W,P) \neq 0$ if and only if $\Psi_{i}(P_{k},W_{R,k},P_{k}^{0}) \neq 0$ for some $R\in\overline{W}^{ls}_{k} $.\\
Now consider two players $i,j\in P_{k}$. If  $|P_{k}|=1$, the PELS condition holds trivially. Otherwise, suppose $i,j$ are distinct. If either $\Psi_{i}(N,W,P)$ or $ \Psi_{j}(N,W,P)$ is 0 in $(N,W,P)$, the condition is again satisfied since both sides of the equality are zero as just noted. Otherwise, in the non-trivial case:
\begin{equation*}
    \frac{\Psi_{i}(N,W,P)}{\sum_{R\in \overline{W}^{ls}_{k}}\Psi_{i}(P_{k},W_{R,k},P_{k}^{0})}= \frac{1}{|\overline{W}^{ls}|}\frac{1}{|R|}=\frac{\Psi_{j}(N,W,P)}{\sum_{R\in \overline{W}^{ls}_{k}}\Psi_{j}(P_{k},W_{R,k},P_{k}^{0})}.
\end{equation*}
Thus, the PELS property is satisfied by $\Psi$.


\noindent\textbf{Uniqueness.}
We demonstrate that the Felsenthal Owen index $\Psi$ is the only coalitional index satisfying the above properties. To this aim, let $F$ be a coalitional power index  satisfying those properties and consider $(N,W,P)\in SIU(N)$ with the corresponding quotient game $(U,\overline{W})$. \medskip

\noindent Since $F$ is a CFI that satisfies QG, for each union $k\in U$:
\begin{equation}
\label{eq:charac1_unic_1}
\sum\limits_{i\in P_{k}} F_{i}(N,W,P)=F_{k}(U,\overline{W},U^{0})
=\psi_{k}(U,\overline{W})=\frac{1}{|\overline{W}^{ls}|}\sum\limits_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}.
 \end{equation}

\noindent If $ \overline{W}^{ls}_{k}= \emptyset$, then equation~(\ref{eq:charac1_unic_1}) implies $\sum\limits_{i\in P_{k}} F_{i}(N,W,P)=0$ and, by NN it follows that $F_{i}(N,W,P)=0$ $\forall i \in P_{k}$.\medskip

\noindent Otherwise, given $R\in \overline{W}^{ls}_{k}$ and $i\in P_{k}$, CFI yields:
       \begin{equation}\label{eq:charac1_unic_2}
        F_{i}(P_{k},W_{R,k},P^{0}_{k})=\psi_i(P_{k},W_{R,k})=\frac{1}{|E^{ls}_{R,k}(N,W,P)|}\sum\limits_{S\in E^{ls}_{R,k,i}(N,W,P)}\frac{1}{|S|}.
       \end{equation} 

\noindent Now, players  in $P_{k}$ can be classified into two subsets:  $P_{k}=P_{k}^{1}\sqcup P_{k}^{2}$, where  $P_{k}^{1}$ consists of players $i\in P_{k}$ such that $E^{ls}_{R,k,i}(N,W,P)=\emptyset$ for all  $R \in \overline{W}^{ls}_{k}$ and $P_{k}^{2}=P_{k}\setminus P_{k}^{1}$. Note that $P_{k}^{2}\neq \emptyset$ as  $\overline{W}^{ls}_{k}\neq \emptyset$. This partition implies that every player  $i\in P_k$ belongs to exactly one of the two subsets:
\begin{enumerate}
\item $i\in P_{k}^{1}$. According to~(\ref{eq:charac1_unic_2}), $F_{i}(P_{k},W_{R,k},P_{k}^{0})=0$ for every  $R \in \overline{W}^{ls}_{k}$. Choosing any $j\in P_{k}^{2}$, the PELS property implies:
       $$0=F_{j}(N,W,P)\cdot 0=  F_{i}(N,W,P)\sum\limits_{R\in \overline{W}^{ls}_{k}}  F_{j}(P_{k},W_{R,k},P_{k}^{0}).
    $$
\noindent Since $j\in P_{k}^{2}$, by~(\ref{eq:charac1_unic_2}) there exists $\widetilde{R}\in \overline{W}^{ls}_{k}$ such that $F_{j}(P_{k},W_{\widetilde{R},k},P_{k}^{0})> 0$, leading to $ F_{i}(N,W,P)=0$.

\item $i\in P_{k}^{2}$. \begin{itemize}[label=\scalebox{0.75}{$\bullet$}]
    \item If $|P_{k}^2|=1$, then $P_{k}^{2}=\{i\}$ and:
$$
F_{i}(N,W,P)=\sum\limits_{j\in P_{k}}F_{j}(N,W,P)\overset{(\ref{eq:charac1_unic_1})}{=}\frac{1}{|\overline{W}^{ls}|}\sum\limits_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}.
$$
\item If  $|P_{k}^{2}|>1$, then for any player $j\in P_{k}^{2}$, the  PELS property implies that there exist a constant $\lambda_{k}$ such that:
\begin{equation}\label{eq:charac1_unic_3}
   F_{j}(N,W,P) = \lambda_{k}   \sum\limits_{R\in \overline{W}^{ls}_{k}}F_{j}(P_{k},W_{R,k},P_{k}^{0}).
\end{equation}
Subsequently:
\begin{align*}
      \frac{1}{|\overline{W}^{ls}|}\sum\limits_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}&\overset{(\ref{eq:charac1_unic_1})}{=}\sum\limits_{j\in P_{k}} F_{j}(N,W,P)=\sum\limits_{j\in P_{k}^{2}} F_{j}(N,W,P)&\\
      &\overset{(\ref{eq:charac1_unic_2}),(\ref{eq:charac1_unic_3})}{=} \lambda_{k}\sum\limits_{R\in \overline{W}^{ls}_{k}} \frac{1}{|R|}  \frac{1}{|E^{ls}_{R,k}(N,W,P)|}\sum\limits_{j\in P_{k}} \sum\limits_{S\in E^{ls}_{R,k,j}(N,W,P)}\frac{1}{|S|}&\\
      & =\lambda_{k}\hspace{1mm}|\overline{W}^{ls}_{k}|.
\end{align*}
Hence, $\lambda_{k}= \frac{1}{|\overline{W}^{ls}| \hspace{0.5mm}|R|}$, $R \in \overline{W}^{ls}$, and equation~(\ref{eq:charac1_unic_3}) implies that:
\begin{equation}
   F_{i}(N,W,P) = \frac{1}{|\overline{W}^{ls}|} \sum\limits_{R\in \overline{W}^{ls}_{k}} \frac{1}{|R|} F_{i}(P_{k},W_{R,k},P_{k}^{0}).
\end{equation}
Lastly, the index $ F_{i}(P_{k},W_{R,k},P_{k}^{0})$ can be substitute using equation~(\ref{eq:charac1_unic_2}).
\end{itemize}
\end{enumerate}
Thus, in all scenarios, the coalitional index $F$ coincides with the Felsenthal Owen index $\Psi$, proving it is the unique coalitional index satisfying the specified properties. 


\end{proof}



\subsection{Second characterization}
 Our second characterization builds directly upon the framework developed by Freixas and Samaniego in \cite{3_Felsenthal_Freixas_samaniego}. In their work, these authors demonstrate that the Felsenthal index is the only power index satisfying the next four properties:\medskip

\textbf{Efficiency (E).} A  power index $f$ satisfies E if for every $(N,W)\in SI(N)$, $\sum_{i\in N} f_{i}(N,W) =1$.\medskip

\textbf{Null player (NP). }
        A  power index $f$ satisfies NP if for every $(N,W) \in SI(N)$ and $i\in N$ such that is a null player in the game $(N,W)$, then $f_{i}(N,W)=0$.
\medskip

\textbf{Symmetry (S). }
        A  power index $f$ satisfies S if for every $(N,W) \in SI(N)$ and $i,j\in N$ such that they are symmetric players in the game $(N,W)$, then $f_{i}(N,W)=f_{j}(N,W)$.
\medskip

\textbf{Transfer for coalitions of least size (TCLS). }
        A power index $f$ satisfies TCLS if for any pair $(N,W)$ and $(N, V)\in SI(N)$ such that $W^{ls}\cap V^{ls} =\emptyset$,  then
    $$
    f (N,W \vee V)= \left\{ \begin{array}{lcc} f (N,W), & \textrm{if} &  c_{\hspace{0.4mm}W} <  c_{\hspace{0.4mm}V} \\ \\ f (N,V), & \textrm{if} & c_{\hspace{0.4mm}V} <  c_{\hspace{0.4mm}W}\\ \\ \frac{ p_{\hspace{0.4mm}W}}{ p_{\hspace{0.4mm}W}+ p_{\hspace{0.4mm}V}}f (N,W) + \frac{ p_{\hspace{0.4mm}V}}{ p_{\hspace{0.4mm}W}+ p_{\hspace{0.4mm}V}} f(N,V),&  & \textrm{otherwise.} \end{array} \right.
    $$
This last property TCLS is closely related to the ``Transfer axiom'' originally introduced in the Shapley-Shubik characterization by Dubey~\cite{74_caracterizacion_Shapley_shubik}, although it focuses exclusively on least size winning coalitions as emphasized  by Felsenthal. In the specific case where $W$ and $V$ have disjoint minimal winning coalitions $W^{ls}\cap V^{ls} =\emptyset$ and identical least sizes $c_{\hspace{0.4mm}W} =  c_{\hspace{0.4mm}V}$, the TCLS property states that power in the disjunction game $W \vee V$ is given by a weighted average of the powers in the individual games. The weights correspond to each game’s relative contribution to the combined set of minimal winning coalitions $W^{ls}\sqcup V^{ls}$.\\[3pt]

