\medskip
Next we list out several properties for coalitional power indexes. Many of them represent adaptations of the previously discussed properties (E, NP, S, and TCLS). As we will subsequently demonstrate, these adapted properties serve to uniquely characterize the Felsenthal Owen power index.\medskip

\textbf{Efficiency (E).} A coalitional power index $F$ satisfies E if for every $(N,W,P)\in SIU(N)$, $\sum_{i\in N} F_{i}(N,W,P) =1$.\medskip

\textbf{Null player (NP). }
        A coalitional power index $F$ satisfies NP if for every $(N,W,P) \in SIU(N)$ and $i\in N$ such that is a null player in the game $(N,W)$, then $F_{i}(N,W,P)=0$.

\medskip

\textbf{Symmetry among unions (S-AU).} A coalitional power index $F$ satisfies S-AU if for every $(N,W,P) \in SIU(N)$ and $k,l\in U$ 
 such that they are symmetric players in the quotient game $(U,\overline{W})$, then
     $$
    \sum_{i\in P_{k}} F_{i}(N,W,P)=\sum_{i\in P_{l}} F_{i}(N,W,P).
     $$

\textbf{Symmetry inside unions (S-IU).} A coalitional power index $F$ satisfies S-IU if for every $(N,W,P) \in SIU(N)$ and $i,j\in P_{k}\in P$, such that they are symmetric players in the game $(N,W)$, then $F_{i}(N,W,P)=F_{j}(N,W,P)$.\medskip

\textbf{Transfer for coalitions of least size among unions (TCLS-AU).} A coalitional power index $F$ satisfies TCLS-AU if for any pair $(N,W, P)$ and $(N, V, P)\in SIU(N)$ such that $\overline{W}^{ls}\cap \overline{V}^{ls} =\emptyset$,  then
    $$
    F (N,W \vee V, P)= \left\{ \begin{array}{lcc} F (N,W, P), & \textrm{if} &  c_{\hspace{0.4mm}\overline{W}} <  c_{\hspace{0.4mm}\overline{V}} \\ \\ F (N,V, P), & \textrm{if} & c_{\hspace{0.4mm}\overline{V}} <  c_{\hspace{0.4mm}\overline{W}}\\ \\ \frac{ p_{\hspace{0.4mm}\overline{W}}}{ p_{\hspace{0.4mm}\overline{W}}+ p_{\hspace{0.4mm}\overline{V}}}F (N,W, P) + \frac{ p_{\hspace{0.4mm}\overline{V}}}{ p_{\hspace{0.4mm}\overline{W}}+ p_{\hspace{0.4mm}\overline{V}}} F (N,V, P),&  & \textrm{otherwise.} \end{array} \right.
    $$

\textbf{Transfer for coalitions of least size inside unions (TCLS-IU).} A coalitional power index $F$ satisfies TCLS-IU if for any pair $(N,W, P)$ and $(N, V, P)\in SIU(N)$ verifying that  $W^{ls}\cap V^{ls} =\emptyset$ and there exists $k\in U$ such that for every $S\in W^{m} \cup V^{m}$ it holds that $S\subseteq P_{k}$, then
       $$
    F(N,W \vee V, P)= \left\{ \begin{array}{lcc} F (N,W, P), & \textrm{if} &  c_{\hspace{0.4mm}W} <  c_{\hspace{0.4mm}V} \\ \\ F (N,V, P), & \textrm{if} & c_{\hspace{0.4mm}V} <  c_{\hspace{0.4mm}W}\\ \\ \frac{ p_{\hspace{0.4mm}W}}{ p_{\hspace{0.4mm}W}+ p_{\hspace{0.4mm}V}}F (N,W, P) + \frac{ p_{\hspace{0.4mm}V}}{ p_{\hspace{0.4mm}W}+ p_{\hspace{0.4mm}V}} F (N,V, P),&  & \textrm{otherwise.} \end{array} \right.
    $$

\textbf{Independence of irrelevant coalitions (IIC).} A coalitional power index $F$ satisfies IIC if for any $(N,W,P)$, given $\widetilde{S} \in W^{m}$ such that $u(\widetilde{S}) \notin \overline{W}^{m}$, then $F(N,W,P)= F(N,W',P)$ where $(W')^m = W ^m \setminus \{\widetilde{S}\}$.\\
This property says that  only coalitions whose representatives play an essential role in the quotient game affect power distribution.\medskip

\textbf{Invariance with respect to least size essential coalitions (ILSE).} A coalitional power index $F$ satisfies ILSE if for any pair $(N,W, P)$ and $(N, V, P) \in SIU(N)$, verifying that $ E^{ls}(N,W, P) = E^{ls}(N, V, P)$ and that there exists $R=\{k_{1},\ldots,k_{s}\}\subseteq U$ such that $\overline{W}^{ls} = \{R\}$ and $\overline{V}^{ls} = \{\{k_{1}\},\ldots,\{k_{s}\}\}$,  then $F(N,W, P) = F (N, V, P)$. 
The ILSE property states that if a game has a unique least size winning coalition of unions, say $\overline{W}^{ls}=\{\{k_{1},\ldots,k_{s}\}\}$, the power distribution among players remains the same when the winning coalitions $S\in W^{m}$ whose representatives are $\{k_{1},\ldots,k_{s}\}$, are decomposed into individual unions
 $S\cap P_{1}, \ldots S \cap P_{s}\in V^{m}$, since essential coalitions of least size 
remain the same. This property is closely related to Owen’s approach in the two-level bargaining model, which assumes that subsets of a union cannot ally with proper subsets of other unions. We illustrate this property with the following example.\\

\begin{example}\label{ej:esenciales2}
 Consider the player set $N=\{a,b,c,d,e,f\}$, partitioned into two groups $P_{1}=\{a,b,c,d\}$ and $P_{2}=\{e,f\}$. Examine the games $(N,W_{1},P)$ and $(N,V,P)$, with the following sets of minimal winning coalitions:
$$
W_{1}^{m}=\{\{a,b,e\},\{c,d,f\},\{a,b,f\}\}  \text{ and } V^{m}=\{\{a,b\},\{c,d\},\{e\},\{f\}\}.
$$ 
Clearly,  minimal winning coalitions of $V$ are those of $W_{1}$ decomposed into individual unions. These two games are under the conditions of the ILSE property, because their quotient games verify that  $\overline{W_{1}}^{ls}=\{\{1,2\}\}$ and $\overline{V}^{ls} =\{\{1\},\{2\}\}$, and their least size essential coalitions coincide:
 $$ 
 E^{ls}(N,W_{1},P)=\{\{a,b\},\{c,d\},\{e\},\{f\}\}= E^{ls}(N,V,P).
 $$ 
Therefore, for any index $F$ satisfying ILSE property, it follows that $F(N,W_{1}, P) = F (N, V, P)$. Now, consider a third game $W_{2}$, where $W^{m}_{2}$ is formed by removing coalition $\{a,b,f\}$ from $W^{m}_{1}$: $$W^{m}_{2}=\{\{a,b,e\},\{c,d,f\}\}.$$
This game still meets the same ILSE conditions, hence $F(N,W_{1}, P) = F (N, W_{2}, P)$.


The interpretation behind this result is that coalition $\{a,b,f\}$ in $W_{1}$ does not supply any additional power to players $a$ and $b$, provided that $\{a,b,e\}$ already exists.
Even though $\{a,b\}$ appears to have two distinct ways to win in $W_{1}$ (with $e$ or with $f$) and only one in $W_{2}$, the coalition structure dictates that $a$ and $b$ can only negotiate their power by joining the entire union $P_{2}=\{e,f\}$. Hence, the availability of partial cooperation does not alter the resulting power distribution.
\end{example}

