\begin{theo}
\label{Theorem2}
The Felsenthal Owen power index is the only coalitional power index that satisfies E, NP, S-AU, S-IU, TCLS-AU, TCLS-IU, IIC, and ILSE. 
\end{theo}

\begin{proof}
\quad\\
\noindent\textbf{Existence.}
First, we will briefly show that the Felsenthal Owen power index satisfies E, NP, S-AU, and S-IU.\medskip

\noindent \textit{E:} Since the Felsenthal power index is efficient and the Felsenthal Owen power index satisfies the QG property, 

$$\sum_{i\in N}\Psi_{i}(N,W,P) = \sum_{k\in U} \sum_{i\in P_{k}}\Psi_{i}(N,W,P) = \sum_{k\in U} \psi_{k}(U,\overline{W}) =1.
    $$ 

\noindent \textit{NP:} Let $i\in N$ be a null player, i.e., $W^{m}_{i}=\emptyset$. Then, for every $R\in \overline{W}^{ls}$, $E_{R,k,i}(N,W,P)=\emptyset$, what implies that $\Psi_{i}(N,W,P)=0$.\medskip 

\noindent \textit{S-AU:} Given two symmetric players $k$ and $l$ in the game $(U,\overline{W})$, the QG property and the symmetry in the case of the Felsenthal power index imply that
     $$
    \sum_{i\in P_{k}} \Psi_{i}(N,W,P)=\psi_{k}(U,\overline{W})=\psi_{l}(U,\overline{W})=\sum_{i\in P_{l}} \Psi_{i}(N,W,P).
     $$

\noindent \textit{S-IU:} Let $i,j$ be two symmetric players in the union $ P_{k}$. For each $R\in \overline{W}^{ls}_{k}$, they are symmetric players in the game $(P_{k},W_{R,k})$. Since $\psi$ satisfies the property of symmetry,    
\begin{equation*} 
\begin{split}
\Psi_{i}(N,W,P)& = \frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\psi_{i}(P_{k},W_{R,k})  \\
 & = \frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\psi_{j}(P_{k},W_{R,k})=\Psi_{j}(N,W,P).
\end{split}
\end{equation*}

\noindent Next, we will prove that $\Psi$ satisfies both TCLS-AU and TCLS-IU.\medskip 

\noindent\textit{TCLS-AU:} Let us consider $(N,W, P)$ and  $(N, V, P) \in SIU(N)$ such that $\overline{W}^{ls}\cap \overline{V}^{ls} =\emptyset$. There are three options:
    \begin{enumerate}[label=(\roman*)]
    \item  $c_{\hspace{0.4mm}\overline{W}} < c_{\hspace{0.4mm}\overline{V}}$. Then, $(\overline{W} \vee \overline{V})^{ls} = \overline{W}^{ls} $ and, given $R \in \overline{W}^{ls}$ and $k\in R$, $E^{ls}_{R,k}(N,W\vee V,P) = E^{ls}_{R,k}(N,W,P)$. Hence, for any $i\in P_{k}$, 
        \begin{align*}
                \mathclap{\hspace{20mm}\Psi_{i}(N,W \vee V,P)} & \notag \\
                &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\sum_{R\in \overline{W\vee V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|} \\
                &=\frac{1}{|\overline{W}\hspace{0.2mm}^{ls}|}\sum_{R\in \overline{W}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W ,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W ,P)}\frac{1}{|S|} \\
                &=\Psi_{i}(N,W ,P).
        \end{align*}
    \item  $c_{\hspace{0.4mm}\overline{W}} > c_{\hspace{0.4mm}\overline{V}}$. It is analogous to the previous case.
     \item  $c_{\hspace{0.4mm}\overline{W}} = c_{\hspace{0.4mm}\overline{V}}$. Then, since  $\overline{W}^{ls}\cap \overline{V}^{ls} =\emptyset$, we distinguish two possibilities for each $R\in (\overline{W} \vee \overline{V})^{ls}:
        $\begin{itemize}
            \item $R \in \overline{W}^{ls}$. For each $k\in R$, $E^{ls}_{R,k}(N,W\vee V,P) = E^{ls}_{R,k}(N,W,P)$.
            \item $R \in \overline{V}^{ls}$. For each $k\in R$, $E^{ls}_{R,k}(N,W\vee V,P) = E^{ls}_{R,k}(N,V,P)$.
        \end{itemize}
    Thus,\\[7pt]
\noindent
\(\Psi_{i}(N,W \vee V,P)\)
\vspace{-0.5em}
\begin{align}
    &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\sum_{R\in \overline{W\vee V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|} \notag \\
    &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\Bigg[\sum_{R\in \overline{W}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|} \notag \\
    & \quad + \sum_{R\in \overline{V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|}\Bigg] \\
    &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\Bigg[\sum_{R\in \overline{W}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W ,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W ,P)}\frac{1}{|S|} \notag \\
    & \quad + \sum_{R\in \overline{V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N, V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N, V,P)}\frac{1}{|S|}\Bigg] \\
    &= \frac{ p_{\hspace{0.4mm}\overline{W}}}{ p_{\hspace{0.4mm}\overline{W}}+ p_{\hspace{0.4mm}\overline{V}}}\Psi_{i} (N,W, P) + \frac{ p_{\hspace{0.4mm}\overline{V}}}{ p_{\hspace{0.4mm}\overline{W}}+ p_{\hspace{0.4mm}\overline{V}}}\Psi_{i}(N,V, P). \notag
\end{align}

  %  \begin{equation*}
  % \begin{split}
  %   \mathclap{\hspace{20mm}\Psi_{i}(N,W \vee V,P)} & \notag \\
  %   &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\sum_{R\in \overline{W\vee V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|} \\
  %   &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\Bigg[\sum_{R\in \overline{W}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|} \notag \\
  %   & \quad + \sum_{R\in \overline{V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W \vee V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W \vee V,P)}\frac{1}{|S|}\Bigg] \\
  %   &= \frac{1}{|\overline{W \vee V}\hspace{0.2mm}^{ls}|}\Bigg[\sum_{R\in \overline{W}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W ,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W ,P)}\frac{1}{|S|} \notag \\
  %   & \quad + \sum_{R\in \overline{V}\hspace{0.01mm}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N, V,P)|} \sum_{S\in E_{R,k,i}^{ls}(N, V,P)}\frac{1}{|S|}\Bigg] \\
  %   &= \frac{ p_{\hspace{0.4mm}\overline{W}}}{ p_{\hspace{0.4mm}\overline{W}}+ p_{\hspace{0.4mm}\overline{V}}}\Psi_{i} (N,W, P) + \frac{ p_{\hspace{0.4mm}\overline{V}}}{ p_{\hspace{0.4mm}\overline{W}}+ p_{\hspace{0.4mm}\overline{V}}}\Psi_{i}(N,V, P).
  %   \end{split}
  %   \end{equation*}  

    \end{enumerate}
 \noindent\textit{TCLS-IU:} Given $(N,W, P)$ and $(N, V, P) \in SIU(N)$ verifying that, for every $S\in W^{m} \cup V^{m}$, it holds that there exists $P_k\in P$ such that $S\subseteq P_{k}$.
    Then $\overline{W}^{ls}=\overline{V}^{ls}=\overline{W\vee V}^{ls}= \{\{k\}\}$ and $E_{\{k\},k}^{ls}(N,W\vee V,P) = (W\vee V)^{ls}$. So

    $$
    \Psi_{i}(N,W \vee V,P) =\frac{1}{| (W\vee V)^{ls}|}\sum_{S\in (W\vee V)_{i}^{ls}}\frac{1}{|S|}.
    $$
    Hence, there are three options:
    \begin{enumerate}[label=(\roman*)]
        \item $c_{W}<c_{V}$. In this case, $(W\vee V)^{ls}=W^{ls}$ and
         $$
        \Psi_{i}(N,W \vee V,P)= \frac{1}{| W^{ls}|}\sum_{S\in W_{i}^{ls}}\frac{1}{|S|}=\Psi_{i}(N,W,P).
        $$

        \item $c_{V}<c_{W}$. Analogous to the previous case.
        \item $c_{W}=c_{V}$. As  $W^{ls}\cap V^{ls} =\emptyset$, 
         \begin{align*}
          \Psi_{i}(N,W \vee V,P) &=\frac{1}{| W^{ls}|+| V^{ls}|}\Bigg[\sum_{S\in W_{i}^{ls}}\frac{1}{|S|}  + \sum_{S\in V_{i}^{ls}}\frac{1}{|S|} \Bigg] &\\
          & =\frac{ p_{\hspace{0.4mm}W}}{ p_{\hspace{0.4mm}W}+ p_{\hspace{0.4mm}V}}\Psi_{i} (N,W, P) + \frac{ p_{\hspace{0.4mm}V}}{ p_{\hspace{0.4mm}W}+ p_{\hspace{0.4mm}V}} \Psi_{i}(N,V, P),
        \end{align*}
        where the last equality follows from the fact that $E_{\{k\},k}^{ls}(N,W,P) = W^{ls}$ and  $E_{\{k\},k}^{ls}(N,V,P) = V^{ls}$.
    \end{enumerate}
Finally, we will highlight the main steps to prove that $\Psi$ satisfies IIC and ILSE.\medskip

\noindent\textit{IIC:} If $(N,W,P)$, $(N,W',P)\in SIU(N)$ are such that $u(\widetilde{S}) \notin \overline{W}^{m}$ and $(W')^m = W ^m \setminus \{\widetilde{S}\}$, then $\overline{W}^{ls}=(\overline{W'})^{ls}$ and, for $R \in \overline{W}^{ls}=(\overline{W'})^{ls}$ and $k\in R$, $E^{ls}_{R,k}(N,W,P)=E^{ls}_{R,k}(N,W',P)$. Then
\begin{equation*} 
\begin{split}
\Psi_{i}(N,W,P)& =  \frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W,P)}\frac{1}{|S|}   \\
 & = \frac{1}{|(\overline{W'})^{ls}|}\sum_{R\in (\overline{W'})^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W',P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W',P)}\frac{1}{|S|} \\
 & = \Psi_{i}(N,W',P).
\end{split}
\end{equation*}

\noindent\textit{ILSE:} In this case, for each $k_{j}\in R$, with $j\in \{1,\ldots,s\}$, we know that $E^{ls}_{R,k_{j}}(N,W,P)=E^{ls}_{\{k_{j}\},k_{j}}(N,V,P)$. Since the Felsenthal index $\psi$ matches for games with the same set of least size winning subsets, we deduce that, for $i \in P_{k_{j}}$,  $\psi_{i}(P_{k_{j}},W_{R,k_{j}})=\psi_{i}(P_{k_{j}},V_{\{k_{j}\},k_{j}})$. So,
$$
\Psi_{i}(N,W,P) = \frac{1}{|R|}\psi_{i}(P_{k},W_{R,k_{j}})= \frac{1}{|\overline{V}^{ls}|}\psi_{i}(P_{k},V_{\{k_{j}\},k_{j}})=\Psi_{i}(N,V,P) .
$$

\noindent\textbf{Uniqueness: }  We demonstrate that the Felsenthal Owen index $\Psi$ is the only coalitional index satisfying the above properties. To this aim, let $F$ be a coalitional power index satisfying those properties and consider $(N,W,P)\in SIU(N)$ with set of minimal winning coalitions $W^{m}=\{S_{1},\ldots,S_{q}\}$. Since $F$ satisfies IIC, we can assume that 
$u(S) \in \overline{W}^{m}$, for every $ S\in W^{m}$.

\noindent We begin by considering the case when $q=1$. In this scenario, $W^{m} = \{S\}=W^{ls}$ for a certain set $S\subseteq N$, i.e., $(N,W)$ is the unanimity game of $S$. Consequently,  the quotient game $(U,\overline{W})$ is the unanimity game of $u(S)$ since $\overline{W}^{m}=\{u(S)\}=\overline{W}^{ls} $. By E and NP:
\begin{equation*}
   1=\sum_{i\in N}F_{i}(N,W,P) = \sum_{i\in S}F_{i}(N,W,P)=\sum_{k\in u(S)}\sum_{i\in S\cap P_{k}}F_{i}(N,W,P).
\end{equation*}

 \noindent Moreover, since the unions in $u(S)$ are symmetric in $(U,\overline{W})$ and the players in $S\cap P_{k}$ are  symmetric in $(N,W)$, by S-AU and S-IU we can conclude that for each $i\in P_k\in P$:
\begin{equation}\label{eq:charac2_unic_1}
  F_{i}(N,W,P) = \begin{cases}
         \frac{1}{|u(S)|| S\cap P_{k}|} & ,\text{ if} \ i \in S\cap P_{k}\\
        0 & , \text{ if} \ i \notin S\cap P_{k}.
    \end{cases}
\end{equation}

\noindent Now, let us examine the case where $q>1$. To this aim, consider a partition of $W^{m}$ into sets $\{T_{1},\ldots, T_{l}\}$, defined by the equivalence relation:
$$S_{d_{1}}, S_{d_{2}} \in T_{h} \Leftrightarrow u(S_{d_{1}})= u( S_{d_{2}}) = R_{h},\hspace{2mm}h \in \{1,\ldots,l\}.$$ 
\noindent Thus, each  $T_{h}$ consist of coalitions $ T_{h} = \{ S_{h_{1}},S_{h_{2}},\ldots, 
S_{h_{t_{h}}}\}\subseteq W^{m}$, and we decompose $W$ as follows:
$$W = W^{T_{1}} \vee \ldots \vee  W^{T_{l}},\text{ where }    W^{T_{h}}=  W_{S_{h_{1}}} \vee \ldots \vee  W_{S_{h_{t_{h}}}}.
$$\medskip

\noindent Given that $\overline{W}^{m} =\{R_{1},\ldots, R_{l}\}$, and assuming $\overline{W}^{ls} =\{R_{1},\ldots, R_{l'}\}$, with $l'\le l$. Then, we can rewrite:
  \[W=\underbrace{W^{T_{1}} \vee \ldots \vee  W^{T_{l'}}}_{V_{1}}\vee\underbrace{W^{T_{l'+1}} \vee \ldots \vee  W^{T_{l}}}_{V_{2}} = V_{1} \vee V_{2}.\]

\noindent Since $(\overline{V}_{1})^{ls} \cap (\overline{V}_{2})^{ls}=\emptyset$  and  $c_{\overline{V}_{1}} < c_{\overline{V}_{2}}$, the property TCLS-AU ensures that  $F(N,W,P) = F(N,V_{1},P).$\medskip

\noindent Consider now the collection $\bigl\{(N,W^{T_{h}},P)\mid\hspace{1mm} h \in \{1, \ldots, l'\}\bigr\}$. For each  $h\in \{1,\ldots, l'\}$, it follows that $(\overline{W^{T_{h}}})^{m}=(\overline{W^{T_{h}}})^{ls}= \{R_{h}\}$, $p_{\hspace{1mm}\overline{W^{T_{h}}}}=1$ and $c_{\hspace{1mm}\overline{W^{T_{h}}}}=c_{\hspace{1mm}\overline{W}}=| R_{h}|$. Additionally, for any $ h_{1},h_{2} \in \{1, \ldots, l'\}$  we have that $(\overline{W^{T_{h_{1}}}})^{ls}\cap (\overline{W^{T_{h_{2}}}})^{ls}= \{R_{h_{1}}\}\cap \{R_{h_{2}}\}= \emptyset$ and $c_{\hspace{1mm}\overline{W^{T_{h_{1}}}}}= c_{\hspace{1mm}\overline{W^{T_{h_{2}}}}}$ for $h_{1}\neq h_{2}.$ Applying TCLS-AU property again and noting that $ \overline{W}^{ls}= \overline{V_{1}}^{ls}$, we obtain:
\begin{equation}\label{eq:charac2_unic_5}
   F(N,V_{1},P) =\frac{1}{\big| \overline{V_{1}}^{ls}\big| }\sum_{h=1}^{l'} p_{\hspace{0.5mm}\overline{W^{T_{h}}}}\hspace{1mm}F(N,W^{T_{h}},P) 
        = \frac{1}{\big| \overline{W}^{ls}\big| }\sum_{h=1}^{l'}  \hspace{0.5mm}F(N,W^{T_{h}},P).
    \end{equation}

\noindent Next, to analyze $F(N,W^{T_{h}},P)$, we define the disjunction game $W_{h}=\vee_{k\in R_{h}} W_{R_{h},k}$, where each component is determined by $(W_{R_{h},k})^{m}= E_{R_{h},k}(N,W^{T_h},P).$\\
Since $E^{ls}(N,W_{h},P)= E^{ls}(N,W^{T_{h}},P)$ and 
$(\overline{W^{T_{h}}})^{ls} = \{R_{h}\}$, whereas $(\overline{W_{h}})^{ls} = \{\{k\} \mid {k\in R_{h}}\}$, the ILSE property ensures that $F(N,W^{T_{h}},P)=F(N,W_{h},P)$.\medskip

\noindent We now $F(N,W_{h},P)$ decompose by reapplying once more the TCLS-AU property. Consider the collection  $\{(N,W_{R_{h},k},P) \mid k\in R_{h}\}$ in which for any $k_{1},k_{2}\in R_{h}$ we have that $(\overline{W_{R_{h},k_{1}}})^{ls}\cap(\overline{W_{R_{h},k_{2}}})^{ls}= \{\{k_{1}\}\}\cap\{\{k_{2}\}\}=  \emptyset$ and $c_{\hspace{1mm}\overline{W_{R_{h},k_{1}}}} = c_{\hspace{1mm}\overline{W_{R_{h},k_{2}}}}= 1$, $k_{1}\neq k_{2}$. Given a player $i\in P_{k}$, there are two options:
\begin{enumerate}
    \item If  $k\notin R_{h}$, then $i$ is a null player in the game $(N,W_{h},P)$ and the NP property implies that $F_{i}(N,W_{h},P)=0$.
    \item Otherwise,  $k\in R_{h}$ and by TCLS-AU:
    \begin{equation}\label{eq:charac2_unic_6}
          \begin{aligned}[t]
     F_{i}(N,W_{h},P) &= \frac{1}{p_{\hspace{0.4mm}\overline{W_{h}}}}\sum_{\tilde{k}\in R_{h}}p_{\hspace{1mm}\overline{W_{R_{h},\tilde{k}}}}F_{i}(N,W_{R_{h},\tilde{k}},P) \\
        &= \frac{1}{|R_{h}|}\sum_{\tilde{k}\in R_{h}} F_{i}(N,W_{R_{h},\tilde{k}},P) \\
               &= \frac{1}{|R_{h}|}F_{i}(N,W_{R_{h},k} ,P),
  \end{aligned}
    \end{equation}
     where the equalities follow from the fact that $p_{\hspace{1mm}\overline{W_{R_{h},\tilde{k}}}}=1$ for all $ \tilde{k}\in R_{h}$, and that $i\in P_{k}$ is a null player in each game $(N,W_{R_{h},\tilde{k}},P)$ with $\tilde{k}\in R_{h}$, $\tilde{k} \neq k$ combined with the assumption that $F$ satisfies the NP property.\medskip

    \noindent Lastly, $F_{i}(N,W_{R_{h},k} ,P)$ is decomposed by considering the TCLS-IU property.   Note that $W_{R_{h},k}=W_{L_{1}} \vee \ldots \vee W_{L_{z}}$, with $L_{j} \subseteq P_{k}$ and $(N,W_{L_{j}},P)$ the unanimity game of $L_{j}$. Consider the collection  $\{(N,W_{L_{j}},P) \mid j\in \{1,\ldots, z\}\} $,  for any $j_{1},j_{2}\in \{1,\ldots, z\} $,   $(W_{L_{j_{1}}})^{ls}\cap (W_{L_{j_{2}}})^{ls}= \emptyset$ and 
$c_{\hspace{1mm}\overline{W_{L_{j_{1}}}}} = c_{\hspace{1mm}\overline{W_{L_{j_{2}}}}}$ for $j_{1}\neq j_{2}$. Thus, TCLS-IU implies that:
\begin{equation}\label{eq:charac2_unic_7}
          \begin{aligned}[t]
      F_{i}(N,W_{R_{h},k},P)  &=\frac{1}{p_{\hspace{0.5mm}W_{R_{h},k}}}\sum_{j=1}^{z}p_{\hspace{0.5mm}W_{L_{j}}} \hspace{0.5mm}F_{i}(N,W_{L_{j}},P) \\
        &= \frac{1}{|E_{R_{h},k}^{ls}(N,W,P)|}\sum_{S\in E_{R_{h},k,i}^{ls}(N,W,P)} \hspace{0.5mm}F_{i}(N,W_{S},P).
  \end{aligned}
    \end{equation}
     where the last equality follows from  the fact that $i$ is a null player in every game $(N,W_{L_{j}},P)$ such that $i \notin L_{j}$ and $F$ satisfies the NP property.
\end{enumerate}
\noindent Taken together the results~(\ref{eq:charac2_unic_1}), (\ref{eq:charac2_unic_5}), (\ref{eq:charac2_unic_6}), and (\ref{eq:charac2_unic_7}), we have that for $i\in P_{k}$,
\begin{align*}
      F_{i}(N,W,P) & =\frac{1}{\big| \overline{W}^{ls}\big| }\sum_{h=1}^{l'}  \hspace{0.5mm}F_{i}(N,W^{T_{h}},P)&\\
      & =  \frac{1}{\big| \overline{W}^{ls}\big| }\sum_{h=1}^{l'}  \hspace{0.5mm} \frac{1}{|R_{h}|}F_{i}(N,W_{R_{h},k},P)&\\
      & =  \frac{1}{\big| \overline{W}^{ls}\big| }\sum_{h=1}^{l'}  \hspace{0.5mm}    \frac{1}{|R_{h}|}\frac{1}{|E_{R_{h},k}^{ls}(N,W,P)|}\sum_{S\in E_{R_{h},k,i}^{ls}(N,W,P)} \hspace{0.5mm}F_{i}(N,W_{S},P)&\\
      & =  \frac{1}{|\overline{W}^{ls}|}\sum_{R\in \overline{W}^{ls}_{k}}\frac{1}{|R|}\frac{1}{|E_{R,k}^{ls}(N,W,P)|} \sum_{S\in E_{R,k,i}^{ls}(N,W,P)}\frac{1}{|S|}.
    \end{align*} 
    Thus, we conclude that  $F$ is the Felsenthal Owen  power index $\Psi$.

\end{proof}


\section{Application example: The International Monetary Fund}

The International Monetary Fund (IMF) is a global financial organization engaged  with the economic well-being and development of its 191 member countries. Among its main objectives, the IMF promotes international monetary cooperation, fosters global trade expansion, and provides temporary financial assistance to countries facing economic difficulties. 
% It for example tries to manage world economy in an era of increasing globalisation, for example by provide clear and reliable rules for international financial and commercial exchanges", Which promotes a more dynamic and efficient international trade, Avoid monetary crises
% Proveer reglas claras y confiables para los intercambios financieros y comerciales, loque promueve un comercio internacional más dinámico y eficiente.

% management of the world economy in an era of increasing globalisation.(Reredactar porque esto está copiado)  regulan la actividad comercial y financiera de carácter internacional entre los países.// implementar políticas económicas conservadoras y disciplinadas en términos de manejo de la moneda y las finanzas para crear condiciones estables y previsibles que favorezcan el comercio internacional.Evitar crisis monetarias que puedan interrumpir cadenas de suministro o acuerdos comerciales.
% Proveer reglas claras y confiables para los intercambios financieros y comerciales.\\
% gestión económica prudente y disciplinada es esencial para fortalecer la confianza en el sistema financiero global, lo que a su vez promueve un comercio internacional más dinámico y eficiente.\\[10pt]

The highest decision-making body of the IMF is the \textit{Board of Governors}, consisting at present of 191 governors, each representing a member country.  Governors are assigned voting weights based on their country's financial contribution to the IMF, and decisions are made through a weighted voting system. The required quota for reaching a decision varies depending on its importance, with thresholds of 50\%, 70\%, or 85\%.

In practice, the Board of Governors normally convenes once a year. To enhance the efficiency of IMF's activity, a smaller body known as the \textit{Executive Board}, is entrusted with the task of daily decision-making.
The structure of this smaller board is the result of negotiations among member countries, which organize to form groups. Once the groups are formed, each one chooses a representative that casts their votes in the Executive Board, on behalf of the entire group. The groups are called the \textit{constituencies} and the representatives are the \textit{executive directors}. Currently, the body consists of 25 executive directors and, as in the Board of Governors, decisions require a specific percentage of weighted votes (50\%, 70\%, or 85\%).
% \textcolor{DarkGray}{ It should be noted that 6 countries with most weight and also Saudi Arabia form single-member constituencies} 
