\section{Convergence and regularity of the trajectories}\label{sec:convergence}

This section is devoted to the study of the trajectory in $t$ of the solutions for the primal and the dual problem.
Before making more assumptions on the function \(\F\), let us recall some definitions for real valued functions defined on a normed vector space \(E\).

\begin{definition}
\label{def: superlinear} A function \(f\!:E \to \R \cup \{+\infty\} \) is \emph{super-linear at infinity} if 
    \[\lim\limits_{\| x\|\to +\infty} \frac{f(x)}{\| x\|} =+\infty.\]
\end{definition}

\begin{definition}
    \label{weakly concave}
    %A proper convex and lower semi-continuous function \(g\!:E \to \R\cup \{+\infty\}\) is said to be smooth %at \(x_0\in \domain g\), if there exists \(r>0\), \(x_0^*\in \partial f(x_0)\) and \(\lambda(x_0,r)\) such %that
    %\[\forall x \in B(x_0,r) \cap \domain g, \quad g(x)\leq g(x_0) + \langle x_0^* \lvert x-x_0 \rangle + %\frac{\lambda(x_0,r)}{2}\lVert x-x_0\rVert^2.\]
    A proper convex and lower semi-continuous function \(f\!:E\to \R\cup \{+\infty\}\) is \emph{strongly convex} at \(x_0\in \domain f\), if there exists \(r>0\), \(x_0^*\in \partial f(x_0)\) and \(\lambda(x_0,r) > 0\) such that
    \[\forall x \in B(x_0,r) \cap \domain f, \quad f(x)\geq f(x_0) + \langle x_0^* \lvert x-x_0 \rangle + \frac{\lambda(x_0,r)}{2}\lVert x-x_0\rVert^2.\]
\end{definition}


\begin{enumerate}[(H1),start=3]
    \item \label{H3}\(\F\) is super-linear at infinity;
    \item \label{H4}\(W \cap (\R_+)^{\mathcal{X\!\times\mathcal{Y}}} \subset \domain \F\), with \(W\) a neighborhood of the origin;
    \item \label{H5} \(\F^*\) is strongly convex at every point of its domain;
    \item \label{H6} \(\F^*\) is \(\mathcal{C}^2\) on \(\interior (\domain \F^*)\).
\end{enumerate}

\begin{remark}
Assumption \(\textnormal{\cref{H4}}\) implies assumption \(\textnormal{\cref{H2}}\).  
\end{remark}


The following proposition shows in particular that under \(\textnormal{\cref{H3}}\), $F^*$ has full domain. Its proof can be found for example in \cite{santambrogio2023course}, but we provide it for self-containedness.
\begin{proposition}
\label{domain F^*}
Under assumptions \(\textnormal{\cref{H1}}\) and \(\textnormal{\cref{H3}}\), the Legendre transform \(\F^*\) is bounded on every ball.
\end{proposition}

\begin{proof}
Let \(R>0\). For any \(\xi\in B(0,R)\) we have
\[\F^*(\xi) \defeq \sup_{v \in \R^\mathcal{X}\!\oplus\R^\mathcal{Y}} \langle v \vert \xi \rangle - \F(v)\leq \max \left\{\sup_{\substack{v \in \domain \F\\ v\neq 0}} \|v\|\left(\|\xi\| - \frac{\F(v)}{\|v\|}\right), -F(0)\right\}.\]
By super-linearity at infinity of \(\F\), there exists \(M>0\) such that \(\F(v) \leq R\|v\|\) whenever \(\|v\| \geq M \), in which case \(\|v\| \| \xi \| - \F(v) \leq 0\), while for \(v \leq M\) we have
\[
\inp{v}{\xi}-F(v) \leq M \|\xi\| - \inf_{\overline{B}(0, M)} F,
\]
the infimum being a finite quantity since a lower semicontinuous convex function always has an affine minorant. We have shown that \(F^*\) is bounded from above on every ball, and since it is convex lsc, it is also globally bounded from below by a continuous affine map, and the result follows.
\end{proof}

\begin{remark}
In the case where \( \F(\cdot) = \mathrm{D}_\phi(\cdot \vert q) \), with \( q\) fixed, \(\phi\) being superlinear guarantees \(\textnormal{\cref{H3}}\) and \(\phi_\infty'=+\infty\). Moreover, assume that there exists \(W\)  a neighborhood of \(0\) such that \(W\cap\R_+ \subset \domain \phi\) is sufficient to ensure \(\textnormal{\cref{H4}}\).
\end{remark}


\begin{proposition}
Assume \(\F\) is of the form \( \F(\cdot) = \mathrm{D}_\phi(\cdot \vert q) \), with \( q\in (\R_+^*)^{\mathcal X}\! \oplus (\R_+^*)^{\mathcal Y} \) fixed and \(\phi\) being super-linear. Suppose \( \phi^* \) is locally convex and of class \( \mathcal{C}^2 \) on \(\interior (\domain \phi) \) then $F$ satisfies \(\textnormal{\cref{H5}}\) and \( \textnormal{\cref{H6}} \).
\end{proposition}

\begin{proof}
 \(\phi^*\) being of class \( \mathcal{C}^2\) on \(\interior \domain \phi \) is clearly sufficient to ensure \(\textnormal{\cref{H6}}\). Let  now \(\xi\in \R^\mathcal{X}\!\oplus\R^\mathcal{Y}\). Since \(\phi^*\) is locally strongly convex, for any \(u\in \domain \phi^*\), there exists \(r>0\) and \(\lambda(r,u)>0\) such that
\[ \forall v \in B(u,r)\cap \domain \phi^*, \quad  \phi^*(v) \geq \phi^*(u) + \eta (u - v) + \frac{\lambda(r,u)}{2}(u - v)^2,\]
with \(\eta \in \partial \phi(u)\). Thus, given \(\xi\in \R^\mathcal{X}\!\oplus\R^\mathcal{Y}\), one has
\begin{align*}
    \forall \tilde{\xi} \in \R^\mathcal{X}\!\oplus\R^\mathcal{Y}, \quad \F^*(\tilde{\xi}) &= \sum_{z\in \mathcal{X} \sqcup \mathcal{Y}} q_z \phi^*(\tilde{\xi}_z) \\
                   &\geq \sum_{z\in \mathcal{X} \sqcup \mathcal{Y}} q_z \left( \phi^*(\xi_z) + \eta_z (\xi_z - \tilde{\xi}_z) + \frac{\lambda(r_z,\xi_z)}{2}(\xi_z - \tilde{\xi}_z)^2 \right) \\
                   &\geq \F^*(\xi) + \langle \eta \vert \xi - \tilde{\xi} \rangle +\frac{\lambda(r,\xi)}{2} \| \xi - \tilde{\xi} \|^2,
\end{align*}
where \(\eta \in \partial \F^*(\xi)\), \(r\defeq \min_z r_z\) and \(\lambda(r,\xi) \defeq \min_z \lambda(r,\xi_z)\). It means that \(\F^*\) is also locally strongly-convex.
\end{proof}


\begin{lemma}[Uniform coercivity of $\mathscr K_t$]\label{uniform_coercivity_kantorovich_functional}
    Under assumptions \(\textnormal{\cref{H1}}\) and \(\textnormal{\cref{H4}}\), the functional \(\inf\limits_{t>0} \mathscr{K}_t\) is coercive.
\end{lemma}

\begin{proof}
For any \(\xi=(\varphi,\psi)\in \R^\mathcal{X}\!\oplus\R^\mathcal{Y}\), one has
\begin{align*}
\inf_{t>0} \mathscr{K}_t(\xi) &= \F^*\left(-\xi\right) + \inf_{t>0}\!\sum_{(x,y)\in\mathcal{X}\!\times\!\mathcal{Y}}\!\frac{1}{t}e^{t(\varphi_x +\psi_y-c(x,y))} \\
&\geq \F^*\left(-\xi\right) + \inf_{t>0}\!\sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}\frac{1}{t}e^{t\left(\varphi_x +\psi_y-c(x,y)\right)_+} \\
&\geq \F^*\left(-\xi\right) + \sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}\left( \varphi_x +\psi_y-c(x,y)\right)_+\stackrel{\text{def}}{=} V(\xi).
\end{align*}
Let us show that $V$ is coercive. Let \((\xi^n)_{n \in \mathbb{N}}=((\varphi^n , \psi^n))_{n \in \mathbb{N}}\) be a sequence in \(\R^{\mathcal{X}} \!\oplus \R^{\mathcal{Y}}\) such that \(\| \xi^n \| \to +\infty\) as \(n \to +\infty\). On one hand, if there exists \( z_0 \in \mathcal{X} \sqcup \mathcal{Y} \) such that, after taking a subsequence, \(\xi_{z_0}^n \to -\infty\) then we have, using \(\textnormal{\cref{H4}}\), that there exists \(r \in\R^*_+ \) such that \(r e_{z_0}\in\domain \F \). It leads to 
\[V(\xi^n) \geq \F^*(-\xi^n) \geq -\xi_{z_0}^n - \F(r e_{z_0}) \to +\infty.\]
On the other hand, if that is not the case, then for any \(z \in \mathcal{X}\sqcup \mathcal{Y}\),  \(\xi_{z}^n\) is bounded from below by some constant $M <0$. Thus there exists \(z_0 \in \mathcal{X}\sqcup \mathcal{Y} \) such that \(\xi_{z_0}^n \to +\infty\). Without loss of generality we assume that \(z_0 \in \mathcal{X}\). Then we have, using \(\textnormal{\cref{H4}}\) again, that for any \(y\in \mathcal{Y}\), there exists \(r \in\R^*_+ \) such that \(r e_y\in\domain \F \). It leads to 
\begin{align*}
V(\xi^n) &\geq  \F^*(-\xi^n) + \varphi_{z_0}^n + \psi_y^n - c(z_0,y)  \\
&\geq  -r\psi_y^n - F(r e_y) + \varphi_{z_0}^n + \psi_y^n - c(z_0,y) \\
&\geq \abs{1-r}M - F(re_y) + \varphi_{z_0}^n - c(z_0,y)\underset{n \to +\infty}{\longrightarrow}  +\infty.
\end{align*}
We have shown that \(V(\xi^n) \to +\infty\) along a subsequence, but since the same reasoning applies to any arbitrary subsequence taken in the beginning, we get the result for the whole sequence, which establishes the coercivity of \(V\).
\end{proof}

\subsection{Trajectory of the regularized dual of UOT problem}

\begin{proposition}
    \label{regularity of dual trajectory}
     Assume that assumptions \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\) hold. Then, there exists a unique solution $\xi(t)$ to \labelcref{Dual UOT_t} for every \(t > 0\) and the trajectory \(t\mapsto \xi(t)\) is a \(\mathcal{C}^1\) function on \(\R_+^*\).
\end{proposition}

\begin{proof}
The existence and uniqueness of the solution to \labelcref{Dual UOT_t} comes from \Cref{prop: existence for regularized problems} and the strict convexity of the functional \(\mathscr{K}_t\), resulting from \labelcref{H5}\papside{Justifier qq part que H5 $\implies$ strct. convex}.

Let us first consider any point \(t_0\in \R_+^*\) and denote by \(f\!: \R_+^*\times (\R^\mathcal{X}\!\oplus\R^\mathcal{Y})\to\R\) the \(\mathcal{C}^1\) function defined by \(f(t,\xi)=D\!\mathscr{K}_t(\xi)\). By optimality of $\xi(t_0)$, \(f(t_0,\xi(t_0))=0\) and by \labelcref{H5}, we get \(\det D_\xi f(t_0,\xi(t_0)) = \det D^2\! \mathscr{K}_{t_0} (\xi(t_0)) > 0\). Thus the implicit function theorem allows to deduce that the trajectory is \(\mathcal{C}^1\) on \(\R_+^*\).
\end{proof}



\begin{proposition}\label{proposition_ODE}
Assume that assumptions \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\) hold. Then the trajectory \(t\mapsto \xi(t)\) satisfies the following ordinary differential equation (ODE) on \(\R_+^*\):
\begin{equation*}
    D^2\!\mathscr{K}_t(\xi(t)) \dot{\xi}(t) + \left(\frac{\partial}{\partial t} D\!\mathscr{K}_t\right)(\xi(t)) = 0
\end{equation*}
which can be explicitly written as
\begin{equation}
    \label{ODE}
    A \diagonal \gamma(t) A^*\dot{\xi}(t) + \frac{1}{t} D^2\!\F^*\!(-\xi(t))\dot{\xi}(t) + \frac{1}{t^2} A \diagonal \gamma(t)\log \gamma(t) = 0.
    \tag{$\text{ODE}$}
\end{equation}
\end{proposition}

\begin{proof}
For any positive \(t\), by using the optimality of \(\xi(t)\) for the functional \(\mathscr{K}_t\), one can obtain
\[D\!\mathscr{K}_t(\xi(t)) = 0.\]
The function \(t \mapsto D\!\mathscr{K}_t(\xi(t))\) is \(\mathcal{C}^1\) on \(\R_+^*\). Differentiating the previous equality with respect to $t$ and using the chain rule leads to
\[D^2\!\mathscr{K}_t(\xi(t)) \dot{\xi}(t) + \frac{\partial}{\partial t} D\!\mathscr{K}_t(\xi(t)) = 0.\]
By computing $D^2\!\mathscr{K}_t$ and $D\!\mathscr{K}_t$ one then obtains \cref{ODE}.
\end{proof}



\begin{proposition}\label{convergence_dual_optimizer}
    Under assumptions \(\textnormal{\cref{H1}}-\textnormal{\cref{H5}}\), the trajectory \(t\mapsto \xi(t)\) d converges towards the solution \(\xi^*\) to \cref{Dual UOT}, as \(t\rightarrow+\infty\).
\end{proposition}

\begin{proof} Using the optimality of \(\xi(t)\) for \labelcref{Dual UOT_t}, we leverage the following inequality
\[
     \mathscr K_t(\xi_t) = \F^*\!\left(-\xi(t)\right) + \!\sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}\!\frac{1}{t} e^{t\langle A^*\xi(t)-c \vert e_{x,y}\rangle } \leq  \F^*\!\left(-\xi^*\right) + \!\sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}\!\frac{1}{t}e^{t\langle A^*\xi^*-c \vert e_{x,y}\rangle }.\]
The constraint \(A^*\xi^* \preceq c\) allows to deduce that
\begin{equation}
    \label{ineq_proof}
 \mathscr K_t(\xi_t) =\F^*\!\left(-\xi(t)\right) + \!\sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}\! \frac{1}{t}e^{t\langle A^*\xi(t)-c \vert e_{x,y}\rangle } \leq \F^*\!\left(-\xi^*\right) + \frac{\abs{\mathcal X}\abs{\mathcal Y}}{t}.
\end{equation}
From this, and the uniform coercivity of $\mathscr K_t$ as stated in \Cref{uniform_coercivity_kantorovich_functional}, we deduce that the trajectory is bounded on \(\mathbb{R}_+^*\setminus (0,1)\). 
By Bolzano-Weierstrass Theorem, we may consider a sequence \( (t_n)_{n \in \mathbb{N}} \) such that \( \xi(t_n) \to \tilde{\xi} \) as \( n \to +\infty \), where \( \tilde{\xi} \) is an accumulation point of the trajectory (at infinity). Since $(\xi(t_n))$ is bounded, by \Cref{domain F^*} we know that $\abs{F^*(\xi(t_n))}$ is bounded by some constant $C >0$. Thus by \labelcref{ineq_proof}, for every \( n \) and every \( (x, y) \in \mathcal{X} \times \mathcal{Y} \),
\[
 \frac{1}{t_n}e^{t_n\langle A^*\xi(t_n)-c \mid e_{x,y}\rangle} \leq C+\F^*\!\left(-\xi^*\right)+ \frac{\abs{\mathcal X}\abs{\mathcal Y}}{t_n}.
\]
If $\alpha \defeq  \inp{A^* \tilde\xi-c}{e_{x,y}} > 0$ then for $n$ large enough we would have $\frac{1}{t_n} e^{t_n\langle A^*\xi(t_n)-c \mid e_{x,y}\rangle} \geq \frac{e^{\alpha t_n/2}}{t_n} \to +\infty$: a contradiction with the boundedness of the right-hand side of the previous equation. We conclude that \( A^*\tilde{\xi} \preceq c \), meaning that any accumulation point is feasible for the non-regularized dual problem. Moreover by \labelcref{ineq_proof} we also have
\[
\F^*\!\left(-\xi(t_n)\right) \leq \F^*\!\left(-\xi^*\right) + \frac{\abs{\mathcal X}\abs{\mathcal Y}}{t_n},
\]
and taking the limit as \( n \to +\infty \), we obtain
\[
\F^*\!(-\tilde{\xi}) \leq \F^*\!(-\xi^*).
\]
This shows that any accumulation point of the trajectory is optimal for the non-regularized dual problem. But since by \labelcref{H5}, $\F^*$ is strictly convex, \labelcref{Dual UOT} admits a unique solution $\xi^*$, thus $\xi(t_n)$ converges to \( \xi^* \).
\end{proof}


\subsection{Trajectory of the regularized UOT problem}

The purpose of the following proposition is to show that the curve \(t \mapsto \gamma(t)\) converges to \(\gamma^*\), the solution of \cref{UOT} of minimal entropy (which is unique by strict convexity of $\entropy$), under suitable assumptions.

\begin{proposition}\label{convergence_primal_optimizer}
    Under assumptions  \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\), the trajectory \(t\mapsto \gamma(t)\) converges towards \(\gamma^*\), the solution of \cref{UOT} with minimal entropy $\entropy$, as \(t\to +\infty\). Moreover, \(t\mapsto \gamma(t)\) is a \(\mathcal{C}^1\) function on \(\mathbb{R}^*_+\).
\end{proposition}


\begin{proof} We start by showing  that the trajectory is bounded. For any positive \(t\), by optimality of \(\gamma(t)\) for \labelcref{UOT_t rescaled} we have that 
\begin{equation}
\label{ineq full}
\langle c\vert  \gamma(t) \rangle + \F(A\gamma(t)) + \frac{1}{t} \entropy(\gamma(t)) \leq \langle c \vert \gamma^* \rangle + \F(A\gamma^*) +  \frac{1}{t} \entropy(\gamma^*).
\end{equation}
Since \(\gamma^*\) is optimal for \labelcref{UOT}, we have
\[
\langle c \vert \gamma^* \rangle + \F(A\gamma^*) \leq \langle c\vert  \gamma(t) \rangle + \F(A\gamma(t))
\]
and combining it with \labelcref{ineq full} we get
\begin{equation}
    \label{inequality on the entropy}
    \entropy(\gamma(t)) \leq \entropy(\gamma^*).
\end{equation}
By coercivity of \(\entropy\), we can conclude that the trajectory $(\gamma(t))_{t> 0}$ is bounded. It implies that there exists \((t_n)_{n \in \mathbb{N}}\) such that \(\gamma(t_n) \to \tilde{\gamma}\) as \(n \to +\infty\), where \(\tilde{\gamma}\) is an accumulation point at infinity. Taking $t =t_n$ in \cref{ineq full} and passing to the limit, we obtain that \(\tilde{\gamma}\) is a solution of \labelcref{UOT}. Finally, using \Cref{inequality on the entropy}, taking $t=t_n$ and passing to the limit, we obtain
\[
\entropy(\tilde{\gamma}) \leq \entropy(\gamma^*),
\]
which implies that \(\tilde{\gamma} = \gamma^*\), and thus \(\gamma(t) \to \gamma^*\) as \(t \to +\infty\).
Finally, the regularity of the trajectory is a direct consequence of \Cref{prop:primal_dual} and \Cref{regularity of dual trajectory}.
%Moreover, recalling that \(\gamma(t_n) = e^{t_n(A^*\xi(t_n) - c)}\), we obtain
%\[
%\forall (x,y) \notin I_0, \quad \gamma_{x,y}(t_n) = e^{t_n\langle A^*\xi(t_n) - c \vert e_{x,y} \rangle } %\to 0,
%\]
%which means \(\tilde{\gamma}\) belongs to \(\mathcal{S}\). 
\end{proof}

