\section{Asymptotics for the regularized unbalanced problem}\label{sec:asymptotics}
This section is devoted to an asymptotic analysis of the regularized unbalanced problem as \(t\to+\infty\). We divide our study into two parts: we start with the dual problem and then we tackle the primal problem. The proofs are strongly inspired from \cite{cominetti1994asymptotic}, which dealt with linear problems with exponential penalization (entropy penalization in the primal). We adapt their strategy to the non-linearity introduced by the function $\F$.

\subsection{Asymptotic analysis of the dual trajectory}
We start by introducing the linear space \(E_0 \defeq \spn\{A e_{x,y} \: \vert \:(x,y)\in I_0 \}\), where $I_0$ is the set of saturated constraint defined in \Cref{I_0 and slack variable}. It corresponds to the space of marginals of (signed) measures concentrated on the set of saturated constraints.

\begin{lemma}
\label{DF*_in_E0}
    Under assumptions \labelcref{H1} -- \labelcref{H6}, the quantity \(D\!\F^*(-\xi^*)\) belongs to \(E_0\).
\end{lemma}

\begin{proof}
Consider the curve \( t\mapsto \xi(t) \) of solutions to \labelcref{Dual UOT_t}. By \labelcref{H1}, \labelcref{H3}, \labelcref{H6} and \Cref{domain F^*}, $\F^*$ is differentiable on $\R^{\mathcal X} \oplus \R^{\mathcal Y}$, thus the first order optimality condition reads as:
\begin{align*} 
D\!\mathscr{K}_t(\xi(t)) &= 0 \\
\Longleftrightarrow
D\!\F^*\!\left(-\xi(t)\right) + \sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}\gamma_{x,y}(t) A e_{x,y} &= 0.
\end{align*}
By \Cref{convergence_dual_optimizer} and \Cref{convergence_primal_optimizer}, $\xi(t) \to \xi^*$ and $\gamma(t) \to \gamma^*$ as $t\to+\infty$, thus taking the limit in the above expression leads to
\[
D\!\F^*(-\xi^*) + \sum_{(x,y)\in I_0}\gamma_{x,y}^* A e_{x,y} =0,
\]
 where we have used the fact that for any \((x,y)\notin I_0\), one has
\[\gamma_{x,y}(t)=e^{t(A^*\xi(t)-c)} \underset{t \to +\infty}{\longrightarrow} 0.\]
From this, we can conclude that \(D\!\F^*(-\xi^*)\in E_0\).
\end{proof}

For any positive \(t\), we consider the quantity \(d(t)\defeq t(\xi(t)-\xi^*)\) and we look at $\mathscr{K}_t$ as a function of $d$ instead of $\xi$, namely we introduce the new   functional \(\tilde{\mathscr{K}}_t\!: \R^\mathcal{X}\!\oplus \R^\mathcal{Y} \to \R\) defined as
\[\tilde{\mathscr{K}}_t(d) \defeq \F^*\left(-\frac{1}{t}d - \xi^*\right) + \!\sum_{(x,y)\in \mathcal{X}\!\times \!\mathcal{Y}}\!\frac{1}{t} e^{\langle A^* d - t \kappa \vert e_{x,y} \rangle }, \]
where \(\kappa\) is the gap between \(A\xi^*\) and \(c\) as defined in \Cref{I_0 and slack variable}. Notice that it is defined in such a way that $\tilde{\mathscr{K}}_t(t(\xi-\xi^*)) = \mathscr K_t(\xi)$.
\begin{proposition}\label{boundedness_d}
     Under assumptions  \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\), for any \(\varepsilon >0\) the trajectory \(t \mapsto d(t)\) is uniformly bounded on \(\R_+ \backslash (0,\varepsilon)\).
\end{proposition}

\begin{proof} Let \(\varepsilon>0\) and \(t>\varepsilon\). Notice now that for any \((x,y) \in I_0\), one has
\[ \langle A^*d(t) \vert e_{x,y} \rangle = t\langle A^*\xi(t)-A^*\xi^* \vert e_{x,y} \rangle  = t\langle A^*\xi(t) - c \vert e_{x,y} \rangle,\]
and thus
\[\langle A^*d(t) \vert e_{x,y} \rangle = \log \gamma_{x,y}(t) \xrightarrow{t\to+\infty} \log \gamma_{x,y}^*.\]
We deduce from this and from the regularity of $\xi(t)$, see \Cref{regularity of dual trajectory}, that \( \langle A^*d(t) \vert e_{x,y} \rangle \) is a bounded quantity on \(\R_+ \backslash (0,\varepsilon)\) for any \((x,y)\in I_0\), which in turn implies that \(d^{(0)}(t)\), the projection of \(d(t)\) onto \(E_0\), is bounded. Besides, since $\tilde{\mathscr{K}}_t(t(\xi-\xi^*)) = \mathscr K_t(\xi)$ and $\xi(t)$ is the unique minimizer of $\mathscr K_t$, $d(t)$ is the unique minimizer $\tilde{\mathscr K}_t$. Comparing it with $d^{(0)}(t)$ yields
\[
\tilde{\mathscr{K}}_t(d(t)) \leq \tilde{\mathscr{K}}_t(d^{(0)}(t)),
\]
which implies
\begin{multline*}
    \F^*\left(-\frac{1}{t}d(t) - \xi^*\right) + \sum_{(x,y)\in I_0}\!\frac{1}{t}e^{\langle A^*d(t) -t\kappa\vert e_{x,y} \rangle}\\
    \leq \F^*\left(-\frac{1}{t}d^{(0)}(t) - \xi^*\right) + \sum_{(x,y)\in \mathcal X \times \mathcal Y}\frac{1}{t}e^{\langle A^*d^{(0)}(t) -t\kappa\vert e_{x,y} \rangle}.
\end{multline*}
Using that \(\langle A^*d(t) \lvert e_{x,y} \rangle = \langle d(t) \lvert A e_{x,y} \rangle = \langle A^*d^{(0)}(t) \lvert e_{x,y} \rangle\) for any \((x,y)\in I_0\), we obtain
\begin{equation}\label{eq_rate_F*_1}
    \F^*\!\left(-\frac{1}{t}d(t) - \xi^*\!\right) \leq  \F^*\!\left(-\frac{1}{t}d^{(0)}(t) - \xi^*\!\right) + \!\sum_{(x,y)\notin I_0}\!\frac{1}{t}e^{\langle A^*d^{(0)}(t)- t\kappa \vert e_{x,y} \rangle}.
\end{equation}
Notice that $d(t)/t = \xi(t) - \xi^* \to 0$ and $-\xi^* \in \domain \F$. Thus, by \labelcref{H5}, for some $r > \varepsilon$ and all $t\geq r$, we have
\begin{equation}\label{eq_rate_F*_2}
    \F^*\left(-\frac{1}{t}d(t) - \xi^*\right) \geq \F^*\left( - \xi^*\right) - \frac{1}{t} \langle D\!\F^*\left(-\xi^*\right) \vert d(t) \rangle + \frac{\lambda_0(-\xi^*,r)}{2t^2}  \norm{d(t)}^2,
\end{equation}
where $\lambda_0 \defeq \lambda_0(-\xi^*,r) > 0$, and by \labelcref{H6} and Taylor's expansion, we have
\begin{equation}\label{eq_rate_F*_3}
    \F^*\left(-\frac{1}{t}d^{(0)}(t) - \xi^*\right) \leq \F^*\left( -\xi^*\right) -\frac{1}{t}\langle D\F^*\left(-\xi^*\right) \vert d^{(0)}(t) \rangle + \frac{C}{t^2}
\end{equation}
for some $C > 0$ and every $t \geq r$. By \Cref{DF*_in_E0}, we have 
\[ \langle D\!\F^*\!\left( -\xi^* \right) \vert d(t)\rangle = \langle D\!\F^*\!\left( -\xi^* \right) \vert d^{(0)}(t)\rangle,\]
and combining this with \labelcref{eq_rate_F*_1}, \labelcref{eq_rate_F*_2} and \labelcref{eq_rate_F*_3}, we obtain
\[
       \lambda_0 \norm{d(t)}^2 \leq  \sum_{(x,y)\notin I_0} 2te^{\langle A^*d^{(0)}(t) - t\kappa \vert e_{x,y} \rangle } + C.
\]
We have seen that $d^{(0)}(t)$ is bounded, and since $\kappa_{x,y} > 0$ for every $(x,y) \not\in I_0$, the right-hand side is bounded, thus $d(t)$ is bounded as well for $t\geq r \geq \varepsilon$. We obtain the result since $d$ is bounded on any compact interval included in $\R_+^*$, by regularity of $t\mapsto \xi(t)$.
\end{proof}


\begin{proposition}\label{convergence_d}
Under assumptions \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\), the trajectory \(t\mapsto d(t)\) converges towards a finite quantity denoted \(d^*\).
\end{proposition}

Before going into the proof, we introduce the following useful lemma.

\begin{lemma}
    \label{set of solutions}
Let \(E'\) be a normed vector space, \(f\!: E' \to\R\) a strictly convex function and \(L\!:E\to E' \) a linear operator and $F$ an affine subspace of direction $\vec F$. If the set of solutions \(\mathcal{U}\) of the problem 
\[\inf_{x\in F} f(Lx)\]
is nonempty, then for any \(x_0 \in \mathcal{U}\), one has \[\mathcal{U} = x_0 + \left(\vec F \cap \ker L\right).\]
\end{lemma}

\begin{proof}
Let \(x_0 \in \mathcal{U}\). The affine subspace \(F\) can be expressed as \(F = x_0 + \vec F\). Then, any \(x_1 \in \mathcal{U}\) can be expressed as \(x_1 = x_0 + y\), with \(y \in \vec F\). Assuming that \(y \notin \ker L\), $L x_1 \leq Lx_2$ and by strict convexity of $f$ we have  
\[
f(Lx_0) = \frac{1}{2} f(Lx_0) + \frac{1}{2} f(Lx_1) > f(Lx_2),
\]
where \(x_2 \defeq (x_0+x_1)/2 = x_0 + \frac{1}{2} y\).
Since $x_2\in F$, this contradicts the optimality of $x_0$ and $x_1$. Therefore \(y \in \ker L\).

Conversely, let \(x_1 \in F\) defined as \(x_1 = x_0 + y\), with \(y \in \vec F \cap \ker L\).
Then, since \(f(Lx_1) = f(Lx_0)\), it follows that \(x_1 \in \mathcal{U}\).
\end{proof} 

\begin{proof}[Proof of \Cref{convergence_d}]
Let \( d^* \) be an accumulation point of the curve $t\mapsto d(t)$ at $+\infty$, meaning that \( d(t_n) \to d^* \) as \( n \to +\infty \) for some sequence \(t_n \to +\infty\). We know that there exists such an accumulation point thanks to \Cref{boundedness_d}. Since \( \xi(t_n) \) is a minimizer of \labelcref{Dual UOT_t} for $t=t_n$, we obtain the following equation:
\[
D\!\F^*\!\left(-\frac{1}{t_n}d(t_n)-\xi^*\right) + \sum_{(x,y)\in \mathcal{X}\!\times\!\mathcal{Y}}e^{\langle A^*d(t_n) - t_n \kappa \vert e_{x,y}\rangle }A e_{x,y} = 0.
\]
Taking the limit in this expression leads to
\[
D\!\F^*(-\xi^*) + \sum_{(x,y)\in I_0}e^{\langle A^*d^* \vert e_{x,y} \rangle}A e_{x,y}=0.
\]
We recognize that is the first order optimality condition of the following differentiable convex function
\[
\mathrm{G} : z\in\R^\mathcal{X}\!\oplus \R^\mathcal{Y} \mapsto \langle D\!\F^*(-\xi^*)\vert z \rangle +  \sum_{(x,y)\in I_0}e^{\langle A^*z | e_{x,y}\rangle },
\]
so that $d^*$ is a minimizer of $\mathrm{G}$. Notice that by \Cref{DF*_in_E0}, $\langle D\!\F^*(-\xi^*)\vert z \rangle$ is a linear function of the quantities $\inp{A^* z}{e_{x,y}}$ for $(x,y) \in I_0$, and since the exponential is strictly convex,  we may apply \Cref{set of solutions} to assert that the set of optimal solutions \( \mathcal{U} \) of $\mathrm{G}$ is given by
\[
\mathcal{U}= d^* + \bigcap\limits_{(x,y)\in I_0} \ker Ae_{x,y}. 
\]
Now, let us introduce \( d_1^*\in \mathcal{U} \) such that \( d_1^* \neq d^* \). We define \( d_1(t) \) by
\[
d_1(t) \stackrel{\text{def}}{=} d(t) + d_1^* - d^*
\]
which satisfies \( d_1(t_n) \rightarrow d_1^* \) as \( n\rightarrow +\infty \). 

We know that \( d(t) \) is a minimizer solution of the functional \( \tilde{\mathscr K}_t \), thus
\[\tilde{\mathscr{K}}(d(t_n)) \leq \tilde{\mathscr{K}}(d_1(t_n)),\]
or equivalently
\begin{multline*}
    \F^*\left(-\frac{1}{t_n}d(t_n) - \xi^*\right) + \sum_{(x,y)\in \mathcal X \times \mathcal Y}\!\frac{1}{t_n}e^{\langle A^*d(t_n) \vert e_{x,y} \rangle}\\
    \leq \F^*\left(-\frac{1}{t_n}d_1(t_n) - \xi^*\right) + \sum_{(x,y)\in \mathcal X \times \mathcal Y}\frac{1}{t_n}e^{\langle A^*d_1(t_n) \vert e_{x,y} \rangle}.
\end{multline*}
Since $d(t_n)$ and $d_1(t_n)$ are bounded, we can write the second order Taylor expansion of $F^*$ at $-\xi^*$ to get
\begin{multline*}
    \frac{\norm{d(t_n)}_{D^2 \F^*(-\xi^*)}^2}2 + \sum_{(x,y)\in \mathcal X \times \mathcal Y}\!t_ne^{\langle A^*d(t_n) -t_n\kappa\vert e_{x,y} \rangle}\\
    \leq \frac{\norm{d_1(t_n)}_{D^2 \F^*(-\xi^*)}^2}2 + \sum_{(x,y)\in \mathcal X \times \mathcal Y}t_ne^{\langle A^*d_1(t_n) -t_n\kappa\vert e_{x,y} \rangle} + o(1),
\end{multline*}
noticing that the first-order term cancelled thanks to \Cref{DF*_in_E0}. Besides, thanks to the same lemma and the fact that $d(t_n)-d_1(t_n) \in \bigcap_{(x,y)\in I_0} \ker Ae_{x,y}$, the terms corresponding to $(x,y) \in I_0$ in the sum are equal on both sides. By non-negativity of the exponential, we forget the terms corresponding to $(x,y) \not\in I_0$ in the left-hand side, and we get:

\[
    \| d(t_n) \|_{D^2\!\F^*\!(-\xi^*)}^2 \leq  \| d_1(t_n) \|_{D^2\!\F^*\!(-\xi^*)}^2 + \!\sum\limits_{(x,y)\notin I_0}\!\frac{2}{t}e^{\langle Ad_1(t_n) - t\kappa \vert e_{x,y} \rangle } + o(1).
\]
Passing to the limit, we obtain
\[
\| d^* \|_{D^2\!\F^*\!(-\xi^*)}^2 \leq \| d_1^* \|_{D^2\!\F^*\!(-\xi^*)}^2.
\]
Thus, we have shown that \( d^* \) is the unique solution of the strictly convex (by \labelcref{H5}) problem:
\[
\inf\limits_{z\in \mathcal{U}}\: \| z \|_{D^2\!\F^*\!(-\xi^*)}^2.
\]
Since every accumulation point of the trajectory is also a solution, it follows that there is an unique accumulation point \( d^* \).
\end{proof}


Now, one shall compute the derivative of \(d(t)\) with respect to \(t\). A simple computation gives us that \(\dot{d}(t)= \frac{1}{t}d(t) +t \dot{\xi}(t)\). Notice that this quantity consists of two parts: \(d(t)\), which converges by the previous proposition, and \(\dot{\xi}(t)\).

\begin{theorem}
\label{main theorem 2}
Under assumptions \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\), the convergence rate of the curve \( t \mapsto \xi(t) \) is at least of order \( O(t^{-1}) \), i.e. for any \(t\) sufficiently large, one has 
\[
\| \xi(t) - \xi^* \|  \lesssim \frac{1}{t}.
\]
\end{theorem}

\begin{proof}Let \( \varepsilon > 0 \) and \( t \geq \varepsilon \). We define the functional \( \Lambda_t\) by
\[
\Lambda_t(\xi) = \| A^*\xi + A^*\xi^* - c \|_{\diagonal(\gamma(t))}^2 + \frac{1}{t} \| \xi - \xi(t) + \xi^* \|_{D^2 \!\F^*\!(-\xi(t))}^2.
\]
Note that \( \dot{d}(t) \) is optimal for \( \Lambda_t \), since the latter is convex and 
\begin{align*}
    D\Lambda_t(\xi) &= 2A\diagonal(\gamma(t))(A^*\xi + A^*\xi^* - c) + \frac{2}{t}D^2\!\F^*\!(-\xi(t))(\xi - \xi(t)+\xi^*)
\shortintertext{and thus}
    D\Lambda_t(\dot{d}(t)) &= 2t\left(A\diagonal(\gamma(t))A^*\dot{\xi}(t) + \frac{1}{t}D^2\!\F^*\!(-\xi(t))\dot{\xi}(t) + \frac{1}{t^2} A \diagonal(\gamma(t)) \log \gamma(t)\right)\\
    &=0.
\end{align*}
Using this property, we get the following inequality
\begin{align*}
    \Lambda_t(\dot{d}(t)) &\leq \Lambda_t(0) \\
    \Longrightarrow \: \:  \, \frac{1}{t} \| t\dot{\xi}(t) \|_{D^2\!\F^*\!(-\xi(t))}^2 &\leq \sum_{(x,y)\notin I_0} \gamma_{x,y}(t)\langle A^*\xi^* - c \vert e_{x,y} \rangle^2 + \frac{1}{t} \| \xi(t) - \xi^* \|_{D^2\!\F^*\!(-\xi(t))}^2 \\
    \Longrightarrow \quad \: \: \: \| \dot{\xi}(t) \|_{D^2\!\F^*\!(-\xi(t))}^2 &\leq \frac{1}{t} \sum_{(x,y)\notin I_0} \gamma_{x,y}(t)\langle A^*\xi^* - c \vert e_{x,y} \rangle^2 + \frac{1}{t^2} \| \xi(t) - \xi^* \|_{D^2\!\F^*\!(-\xi(t))}^2 \\
    \Longrightarrow \quad \quad \quad \quad \quad \: \: \:   \| \dot{\xi}(t) \|^2 &\leq \frac{1}{t}\frac{C_1}{\lambda_{\min}(t)} \max_{(x,y)\notin I_0}\gamma_{x,y}(t) + \frac{1}{t^4}\frac{\lambda_{\max}(t)}{\lambda_{\min}(t)} \| d(t) \|^2,
\end{align*}
where \( C_1 \defeq \sum_{(x,y)\notin I_0} \kappa_{x,y}^2 \) and \(\lambda_{\min}(t)>0\) and \(\lambda_{\max}(t)<+\infty\) are respectively the smallest and the largest eigenvalues of \(D^2\!\F^*\!(-\xi(t))\). We have already seen that the trajectory \( t \mapsto d(t) \) is bounded for \( t \geq \varepsilon \) which implies that there exists \( C_2 > 0 \) such that, for any \( (x,y) \notin I_0 \), one has  
\[
\gamma_{x,y}(t) = e^{t\langle A^*\xi(t) - c \vert e_{x,y} \rangle} = e^{\langle A^*d(t)\vert e_{x,y} \rangle} e^{-t\kappa_{x,y}} \leq C_2 e^{-t\kappa^*},
\]
where \(\kappa^*\defeq\min\limits_{(x,y)\notin I_0} \kappa_{x,y}\). One obtains  
\[
\| \dot{\xi}(t) \|^2 \leq \frac{1}{t} C e^{-t\kappa^*} + \frac{1}{t^4} K,
\]
where  
\[
C \defeq \sup_{t>\varepsilon} \frac{C_1 C_2}{\lambda_{\min}(t)}<+\infty \quad \text{and} \quad K \defeq \sup_{t>\varepsilon} \frac{\lambda_{\max}(t)}{\lambda_{\min}(t)}  \|d(t)\|^2<+\infty.
\]
Moreover, \(t\mapsto t^{-1}e^{-t\kappa^*}\) converges exponentially fast towards \(0\) and thus \(t^{-1} e^{-t\kappa^*} \lesssim t^{-4}\) when \(t\) is sufficiently large. Consequently, we have as $t$ goes to $+\infty$
\[
\| \dot{\xi}(t) \|  \lesssim  t^{-2},
\]
which leads to
\[
    \| \xi^* - \xi(t) \|  \leq \int_t^{+\infty} \| \dot{\xi}(\omega)\| \,\dd\omega \lesssim \int_t^{+\infty} \frac{1}{\omega^2}\,\dd\omega \lesssim \frac{1}{t}. 
\]
\end{proof}

\subsection{Asymptotic analysis of the regularized transport plan}
\begin{theorem}
\label{main theorem}
Under assumptions \(\textnormal{\cref{H1}}-\textnormal{\cref{H6}}\), the convergence rate of the curve \(t\mapsto \gamma(t)\) is at least of order \(O(t^{-\frac{1}{2}})\), i.e. for any \(t\) sufficiently large, one has
\[\| \gamma(t) - \gamma^*\| \lesssim \frac{1}{\sqrt{t}}. \]
\end{theorem}

\begin{proof} Let \(t>0\) sufficiently large in order to have \(\| \xi(t) -\xi^*\| \lesssim  t^{-1}\) as shown in \Cref{main theorem 2}. We have seen in \Cref{proposition_ODE} that $\dot\xi$ solves \labelcref{ODE}, which can be recognized as the first-order optimality condition of the following convex optimization problem
\[\inf_{\R^\mathcal{X}\!\oplus \R^\mathcal{Y}} \Psi_t(\xi) \defeq \inf\limits_{\xi\in \R^\mathcal{X}\!\oplus \R^\mathcal{Y}} \| A^*\xi + \frac{1}{t^2}\log\gamma(t)\|^2_{\diagonal(\gamma(t))}  + \frac{1}{t} \| \xi\|^2_{ D^2\!\F^*\!(-\xi(t))}.\]
We compare $\dot\xi(t)$ with the competitor \(h(t)\defeq \frac{\xi^* - \xi(t)}{t}\) to obtain
\begin{align*}
    \Psi_t(\dot{\xi}(t)) &\leq \Psi_t(h(t))\\
     &\leq \sum_{(x,y)\in \mathcal{X}\times\mathcal{Y}}  \gamma_{x,y}(t)\left(\inp{A^*h(t)}{e_{x,y}}+\frac{\log\gamma_{x,y}(t)}{t^2}\right)^2 + \frac{1}{t}\| h(t)\|^2_{D^2\mathrm{F}^*(-\xi(t))} \\   
   &\leq \sum_{(x,y)\in \mathcal{X}\times\mathcal{Y}} \frac{1}{t^2}\gamma_{x,y}(t)\langle A^*\xi^*-A^*\xi(t)+A^*\xi(t)-c \vert e_{x,y} \rangle^2 + \frac{1}{t^3}\| \xi^* - \xi(t)\|^2_{D^2\mathrm{F}^*(-\xi(t))} \\
    &\leq \sum_{(x,y)\notin I_0} \frac{1}{t^2}\gamma_{x,y}(t)\langle A^*\xi^*-c \vert e_{x,y} \rangle^2 + \frac{1}{t^3}\lambda_{\max}(t)\| \xi^*  -  \xi(t)\|^2 \\
   &\lesssim \frac{1}{t^2}\max\limits_{(x,y) \notin I_0} \gamma_{x,y}(t) + \frac{1}{t^5},
\end{align*}
where the last inequality is obtained using that \(\sum_{(x,y)\notin I_0} \langle A^*\xi^* \!-\! c \vert e_{x,y} \rangle^2\) and \(\lambda_{\max}(t)\), the largest eigenvalue of \( D^2\mathrm{F}^*\!(-\xi(t))\), are bounded quantities. From this, for any \((x,y) \in \mathcal{X}\!\times\!\mathcal{Y}\), one can obtain 
\[ \gamma_{x,y}(t)\langle  A^*\dot{\xi}(t) + \frac{\log \gamma(t)}{t^2} \vert  e_{x,y} \rangle^2 \lesssim \frac{1}{t^2}\max_{(x,y)\notin I_0} \gamma_{x,y}(t) + \frac{1}{t^5}.\] 
Moreover, we compute
\begin{align*}
\frac{\textit{d}}{\textit{d}t}\left(\frac{1}{t}\log \gamma(t)\right) &=\! -\frac{1}{t^2}\log \gamma(t) + \frac{1}{t}\frac{\dot{\gamma}(t)}{\gamma(t)} \\
&=\! - \frac{1}{t}( A^*\xi(t)-c)  \!+\!\frac{1}{t}\frac{(tA\dot{\xi}(t) + A\xi(t)-c)\gamma(t)}{\gamma(t)}\\
&=\! A^*\dot{\xi}(t),
\end{align*}
and in particular \( A^*\dot{\xi}(t) + \frac{\log\gamma(t)}{t^2}=\frac{1}{t}\frac{\dot{\gamma}(t)}{\gamma(t)}\). Thus, we have
\begin{align*}
    \gamma_{x,y}(t)\left(\frac{1}{t}\frac{\dot{\gamma}_{x,y}(t)}{\gamma_{x,y}(t)}\right)^2 &\lesssim \frac{1}{t^2}\max_{(x,y)\notin I_0} \gamma_{x,y}(t) + \frac{1}{t^5}\\
    \Longleftrightarrow \quad \quad \quad \quad \quad \frac{\dot{\gamma}_{x,y}(t)^2}{\gamma_{x,y}(t)} &\lesssim \max_{(x,y)\notin I_0}\gamma_{x,y}(t) + \frac{1}{t^3}  \\
    \implies \:\quad \quad \quad \quad \quad  \dot{\gamma}_{x,y}(t)^2 &\lesssim \max_{(x,y)\notin I_0}\gamma_{x,y}(t) + \frac{1}{t^3},
\end{align*}
where the last inequality uses that \(t\mapsto \gamma(t)\) is bounded when \(t\) is sufficiently large. Since \(d(t)\) is bounded for
\(t\) large enough and recalling that the transport coupling can be expressed in terms of the dual variable as 
\[\gamma(t)= e^{t(A^*\xi(t)  - c)} = e^{t A^*(\xi(t)-\xi^*)- t\kappa} = e^{ A^*d(t) - t\kappa},\]
it follows that there exists \(C>0\) such that
\[\forall (x,y) \notin I_0, \quad \gamma_{x,y}(t) \leq Ce^{-t\kappa^*}, \]
with \(\kappa^*=\min_{(x,y)\notin I_0} \kappa_{x,y}\).
It allows to conclude that for any \((x,y) \notin I_0\), \(\gamma_{x,y}(t)\) converges exponentially fast towards \(0\). Consequently, we obtain the asymptotic estimate
\[\abs{\dot{\gamma}_{x,y}(t)} \lesssim t^{-\frac{3}{2}}. \]
\noindent Finally, we have
\begin{align*}
\| \gamma^* - \gamma(t) \| &\leq \int_{t}^{+\infty} \|\dot{\gamma}(\omega) \| \dd\omega \lesssim \int_{t}^{+\infty} \frac{1}{\omega^\frac{3}{2}} \,\dd\omega \lesssim \frac{1}{\sqrt{t}}.
\end{align*}
which allows to obtain 
\[ \| \gamma(t) - \gamma^* \| \lesssim \frac{1}{\sqrt{t}}.\qedhere\]
\end{proof}


\section{Numerical experiments}\label{sec:numerics}

We consider two finite sets \(\mathcal{X}, \mathcal{Y} \subset \R^d\) with cardinality \(N\) and \(M\), respectively and  divergences which take the form \(\mathrm{F}(\cdot) = \mathrm{D}_\phi(\cdot \vert q)\) where \(q\) represents the marginals and \(\phi\) is an entropy function. \\

For each divergence \(\mathrm{F}\) considered in this section, we provide numerical illustrations of the expected upper bounds on the convergence rates for both the primal and dual problem.
We consider two different datasets. 
The first dataset consists of two point clouds \(\mathcal{X}\) and \(\mathcal{Y}\) with uniform weights. Notably, \(\mathcal{Y}\) contains outliers—points that are significantly distant from the others. The measures supported on these sets have different total masses, with \(|\mu| = 13\) and \(|\nu| = 15\).

The second dataset is composed of two discretized Gaussian measures on a regular 1-dimensional grid, also with unequal masses: \(|\mu| = 11\) and \(|\nu| = 10\). 

The convergence rate plots are presented on a logarithmic scale and are compared to their theoretically expected rates.
