\paragraph{Inventory and Cash Dynamics}
Inventory and cash evolve as:
\begin{align}
dq(t) &= -\nu(t) dt, \quad q(0) = X_0, \quad q(T) \geq 0, \label{eq:inventory} \\
dC(t) &= \nu(t) \left( S(t) - \epsilon \nu(t)^\beta \right) dt. \label{eq:cash}
\end{align}



\section{Expert Models for Optimal Execution}
\label{appendix:expertmodel}

\subsection{Almgren-Chriss model}
Consider a financial asset whose mid-price $S_t$ evolves as
\begin{equation}
\mathrm{d}S_t = \sigma\,\mathrm{d}W_t - \gamma\,v_t\,\mathrm{d}t,
\end{equation}
where $\sigma>0$ is the volatility, $\gamma>0$ is the permanent impact coefficient, and $v_t\ge0$ is the trading rate (sell rate). The inventory dynamics satisfy
\begin{equation}
\mathrm{d}q_t = -v_t\,\mathrm{d}t,\quad q_0=Q_0.
\end{equation}
Trades incur a temporary impact cost $\eta v_t^2$ per unit time and a permanent impact cost $\gamma q_t v_t$. Remaining inventory $q_T$ is settled at price $S_T$. We minimize the expected total cost
\begin{equation}
J(v)=\mathbb{E}\Bigl[\int_0^T(\eta v_t^2+\gamma q_t v_t)\,\mathrm{d}t - q_T S_T\Bigr].
\end{equation}

\paragraph{HJB Formulation}

Define the value function
\begin{equation}
V(t,S,q)=\inf_{v_{[t,T]}}\mathbb{E}\Bigl[\int_t^T(\eta v_s^2+\gamma q_s v_s)\mathrm{d}s - q_T S_T \;\Big|\;S_t=S,q_t=q\Bigr],
\end{equation}
with terminal condition $V(T,S,q)=-qS$. The HJB equation reads
\begin{equation}
0 = V_t + \frac{1}{2}\sigma^2 V_{SS} + \inf_{v\ge0}\{ -vV_q - \gamma v V_S + \eta v^2 + \gamma q v\}.
\end{equation}
The first-order condition gives
\begin{equation}
v^*=\frac{V_q+\gamma V_S-\gamma q}{2\eta}.
\end{equation}
Substitution yields the PDE
\begin{equation}
0=V_t + \frac{1}{2}\sigma^2 V_{SS} - \frac{(V_q+\gamma V_S-\gamma q)^2}{4\eta}.
\end{equation}

\paragraph{Quadratic Ansatz and ODE System} 

We postulate a quadratic form
\begin{equation}
V(t,S,q)=A(t)q^2+B(t)S q + C(t)S^2 + D(t).
\end{equation}
Matching coefficients in the HJB PDE leads to the following Riccati ODEs:
\begin{align}
A'(t)&=\frac{[2A(t)+\gamma B(t)-\gamma]^2}{4\eta},\quad A(T)=0,\\
B'(t)&=\frac{[2A(t)+\gamma B(t)-\gamma][B(t)+2\gamma C(t)]}{2\eta},\quad B(T)=-1,\\
C'(t)+\sigma^2C(t)&=\frac{[B(t)+2\gamma C(t)]^2}{4\eta},\quad C(T)=0,\\
D'(t)&+\sigma^2 C(t)=0,\quad D(T)=0.
\end{align}

\paragraph{Closed-Form Solution}
Setting $\Delta=\gamma^2+4\eta$, the solutions are
\begin{align}
A(t)&=\frac{\sqrt{\Delta}-\gamma}{4\eta}\coth\bigl(\tfrac{\sqrt{\Delta}}{2\eta}(T-t)\bigr)-\frac{\gamma}{2},\\
B(t)&=-\frac{\sqrt{\Delta}}{\sqrt{\Delta}\cosh(\sqrt{\Delta}(T-t))-\gamma\sinh(\sqrt{\Delta}(T-t))},\\
C(t)&=\frac{\eta\sinh(\sqrt{\Delta}(T-t))}{4(\sqrt{\Delta}\cosh(\sqrt{\Delta}(T-t))-\gamma\sinh(\sqrt{\Delta}(T-t))) }.
\end{align}
Thus the state-feedback control is
\begin{equation}
v^*(t,S_t,q_t)=\alpha_1(t)q_t+\alpha_2(t)S_t,
\end{equation}
with
\begin{equation}
\alpha_1(t)=\frac{2A(t)+\gamma B(t)-\gamma}{2\eta},\quad
\alpha_2(t)=\frac{B(t)+2\gamma C(t)}{2\eta}.
\end{equation}




\subsection{Expert Trajectory Generation via Proximal Policy Optimization}
\label{sec:ppo_expert_data_collection}

To generate diverse and robust expert demonstrations for training the FlowOE imitation learning framework, we employ Proximal Policy Optimization (PPO) agents \citep{schulman2017proximal}. This approach proves particularly valuable in scenarios where analytical solutions are unavailable or when greater adaptability is required. The PPO agents serve as sophisticated experts that are specifically trained for optimal execution in a simulated Heston market environment.



We train individual PPO agents that are tailored to distinct market scenarios. These scenarios are categorized by volatility levels (High/Low) and market impact characteristics (High/Low), resulting in four distinct configurations: HH, HL, LH, and LL . Each PPO agent is trained to minimize an execution cost function, which is equivalently expressed as maximizing cumulative rewards that penalize execution costs, price variance risks, and residual inventory at the terminal time $T$.

The PPO agents operate within a custom Gym-compatible environment \texttt{(`OptimalExecutionHestonEnv')} \citep{brockman2016openaigym} that simulates Heston volatility dynamics, nonlinear temporary impact, and linear permanent impact. 

At discrete time points $t_k$, the agents observe the following state variables:
\begin{itemize}
\item Remaining time until termination: $T - t_k$
\item Current inventory position: $q(t_k)$
\item Mid-price of the asset: $S(t_k)$
\item Current volatility level: $V(t_k)$
\end{itemize}

These observations are normalized prior to input into the PPO policy network, which is typically implemented as a multilayer perceptron. The network outputs the parameters (mean and standard deviation) of Gaussian action distributions. The actions represent fractions of inventory to be liquidated at each time step $\Delta t$, which are subsequently converted into discrete share quantities. A critical constraint is enforced to ensure complete liquidation of all remaining inventory in the final step, thereby guaranteeing zero terminal inventory.

Training continues until performance convergence is achieved for each scenario, at which point the optimal models are saved for subsequent use in trajectory generation.

\subsection{Systematic Generation of Expert Trajectories}

Following the training phase, the PPO expert models generate extensive state-action trajectories across systematically varied market parameters. This process enhances the comprehensiveness of the dataset and ensures robust coverage of the parameter space. The data collection methodology comprises four key stages:

\textbf{Parameter Grid Construction.} We define a comprehensive parameter grid that systematically varies the initial volatility ($\sqrt{V_0}$), volatility of variance ($\xi$), market impact nonlinearity ($\beta$), and other relevant Heston model parameters including the drift ($\mu$), mean reversion rate ($\kappa$), long-term variance ($\theta$), correlation coefficient ($\rho$), and impact parameters ($\eta$, $\epsilon$).

\textbf{Scenario-Specific Model Selection.} Each parameter combination is mapped to one of the four scenarios (HH, HL, LH, LL) based on its volatility and market impact characteristics. The appropriate pre-trained PPO model is then selected, with fallback options implemented when direct parameter matches are unavailable.

\textbf{Episode Simulation.} For each parameter set, we simulate multiple episodes (typically 100) using unique random seeds to ensure trajectory diversity. Within each episode, states are systematically recorded and input to the PPO networks, actions are computed and executed, and rewards are tracked until episode termination at time $T$.

\textbf{Data Aggregation and Storage.} The collected trajectories encompass states, actions, rewards, episode termination indicators, and comprehensive metadata including implementation shortfall, final inventory positions, and scenario labels. The data is efficiently stored using Zarr archives with Blosc compression to optimize storage requirements and access speed.

This systematic approach to PPO-based trajectory generation significantly enhances the FlowOE training corpus, thereby promoting robust imitation learning performance across diverse market scenarios and parameter regimes.




\subsection{State-Dependent Trading Strategy}

Due to the complexity of solving the HJB equation analytically, we implement a state-dependent trading strategy that captures the key features of the optimal solution:

\begin{equation}
\nu_t^* = \Phi(t, X_t, S_t, V_t) \cdot \Psi(V_t, \mathbb{E}[V_T|V_t]) \cdot \Omega(T-t)
\end{equation}

where:
$\Phi(t, x, s, v) = \left(\frac{x}{T-t}\right)^{\frac{1}{1+\beta}}$ is the base trading rate accounting for non-linear impact
$\Psi(v, \mathbb{E}[v_T]) = \left(\frac{\mathbb{E}[V_T|V_t]}{V_t}\right)^{0.5}$ is the volatility adjustment factor
$\Omega(\tau) = \min(2, \frac{1}{\tau})$ is the urgency factor as time to maturity decreases


The expected future variance is computed using the mean-reverting property:

\begin{equation}
\mathbb{E}[V_T | V_t] = \theta + (V_t - \theta)e^{-\kappa(T-t)}
\end{equation}





We define the problem mathematically and present four expert strategies: TWAP, VWAP, an approximated Almgren-Chriss strategy (AC-Approx), and a Heston-Optimal strategy tailored to the non-linear impact and stochastic volatility setting. The mathematical formulations are derived, and their performance is assessed through simulations.



\subsection{Discretization}
In discrete time, for step $k = 0, 1, \dots, N-1$, the trader sells $x_k = \nu_k \Delta t$ shares. The price and variance are updated using a Milstein scheme for the variance to ensure non-negativity:
\begin{align}
    \log S(t_{k+1}) &= \log S(t_k) + \left( \mu - \frac{1}{2} V(t_k) - \eta \nu_k \right) \Delta t + \sqrt{V(t_k)} \sqrt{\Delta t} Z_{S,k}, \\
    V(t_{k+1}) &= V(t_k) + \kappa \left( \theta - V(t_k) \right) \Delta t + \xi \sqrt{V(t_k)} \sqrt{\Delta t} Z_{v,k} + \frac{\xi^2}{4} \Delta t \left( Z_{v,k}^2 - 1 \right),
\end{align}
where $Z_{S,k}$ and $Z_{v,k}$ are correlated standard normal random variables with correlation $\rho$. The execution price is:
\begin{equation}
    \tilde{S}_k = S(t_k) - \epsilon \nu_k^\beta.
\end{equation}
Inventory and cash updates are:
\begin{align}
    q(t_{k+1}) &= q(t_k) - x_k, \\
    C(t_{k+1}) &= C(t_k) + x_k \tilde{S}_k.
\end{align}





\section{MDP Formulation of Optimal Execution}

We formulate optimal execution as an MDP with tuple $(\mathcal{S}, \mathcal{A}, \mathcal{R}, \mathcal{P}, \gamma)$.

\textbf{State Space $\mathcal{S}$:} At time $t$, the state is $s_t = (\tau_t, q_t, S_t, V_t)$ where:
\begin{itemize}
\item $\tau_t = T - t$: remaining time (normalized by total time $T$)
\item $q_t$: current inventory (normalized by initial inventory $X_0$)
\item $S_t$: mid-price (normalized by initial price $S_0$)
\item $V_t$: variance (normalized by initial variance $V_0$)
\end{itemize}

\textbf{Action Space $\mathcal{A}$:} The action $a_t \in [0, 1]$ represents the fraction of remaining inventory to trade at time $t$.


\textbf{Reward ($\mathcal{R}$):} The agent aims to maximize cumulative rewards. The immediate reward $r_k$ at step $k$ can be defined as the cash received from selling $n_k$ shares, penalized by a risk term. A common objective in Optimal Execution (OE) is to minimize the Implementation Shortfall (IS) and its variance. We define the reward to align with this objective:
    \begin{equation}
        r_k(s_k, a_k, s_{k+1}) = n_k \tilde{S}_k - \lambda \cdot \text{RiskTerm}_k
        \label{eq:reward_function}
    \end{equation}
    where:
    \begin{itemize}
        \item $n_k$ is the number of shares sold in step $k$.
        \item $\tilde{S}_k$ is the actual execution price per share at step $k$.
        \item $\lambda$ is a risk aversion coefficient.
        \item $\text{RiskTerm}_k$ is a term quantifying the risk incurred during step $k$, which could be related to price volatility or deviation from a target execution schedule.
    \end{itemize}
    A significant negative reward (penalty) is applied at the terminal step if any shares $q_N$ remain unliquidated ($q_N > 0$). The overall objective for the agent is to maximize the sum of discounted rewards $\sum_{k=0}^{N-1} \gamma^k r_k$. This reward structure encourages the agent to maximize execution proceeds while managing risk, effectively aiming to minimize an objective similar to the Almgren-Chriss cost function, i.e., $\mathbb{E}[\text{IS}] + \lambda \text{Var}[\text{IS}]$.
where $\text{trading\_cost}_t = \varepsilon |\nu_t|^\beta \cdot \text{shares\_traded}_t$ and $\lambda$ is the terminal inventory penalty.

\textbf{Transition Dynamics $\mathcal{P}$:} The market follows Heston stochastic volatility dynamics:
\begin{align}
dS_t &= \mu S_t dt + \sqrt{V_t} S_t dW_t^S - \eta \nu_t S_t dt \\
dV_t &= \kappa(\theta - V_t)dt + \xi\sqrt{V_t} dW_t^V
\end{align}
where $\nu_t$ is the trading rate, $\eta$ is the permanent impact coefficient, and $\langle dW_t^S, dW_t^V \rangle = \rho dt$.

The inventory evolves as: $q_{t+1} = q_t - a_t \cdot q_t$

\textbf{Discount Factor:} $\gamma = 0.99$

\subsection{Gymnasium Environment Implementation}

We implement the execution environment following OpenAI Gymnasium standards:





\begin{algorithm}[H]
\caption{MDP Approximation of \texttt{OptimalExecutionHestonEnv}}
\label{alg:heston-mdp}
\begin{algorithmic}[1]
\REQUIRE Environment parameters $(T,N,X_0,S_0,V_0,\mu,\kappa,\theta,\xi,\rho,\eta,\epsilon,\beta,\lambda,\phi)$ where $\lambda$: risk-aversion; $\phi$: terminal-inventory penalty
\STATE $\Delta t \gets T/N$

\STATE \textbf{Function Reset():}
\STATE \hspace{1em} $t_0\gets 0$, $q_0\gets X_0$, $S_0\gets S_0$, $V_0\gets V_0$, $C_0\gets 0$
\STATE \hspace{1em} \textbf{return} $\mathbf{s}_0 = f_{\text{norm}}(t_0,q_0,S_0,V_0)$

\STATE \textbf{Function Step}($a_t \in [0,1]$): \COMMENT{$a_t$ = fraction of remaining inventory to trade}
\IF{$t = T-\Delta t$} 
\STATE $a_t \gets 1$ \COMMENT{force full liquidation in the last step}
\ENDIF
\STATE $\text{shares} \gets a_t \cdot q_t$
\STATE $\nu_t \gets \text{shares}/\Delta t$ \COMMENT{trading rate}
\STATE $\text{temp} \gets \epsilon \cdot \nu_t^{\beta}$ \COMMENT{non-linear temporary impact}
\STATE $\text{perm} \gets \eta \cdot \nu_t$ \COMMENT{permanent impact per unit time}
\STATE $P_t^{\text{exec}} \gets S_t-\text{temp}-0.5\eta \cdot \text{shares}$
\STATE $\text{cost}_t \gets \text{temp} \cdot \text{shares}+0.5\eta \cdot \text{shares}^2$
\STATE $C_{t+\Delta t} \gets C_t + P_t^{\text{exec}} \times \text{shares}$
\STATE $q_{t+\Delta t} \gets q_t-\text{shares}$ \COMMENT{update inventory}

\STATE Draw $Z_1,Z_2\sim\mathcal{N}(0,1)$
\STATE $W_S\gets Z_1$, $W_V\gets \rho Z_1+\sqrt{1-\rho^2} \cdot Z_2$ \COMMENT{correlated Brownian motions}
\STATE $dV \gets \kappa(\theta-V_t)\Delta t + \xi\sqrt{V_t}\sqrt{\Delta t} \cdot W_V + \frac{1}{4}\xi^2\Delta t \cdot (W_V^2-1)$
\STATE $V_{t+\Delta t}\gets\max(0,V_t+dV)$
\STATE $d\ln S\gets(\mu-\frac{1}{2} V_t)\Delta t+\sqrt{V_t}\sqrt{\Delta t} \cdot W_S$
\STATE $S_{t+\Delta t}\gets S_t \cdot e^{d\ln S}-\text{perm}$

\STATE $t \gets t+\Delta t$
\STATE $\text{done}\gets(t\ge T) \lor (q_{t+\Delta t}\le10^{-6})$
\STATE $\text{hold}\gets-\lambda \cdot q_{t+\Delta t}^{2} \cdot V_{t+\Delta t} \cdot \Delta t$
\STATE $\text{reward}\gets -\frac{\text{cost}_t}{X_0S_0}\times100 + \text{hold}$
\IF{$\text{done} \land q_{t+\Delta t}>0$} 
\STATE $\text{reward}\gets\text{reward}-\phi \cdot (q_{t+\Delta t}/X_0)$ \COMMENT{penalise leftover inventory}
\ENDIF
\STATE \textbf{return} $f_{\text{norm}}(t,q_{t+\Delta t},S_{t+\Delta t},V_{t+\Delta t})$, $\text{reward}$, $\text{done}$, $\text{info}$

\end{algorithmic}
\end{algorithm}







