\title[Exceptional points and defective resonances]{Exceptional points and defective resonances in an acoustic scattering system with sound-hard obstacles}


\author[K. Matsushima]{Kei Matsushima\,\orcidlink{0000-0002-0352-8770}}
\address{\parbox{\linewidth}{Kei Matsushima\\
  Graduate School of Engineering, University of Tokyo, 2–11–16 Yayoi, Bunkyo–ku, Tokyo 113–8656, Japan, \href{http://orcid.org/0000-0002-0352-8770}{orcid.org/0000-0002-0352-8770}}.}
