\subsection{From Mechanism to Games}
Any mechanism $\mathcal{M}$ induces a {\em finite-action game}, where each producer $i \in [n]$ behaves strategically and selects her bid $b_i$ among the bid values in $[M]$ so as to maximize her {\em individual revenue} $U_i^\mathcal{M}(\vecb) :=  (p_i(\vecb) - c_i )\cdot x_i(\vecb)$.

\begin{definition}[mixed Nash equilibrium]
\label{def:mne}
Given a mechanism $\mathcal{M}$, a mixed Nash equilibrium is a collection of independent probability distributions $\mathbf{\sigma}:= (\sigma_1,\ldots,\sigma_n)$ over the possible bid values in $[M]$, such that for each agent $i \in [n]$,
\begin{align*}
    \Ex_{\vecb \sim \sigma}[U_i^\mathcal{M}(\vecb)] \geq \max_{b'_i\in [M]} \Ex_{\vecb_{-i} \sim \sigma_{-i}}[U_i^\mathcal{M}(b'_i,\vecb_{-i})].
\end{align*}
Given an instance $\mathcal{I}:=\{(s_i,c_i)\}_{i \in [n]}$ of an energy market, we denote by $\mathrm{MNE}(\mathcal{M},\mathcal{I})$ the set of all mixed Nash equilibria of mechanism $\mathcal{M}$ for instance $\mathcal{I}$.
\end{definition}
Since we consider finite games, any mechanism $\mathcal{M}$ admits at least one mixed Nash equilibrium. 

\begin{definition}[pure Nash equilibrium]
\label{def:pne}
Given a mechanism $\mathcal{M}$, a pure Nash equilibrium is a bidding profile $\vecb$ such that for each agent $i \in [n]$,
\begin{align*}
    U_i^\mathcal{M}(\vecb) \geq \max_{b'_i\in [M]} U_i^\mathcal{M}(b'_i,\vecb_{-i}).
\end{align*}
\end{definition}
It is well-known that VCG has the truthful bid profile $(c_1, c_2, ..., c_n)$ as pure Nash equilibrium.

We conclude this section by defining two different ways of comparing mechanisms in terms of the unit price at their mixed Nash equilibria.
\begin{definition}[dominance relations between mechanisms]\label{d:domination}
A mechanism $\mathcal{M}$ {\em strongly dominates} mechanism $\mathcal{M}'$ if and only if
\[ \max_{\sigma \in \mathrm{MNE}(\mathcal{M},\mathcal{I}) } p^{\sss\mathrm{unit}}_{\mathcal{M}}(\sigma) \leq  \min_{\sigma \in \mathrm{MNE}(\mathcal{M}',\mathcal{I}) } p^{\sss\mathrm{unit}}_{\mathcal{M}'}(\sigma) ~~\text{for every instance }\mathcal{I}.  \]
A mechanism $\mathcal{M}$ {\em weakly dominates} mechanism $\mathcal{M}'$ if and only if
\[ \max_{\sigma \in \mathrm{MNE}(\mathcal{M},\mathcal{I}) } p^{\sss\mathrm{unit}}_{\mathcal{M}}(\sigma) \leq  \max_{\sigma \in \mathrm{MNE}(\mathcal{M}',\mathcal{I}) } p^{\sss\mathrm{unit}}_{\mathcal{M}'}(\sigma) ~~\text{for every instance }\mathcal{I}.  \]
\end{definition}

\noindent Less formally, when mechanism $\mathcal{M}$ strongly dominates mechanism $\mathcal{M}'$, then in every instance, the unit price at any mixed NE of $\mathcal{M}$ is at most as high as the unit price of any mixed NE of $\mathcal{M}'$. In case of weak dominance, there exists a mixed NE of $\mathcal{M}'$ that has at least as high unit price as any mixed NE of $\mathcal{M}$.


\section{Overview of Technical Results}
Our first main result establishes that PC is not strictly dominated by any other mechanism. However, we show that this also holds for PB and VCG.

\begin{restatable}{theorem}{Tnodominating}
\label{t:1}
There is no mechanism strictly dominating Pay-as-Clear, Pay-as-Bid, or VCG.
\end{restatable}

Despite the fact that none among PB, PC, and VCG can be strictly dominated by any other mechanism, there are still interesting comparisons among them. Our second main result establishes that PB weakly dominates PC. 

\begin{theorem}\label{t:2}
Pay-as-Bid weakly dominates Pay-as-Clear. At the same time, Pay-as-Clear does not weakly dominate Pay-as-Bid.
\end{theorem}
Theorem~\ref{t:2} establishes that in every energy market, the unit price of any mixed NE of PB is always lower than the unit price of the worst-case mixed NE of PC. At the same time, Theorem~\ref{t:2} excludes the opposite direction.


\begin{remark}
We remark that in all non-degenerate energy markets, the unit price of the worst-case NE of PC is actually {\em strictly smaller} than the unit price the worst-case NE of PB.
\end{remark}

%\begin{remark}
% We remark that it could have been the case that at for any energy market $\mathcal{I}$, the unit price of the worst-case NE of PB coincides in with the unit price of the worst-case NE of PC. However Theorem~\ref{t:2} excludes this case. In fact as our results reveal that in degenerate instances $\mathcal{I}$, the unit price worst-case NE of PC is strictly smaller than the unit price the worst-case NE of PB.
%\end{remark}


\noindent Theorem~\ref{t:2} is directly implied by Theorems~\ref{t:3} and~\ref{t:PB}, which characterize the unit prices of mixed NE for PC and PB, respectively. Both Theorem \ref{t:3} and Theorem \ref{t:PB} are based on instance-dependent parameters and are presented in the next section.

Interestingly enough, VCG does not weakly dominate PC and can in fact lead to a considerably higher unit price. This is formally established in Theorem~\ref{t:VCG}.

\begin{restatable}{theorem}{TVCG}
\label{t:VCG}
VCG does not weakly dominate Pay-as-Clear. There is an instance with $n$ agents where the unit price of VCG is $\Theta(\log n)$ times the unit price of the worst mixed NE of Pay-as-Clear. 
\end{restatable}




\subsection{Pay-as-Clear vs Pay-as-Bid}\label{s:PB-PC}
We now introduce some necessary notation for the comparison of PC and PB.

\begin{definition}
    \label{def:H}
    The best response of producer $i \in [n]$ in Pay-as-Clear, with respect to the bidding profile $b_{-i}$, is defined as
    \begin{align*}
        \mathcal{BR}(b_{-i}):= \begin{cases}\argmax_{b_i \in [M]} U_i(b_i,b_{-i}) & \text{if } \max_{b_i \in [M]} U_i(b_i,b_{-i})>0\\
        c_i& \text{if }\max_{b_i \in [M]} U_i(b_i,b_{-i}) = 0
        \end{cases}
    \end{align*}
\noindent We also denote by $\high{b}_i$ the highest bid among the best responses of agent $i \in [n]$ in case any other agent $j \neq i$ bids either $c_j$ or $c_j+1$,
    \begin{align*}
        \high{b}_i := \max_{\mathbf{d}_{-i}\in\set{0,1}^{n-1}}\max
    \{b_i \in [M]~:~ b_i \in \mathcal{BR}(\mathbf{c}_{-i}+\mathbf{d}_{-i})\}.
    \end{align*}
Finally, we denote by $\low{b}_i:= \lceil c_i + \max_{b'_i\in[M]}U_i(b'_i,\mathbf{c}_{-i}) / s_i\rceil$ the smallest possible price giving agent $i \in [n]$ at least utility $\max_{b'_i\in[M]}U_i(b'_i,\mathbf{c}_{-i})$ when she sells her maximum of $s_i$ energy units.
\end{definition}

Before proceeding, we provide an example clarifying the crucial notions of $\high{b}_i$ and $\low{b}_i$. 

\begin{example} Consider an energy market with $M=6$ and $n=3$ producers with  supplies $s_1=3/4, s_2=3/4, s_3=1/10$ and costs $c_1=0, c_2=1, c_3=4$. Notice that the best response always locates on the cost of some other agent or $M$. When other agents bid truthfully, agent $1$'s best response is $4$ since bidding $4$ provides a utility of $1$, which is higher than the utility from bidding $1$, which is $0.75$, or bidding $6$, which is $0.9$. And the utility given by bidding $4$ while other agents bid truthfully gives $\low{b}_1=\lceil0+1/0.75\rceil=2$. To reveal the final $\high{b}_1$, we need to consider further if agent $2$, agent $3$, or both, bid their cost plus one. When agent $2$ ever bids $c_2+1=2$, the best response of agent $1$ is $2$. And if only agent $3$ bids $c_3+1=5$, the best response is $5$. We conclude $\high{b}_1=5$ by taking the maximum among all the above best responses. We can also perform similar calculations for agent $2$, obtaining $\high{b}_2=6$ and $\low{b}_2=2$. For agent $3$, it always yields a utility of $0$ when other agents bid their cost or the cost plus one. Thus, $\high{b}_3=4$ by definition, and $\low{b}_3=4$.
\end{example}

The quantities $\high{b}_i$ and $\low{b}_i$ can be used to establish lower and upper bounds on the unit price of mixed NE of PC and PB. Theorem~\ref{t:3} establishes such a lower bound for PC. 

\begin{theorem}\label{t:3}
For any energy market $\mathcal{I}$, Pas-as-Clear admits at least one pure NE with unit price at least $\max_{i\preceq_\mathbf{c} \tau(\mathbf{c})} \high{b}_i$. Moreover, the unit price of any mixed NE of Pay-as-Clear is at least $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_i$.
\end{theorem}

%\noindent Theorem~\ref{t:3} not only establishes a lower bound on the worst-case mixed NE of PC but also establishes the existence of pure Nash Equilibrium. The proof of Theorem~\ref{t:3} is based on establishing that if all producers $i \in [n]$ bid \textit{approximately truthfully} ($c_j$ or $c_j + 1$) apart from agent $i^\star := \argmax_{i\preceq_\mathbf{c} \tau(\mathbf{c})} \high{b}_i$ that bids $b_{i^\star}^H \in [M]$, then the resulting pure bidding profile is a pure Nash Equilibrium.

Theorem~\ref{t:PB} establishes a unit price upper bound at the worst-case mixed Nash equilibrium for PB.
\begin{theorem}\label{t:PB}
    Any mixed NE of Pay-as-Bid is supported in $[\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_{i}-1, \max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_{i}]$.
\end{theorem}

It should now be clear how Theorem~\ref{t:2} is directly implied by Theorem~\ref{t:3} and Theorem~\ref{t:PB}. Specifically, Theorem~\ref{t:PB} establishes that the support of any mixed NE of PB lies between the unit price of the best and worst mixed NE of PC. In Theorem~\ref{thm:UB-PB-better}, we establish that under some mild assumption excluding degenerate instances, the worst-case NE of PB is strictly better than the worst-case NE of PC.

\begin{restatable}{theorem}{TUBPBbetter}
    \label{thm:UB-PB-better}
    The unit price given by the worst-case mixed NE of Pay-as-Bid is strictly smaller than $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_i$ in a large family of instances.
\end{restatable}

