\begin{lemma}\label{l:main}
Let the sequence $\mathcal{S}' = \sigma^1,\sigma^2, \ldots$ then for any mixed NE $\sigma^k = (\sigma^k_A,\sigma^k_B)$ we can construct a strategy pair $\hat{\sigma}^k = (\hat{\sigma}^k_A,\hat{\sigma}^k_B)$ such that $i)$ $\hat{\sigma}^k$ is an $(1-M\cdot\sigma^k_A(0))$-approximate mixed NE $ii)$ the payment of $\hat{\sigma}^k$ is greater than $\mu_{M} > 0$ where is a mechanism-dependent constant. 
\end{lemma}
Before presenting the proof of Lemma~\ref{l:main}, we complete the proof of Theorem~\ref{t:1}. Lemma~\ref{l:main} establishes that there exists a sequence $\hat{\sigma}^1,\hat{\sigma}^2,\ldots,\hat{\sigma}^k,\ldots$ where each $\hat{\sigma}^k = (\hat{\sigma}^k_B, \hat{\sigma}^k_B)$ a $(1-M\cdot\sigma_A^k(0))$-approximate mixed NE and admits payment at least $\mu_G > 0$. Since we are in compact space there exists a convergent subsequence, $\lim_{k \rightarrow \infty} \sigma_k = \sigma^\star$. Since $\lim_{k \rightarrow \infty} \epsilon_k = 0$ and $\lim_{k \rightarrow \infty} \sigma_A^k(0) = 1$, we are ensured that $\sigma^\star$ is a mixed NE while admits payment at least $\mu_G > 0$.

\smallskip
\smallskip

%\begin{proof}[Proof of Lemma~\ref{l:main}]
\paragraph{Proof of Lemma~\ref{l:main}.}
\noindent Let the mixed NE $\sigma^k = (\sigma^k_A,\sigma^k_B)$. We first consider the case where agent $A$ sells a positive amount of energy. Since $A$ has marginal cost $\epsilon_k > 0$, agent $A$ needs to receive a positive payment (otherwise its utility is negative while $A$ can make it non-negative by bidding $1$).
\smallskip
\smallskip

Since the overall payment of $A$ must be positive and $0 \in \mathrm{support}(\sigma_A^k)$, the expected payment of $A$ when bidding $0$ must be positive,
\[ \sum_{j \in [M]} \sigma_B^k(j) \cdot x_A(0,j)\cdot p_A(0,j) >0. \]
As a result, the set $C_k := \{j \in [M]~:~\sigma^k_B(j) > 0 \text{ and } x_A(0,j)\cdot p_A(0,j) > 0\}$ is not empty. Now consider the probability distribution $\hat{\sigma}^k_B $ defined as,
\[\hat{\sigma}^k_B(j)  := \begin{cases}
      \frac{\sigma^k_B(j)}{1 -  \sum_{\ell \notin C_k}\sigma^k_B(\ell)}, &\text{if }j \in C_k, \\
      0, &\text{otherwise.}\\
\end{cases}
\]
We are going to show that $\hat{\sigma}_k := (e_0,\hat{\sigma}_B^k)$ 
where $e_0 = (1,0,\ldots,0)$ is an $\epsilon_k$-approximate mixed NE while it admits a positive payment.
Since $0 \in \mathrm{support}(\sigma_A^k)$ we are ensured that 
\[ \sum_{j \in [M]} \sigma_B^k(j) \cdot x_A(0,j)\cdot (p_A(0,j) - \epsilon_k) \geq \sum_{j \in [M]} \sigma_B^k(j) \cdot x_A(i,j)\cdot (p_A(i,j) - \epsilon_k)~~~~\text{for all bids } i \in [M]\]
By the definition of $j \in C_k$ we get that 
\[\sum_{j \notin C_k} \sigma_B^k(j) \cdot x_A(0,j)\cdot (p_A(0,j) - \epsilon_k) \leq 0\]
At the same time, for all bids $i \geq 1$
\[\sum_{j \notin C_k} \sigma_B^k(j) \cdot x_A(i,j)\cdot (p_A(i,j) - \epsilon_k) \geq 0\]
due to the fact that $p_A(i,j)  \geq 1$. Combining all the latter we get that for all bids $i \geq 1$,
\begin{eqnarray*}
\sum_{j \in C_k} \sigma_B^k(j) \cdot x_A(0,j)\cdot (p_A(0,j) - \epsilon_k) &\geq& \sum_{j \in M} \sigma_B^k(j) \cdot x_A(0,j)\cdot (p_A(0,j) - \epsilon_k)\\
&\geq& \sum_{j \in M} \sigma_B^k(j) \cdot x_A(i,j)\cdot (p_A(i,j) - \epsilon_k)\\
&\geq& \sum_{j \in C_k} \sigma_B^k(j) \cdot x_A(i,j)\cdot (p_A(i,j) - \epsilon_k)
\end{eqnarray*}
By dividing the latter inequality with $1/(1 - \sum_{\ell \notin C_k}\sigma_B(\ell))$ we get that  
\begin{eqnarray*}
\sum_{j \in C_k} \hat{\sigma}_B^k(j) \cdot x_A(0,j)\cdot (p_A(0,j) - \epsilon_k) \geq\sum_{j \in C_k} \hat{\sigma}_B^k(j) \cdot x_A(i,j)\cdot (p_A(i,j) - \epsilon_k)
\end{eqnarray*}
meaning that agent $A$ has no exploitability against strategy $\hat{\sigma}_B$. At the same time, we are ensured that the payment of agent $A$ is at least $\mu_A := \min_{i,j \in [M]} \{x_{A}(i,j)\cdot p_A(i,j)~:~ x_{A}(i,j)\cdot p_A(i,j) > 0\}$.
\smallskip
\smallskip

\noindent We complete the proof by showing that the exploitability agent $B$ with respect to $e_0 = (1,0,\ldots,0)$ is at most $M\cdot(1-\sigma_A^k(0))$. This is because
\[ \left|\sum_{i \in [M]} \sigma_A(i) \cdot x_A(i,j)\cdot p_A(i,j)  -  \sum_{i \in [M]} e_0(i) \cdot x_A(i,j)\cdot p_A(i,j)\right| \leq M \cdot (1-\sigma_A^k(0))\]
\smallskip
\smallskip

We complete the proof of Lemma~\ref{l:main} in case agent $A$ does not sell any of its energy (the amount of energy that agent $B$ sells is  $1$). This means that for any bid $i \in [M]$, $x_A(i,j) = 0$ for all $j \in \mathrm{support}(\sigma_B^k)$ since otherwise agent $A$ could deviate to a strategy and sell some of its energy making its revenue positive. Now let $j_\mathrm{max} := \mathrm{argmax}_{j \in \mathrm{support(\sigma_B)}} \sum_{ i \in [M]} \sigma_A(i) \cdot p_B(i,j)$. Then the pair of strategies $\hat{\sigma} =  ( \sigma_A, e_{j_\mathrm{max}})$ is a mixed NE
since $x_A(i,j_{\mathrm{max}}) = 0$ for all $i \in [M]$. At the same time the payment to agent $B$ is at least $1$ since $\mathrm{max}_{j \in \mathrm{support(\sigma_B)}} \sum_{ i \in [M]} \sigma_A(i) \cdot p_B(i,j) \geq 1$.
\qed



\smallskip
\smallskip
\smallskip


\item \underline{There exists an infinite subsequence $\mathcal{S}' \subseteq 
\mathcal{S}$ such that for any $\sigma_k \in \mathcal{S}'$,  $\mathrm{support}(\sigma^k_A) = \{0\}$}.
\smallskip
\smallskip

In this case, we are ensured that at limiting point $\sigma^\star$, $\lim_{k \rightarrow \infty} \sigma^k = \sigma^\star$ and the proof follows with the exact same steps as above.

\end{itemize}
\qed
\end{proof}

