% \begin{theorem}
% \label{thm:UB-PC}
% The unit price given by the worst-case pure Nash equilibrium of Pay-as-Clear is at least $\max_{i\preceq_\mathbf{c} \tau(\mathbf{c})} \high{b}_i$.
% \end{theorem}

\begin{proof}
Let agent $i$ be the agent that has $\high{b}_i=\max_{j\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_j$ and let $\mathbf{b}^\star_{-i}=\mathbf{c}_{-i}+\mathbf{d}_{-i}$ where $\mathbf{d}_{-i}\in\set{0,1}^{n-1}$ such that $\high{b}_i=\max\set{b_i\in[M] \text{ s.t. }b_i\in \mathcal{BR}(\mathbf{b}^\star_{-i})}$. We will establish that $\vecb^\star=(\high{b}_i,\vecb^\star_{-i})$ is a pure NE and $p^{unit}(\vecb^\star)=\high{b}_i$.
\smallskip

\noindent By the definition of $\vecb^\star$ agent $i \in [n]$ has no incentive to deviate. Now consider any other agent $j\neq i$. 

\begin{itemize}
\item Let agent $j\preceq_\mathbf{c}\mathbf{c}$, for any bid $b_j\leq \high{b}_i$, the agent $j$ will sell less or equal amount of energy at price $\high{b}_i$. Thus, $U_j(b_j,b^\star_{-j}) \leq U_j(c_j,b^\star_{-j})$. 
As a result, we need to consider only the case $b_j > \high{b}_i$. By the definition, we know that 
\begin{align*}
    \max\set{b_j\in[M]\text{ s.t. }b_j\in\mathcal{BR}(c_i,\vecb^\star_{-i-j})}\leq \high{b}_j \leq \high{b}_i,
\end{align*} while in the bidding profile $\vecb^\star$ agent $j \in [n]$ sells $s_j$ amount of energy. This means that \[\max_{b_j\in[M]}U_j(b_j,(c_i,\mathbf{b^\star}_{-i-j}))\leq (\high{b}_i-c_j)\cdot s_j = U_j(\vecb^\star). \] Therefore, we have  
\[U_j(b_j, \vecb^\star_{-j}) = U_j(b_j, (c_i,\mathbf{b^\star}_{-i-j})) \leq \max_{b_j\in[M]}U_j(c_j,(b_i,\mathbf{b^\star}_{-i-j}))  \leq U_j(\vecb^\star).\]
The equality is due to $b_j>\high{b}_i=b^\star_i$. Thus, agent $j$ has no incentive to deviate.
\smallskip
\smallskip
\smallskip

\item  In the case $j \succ_\mathbf{c}\tau(\mathbf{c})$, if $c_j<\high{b}_i$, the same argument as above follows. If $c_j \geq \high{b}_i$, agent $j$ sells $0$ amount of energy for any bid $b_j \geq \high{b}_i$. This is because $\sum_{j\preceq_\mathbf{c}\tau(\mathbf{c})} s_j \geq 1$. For any bid $b_j < \high{b}_i$, the agent with $c_j \geq \high{b}_i$ cannot have non-positive utility. In any case, an agent $j$ does not have an incentive to deviate.

\noindent Now, we consider the unit price $p(\vecb^\star)$. By the maximality of $\high{b}_i$, $p(\vecb^\star)$ cannot be greater than $\high{b}_i$. At the same time, $p(\vecb^\star)$ is at least $\high{b}_i$ since agent $i$ yields a positive utility in the bidding profile $\mathbf{c}+1$ where every agent bids the real cost plus one, which implies $\high{b}_i> c_i$. Thus, $p(\vecb^\star)=\high{b}$.
\end{itemize}
\qed
\end{proof}

\section{Proof of Lemma \ref{lem:least-utility-PC}}
\label{proof:lem:least-utility-PC}
\LleasttuilityPC*

\begin{proof}

     The lemma follows since
     \begin{align}
     \label{inq:lem-pc-least-utility}
         U_i(\mathbf{b})= x_i(\mathbf{b})\cdot(q(\vecb)-c_i)\geq x_i(b_i,\mathbf{c}_{-i})\cdot(q(b_i,\mathbf{c}_{-i})-c_i)=U_i(b_i,\mathbf{c}_{-i}).
     \end{align}
     The equalities hold by definition. The inequality holds since $x_i(\mathbf{v})$ and $q(\mathbf{v})$ are monotone with respect to $v_j$ where $j\neq i$ and $b_j\geq c_j$ holds for any $j\neq i$.  

     \smallskip
     \noindent If we let $b^\star_i= \max \mathcal{BR}(\mathbf{c}_{-i})$, and consider any mixed NE $\sigma$, we have
     \begin{align*}
         \Ex_{\vecb\sim\sigma}[U_i(\vecb)]&\geq \max_{b'_i\in[M]}\Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(b'_i,\vecb_{-i})]\geq \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(b^\star_i,\vecb_{-i})]\\
         &=\sum_{\vecb_{-i}\in \text{support}(\sigma_{-i})}\Pr[\vecb_{-i}]\cdot U_i(b^\star_i,\vecb_{-i})\geq \sum_{\vecb_{-i}\in \text{support}(\sigma_{-i})}\Pr[\vecb_{-i}]\cdot U_i(b^\star_i,\mathbf{c}_{-i})\\
         &=U_i(b^\star_i,\mathbf{c}_{-i})=\max_{b'_i\in[M]} U_i(b'_i,\mathbf{c}_{-i}).
     \end{align*}
     The first inequality is due to the equilibrium condition. The second inequality follows from the maximality. The first equality is by definition. The third inequality follows from Inequality \eqref{inq:lem-pc-least-utility}. The second equality follows by the normalization of probabilities. The last equality holds due to our choice of $b^\star_i$. \qed
\end{proof}
\section{Proof of Theorem \ref{thm:LB-PC}}
\label{proof:thm:LB-PC}

\TLBPC*
\begin{proof}
Assume there is a mixed NE $\sigma$ with $\Ex_{\vecb\sim\sigma}[p^{\sss \text{unit}}(\vecb)]<\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_i$. It suggest the expected clearing price $\Ex_{\vecb\sim\sigma}[q(\vecb)]<\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_i$ since 
\begin{align*}
    p^{\sss \text{unit}}(\vecb)=\sum_{i \in [n]}x_i(\vecb) \cdot p_i(\vecb)=\sum_{i \in [n]}x_i(\vecb) \cdot q(\vecb)=q(\vecb),
\end{align*}
where all equalities are by definition.

\noindent Fix an agent $j$ whose $\low{b}_j=\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_i$, we have 
\begin{align*}
    \Ex_{\vecb\sim\sigma}[U_j(\vecb)]
    &=\Ex_{\vecb\sim\sigma}[x_j(\vecb)\cdot(p_j(\vecb)-c_j)]=\Ex_{\vecb\sim\sigma}[x_j(\vecb)\cdot(q(\vecb)-c_j)]\\
    &\leq \Ex_{\vecb\sim\sigma}[s_j\cdot(q(\vecb)-c_j)]=s_j\cdot(\Ex_{\vecb\sim\sigma}[q(\vecb)]-c_j)\\
    &<s_j\cdot(\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_i-c_j)=s_j\cdot(\low{b}_j-c_i)=\max_{b'_i\in[M]}U_j(b'_j,\mathbf{c}_{-j}).
\end{align*}
The first and second equality follow by definition. The first inequality holds since $s_j$ is the maximum allocation agent $j$ might receive. The third equality holds by the linearity of expectation. The second inequality follows since we have shown $\Ex_{\vecb\sim\sigma}[q(\vecb)]<\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\low{b}_i$. The fourth equality holds by our choice of agent $j$. The last equality follows by the definition of $\low{b}_j$.

\noindent However, Lemma \ref{lem:least-utility-PC} guarantees that 
\begin{align*}
    \Ex_{\vecb\sim\sigma}[U_j(\vecb)]\geq \max_{b'_j\in[M]}U_j(b'_j,\mathbf{c}_{-j}),
\end{align*}
which leads to a contradiction.
\qed
\end{proof}

