     \begin{align*}
         \Ex_{\vecb\sim\sigma}[U_i(\vecb)]&\geq \max_{b'_i\in[M]}\Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(b'_i,\vecb_{-i})]\geq \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(b^\star_i,\vecb_{-i})]\\
         &=\sum_{\vecb_{-i}\in \text{support}(\sigma_{-i})}\Pr[\vecb_{-i}]\cdot U_i(b^\star_i,\vecb_{-i})\geq \sum_{\vecb_{-i}\in \text{support}(\sigma_{-i})}\Pr[\vecb_{-i}]\cdot U_i(b^\star_i,\mathbf{c}_{-i})\\
         &=U_i(b^\star_i,\mathbf{c}_{-i})=\max_{b_i\in[M]} U_i(b_i,\mathbf{c}_{-i}).
     \end{align*}
The first inequality is due to the equilibrium condition. The second inequality follows from the maximality. The first equality is by definition. The third inequality follows from Inequality \eqref{inq:lem-pb-least-utility}. The second equality follows by the normalization of probabilities. The last equality holds due to our choice of $b^\star_i$. 
\qed
\end{proof}

\section{Proof of Theorem \ref{thm:LB-PB}}
\label{proof:thm:LB-PB}
\TLBPB*
\begin{proof}
Fix the agent $i:=\argmax_{j\preceq_{\mathbf{c}}\tau(\mathbf{c})}\low{b}_j$. Due to Lemma~\ref{lem:least-utility-PB} and the equilibrium condition, any bid in agent $i$'s support should yield a utility of at least $\max_{b'_i\in[M]}U_i(b'_i,\mathbf{c}_{-i})$. Recall $\low{b}_i= c_i + \max_{b'_i\in[M]}U_i(b'_i,\mathbf{c}_{-i}) / s_i$, agent $i$ has no incentive to bid below $ \low{b}_i$ with non-zero probability in $\sigma$. Consider any bid $b_i < \low{b}_i$, even in case agent $i \in [n]$ sells all of its energy $s_i \in [0,1]$, its utility is strictly less than $\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})$. As a result, we are ensured that the with probability $1$, agent $i \in [n]$ bids greater or equal to $\low{b}_i:= \max_{j\preceq_{\mathbf{c}}\tau(\mathbf{c})}\low{b}_j$.
\smallskip
\smallskip

\noindent Notice that since agent $i \in [n]$ sells a positive amount of energy once bidding $\high{b}_i$ and since $\low{b}_i \leq \high{b}_i$, we are ensured that $\sum_{ c_j < \low{b}_i}s_j < 1$. Therefore, any agent $j\neq i$ with cost $c_j < \low{b}_i$, is ensured to sell his whole supply $s_j$ by bidding $\low{b}_i-1$. In this case, bidding lower cannot increase the allocation. Thus, any agent $j \neq i$ will have a strictly smaller payoff once bidding less than $\low{b}_i-1$. \qed
\end{proof}

\section{Proof of Theorem~\ref{thm:UB-PB}}\label{proof:thm:UB-PB}

\TUBPB*

\noindent The proof of Theorem~\ref{thm:UB-PB} follows easily by Lemma~\ref{lem:ub-low-cost-agent} which is presented up next. The proof of Lemma~\ref{lem:ub-low-cost-agent} is presented in Appendix~\ref{proof:lem:ub-low-cost-agent}. 
\begin{lemma}
    \label{lem:ub-low-cost-agent}
    Let $t:=\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\max_{\sigma_i(b_i)>0} b_i$ be the maximum possible bid of an agent $i\preceq_\mathbf{c}\tau(\mathbf{c})$. Let agent $i\preceq_\mathbf{c}\tau(\mathbf{c})$ be the agent with the lowest priority according to the lexicographical order among agents who bid $t$ with positive probability, we have $t\leq \high{b}_i$.
\end{lemma}
To this end we complete the section with the proof of Theorem~\ref{thm:UB-PB}.
\begin{proof}[Proof of Theorem~\ref{thm:UB-PB}]
    By Lemma \ref{lem:ub-low-cost-agent}, the highest possible bid from all the agent $i\preceq_\mathbf{c}\tau(i)$ is at most $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_i$. Since $\sum_{i\preceq_\mathbf{c} \tau(\mathbf{c})}s_i\geq 1$, any agent $j\succ_\mathbf{c}\tau(i)$ cannot sell positive amount by bidding $b_j\geq\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_i$. Thus, no energy is bought at price higher than $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_i$.\qed
\end{proof}





\subsection{Proof of Lemma \ref{lem:ub-low-cost-agent}}
\label{proof:lem:ub-low-cost-agent}
 Due to Lemma \ref{lem:least-utility-PB}, agent $i$'s utility is at least $\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})$. Thus, $\Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_i)]$ is at least $\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})$ by equilibrium condition. We first assume that $\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})>0$ and will solve the case $\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})=0$ later. Under our assumption, we notice a specific behavior by agents $j\succ_\mathbf{c}\tau(\mathbf{c})$ with cost $c_j<t-1$.

\begin{claim2}
    \label{clm:low-cost-agent-always-bids-low}
    If an agent $j\succ_\mathbf{c}\tau(\mathbf{c})$ has cost $c_j<t-1$, it will bid at most $t-1$ with probability of $1$.
\end{claim2}

\begin{proof}
    Since $\Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_i)]\geq\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i}) >0$, we notice there exists at least one bidding profile $\vecb\sim\sigma$ where $b_i=t$ such that $\tau(\mathbf{b})\succeq_\vecb i$. Together with the fact $\sum_{k\preceq_\mathbf{c}\tau(\mathbf{c})}s_k\geq 1$ and our choice of $i$, $\tau(\mathbf{b})= i$ in such $\vecb$. Thus, any agent $j\succ_\mathbf{c}\tau(\mathbf{c})$ with $c_j<t-1$ will always bid at most $t-1$. Otherwise, it sells an amount of $0$ with probability of $1$ due to the fact $\sum_{k\preceq_\mathbf{c}\tau(\mathbf{c})}s_k\geq 1$ and our lexicographical tie-breaking.
    \qed
\end{proof}

\noindent Next, we establish the value of $t$ in two complementary cases.
\begin{itemize}
    \item {\bf Case 1:} There are no agent $j\succ_\mathbf{c}\tau(\mathbf{c})$ has cost $c_j=t-1$.

    \smallskip
    \noindent In this case, we have
    \begin{align}
        \label{inq:case1-ub}
        \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_{-i})]=U_i(t,\mathbf{c}_{-i})\leq\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i}).
    \end{align}
    The equality holds due to our choice of $i$ and Claim \ref{clm:low-cost-agent-always-bids-low}, since $c_j<t$ implies $c_j<t-1$ in this case. And the inequality is due to the maximality. Furthermore, we have 
    \begin{align}
        \label{inq:case1-lb}
        \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_{-i})]=\Ex_{\vecb\sim\sigma}[U_i(\vecb)]\geq \max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i}).
    \end{align}
    The equality follows from equilibrium condition. And the inequality is by Lemma \ref{lem:least-utility-PB} and linearity of expectation. 

    Putting Inequality \eqref{inq:case1-ub} and $\eqref{inq:case1-lb}$ together, it is clear that $t$ is a best response to $\mathbf{c}_{-i}$. Thus, \begin{align*}
        t\leq \max\set{b_i\in[M]\text{ such that } b_i\in\mathcal{BR}(\mathbf{c}_{-i})}\leq\high{b}_i.
    \end{align*}
    \item {\bf Case 2:} If there is at least one agent $j\succ_\mathbf{c}\tau(\mathbf{c})$ has cost $c_j=t-1$.

    \smallskip
    \noindent In this case, an agent $j\succ_\mathbf{c}\tau(\mathbf{c})$ with $c_j=t-1$ might bid anything greater than or equal to $c_k$. However, when agent $i$ bids $t$, the conditional expected utility depends only on whether every agent $j$ bids $c_j=t-1$ or greater than $c_j$, in other words, at least $t$. Thus, agent $i$'s expected utility conditioned on bidding $t$ is 
    \begin{align*}
        \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_{-i})]=\sum_{\mathbf{d}_{-i}\in\set{0,1}^{n-1}} \Pr_{\vecb_{-i}\sim\sigma_{-i}}\left[\bigwedge_{j\neq i}\min\{b_j,c_j+1\}=c_j+d_j\right]\cdot U_i(t,\mathbf{c}_{-i}+\mathbf{d}_{-i})
    \end{align*}
    Note that $\Pr_{\vecb_{-i}\sim\sigma_{-i}}\left[\bigwedge_{j\neq i}\min\{b_j,c_j+1\}=c_j+d_j\right]$ denotes the probability that every agent $j$ bids $b_j=c_j$ if $d_j=0$, otherwise, bids $b_j\geq c_j+1$. We define $\mathbf{d}^\star_{-i}\in\set{0,1}^{n-1}$ where $d^\star_{j}=1$ if and only if $c_j+1=t$. We have
    \begin{align}
        \label{inq:case2-PB-ub}
        \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_{-i})]\leq U(t,\mathbf{c}_{-i}+\mathbf{d}^\star_{-i}).
    \end{align}
    The inequality follows since $U_i(t,\mathbf{c}_{-i}+\mathbf{d}_{-i})$ is maximized when $\mathbf{d}_{-i}=\mathbf{d}^\star_{-i}$. To understand, $\mathbf{d}^\star_{-i}$ says every agent $j$ with $c_j=t-1$ will bid $t$ so that the allocation $x_i(t,\mathbf{c}_{-i}+\mathbf{d}_{-i})$ is maximized when $\mathbf{d}_{-i}=\mathbf{d}^\star_{-i}$. 
    Moreover, for any $b_i\neq t$, we have
    \begin{align}
        \label{inq:case2-PB-lb}
        \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(t,\vecb_{-i})]\geq \max_{b_i\neq t}\Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_i(b_i,\vecb_{-i})]\geq \max_{b_i\neq t} U_i(b_i,\mathbf{c}_{-i}+\mathbf{d}^\star_{-i}). 
    \end{align}
    The first inequality is by equilibrium condition.
    The reason why the second inequality follows is: 1. Agent $i$'s utility while fixing a specific bid is minimized when the allocation is minimized; 2. We have $b_i\neq t$, so the agent $j$ with $c_j=t-1$ does not affect the utility if it bids $c_j+1$.

    Putting Inequality \eqref{inq:case2-PB-ub} and \eqref{inq:case2-PB-lb} together, we get 
    \begin{align*}
        U(t,\mathbf{c}_{-i}+\mathbf{d}^\star_{-i})=\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i}+\mathbf{d}^\star_{-i}).
    \end{align*}
    Thus, by definition,
    \begin{align*}
        t&\leq\max\set{b_i\in[M] \text{ such that } b_i\in\mathcal{BR}(\mathbf{c}_{-i}+\mathbf{d}^\star_{-i})}\\
        &\leq \max_{\mathbf{d}\in\set{0,1}^n}\max\set{b_i\in[M] \text{ such that } b_i\in\mathcal{BR}(\mathbf{c}_{-i}+\mathbf{d}_{-i})}=\high{b}_i.
    \end{align*}
\end{itemize}

\smallskip
\smallskip

\noindent Finally, we consider what if $\max_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})=0$. In this case, we have $\high{b}_i=c_i+1$. Assume $t> c_i+1$, agent $j$ with $c_j=c_i$ will bid in $[c_i+1, t-1]$ with probability of $1$ since $\sum_{k\preceq_\mathbf{c} \tau(\mathbf{c})}s_k\geq 1$. And when agent $i$ bids $t$, it receives a conditional expected utility of $0$ since $\sum_{k\neq i,c_k\leq c_i}s_k\geq 1$. It contradicts that $\sigma$ is a mixed NE since agent $i$ can move all the probability mass of bidding $t$ to bid $c_i+1$ to improve the utility. 

\noindent In all cases, the theorem follows.
\qed

\section{Proof of Theorem \ref{thm:UB-PB-better}}
\label{proof:thm:UB-PB-better}
\TUBPBbetter*

\begin{proof} 
Let $i^\star:=\argmax_{i\preceq_\mathbf{c}\tau(c)}\low{b}_i$. Assume that if $s_{i^\star}<1$, $\low{b}_{i^\star}+1< \high{b}_{i^\star}$, and $\low{b}_j\leq\low{b}_{i^\star}-2$ for every agent $j\neq i^\star$. We will show that the unit price given by the worst-case mixed NE of PB is at most $p:= (1-s_{i^\star})\cdot\left(\low{b}_{i^\star}+1+\gamma\cdot\sum_{\ell=\low{b}_{i^\star}+2}^{\high{b}_{i^\star}}{1}/{(\ell-c_{i^\star}-1)}\right)+s_{i^\star}\cdot\high{b}_{i^\star}$ where $\gamma=\max_{b'_{i^\star}\in[M]}U_{i^\star}(b'_{i^\star},\mathbf{c}_{-i^\star})/s_{i^\star}+1$.  Moreover, $p < \high{b}_{i^\star}\leq \max_{i\preceq_{\mathbf{c}}\tau(\mathbf{c})}\high{b}_i$.

%\begin{remark}
\noindent We remark that $s_{i^\star} < 1$ is a natural assumption since, most likely, no single producer $i \in [n]$ will be able to cover the whole energy demand. The assumption $\low{b}_{i^\star}+1<\high{b}_{i^\star}$, is also mild since $\low{b}_{i^\star}+1\geq \high{b}_{i^\star}$ only happens when $i \in [n]$ sells exactly $s_{i^\star}$ energy as a pivotal agent. This only happens if $\sum_{j: c_j \leq \high{b}_{i^\star} }  s_j$ is equal to the total energy demand of $1$. This case will occur with $0$ probability assuming a small random perturbation on the  supplies $s_j$ of the agents. Similarly, assuming in case of sufficiently small discretization and a random permutation on the  supplies $s_j$, the assumption $\low{b}_j\leq\low{b}_{i^\star}-2$ is satisfied with probability $1$.
%\end{remark}


\noindent We start by tightening the support of the mixed NE.
\begin{lemma}
\label{lem:tighten-supp}
Let $i^\star:=\argmax_{i\preceq_\mathbf{c}\tau(c)}\low{b}_i$. In case that every agent $j\neq i^\star$ has $\low{b}_j\leq\low{b}_{i^\star}-2$. Then the support of any mixed NE is a subset of $[\low{b}_{i^\star}-1,\high{b}_{i^\star}]$. 
%Specifically, the support of agent $i$ is a subset of $[\low{b}_i,\high{b}_i]$.
\end{lemma}

\begin{proof}
The lower bound follows directly from Theorem \ref{thm:LB-PB}, so we only need to prove the upper bound. We first establish that in case agent $j\in [n]$ sells its supply $s_j \in [0,1]$ at price $\low{b}_j+1$, then its utility is higher than the \textit{best possible utility} once bidding $\high{b}_j$. By the definition of $\low{b}_j$ we have that,
    \begin{align}
        \label{inq:tighter_interval_1}
        \low{b}_j=\left\lceil c_j+\frac{\max_{b_j\in[M]}U_j(b_j,\mathbf{c}_{-j})}{s_j}\right\rceil\geq c_j+\frac{\max_{b_j\in[M]}U_j(b_j,\mathbf{c}_{-j})}{s_j}.
    \end{align}
    Then we consider the maximum utility achieved by becoming the pivotal agent, we have that
    \begin{align}
        \nonumber
        \max_{\mathbf{d}_{-j}\in\set{0,1}^{n-1}}\max_{b_j\in[M]}U_j(b_j,\mathbf{c}_{-j}+\mathbf{d}_{-j})&\leq \max_{b_j\in[M]}U_j(b_j,\mathbf{c}_{-j}+1)\\
        \nonumber
        &\leq\max_{b_j\in[M]}U_j(b_j-1,\mathbf{c}_{-j})+(b_j-(b_j-1))\cdot s_j\\ 
          \label{inq:tighter_interval_2}          &=\max_{b_j\in[M]}U_j(b_j,\mathbf{c}_{-j})+s_j.
    \end{align}
    The first inequality follows since the price under the same allocation is maximized if every other agent bids one step to the left. The second inequality follows since the allocation is the same if every agent shifts its bid one step to the left. The equality is simply by algebra.

    \smallskip
    \noindent Plug Inequality \eqref{inq:tighter_interval_2} into \eqref{inq:tighter_interval_1}, we get
    \begin{align*}
        \low{b}_j+1\geq c_j+\frac{\max_{\mathbf{d}_{-j}\in\set{0,1}^{n-1}}\max_{b_j\in[M]}U_j(b_j,\mathbf{c}_{-j}+\mathbf{d}_{-j})}{s_j}.
    \end{align*}

\noindent Notice that by Theorem~\ref{thm:LB-PB}, the support of any mixed NE is greater than $\low{b}_{i^\star} - 1$ meaning that if agent $j$ bids $\low{b}_{i^\star} - 2 \geq \low{b}_j + 1$ then agent $j \in [n]$ sells its whole energy $s_j$ at price at least $\low{b}_j +1$, meaning that the utility of bidding $\low{b}_{i^\star} - 2$ is at least $U_j(\high{b}_j,\mathbf{c}_{-j}+\mathbf{d}_{-j})$.    


\noindent Thus, the agent $j$ with $\low{b}_j\leq\low{b}_j-2$ will not have a positive probability to bidding any value to make it become the pivotal agent surely since the utility is always better if it can sell all the supply with price $\low{b}_j+1$. And by a similar argument as in the Theorem \ref{thm:LB-PB}, agent $i^\star$ bids at least $\low{b}_{i^\star}$ with probability of $1$. Thus, agent $j$ is ensured to sell everything by bidding $\low{b}_{i^\star}-1$. Recall we assume that $\low{b}_j\leq \low{b}_{i^\star}-2$. So any agent $j\neq i$ prefers to bid $\low{b}_{i^\star}-1$ than becoming the pivotal agent, in other words, it cannot be the one who bids the highest possible bid. The lemma follows since we can repeat the proof of Theorem \ref{thm:UB-PB} with the knowledge that agent $i$ bids the highest.
    \qed
\end{proof}
Now, consider a mixed NE $\sigma$. Assume that $t=\max_{\sigma_{i^\star}(b_{i^\star})>0}b_{i^\star}$. By Lemma \ref{lem:tighten-supp}, we have $\sigma_{i^\star}(b_{i^\star})>0$ only if $\low{b}_{i^\star}-1\leq b_{i^\star} \leq \high{b}_{i^\star}$. Assume without loss of generality that $\sigma_{i^\star}(\high{b}_{i^\star})>0$; otherwise, the unit price is always lower than the bound we present. Due to the equilibrium, agent $i^\star$'s expected utility conditioned on bidding $\high{b}_{i^\star}$ is at least the expected utility conditioned on bidding any other $b_{i^\star}\in [M]$, i.e.,
    \begin{align} 
        \label{inq:unit-price-pb-1}
        \Ex_{\vecb_{-i^\star}\sim\sigma_{-i^\star}}[U_{i^\star}(\high{b}_{i^\star},\vecb_{-i^\star})]&\geq \Ex_{\vecb_{-i^\star}\sim\sigma_{-i^\star}}[U_{i^\star}(b_{i^\star},\vecb_{-i^\star})]\geq s_{i^\star}\cdot (b_{i^\star}-c_{i^\star})\cdot\Pr_{\vecb_{-i\star}\sim \sigma_{-i}}[x_{i^\star}(b_{i^\star},\vecb_{-i^\star})=s_{i^\star}]
    \end{align}
    The second inequality follows since we ignore any utility given by the case $x_{i^\star}(b_{i^\star},\mathbf{b}_{-i^\star})\neq s_{i^\star}$, in other words, agent $i^\star$ sells all its supply while bidding $b_{i^\star}$. Furthermore, 
    \begin{align}
        \label{inq:unit-price-pb-2}
        \Ex_{\vecb_{-i}\sim\sigma_{-i}}[U_{i^\star}(\high{b}_{i^\star},\vecb_{-i^\star})]\leq \max_{\mathbf{d}_{-{i^\star}}\in\set{0,1}^{n-1}}\max_{b_{i^\star}\in[M]}U_{i^\star}(b_i,\mathbf{c}_{-i^\star}+\mathbf{d}_{-i^\star})\leq \max_{b_{i^\star}\in[M]}U_{i^\star}(b_{i^\star},\mathbf{c}_{-i^\star})+s_{i^\star}.
    \end{align}
    The first inequality follows since $\high{b}_{i^\star}$ is either $c_j$ or $c_j+1$ for some agent $j$. The second inequality follows by Inequality \eqref{inq:tighter_interval_2}.
    Puttng Inequality \eqref{inq:unit-price-pb-1} and \eqref{inq:unit-price-pb-2} together, we have
    \begin{align*}
        \Pr_{\vecb_{-i}\sim\sigma_{-i}}[x_{i^\star}(b_{i^\star},\vecb_{-i^\star})=s_{i^\star}]\leq \frac{\max_{b'_{i^\star}\in[M]}U_{i^\star}(b'_{i^\star},\mathbf{c}_{-i^\star})+s_{i^\star}}{s_{i^\star}\cdot(b_{i^\star}-c_{i^\star})}=\frac{\gamma}{b_{i^\star}-c_{i^\star}}.
    \end{align*}
    %where $\beta:=\argmax_{b_i\in[M]}U_i(b_i,\mathbf{c}_{-i})$ when everyone else bid truthfully and $\xi:=x_i(\beta,\mathbf{c}_{-i})$.
\smallskip
\smallskip

\noindent Notice that in case $x_{i^\star}(b_{i^\star},\mathbf{b}_{-i^\star})<s_{i^\star}$ then at least $1-s_{i^\star}$ energy is bought at price at most $b_{i^\star}$. Denote the random variable $X_{\leq \alpha}$ as the amount of energy that is bought at a price at most $\alpha$. The randomness comes from which bidding profile is drawn from the distribution. We have
%In other words, the clearing price $q(b_i,\mathbf{b}_i) \leq b_i$ (recall Definition \ref{def:allocation-and-clearing-price}) is at most $b_i$. 
    \begin{align}
        \label{inq:unit-price-pb-prob}
        \Pr_{\vecb\sim\sigma}[X_{\leq\alpha}\geq 1- s_{i^\star}]\geq 1-\Pr_{\vecb_{-i}\sim\sigma_{-i}}[x_{i^\star}(b_{i^\star}=\alpha,\vecb_{-i^\star})=s_{i^\star}]\geq 1-\frac{\gamma}{\alpha-c_{i^\star}}.
    \end{align}

    \noindent We can then upperbound the unit price by minimizing the energy sold at a low price. Specifically, when $X_{\leq \alpha}\geq 1-s_{i^\star}$ but $X_{\leq \alpha-1}< 1-s_{i^\star}$, we assume exactly $1-s_{i^\star}$ energy is sold below the price $\alpha$ and the remaining $s_{i^\star}$ energy is sold at the price of $\high{b}_{i^\star}$. In this way, we will only increase the unit price. As a result,
    \begin{align}
        \label{inq:unit-price-relaxation-1}
        \Ex_{\vecb\sim\sigma}[p^{unit}(\vecb)]\leq \sum_{\alpha=\low{b}_{i^\star}-1}^{\high{b}_{i^\star}}f(\alpha)\cdot (s_{i^\star}\cdot\high{b}_{i^\star}+(1-s_{i^\star})\cdot \alpha),
    \end{align}
    where we denote \[f(\alpha)=\Pr_{\vecb\sim\sigma}[X_{\leq \alpha}\geq 1-s_{i^\star}\text{ and }X_{\leq \alpha-1}< 1-s_{i^\star}]=\Pr_{\vecb\sim\sigma}[X_{\leq \alpha}\geq 1-s_{i^\star}]-\Pr_{\vecb\sim\sigma}[X_{\leq \alpha-1}\geq 1-s_{i^\star}].\]

    \noindent Notice that $\Pr_{\vecb\sim\sigma}[X_{\leq \alpha}\geq 1-s_{i^\star}]=0$ for any $\alpha < \low{b}_{i^\star}-1$ since every agent bids at least $\low{b}_{i^\star}$. And $\Pr_{\vecb\sim\sigma}[X_{\leq \alpha}\geq 1- s_{i^\star}]=1$ for any $\alpha \geq\high{b}_{i^\star}$ since every agent bids at most $\high{b}_{i^\star}$. Thus, we can upperbound the RHS of Inequality \eqref{inq:unit-price-relaxation-1} by as setting,

\smallskip

    \begin{align}
    \label{inq:unit-price-tight-prob-est}
        f(\alpha)=\begin{cases}
            0, &\alpha=\low{b}_{i^\star}-1 \text{ or }\low{b}_{i^\star},\\
            1-\frac{\gamma}{\alpha-c_{i^\star}},&\alpha=\low{b}_{i^\star}+1,\\
            \gamma\cdot(\frac{1}{\alpha-c_{i^\star}-1}-\frac{1}{\alpha-c_{i^\star}}),&\low{b}_{i^\star}+2\leq \alpha\leq\high{b}_{i^\star}-1\\
            \gamma\cdot\frac{1}{\alpha-c_{i^\star}-1}, &\alpha=\high{b}_{i^\star}\\
        \end{cases}.
    \end{align}

\noindent This is because the assignment presenting in Equation~\eqref{inq:unit-price-tight-prob-est} is the assignment maximizing Equation~\eqref{inq:unit-price-relaxation-1} while at the same time satifying Equation~\eqref{inq:unit-price-pb-prob} and the non-negativity of probabilities. 
\noindent Plugging Equality \eqref{inq:unit-price-tight-prob-est} into Inequality \eqref{inq:unit-price-relaxation-1}, we have

    \begin{align*}
        \Ex_{\vecb\sim\sigma}[p^{unit}(\vecb)]&\leq (1-s_{i^\star})\cdot\left((1-\frac{\gamma}{\low{b}_{i^\star}-c_{i^\star}+1})\cdot(\low{b}_{i^\star}+1)+\gamma\cdot\sum_{\alpha=\low{b}_{i^\star}+2}^{\high{b}_{i^\star}-1}\left(\frac{\alpha}{\alpha-c_{i^\star}-1}-\frac{\alpha}{\alpha-c_{i^\star}}\right)\right)\\
        &\quad+\left(s_{i^\star}+(1-s_{i^\star})\cdot\gamma\cdot\frac{1}{\high{b}_{i^\star}-c_{i^\star}-1}\right)\cdot \high{b}_{i^\star}\\
        &=(1-s_{i^\star})\cdot\left(\low{b}_{i^\star}+1-\gamma\cdot\frac{\high{b}_{i^\star}-1}{\high{b}_{i^\star}-c_{i^\star}-1}+\gamma\cdot\sum_{\alpha=\low{b}_{i^\star}+2}^{\high{b}_{i^\star}-1}\frac{1}{\alpha-c_{i^\star}-1}\right)\\
        &\quad+\left(s_{i^\star}+(1-s_{i^\star})\cdot\gamma\cdot\frac{1}{\high{b}_{i^\star}-c_{i^\star}-1}\right)\cdot \high{b}_{i^\star}\\
        &=(1-s_{i^\star})\cdot\left(\low{b}_{i^\star}+1+\gamma\cdot\sum_{\alpha=\low{b}_{i^\star}+2}^{\high{b}_{i^\star}}\frac{1}{\alpha-c_{i^\star}-1}\right)+s_{i^\star}\cdot\high{b}_{i^\star}.
    \end{align*}
    The equalities simply follow from algebra.
     When $\alpha\geq \low{b}_{i^\star}+2$, we have $s_{i^\star}\cdot(\alpha-c_{i^\star}-1)\geq s_{i^\star}\cdot(\low{b}_{i^\star}+1-c_{i^\star})\geq\max_{b_{i^\star}\in[M]}U_{i^\star}(b_{i^\star},\vecb_{-i^\star})+s_{i^\star}$ by definition of $\low{b}_{i^\star}$. By dividing with $s_{i^\star}$ we get that $\alpha - c_{i^\star} - 1\geq \gamma + 1$ and thus  $\gamma/(\alpha-c_{i^\star}-1)\leq 1$. We further notice that the inequality is strict when $\alpha> \low{b}_{i^\star}+2$. Thus,
    \begin{align*}
        \Ex_{\vecb\sim\sigma}[p^{unit}(\vecb)]&< (1-s_{i^\star})\cdot(\low{b}_{i^\star}+1+(\high{b}_{i^\star}-(\low{b}_{i^\star}+2)+1)\cdot 1) +s_{i^\star}\cdot\high{b}_{i^\star}=\high{b}_{i^\star}.
    \end{align*}
    \qed
\end{proof}
\section{Proof of Theorem~\ref{t:VCG}}\label{app:VCG}

\TVCG*
\begin{proof}
\noindent Example \ref{example:VCG-can-be-bad} demonstrates an energy market where the unit price given by VCG can be arbitrarily bad compared to the unit price given by PC or PB. 
\begin{example}
    \label{example:VCG-can-be-bad}
    Let $\delta>2$ be a constant integer. Consider an energy market with $n=2k-1$ producers and $M=\delta\cdot k-2$, where each producer's supply and cost can be described as follows
    \begin{align*}
        s_i&=\begin{cases}
            \frac{1}{k}, & i\leq k,\\
            \frac{1}{2k}, & i=k+1,\\
            \frac{1}{k(i-k)(i-k+1)}, &k+2\leq i\leq 2k-1,
        \end{cases}\\
        c_i&=\begin{cases}
            0, & i\leq k,\\
            \delta, & i=k+1,\\
            \delta \cdot(i-k)-2, &k+2\leq i\leq 2k-1.
        \end{cases}
    \end{align*}
\end{example}
Recall that VCG is a truthful mechanism, and the externality determines the payment each agent receives their presence imposes on the total cost of the market, i.e., what the market would have to cost if that particular agent had not participated. Thus, the payment to each agent $i \in [k]$ in the equilibrium where everyone bids truthfully is 
    \begin{align*}
        p_i(\mathbf{c})&=\sum_{j=k+1}^{2k-1}c_j\cdot s_j+M\cdot\left(1-\left(\sum_{j=1}^{2k-1}s_j-s_i\right)\right)\\
        &=\delta \cdot \frac{1}{2k}+\sum_{j=2}^{k-1}\frac{\delta\cdot j-2}{k\cdot j\cdot (j+1)}+\frac{\delta\cdot k-2}{k^2}\\
        &=\frac{\delta}{k}\cdot \mathcal{H}_k-\frac{1}{k},
    \end{align*}
where $\mathcal{H}_k$ is the $k$-th harmonic number and the equalities hold by simple algebra. So, the worst-case unit price given by NE in VCG is at least $\Omega(\log n)$.

\noindent Next, we consider the worst-case unit price given by PB and PC. Due to Theorem \ref{t:PB}, the unit price in worst-case mixed NE in PB is bounded by $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})} \high{b}_i$. Since we have $ (\delta\cdot j-1)\cdot \frac{1}{k}\cdot(1-\sum_{\ell=2}^{j}\frac{1}{\ell\cdot(\ell-1)})=(\delta-\frac{\delta}{j})\cdot\frac{1}{k}<\delta\cdot\frac{1}{k}$ for any $j\geq 2$, the best response of any agent $i\preceq_\mathbf{c}\tau(\mathbf{c})$ when everybody else bid approximately truthful is always bidding $\delta$ or $\delta+1$. Thus, the unit price given by worst-case NE is at most $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})}\high{b}_i=\delta+1=O(1)$. The unit price in the worst-case mixed NE in PC is a bit tricky since we have not provided any upper bound for it yet. But we claim it is also at most $\max_{i\preceq_\mathbf{c}\tau(\mathbf{c})} \high{b}_i$ by a similar argument we used to prove the upper bound in PB, since the utility for the pivotal agent is the same in PB and PC. 
\qed
\end{proof}
% \noindent In Example \ref{example:VCG-can-be-bad}, the unit price resulting from the VCG mechanism is in $\Theta(\log n)$. In contrast, both PC and PB yield a unit price of $O(1)$. This significant discrepancy underscores a critical divergence in unit prices between  VCG and PC/PB under specific conditions. Therefore, this example demonstrates that VCG may be an undesirable choice when unit price is a key evaluative metric for a mechanism, despite its truthfulness. This finding is perhaps unsurprising, as similar phenomena regarding price behavior are observed in classic single-item auction settings; however, quantifying the precise cost associated with the truth-telling property remains a valuable endeavor.

% \noindent In our next example the price given by the best-case mixed Nash equilibrium in PB is strictly larger than the price given by the best-case mixed Nash equilibrium in PC. Recall we have proved in Theorem \ref{t:1} that PC cannot be strictly dominated by any mechanism with individual rationality, including PB. However, our proof does not exclude the possibility that the best unit price by PB is always lower than the best unit price by PC, which is another kind of dominance. We now present Example \ref{example:best-PC-can-be-better} to show it is not the case. 


\section{Best-case PB vs Best-Case PC}

\label{app:bestPC}

We have proved in Theorem \ref{t:1} that PC cannot be strictly dominated by any mechanism with individual rationality, including PB. However, our proof does not exclude the possibility that the best unit price by PB is always lower than the best unit price by PC, which is another kind of dominance. We now present Example \ref{example:best-PC-can-be-better} to show it is not the case. 

\label{app:b}
\begin{example}
    \label{example:best-PC-can-be-better}
    Let $\delta$ be a positive constant integer. Consider an energy market with $M=3\delta$ and $n = 3$ producers with  supplies $s_1=1/2,s_2=3/4,s_3=1/4$ and marginal costs $c_1=0,c_2=0,c_3=\delta$. 
\end{example}

\noindent  We first notice that the bidding profile $\vecb=(\delta,0,\delta)$ is a mixed NE in PC. And it provides the lowest price in PC due to Theorem \ref{thm:LB-PC}. Next, we will show that the price given by the best-case NE in PB is strictly greater than $\delta$. In this instance, we have $1\preceq_\mathbf{c}\tau(\mathbf{c})$ and $2\preceq_\mathbf{c}\tau(\mathbf{c})$. And $\low{b}_2=\delta$, while $\low{b}_1=\delta/2$. Due to a similar argument in theorem \ref{thm:LB-PB}, all agents bid at least $\max\set{\low{b}_1,\low{b}_2}$ in any mixed NE of PB. We only need to show that any bidding profile $\vecb$ with $b_1=\delta$ and $b_2=\delta$ is not an NE. It is clear that $U_2(\vecb)=\delta/2<3\delta/4\leq \max_{b'_2\in[M]}U_2(b'_2=3\delta,\mathbf{c}_{-2})$. Due to Lemma \ref{lem:least-utility-PB}, agent $2$ can increase the utility by bidding $\high{b}_2=3\delta$ regardless of the strategy of agent $3$. Therefore, $\vecb$ cannot be an NE.

