\caption{The outward cuspidal domain}
\end{figure} 

In a series of papers \cite{Mazya1, Mazya2, Mazya3, Mazya5}, Maz'ya and Poborchi found sharp conditions on the cuspidal function $\psi$ to guarantee that the outward cuspidal domain $\boz_\psi$ is a $(W^{1, p}, W^{1, q})$-extension domain for $1\leq q<p<\fz$. In the paper \cite{KZ:cusp} it was proved that for an arbitrary model function $\psi$, the corresponding outward cuspidal domain $\boz_\psi$ is a $(W^{1, p}, W^{1, q})$-extension domain for every $1\leq q<n-1$ and $(n-1)q/(n-1-q)\leq p<\fz$. Furthermore, in the paper \cite{EKMZ:imrn}, it was proved that for an arbitrary outward cuspidal domain $\boz_\psi$, the Sobolev space $W^{1, p}(\boz_\psi)$ is isometrically equivalent to the Haj\l{}asz-Sobolev space $M^{1, p}(\boz_\psi)$ for every $1<p<\fz$. Also see \cite{Zhu1} for a more general result. Via this result, we can conclude that $\boz_\psi$ is a $p$-Poincar\'e domain for every $1<p<\fz$. Hence, for outward cuspidal domains, the two different Sobolev extension properties are equivalent. 
\begin{thm}\label{th:cusp}
Let $\boz_\psi\subset\rn$ be an outward cuspidal domain. Then it is a $p$-Poincar\'e domain for $1<p<\fz$. It is a $(W^{1, p}, W^{1, q})$-extension domain for some $1\leq q<p<\fz$, if and only if it is also an $(L^{1,p}, L^{1, q})$-extension domain.
\end{thm}

Our final result addresses the case $p>n$ which is not covered by the second part of the Proposition \ref{th:StoH}. Notice that the condition $q^\star <p\leq n$ in Proposition \ref{th:StoH} requires that $1\leq q<\frac{n}{2}$ and that no counterexamples can exist by the first part of the Proposition when $q \geq n$. Theorem \ref{th:n-1} below will provide us with negative examples when $1\leq q <n-1$, but the case where $n-1\leq q<n$ remains open. By Theorem \ref{th:cusp}, outward cusps do not give examples for the missing case $n-1\leq q<n$. However, the construction for Theorem \ref{th:n-1} is based on a somewhat related non-smoothness. Indeed, one relies on outward ``mushrooms'', based on cylindrical stems. The idea behind constructions of this type goes back to Nikod\'ym. The construction for the example referred to in Theorem \ref{th:poincare} is also of Nikod\'ym-type. However, the proof of the extension property heavily relies on the assumption that $p<n$. We prove the extension property of our example via ideas from \cite{KUZ:JFA} instead of using ideas from \cite{KMZ:arxiv}. Analysis of our argument shows that the restriction $p> \frac{q(n-1)}{(n-1-q)}$ cannot be avoided, see Section \ref{difdomain}. This suggest that perhaps no counterexamples for the coincidence exist when $q\geq n-1$.

\begin{thm}\label{th:n-1}
Let $n\geq 3$, $1\leq q<n-1$ and $(n-1)q/(n-1-q)<p<\fz$. Then there exists a bounded domain $\boz\subset\rn$ which is a $(W^{1, p}, W^{1, q})$-extension domain but not an $(L^{1, p}, L^{1, q})$-extension domain.
\end{thm}


\section{Preliminaries}
We refer to generic positive constants by $C$. These constants may change even in a single string of estimates. The dependence of the constant on parameters $\alpha, \beta,\cdots$ is expressed by the notation $C = C(\alpha, \beta, \cdots)$ if needed.
First, let us give the definition of Sobolev spaces and homogeneous Sobolev spaces.
\begin{defn}\label{de:sobolev}
For $u\in L^1_{\rm loc}(\boz)$, we say $u$ belongs to the homogeneous Sobolev space $L^{1, p}(\boz)$ for $1\leq p\leq\fz$ if $u$ is weakly differentiable and its weak (distributional) derivative $\nabla u$ belongs to $L^p(\boz; \rn)$. The homogeneous Sobolev space $L^{1, p}(\boz)$ is equipped with the semi-norm
\[\|u\|_{L^{1, p}(\boz)}:=\begin{cases}
\lf(\int_\boz\lf|\nabla u(x)\r|^pdx\r)^{\frac{1}{p}}, &\ {\rm for}\ 1\leq p<\fz,\\
{\rm esssup}\lf|\nabla u\r|, &\ {\rm for}\ p=\fz.
\end{cases}\] 
Furthermore, if $u\in L^{1,p}(\Omega)$ is also $L^p$-integrable, then we say $u$ belongs to the Sobolev space $W^{1 ,p}(\boz)$. The Sobolev space $W^{1, p}(\boz)$ is equipped with the norm
\[\|u\|_{W^{1, p}(\boz)}:=\begin{cases}
\lf(\int_\boz\lf|u(x)\r|^p+\lf|\nabla u(x)\r|^pdx\r)^{\frac{1}{p}}, &\ {\rm for}\ 1\leq p<\fz,\\
{\rm esssup}\lf(\lf|u\r|+\lf|\nabla u\r|\r), &\ {\rm for}\ p=\fz.
\end{cases}\] 
\end{defn}
%Then we give the definition of homogeneous Sobolev and Sobolev extension domains.
%\begin{defn}\label{de:extension}
%A bounded domain $\boz\subset\rn$ is a called a $(L^{1, p}, L^{1, q})$-extension domain for $1\leq q\leq p\leq\fz$, if for every $u\in L^{1, p}(\boz)$, there exists a function $E(u)\in L^{1, q}(\rn)$ with $E(u)\big|_\boz\equiv u$ and 
%\[\|E(u)\|_{L^{1, q}(\rn)}\leq C\|u\|_{L^{1, p}(\boz)}\]
%for a constant $C$ independent of $u$. Replace homogeneous Sobolev spaces $L^{1, p}(\boz)$ and $L^{1, q}(\rn)$ by Sobolev spaces $W^{1, p}(\boz)$ and $W^{1,q}(\rn)$ respectively, we obtain the definition of $(W^{1, p}, W^{1, q})$-extension domain.
%\end{defn}

By the results due to Calder\'on \cite{calderon} and Stein \cite{stein}, Lipschitz domains are $(W^{k, p}, W^{k, p})$-extension domains for arbitrary $k\in\mathbb N$ and $1\leq p\leq\fz$. Later, Jones generalized this result to $(\epsilon, \delta)$-domains. Every Lipschitz domain is an $(\epsilon, \delta)$-domain for some $\epsilon, \delta>0$. However, the class of $(\epsilon, \delta)$-domains is strictly larger than the class of Lipschitz domains. As we will use this result later, for the convenience of readers, we present the definition of $(\epsilon, \delta)$-domains here.
\begin{defn}\label{de:ED}
Let $0<\epsilon<1$ and $\delta>0$. We say that a domain $\boz\subset\rn$ is an $(\epsilon, \delta)$-domain, if for every $x, y\in\boz$ with $|x-y|<\delta$, there is a rectifiable curve $\gamma\subset\boz$ joining $x, y$ and satisfies the following two inequalities that 
\begin{equation}\label{eq:uni1}
{\rm length}(\gamma)\leq\frac{1}{\epsilon}|x-y|
\end{equation}
and
\begin{equation}\label{eq:uni2}
d(z, \partial\boz)\geq\frac{\epsilon|x-z||y-z|}{|x-y|}\ {\rm for\ all}\ z\ {\rm on}\ \gamma.
\end{equation}
\end{defn}

By a classical mollification argument, for arbitrary domain $\boz$, we always have that $C^\fz(\boz)\cap W^{1, p}(\boz)$ is always dense in $W^{1, p}(\boz)$ for every $1\leq p<\fz$. See \cite[Theorem 4.2]{Evans:book}. However, we cannot have that $C^\fz(\overline\boz)\cap W^{1, p}(\boz)$ is always dense in $W^{1, p}(\boz)$, unless the domain $\boz$ is sufficiently nice. For the following definition of segment condition, see e.g. the book \cite{AandF:book}.
\begin{defn}\label{de:segment}
Let $\boz\subset\rn$ be a domain. We say it satisfies the segment condition if for every $x\in\partial\boz$, there exists a neighborhood $U_x$ of $x$ and a nonzero vector $y_x$ such that if $z\in\overline\boz\cap U_x$, then $z+ty_x\in\boz$ for $0<t<1$.
\end{defn}
The following lemma tells us that the Sobolev functions defined on a domain with segment condition can be approximated by functions smooth up to the boundary.
\begin{lem}\label{le:smooth}
Let $\boz\subset\rn$ be a domain which satisfies the segment condition. Then for every $1\leq p<\fz$, the subspace $C^\fz(\overline\boz)\cap W^{1, p}(\boz)$ is dense in $W^{1, p}(\boz)$.
\end{lem}

