\section{Proof of Theorem \ref{th:poincare}}
In this section, we prove Theorem \ref{th:poincare}. 
\begin{proof}[Proof of Theorem \ref{th:poincare}]
 Let $\boz\subset\rn$ be a bounded $p$-Poincar\'e domain and a $(W^{1, p}, W^{1, q})$-extension domain. By \cite{HKjam}, we know that $W^{1, p}(\Omega)$ coincides with $L^{1, p}(\Omega)$ as a set of functions. So, for $u\in L^{1,p}(\Omega),$ we have $(u-u_{\Omega})\in W^{1,p}(\Omega).$ Let $B$ be a ball with $\Omega \subset B$. We define a function on $B$ by 
$$T(u):=E(u-u_\boz)+u_\boz.$$ 
Then we have $T(u)\in W^{1, q}(B)$ with $T(u)\big|_B\equiv u$. By the fact $\boz$ is a $(W^{1, p}, W^{1, q})$-extension domain and by the $(p,p)$-Poincar\'e inequality, we have 
\begin{eqnarray}
\|\nabla T(u)\|_{L^q(B)}=\|\nabla E(u-u_\boz)\|_{L^q(B)}\leq \|u-u_{\boz}\|_{W^{1, p}(\boz)}\leq C\|\nabla u\|_{L^p(\boz)}.
\end{eqnarray}
This shows that $\boz$ is a $(L^{1, p}, L^{1, q})$-extension domain, since $B$ is such a domain.
\end{proof}
 \section{Proof of Theorem \ref{th:cusp}}
 \begin{proof}[Proof of Theorem \ref{th:cusp}]

    Let $\boz_\psi\subset\rn$ be an outward cuspidal domain. At first we show that $\boz_\psi$ is a $p$- Poincar\'e domain. Fix $u\in C^{\infty}(\boz_\psi)\cap W^{1,p}(\boz_\psi)$. From \cite[Lemma 4.1]{Zhu1}, there exists a non-negative function $g_u\in L^{p}(\boz_\psi)$ such that for almost every $x ,y \in \boz_\psi$, we have
    \begin{equation}\label{eq4.1}
        |u(x)-u(y)|\leq C |x-y|(g_{u}(x)+ g_{u}(y))
    \end{equation}
    and 
    \begin{equation}\label{eq4.2}
        \int_{\boz_{\psi}}g_u(z)^p dz \leq C \int_{\boz_\psi}|\nabla u(z)|^pdz
    \end{equation}
    with a constant independent of $u$.\\
    By using \ref{eq4.1} and \ref{eq4.2}, we get that
    \begin{eqnarray} \label{peq1}
        \int_{\boz_\psi}|u(x)-u_{\boz_\psi}|^pdx &=& \int_{\boz_\psi}|u(x) \barint_{\boz_\psi} dy -\barint_{\boz_\psi}u(y)dy|^p dx \nonumber\\
        &= & \int_{\boz_\psi}| \barint_{\boz_\psi}u(x) dy -\barint_{\boz_\psi}u(y)dy|^p dx \nonumber\\
        &\leq & \int_{\boz_\psi}\barint_{\boz_\psi}|u(x)-u(y)|^pdydx\nonumber\\
        &\leq& \int_{\boz_\psi}\barint_{\boz_\psi} |x-y|^p(g_u(x)+g_u(y))^pdydx\nonumber\\
        &\leq & C \diam(\boz_\psi)^p \int_{\boz_\psi}|\nabla u(z)|^pdz
    \end{eqnarray}
    Hence, \ref{peq1} shows that $\boz_\psi$ is a $p$-Poincar\'e domain for every $1\leq p \leq \infty$. By using Theorem \ref{th:poincare}, we get that if $\boz_\psi$ is a $(W^{1,p},W^{1,q})$-extension domain, then it is also an $(L^{1,p},L^{1,q})$-extension domain.
 \end{proof}
\section{Proof of Theorem \ref{th:n-1}}

\subsection{The construction of the domain}\label{construction}
Let $1\leq q<n-1$ and $(n-1)q/(n-1-q)<p<\infty$ be fixed.
We use the notation $\mathscr Q(x, r)$ to denote an $(n-1)$-dimensional closed cube in the $(n-1)$-dimensional Euclidean hyperplane $\rr^{n-1}$ with the center $x\in\rr^{n-1}$ and the side-length $2r$. Let $\mathscr Q_0:=[0, 1]^{n-1}$ be the $(n-1)$-dimensional closed unit cube in the $(n-1)$-dimensional Euclidean hyperplane $\mathbb R^{n-1}$.  We divide $\mathscr Q_0$ into $2^{n-1}$ equivalent $(n-1)$-dimensional closed cubes whose interiors are pairwise disjoint. Pick one of them and denote it by $\mathscr Q_1$.  Denote by $z_1$ to be the center of  the cube $\mathscr Q_1$. So $\mathscr Q_1=\mathscr Q\lf(z_1, \frac{1}{4}\r)$. Define
$$\mathscr B_1:=B^{n-1}\lf(z_1, \frac{1}{2^2}\r)\ {\rm and}\  \mathcal B_1:={B^{n-1}}\lf(z_1, \lf(\frac{1}{4}\r)^{\frac{1}{n-1}+\frac{p}{q}}\r).$$
Define $\mathscr C_1:=\mathscr B_1\times \lf(\frac{3}{2}, 2\r)$ to be an open cylinder and $\mathcal C_1:=\mathcal B_1\times\lf[1, \frac{3}{2}\r]$ to be a cylinder which connects the unit cube $\mathcal Q_0$ and the cylinder $\mathscr C_1$.

Choose one of the cubes different from $\mathscr Q_1$ from the first step and denote it by $\mathscr Q'_1$. Divide $\mathscr Q'_1$ into $2^{n-1}$ equivalent $(n-1)$-dimensional closed cubes such that their interiors are pairwise disjoint. Pick one of them up and denote it by $\mathscr Q_2$. Then its edge length is $\frac{1}{4}$. Denote $z_2$ to be the center of the cube $\mathscr Q_2$. So $\mathscr Q_2=\mathscr Q\lf(z_2, \frac{1}{8}\r)$. Define 
\[\mathscr B_2:=B^{n-1}\lf(z_2, \frac{1}{2^3}\r)\ {\rm and}\ \mathcal B_2:={B^{n-1}}\lf(z_2, \lf(\frac{1}{4^2}\r)^{\frac{1}{n-1}+\frac{p}{q}}\r).\]
Define $\mathscr C_2:=\mathscr B_2\times\lf(\frac{3}{2}, 2\r)$ to be an open cylinder and $\mathcal C_2:=\mathcal B_2\times\lf[1, \frac{3}{2}\r]$ to be a cylinder connecting the cube $\mathcal Q_0$ and the cylinder $\mathscr C_2$.

We continue the construction by induction. For $k\in\mathbb N$, assume we have already constructed $(n-1)$-dimensional closed cubes $\mathscr Q_k$, $(n-1)$-dimensional balls $\mathscr B_k$ and $\mathcal B_k$ and the cylinders $\mathscr C_k$ and $\mathcal C_k$. Here $\mathscr Q_k$ is one of $2^{n-1}$ equivalent subcubes of the dyadic cube from $\mathscr Q_{k-1}$. Fix a remaining cube in $\mathscr Q_{k-1}$ and denote it by $\mathscr Q'_{k}$. Divide $\mathscr Q'_k$ into $2^{n-1}$ equivalent $(n-1)$-dimensional closed cubes such that their interiors are pairwise disjoint. Fix one of them and denote it by $\mathscr Q_{k+1}$. Its edge length is $\frac{1}{2^{k+1}}$. Set $z_{k+1}$ to be the center of $\mathscr Q_{k+1}$. Define
\[ \mathscr B_{k+1}:= B^{n-1}\lf(z_{k+1}, \frac{1}{2^{k+2}}\r)\ {\rm and}\  \mathcal B_{k+1}:={B^{n-1}}\lf(z_{k+1}, \lf(\frac{1}{4^{k+1}}\r)^{\frac{1}{n-1}+\frac{p}{q}}\r).\]
Define $\mathscr C_{k+1}:=\mathscr B_{k+1}\times(2, 3)$ and define $\mathcal C_{k+1}:=\mathcal B_{k+1}\times [1, 2]$ to be a cylinder which connects $\mathcal Q_0$ and $\mathscr C_{k+1}$. To simplify the notation, for every $1\leq k<\fz$, we use $\tilde r_k$ and $r_k$ to denote the radius of $\mathscr B_k$ and $\mathcal B_k$ respectively. That is
\begin{equation}\label{eq:radius}
\tilde r_k=\frac{1}{2^{k+1}}\ {\rm and}\ r_k=\lf(\frac{1}{4^k}\r)^{\frac{1}{n-1}+\frac{p}{q}}.
\end{equation}

In conclusion, for every $k\in\mathbb N$, we have constructed two cylinders $\mathscr C_k$ and $\mathcal C_k$ such that the cylinder $\mathcal C_k$ connects the unit cube $\mathcal Q_0$ and the cylinder $\mathscr C_k$. Then our domain $\boz_{p ,q}$ is defined by setting
\begin{equation}\label{eq:boz}
\boz_{p, q}:=\mathcal Q_0\cup\lf(\bigcup_{k=1}^\fz\mathscr C_k\r)\cup\lf(\bigcup_{k=1}^\fz\mathcal C_k\r).
\end{equation}
Given $m\in\mathbb N$, we define
\begin{equation}\label{eq:boz1}
\boz^m_{p, q}:=\mathcal Q_0\cup\lf(\bigcup_{k=1}^m\mathscr C_k\r)\cup\lf(\bigcup_{k=1}^m\mathcal C_k\r).
\end{equation}
