\section{Example shown in the main proof is strong}
Let $\Omega$ be the domain as constructed in \eqref{eq:boz}. For $k\in \mathbb{N}$, we define $u$ on $\boz$ by setting
\begin{equation}
    u_k(x):= \begin{cases}
        0, \  &{\rm if}\ \ x\in \Omega\setminus \mathcal{C}_{k}\cup \mathscr C_k,\\
        1, \ &{\rm if}\ \ x\in \mathscr C_k,\\
        x_n-2,  \  &{\rm elsewhere}.
    \end{cases}
\end{equation}
Now, 
\begin{equation}
    \|u_k\|_{W^{1,p}(\Omega)}= \|u_k\|_{L^p{(\Omega)}}+\|\nabla u_k\|_{L^p(\Omega)},
\end{equation}
which implies that
\begin{eqnarray}
     \|u_k\|_{W^{1,p}(\Omega)} &\leq & C\left[\left(\frac{1}{2^{k+1}}\right)^{\frac{n-1}{p}}+ \left(\frac{1}{4^{k}}\right)^{\left(\frac{1}{(n-1)}+\frac{p}{q}\right)\frac{(n-1)}{p}}\right]
\end{eqnarray}
Since $\frac{1}{p}+\frac{n-1}{q}$ is positive, we get that
\begin{equation}\label{eqp}
         \|u_k\|_{W^{1,p}(\Omega)} \leq C\left[\left(\frac{1}{2^{k+1}}\right)^{\frac{n-1}{p}}\right]
\end{equation}
Let $T_t$ for $t\in \mathbb{R}$ be any hyperplane perpendicular to $\mathcal{C}_{k}$ that intersect and let $Eu_{k}$ be extension of $u_k$.
 By Sobolev embedding inequality, we have for a.e. $t\in \mathbb{R}$
\begin{equation}\label{eqpe}
    2^{\frac{-(k+2)(n-1)}{q_{n-1}^*}}\leq C_{n,q}\left(\int_{T_t}|\nabla Eu_k(x)|^qdx\right)^{\frac{1}{q}}
\end{equation}
where $q_{n-1}^*= \frac{q(n-1)}{(n-1-q)}.$\\
By using \eqref{eqpe}, we get that
\begin{equation}\label{eqpp}
   2^{\frac{-(k+2)(n-1)}{q_{n-1}^*}}\leq C_{n,q}\leq \|Eu_k\|_{W^{1,q}(\mathbb{R}^n)}. 
\end{equation}
 Combining \eqref{eqp} and \eqref{eqpp}, we get that
\begin{eqnarray}\label{meq}
\frac{\|Eu_{k}\|_{W^{1,q}(\mathbb{R}^n)}}{\|u_{k}\|_{W^{1,p}(\Omega)}}&\geq& C_{p,q,n}2^{-(k+2)\left(\frac{(n-1)}{q_{n-1}^\star}-\frac{(n-1)}{p}\right)}
\end{eqnarray}
For $p< q^\star_{n-1}$, \eqref{meq} tends to infinity as $k$ tends to infinity.
\begin{remark}
    If we consider the domain $\widetilde{\Omega}$ a slightly modification of the domain as constructed in \eqref{difdomain}. We will fix the cube $\mathcal{Q}_0$ and attach cylinders $\mathcal{C}_k$ to it such the the ratio of width and height of the cylinder goes to zero as $k$ goes to infinity. Then $\widetilde{\Omega}$ is not a $(W^{1,p}, W^{1,q})$ extension domain if $1\leq q <n-1$ and $p< \frac{q(n-1)}{(n-1-q)}$.  
\end{remark}
