	\includegraphics[width=.95\columnwidth]{tikz_2.pdf}
	\caption{\label{fig:kfold}K-fold-adapted illustration. The test set is next to the training set. For each round of the k-fold, the training and testing set is shifted by the exact size of the test set.}
\end{figure}

%For each fold, the model's performance is quantified by calculating the accuracy, defined as the proportion of correctly classified segments (TR or N) in the test set. The accuracy obtained for each fold is recorded, and at the end of the cross-validation process, the overall accuracy of the model is computed as the average of these $K$ accuracies. 

For each fold, the model's performance is quantified by calculating both the accuracy and recall. The accuracy is defined as the ratio of correctly classified segments (TR or N) to the total number of segments in the test set:
%
\begin{equation}
\text{Accuracy}_k = \frac{\mathrm{TP}_k + \mathrm{TN}_k}{\mathrm{TP}_k + \mathrm{TN}_k + \mathrm{FP}_k + \mathrm{FN}_k}
\end{equation}
%
where $\mathrm{TP}_k$ is the number of true positives (TR segments correctly classified as TR), $\mathrm{TN}_k$ is the number of true negatives (N segments correctly classified as N), $\mathrm{FP}_k$ is the number of false positives (N segments incorrectly classified as TR), and $\mathrm{FN}_k$ is the number of false negatives (TR segments incorrectly classified as N). 

While accuracy provides an overall measure of performance, it may be misleading in our case due to the dataset's imbalance. Specifically, the dataset contains significantly more N segments than TR segments, meaning that a model biased towards predicting the majority class (N) could achieve a high accuracy without effectively identifying TR segments. To address this limitation, we also compute recall, which is defined as the proportion of actual positive instances the model correctly identified. Mathematically, it is given by:
%
\begin{equation}
\text{Recall}_k = \frac{\mathrm{TP}_k}{\mathrm{TP}_k + \mathrm{FN}_k}.
\end{equation}
%
Recall measures the model's ability to capture all relevant instances, making it particularly important in scenarios where missing positive cases is costly, such as in medical diagnoses or fraud detection.
Both the accuracy and recall for each fold are recorded. At the end of the cross-validation process, the overall accuracy and recall of the model are computed as the averages of these $K$ metrics:
%
\begin{equation}
\text{Average Accuracy} \equiv \alpha = \frac{1}{K} \sum_{k=1}^K \text{Accuracy}_k,
\end{equation}
%
\begin{equation}
\text{Average Recall} \equiv \beta = \frac{1}{K} \sum_{k=1}^K \text{Recall}_k.
\end{equation}
%
Combining these metrics provides a more nuanced and reliable evaluation of the model's performance across all folds.


The CNN architecture used, illustrated in Fig. \ref{fig:cnn}, presents as input the sequences of states, from the time series, extracted as shown in Fig. \ref{fig:regimes}. The data flow through its different layers, in 8 steps, is as follows:
%
\begin{algorithm}[H]
\caption{\revision{CNN-Based Classification Procedure}}
\begin{algorithmic}[1]
\STATE \revision{\textbf{Input:} Regime window (a segment of a time series)}
\STATE \revision{\textbf{Step 1:} Apply convolution operations to extract local patterns.}
\STATE \revision{\textbf{Step 2:} Apply dropout to randomly disable neurons during training (regularization).}
\STATE \revision{\textbf{Step 3:} Apply max-pooling with a window size of 2 to reduce spatial dimensionality.}
\STATE \revision{\textbf{Step 4:} Flatten the pooled feature maps into a 1D vector.}
\STATE \revision{\textbf{Step 5:} Pass through a dense layer with 100 neurons using ReLU activation.}
\STATE \revision{\textbf{Step 6:} Pass through a dense layer with 1 neuron using Sigmoid activation (regression output).}
\STATE \revision{\textbf{Output:} Classify the output as ``Transition'' or ``Normal'' based on the predicted value.}
\end{algorithmic}
\end{algorithm}


