%\begin{eqnarray}\label{Eq: 4potential broadening}
%&&V(r) =\sum_V V_{R_M}(r)=\sum_{\gs} \Delta_{\gs} e^{i \gs \cdot \rr}\nonumber\\
%&&V_{\RR}(r) =\begin{cases} 
%\frac{\Delta_0 \Omega_0}{\pi a^2} &|\rr-%\RR|<a \\
%0 &|\rr-\RR|>a 
%\end{cases},
%\end{eqnarray}
%where \commentCXL{Define all the notation. }
%When potential radius $a$ goes to zero, the broadening potential recovers the form of $\delta$-function potential. The Fourier transform component $\Delta_{\gs}$ is reduced with increasing $|\gs|$, as shown in Fig. XXX \commentCXL{We need to show the dependence of $|\Delta_{\gs}|$ as a function of $|\gs|$. }. We may choose the cutoff $G_\Lambda$ with the value $|\Delta_{G_\Lambda}|=0.5\Delta_0$, and Fig.\ref{free e gas delta} (b) shows the evolution of $G_\Lambda$ as function of $a$.

Furthermore, we can also extract the eigen wavefunction form of the bound state from the above formalism. We denote the eigen wave function of $H_{2D}$ as $\ket{n}$, namely $H_{2D}\ket{n,\kk} = \mathcal{E}_n(\kk) \ket{n,\kk}$ with $\mathcal{E}_{n}(\kk)$ determined from Eq.(\ref{Eq:equation_poles}). One can show  
\begin{eqnarray}
\text{lim}_{E\rightarrow \mathcal{E}_n(\kk)}\bra{j} (E-H_{2D})^{-1}\ket{\phi_0}&=&\sum_{n'}\text{lim}_{E\rightarrow \mathcal{E}_n(\kk)}\bra{j} (E-H_{2D})^{-1}\ket{n',\kk}\langle n',\kk|\phi_0\rangle\nonumber\\
&\approx&\text{lim}_{E\rightarrow \mathcal{E}_n(\kk)} (E-\mathcal{E}_n(\kk))^{-1} \langle j|n,\kk\rangle \langle n,\kk|\phi_0\rangle
.\label{Eq:wavefunction 1d 0}
\end{eqnarray}
From Eq.(\ref{Eq:wavefunction 1d 0}), we have
\begin{eqnarray}
 \langle j | n,\kk \rangle \langle n,\kk | \phi_0 \rangle&=&\text{lim}_{E\rightarrow \mathcal{E}_n(\kk)}(E- \mathcal{E}_n(\kk))\bra{j} (E-H_{2D})^{-1}\ket{\phi_0}\nonumber\\
 &=&\text{lim}_{E\rightarrow \mathcal{E}_n(\kk)}\frac{1}{ \sqrt{N_g}}\frac{E- \mathcal{E}_n(\kk)}{1-\Delta_0 \mathbf{g}(\kk, E)}\frac{1}{E-E_j(\kk)},
  \label{Eq:wavefunction 1d}
\end{eqnarray}
where we have used Eq.(\ref{Eq:4 free gas delta}) in the last step. When $E\rightarrow\mathcal{E}_n$, Eq.(\ref{Eq:equation_poles}) should be satisfied so both the numerator $E- \mathcal{E}_n(\kk)$ and the denominator $1-\Delta_0 \mathbf{g}(\kk, E)$ in Eq.(\ref{Eq:wavefunction 1d}) are approaching zero. This limit can be evaluated via the L'Hospital's rule as
\begin{eqnarray} 
\text{lim}_{E\rightarrow \mathcal{E}_n(\kk)}\frac{E- \mathcal{E}_n(\kk)}{1-\Delta_0 \mathbf{g}(\kk, E)}&=&-\left.\frac{1}{\Delta_0\partial\mathbf{g}(\kk,E)/\partial E}\right|_{E=\mathcal{E}_n(\kk)}
= \frac{1}{\Delta_0\sum_{j'} (\mathcal{E}_n(\kk)-E_{j'}(\kk))^{-2}}.
  \label{Eq:limit wave}
\end{eqnarray}
 Although some $\mathcal{E}_n(\kk)$ are very close to $E_j(\kk)$, they are not equal, i.e., $\mathcal{E}_n(\kk) \neq E_j(\kk)$, as proven in Eq.~(\ref{Eq:6 free electron delta}). Therefore, the limit in Eq.(\ref{Eq:limit wave}) converges and 
\begin{eqnarray}\label{Eq:wavefunction 1d1}
\langle j | n,\kk \rangle \langle n,\kk | \phi_0 \rangle = \frac{1}{ \sqrt{N_g} } \frac{1}{\Delta_0\sum_{j'} (\mathcal{E}_n(\kk)-E_{j'}(\kk))^{-2}} \frac{1}{\mathcal{E}_n(\kk)-E_j(\kk)}. \\
 \langle j | n,\kk \rangle = \frac{1}{ \sqrt{N_g} \langle n,\kk | \phi_0 \rangle} \frac{1}{\Delta_0\sum_{j'} (\mathcal{E}_n(\kk)-E_{j'}(\kk))^{-2}} \frac{1}{\mathcal{E}_n(\kk)-E_j(\kk)}. \label{Eq:wavefunction 1d2}
\end{eqnarray}
In the last step, we divide $ \langle n,\kk | \phi_0 \rangle$ in both sides, which requires $\langle n,\kk | \phi_0 \rangle \neq 0$.
Supposing $\langle n,\kk | \phi_0 \rangle = 0$, we will have $H_{2D}\ket{n,\kk}=(H_0(\kk)+P_0)\ket{n,\kk}=H_0(\kk)\ket{n,\kk}$ using the form of $P_0$ in Eq.(\ref{Eq:projection0}). Since $\ket{n,\kk}$ is an eigenstate of $H_{2D}(\kk)$, e.g. $H_{2D}(\kk)\ket{n,\kk}=\mathcal{E}(k)\ket{n,k}$, we find $\mathcal{E}(k)$ has also to be an eigenstate of $H_0(\kk)$. However, we have previously proven any eigen-energy $E_j(\kk)$ of $H_0(\kk)$ is {\it not} a pole of $Tr(G)$ and thus cannot be an eigenstate of $H_{2D}$, and thus we find a contradiction, which means $\langle n,\kk | \phi_0 \rangle$ cannot be zero, $\langle n,\kk | \phi_0 \rangle\neq0$.  
We note that only $\frac{1}{\mathcal{E}_n(\kk)-E_j}$ depends on the index $j$, while the whole factor $\frac{1}{ \sqrt{N_g} \langle n,\kk | \phi_0 \rangle} \frac{1}{\Delta_0\sum_{j'} (\mathcal{E}_n(\kk)-E_{j'}(\kk))^{-2}}$ in front of $\frac{1}{\mathcal{E}_n(\kk)-E_j}$ in Eq.(\ref{Eq:wavefunction 1d2}) is independent of $j$ and thus just the normalization factor. Therefore, we can write the wavefunction as 
\begin{equation} \label{Eq:wavefunction 1d3}
    \langle j | n, \kk\rangle=N_{2D} \frac{1}{\mathcal{E}_n(\kk)-E_j(\kk)}
\end{equation} 
where $N_{2D}=\frac{1}{ \sqrt{N_g} \langle n,\kk | \phi_0 \rangle} \frac{1}{\Delta_0\sum_{j'} (\mathcal{E}_n(\kk)-E_{j'}(\kk))^{-2}}$ is regarded as the normalization factor. %\commentCXL{I'm still a bit confused about the behavior here. Basically, this form of the wavefunction says the amplitude in the $j$ component is determined by the factor $\frac{1}{\mathcal{E}_n(\kk)-E_j(\kk)}$ here. The larger energy difference $\mathcal{E}_n(\kk)-E_j(\kk)$, the smaller amplitude for that component. Since $E_j(\kk)$ is a power law function $|\kk+\gs_j|^2$, we would expect a power law decay in the real space as well. However, for a localized wavefunction, it should be exponential decay. How to understand that? Or do I miss any point?  }

We denote the localized eigen-wavefunction of the Hamiltonian in Eq.(\ref{Eq:H2DEG_momentum}) of bounded state as $\ket{0,\kk}$. For the wavefunction at $\mathbf{\Gamma}$, namely $\ket{0,\mathbf{\Gamma}}$, its real space form can be approximated as
% We approximate the wavefunction distribution at each $\kk$ by $\langle \rr|0,\kk\rangle\approx\langle \rr|0,\mathbf{\Gamma}\rangle$, and $\langle \rr|0,\mathbf{\Gamma}\rangle\approx\frac{1}{2\pi} \int \langle j|0,\mathbf{\Gamma}\rangle e^{i \gs_j\cdot \rr} d\gs_j$, 
\begin{eqnarray}
    \langle \rr|0,\mathbf{\Gamma}\rangle = \sum_j \langle j|0,\mathbf{\Gamma}\rangle e^{i \gs_j\cdot \rr}  \approx \frac{1}{\Omega_B} \int d\gs e^{i \gs \cdot \rr} \langle \gs|0,\mathbf{\Gamma}\rangle,
\end{eqnarray}
where we change the summation over the discrete $\gs_j$ to the integral over the continuous variable $\gs$. Using Eq.(\ref{Eq:wavefunction 1d2}), we find 
\begin{eqnarray}
   \langle \rr|0,\mathbf{\Gamma}\rangle = \frac{N_{2D}}{(2\pi)^2}\int\frac{1}{{\mathcal{E}_0(\mathbf{\Gamma})-\gs^2}}e^{i \gs\cdot \rr} d \gs = -N_{2D}K_0(\sqrt{-\mathcal{E}_0(\mathbf{\Gamma})} |\rr|),
\end{eqnarray}
where $K_0(\rr)$ is the modified Bessel function of the second kind. In the limit $|\rr| \gg 1$, the asymptotic behavior of $K_{0}(\rr)$ is given by 
$K_{0}(\rr) \approx \sqrt{\frac{\pi}{2|\rr|}}\;e^{-\sqrt{-\mathcal{E}_0(\mathbf{\Gamma})}|\rr|}$, thus corresponding to an exponentially localized wavefunction in periodic $\delta$-like-function.

From the above form (\ref{Eq:wavefunction 1d2}) of the eigen wavefunction, we also numerically examine the localized wavefunction form of the bound state, denoted as $\ket{0,\kk}$, for different values of the cut-off $G_\Lambda$ in  Fig.\ref{Fig: Wave_function_ delta}. Fig.\ref{Fig: Wave_function_ delta}(a)-(c) shows the moir\'e superlattice potential form for different cut-off values of $G_\Lambda$, from which one can see the confining potential becomes more and more similar to a $\delta$-function potential as  $G_\Lambda$ is increased. At the same time, the real space form of the bound state eigen wavefunction, denoted by $|\langle \rr|0,\mathbf{\Gamma}\rangle|^2$, also becomes more and more localized around 1a Wyckoff position of moir\'e unit cell with increasing $G_\Lambda$ in Fig.\ref{Fig: Wave_function_ delta}(d)-(f). Here we keep $\Delta_0=-0.05$. %\commentCXL{In the caption it says $\Delta_0=-0.05eV$. Should it be a positive or a negative number? }

