\subsection{Moir\'e Chern-band model with a periodic $\delta$-function potential} \label{section:delta chern band}
% \commentCXL{Can we change all the notation below to Chern-band model, rather than the positive $M_z$ block of the BHZ model? }
Now we apply the periodic $\delta$-function potential to the Chern-band model, and the full Hamiltonian is $H_{mC}$ in Eq.(\ref{Eq:HammC}) with the Chern-band Hamiltonian $H_{C}$ in Eq.(\ref{Eq:Ham_Chernband}). In the Sec.\ref{Sec:deltapotential_parabolicbands}, we have shown that for a small positive $\Delta_0$, the band dispersion around the conduction band bottom remains almost unchanged. Therefore, for the convenience of deriving a compact formalism, we apply the periodic $\delta$-function-like potential to both the conduction and valence bands with $\Delta_0>0$. $H_{m}$ is given by the periodic $\delta$-function-like  potential in Eq.(\ref{Eq:HM_delta_periodic}). 
%We expect a flat bounded state from valance (conduction) bands to construct heavy Fermion model.
%Since the Hamiltonian is block diagonal with two blocks possessing opposite z-directional mirror symmetry $M_z$ eigen-values, we only need to consider the block with $M_z = +i$ mirror eigen-value. 
In the momentum space, the full Hamiltonian reads
\begin{eqnarray}\label{Eq:HammC_delta_momentum}
&&H_{mC}(\kk) =H_0(\kk) + H_{\text{m}} = H_0(\kk) +N_g\Delta_0 P_0 \\
&&H_0(\kk)=\begin{pmatrix}
H_{C} (\kk + \gs_1)  & 0 & \dots& 0\\
0 & H_{C} (\kk + \gs_2) & \dots& 0\\
\vdots & \vdots & \ddots&  \vdots\\
0 & 0 & \dots & H_{C} (\kk + \gs_{N_g})
\end{pmatrix},
\end{eqnarray}
where $H_{C} (\kk)$ is a $2\times 2$ matrix defined in Eq.(\ref{Eq:Ham_Chernband}), $\gs_j$ is the moir\'e reciprocal lattice vectors within the momentum cut-off $G_\Lambda$ ($j = 1, 2,..., N_g$), and 
\begin{eqnarray} \label{eq_SM:P0_projector}
    P_0 = \ket{\phi_0}\bra{\phi_0} \otimes 1_{2\times2}
\end{eqnarray} is the projection operator with $\ket{\phi_0}$ defined in Eq.(\ref{Eq:projection0}) and  $1_{2\times 2}$ is the 2-by-2 identity matrix. 

Below we define $\ket{\phi_0,\alpha}=\ket{\phi_0}\otimes\ket{\alpha}$, with $\alpha = 1, 2$ indexing two orbital basis of $H_{C}$. The Moir\'e term can be written as $H_{\text{m}}=N_g\Delta_0  (\ket{\phi_0,1}\bra{\phi_0,1}+\ket{\phi_0,2}\bra{\phi_0,2})$. For the derivation below, we define $\ket{j,\alpha}$ as $\ket{j,\alpha}=\ket{j}\otimes\ket{\alpha}$ for $j$ indexing the moir\'e reciprocal lattice vector, so that we have  $\bra{j,\alpha}H_0(\kk)\ket{j',\beta}= H_{C}^{\alpha\beta}(\kk+\gs_j)\delta_{j'j}$. $\ket{j,\alpha}$ is independent of the momentum $\kk$.

The bare Green's function is defined by the matrix inverse
\begin{eqnarray}
    \hat{g}(\kk)=(E 1_{2N_g\times 2N_g}-H_{0}(\kk))^{-1}
\end{eqnarray}
and its component connecting the state $\ket{\phi_0,\alpha}$ and $\ket{\phi_0,\beta}$ is given by 
\begin{eqnarray}\label{Eq: bare GreenFunction_Relation_BHZ_0}
    \mathbf{g}^{0}_{\alpha,\beta}(\kk,E) = N_g\bra{\phi_0,\alpha}\hat{g}\ket{\phi_0,\beta} = N_g\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{0}(\kk))^{-1}\ket{\phi_0,\beta}. 
\end{eqnarray}

By using the form of $|\phi_0\rangle$ in Eq.(\ref{Eq:projection0}), we can further define the matrix form $\mathbf{g}(k,E)$ as 
\begin{eqnarray}
    \mathbf{g}(\kk, E)=\sum_j \mathbf{g}^0(\kk+\gs_j, E), 
\end{eqnarray}
where
\begin{eqnarray}
   \mathbf{g}^0(\kk+\gs_j, E)=\frac{1}{E 1_{2\times 2}-H_{C}(\kk+\gs_j)}
\end{eqnarray}
is a $2\times 2$ matrix. The full Green's function is defined as 
\begin{eqnarray}
    G = (E 1_{2N_g\times 2N_g}-H_{mC}(\kk))^{-1}
\end{eqnarray}
and its component connecting the state $\ket{\phi_0,\alpha}$ and $\ket{\phi_0,\beta}$ is given by 
\begin{eqnarray}\label{Eq:GreenFunction_Relation_0_BHZ}
    N_g \bra{\phi_0,\alpha}G\ket{\phi_0,\beta} &=& N_g\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{0}(\kk)-H_{\text{m}})^{-1}\ket{\phi_0,\beta}\nonumber\\&=&N_g\bra{\phi_0,\alpha}(1_{2N_g\times 2N_g}-(E 1_{2N_g\times 2N_g}-H_{0}(\kk))^{-1}H_{\text{m}})^{-1}(E 1_{2N_g\times 2N_g}-H_{0}(\kk))^{-1}\ket{\phi_0,\alpha}\nonumber\\
    &=&N_g\bra{\phi_0,\alpha}\sum^\infty_{n=0} (\hat{g}(\kk)H_{\text{m}})^n\hat{g}(\kk)\ket{\phi_0,\beta}\nonumber\\
    &=&N_g\sum^\infty_{n=0}\sum_{i,\gamma} \bra{\phi_0,\alpha}(\hat{g}(\kk)H_{\text{m}})^n\ket{\phi_i,\gamma}\bra{\phi_i,\gamma}\hat{g}(\kk)\ket{\phi_0,\beta},
    \end{eqnarray}
where $\alpha, \beta, \gamma = 1, 2$ and $\phi_i$ indexing a complete set of basis wavefunction with $\phi_{i=0}$ given by Eq.(\ref{Eq:projection0}).
In Eq.(\ref{Eq:GreenFunction_Relation_0_BHZ}), we have
\begin{eqnarray}\label{Eq:GreenFunction_Relation_02_BHZ}
\bra{\phi_0,\alpha}(\hat{g}(k)H_{\text{m}})^n\ket{\phi_i,\gamma}&=&\sum_j\sum_{\gamma'}\dots\sum_k\sum_{\gamma''}\bra{\phi_0,\alpha}\hat{g}(\kk)H_{\text{m}}\ket{\phi_j,\gamma'}\bra{\phi_j,\gamma'}\dots\ket{\phi_k,\gamma''}\bra{\phi_k,\gamma''}\hat{g}(\kk)H_{\text{m}}\ket{\phi_i,\gamma}\nonumber\\
&=&\Delta_0^n[\mathbf{g}^{n}(\kk,E)]_{\alpha,\gamma}\delta_{i,0},
\end{eqnarray}
where we have used the form $H_{\text{m}} = N_g \Delta_0 P_0$ with $P_0$ given by Eq.(\ref{eq_SM:P0_projector}) in deriving the last step. Substituting Eq.(\ref{Eq:GreenFunction_Relation_02_BHZ}) into Eq.(\ref{Eq:GreenFunction_Relation_0_BHZ}), we get
\begin{eqnarray}\label{Eq:GreenFunction_Relation_1_BHZ}
N_g \bra{\phi_0,\alpha}G\ket{\phi_0,\beta} &=&\sum^\infty_{n=0}\sum_\gamma \Delta^n_1[\mathbf{g}^n(\kk,E)]_{\alpha,\gamma}\mathbf{g}(\kk,E)_{\gamma,\beta}\nonumber\\
&=& \sum_\gamma (1_{2\times 2} -\Delta_0 \mathbf{g}(\kk,E))^{-1}_{\alpha,\gamma} [\mathbf{g}(\kk,E)]_{\gamma,\beta}
\end{eqnarray}
The corresponding $2\times 2$ matrix form can be written as
\begin{eqnarray}\label{Eq:GreenFunction_Relation_1_BHZ_matrix}
N_g \bra{\phi_0}G\ket{\phi_0} &=&\sum^\infty_{n=0}\Delta_0^n\mathbf{g}^n(\kk,E)\mathbf{g}(\kk,E)\nonumber\\
&=&(1_{2\times 2} -\Delta_0 \mathbf{g}(\kk,E))^{-1}\mathbf{g}(\kk,E).
\end{eqnarray}
Eq.(\ref{Eq:GreenFunction_Relation_1_BHZ_matrix}) is the generalization of Eq.(\ref{Eq:GreenFunction_Relation_1}) to the moir\'e Chern-band model.

We further introduce the projection operator 
\begin{eqnarray}
\PP_{\kk+\gs_j, \eta}=\ket{\kk+\gs_j,\eta}\bra{\kk+\gs_j,\eta}, 
\end{eqnarray}
where $\ket{\kk+\gs_j,\eta}$ is the eigenstate of $H_{C}(\kk+\gs_j)$, 
\begin{eqnarray}\label{Eq:HamC_eigen_basis}
H_{C}(\kk+\gs_j)\ket{\kk+\gs_j,\eta}=E_{\eta}(\kk+\gs_j)\ket{\kk+\gs_j,\eta}
\end{eqnarray}
with $\eta = 1, 2$ labelling two eigenstates. The project operator can be written in the Pauli matrix form, 
\begin{eqnarray}\label{Eq: Projection Pauli} 
&&\PP_{\kk,\eta}=\sum^3_{i=0}d^{\eta}_{i,\kk}\sigma_i\nonumber\\
&&d^{\eta}_{0,\kk}=\frac{1}{2}; d^{\eta}_{1,\kk}=\frac{\eta A k_x}{2 D_{0\kk}};d^{\eta}_{2,\kk}=\frac{-\eta  Ak_y}{2 D_{0\kk}};d^{\eta}_{3,\kk}=\frac{\eta\mathcal{M}(\kk)}{2 D_{0\kk}},\nonumber\\
&& D_{0\kk}=\sqrt{\mathcal{M}^2(\kk)+A^2 k^2}
\end{eqnarray}
for the Chern-band model Hamiltonian $H_C$ in Eq.(\ref{Eq:Ham_Chernband}). With the projection operator, we can rewrite 
\begin{eqnarray}\label{Eq:freeGreenFunction_BHZ}
    \mathbf{g}^0(\kk+\gs_j, E) = \sum_{\eta} \frac{\PP_{\kk+\gs_j,\eta}}{E-E_{\eta}(\kk+\gs_j)};  \quad \mathbf{g}(\kk, E)=\sum_j \mathbf{g}^0(\kk+\gs_j, E). 
\end{eqnarray}

We next need to find the trace of the full Green's function. We start with  \begin{eqnarray}\label{Eq:identity BHZ}
    &&[E 1_{2N_g\times 2N_g} -H_0-N_g\Delta_0  P_0](E 1_{2N_g\times 2N_g}-H_{mC})^{-1} =  (E 1_{2N_g\times 2N_g} - H_{mC})^{-1}[E 1_{2N_g\times 2N_g}-H_0-N_g\Delta_0  P_0]\nonumber \\
    &&=1_{2N_g\times 2N_g}
\end{eqnarray}
Using Eq.(\ref{Eq:identity BHZ}), we have
\begin{eqnarray}\label{Eq:alphaj BHZ 1}
   &&\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g} - H_{mC})^{-1}(E 1_{2N_g\times 2N_g} -H_0)\ket{j, \beta}-\sum^2_{\gamma=1}N_g\Delta_0\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1}\ket{\phi_0,\gamma}\langle \phi_0,\gamma | j,\beta \rangle\nonumber \\
   && =\langle \phi_0,\alpha | j,\beta \rangle.
\end{eqnarray}  
We insert the identity $1 = \sum_{j', \gamma}\ket{j',\gamma}\bra{j',\gamma}$ into the first term of Eq.(\ref{Eq:alphaj BHZ 1}) and obtain
\begin{eqnarray}
 &&\sum_{j',\gamma}\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1}\ket{j',\gamma}\bra{j',\gamma}(E 1_{2N_g\times 2N_g}-H_0)\ket{j,\beta}\nonumber \\
 && =\sum^2_{\gamma=1}\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1} \ket{j,\gamma}(E \delta_{\beta \gamma} - H^{\gamma\beta}_{C}(\kk+\gs_j)).
\end{eqnarray} 
Therefore, Eq.(\ref{Eq:alphaj BHZ 1}) changes to 
\begin{eqnarray}
    && \sum^2_{\gamma=1}\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1} \ket{j,\gamma}(E \delta_{\beta \gamma} - H^{\gamma\beta}_{C}(\kk+\gs_j)) = \nonumber \\
    && \langle \phi_0,\alpha | j,\beta \rangle + \sum^2_{\gamma=1}N_g\Delta_0\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1}\ket{\phi_0,\gamma}\langle \phi_0,\gamma | j,\beta \rangle . \label{alphaj BHZ 1 component}
\end{eqnarray}

We can further simplify Eq.(\ref{alphaj BHZ 1 component}) by the matrix inverse,
\begin{eqnarray}
    && \sum^2_{\beta,\gamma=1}\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1} \ket{j,\gamma}(E 1_{2\times2} - H_{C}(\kk+\gs_j))_{\gamma,\beta}(E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta}  \nonumber \\
    && =\sum^2_{\beta=1}\left(\frac{\delta_{\alpha,\beta}}{\sqrt{N_g}}+\sum^2_{\gamma=1}N_g\Delta_0\bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1}\ket{\phi_0,\gamma}\frac{\delta_{\gamma,\beta}}{\sqrt{N_g}}\right)(E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta},  \nonumber
    \end{eqnarray}

 so that
    \begin{eqnarray}
     && \bra{\phi_0,\alpha}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1} \ket{j,\eta} =\frac{1}{\sqrt{N_g}} \sum^2_{\beta=1} ( \delta_{\alpha,\beta} +N_g\Delta_0\bra{\phi_0,\alpha}G\ket{\phi_0,\beta} ) (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta} \nonumber \\
     && = \frac{1}{\sqrt{N_g}} \sum^2_{\beta=1} ( \delta_{\alpha,\beta} +\sum_\gamma (1_{2\times 2} - \Delta_0 \mathbf{g}(\kk,E))^{-1}_{\alpha,\gamma} [\Delta_0 \mathbf{g}(\kk,E)]_{\gamma,\beta}) (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta} \nonumber \\
     && = \frac{1}{\sqrt{N_g}} \sum^2_{\beta=1} (1_{2\times 2} - \Delta_0 \mathbf{g}(\kk,E))^{-1}_{\alpha,\beta}  (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta}, 
     \label{alphaj BHZ 2 component}
\end{eqnarray}
where we have used $\langle\phi_0, \alpha|j, \beta\rangle=\frac{1}{\sqrt{N_g}} \delta_{\alpha\beta}$ and Eq.(\ref{Eq:GreenFunction_Relation_1_BHZ_matrix}). The above expression can be rewritten into a $2\times 2$ matrix form
\begin{eqnarray} \label{Eq:alphaj BHZ 1 Matrix} 
&& \bra{\phi_0}(E 1_{2N_g\times 2N_g} -H_{mC})^{-1}\ket{j}= \frac{1}{\sqrt{N_g}} (1_{2\times 2} - \Delta_0 \mathbf{g}(\kk,E))^{-1}  (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}. \label{Eq:alphaj BHZ 2 Matrix} 
\end{eqnarray}
Eq.(\ref{alphaj BHZ 2 component}) can be regarded as a generalization of Eq.(\ref{Eq:4 free gas delta}) to the moir\'e Chern-band model. 

We next generalize Eq.(\ref{Eq:2 free gas delta}) as
\begin{eqnarray} \label{Eq: JJ BHZ 1}
&& \bra{j,\alpha} \left[E 1_{2N_g\times 2N_g} -H_0- \sum^2_{\gamma=1}N_g\Delta_0\ket{\phi_0,\gamma}\bra{\phi_0,\gamma}\right](E 1_{2N_g\times 2N_g}-H_{mC})^{-1}\ket{j,\beta}=\delta_{\alpha,\beta}\nonumber\\
\end{eqnarray}
which can be simplified as
% The matrix form of Eq.(\ref{Eq: JJ BHZ 1}) is
% \begin{eqnarray}
%   && \bra{j} [E 1_{2N_g\times 2N_g} -H_0-N_g\Delta_0\ket{\phi_0}\bra{\phi_0}](E-H_{mC})^{-1}\ket{j}=1_{2\times2} \label{Eq: JJ BHZ 1 matrix}
% \end{eqnarray}
% Combining Eq.(\ref{Eq: JJ BHZ 1}) and Eq.(\ref{alphaj BHZ 2 component}) lead to
\begin{eqnarray} \label{Eq:2d generalization SC16}
&&\sum^{2}_{\gamma=1}\sum_{j'}\bra{j,\alpha} (E 1_{2N_g\times 2N_g} -H_0)\ket{j',\gamma}\bra{j',\gamma}(E 1_{2N_g\times 2N_g} -H_{mC})^{-1}\ket{j,\beta} = \nonumber \\
&& \delta_{\alpha,\beta}+ \sum^2_{\gamma=1}N_g\Delta_0\langle j,\alpha|\phi_0,\gamma\rangle\bra{\phi_0,\gamma}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1}\ket{j,\beta},
\nonumber\\
&&\sum_\gamma(E 1_{2\times 2} -H_{C}(\kk+\gs_j))_{\alpha\gamma} \bra{j,\gamma} (E 1_{2N_g\times 2N_g} -H_{mC})^{-1}\ket{j,\beta} = \nonumber \\
&& \delta_{\alpha,\beta}+\sum_{\eta}\Delta_0 (1_{2\times2}-\Delta_0 \mathbf{g}(\kk,E))^{-1}_{\alpha\eta}(E 1_{2\times 2} -H_{C}(\kk+\gs_j))^{-1}_{\eta\beta},
\end{eqnarray}
where we have used Eq.(\ref{alphaj BHZ 2 component}) to simplify the right side of the first equation in Eq.(\ref{Eq:2d generalization SC16}). With matrix inversion, we find
\begin{eqnarray}
    &&\bra{j,\gamma} (E 1_{2N_g\times 2N_g} -H_{mC})^{-1}\ket{j,\beta}=(E 1_{2\times 2} -H_{C}(\kk+\gs_j))^{-1}_{\gamma\beta} +\nonumber\\
&&\sum_{\eta,\alpha} (E 1_{2\times 2} - H_{C}(\kk+\gs_j))^{-1}_{\gamma\alpha}\Delta_0 (1_{2\times2}-\Delta_0 \mathbf{g}(\kk,E))^{-1}_{\alpha\eta}(E-H_{C}(\kk+\gs_j))^{-1}_{\eta\beta}.
\label{Eq:trace BHZ delta comp}
\end{eqnarray}
The matrix form of Eq.(\ref{Eq:trace BHZ delta comp}) is 
\begin{eqnarray}
&& \bra{j} (E 1_{2N_g\times 2N_g} -H_{mC}(\kk))^{-1}\ket{j}=\frac{1}{E 1_{2\times 2}-H_{C}(\kk+\gs_j)}+\frac{\Delta_0}{E 1_{2\times 2}-H_{C}(\kk+\gs_j)}\frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}\frac{1}{E 1_{2\times 2}-H_{C}(\kk+\gs_j)}.\nonumber \\\label{Eq:trace BHZ delta0}
\end{eqnarray}
By summing over $j$ on both sides, we get the trace of the full Green's function
\begin{eqnarray}
&& Tr(G) = Tr_{\sigma}\left(\sum_j \bra{j} (E 1_{2N_g\times 2N_g} -H_{mC}(\kk))^{-1}\ket{j}\right)  \nonumber \\
&& = Tr_{\sigma}\left(\mathbf{g}(\kk,E)+\sum_j\frac{\Delta_0}{E 1_{2\times 2}-H_{C}(\kk+\gs_j)}\frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}\frac{1}{E 1_{2\times 2}-H_{C}(\kk+\gs_j)}\right) \nonumber \\
&& = Tr_{\sigma}\left(\mathbf{g}(\kk,E)+\Delta_0 \sum_j \mathbf{g}^0(\kk+\gs_j, E) \frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)} \mathbf{g}^0(\kk+\gs_j, E)\right),\label{Eq:trace BHZ delta}
\end{eqnarray}
where $Tr_{\sigma}$ is taken for the $2\times 2$ matrices.
Eq.(\ref{Eq:trace BHZ delta}) can be viewed as the generalization of Eq.(\ref{Eq:5 free e delat}).

We next would like to identify the poles of $Tr(G)$. We will first show the poles of $\mathbf{g}(\kk,E)$ are {\it not} the poles of $Tr(G)$. From Eq.(\ref{Eq:freeGreenFunction_BHZ}), 
% One type of possible poles is the pole of $\mathbf{g}(E)$, another is  the pole of $\frac{1}{1-\Delta_0 \mathbf{g}(E)}$. 
the pole of $\mathbf{g}(\kk,E)$ is given by $E=E_{\eta}(\kk+\gs_j)$. When $E = E_{\eta}(\kk+\gs_j) + \delta E$ with $\delta E \rightarrow 0$, we only need to keep the divergent terms so that 
\begin{eqnarray}
    \mathbf{g}(\kk, E) \approx \mathbf{g}^0(\kk+\gs_{j}, E) \approx \frac{\PP_{\kk+\gs_j,\eta}}{\delta E}
\end{eqnarray}
and  $Tr(G)$ is approximated by 
\begin{eqnarray}
\lim_{E\rightarrow E_{\eta}(\kk+\gs_j)} Tr_{\sigma}(G) &\approx&
\lim_{\delta E\rightarrow 0} Tr_{\sigma}\left[ \frac{\PP_{\kk+\gs_j,\eta}}{\delta E} + \Delta_0 \frac{\PP_{\kk+\gs_j,\eta}}{\delta E} (1_{2\times 2} - \Delta_0 \frac{\PP_{\kk+\gs_j,\eta}}{\delta E})^{-1} \frac{\PP_{\kk+\gs_j,\eta}}{\delta E} \right]\nonumber\\
&= &\lim_{\delta E\rightarrow0} Tr_{\sigma}\left[\frac{\PP_{\kk+\gs_j, \eta}}{\delta E}\cdot \left(1_{2\times 2} + (\delta E 1_{2\times 2} -\Delta_0 \PP_{\kk+\gs_j, \eta})^{-1}\Delta_0 \PP_{\kk+\gs_j, \eta}\right)\right]\nonumber\\
& =&\lim_{\delta E\rightarrow 0}Tr_{\sigma}\left[\PP_{\kk+\gs_j, \eta}\cdot(\delta E 1_{2\times 2}-\Delta_0 \PP_{\kk+\gs_j, \eta}
)^{-1}\right]\nonumber\\
& =& \lim_{\delta E\rightarrow0}Tr_{\sigma} \left[\frac{(\sum^3_{i=0} d^{\eta}_{i,\kk+\gs_j}\sigma_i)[(\delta  E-\Delta_0d^{\eta}_{0,\kk+\gs_j})\sigma_0+\sum^3_{i=1} \Delta_0d^{\eta}_{i,\kk+\gs_j}\sigma_i]}{(\delta E-\Delta_0 d^{\eta}_{0,\kk+\gs_j})^2-\sum^3_{i=1} (\Delta_0 d^{\eta}_{i,\kk+\gs_j})^2} \right]\nonumber\\& =&\lim_{\delta E\rightarrow0}2\frac{d^{\eta}_{0,\kk+\gs_j}(\delta  E-\Delta_0d^{\eta}_{0,\kk+\gs_j})+\sum^3_{i=1} \Delta_0(d^{\eta}_{i,\kk+\gs_j})^2}{(\delta E-\Delta_0 d^{\eta}_{0,\kk+\gs_j})^2-\sum^3_{i=1} (\Delta_0 d^{\eta}_{i,\kk+\gs_j})^2}.
\label{Eq:8}
    \end{eqnarray}
From Eq.(\ref{Eq: Projection Pauli}), we know $(d^{\eta}_{0,\kk+\gs_j})^2-\sum^3_{i=1}(d^{\eta}_{i,\kk+\gs_j})^2=0$, so that 
\begin{eqnarray}
\lim_{E\rightarrow E_{\eta}(\kk+\gs_j)} Tr(G) &\approx &\lim_{\delta E\rightarrow 0}\frac{2 d^{\eta}_{0,\kk+\gs_j}\delta E}{-2d^{\eta}_{0,\kk+\gs_j}\Delta_0\delta E+(\delta E)^2}\approx -\frac{1}{\Delta_0}.
\label{Eq:BHZ trace0}
\end{eqnarray}
Thus, we have proven that the pole of $\mathbf{g}(\kk, E)$ is {\it not} the pole of $Tr(G)$ for any finite $\Delta_0$. Eq.(\ref{Eq:BHZ trace0}) is the generalization of Eq.(\ref{Eq:6 free electron delta}), and we get the same conclusion as that in 2D free electron gas with periodic $\delta$-function potential.  
Since we can always choose any complete set of basis wavefunction for the computation of the trace, we have $Tr(\PP_{\kk+\gs_j, \eta}) = 1$ and 
\begin{eqnarray} \label{Eq: BHZ trace 1}
Tr(G) &=& Tr\left(\mathbf{g}(\kk,E)\right)+\Delta_0 \sum_j Tr\left( \mathbf{g}^0(\kk+\gs_j, E) \frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)} \mathbf{g}^0(\kk+\gs_j, E)\right)\nonumber \\
&=&  \sum_{j, \eta} \frac{1}{E-E_{\eta}(\kk+\gs_j)} + \Delta_0 \sum_{j,\eta}  \frac{1}{(E -E_\eta(\kk+\gs_j))^2}\bra{\kk+\gs_j,\eta}\frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}\ket{\kk+\gs_j,\eta},
\end{eqnarray}
in which we use the basis function $\ket{\kk+\gs_j,\eta}$ defined in Eq.(\ref{Eq:HamC_eigen_basis}). 



