As $E_\eta(\kk+\gs_j)$ is not a pole of $Tr(G)$, the poles of $Tr(G)$ can only come 
% We approved $\mathcal{E}_n\neq E_\eta(\kk+\gs_j)$, so that the divergence only comes 
from $\bra{\kk+\gs_j,\eta}\frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}\ket{\kk+\gs_j,\eta}$. Without losing generality, ${1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}$ and $\frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}$ can be expressed as 
\begin{eqnarray}
    {1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}=\sum^3_{i=0}\mathbf{\hat{g}}^i(\kk,E)\sigma_i;\quad \frac{1}{1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}=\frac{\mathbf{\hat{g}}^0(\kk,E)\sigma_0-\sum^3_{i=1}\mathbf{\hat{g}}^i(\kk,E)\sigma_i}{Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}. \label{Eq:inverse_poleequation}
\end{eqnarray}
Here we expand the 2-by-2 matrix of the expression ${1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E)}$ into the basis of identity matrix and Pauli matrices with the expansion coefficients defined as $\mathbf{\hat{g}}^i(\kk,E)$. Therefore, the poles of $Tr(G)$ is given by 
\begin{eqnarray} \label{Eq: BHZ E 0}
Det(1_{2\times 2}-\Delta_0 \mathbf{g}(\kk,\mathcal{E}_n))=0,
\end{eqnarray}
from which we can solve the full energy spectrum $\mathcal{E}_n(\kk)$ of our model. 

Finally, we will generalize the derivation of Eq.(\ref{Eq:wavefunction 1d}) to solve the eigen-wavefunctions. For the eigen-energy $\mathcal{E}_n(\kk)$, we consider
\begin{eqnarray}
\lim_{E\rightarrow \mathcal{E}_n(\kk)}\bra{j,\beta} (E 1_{{2N_g\times 2N_g}}-H_{mC})^{-1}\ket{\phi_0,\alpha}=\lim_{E\rightarrow \mathcal{E}_n(\kk)}(E - \mathcal{E}_n(\kk) )^{-1}\langle j,\beta | n, \kk \rangle \langle n, \kk | \phi_0,\alpha \rangle,\label{Eq:wavefunction BHZ1}
\end{eqnarray}
where $\ket{n, \kk}$ is the eigenstate of $H_{mC}$ defined as $H_{mC}(\kk)\ket{n,\kk}=\mathcal{E}_n(\kk)\ket{n, \kk}$.

On the other hand, the Hermitian conjugation of Eq.(\ref{Eq:alphaj BHZ 2 Matrix}) gives
\begin{eqnarray}
  &&\bra{j,\beta}(E 1_{2N_g\times 2N_g}-H_{mC})^{-1} \ket{\phi_0,\alpha} =\frac{1}{\sqrt{N_g}} \sum^2_{\eta=1} (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta} (1_{2\times 2} - \Delta_0 \mathbf{g}(\kk,E))^{-1}_{\eta, \alpha}. 
  \label{wavebhz0}
\end{eqnarray}
% The matrix form of Eq.(\ref{wavebhz0}) is 
% \begin{eqnarray}
%   &&\bra{j}(E 1_{2N_g\times 2N_g} -H_{mC})^{-1}\ket{\phi_0}=\frac{1}{\sqrt{N_g}}(E 1_{2\times 2} -H_{C}(k+\gs_j))^{-1} (1_{2\times 2}+N_g\Delta_0\bra{\phi_0}G\ket{\phi_0}) .\label{wavebhz0 matrix}
% \end{eqnarray}

Comparing Eq.(\ref{Eq:wavefunction BHZ1}) with Eq.(\ref{wavebhz0}), we find
\begin{eqnarray}
&& \langle j,\beta | n, \kk \rangle \langle n, \kk | \phi_0,\alpha\rangle=lim_{E\rightarrow \mathcal{E}_n(\kk)}(E- \mathcal{E}_n(\kk))\bra{j,\beta} (E 1_{{2N_g\times 2N_g}}-H_{mC})^{-1}\ket{\phi_0,\alpha}\nonumber\\
&=&lim_{E\rightarrow \mathcal{E}_n(\kk)}(E- \mathcal{E}_n(\kk))
\frac{1}{\sqrt{N_g}} \sum^2_{\eta=1} (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta} (1_{2\times 2} - \Delta_0 \mathbf{g}(\kk,E))^{-1}_{\eta, \alpha}
\label{Eq:wavefunction BHZ2}
\end{eqnarray}



In the limit $E\rightarrow \mathcal{E}_n(\kk)$, both $E- \mathcal{E}_n(\kk)$ and $Det(1_{2\times 2} - \Delta_0 \mathbf{g}(\kk,E))$ equal to zero, so we need to use the L'Hospital's rule to take the limit as
\begin{eqnarray}
&& \langle j,\beta | n, \kk \rangle \langle n, \kk | \phi_0,\alpha\rangle
= \lim_{E\rightarrow \mathcal{E}_n(\kk)}(E- \mathcal{E}_n(\kk))
\frac{1}{\sqrt{N_g} } \sum^2_{\eta=1} (E 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}_{\beta,\eta} \left[\frac{\mathbf{\hat{g}}^0(\kk,E)\sigma_0-\sum^3_{i=1}\mathbf{\hat{g}}^i(\kk,E)\sigma_i}{Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right]_{\eta, \alpha} \nonumber \\
&& = \frac{1}{\sqrt{N_g}} \left[\frac{1}{\partial_E Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right]_{E\rightarrow \mathcal{E}_n(\kk)} \left[(\mathcal{E}_n(\kk) 1_{2\times2}- H_{C}(\kk+\gs_j))^{-1}(\mathbf{\hat{g}}^0(\kk,\mathcal{E}_n(\kk))\sigma_0-\sum^3_{i=1}\mathbf{\hat{g}}^i(\kk,\mathcal{E}_n(\kk))\sigma_i)\right]_{\beta, \alpha} \nonumber \\
&& = \frac{1}{\sqrt{N_g} } \left[\frac{1}{\partial_E Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right]_{E\rightarrow \mathcal{E}_n(\kk)} \sum_{\eta} \frac{\left[\PP_{\kk+\gs_j,\eta}(\mathbf{\hat{g}}^0(\kk,\mathcal{E}_n(\kk))\sigma_0-\sum^3_{i=1}\mathbf{\hat{g}}^i(\kk,\mathcal{E}_n(\kk))\sigma_i)\right]_{\beta, \alpha} }{\mathcal{E}_n(\kk) -E_{\eta}(\kk+\gs_j)} \nonumber \\
&& = \frac{1}{\sqrt{N_g} } \left[\frac{1}{\partial_E Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right]_{E\rightarrow \mathcal{E}_n(\kk)} \mathcal{F}^{\beta,\alpha}(\kk,\gs_j), \label{Eq:wave function delta BHZ}
\end{eqnarray}
where $\mathcal{F}^{\beta,\alpha}(\kk,\gs_j) =\sum_{\eta} \frac{\left[\PP_{\kk+\gs_j,\eta}(\mathbf{\hat{g}}^0(\kk,\mathcal{E}_n(\kk))\sigma_0-\sum^3_{i=1}\mathbf{\hat{g}}^i(\kk,\mathcal{E}_n(\kk))\sigma_i)\right]_{\beta, \alpha} }{\mathcal{E}_n(\kk) -E_{\eta}(\kk+\gs_j)} $. 
%The factor $\frac{1}{\sqrt{N_g} \langle n, \kk | \phi_0,\alpha\rangle} \left[\frac{1}{\partial_E Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right]_{E\rightarrow \mathcal{E}_n(\kk)} $ is independent of the indices $j$ and $\beta$ and thus just plays the role of a normalization factor, while the projection of the eigen-wavefunction into the basis $|j, \beta\rangle$ is determined by $\sum_{\eta} \frac{\left[\PP_{\kk+\gs_j,\eta}(\mathbf{\hat{g}}^0(\kk,\mathcal{E}_n(\kk))\sigma_0-\sum^3_{i=1}\mathbf{\hat{g}}^i(\kk,\mathcal{E}_n(\kk))\sigma_i)\right]_{\beta, \alpha} }{\mathcal{E}_n(\kk) -E_{\eta}(\kk+\gs_j)} $.  

Since $\langle n,\kk | \phi_0,\alpha\rangle$ at the left side of Eq.(\ref{Eq:wave function delta BHZ}) is independent of $j, \beta$ and the states $\ket{j,\beta}$ form a complete set of basis wavefunctions, we can take the norm for both sides and the sum over both $j$ and $\beta$ and obtain \begin{eqnarray}
&& \sum_{j,\beta}|\langle j,\beta | n, \kk \rangle |^2|\langle n, \kk | \phi_0,\alpha\rangle |^2= \frac{1}{N_g } \left[\frac{1}{\partial_E Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right]^2_{E\rightarrow \mathcal{E}_n(\kk)} \sum_{j,\beta} |\mathcal{F}^{\beta,\alpha}(\kk,\gs_j) |^2\\
&& |\langle n, \kk | \phi_0,\alpha\rangle| = \frac{1}{\sqrt{N_g} } \left|\frac{1}{\partial_E Det (1_{2\times 2}-\Delta_0\mathbf{g}(\kk,E))}\right|_{E\rightarrow \mathcal{E}_n(\kk)} \sqrt{\sum_{j,\beta} |\mathcal{F}^{\beta,\alpha}(\kk,\gs_j) |^2},\label{Eq:wave function delta BHZ2}
\end{eqnarray}
where we use $\sum_{j,\beta}|\langle j,\beta | n, \kk \rangle |^2=1$ as $\ket{j,\beta}$ is a complete set of basis. 

With Eqs.(\ref{Eq:wave function delta BHZ}) and (\ref{Eq:wave function delta BHZ2}), we can derive the form of $\langle j,\beta | n, \kk \rangle$ up to a phase factor for any $j, \beta$ once $\langle n,\kk | \phi_0,\alpha\rangle\neq 0$. Below we will show that there must exist at least one $\alpha$ to satisfy $\langle n,\kk | \phi_0,\alpha\rangle\neq 0$. To see that we can assume $\langle n,\kk | \phi_0, \alpha \rangle = 0$ for both $\alpha = 1, 2$, and from Eq.(\ref{eq_SM:P0_projector}), we have 
\begin{eqnarray} \label{Eq: nozero delta}
    H_{mC}(\kk) \ket{n,\kk}=H_{0}(\kk) \ket{n,\kk}=\mathcal{E}_n(\kk) \ket{n,\kk}.
\end{eqnarray}  
Eq.(\ref{Eq: nozero delta}) indicates that  $\mathcal{E}_n(\kk)$ is the eigenvalue of $H_{0}(\kk)$. However, we have proven that the pole of $\mathbf{g}(\kk, E)$ is {\it not} the pole of $Tr(G)$ for any finite $\Delta_0$ in the above and thus we find a contradiction, which means there must be one $\alpha$ with non-zero $\langle n,\kk | \phi_0, \alpha \rangle$. By substituting Eq.(\ref{Eq:wave function delta BHZ2}) into Eq.(\ref{Eq:wave function delta BHZ}), we find 
\begin{eqnarray}
\langle j, \beta | n,\kk\rangle=\frac{\mathcal{F}^{\beta,\alpha}(\kk,\gs_j)}{\sqrt{\sum_{j,\beta} |\mathcal{F}^{\beta,\alpha}(\kk,\gs_j) |^2}}    
\end{eqnarray}
for any $j, \beta$, thus solving the form of the eigen-wavefunction $|n,\kk\rangle$. Here, we have chosen the phase factor of $\langle n,\kk | \phi_0, \alpha \rangle$ to be zero.
For $H_{mC}(\kk)$ in Eq.(\ref{Eq:HammC_delta_momentum}), we denote the wave function of the VB1 band at the $\mathbf{\Gamma}$ point as $\ket{\text{VB1}, \mathbf{\Gamma}}$ and the spatial distribution, namely $|\langle\mathbf{r}\mid VB1, \mathbf{\Gamma} \rangle|^2$. Under the $\delta$-function-like potential shown in Fig.\ref{Fig: Wave_function_delta_BHZ}(a) and (b) for different values of $G_\Lambda$ can be computed and shown in Fig.\ref{Fig: Wave_function_delta_BHZ}(c) and (d). We find that, similar to the case of a free electron gas in a $\delta$-function-like potential, the wave function $\ket{VB1, \mathbf{\Gamma}}$ is highly localized near the Wyckoff position 1a for a large $G_{\Lambda}$. 

