Based on the above discussion, we  find the effective Hamiltonian 
\begin{eqnarray}\label{eq_SM:Heff_fk1}
&&H^{eff}_f(\kk)=\tilde{H}^0_f(\kk)+ \Delta_0\begin{pmatrix}
1  & 1& \dots& 1\\
1 & 1 & \dots& 1\\
\vdots & \vdots & \ddots&  \vdots\\
1 & 1 & \dots &1
\end{pmatrix},\\
&&\tilde{H}^0_{f,ij}(\kk)=\delta_{i,j}E_v(\kk+\gs_j),
\end{eqnarray}
where $i,j = 1, \cdots, N_g$ and  $E_v(\kk+\gs_j)$ are obtained from the second order perturbation as
\begin{eqnarray}\label{Eq_SM:EvApprox0}
&&E_v(\kk+\gs_j)=\begin{cases}
    % H^{2,2}_{C} (\kk + \gs_j)+\frac{|H^{1,2}_{C} (\kk + \gs_j)|^2}{H^{2,2}_{C} (\kk + \gs_j)-H^{1,1}_{C} (\kk + \gs_j)}=
    (D-B)|\kk+\gs_j|^2-M-\frac{A^2|\kk+\gs_j|^2}{2B|\kk+\gs_j|^2+2M-\Delta_0}. 
    & j\neq 1\\
   (D-B)\kk^2-M.& j=1
\end{cases}
\label{Eq:HBHZ valance band}
\end{eqnarray}
% The Hamiltonian $H^{eff}_f(\kk)$ \addYZ{without $H^{eff(2)}_f$} \commentCXL{what does this mean? Why without $H^{eff(2)}_f$? } recovers that in Sec.\ref{Sec:deltapotential_parabolicbands} for a parabolic band in a \addYZ{periodic} $\delta$-function-like potential. \commentCXL{Can one just use the expression below after dropping $\Delta_0$? } \addYZ{The term $-\frac{A^2|\kk+\gs_j|^2}{2B|\kk+\gs_j|^2+2M-\Delta_0} $ in Eq.(\ref{Eq:HBHZ valance band}) is from $H^{eff(2)}_f$.}  \addYZ{In addition, for $j\neq1$, we further drop the $\Delta_0$ in $\frac{A^2|\kk+\gs_j|^2}{2B|\kk+\gs_j|^2+2M-\Delta_0} $, because $\Delta_0$ is more than 100 times smaller than  $2B|\kk+\gs_j|^2+2M$ in the denominator. Therefore we have
% \begin{eqnarray}\label{Eq_SM:EvApprox1}
% &&E_v(\kk+\gs_j)\approx\begin{cases}
%     (D-B)|\kk+\gs_j|^2-M-\frac{A^2|\kk+\gs_j|^2}{2B|\kk+\gs_j|^2+2M}.
