% According to Tab.\ref{TAB: symmetry C3v matrix}, the allowed terms are $\sigma_3 \lambda'_6 $ and $(\sigma_2\lambda'_3+\sigma_1\lambda'_4)$. Including the kinetic term from orbitals, the effective 6 band model are 
\begin{eqnarray}\label{eq_SM:H_hetero_full}
&&H_{3b,hetero}(\kk)=\left[\frac{1}{3}(E_1 + A_1 k^2)+\frac{2}{3}(E_2 + A_2 k^2)\right] \sigma_0 \Lambda_0 +\left[\frac{1}{\sqrt{3}
}(E_1 + A_1 k^2)-\frac{1}{\sqrt{3}}(E_2 + A_2 k^2)\right]\sigma_0 \Lambda_5 \nonumber \\ 
&&+\sqrt{2} B_0 (k_x \sigma_0 \Lambda_3 -k_y \sigma_0 \Lambda_4)+\sqrt{2} B_1 \left[(k^2_x-k^2_y) \sigma_0 \Lambda_1 +2k_xk_y \sigma_0 \Lambda_2)\right] + B_2 \left[(k^2_x-k^2_y) \sigma_0 \Lambda_7 +2k_xk_y \sigma_0 \Lambda_8)\right] \nonumber \\ 
&&-\Delta_{SOC}\sigma_3 \Lambda_6+\sqrt{2}\Delta    _{Inter}(\sigma_2\Lambda_3+\sigma_1\Lambda_4)+R_2(\sigma_3\Lambda_7k_y+\sigma_3\Lambda_8k_x)+R_3(\sigma_3\Lambda_1k_y+\sigma_3\Lambda_2k_x)\nonumber\\
&&+\frac{1}{3}R_0 \left[\sigma_2(\Lambda_0+\sqrt{3}\Lambda_5)k_x-\sigma_1(\Lambda_0+\sqrt{3}\Lambda_5)k_y\right ]+\frac{2}{3}R_1\left [\sigma_2(\Lambda_0-\frac{\sqrt{3}}{2}\Lambda_5)k_x-\sigma_1(\Lambda_0-\frac{\sqrt{3}}{2}\Lambda_5)k_y\right ],
\end{eqnarray}
%\commentCXL{Check and confirm $1/3, 2/3, 1/\sqrt{3}, \sqrt{2}, ... $ coefficients}. 
where $E_1, E_2, A_1, A_2, B_0, B_1, B_2$ are material dependent parameters independent of spin, $\Delta_{SOC}$ and $\Delta_{Inter}$ describe the $\kk$-independent SOC terms, $R_0$ and $R_1$ terms are Rashba SOC in TI$_2$Se$_2$ and Zn$_2$Te$_2$ layers, respectively, and the $R_2$ and $R_3$ terms are spin-dependent hopping terms connected to out-of-plane spin ($\sigma_3$). 
 %\addYZ{YZ: In the form of $(\Lambda_0+\frac{\sqrt{3}}{2}\Lambda_5)$, $R_0$ is just Rashba term TI$_2$Se$_2$ layer. If we use $(\Lambda_0-\frac{\sqrt{3}}{2}\Lambda_5)$ and $(\Lambda_0+\frac{\sqrt{3}}{2}\Lambda_5)$ as basis, We need to rewrite the first two terms. therefore I do not think we need to do that. }

To project the above Hamiltonian to the Chern-band model, we will below ignore the interlayer SOC term $\Delta_{inter}(\sigma_2\Lambda_3+\sigma_1\lambda_4)$, $\kk$-dependent SOC terms and the off-diagonal $\kk^2$ terms ($B_1$ and $B_2$ terms), which are expected to be small, so the effective 6-bands model becomes block diagonal and can be written as 
\begin{eqnarray}
&&H_{3b,hetero}(\kk)=\left (\begin{array}{ccc}
        H_{hetero,\uparrow}(\kk)&0  \label{Eq:3b model 1}\\ 
        0 & H_{hetero,\downarrow}(\kk)
    \end{array}\right),\\
&&H_{3b,hetero,\uparrow}(\kk) =
\begin{pmatrix}
E_1 + A_1 k^2 & i B_0 (k_x + i k_y) & i B_0 (k_x - i k_y) \\
-i B_0 (k_x - i k_y) & E_2 + \Delta_{SOC} + A_2 k^2 & 0 \\
-i B_0 (k_x + i k_y) & 0 & E_2 - \Delta_{SOC} + A_2 k^2
\end{pmatrix}\\
&&H_{3b,hetero,\downarrow}(\kk) =
\begin{pmatrix}
E_1 + A_1 k^2 & i B_0 (k_x + i k_y) & i B_0 (k_x - i k_y) \\
-i B_0 (k_x - i k_y) & E_2 - \Delta_{SOC} + A_2 k^2 & 0 \\
-i B_0 (k_x + i k_y) & 0 & E_2 +\Delta_{SOC} + A_2 k^2
\end{pmatrix} \label{Eq:3b model 3},
\end{eqnarray}  
on the basis wavefunctions $\ket{\mathbf{\Gamma}_1,J_{z}=1/2,\uparrow}$, $ \ket{\mathbf{\Gamma}_3,J_{z}=3/2,\uparrow}$, $\ket{\mathbf{\Gamma}_3,J_{z}=-1/2,\uparrow}$ and $ \ket{\mathbf{\Gamma}_1,J_{z}=-1/2,\downarrow}$, $ \ket{\mathbf{\Gamma}_3,J_{z}=1/2,\downarrow}$, $ \ket{\mathbf{\Gamma}_3,J_{z}=-3/2,\downarrow}$ for spin up and down, respectively.
Here, $E_1>E_2$ so that for each spin block of the Hamiltonian $H_{hetero}$, the first component gives the conduction band with $L=0$ while the second and third components provide the valence bands with $L=\pm 1$. We focus on the spin up block $H_{hetero,\uparrow}$. If $\Delta_{SOC}>0$, we would expect the $\ket{\mathbf{\Gamma}_3,J_{z}=3/2,\uparrow}$ state has a higher energy than the $\ket{\mathbf{\Gamma}_3,J_{z}=-1/2,\uparrow}$ state and thus serves as the topmost valence band, so we project out the $\ket{\mathbf{\Gamma}_3,J_{z}=-1/2,\uparrow}$ state and the resulting Hamiltonian on the basis $\ket{\mathbf{\Gamma}_1,J_{z}=1/2,\uparrow}$,$\ket{\mathbf{\Gamma}_3,J_{z}=3/2,\uparrow}$ is given by
\begin{eqnarray}\label{Eq:hetro eff}
   H^{eff}_{hetero,\uparrow}(\kk) = \begin{pmatrix}
E_1 + A_1 k^2+\frac{B_0^2 \kk^2}{E_1-E_2+\Delta_{SOC}} & i B_0 (k_x + i k_y) \\
-i B_0 (k_x - i k_y) & E_2 + \Delta_{SOC} + A_2 k^2  
\end{pmatrix},
\end{eqnarray}
which is identical to the Chern-band model in Eq.(\ref{Eq:Ham_Chernband}) up to a unitary transformation. 

If $\Delta_{SOC}<0$, we can project out the $\ket{\mathbf{\Gamma}_3,J_{z}=3/2,\uparrow}$ state instead and the Hamiltonian on the basis $\ket{\mathbf{\Gamma}_1,J_{z}=1/2,\uparrow}$ and $\ket{\mathbf{\Gamma}_3,J_{z}=-1/2,\uparrow}$ is
\begin{eqnarray}\label{Eq:hetro eff2}
   H^{eff}_{hetero,\uparrow}(\kk) = \begin{pmatrix}
E_1 + A_1 k^2+\frac{B_0^2 \kk^2}{E_1-E_2-\Delta_{SOC}} & i B_0 (k_x -i k_y) \\
-i B_0 (k_x +i k_y) & E_2 - \Delta_{SOC} + A_2 k^2  
\end{pmatrix}, 
\end{eqnarray}
which still recovers the Chern-band model form Eq.(\ref{Eq:Ham_Chernband}) up to a unitary transformation.

