\section{Proofs}\label{sec:proofs}

This section provides proofs of main results in previous sections.

We first show that $v(t,r,z)$ given by \eqref{eq:v} is a classical solution to the Neumann boundary problem \eqref{eq:HJB-v}.
\begin{lemma}\label{lem:derivative-v}
Let $f\in\C([0,T])$ satisfies $f(t)> 0$ for all $t\in[0,T]$. We have $v\in{\C}^{1,2,2}(\overline{\mathcal{D}}_T)$ and $v_r\in$ ${\C}^{1,2,2}(\overline{\mathcal{D}}_T)$. Moreover, for $(t, r, h) \in\overline{\mathcal{D}}_T$, we get
\begin{align}
v_r(t, r,z)&=\lambda\mathbb{E}\left[\int_t^{\tau_r^t \wedge T} e^{-\rho s-R_s^{t, r}} f(s)ds\right]+(1-\lambda)\eta  \Ex\left[ \int_t^{\tau_r^t \wedge T}e^{-\rho s-R^{t,r}_s}Z_s^{t,z} ds\right], \label{eq:v-r}\\
v_{rr}(t,r,z)&=\lambda \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds-\lambda  \Ex\left[\int_{t}^{\tau_r^t\wedge T} e^{-\rho s-R_s^{t,r}}f(s)ds\right]\nonumber\\
&\quad+(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\nonumber\\
&\quad-(1-\lambda)\eta  \Ex\left[ \int_t^{\tau_r^t \wedge T}e^{-\rho s-R^{t,r}_s}Z_s^{t,z} ds\right],\label{eq:v-rr}
\end{align}
where $\kappa:=\mu_Z-\frac{\sigma_Z^2}{2}-\frac{\mu\sigma_Z}{2\sigma}+\frac{\sigma\sigma_Z\rho}{\mu}$, the stopping time $\tau_r^t$ is defined by
$$\tau_r^t:=\inf \left\{s \geq t ;~-\frac{\mu}{\sigma}\left(W_s-W_t\right)-\left(\frac{\mu^2}{2\sigma^2}-\rho\right)(s-t)=r\right\},$$
and we recall that the function $\phi(s,x,y)$ is given by \eqref{eq:phi}.
%\begin{align}\label{eq:phi}
%\phi(s,x,y)= \frac{2(2 y-x)}{\tilde{\sigma}^2\sqrt{2\tilde{\sigma}^2 \pi s^3}} \exp \left(\frac{\tilde{\mu}}{\tilde{\sigma}} x-\frac{1}{2} \tilde{\mu}^2 s-\frac{(2 y-x)^2}{2\tilde{\sigma}^2 s}\right)
%\end{align}
%with parameters $\tilde{\mu}:=\frac{\mu}{2\sigma}-\frac{\sigma}{\mu}\rho$ and $\tilde{\sigma}:=-\frac{\mu}{\sigma}$.
\end{lemma}

\begin{proof}
For $(t,r)\in [0,T]\times \R_+$, let us denote 
\begin{align}
h(t,r)&:=-(1-\lambda)\eta \Ex\left[ \int_t^T\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right],\label{eq:h}\\
l(t,r)&:=-\lambda\Ex\left[ \int_t^Te^{-\rho s-R^{t,r}_s}f(s) ds\right].\label{eq:l}
\end{align}
Then, $v(t,r,z)=zh(t,r)+l(t,r)$ for $(t,r,z)\in \overline{\mathcal{D}}_T$. By a similar calculation as in the proof of Proposition  4.1 in \cite{BoLiaoYu21} and in the proof of Lemma 3.4 in \cite{BHY24a}, we can obtain 
\begin{align}
l_r(t, r)&=\lambda\mathbb{E}\left[\int_t^{\tau_r^t \wedge T} e^{-\rho s-R_s^{t, r}} f(s)ds\right].\label{eq:l-r-1}\\
zh_r(t, r)&=(1-\lambda)\eta z\Ex\left[ \int_t^{\tau_r^t \wedge T}\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right].\nonumber\\
l_{rr}(t,r)&=\lambda  \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds-\lambda  \Ex\left[\int_{t}^{\tau_r\wedge T} e^{-\rho s-R_s^{t,r}}f(s)ds\right].\label{eq:l-r-2}\\
zh_{rr}(t,r)&=(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\nonumber\\
&\quad-(1-\lambda)\eta z \Ex\left[ \int_t^{\tau_r^t \wedge T}\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right],\nonumber
\end{align}
and 
\begin{align}
l_{rrr}(t,r)&=-2\lambda  \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds+\lambda  \Ex\left[\int_{t}^{\tau_r\wedge T} e^{-\rho s-R_s^{t,r}}f(s)ds\right]\nonumber\\
&\quad+\lambda  \int_{t}^{T} e^{-\rho s}\phi(s-t,r,r)f(s) ds+\lambda  \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi_r(s-t,x,r)f(s)dx ds,\label{eq:l-r-3}\\
h_{rrr}(t,r)&=-2(1-\lambda)\eta\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\nonumber\\
&\quad+(1-\lambda)\eta \Ex\left[ \int_t^{\tau_r^t \wedge T}\exp\left(-\rho s-R^{t,r}_s+\left(\mu_Z-\frac{\sigma_Z^2}{2}\right)(s-t)+\sigma_Z(W_s-W_t)\right) ds\right]\nonumber\\
&\quad+(1-\lambda)\eta\int_{t}^{T} \exp\left(-\rho s-\frac{\sigma\sigma_Z}{\mu}r+\kappa(s-t)\right) \phi(s-t,r,r)dx ds\label{eq:h-r-3}\\
&\quad-(1-\lambda)\eta\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi_r(s-t,x,r)dx ds.\nonumber
\end{align}
From \eqref{eq:l-r-1}-\eqref{eq:h-r-3}, we deduce \eqref{eq:v-r}-\eqref{eq:v-rr} and $v_{rrr}=l_{rrr}+zh_{rrr}$ is continuous in $(t,r,z)$. We next derive the expression of $v_z,v_{zz},v_{rz}$ and $v_{rrz}$. Note that  $v(t,r,z)=zh(t,r)+l(t,r)$, it holds that, for $(t,r,z)\in\overline{\mathcal{D}}_T$,
\begin{align}\label{eq:v-z}
v_z(t,r,z)=h(t,r),\quad v_{zz}(t,r,z)=0,\quad v_{rz}(t,r,z)=h_r(t,r,z)\quad v_{rrz}(t,r,z)=h_{rr}(t,r,z).
\end{align}
Finally, we derive the expression of $v_t$ and $v_{rt}$. For any $\delta\in[-t,T-t]$, it holds that
\begin{align*}
l(t,r)&=-\lambda \Ex\left[\int_{t}^T e^{-\rho s-R_s^{t,r}}f(s)ds\right]=-\lambda \Ex\left[\int_{t}^{T}e^{-\rho s-R_{s+\delta}^{t+\delta,r}}f(s)ds\right].
\end{align*}
Then, we get
\begin{align*}
&\lim_{\delta\to 0}\frac{l(t+\delta,r)-l(t,r)}{\delta}\\
&=-\lambda \lim_{\delta\to 0}\frac{1}{\delta}\left\{ \Ex\left[\int_{t+\delta}^{T} e^{-\rho s-R_{s}^{t+\delta,r}}f(s)ds\right]-\Ex\left[ \int_t^Te^{-\rho s-R^{t+\delta,r}_{s+\delta}}f(s)ds\right] \right\}\\
&=\lambda\lim_{\delta\to 0}\frac{1}{\delta}\Ex\left[\int_t^{t+\delta}e^{-\rho s-R_{s}^{t+\delta,r}}f(s)ds\right]-\lambda  \int_{t}^{T} e^{-\rho s}f(s)\lim_{\delta\to 0}\left\{\frac{1}{\delta}\Ex\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]\right\}ds\\
&=\lambda e^{-\rho t-r}f(t)-\lambda  \int_{t}^{T} e^{-\rho s}f(s)\lim_{\delta\to 0}\left\{\frac{1}{\delta}\Ex\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]\right\}ds.
\end{align*}
By applying It\^o's lemma and taking expectation, we have $\Ex\left[e^{-R_{s}^{t+\delta,r}}-e^{-R^{t+\delta,r}_{s+\delta}}\right]=-\rho \delta-\Ex\left[\int_{s+\delta}^s  dL_{\ell}^{t+\delta,r}\right]$. Using the Dominated Convergence Theorem and Proposition~2.5 in \cite{Abraham2000}, we arrive at
\begin{align}\label{eq:l-t-1}
l_t(t,r)=\lambda e^{-\rho t-r}f(t)+\lambda  \int_{t}^{T} e^{-\rho s}f(s)(\rho-p(t,r;s,0))ds,
\end{align}
where $p(t,r;s,x)$ is the conditional density function of the reflected drifted Brownian process $R^{t,r}$ \citep{Vee2004}. Similar to the calculation above, we can also get
\begin{align}\label{eq:h-t-1}
zh_t(t,r)
&=(1-\lambda)\eta \left\{\Ex\left[ \int_{t}^{T} e^{-\rho s-R^{t,r}_{s}} Z_{s}^{t,z} ds\right]+\Ex\left[  e^{-\rho T-R^{t,r}_{T}} Z_{T}^{t,z} \right]\right\}.
\end{align}
We also have from \eqref{eq:v-r} that
\begin{align}\label{eq:v-t-2}
&v_{rt}(t,r)=-\lambda \int_t^T \int_0^r \int_{-\infty}^y e^{-\rho s-r+x}\phi_s(s-t,x,y)dsdyds\\
&\quad-(1-\lambda)\eta z\int_{t}^{T}\int_0^r \int_{-\infty}^{y} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi_s(s-t,x,y)dx dyds.\nonumber
\end{align}
By applying \eqref{eq:l-r-1}, \eqref{eq:l-r-2}, \eqref{eq:v-z} \eqref{eq:l-t-1} and \eqref{eq:h-t-1},  we deduce that $v \in {\C}^{1,2,2}(\overline{\mathcal{D}}_T)$. Using \eqref{eq:l-r-2}, \eqref{eq:l-r-3}, \eqref{eq:h-r-3}, \eqref{eq:v-z} and \eqref{eq:v-t-2}, we further have that $v_r \in {\C}^{1,2,2}(\overline{\mathcal{D}}_T)$.
\end{proof}


Building upon Lemma \ref{lem:derivative-v}, we have the following result:
\begin{proposition}\label{prop:v}
Let $f\in {\C}([0,T])$ satisfy $f(t)> 0$ for all $t\in[0,T]$. Then, the function $v$ defined by \eqref{eq:v} is the unique classical solution to the Neumann boundary problem \eqref{eq:HJB-v} satisfying $|v(t,r,z)|\leq C(1+z)$ for some constant $C>0$. 
\end{proposition}




\begin{proof}[Proof of Proposition \ref{thm:dual-u}]
It follows from Proposition \ref{prop:v} that the function  $\hat{u}(t,y,z)$ is the  unique classical solution of the dual equation \eqref{eq:dual-u} satisfying $|\hat{v}(t,y,z)|\leq K(1+z)$ for some positive constant $K$ and $\hat{u}_y \in {\C}^{1,2,2}([0,T]\times (0,1]\times\R_+)$. Furthermore, the strict convexity of $(0,1] \ni y \mapsto \hat{u}(t,y)$ for fixed $t \in[0, T) $ follows from the fact that 
\begin{align*}
&\hat{u}_{y y}=\frac{e^{\rho t}}{y^2}(v_{rr}+v_r)=\frac{\lambda e^{\rho t}}{y^2} \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s-r+x}\phi(s-t,x,r)f(s)dx ds\\
&\qquad+\frac{(1-\lambda)\eta e^{\rho t}}{y^2}\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s-r+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds>0.
\end{align*} 
By Lemma \ref{lem:derivative-v}, we that $f(t)\geq 0$ and $\eta=(\mu_Z\sigma-\mu\sigma_Z)/\sigma>0$.  
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm:verification}]
The proof of the item  (i) is similar to the proof of Theorem 5.1 in \cite {BoLiaoYu21}, and hence we omit it here. Mext, we only show the item (ii). It is not difficult to see that
\begin{align}\label{eq:theta-1}
\lim_{y\downarrow 0}z \hat{u}_{yz}(t,y,z)&=-\lim_{y\downarrow 0}\frac{e^{\rho t}z}{y}v_{rz}(t,-\ln y,z)=-\lim_{r\to +\infty}e^{\rho t+r}zv_{rz}(t,r,z)\nonumber\\
&=-(1-\lambda)\eta\mathbb{E}\left[\int_t^{T} e^{-\frac{\mu}{\sigma}\left(W_s-W_t\right)-\frac{\mu^2}{2\sigma^2}(s-t)}  Z_s^{t,z}ds\right]\nonumber\\
&=-(1-\lambda)\left(e^{\eta (T-t)}-1\right)z.
\end{align}
In view of $\mu>0$, \eqref{eq:v-rr} and $\hat{u}_{yy}\geq 0$ from Proposition \ref{thm:dual-u}, we have 
\begin{align}\label{eq:estimate-theta-1}
0\leq\liminf_{y\downarrow 0} y\hat{u}_{yy}(t,y,z)\leq \limsup_{y\downarrow 0} y\hat{u}_{yy}(t,y,z)=\limsup_{r\to +\infty} e^{\rho t+r}(v_{rr}+v_r)(t,r,z).
\end{align}
We obtain from Lemma \ref{lem:derivative-v} that
\begin{align}\label{eq:estimate-theta-2}
e^{r}(v_{rr}+v_r)(t,r,z)\nonumber\\
&\quad=\lambda \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx ds\\
&\qquad +(1-\lambda)\eta z\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds.\nonumber
\end{align}
In the sequel, let $C>0$ be a generic positive constant independent of $(t,x,z)$, which may differ from line to line. For the case $r>2$, it holds that $(r+y)^2-1>0$ for all $y\geq0$. As $f\in C([0,T])$, it follows that, for all $(t,r)\in[0,T]\times (2,\infty)$,
\begin{align}\label{eq:estimate-theta-3}
&\int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx\leq C \int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)dx ds\nonumber\\
%&=C\int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\frac{2(2 r-x)}{\hat{\sigma}^2\sqrt{2\hat{\sigma} \pi (s-t)^3}}\exp\left(\frac{\hat{\mu}}{\hat{\sigma}} x-\frac{1}{2} \hat{\mu}^2 (s-t)-\frac{(2 r-x)^2}{2\hat{\sigma}^2 (s-t)}\right)dxds\nonumber\\
&\overset{y=r-x}{=}C\int_{t}^{T}\int_{0}^{\infty} e^{-\rho s+r-y}\frac{2( r+y)}{\hat{\sigma}^2\sqrt{2\hat{\sigma} \pi (s-t)^3}}\exp\left(\frac{\hat{\mu}}{\hat{\sigma}}(r-y)-\frac{1}{2} \hat{\mu}^2 (s-t)-\frac{( r+y)^2}{2\hat{\sigma}^2 (s-t)}\right)dyds\nonumber\\
&=C\int_{t}^{T}\frac{2\exp\left(-\frac{1}{2\hat{\sigma}^2 (s-t)}\right)}{\hat{\sigma}^2\sqrt{2\hat{\sigma} \pi (s-t)^3}}e^{-\rho s}ds\int_{0}^{\infty} ( r+y)\exp\left(\frac{\hat{\mu}}{\hat{\sigma}} (r-y)+r-\frac{( r+y)^2-1}{2\hat{\sigma} ^2(T-t)}\right)dy\nonumber\\
&\leq C r\exp\left(\left(\frac{\hat{\mu}}{\hat{\sigma}}+1\right)r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)}\right)\int_{0}^{\infty} ( 1+y)\exp\left(-\frac{y^2}{2\hat{\sigma}^2 (T-t)}-\frac{\hat{\mu}}{\hat{\sigma}}y\right)dy\nonumber\\
&\leq Cr\exp\left(\frac{\hat{\mu}}{\hat{\sigma}}r+r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)}\right).
\end{align}
Since the mapping $r\to r\exp(\frac{\hat{\mu}}{\hat{\sigma}} r+r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)})$ is continuous, and
$\lim_{r\to\infty}r\exp(\frac{\hat{\mu}}{\hat{\sigma}}r +r-\frac{r^2-1}{2\hat{\sigma}^2 (T-t)})=0$, we have 
\begin{align}\label{eq:estimate-theta-4}
&\limsup_{r\to+\infty}\int_{t}^{T}\int_{-\infty}^{r} e^{-\rho s+x}\phi(s-t,x,r)f(s)dx\leq 0.
\end{align}
In a similar fashion to derive \eqref{eq:estimate-theta-3}, we can also get that
\begin{align}\label{eq:estimate-theta-5}
&\limsup_{r\to+\infty}\int_{t}^{T}\int_{-\infty}^{r} \exp\left(-\rho s+\left(1-\frac{\sigma\sigma_Z}{\mu}\right)x+\kappa(s-t)\right) \phi(s-t,x,r)dx ds\leq 0.
\end{align}
Therefore, in view of \eqref{eq:estimate-theta-1} \eqref{eq:estimate-theta-2}, \eqref{eq:estimate-theta-4} and \eqref{eq:estimate-theta-5}, we deduce that
\begin{align}\label{eq:theta-2}
\lim_{y\downarrow 0} y\hat{u}_{yy}(t,y,z)=0.
\end{align}
Together with \eqref{eq:theta-1}, the  feedback control function $\theta^*(t,x,z)$ give by \eqref{eq:optimal-theta} is well-defined.
Moreover, we can see that the function $(x,z) \to \theta^*(t,x,z)$ is locally Lipschitz continuous and satisfies the liner growth with respect to $z$.
% that
%\begin{itemize}
%\item[(i)] for $R>0$, there exists some positive constant $L_R$ depending on $R$ such that, for any $t\in[0,T],(x_1,z_1),(x_2,z_2)\in[0,R]^2$,
% \begin{align*}
%|\theta^*(t,x_1,z_1)-\theta^*(t,x_2,z_2)|\leq L_R(|x_1-x_2|+|z_1-z_2|);
%\end{align*}
%\item[(ii)] there exists some positive constant $C$ such that
%\begin{align*}
%|\theta^*(t,x,z)|\leq C(1+z),\quad \forall  (t,x,z)\in \overline{\mathcal{D}}_T.
%\end{align*}
%\end{itemize}
Thus, the SDE \eqref{eq:optimal-SDE} has a unique strong solution, which implies $\theta^*\in\mathbb{U}^r$. 

 For any $\theta\in \mathbb{U}^r$, let $(X_t)_{t\in[ 0,T]}$ be the resulting state process. For $n\in \mathbb{N}$ and $1/n<T$, define the stopping time $\tau_n$ by $\tau_n:=\left(T-\frac{1}{n}\right)\wedge\inf \left\{s\geq 0: X_s \wedge Z_s\geq n\right\}$. By applying It\^o's lemma to $e^{-\rho \tau_n}u(\tau_n,X_{\tau_n},Z_{\tau_n})$ and  taking the expectation on both sides, we deduce
\begin{align}\label{eq:value-ineq}
\Ex\left[e^{-\rho (\tau_n-t)}u(\tau_n,X_{\tau_n},Z_{\tau _n})\right]+\mathbb{E}\left[-\int_t^{\tau_n}e^{-\rho (s-t)}dL_s^X\right]\leq u(t,x,z),
\end{align}
and the equality holds when $\theta=\theta^*$. In view of Proposition \ref{thm:dual-u} and \eqref{eq:sol-u}, we know that $u(t,x,z)\leq 0$ on $\overline{\mathcal{D}_T}$ and $u(t,x,z)=\inf_{y\in(0,1]}\{\hat{u}(t,y,z)+yx\}\geq \inf_{y\in(0,1]}\{\hat{u}(t,y,z)\}\geq -C(1+z)$ on $\mathcal{O}_T$ for some positive constant $C$. This yields that $|u(t,x,z)|\leq C(1+z)$, for all $(t,x,z)\in\overline{\mathcal{D}_T}$.  Letting $n \rightarrow \infty$ on both sides of \eqref{eq:value-ineq}, by using Dominated Convergence Theorem and  Monotone Convergence Theorem, we get the desired result.
\end{proof}

%\begin{proof}[Proof of Lemma \ref{lem:u_x}]
%Let $x\to y(t,x,z)$ be the inverse function of $y\to-\hat{u}_y(t,y,z)$ for $(t,x,z)\in {\cal O}_T$. It follows from the implicit function theorem that $y$ is $C^1$ on ${\cal O}_T$.  By using the dual transform and direct calculations, we can obtain that, for $(t,x,z)\in {\cal O}_T$,
