%&u_{xt}(t,x,z)=-\frac{\hat{u}_{yt}(t,y,z)}{\hat{u}_{yy}(t,y,z)},\quad u_{xx}(t,x,z)=-\frac{1}{\hat{u}_{yy}(t,y,z)},\quad u_{xxx}(t,x,z)=-\frac{\hat{u}_{yyy}(t,y,z)}{\hat{u}_{yy}^3(t,y,z)},\\
%&u_{xz}(t,x,z)=-\frac{\hat{u}_{yz}(t,y,z)}{\hat{u}_{yy}(t,y,z)},\quad u_{xxz}(t,x,z)=\frac{\hat{u}_{yzz}(t,y,z)}{\hat{u}_{yy}^2(t,y,z)}-\frac{\hat{u}_{yz}(t,y,z)\hat{u}_{yyy}(t,y,z)}{\hat{u}_{yy}^3(t,y,z)},\\
%&u_{xzz}(t,x,z)=-\frac{\hat{u}_{yzz}(t,y,z)}{\hat{u}_{yy}(t,y,z)}+\frac{2\hat{u}_{yz}(t,y,z)\hat{u}_{yyz}(t,y,z)}{\hat{u}_{yy}(t,y,z)}-\frac{\hat{u}_{yz}^2(t,y,z)\hat{u}_{yyy}(t,y,z)}{\hat{u}^3_{yy}(t,y,z)}.
