By using Lemma \ref{lem:derivative-v} and Theorem \ref{thm:verification}, we can directly get Lemma  \ref{lem:u_x}. Then, we here provide the proofs of Lemma \ref{lem:dual-process}, Lemma \ref{lem:fixpoint-r} and Lemma \ref{lem:continuity-f}.

\begin{proof}[Proof of Lemma \ref{lem:dual-process}]
We first consider the case with $(0,x,z)\in {\cal O}_T$ and ${\cal O}_T\neq \emptyset$. In view of Lemma \ref{lem:u_x}, the partial derivative of the value function $u$ with respect to $x$ satisfies that $u_x\in\C^{1,2,2}({\cal O}_T)$.  For any $t\in [0,T)$ and $\varepsilon\in(0,1)$, by applying It\^o's formula to $Y_{t\wedge (1-\varepsilon)\tau_0}=u_x({t\wedge (1-\varepsilon)\tau_0},X_{t\wedge (1-\varepsilon)\tau_0}^*,Z_{t\wedge (1-\varepsilon)\tau_0})$, we obtain
\begin{align}\label{eq:ito-Y-1}
Y_{t\wedge (1-\varepsilon)\tau_0}&=Y_0+\int_0^{{t\wedge (1-\varepsilon)\tau_0}} {\cal L}^{\theta_s^*} u_x(s,X_{s}^*)ds+\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  u_{xx}(s,X_{s}^*)dL_s^X\nonumber\\
&\quad+\int_0^{{t\wedge (1-\varepsilon)\tau_0}} \left((\theta_s^*\sigma-(1-\lambda)\sigma_Z Z_s )u_{xx}(s,X_{s}^*,Z_s)+\sigma_Z Z_s u_{xz}(s,X_{s}^*,Z_s) \right) dW_s,
\end{align}
where the operator ${\cal L}^{\theta}$ with $\theta\in \R$ acting on %$C^{1,2,2}(\mathcal{D}_T)\cap C(\overline{\mathcal{D}}_T)$ 
$g\in C^{1,2,2}(\mathcal{D}_T)$ is defined by
\begin{align*}
{\cal L}^{\theta}g&:=g_t+g_x\mu\theta+\frac{1}{2}g_{xx}(\sigma\theta-(1-\lambda)\sigma_Zz)^2+g_{xz}(\sigma\theta-(1-\lambda)\sigma_Zz)\sigma_Z z\\
&\quad+\frac{1}{2}\sigma_Z^2z^2g_{zz}+\mu_Z zg_z -((1-\lambda)\mu_Zz+\lambda f(t)) g_x.
\end{align*} 
We can obtain from \eqref{eq:optimal-theta} that
\begin{align}\label{eq:ito-Y-2}
& (\theta_s^*\sigma-(1-\lambda)\sigma_Z Z_s )u_{xx}(s,X_{s}^*,Z_s)+\sigma_Z Z_s u_{xz}(s,X_{s}^*,Z_s) =- \frac{\mu}{\sigma} u_{x}(s,X_{s}^*,Z_s)=- \frac{\mu}{\sigma}Y_s.
\end{align}
It follows from Theorem \ref{thm:verification} that $({\cal L}^{\theta_s^*} -\rho)u(t,x,z)=0$ for $(t,x,z)\in  {\cal O}_T$. Taking the derivative of $x$ on both sides of the equation, we have
\begin{align}\label{eq:ito-Y-3}
&\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  {\cal L}^{\theta_s^*} u_x(s,X_{s}^*,Z_s)ds=\int_0^{{t\wedge (1-\varepsilon)\tau_0}} \rho  u_x(s,X_{s}^*,Z_s)ds=\int_0^{{t\wedge (1-\varepsilon)\tau_0}}  \rho Y_sds.
\end{align}
Denote by $L_t^Y=-\int_0^{t}  u_{xx}(s,X_{s}^*,Z_s)dL_s^X$ for $t\geq 0$. Consequently, it follows from \eqref{eq:ito-Y-1}-\eqref{eq:ito-Y-3} and the arbitrariness of $\varepsilon\in(0,1)$ that
\begin{align*}
dY_t= \rho Y_tdt-\frac{\mu}{\sigma}Y_tdW_t-dL_t^Y,\quad t\in(0,\tau_0).
\end{align*}
Note that $u_x(t,x,z)\leq 1$, $u_x(t,0,z)= 1$ and $u_{xx}(t,x,z)\leq 0$ for all $(t,x,z)\in{\cal O}_T$. Then,  the process $L=(L_t^Y)_{t\in[0,\tau_0)}$ is a continuous and non-decreasing process (with $L_t^{Y}=0$)  which increases on the time set $\{t\in[0,\tau_0);~Y_t=1\}$ only. This implies that  $Y$ taking values on $(0,1]$ is a reflected process and $L^Y$ is the local time process of $Y$. 

Next, we claim that $Y_t=e^{-R_t^{0,r}}$ on $[0,\tau_0)$, where  the reflected process $(R_t^{0,r})_{t\in [0,T]}$ is given by \eqref{eq:R} with $r=-\ln Y_0=-\ln v_x(0,x,z)$. Let $\tilde{Y}_t=e^{-R_t^{0,r}}$ for $t\in[0,T]$. Then, by using It\^o's rule, $\tilde{Y}=(\tilde{Y}_t)_{t\in[0,T]}$ satisfies the following dynamics given by
\begin{align*}
d\tilde{Y}_t= \rho \tilde{Y}_tdt-\frac{\mu}{\sigma}\tilde{Y}_tdW_t-dL_t^{\tilde{Y}},
\end{align*}
where $L_t^{\tilde{Y}}=\int_0^t e^{-R_t^{0,r}} dL_s^{0,r}=\int_0^t  dL_s^{0,r}=L_t^{0,r}$ for $t\in[0,T]$. We can see that $L^{\tilde{Y}}=(L_t^{\tilde{Y}})_{t\in [0,T]}$ is a continuous and non-decreasing process that increases only on $\{t \in[0, T] ;~R_s^{0,r}=0\}=\{t \in[0, T] ;~\tilde{Y}_s=1\}$ with $L_0^{\tilde{Y}}=0$. This yields that $\tilde{Y}$ is a  the reflected process and $L^{\tilde{Y}}$ is the corresponding local time process. Noting that $\tilde{Y}$ and $Y$ satisfy the same reflected SDE, by the uniqueness of the strong solution, we deduce that $Y_t=\tilde{Y}_t=e^{-R_t^{0,r}}$ on $[0,\tau_0)$. Thus, it holds that, $\Px$-a.s.
\begin{align*}
\tau_0&=\inf\{t\in[0,T] ,~ X_t^*\geq x_0(t,Z_t)\}\wedge T=\inf\{t\in[0,T] ,~ v_x(t,X_t^*,Z_t)\leq0\}\wedge T\nonumber\\
&=\inf\{t\in[0,T] ,~ Y_t\leq 0\}\wedge T=\inf\{t\in[0,T] ,~ e^{-R_t^{0,r}}\leq 0\}\wedge T=T.
\end{align*}
Then, it is not hard to see that $Y$ satisfies the dynamic \eqref{eq:Yt} on $(0,T]$ with $Y_0=v_x(0,x,z)$.

We next let $(0,x,z)\in {\cal O}_T^c\cap \overline{\mathcal{D}}_T$. In this case, we have $x\leq x_0(0,z)$, and hence $\tau_0=0$, $\Px$-a.s., and the value function  $u(0,x,z)=0$. Introduce ${\cal M}:=\{\omega\in\Omega;~(t,X_t^*,Z_t)\in  {\cal O}_T^c\cap \overline{\mathcal{D}}_T\}$. Assume that there exists some $t_0\in(0,T]$ such that $\Px({\cal M})>0$. Then, it follows from the dynamic program principle and the fact $u(t,X_t^*,Z_t)<0$ on ${\cal M}$ that
\begin{align*}
0=u(0,x,z)&=\Ex\left[-\int_0^{t}e^{-\rho s}dL_s^{X^*}+e^{-\rho t}u(t,X_t^*,Z_t)\right]\leq\Ex\left[e^{-\rho t}u(t,X_t^*,Z_t){\bf 1}_{{\cal M}}\right]<0,
\end{align*}
which yields a contradiction. Thus, for any $t\in[0,T]$, we have $(t,X_t^*,Z_t)\in  {\cal O}_T^c\cap \overline{\mathcal{D}}_T$, $\Px$-a.s., which completes the proof of the lemma.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:fixpoint-r}]
In view of \eqref{eq:G} and \eqref{eq:H}, the functions $G(r,s,t)$ and $H(r,z,t)$ are non-negative and continuous.  Fix $(r,z)\in \R_+\times (0,\infty)$. Choose $N>0$ with $0=t_0<t_1<t_2<\cdots<t_N=T$ and $t_{i+1}-t_i=T/N$ for $i=0,\ldots,N-1$ such that
\begin{align*}
M:=\sup_{i=0,...,N-1}  \sup_{t \in  [t_i,t_{i+1}]} \int_{t}^{t_{i+1}}G(r,s,t) ds<1.
\end{align*}
For $t\in [t_{N-1},t_N]$ and $f_1,f_2\in C([t_{N-1},t_N])$, we have 
\begin{align*}
|{\cal J}f_1(t)-{\cal J}f_2(t)|&=\left|\int_t^T \left(f_1(s)-f_2(s)\right) G(r,s,t)ds\right|\leq \int_t^T \left|f_1(s)-f_2(s)\right|G(r,s,t)ds\\
&\leq \sup_{s\in[t,T]}|f_1(s)-f_2(s)| \int_t^T G(r,s,t)ds\leq M \|f_1-f_2\|_{[t_{N-1},t_N]},
\end{align*}
where $\|f\|_{[t_{N-1},t_N]}:=\sup_{t\in [t_{N-1},t_N]}|f(t)|$ for $f\in\C([t_{N-1},t_N])$ is the uniform norm of continuous function on  $[t_{N-1},t_N]$. This implies that ${\cal J}$ is a contraction map on $\C([t_{N-1},t_N])$ and hence has a unique fixed point $f^N$ on $[t_{N-1},t_N]$. Furthermore, if we start with a non-negative continuous function $f_0\in\C([t_{N-1},t_N])$, and consider the sequence $(f_n)_{n\geq 1}$ with $f_n:={\cal J}f_{n-1}$. It follows from  $G(r,s,t)\geq 0$ and $H(r,z,t)\geq 0$ that $f_n$ is also a non-negative function, for any $n\geq 1$. As $f_n$ converges to the fixed point $f^N$, we know $f^N(t)\geq 0$ on $[t_{N-1},t_N]$. On $[t_{N-2},t_{N-1}]$, let us consider the mapping ${\cal J}^{N-1}:\C([t_{N-2},t_{N-1}])\mapsto\C([t_{N-2},t_{N-1}])$ defined by
\begin{align*}
{\cal J}^{N-1}f(t):=\int_t^{t_{N-1}}f(s)G(r,s,t)ds+\int_{t_{N-1}}^{T} f^N(s)G(r,s,t)ds+H(r,z,t),\quad \forall t\in[t_{N-2},t_{N-1}].
\end{align*}
Similarly, we can see that ${\cal J}^{N-1}$ is a contraction mapping on $\C([t_{N-2},t_{N-1}]\times )$ and hence has a unique fixed point $f^{N-1}(t)\geq 0$ on $[t_{N-2},t_{N-1}]$ with $f^{N-1}(t_{N-1})=f^N(t_{N-1})$. Repeating this procedure, we can get the non-negative continuous function sequence $\{f^i\}_{i=1,\ldots,N}$. Define the function $f:[0,T]\to \R_+$ with $f(t)=f^i(t)$ for $t\in[t_{i-1},t_i]$, then the non-negative  continuous $f$ is the unique fixed point of mapping ${\cal J}$. If there exists some $t_0\in[0,T)$ such that $f(t_0)\leq0$, then let us introduce $\hat{t}:=\sup\{t\in[0,T];~f(t)\leq 0\}$. As $f(T)>0,f(t_0)\leq 0$ and $f\in\C([0,T])$, we have $\hat{t}\in[t_0,T)$, and 
\begin{align*}
f(\hat{t})=\int_{\hat{t}}^T f(s)G(r,s,t_0)ds+H(r,z,\hat{t})\leq 0,
\end{align*}
which contradicts with the facts that $f,G\geq 0$, $H>0$ on $(\hat{t},T]$. Thus, we complete the proof.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:continuity-f}]
Fix $(r_1,t_1)\in\R_+\times [0,T]$. For any $\epsilon\in (0,1)$ and $(r_2,t_2)\in {\cal M}^{(r_1,t_1)}_{\epsilon}:=\{(r,t)\in \R_+\times [0,T];~|r-r_1|+|t-t_1|\leq \epsilon\}$, we have
\begin{align}\label{continuity} 
|f(t_1;r_1)-f(t_2;r_2)|\leq |f(t_1;r_1)-f(t_2;r_1)|+|f(t_2;r_1)-f(t_2;r_2)|
\end{align}
It follows from Lemma \ref{lem:fixpoint-r} that
\begin{align}\label{continuity-1}
|f(t_1;r_1)-f(t_2;r_1)|&\leq \left|\int_{t_1}^{t_2} f(s;r_1)G(r_1,s,t_1)ds\right|+\left|H(r_1,z,t_1)-H(r_1,z,t_2)\right|\nonumber\\
&\leq \max_{s\in[t_1,t_2]}|f(s;r_1)G(r_1,s,t_1)||t_2-t_1|+\left|H(r_1,z,t_1)-H(r_1,z,t_2)\right|.
\end{align}
Utilizing the continuity of $(r,s,t)\mapsto G(r,s,t)$, $(r,t)\mapsto H(r,z,t)$ and  $s\mapsto f(s;r)$, we deduce from \eqref{continuity-1} that
\begin{align}\label{continuity-2}
\lim_{\epsilon \to0}|f(t_1;r_1)-f(t_2;r_1)|=0.
\end{align}
On the other hand, applying Lemma \ref{lem:fixpoint-r} again, for $t\in[0,T]$,  we have that
\begin{align}\label{continuity-3}
&|f(t;r_1)-f(t;r_2)|\nonumber\\
&\leq\left|\int_{t}^T (f(s;r_1)-f(s;r_2))G(r_2,s,t)+(G(r_1,s,t)-G(r_2,s,t))f(s;r_1)ds\right|\nonumber\\
&\quad+\left|H(r_1,z,t)-H(r_2,z,t)\right|\nonumber\\
&\leq\int_{t}^T |f(s;r_1)-f(s;r_2)|G(r_2,s,t)ds+\max_{(s,t)\in[0,T]^2}|(G(r_1,s,t)-G(r_2,s,t))f(s;r_1)|T\nonumber\\
&\quad+\max_{s\in[0,T]}\left|H(r_1,z,t)-H(r_2,z,t)\right|\nonumber\\
&\leq K_1\int_{t}^T |f(s;r_1)-f(s;r_2)|ds+K_2(r_1,r_2),
\end{align}
where the positive constant $K_1:=\max_{(r,t_2)\in {\cal M}_1^{(r_1,t_1)},~s\in[t,T]}G(r,s,t)<+\infty$, and the function $K_2(r_1,r_2)$ is given by
\begin{align*}
K_2(r_1,r_2):=\max_{(s,t)\in[0,T]^2}|(G(r_1,s,t)-G(r_2,s,t))f(s;r_1)|T+\max_{s\in[0,T]}\left|H(r_1,z,s)-H(r_2,z,s)\right|,
\end{align*}
which satisfies $\lim_{\epsilon \to 0}K_2(r_1,r_2)\to 0$. Since \eqref{continuity-3} holds for any $t\in[0,T]$, replacing $t$ with $T-t$, we deduce that
\begin{align*}
\left|f(T-t;r_1)-f(T-t;r_2)\right|&\leq K_1\int_{T-t}^T |f(s;r_1)-f(s;r_2)|ds+K_2(r_1,r_2)\nonumber\\
&=K_1\int_{0}^t |f(T-s;r_1)-f(T-s;r_2)|ds+K_2(r_1,r_2).
\end{align*}
It follows from the Gronwall's inequality that
\begin{align}\label{continuity-4}
\lim_{\epsilon \to 0}\left|f(T-t;r_1)-f(T-t;r_2)\right|\leq \lim_{\epsilon \to 0}K_1 e^{K_2(r_1,r_2)T}=0.
\end{align}
Taking $t=T-t_2$ in \eqref{continuity-4} and noting $\lim_{\epsilon \to 0}|f(t_2;r_1)-f(t_2;r_2)|=0$, together with \eqref{continuity} and \eqref{continuity-2}, we conclude that the function $(r,t)\mapsto f(t;r)$ is continuous.
\end{proof}


