\section{Tensor form factors \label{app:tff}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this section, we discuss the tensor form factors in the mean-field picture.
By considering the NLO matrix element~\eqref{eq:3corr} of the ``local" chiral-odd operator~\eqref{eq:eff} between proton states, we derive the following multipole structure:
\begin{subequations}
\label{eq:meanfield_FFs}
\begin{align}
& \mathcal{M}^{u-d}_{\mathrm{FFs}}[i \sigma^{0i}]=2 M_{N} \, \bm{1} \, Y^{i}_{1} \,
\frac{\sqrt{-t}}{2M_{N}} N_{\textrm{mf}, 1}, 
\\[1ex]
& \mathcal{M}^{u+d}_{\mathrm{FFs}}[i \sigma^{ij}]=2 M_{N} \bigg{[} i \epsilon^{ijm}\, \sigma^{m} \, Y_{0} \, 
N_{\textrm{mf}, 0}  
\cr
 &-i \epsilon^{ijl} \sigma^{m} \, Y^{lm}_{2} \, \frac{t}{4M^{2}_{N}} N_{\textrm{mf}, 2} \bigg{]},
\end{align}
\end{subequations}
in the 3D Breit frame, where $N_{\mathrm{mf}} \equiv N_{\mathrm{mf}}(t)$ denotes the mean-field (multipole) form factors appearing as rotational corrections. The explicit expressions for these are given by:
\begin{subequations}
\label{eq:local}
\begin{align}
&N_{\mathrm{mf},0} = - \frac{N_c}{6I} \sum_{\substack{n,\mathrm{non}  \\ j,\mathrm{occ} }} \frac{1}{E_n - E_j} \langle n | \tau^{m} | j \rangle \cr
&\times \langle j | \gamma_{0} \Sigma^{m} \,  j_{0}(|\bm{\hat{X}}| \sqrt{-t} ) | n \rangle, \\[1ex]
&N_{\mathrm{mf},1} = - \frac{iM_{N}N_c}{3I\sqrt{-t}} \sum_{\substack{n,\mathrm{non}  \\ j,\mathrm{occ} }} \frac{1}{E_n - E_j}  \langle n | \tau^{m} | j \rangle \cr
&\times  \langle j | \gamma^{k} \tau^{m}  \frac{\bm{\hat{X}}^{k}}{|\bm{\hat{X}}|}  j_{1}(|\bm{\hat{X}}| \sqrt{-t} )  | n \rangle, \\
&N_{\mathrm{mf},2} = - \frac{3M^{2}_{N}N_c}{It} \sum_{\substack{n,\mathrm{non}  \\ j,\mathrm{occ} }} \frac{1}{E_n - E_j}  \langle n | \tau^{l} | j \rangle \cr
&\times \langle j | \gamma_{0} \Sigma^{m} Y^{lm}_{2}\left(\Omega_{\bm{\hat{X}}}\right) j_{2}(|\bm{\hat{X}}| \sqrt{-t} ) \,   | n \rangle.
\end{align}
\end{subequations}
By performing the 3D multipole expansion of the covariant matrix element in Eq.~\eqref{eq:General_ME_tensor} and comparing the result with Eq.~\eqref{eq:local}, we obtain the following relations between the mean-field form factors and the tensor form factors:
\begin{subequations}
\label{eq:local_1}
\begin{align}
 H^{u+d}_{T} + \frac{t}{6M^{2}_{N}}E^{u+d}_{T}&=N_{\mathrm{mf},0}, \\
 H^{u-d}_{T}+E^{u-d}_{T}+2\tilde{H}^{u-d}_{T}&=N_{\mathrm{mf},1}, \\[1ex]
 E^{u+d}_{T}&=N_{\mathrm{mf},2}.
\end{align}
\end{subequations}
These combinations serve as the basis for proving polynomiality and sum rules, as well as for implementing numerical estimations.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Polynomiality \label{app:poly}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Using the results~\eqref{eq:moment} for the $m$-th moments of the mean-field GPDs in the single-particle representation~\eqref{eq:moment_1}, we have established the polynomiality of the monopole mean-field GPD in the large-$N_c$ limit. In this appendix, we extend the analysis to the higher-multipole chiral-odd GPDs and demonstrate their polynomiality properties. For simplicity, the proof is carried out in the limit $t \to 0$ with $\xi \neq 0$.

\subsection{$\xi$-even dipole GPD}
The single-particle matrix element $A_{1}$ for the $m$-th moment of the dipole GPD $Z_{\mathrm{mf},1}$ is given by
\begin{subequations}
\label{eq:even_dipole_1}
\begin{align}
&A^{ki}_1(\xi,t) = \frac{4}{3} \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}} \langle n| \tau^{b} | j \rangle  \cr
&\times \langle j | \tau^{b} (1+\gamma^{0} \gamma^{3}) \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle, \\
&B^{ki}_1(\xi,t) = 4 \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}}  \cr
&\times \langle n | (1+\gamma^{0} \gamma^{3}) \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
Considering the $G_{5}$ symmetry~\eqref{eq:Gparity}, Eq.~\eqref{eq:even_dipole_1} becomes
\begin{subequations}
\label{eq:even_dipole_2}
\begin{align}
&A^{ki}_1(\xi,t) = \frac{4}{3} \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}} \langle n| \tau^{b} | j \rangle  \cr
&\times \langle j | \tau^{b} (\gamma^{0} \gamma^{3})^{k} \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle, \\
&B^{ki}_1(\xi,t) = 4 \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}}  \cr
&\times \langle n | (\gamma^{0} \gamma^{3})^{k} \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
The operator $e^{i\bm{\Delta} \cdot \hat{\bm{X}}}$ in Eq.~\eqref{eq:even_dipole_2} is now expanded in terms of partial waves. In the limit $t \to 0$, the combination $\Delta^{a} e^{i\bm{\Delta} \cdot \hat{\bm{X}}}$ takes the form [cf.~\eqref{eq:pwe_fw}]
\begin{align}
&\Delta^{a} e^{i \bm{\Delta}\cdot \hat{\bm{X}}} \cr
&\overset{t\to0}{=} - i \nabla^{a} \left[\sum^{\infty}_{l=2} \frac{(-2i M_{N} \xi |\hat{\bm{X}}|)^{l}}{l!} P_{l} (\cos{\hat{\theta}}) \right],
\label{eq:even_dipole_3}
\end{align}
where the lowest value of $l$ that contributes nontrivially to Eq.~\eqref{eq:even_dipole_2} is $l = 2$. Using the relation~\eqref{eq:hierarchy2}, the squared transverse momentum transfer $|\bm{\Delta}_{\perp}|^{2}$ in the denominator of Eq.~\eqref{eq:even_dipole_2} becomes
\begin{align}
|\bm{\Delta}_{\perp}|^{2} \overset{t\to 0}{=} -(2\xi M_{N})^{2}.
\label{eq:even_dipole_4}
\end{align}
Substituting Eqs.~\eqref{eq:even_dipole_3} and \eqref{eq:even_dipole_4} into Eq.~\eqref{eq:even_dipole_2}, we obtain
\begin{subequations}
\label{eq:even_dipole_5}
\begin{align}
A^{ki}_1(\xi,0) &= -\frac{4}{3} i \sum^{\infty}_{l=2} \frac{(-2i M_{N} \xi)^{l-2}}{l!}  \langle n| \tau^{b} | j \rangle  \cr
&\times \langle j | \tau^{b} (\gamma^{0} \gamma^{3})^{k}  (\bm{\gamma}_{\perp} \cdot \bm{\nabla}_{\perp}) (\hat{p}^{3})^{k-i}   \cr
&\times|\hat{\bm{X}}|^{l} P_{l} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle, \\[1ex]
B^{ki}_1(\xi,0) &= -4 i \sum^{\infty}_{l=2} \frac{(-2i M_{N} \xi)^{l-2}}{l!}   \cr
&\times \langle n |  (\gamma^{0} \gamma^{3})^{k}  (\bm{\gamma}_{\perp} \cdot \bm{\nabla}_{\perp}) (\hat{p}^{3})^{k-i}   \cr
&\times|\hat{\bm{X}}|^{l} P_{l} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
Next, taking into account the parity invariance~\eqref{eq:parity}, we find that the allowed partial waves in Eq.~\eqref{eq:even_dipole_5} are restricted to even values, $l = 2, 4, \ldots$. This leads to the modification of the summation in Eq.~\eqref{eq:even_dipole_5} as
\begin{align}
\sum^{\infty}_{l=2}[...] \to \sum^{\infty}_{l=2,4, \ldots}[...].
\label{eq:even_dipole_6}
\end{align}
The part of the single-particle operator in Eq.~\eqref{eq:even_dipole_5} can be rewritten as
\begin{subequations}
\begin{align}
 (\gamma^{0}\gamma^{3})^{k} (\bm{\gamma}_{\perp} \cdot \bm{\nabla}_{\perp}) &= (\bm{\gamma}_{\perp} \cdot \bm{\nabla}_{\perp}) && (\text{$k$ even}), \\[1ex]
&=i  \gamma^{0}  (\bm{\Sigma} \times \bm{\nabla})^{3}  && (\text{$k$ odd}).
\label{eq:even_dipole_7}
\end{align}
\end{subequations}
Note that $\tau^{b}| j\rangle \langle j |\tau^{b}$ is invariant under hedgehog rotations. Therefore, it effectively behaves as a rank-zero 3D irreducible tensor operator with respect to simultaneous isospin and space rotations (cf.~\cite{Ossmann:2004bp}). Utilizing this property, along with the grand spin selection rule~\eqref{eq:Wigner_Ekart_1} for a single sum, we determine the maximum value of $l$ for the summation in Eq.~\eqref{eq:even_dipole_5}, following the same logic used in the derivation of Eq.~\eqref{l_max_m_2_main}:
\begin{subequations}
\label{eq:even_dipole_8}
\begin{alignat}{2}
l^{A,B}_{\mathrm{max}}(k) &= k + 2 \hspace{2em} && (\text{$k$ even}),
\\[1ex]
&= k +1 && (\text{$k$ odd}).
\end{alignat}
\end{subequations}
In terms of $m$, the maximum value is given by $l^{A}_{\mathrm{max}}(k = m - 1)$.
Furthermore, it is convenient to change the summation variable in Eq.~\eqref{eq:even_dipole_5} from $l$ to $l - 2$, so that the actual powers of $\xi$ appear in the polynomial. The maximum value of the new variable is then given by
\begin{subequations}
\label{l_max_m_2}
\begin{alignat}{2}
l^{A}_{\mathrm{max}}(m) &= m - 1 \hspace{2em} && (\text{$m$ odd}),
\\[1ex]
&= m -2 && (\text{$m$ even}).
\end{alignat}
\end{subequations}
The results for $l^{B}_{\mathrm{max}}(m)$ can also be simply obtained by replacing  $k = m - 2$. Shifting the summation variable $l$ accordingly, Eq.~\eqref{eq:even_dipole_5} becomes
\begin{subequations}
\label{eq:even_dipole_9}
\begin{align}
&A^{ki}_1(\xi,0) = -\frac{4}{3} i \sum^{l^{A}_{\mathrm{max}}(m)}_{l=0,2,4...} \frac{(-2i M_{N} \xi)^{l}}{(l+2)!}   \cr
&\times \langle n| \tau^{b} | j \rangle  \langle j | \tau^{b} (\gamma^{0} \gamma^{3})^{k}  (\bm{\gamma}_{\perp} \cdot \bm{\nabla}_{\perp}) \nonumber \\[1ex]
&\times (\hat{p}^{3})^{k-i} |\hat{\bm{X}}|^{l+2} P_{l+2} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle, \\[1ex]
&B^{ki}_1(\xi,0) = -4 i \sum^{l^{B}_{\mathrm{max}}(m)}_{l=0,2,4 ...}  \frac{(-2i M_{N} \xi)^{l}}{(l+2)!}   \cr
&\times \langle n |  (\gamma^{0} \gamma^{3})^{k}  (\bm{\gamma}_{\perp} \cdot \bm{\nabla}_{\perp})    \cr
&\times (\hat{p}^{3})^{k-i} |\hat{\bm{X}}|^{l+2} P_{l+2} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
We find that the dipole GPD $Z_{\mathrm{mf},1}$ is a polynomial in even powers of $\xi$, with its highest power bounded as required by Eq.~\eqref{eq:polynomiality}. This prove the polynomiality of the $\xi$-even dipole GPD.


\subsection{$\xi$-odd dipole GPD}

The single-particle matrix elements $\tilde{A}_{1}$ and $\tilde{B}_{1}$ for the $m$-th moment of the dipole GPD $\tilde{Z}_{\mathrm{mf},1}$ are given by
\begin{subequations}
\label{eq:odd_dipole_1}
\begin{align}
&\tilde{A}^{ki}_1(\xi,t) = 4 i \epsilon^{3ab} \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}} \langle n| \tau^{b} | j \rangle  \cr
&\times \langle j | (1+\gamma^{0} \gamma^{3}) \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle,  \\[1ex]
&\tilde{B}^{ki}_1(\xi,t) = 4 i \epsilon^{3ab}  \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}} \cr
&\times \langle n | \tau^{b} (1+\gamma^{0} \gamma^{3}) \gamma^{a} (\hat{p}^{3})^{k-i} e^{i\bm{\Delta} \cdot \hat{\bm{X}}}(\hat{p}^{3})^{i} | n \rangle, 
\end{align}
\end{subequations}
Applying the $G_{5}$ symmetry~\eqref{eq:Gparity}, Eq.~\eqref{eq:odd_dipole_1} simplifies to
\begin{subequations}
\label{eq:odd_dipole_2}
\begin{align}
&\tilde{A}^{ki}_1(\xi,t) = 4 i \epsilon^{3ab} \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}} \langle n| \tau^{b} | j \rangle  \cr
&\times \langle j | (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle,  \\[1ex]
&\tilde{B}^{ki}_1(\xi,t) = 4 i \epsilon^{3ab}  \frac{\Delta^{a}}{|\bm{\Delta}_{\perp}|^{2}} \cr
&\times \langle n | \tau^{b} (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a} (\hat{p}^{3})^{k-i} e^{i\bm{\Delta} \cdot \hat{\bm{X}}}(\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
We now perform the partial wave expansion of the operator $\Delta^{a} e^{i\bm{\Delta} \cdot \hat{\bm{X}}}$ as outlined in Eq.~\eqref{eq:even_dipole_3}. Substituting Eqs.~\eqref{eq:even_dipole_3} and \eqref{eq:even_dipole_4} into Eq.~\eqref{eq:odd_dipole_2}, we obtain
\begin{subequations}
\label{eq:odd_dipole_5}
\begin{align}
&\tilde{A}^{ki}_1(\xi,0) \cr
&=4 \sum^{\infty}_{l=2} \frac{(-2i M_{N} \xi)^{l-2}}{l!}    \langle n| \tau^{3} | j \rangle \langle j   | (\gamma^{0} \gamma^{3})^{k+1}  \cr
&\times   (\bm{\gamma} \times \bm{\nabla})^{3} (\hat{p}^{3})^{k-i}  |\hat{\bm{X}}|^{l} P_{l} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle,  \\[1ex]
&\tilde{B}^{ki}_1(\xi,0) \cr
&=4 \sum^{\infty}_{l=2} \frac{(-2i M_{N} \xi)^{l-2}}{l!} \langle n | \tau^{3} (\gamma^{0} \gamma^{3})^{k+1}  \cr
&\times    (\bm{\gamma} \times \bm{\nabla})^{3} (\hat{p}^{3})^{k-i} |\hat{\bm{X}}|^{l} P_{l} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
Next, the parity transformation~\eqref{eq:parity} determines the allowed parity of the partial waves $l$. Under this transformation, only odd values of $l$ contribute to Eq.~\eqref{eq:odd_dipole_5}, modifying the summation as follows:
\begin{align}
\sum^{\infty}_{l=2}[\ldots] \to \sum^{\infty}_{l=3,5, \ldots}[\ldots].
\end{align}
Lastly, the maximal power of $l$ is constrained by the selection rules given in Eqs.~\eqref{eq:Wigner_Ekart_1} and \eqref{eq:Wigner_Ekart_2}. Using the relations in Eq.~\eqref{eq:gamma_i}, the grand spin selection rules, and the same reasoning applied in deriving Eq.~\eqref{l_max_m_2_main}, we determine the maximal value of $l$ to be
\begin{subequations}
\label{eq:odd_dipole_6}
\begin{alignat}{2}
l^{A,B}_{\mathrm{max}}(k) &= k+3  \hspace{2em} && (\text{$k$ even}),
\\[1ex]
&= k +2 && (\text{$k$ odd}).
\end{alignat}
\end{subequations}
This result can also be expressed in terms of the variable $m$ (with $k = m - 1$ for $l_{\mathrm{max}}^{A}$). Furthermore, by shifting the summation variable as $l \to l - 3$, we obtain:
\begin{subequations}
\label{eq:odd_dipole_8}
\begin{alignat}{2}
l^{A}_{\mathrm{max}}(m) &= m-1  \hspace{2em} && (\text{$m$ odd}),
\\[1ex]
&= m -2 && (\text{$m$ even}).
\end{alignat}
\end{subequations}
Similarly, the result for $l^{B}_{\mathrm{max}}$ follows by setting $k = m - 2$ in Eq.~\eqref{eq:odd_dipole_6}. Shifting the summation variable $l$ accordingly, Eq.~\eqref{eq:odd_dipole_5} becomes
\begin{subequations}
\label{eq:odd_dipole_9}
\begin{align}
&\tilde{A}^{ki}_1(\xi,0) \cr
&=4\sum^{l^{A}_{\mathrm{max}}(m)}_{l=0,2,4...} \frac{(-2i M_{N} \xi)^{l+1}}{(l+3)!}  \langle n| \tau^{3} | j \rangle \langle j | (\gamma^{0} \gamma^{3})^{k+1} \cr
&\times  (\bm{\gamma} \times \bm{\nabla})^{3} (\hat{p}^{3})^{k-i}  |\hat{\bm{X}}|^{l+3} P_{l+3} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle, \\
&\tilde{B}^{ki}_1(\xi,0) \cr
&=4\sum^{l^{B}_{\mathrm{max}}(m)}_{l=0,2,4...} \frac{(-2i M_{N} \xi)^{l+1}}{(l+3)!}   \langle n | \tau^{3} (\gamma^{0} \gamma^{3})^{k+1} \cr
& \times (\bm{\gamma} \times \bm{\nabla})^{3} (\hat{p}^{3})^{k-i} |\hat{\bm{X}}|^{l+3} P_{l+3} (\cos{\hat{\theta}} ) (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
The $m$-th moment of the dipole mean-field GPD $\tilde{Z}_{\mathrm{mf},1}$ consists of contributions from $\xi E_{T}$ and $\tilde{E}_{T}$. As shown in Eq.~\eqref{eq:odd_dipole_9}, the dipole mean-field GPD is clearly an odd function of $\xi$, with maximal powers reaching $m$, as generally required by polynomiality from $\xi E_{T}$ and $\tilde{E}_{T}$. Thus, we have demonstrated the polynomiality of the $\xi$-odd dipole GPD $\tilde{Z}_{\mathrm{mf},1}$. Notably, the first moment of $\tilde{Z}_{\mathrm{mf},1}$ is nonzero due to the presence of the $\xi E_{T}$ term.


\subsection{Quadrupole GPD}


The single-particle matrix elements ${A}_{2}$ and ${B}_{2}$ for the $m$-th moment of the quadrupole GPD ${Z}_{\mathrm{mf},2}$ are given by
\begin{subequations}
\label{eq:quadrupole_1}
\begin{align}
&A^{ki}_{2}(\xi,t) = \frac{16 i \epsilon^{3ab}}{|\bm{\Delta}_{\perp}|^{4}} (\Delta^{b}_{\perp}\Delta^{c}_{\perp} - \frac{1}{2}\delta^{bc}|\bm{\Delta}_{\perp}|^{2})  \cr
&\hspace{-0.1cm}\times  \langle n| \tau^{c} | j \rangle \langle j | (1+\gamma^{0} \gamma^{3}) \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle,  \\[1ex]
&B^{ki}_{2}(\xi,t) =  \frac{16 i \epsilon^{3ab} }{|\bm{\Delta}_{\perp}|^{4}} (\Delta^{b}_{\perp}\Delta^{c}_{\perp} - \frac{1}{2}\delta^{bc}|\bm{\Delta}_{\perp}|^{2}) \cr
&\times \langle n | \tau^{c} (1+\gamma^{0} \gamma^{3}) \gamma^{a} (\hat{p}^{3})^{k-i} e^{i\bm{\Delta} \cdot \hat{\bm{X}}}(\hat{p}^{3})^{i} | n \rangle, 
\end{align}
\end{subequations}
Applying the $G_{5}$ symmetry~\eqref{eq:Gparity}, Eq.~\eqref{eq:quadrupole_1} simplifies to
\begin{subequations}
\label{eq:quadrupole_2}
\begin{align}
&A^{ki}_{2}(\xi,t) =   \frac{16 i \epsilon^{3ab}}{|\bm{\Delta}_{\perp}|^{4}} (\Delta^{b}\Delta^{c} - \frac{1}{2}\delta^{bc}|\bm{\Delta}_{\perp}|^{2}) \cr
&\times \langle n| \tau^{c} | j \rangle \langle j | (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a} (\hat{p}^{3})^{k-i}  e^{i\bm{\Delta} \cdot \hat{\bm{X}}} (\hat{p}^{3})^{i} | n \rangle,  \\[1ex]
&B^{ki}_{2}(\xi,t) =    \frac{16 i \epsilon^{3ab}}{|\bm{\Delta}_{\perp}|^{4}} (\Delta^{b}\Delta^{c} - \frac{1}{2}\delta^{bc}|\bm{\Delta}_{\perp}|^{2})\cr
&\times \langle n | \tau^{c} (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a} (\hat{p}^{3})^{k-i} e^{i\bm{\Delta} \cdot \hat{\bm{X}}}(\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
In the limit $t \to 0$, the projection of the partial waves $e^{i\bm{\Delta} \cdot \hat{\bm{X}}}$ onto the quadrupole structure is given by [cf.~\eqref{eq:pwe_fw}]
\begin{align}
&(\Delta^{b}\Delta^{c} - \frac{1}{2}\delta^{bc}|\bm{\Delta}_{\perp}|^{2})e^{i \bm{\Delta} \cdot \hat{\bm{X}}} \cr
&\overset{t\to 0}{=} -(\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} )\cr
&\times \nabla^{p}_{\perp}\nabla^{q}_{\perp}  \left[\sum^{\infty}_{l=4} \frac{(-2i M_{N} \xi |\hat{\bm{X}}|)^{l}}{l!} P_{l} (\cos{\hat{\theta}}) \right], 
\label{eq:quadrupole_3_a}
\end{align}
where the minimal value of $l$ for a non-vanishing contribution to Eq.~\eqref{eq:quadrupole_2} is $l=4$. Inserting Eqs.~\eqref{eq:quadrupole_3_a} and \eqref{eq:even_dipole_4} into Eq.~\eqref{eq:quadrupole_2}, we obtain
\begin{subequations}
\label{eq:quadrupole_3}
\begin{align}
&A^{ki}_{2}(\xi,0)\cr
&= -16\sum^{\infty}_{l=4}  \frac{(-2i M_{N} \xi )^{l-4}}{l!}    (\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} )\cr
&\times  i \epsilon^{3ab}  \langle n| \tau^{c} | j \rangle \langle j | (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a}  \nonumber \\[1ex]
&\times (\hat{p}^{3})^{k-i}  \nabla^{p}_{\perp}\nabla^{q}_{\perp} |\hat{\bm{X}}|^{l}  P_{l} (\cos{\hat{\theta}}) (\hat{p}^{3})^{i} | n \rangle,  \\[1ex]
&B^{ki}_{2}(\xi,0) \cr
&= -16\sum^{\infty}_{l=4} \frac{(-2i M_{N} \xi )^{l-4}}{l!}  (\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} )  \cr
&\times  i \epsilon^{3ab} \langle n | \tau^{c} (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a}  \nonumber \\[1ex]
&\times (\hat{p}^{3})^{k-i} \nabla^{p}_{\perp}\nabla^{q}_{\perp} |\hat{\bm{X}}|^{l}  P_{l} (\cos{\hat{\theta}}) (\hat{p}^{3})^{i} | n \rangle, 
\end{align}
\end{subequations}
Next, applying the parity transformation discussed in Eq.~\eqref{eq:parity} to Eq.~\eqref{eq:quadrupole_3}, we find that only even powers of $l$ survive:
\begin{align}
\sum^{\infty}_{l=4}[\ldots] \to \sum^{\infty}_{l=4,6, \ldots}[\ldots].
\end{align}
To determine the upper bound of $l$, we examine the maximal rank of the single-particle operator. To see this, we first express the 2D irreducible tensor operator in terms of its 3D counterpart. For $A_{2}$ with even $k$, we have a irreducible rank-3 tensor:
\begin{align}
&i\epsilon^{3ab}\gamma^{0}\gamma^{3}\gamma^{a}\left(\nabla^{b}_{\perp}\nabla^{c}_{\perp} - \frac{1}{2}\delta^{bc} \bm{\nabla}^{2}_{\perp}\right) \cr
&= \gamma^{0}\Sigma^{b}_{\perp} (\nabla_{\perp}^{b}\nabla_{\perp}^{c}-\frac{1}{3} \delta^{bc} \bm{\nabla}^{2}) \cr
&+\frac{1}{2}\gamma^{0}\Sigma^{b}_{\perp} (\nabla^{3}\nabla^{3}-\frac{1}{3} \bm{\nabla}^{2})\delta^{bc}.
\label{eq:quadrupole_4}
\end{align}
Similarly, for odd $k$, we also obtain a irreducible rank-3 tensor:
\begin{align}
&\gamma^{a}\left(\nabla^{b}_{\perp}\nabla^{c}_{\perp} - \frac{1}{2}\delta^{bc}_{\perp} \bm{\nabla}^{2}_{\perp}\right) \cr
&= \gamma^{a} (\nabla_{\perp}^{b}\nabla_{\perp}^{c}-\frac{1}{3} \delta^{bc}_{\perp} \bm{\nabla}^{2}) \cr
&+ \frac{1}{2}\gamma^{a} (\nabla^{3}\nabla^{3}-\frac{1}{3} \bm{\nabla}^{2})\delta^{bc}_{\perp}.
\label{eq:quadrupole_5}
\end{align}
By coupling either Eq.~\eqref{eq:quadrupole_4} or Eq.~\eqref{eq:quadrupole_5} with the momentum/displacement operators in Eq.~\eqref{eq:quadrupole_3}, we determine the maximal rank of the single-particle operator. Following the reasoning used in the derivation of Eq.~\eqref{l_max_m_2_main}, we obtain the maximal value of $l^{A}_{\mathrm{max}}$:
\begin{align}
\label{eq:quadrupole_6}
l^{A}_{\mathrm{max}}(k) &= k+4,
\end{align}
which holds for all $k$. The corresponding results for $l^{B}_{\mathrm{max}}(k)$ can be derived in a similar way by considering Eqs.~\eqref{eq:quadrupole_4} and \eqref{eq:quadrupole_5} along with the selection rule for the single sum:
\begin{subequations}
\label{eq:quadrupole_7}
\begin{alignat}{2}
l^{B}_{\mathrm{max}}(k) &= k+4  \hspace{2em} && (\text{$k$ even}),
\\[1ex]
&= k +3 && (\text{$k$ odd}).
\end{alignat}
\end{subequations}
Rewriting Eqs.~\eqref{eq:quadrupole_6} and \eqref{eq:quadrupole_7} in terms of $m$ and shifting the summation variable $l \to l-4$, we obtain:
\begin{alignat}{2}
l^{A}_{\mathrm{max}}(m) &= m-1  \hspace{2em} && (\text{$k$ even/odd}). 
\label{eq:quadrupole_7_a}
\end{alignat}
The result for $l^{B}_{\mathrm{max}}(m)$ can be obtained analogously to Eq.~\eqref{eq:quadrupole_7_a}. Under the change of summation variable, Eq.~\eqref{eq:quadrupole_3} finally becomes:
\begin{subequations}
\label{eq:quadrupole_8}
\begin{align}
&A^{ki}_{2}(\xi,0) = -16\sum^{l^{A}_{\mathrm{max}}(m)}_{l=0,2,4...}  \frac{(-2i M_{N} \xi )^{l}}{(l+4)!}  i \epsilon^{3ab}\cr
&\times  (\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} )   \langle n| \tau^{c} | j \rangle \langle j | (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a}  \nonumber \\[1ex]
&\times (\hat{p}^{3})^{k-i}  \nabla^{p}_{\perp}\nabla^{q}_{\perp} |\hat{\bm{X}}|^{l+4}  P_{l+4} (\cos{\hat{\theta}}) (\hat{p}^{3})^{i} | n \rangle,  \\
&B^{ki}_{2}(\xi,0) = -16\sum^{l^{B}_{\mathrm{max}}(m)}_{l=0,2,4...} \frac{(-2i M_{N} \xi )^{l}}{(l+4)!}   i \epsilon^{3ab} \cr
&\times  (\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} ) \langle n | \tau^{c} (\gamma^{0} \gamma^{3})^{k+1} \gamma^{a}  \nonumber \\[1ex]
&\times (\hat{p}^{3})^{k-i} \nabla^{p}_{\perp}\nabla^{q}_{\perp} |\hat{\bm{X}}|^{l+4}  P_{l+4} (\cos{\hat{\theta}}) (\hat{p}^{3})^{i} | n \rangle.
\end{align}
\end{subequations}
The $m$-th moment of the quadrupole mean-field GPD $Z_{\mathrm{mf},2}$ coincides with those of $E_{T}$ in the large-$N_{c}$ limit. As shown in Eq.~\eqref{eq:quadrupole_8}, the result is manifestly an even function of $\xi$, and the maximal power of $\xi$ reaches $m-1$, consistent with the polynomiality property of $E_{T}$. This confirms the polynomiality of $Z_{\mathrm{mf},2}$.

