%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Sum rules \label{app:sr}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this appendix, using the results from the polynomiality proof of the higher-multipole GPDs and taking their first moments ($m = 1$), we demonstrate that the mean-field GPDs are connected to the tensor form factors, in accordance with the standard sum rule for chiral-odd GPDs. As in Appendix~\ref{app:poly}, we verify the sum rules in the limit $t = 0$ with $\xi \neq 0$.

\subsection{$\xi$-even dipole GPD}
By taking the first moment $m = 1$ of the $\xi$-even dipole GPD in Eq.~\eqref{eq:moment}, we obtain
\begin{align}
&\int dx \, Z_{\mathrm{mf},1}(x, \xi, 0) \cr
&= -\frac{M_{N} N_{c}}{4I} \sum_{\substack{n,\mathrm{non} \\ j,\mathrm{occ}}} \frac{1}{E_{n}-E_{j}} A^{00}_{1}(\xi,0),
\label{eq:sr_ed1}
\end{align}
where the single-particle matrix element $A^{00}_{1}(\xi,0)$ is given by
\begin{align}
&A^{00}_{1}(\xi,0) = \frac{2}{3} i \langle n | \bm{\tau} | j \rangle \cdot \langle j | \bm{\tau} (\bm{\gamma_{\perp}} \cdot \bm{\hat{X}_{\perp}})| n \rangle,
\label{eq:sr_ed2}
\end{align}
where $\bm{\hat{X}}_{\perp}=(\hat{X}_{1},\hat{X}_{2})$. In the derivation of Eq.~\eqref{eq:sr_ed2}, we used the relation
\begin{align}
\nabla^{a}_{\perp} \left[ |\bm{\hat{X}}|^{2}P_{2}(\cos\hat{\theta}) \right] = -\hat{X}^{a}_{\perp}.
\end{align}
Owing to the minimal generalization of spherical symmetry induced by the hedgehog symmetry, along with the grand spin selection rule~\eqref{eq:Wigner_Ekart_2} for the double sum, the matrix element~\eqref{eq:sr_ed2} in the 2D representation can be related to a rotationally invariant form:
\begin{align}
 &\langle n | \bm{\tau} | j \rangle \cdot \langle j | \bm{\tau} (\bm{\gamma_{\perp}} \cdot \bm{\hat{X}_{\perp}})  | n \rangle  \cr
&= \frac{2}{3} \langle n | \bm{\tau} | j \rangle \cdot \langle j | \bm{\tau} (\bm{\gamma } \cdot \bm{\hat{X} })  | n \rangle .
\end{align}
Using the relation above, we can express the first moment of the $\xi$-even dipole GPD~\eqref{eq:sr_ed1} in terms of the mean-field tensor form factors~\eqref{eq:local}, derived from the local operator. We then obtain
\begin{align}
&\int dx \, Z_{\mathrm{mf},1}(x, \xi, 0) = N_{\mathrm{mf},1}(0). 
\end{align}
Using the relation~\eqref{eq:local_1} between the mean-field and tensor form factors, we arrive at
\begin{align}
&\int dx \, Z_{\mathrm{mf},1}(x, \xi, 0) \cr
&=H^{u-d}_{T}(0)+E^{u-d}_{T}(0)+2\tilde{H}^{u-d}_{T}(0).
\end{align}
This result coincides with the first moment of the mean-field GPD defined in Eq.~\eqref{relation_1}. Thus, we have proven the sum rule for the $\xi$-even dipole mean-field GPD.




\subsection{$\xi$-odd dipole GPD}
By taking the first moment $m = 1$ of the $\xi$-odd dipole GPD in Eq.~\eqref{eq:moment}, we obtain
\begin{align}
&\int dx \, \tilde{Z}_{\mathrm{mf},1}(x, \xi, 0) \cr
&= -\frac{M_{N}N_{c}}{4I} \sum_{\substack{n,\mathrm{non} \\ j,\mathrm{occ}}} \frac{1}{E_{n}-E_{j}} \tilde{A}^{00}_{1}(\xi,0),
\label{eq:sr_od1}
\end{align}
where the single-particle matrix element $\tilde{A}^{00}_{1}(\xi,0)$ is given by
\begin{align}
&\tilde{A}^{00}_{1}(\xi,0) \cr
&= 4 M_{N} \xi \langle n | \tau^{3} | j \rangle \cdot \langle j | \gamma^{0} \Sigma^{a}_{\perp} |\bm{\hat{X}}|Y^{a3}_{2} (\Omega_{\hat{\bm{X}}}) | n \rangle 
\label{eq:sr_od2}
\end{align}
In deriving Eq.~\eqref{eq:sr_od2}, we used the relations for the Dirac matrices~\eqref{eq:gamma_i} and
\begin{align}
\nabla^{a} \left[ |\bm{\hat{X}}|^{3}P_{3}(\cos\hat{\theta}) \right] = -3|\bm{\hat{X}}|^{2}Y^{a3}_{2}(\Omega_{\hat{\bm{X}}}).
\end{align}
Using the grand spin selection rule~\eqref{eq:Wigner_Ekart_2} for the double sum, we rewrite Eq.~\eqref{eq:sr_od2} in a 3D rotationally invariant form:
\begin{align}
 &\langle n | \tau^{3} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b}_{\perp} |\bm{\hat{X}}|^{2} Y^{b3}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle  \cr
&=  \frac{1}{5}\langle n | \tau^{a} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b} |\bm{\hat{X}}|^{2} Y^{ab}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle.
\end{align}
Using this relation, we express the first moment of the $\xi$-odd mean-field GPD~\eqref{eq:sr_od1} in terms of the mean-field tensor form factors~\eqref{eq:local}. After that, taking into account the relation~\eqref{eq:local_1}, we find
\begin{align}
&\int dx \, \tilde{Z}_{\mathrm{mf},1}(x, \xi, 0) =-\xi E^{u+d}_{T}(0).
\end{align}
This result coincides with the first moment of the mean-field GPD defined in Eq.~\eqref{relation_1tilde}, where the first moment of $\tilde{E}_{T}$ is zero. We have thus proven the sum rule for the $\xi$-odd dipole mean-field GPD.

\subsection{Quadrupole GPD}
By taking the first moment $m = 1$ of the $\xi$-odd dipole GPD in Eq.~\eqref{eq:moment}, we derive
\begin{align}
&\int dx \, Z_{\mathrm{mf},2}(x, \xi, 0) \cr
&= -\frac{M^{2}_{N}N_{c}}{4I} \sum_{\substack{n,\mathrm{non} \\ j,\mathrm{occ}}} \frac{1}{E_{n}-E_{j}} A^{00}_{2}(\xi,0),
\label{eq:sr_q1}
\end{align}
where the single-particle matrix element $A^{00}_{2}(\xi,t)$ is found to be
\begin{align}
&A^{00}_{2}(\xi,0) = -\frac{2}{3}  (\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} ) \cr
&\times \langle n | {\tau}^{c} | j \rangle \langle j | \gamma^{0}\Sigma^{a}_{\perp} \nabla^{p}_{\perp}\nabla^{q}_{\perp} |\hat{\bm{X}}|^{4} P_{4}(\cos{\hat{\theta}}) | n \rangle.
\label{eq:sr_q2}
\end{align}
In deriving Eq.~\eqref{eq:sr_q2}, we used the relations for the Dirac matrices~\eqref{eq:gamma_i}. Using the identity
\begin{align}
&\left(\delta^{bp}\delta^{cq }- \frac{1}{2} \delta^{pq} \delta^{bc} \right) \nabla^{p}_{\perp} \nabla^{q}_{\perp} \left[ |\bm{\hat{X}}|^{4}P_{4}(\cos\hat{\theta}) \right]  \cr
&= 3 \left( \hat{X}^{b}_{\perp}\hat{X}_{\perp}^{c} - \frac{1}{2} \delta^{bc} |\hat{\bm{X}}_{\perp}|^{2}\right).
\end{align}
and reducing the 2D irreducible tensor to its 3D counterpart [cf.~\eqref{eq:3dto2d}], we arrive at
\begin{align}
&A^{00}_{2}(\xi,0) \cr
&= -2 \langle n | \tau^{a}_{\perp} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b}_{\perp} |\bm{\hat{X}}|^{2} Y^{ab}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle  \cr
 &-\langle n | \tau^{a}_{\perp} | j \rangle  \langle j |  \gamma^{0} \Sigma^{a}_{\perp} |\bm{\hat{X}}|^{2} Y^{33}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle .
\label{eq:sr_q3}
\end{align}
Considering the grand spin selection rule~\eqref{eq:Wigner_Ekart_2}, we obtain the following identities:
\begin{subequations}
\begin{align}
 &\langle n | \tau^{a}_{\perp} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b}_{\perp} |\bm{\hat{X}}|^{2} Y^{ab}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle  \cr
&= \frac{7}{15} \langle n | \tau^{a} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b} |\bm{\hat{X}}|^{2} Y^{ab}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle, \\[1ex]
 &\langle n | \tau^{a}_{\perp} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b}_{\perp} |\bm{\hat{X}}|^{2} Y^{33}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle  \cr
&= -\frac{2}{15} \langle n | \tau^{a} | j \rangle  \langle j |  \gamma^{0} \Sigma^{b} |\bm{\hat{X}}|^{2} Y^{ab}_{2}(\Omega_{\hat{\bm{X}}}) | n \rangle.
\end{align}
\end{subequations}
These relations allow us to restore the 3D rotationally invariant expression in Eq.~\eqref{eq:sr_q3}. Thus, the first moment of the quadrupole GPD~\eqref{eq:sr_q1} is related to the mean-field form factors~\eqref{eq:local}. Employing the relation~\eqref{eq:local_1}, we finally obtain
\begin{align}
&\int dx \, Z_{\mathrm{mf},2}(x, \xi, 0) = E^{u+d}_{T}(0).
\end{align}
This relation coincides with the first moment of the mean-field GPD defined in Eq.~\eqref{relation_2}. We have thus proven the sum rule for the quadrupole mean-field GPD.




