\section{Some functors over the category of sheaves of modules}

%-----------------------------------------------------------------------------------------------
%Thorough out this section, we suppose that $R$ is a commutative Noetherian ring with $1\neq 0$ and $M$ and $N$ are finitely generated $R$-module. Also, we assume that $X$ is a connected scheme and $\mathfrak{F}$ is an $\mathcal{O}_X$-module.

In this section, using free resolutions of a sheaf, we introduce the concept of operations $\overline{\Tr}$ and $\overline{\lambda}$ and we will show that they are functors over the category of coherent sheaves of modules on affine schemes. To this end, we recall some definitions.
 \begin{defn}\label{B1}
Let 
$\overset{t_2}\oplus\mathcal{O}_X  \overset{\phi}{\rightarrow} \overset{t_1}\oplus\mathcal{O}_X \overset{\varphi}{\rightarrow}\mathfrak{F} \rightarrow 0$
 be a free resolution of $\mathfrak{F}.$ 
% as $\mathcal{O}_X$-module. 
 So, we say $\mathfrak{F}$ has $(t_1 , t_2)$-ranks.

 By applying $(-)^*= \mathcal{H}om_{\mathcal{O}_X}(- ,\mathcal{O}_X),$ we get the exact sequence
\begin{equation}\label{e2}
0 \rightarrow \mathfrak{F}^* \overset{\varphi^*}{\rightarrow} (\overset{t_1}\oplus\mathcal{O}_X)^* \overset{\phi^*}{\rightarrow} (\overset{t_2}\oplus\mathcal{O}_X)^* \rightarrow \overline{\Tr} \mathfrak{F} \rightarrow 0
\end{equation}
where transpos of $\mathfrak{F},$ $\overline{\Tr}\mathfrak{F}$ denotes $\coker \phi^*.$ Similarly, one may consider $\overline{\lambda}\mathfrak{F} := \coker \varphi^*=\Omega(\overline{\Tr}\mathfrak{F})$ where "$\Omega$" is the first syzygy. Hence, we get other exact sequences
\begin{equation}
0 \rightarrow \mathfrak{F}^* \overset{\varphi^*}{\rightarrow} (\overset{t_1}\oplus\mathcal{O}_X)^*\rightarrow \overline{\lambda} \mathfrak{F} \rightarrow 0
\end{equation}
and
\begin{equation}\label{e3}
0 \rightarrow \overline{\lambda} \mathfrak{F} \overset{\phi^*}{\rightarrow} (\overset{l}\oplus\mathcal{O}_X)^* \rightarrow \overline{\Tr} \mathfrak{F} \rightarrow 0.
\end{equation}
\end{defn} 
 By this definition, the following remark is notable.
 \begin{rem}\label{B21}
 \begin{itemize}
 \item [(1)]
 By \cite[ exercise 2.1.2 and page 65]{H},
 $(\mathfrak{F})^*$,  $\overline{\Tr}\mathfrak{F}$ and $\overline{\lambda}\mathfrak{F}$ are sheaves of $\mathcal{O}_X$-module.

 \item [(2)]
If $\mathfrak{F}$ is a quasi coherent (or respectively coherent) then, by \cite[ proposition  2.5.7]{H}, $\overline{\Tr}\mathfrak{F}$ and $\overline{\lambda}\mathfrak{F}$ are quasi coherent (respectively coherent).
  \item [(3)]
If $\mathfrak{F}$ is free then, $\varphi$ is isomorphism and so $\overline{\Tr}\mathfrak{F}$ and $\overline{\lambda}\mathfrak{F}$ vanish.
\end{itemize}
\end{rem}
In view of the definition,
it is natural to ask ``whether any choice of free resolutions for $\mathfrak{F}$ has no effect and $\overline{\Tr} \mathfrak{F}$ may be uniquely defined ?". Theorem \ref{B24} shows that, in the case where $X$ is affine scheme, it does under ``stabilization". We will come back to this question again in Section 3.
\begin{defn}
%A finitely generated $R$-module 
It is said that $M$ is stable if $M$ has no free summands. Also, two $R$-modules $M$ and $N$ are stability isomorphic, denoted $\underline{M}=\underline{N},$ if there exist free modules of finite rank $H$ and $W$ with $H\oplus M\cong N\oplus W.$
% \end{defn}
Inspired by this definition, we construct the concept of a stable sheaf of modules.
%\begin{defn}
%Let $\mathfrak{F}$ be a $\mathcal{O}_X$-modules. 
We say $\mathfrak{F}$ is stable if there is no a split exact sequence  
$0 \rightarrow \overset{t}\oplus\mathcal{O}_X \rightarrow \mathfrak{F}.$ So, $\mathfrak{F}$ has no free direct summands.
Also, two sheaves of modules $\mathfrak{F}$ and $\mathfrak{G}$ are stability isomorphic and denote $\underline{\mathfrak{G}}=\underline{\mathfrak{F}} $ if there exist free sheaves of finite rank $\mathfrak{h}$ and $\mathfrak{w}$ with $\mathfrak{h}\oplus\mathfrak{G}\cong\mathfrak{F}\oplus\mathfrak{w}.$
\end{defn}
The following lemma shows that the stability of two modules is transferred to the stability of their associated sheaves and vice versa.
 \begin{lem}\label{B}
 Let $X=\Spec(R)$ be an affine scheme.
 % and $M$ and $N$ be finitely generated $R$-modules. 
 Then $M$ and $N$ are stability isomorphic if and only if $\overset {\sim} M$ and $\overset {\sim} N$ are stability isomorphic. In particular, $M$ is stable if and only if $\overset {\sim} M$ is so.
 \end{lem}
