 There are some relations between the transpose of a module and the transpose of its associated sheaf
as the following theorem shows.
 \begin{thm}\label{B3}
 Let $X=\Spec(R)$ be an affine scheme.
 % and $M$ be a finitely generated $R$-module. 
 Then the following statments hold.
\begin{enumerate}
\item 
 $\underline{\overline{\lambda} \overset {\sim} M} \cong \underline{ \overset {\sim} {\lambda M }}$

 \item
 $\underline{\overline{\Tr} \overset {\sim} M} \cong \underline{ \overset {\sim} {\Tr M}}$

 \item
 $\underline{\Gamma (X,\overline{\lambda} \overset {\sim} M)} \cong \underline{ \Gamma (X,\overset {\sim} {\lambda M })}=\underline{ \lambda M}$

 \item
 $\underline{\Gamma (X,\overline{\Tr} \overset {\sim} M)} \cong \underline{ \Gamma (X,\overset {\sim} {\Tr M })}=\underline{\Tr M}$
\item
$\underline{\overline{\Tr}(\overline{\Tr}\overset {\sim} M) }\cong \underline{ \overset {\sim} M}$.
\end{enumerate}
 \end{thm}
\begin{proof}
First note that using \ref{B}, one may assume that $M$ is stable. Let $F_2 \overset{f}{\rightarrow} F_1 \overset{g}{\rightarrow} M \rightarrow 0$ be a minimal free resolution of $M.$ Applying $(-)^+$, we get the exact sequences 
