In the rest of this section, we classify locally free sheaves in terms of their transpose. 

\begin{prop}\label{B4}
Let $\mathfrak{F}$ be a coherent $\mathcal{O}_X$-module. Then 
 the following statments are equivalent.
 \begin{itemize}
\item [(1)] $\mathfrak{F}$ is locally free.
\item [(2)] $\underline{\overline{\Tr}\mathfrak{F}}=0$.
\item [(3)]  $\mathfrak{F}$ is $\mathcal{O}_X$-projective.
\end{itemize}
\end{prop}

\begin{proof}
Note that we may consider the case where $\mathfrak{F}$ is stable.
\begin{itemize}
\item["$1\rightarrow 2$"]
Let $U$ be an arbitrary open affine subset. So, by the assumption and \ref{B21} and also \ref{B5}, 
$ \overline{Tr}(\mathfrak{F}\mid_U)= 0. $
Hence, $ \overline{Tr}\mathfrak{F} =0 .$
\item ["$2 \rightarrow 3$"]  
By the assumption,
$X$ can be covered by open affine subsets $ U_i = \Spec R_i$ such that, for each $i$, there exists a finitely generated $R_i$-module $M_i$ with $\mathfrak{F}\mid_{U_i}=\overset{\sim} M_i.$ 
%So, $0=(\overline{Tr}\mathfrak{F})\mid_{U_i} = \overline{Tr}(\mathfrak{F}\mid_{U_i}) =\overline{Tr}(\overset {\sim}M) = \overset {\sim}{\Tr M}.$ 
Hence, via \ref{B3}, one may see $ \Tr M_i=0.$ So, \cite[2.6]{A} implies
$M_i$ is projective. Therefore, there exist $ \mathcal{O}(U_i) $-module $N_i$ and an integer number $l_i$ such that $\overset{l_i}\oplus \mathcal{O}(U_i) = M_i\oplus N_i.$ Choosing $l:= max \{l_i\}$ (and suitable $N_i$), we can assume that $\overset{l}\oplus \mathcal{O}(U_i) = M_i\oplus N_i$ for all $i.$ Applying "$\sim$,"we get $\overset{l}\oplus \mathcal{O}_X\mid_{U_i} =\mathfrak{F}\mid_{U_i} \oplus \overset{\sim}{N_i}$ and $ \mathfrak{F}\mid_{U_i} $ is $ \mathcal{O}_X\mid_{U_i} $-projective. Setting $ \mathfrak{G}_i=\overset{\sim}{N_i},$ for $i \neq j$, $\overset{l}\oplus \mathcal{O}_X\mid_{U_i\cap U_j} =\mathfrak{F}\mid_{U_i\cap U_j}\oplus \mathfrak{G}_i\mid_{U_i\cap U_j}=\mathfrak{F}\mid_{U_i\cap U_j}\oplus \mathfrak{G}_j\mid_{U_i\cap U_j}.$ Hence,
$ \mathfrak{G}_i\mid_{U_i\cap U_j}\cong\mathfrak{G}_j\mid_{U_i\cap U_j}. $
Using glueing of sheaves lemma, there exists a uniqe sheaf of modules $ \mathfrak{G} $ such that $ \mathfrak{G}_i=\mathfrak{G}\mid_ {U_i}.$ So, $(\overset{l}\oplus \mathcal{O}_X)\mid_{U_i} =\mathfrak{F}\mid_{U_i}\oplus \mathfrak{G}\mid_{U_i}=(\mathfrak{F}\oplus \mathfrak{G})\mid_{U_i}$ and the result follows from \ref{R.2}.

\item ["$3 \rightarrow 1$"]

Let $\fp$ be a point of $X$ and let $\mathfrak{F}$ be a $\mathcal{O}_X$-projective . So, one may find an open affine subset 
 $U\subseteq X$ and $\mathcal{O}(U)$-module $M$ such that $\fp \in U$ and $\mathfrak{F}\mid_U=\overset {\sim}M.$ So, by the assumption, there exist a sheaf of $\mathcal{O}_X$-module $\mathfrak{h}$ and an integer number $l$ such that $\overset{l}\oplus \mathcal{O}_X = \mathfrak{F} \oplus \mathfrak{h}.$ 
%Therefore, $$(\overset{l}\oplus \mathcal{O}_X \mid_U)_{\fp}= (\mathfrak{F}\mid_U)_{\fp} \oplus (\mathfrak{h}\mid_U)_{\fp} =  M_{\fp} \oplus (\mathfrak{h}\mid_U)_{\fp}.$$ So,
This, in conjunction
with Proposition \ref{B23}, implies that $M_{\fp}$ is free. Now,
the result follows from \cite[exercise 2.5.3] {H}.
 \end{itemize}
\end{proof}
