\justify A quintessence scalar field paradigm given by the action \begin{equation*}
S=\!\int d^{4}x\sqrt{-g}\left[\frac{R}{2\kappa^{2}}-\frac12 g^{\mu\nu}\partial_{\mu}\phi\partial_{\nu}\phi-V(\phi)\right],
\end{equation*}
is governed by the following cosmological equations 
\begin{align*}
3H^{2} &= \kappa^{2}\!\left(\rho+\frac{\dot\phi^{2}}{2}+V\right), \\
2\dot H+3H^{2} &= -\kappa^{2}\!\left(w\rho+\frac{\dot\phi^{2}}{2}-V\right),\\
\ddot\phi+3H\dot\phi+V_{\phi}&=0
\end{align*}
Here $\rho$ is the background barotropic fluid with constant equation-of-state parameter $w$ of matter. Defining expansion normalized variables as in \cite{dyn1Copeland:2006wr,dyn2bahamonde2018dynamical,dyn3clifton2012modified}, \begin{equation*}
x\equiv\frac{\kappa\dot\phi}{\sqrt6\,H}, 
\qquad 
y\equiv\frac{\kappa\sqrt{V}}{\sqrt3\,H},
\end{equation*}
Alongside choosing an exponential potential form
\begin{equation*}
V(\phi)=V_{0}e^{-\lambda\kappa\phi},
\qquad 
\lambda=\text{const},
\end{equation*}
Allows us to write the cosmological equations in the following form
\justify
\begin{align}
x^\prime &= -\frac{3}{2} \left[ 2 x + (w-1) x^3 + x (w+1) (y^2 - 1) - \sqrt{\frac{2}{3}} \lambda y^2 \right], \\
y^\prime &= -\frac{3}{2} y \left[ (w-1) x^2 + (w+1) (y^2 - 1) + \sqrt{\frac{2}{3}} \lambda x \right].
\end{align}
\justify
Rewriting equations (S1) and (S2) as:
\justify
\begin{align}
x^\prime &= \frac{3}{2} (w-1) \left( x - x^3 \right) + \sqrt{\frac{3}{2}} y^2 \left( \lambda - x \sqrt{\frac{3}{2}} (w+1) \right), \\
y^\prime &= \frac{3}{2} (w+1) \left( y - y^3 \right) - \sqrt{\frac{3}{2}} x y \left( \lambda + x \sqrt{\frac{3}{2}} (w-1) \right).
\end{align}


\justify
Assuming solutions of the form:

\justify
\begin{align}
x &= \frac{1}{2} \left( u e^{i \omega N} + u^* e^{-i \omega N} \right), \\
y &= \frac{1}{2} \left( v e^{i \frac{\omega}{2} N} + v^* e^{-i \frac{\omega}{2} N} \right).
\end{align}


\justify
The derivatives and products are:



\justify



\begin{align}
x^\prime &= \frac{1}{2} \left( i \omega u e^{i \omega N} + u^\prime e^{i \omega N} - i \omega u^* e^{-i \omega N} + {u^\prime}^* e^{-i \omega N} \right), \\
y^\prime &= \frac{1}{2} \left( i \frac{\omega}{2} v e^{i \frac{\omega}{2} N} + v^\prime e^{i \frac{\omega}{2} N} - i \frac{\omega}{2} v^* e^{-i \frac{\omega}{2} N} + {v^\prime}^* e^{-i \frac{\omega}{2} N} \right), \\
y^2 &= \frac{1}{4} \left( v^2 e^{i \omega N} + v^{*2} e^{-i \omega N} + 2 |v|^2 \right), \\
x y &= \frac{1}{4} \left( u v e^{3 i \frac{\omega}{2} N} + u v^* e^{i \frac{\omega}{2} N} + u^* v e^{-i \frac{\omega}{2} N} + u^* v^* e^{-3 i \frac{\omega}{2} N} \right), \\
y^2 x &= \frac{1}{8} \left( u v^2 e^{2 i \omega N} + |v|^2 u e^{i \omega N} + u v^{*2} + u^* v^2 + |v|^2 u^* e^{-i \omega N} + u^* v^{*2} e^{-2 i \omega N} \right), \\
x^2 y &= \frac{1}{8} \left( u^2 v e^{5 i \frac{\omega}{2} N} + u^2 v^* e^{3 i \frac{\omega}{2} N} + 2 |u|^2 v e^{i \frac{\omega}{2} N} + 2 |u|^2 v^* e^{-i \frac{\omega}{2} N} + u^{*2} v e^{-3 i \frac{\omega}{2} N} + u^{*2} v^* e^{-5 i \frac{\omega}{2} N} \right), \\
x^3 &= \frac{1}{8} \left( u^3 e^{3 i \omega N} + 3 |u|^2 u e^{i \omega N} + 3 |u|^2 u^* e^{-i \omega N} + u^{*3} e^{-3 i \omega N} \right), \\
y^3 &= \frac{1}{8} \left( v^3 e^{3 i \frac{\omega}{2} N} + 3 |v|^2 v e^{i \frac{\omega}{2} N} + 3 |v|^2 v^* e^{-i \frac{\omega}{2} N} + v^{*3} e^{-3 i \frac{\omega}{2} N} \right).
\end{align}


\justify
Substituting equations (S5) to (S14) into (S3) and (S4) yields:



\justify



\begin{align}
(i \omega u + u^\prime) &= \left[ \frac{3}{2} w \left( 1 - \frac{3}{4} |u|^2 - \frac{1}{4} |v|^2 \right) - \frac{3}{2} \left( 1 - \frac{3}{4} |u|^2 + \frac{1}{4} |v|^2 \right) \right] u + \frac{1}{2} \sqrt{\frac{3}{2}} \lambda (v^2), \\
\left( i \frac{\omega}{2} v + v^\prime \right) &= \left[ \frac{3}{2} w \left( 1 - \frac{3}{4} |v|^2 - \frac{1}{2} |u|^2 \right) + \frac{3}{2} \left( 1 - \frac{3}{4} |v|^2 + \frac{1}{2} |u|^2 \right) \right] v - \frac{1}{2} \sqrt{\frac{3}{2}} \lambda u v^*.
\end{align}



\justify
For small $|u|^2, |v|^2 \ll 1$, equations (S15) and (S16) simplify to:






\justify
\begin{align}
(i \omega u + u^\prime) &= \frac{3}{2} (w-1) u + \frac{1}{2} \sqrt{\frac{3}{2}} \lambda (v^2), \\
\left( i \frac{\omega}{2} v + v^\prime \right) &= \frac{3}{2} (w+1) v - \frac{1}{2} \sqrt{\frac{3}{2}} \lambda u v^*.
\end{align}



\justify
Defining $\Omega_u = \frac{3}{2}(w-1)$, $\Omega_v = \frac{3}{2}(w+1)$, and $\alpha = \frac{1}{2} \sqrt{\frac{3}{2}} \lambda$, we obtain:

\begin{align}
u^\prime &= (\Omega_u - i \omega) u + \alpha v^2, \\
v^\prime &= \left( \Omega_v - i \frac{\omega}{2} \right) v - \alpha u v^*.
\end{align}


\justify
For frequency combs, express solutions as $u = u_0 + \delta u$ and $v = v_0 + \delta v$. Setting $u^\prime = 0$ and $v^\prime = 0$ in equations (S19) and (S20) for steady-state components:









\justify
\begin{align}
(\Omega_u - i \omega) u_0 + \alpha (v_0^2) &= 0, \\
\left( \Omega_v - i \frac{\omega}{2} \right) v_0 - \alpha u_0 v_0^* &= 0.
\end{align}



\justify
Multiplying equations (S21) and (S22) by their complex conjugates:



\justify
\begin{align}
u_0 &= -\frac{\alpha v_0^2}{\Omega_u - i \omega}, \\
u_0^* &= -\frac{\alpha v_0^{*2}}{\Omega_u + i \omega}, \\
|u_0|^2 &= \frac{\alpha^2 |v_0|^4}{\Omega_u^2 + \omega^2}, \\
\left( \Omega_v - i \frac{\omega}{2} \right) v_0 &= \alpha u_0 v_0^*, \\
\left( \Omega_v + i \frac{\omega}{2} \right) v_0^* &= \alpha u_0^* v_0, \\
|u_0|^2 &= \frac{1}{\alpha^2} \left( \Omega_v^2 + \frac{\omega^2}{4} \right).
\end{align}


\justify
Substituting equation (S28) into (S25):


\justify
\begin{equation}
|v_0|^2 = \frac{1}{\alpha^2} \sqrt{\left( \Omega_v^2 + \frac{\omega^2}{4} \right) (\Omega_u^2 + \omega^2)}.
\end{equation}


\justify
Substituting $u = u_0 + \delta u$ and $v = v_0 + \delta v$ into equations (19) and (20):




\justify
\begin{align}
\delta u^\prime &= (\Omega_u - i \omega) u_0 + (\Omega_u - i \omega) \delta u + \alpha v_0^2 + 2 \alpha v_0 \delta v + \alpha \delta v^2, \\
\delta v^\prime &= \left( \Omega_v - i \frac{\omega}{2} \right) v_0 + \left( \Omega_v - i \frac{\omega}{2} \right) \delta v - \alpha u_0 v_0^* - \alpha u_0 \delta v^* - \alpha \delta u v_0^* - \alpha \delta u \delta v^*.
\end{align}



\justify
Using steady-state conditions, simplify to:
\justify
\begin{align}
\delta u^\prime &= (\Omega_u - i \omega) \delta u + 2 \alpha v_0 \delta v + \alpha \delta v^2, \\
\delta v^\prime &= \left( \Omega_v - i \frac{\omega}{2} \right) \delta v - \alpha u_0 \delta v^* - \alpha \delta u v_0^* - \alpha \delta u \delta v^*.
\end{align}



\justify
Neglecting higher-order terms $\alpha \delta v^2$ and $\alpha \delta u \delta v^*$:
\justify



\begin{align}
\delta u^\prime &= (\Omega_u - i \omega) \delta u + 2 \alpha v_0 \delta v, \\
\delta v^\prime &= \left( \Omega_v - i \frac{\omega}{2} \right) \delta v - \alpha u_0 \delta v^* - \alpha \delta u v_0^*.
\end{align}
\justify


Conjugates of equations (S34) and (S35):
\justify


\begin{align}
\delta {u^\prime}^* &= (\Omega_u + i \omega) \delta u^* + 2 \alpha v_0^* \delta v^*, \\
\delta {v^\prime}^* &= \left( \Omega_v + i \frac{\omega}{2} \right) \delta v^* - \alpha u_0^* \delta v - \alpha \delta u^* v_0.
\end{align}
\justify




Assuming $\delta u = b_1 e^{\eta t}$, $\delta u^* = b_2 e^{\eta t}$, $\delta v = b_3 e^{\eta t}$, and $\delta v^* = b_4 e^{\eta t}$, and substituting:
\justify
\begin{align}
b_1 &= \frac{2 \alpha v_0}{\eta - \Omega_u + i \omega} b_3, \\
b_2 &= \frac{2 \alpha v_0^*}{\eta - \Omega_u - i \omega} b_4, \\
b_3 &= -\frac{\alpha u_0 (\eta - \Omega_u + i \omega)}{(\eta - \Omega_v + i \frac{\omega}{2})(\eta - \Omega_u + i \omega) + 2 \alpha^2 |v_0|^2} b_4.
\end{align}
\justify






Substituting equations (S38) to (S40) into (S37):
\justify
\begin{align}
\eta &= \left( \Omega_v + i \frac{\omega}{2} \right) + \frac{\alpha^2 |u_0|^2 (\eta - \Omega_u + i \omega)}{(\eta - \Omega_v + i \frac{\omega}{2})(\eta - \Omega_u + i \omega) + 2 \alpha^2 |v_0|^2} - \frac{2 \alpha^2 |v_0|^2}{\eta - \Omega_u - i \omega}, \\
\eta^2 &- (\Omega_u + \Omega_v) \eta + \Omega_u \Omega_v - \frac{\omega^2}{2} + 2 \alpha^2 |v_0|^2 - i \omega \left( \frac{3}{2} \eta - \frac{\Omega_u}{2} - \Omega_v \right) \notag \\
&= \frac{\alpha^2 |u_0|^2 (\eta^2 - 2 \Omega_u \eta + \Omega_u^2 + \omega^2)}{\alpha^2 (\Omega_v + \Omega_u) \eta + \Omega_u \Omega_v - \frac{\omega^2}{2} + 2 \alpha^2 |v_0|^2 + i \omega \left( \frac{3}{2} \eta - \frac{\Omega_u}{2} - \Omega_v \right)}.
\end{align}


\justify
This leads to the polynomial equation after simplification:
\justify
\begin{align}
&\left[ \left( \eta^2 - (\Omega_u + \Omega_v) \eta + \Omega_u \Omega_v - \frac{\omega^2}{2} + 2 \alpha^2 |v_0|^2 \right)^2 + \omega^2 \left( \frac{3}{2} \eta - \frac{\Omega_u}{2} - \Omega_v \right)^2 \right] \notag \\
&= \alpha^2 |u_0|^2 (\eta^2 - 2 \Omega_u \eta + \Omega_u^2 + \omega^2).
\end{align}
\justify




Substituting $|u_0|^2$ and $|v_0|^2$:
\justify
\begin{align}
&\left[ (\Omega_u + \Omega_v) \eta^3 + \left( 4 \Omega_u \Omega_v + \Omega_u^2 + \omega^2 + 4 \sqrt{\left( \Omega_v^2 + \frac{\omega^2}{4} \right)(\Omega_u^2 + \omega^2)} \right) \eta^2 \right. \notag \\
&\left. + \left( 2 \Omega_u^2 \Omega_v + 2 \Omega_v \omega^2 + 4 \sqrt{\left( \Omega_v^2 + \frac{\omega^2}{4} \right)(\Omega_u^2 + \omega^2)} (\Omega_u + 4 \Omega_v) \right) \eta \right. \notag \\
&\left. + \left( \Omega_v^2 + \frac{\omega^2}{4} \right)(\Omega_u^2 + \omega^2) + 2 \sqrt{\left( \Omega_v^2 + \frac{\omega}{4} \right)(\Omega_u^2 + \omega^2)} (\Omega_u + \omega^2) \right] = 0.
\end{align}
\justify
With $\Omega_u = \frac{3}{2}(w-1)$ and $\Omega_v = \frac{3}{2}(w+1)$:
\justify


\begin{align}
&\eta^4 - 6 w \eta^3 + \left( \frac{9}{4}(w-1)(9 w + 7) + \frac{9}{4} \sqrt{\left( \frac{9}{4}(w+1)^2 + \frac{\omega^2}{4} \right) \left( \frac{9}{4}(w-1)^2 + \omega^2 \right)} \right) \eta^2 \notag \\
&- \left( \frac{27}{4}(w-1)^2 (w+1) + 3 (w+1) \omega^2 + \frac{9}{4} \sqrt{\left( \frac{9}{4}(w+1)^2 + \frac{\omega^2}{4} \right) \left( \frac{9}{4}(w-1)^2 + \omega^2 \right)} (15 w + 9) \right) \eta \notag \\
&+ \frac{9}{4} \left( \frac{9}{4}(w+1)^2 + \frac{\omega^2}{4} \right) \left( \frac{9}{4}(w-1)^2 + \omega^2 \right) \notag \\
&+ \frac{9}{4} \sqrt{\left( \frac{9}{4}(w+1)^2 + \frac{\omega^2}{4} \right) \left( \frac{9}{4}(w-1)^2 + \omega^2 \right)} \left( \frac{9}{4}(w^2 - 1) - \omega^2 \right) = 0.
\end{align}

\justify
Assuming $\omega^2 \ll |w|$:
\justify
\begin{equation}
\eta^4 - 6 w \eta^3 + \frac{9}{4}(w-1)(9 w + 7) \eta^2 - \frac{27}{4}(w^2 - 1)(11 w + 5) \eta + \frac{405}{4}(w^2 - 1)^2 = 0.
\end{equation}
\justify

For stability, apply the Routh-Hurwitz criteria for $\eta^4 + c_1 \eta^3 + c_2 \eta^2 + c_3 \eta + c_4 = 0$, where:

\justify
\begin{itemize}
\item $c_1 = -6 w$,
\item $c_2 = \frac{9}{4}(w-1)(9 w + 7)$,
\item $c_3 = -\frac{27}{4}(w^2 - 1)(11 w + 5)$,
\item $c_4 = \frac{405}{4}(w^2 - 1)^2$.
\end{itemize}

\justify
The conditions are:
\justify


\begin{enumerate}
\item $c_1 \geq 0 \implies -6 w \geq 0 \implies w \leq 0$.
\item $c_2 \geq 0 \implies \frac{9}{4}(w-1)(9 w + 7) \geq 0 \implies w \in (-\infty, -\frac{7}{9}] \cup [1, \infty) \implies w \in (-\infty, -0.778] \cup [1, \infty)$.
\item $c_3 \geq 0 \implies -\frac{27}{4}(w^2 - 1)(11 w + 5) \geq 0 \implies w \in (-\infty, -1] \cup [-\frac{5}{11}, 1] \implies w \in (-\infty, -1] \cup [-0.455, 1]$.
\item $c_4 \geq 0$ is always satisfied.
\item $c_1 c_2 - c_3 \geq 0$:


\begin{align}
&-6 w \cdot \frac{9}{4}(w-1)(9 w + 7) + \frac{27}{4}(w^2 - 1)(11 w + 5) \geq 0, \\
&\implies -7 w^3 + 9 w^2 + 3 w - 5 \geq 0, \\
&\implies (w-1)^2 (7 w + 5) \leq 0, \\
&\implies w \leq -\frac{5}{7} \implies w \leq -0.714.
\end{align}

\item $c_3 (c_1 c_2 - c_3) - c_1^2 c_4 \geq 0$:

\justify
\begin{align}
&\left( \frac{27}{4} \right)^2 (w^2 - 1)(11 w + 5)(w-1)^2 (7 w + 5) - (-6 w)^2 \frac{405}{4}(w^2 - 1)^2 \geq 0, \\
&\implies (w-1)^2 (w+1) (3 w^3 + 67 w^2 + 65 w + 25) \leq 0, \\
&\implies -21.3361 \leq w \leq -1.
\end{align}


\end{enumerate}

Compiling all conditions:
\justify
\begin{itemize}
\item $w \leq 0$,
\item $w \in (-\infty, -0.778] \cup [1, \infty)$,
\item $w \in (-\infty, -1] \cup [-0.455, 1]$,
\item $w \leq -0.714$,
\item $-21.3361 \leq w \leq -1$.
\end{itemize}
\justify
So we see that the region which satisfies all the creation is $-21.3361 \leq w \leq -1$, which suggests that a frequency comb behaviour can be seen in an expanding cosmology if there is a phantom-like matter component.


