	\appendix
 \section{ Appendix }
 \label{appendixA}
In this Appendix, we provide the necessary details that go into the computation of the susceptibility. For this, we take the gauge field fluctuation equation of motion (\ref{susceptibilityEOM}) and rewrite it as
 \begin{equation}
    \partial_z(X_{tz} V_0') -k^2 p V_0=0\,,
    \label{EOMappendix}
\end{equation}
where
\begin{equation}
    X_{tz}=\sqrt{-\mathcal{G}} f(z) G^{zz} G^{00}\,,
\end{equation}
and $p= \sqrt{-\mathcal{G}} f(z)G^{00} G^{11}$ (or $p= \sqrt{-\mathcal{G}} f(z)G^{00} G^{33}$) when the momentum is chosen along the $x_1$ direction (or the $x_3$ direction).

Next, we consider the hydrodynamic expansion of the form,
 \begin{eqnarray}
	    V_0(z)= F_0(z) + k^2 F_{k^2}(z)+...\,.
     \label{hydrodynamicexpansionappendix}
	\end{eqnarray}

Substituting the value of $V_0(z)$ from (\ref{hydrodynamicexpansionappendix}) into (\ref{EOMappendix}), we get
 \begin{equation}
     (X_{tz}(F_0'(z)+k^2 F_{k^2}'(z)))' -k^2 p (F_0(z)+k^2 F_{k^2}(z))=0\,.
 \end{equation}
Equating the coefficients of various power of $k$, we get the following equation of motion for $F_0(z)$ and $F_{k^2}(z)$: 
\begin{equation}
    (X_{tz} F_0'(z))'=0\,.
    \label{F0EOM}
\end{equation}
\begin{equation}
	    (X_{tz} F_{k^2}'(z))' - p F_0(z) =0\,.
     \label{Fk^2EOM}
	\end{equation}
From Eq.~(\ref{F0EOM}), we get the following solution
\begin{equation}
    X_{tz} F_0'(z)=C_0\,.
    \label{condition}
\end{equation}
By integrating the above, we get the expression of $F_0(z)$ as
\begin{equation}
    F_0(z)= C_0 \int_{z_h}^{z} \frac{d z}{X_{tz}}\,,
    \label{F0sol}
\end{equation}
where $C_0$ is a constant of integration. Substituting (\ref{condition}) into (\ref{Fk^2EOM}), leads to
\begin{equation}
     (X_{tz} F_{k^2}'(z))' = p C_0 S(z)
\end{equation}
where $S(z)=\int_{z_h}^{z} \frac{ d\tilde{z}}{X_{tz}(\tilde{z})}$.
Substituting the above expressions into~(\ref{EOMappendix}) and comparing the coefficient of $k^2$:
\begin{align}
    k^2 p V_0 &= (X_{tz} V_0')' = k^2 (X_{tz} F_{k^2}'(z))' \nonumber \\
    &= k^2 p C_0 S(z)\,.
    \label{k2coefficient}
    \end{align}
This leads to
\begin{equation}
 V_0 = C_0 S(z)\,.
       \label{V0sol}
    \end{equation}  

Now, the quark number susceptibility is related to the retarded Green's function 
 \begin{eqnarray}
     \chi =  -\lim_{k,z \to 0} \Re [G_{tt}(\omega=0,k)]\,.
 \end{eqnarray}
The retarded Green's function is obtained by taking the second derivative of the on-shell boundary action with respect to the boundary value of the field. For our model, the boundary on-shell action is given by
\begin{eqnarray}
	S_{\text{on-shell,bdy}} & = & \lim\limits_{z\to 0}\int d^4x\frac{4}{z^3}V_0\partial_z V_0\,.
    \label{onshell}
\end{eqnarray} 
Putting the value of $V_0$ from (\ref{V0sol}) in the on-shell boundary action (\ref{onshell}), we get the retarded function as $G_{tt}(\omega=0,k)= -\frac{1}{S(0)}$. Then, using the explicit form of $X_{tz}$, we get 
\begin{eqnarray}
    \chi = \frac{1}{S(0)} =  \left(\int _{z_h}^{0} \frac{dz}{\sqrt{-\mathcal{G}} f(z) G^{zz} G^{00}}\right)^{-1}\,.
\end{eqnarray}
Here, we observe that $\chi$ is independent of $p$, which characterizes the direction of momentum. Consequently, the susceptibility remains the same for the momentum along both the $x_1$ and $x_3$ directions.



